window.KURAN_MEALS=window.KURAN_MEALS||{};window.KURAN_MEALS["bayrakli"]=[[{"n":1,"t":"Rahmet ve merhametin kaynağı olan Allah`ın adıyla."},{"n":2,"t":"Bütünüyle övgü, âlemlerin rabbi Allah`a aittir."},{"n":3,"t":"O, rahmet ve merhametin kaynağıdır."},{"n":4,"t":"Din/ceza ve ödül gününün sahibidir."},{"n":5,"t":"Yalnız sana kulluk eder ve yalnız senden yardım dileriz."},{"n":"6-7","t":"Bizi doğru yola, yani kendilerini nimetlendirdiklerinin yoluna ilet; gazaba uğramışların ve sapıkların yoluna değil!"}],[{"n":1,"t":"Elif, lâm, mîm."},{"n":2,"t":"Kendisinde hiç şüphe olmayan bu kitap, sakınanlar için bir rehberdir."},{"n":3,"t":"Onlar, gayba inanırlar, namazı kılarlar, kendilerine verdiklerimizden Allah yolunda harcarlar."},{"n":4,"t":"Sana indirilene ve senden önce indirilene de iman ederler; âhiret gününe kesinlikle inanırlar."},{"n":5,"t":"İşte onlar, Rablerinden gelen bir hidayet üzeredirler ve işte onlar kurtuluşa erenlerin ta kendileridirler."},{"n":6,"t":"İnkâr edenleri uyarsan da uyarmasan da, onlar için aynıdır; iman etmezler."},{"n":7,"t":"Bu nedenle Allah onların kalplerini ve kulaklarını mühürlemiştir. Onların gözlerine de bir perde çekilmiştir. Onlar için büyük bir azap vardır."},{"n":8,"t":"İnsanlardan bazıları inanmadıkları halde, “Allah`a ve âhiret gününe inandık” derler."},{"n":9,"t":"Allah`ı ve iman edenleri aldatmaya çalışıyorlar. Halbuki onlar kendilerini aldatıyorlar da bunun farkında değillerdir."},{"n":10,"t":"Onların kalplerinde bir hastalık vardır. Allah da onların hastalığını arttırmıştır. Yalan söylediklerinden dolayı, onlara acı veren bir azap vardır."},{"n":11,"t":"Onlara, “Yeryüzünde bozgunculuk yapmayın!” denildiğinde, “Biz ancak ıslah edici kimseleriz” derler."},{"n":12,"t":"Onların bozguncu olduklarını iyi bilin. Lâkin onlar bunun farkında değillerdir."},{"n":13,"t":"Onlara, “İnsanların iman ettiği gibi siz de iman edin!” dendiğinde, “Biz hiç beyinsizlerin iman ettikleri gibi iman eder miyiz!” derler. Biliniz ki, beyinsizler ancak kendileridir, fakat bunu bilmezler."},{"n":14,"t":"Müminlerle karşılaştıklarında, “İman ettik” derler, reisleriyle baş başa kaldıklarında ise, “Biz sizinle beraberiz; biz sadece alay ediyoruz” derler."},{"n":15,"t":"Allah onlarla alay ediyor ve taşkınlıkları içinde şaşkınca dolaşmalarına süre tanıyor."},{"n":16,"t":"İşte onlar, doğru yola karşılık sapıklığı satın alanlardır. Onların bu ticareti kazançlı olmayacak ve doğru yolu da bulamayacaklardır."},{"n":17,"t":"Onların durumu, bir ateş yakan kimseye benzer. O ateş yanıp etrafını aydınlattığında, Allah hemen onların aydınlığını giderir ve onları hiçbir şey göremeyecekleri karanlıklar içinde bırakır."},{"n":18,"t":"Onlar manen sağır, dilsiz ve kördür; gerçeğe dönmezler."},{"n":19,"t":"Yahut onların durumu, gökten sağanak halinde boşalan, içinde yoğun karanlıklar, gök gürültüsü ve şimşekler bulunan fırtınaya tutulmuş insana benzer. O münafıklar yıldırımlardan gelecek ölüm korkusuyla parmaklarını kulaklarına tıkarlar. Halbuki Allah, kâfirleri çepeçevre kuşatmıştır."},{"n":20,"t":"Neredeyse gözlerini kapıverecek olan şimşek önlerini aydınlattığında onun ışığında yürürler; üzerlerine karanlık çökünce dikilip kalırlar. Allah dileseydi, elbette onların kulaklarını sağır, gözlerini kör ederdi. Şüphesiz Allah, her şeye gücü yetendir."},{"n":21,"t":"Ey insanlar! Sizi ve sizden öncekileri yaratan Rabbinize kulluk ediniz ki, ruh olgunluğuna eresiniz."},{"n":22,"t":"O Allah ki, yeryüzünü sizin için bir döşek, gökyüzünü bir bina yaptı. O, gökten su indirip onunla çeşit çeşit meyveleri size rızık olarak çıkardı. O halde, bile bile Allah`a eşler koşmayınız."},{"n":23,"t":"Eğer kulumuza indirdiğimiz Kur`ân`dan şüphe ediyorsanız, siz de onun bir sûresinin benzerini getiriniz ve eğer sözünüzün eri iseniz Allah`tan başka tapındıklarınızı da yardıma çağırınız."},{"n":24,"t":"Kur`an`ın veya on suresinin benzerini getiremediniz; bir suresinin benzerini de asla getiremeyeceksiniz. O halde yakıtı insanlar ile taşlar olan ve kâfirler için hazırlanmış bulunan ateşten korkun!"},{"n":25,"t":"İman edip de yararlı iş yapanları, içinden ırmaklar akan cennetlerle müjdele! Kendilerine cennette meyve nimeti verildiğinde, “Bu, daha önce de dünyada yediğimize benziyor; bunun benzeri bize verilmişti” diyecekler. Orada onların, her türlü pislikten arınmış tertemiz eşleri olacak ve orada süreli olarak kalacaklardır."},{"n":26,"t":"Allah, bir sivri sineği, hatta ondan daha küçük bir şeyi örnek vermekten çekinmez. İnananlar, bu örneğin Rabblerinden bir gerçek olduğunu bilirler. Kâfirler ise, “Allah bu örnekle ne demek istedi?” derler. “Allah bu örnekle birçoğunu saptırır, birçoğunu da doğruya yöneltir; bu örnekle, fâsıklardan başkasını saptırmaz.”"},{"n":27,"t":"O fâsıklar ki, Allah`a kesin söz verdikten sonra sözlerinden dönerler; Allah`ın bitiştirilmesini emrettiği ilişkileri keser ve yeryüzünde bozgunculuk yaparlar. Onlar manen iflâs etmiş kimselerdir."},{"n":28,"t":"Allah`ı nasıl inkâr ediyorsunuz? Siz yokken, sizi var etti. Sonra sizi öldürecek ve sonra tekrar diriltecek. Sonunda O`na döndürüleceksiniz."},{"n":29,"t":"Allah, yerde olanların hepsini sizin için yarattı, sonra iradesini göğe yöneltip onları yedi gök olarak düzenledi. O, her şeyi bilendir."},{"n":30,"t":"Rabbin meleklere, “Ben yeryüzünde bir halife yaratacağım” dediği vakit melekler, “Biz seni överek anarken ve yüceltip dururken, orada fesat çıkaracak, kan dökecek birini mi yaratacaksın?” dediler. Allah, “Ben sizin bilmediğinizi bilirim” diye cevap verdi."},{"n":31,"t":"Allah, Âdem`e bütün isimleri öğretti. Sonra o varlıkları ve nesneleri meleklerin karşısına çıkarıp “Görüşünüzde doğru iseniz, bunların adlarını bana söyleyiniz” dedi."},{"n":32,"t":"Melekler, “Seni bütün eksikliklerden uzak tutarız! Bizim senin öğrettiğinden başka bilgimiz yoktur. Her şeyi bilen ve hikmet sahibi sensin” dediler."},{"n":33,"t":"Allah, “Ey Âdem! Onlara eşyanın isimlerini anlat” dedi. Âdem, onların isimlerini meleklere anlatınca Allah, “Size demedim mi, göklerin ve yerin sırlarını ben bilirim ve ben sizin açıkladığınız ve gizlediğiniz şeyleri de bilirim” dedi."},{"n":34,"t":"Meleklere, “Âdem`e secde ediniz” dediğimiz vakit İblis`ten başka hepsi secde ettiler. İblis secde etmedi, kibirlendi ve kâfirlerden oldu."},{"n":35,"t":"“Sen ve eşin birlikte cennete yerleşiniz, ikiniz de oradaki nimetlerden istediğinizi bol bol yiyiniz, ancak şu ağaca yaklaşmayınız, yoksa zalim/büyük hata yapanlardan olursunuz.”"},{"n":36,"t":"Bunun üzerine şeytan, onları bulundukları yerden kaydırıp çıkardı. Biz de, “Birbirinize düşman olarak oradan ininiz ve yeryüzünde belli bir zamana kadar ikamet edip yaşayacaksınız” dedik."},{"n":37,"t":"Bunun üzerine Âdem, Rabbinden bazı kelimeler alıp öğrendi. Allah da tövbesini kabul etti. Çünkü Allah, tövbeyi çok kabul eden ve çok merhamet edendir."},{"n":38,"t":"“Hepiniz oradan inin. Size benden doğru yolu gösteren bir rehber geldiğinde, kim rehberime uyarsa, onlara hiçbir korku yoktur ve onlar üzülmeyeceklerdir”."},{"n":39,"t":"İnkâr edip âyetlerimizi yalanlayanlara gelince, onlar da cehennemliktirler; onlar orada süreli olarak kalacaklardır."},{"n":40,"t":"Ey İsrâiloğulları! Sizlere verdiğim nimetleri hatırlayınız. Siz benim emrimi yerine getiriniz ki, ben de sizin isteğinizi yerine getireyim. Sadece benden çekinin."},{"n":41,"t":"Beraberinizde olan Tevrat`ı doğrulayıcı olarak indirdiğim Kur`ân`a iman ediniz. Sakın onu inkâr edenlerin ilki olmayınız. Âyetlerimi de küçük bir değerle değiştirmeyiniz ve yalnız benden sakınınız."},{"n":42,"t":"Bilerek hakkı bâtıl ile karıştırmayınız ve hakkı gizlemeyiniz."},{"n":43,"t":"Namazı kılınız, zekâtı veriniz ve rükû edenlerle beraber rükû ediniz."},{"n":44,"t":"Ey bilginler, kitabı okuduğunuz halde, insanlara iyiliği emredip, kendinizi unutuyor musunuz? Aklınızı kullanmıyor musunuz?"},{"n":"45-46","t":"Sabır ve dua ile Allah`tan yardım isteyin. Sabır ve dua, Rablerine kavuşacaklarını ve kesinlikle O`na döneceklerini bilen, gerçekten kalbi Allah sevgisinden dolayı ürperenlerin dışındakilere ağır gelir."},{"n":47,"t":"Ey İsrâiloğulları! Size verdiğim nimetimi ve sizi âlemlere üstün kıldığımı hatırlayınız."},{"n":48,"t":"Hiç kimsenin başkasına fayda veremeyeceği, şefaatin kabul edilmeyeceği, fidye alınmayacağı ve yardım yapılmayacağı bir günden sakınınız."},{"n":49,"t":"Hani sizi Firavun`un yandaşlarından kurtarmıştık. Zira onlar, eziyetin en kötüsünü size lâyık görüyorlardı. Erkek çocuklarınızı boğazlıyor, kızlarınızı hayatta bırakıyorlardı. Bu uygulamada, sizin için Rabbinizden ağır bir imtihan vardı."},{"n":50,"t":"Sizin için denizi yarmış, sizi kurtarmış ve Firavun taraftarlarını boğmuştuk; siz de bunu görüyordunuz."},{"n":51,"t":"Mûsâ ile kırk gece için sözleştikten sonra, siz onun ardından şirk koşarak buzağıyı tanrı edindiniz."},{"n":52,"t":"Bu davranışınızdan sonra şükredersiniz diye sizi affetmiştik."},{"n":53,"t":"Hani biz, doğru yolu bulasınız diye Mûsâ`ya kitâbı ve furkânı vermiştik."},{"n":54,"t":"Ve Musa halkına dönüp “Ey halkım!” demişti. Doğrusu buzağıya taparak kendinize yazık ettiniz. O halde tevbe ederek tekrar yaratıcınıza yönelin ve size bu günahı işleten benliğinizi öldürüp yok edin veya bu suçunuzdan dolayı; buzağıya tapmayanlar, tapanları öldürün veya intihar ederek, kendi kendinizi öldürerek yok edin. Bu sizin için yaratıcınız katında en hayırlısı olacaktır. Bunun üzerine O, tevbenizi kabul etmişti. Çünkü yalnız O`dur tevbeleri kabul eden ve kullarına acıyan."},{"n":55,"t":"Şu zamanı da hatırlayınız ki, siz “Ey Mûsâ! Allah`ı apaçık görünceye kadar sana asla iman etmeyeceğiz!” demiştiniz de, göre göre sizi yıldırım çarpmıştı."},{"n":56,"t":"Şükredersiniz diye, sizi ölümünüzün ardından dirilttik."},{"n":57,"t":"Ve bulutların sizi gölgeleriyle rahatlatmasını sağladık, ayrıca “Size rızık olarak verdiğimiz güzel şeylerden yararlanın” diyerek kudret helvası ve bıldırcın da gönderdik. Onlar işledikleri bu günahlarla zulmü bize değil kendilerine ettiler."},{"n":58,"t":"İsrâiloğulları`na, “bu kente giriniz, orada bulunanlardan bol bol yiyiniz; kapısından boyun eğerek giriniz; ‘Hıtta/hatalıyız` deyiniz ki hatalarınızı bağışlayalım. Çünkü biz, iyi davrananlara fazlasıyla vereceğiz” demiştik."},{"n":59,"t":"Fakat zâlimler, kendilerine söylenenleri başka sözlerle değiştirdiler. Bunun üzerine biz, yapmakta oldukları kötülükler sebebiyle zâlimlerin üzerine gökten acı bir azap indirdik."},{"n":60,"t":"“Allah`ın nimetlerinden yiyiniz, içiniz, sakın yeryüzünde bozgunculuk etmeyiniz” dedik."},{"n":61,"t":"Siz, “Ey Mûsâ, hep aynı şeyi yemeye katlanamayız. Bizim için Rabbine dua et de, bize yerin bitirdiği şeylerden sebze, salatalık, sarımsak, mercimek ve soğan çıkarsın” demiştiniz. Mûsâ da, “Daha iyi olanı daha değersiz olanla değişmek mi istiyorsunuz? İnin şehre, orada istediğiniz var” dedi. Horluk ve yoksulluğa maruz kaldılar ve Allah`ın gazabına uğradılar. Bu musibet, Allah`ın âyetlerini inkâr etmeleri, peygamberlerini haksız yere öldürmeleri ve isyan edip aşırı gitmeleri sebebiyle geldi."},{"n":62,"t":"Kesinlikle, iman edenlerden, Yahudi olanlardan, Hıristiyanlardan ve Sâbiîlerden kim Allah`a ve âhiret gününe inanıp iyi amelde bulunursa, Rabbleri katında onların ödülü vardır. Onlara bir korku yoktur ve onlar kederlenmeyeceklerdir."},{"n":63,"t":"Hani sizden sağlam bir söz almış, Tûr`u da üstünüze kaldırmış ve “Size verdiğimiz kitabın hükümlerine sımsıkı sarılınız, içinde olanları hatırlayınız ki, ruh olgunluğuna ulaşasınız” demiştik."},{"n":64,"t":"Bundan sonra yine yüz çevirdiniz. Allah`ın iyiliği ve merhameti üzerinizde olmasaydı, manen iflas etmiş olacaktınız."},{"n":65,"t":"İçinizden Cumartesi günü yasağını çiğneyenleri elbette bilirsiniz. İşte bundan dolayı onlara, “Aşağılık maymunlar olun” dedik."},{"n":66,"t":"Ve onları, hem ilk kuşaklar hem de sonraki nesiller için bir ibret vesikası, (taklitten) sakınanlar içinde uyarıcı bir örnek kıldık."},{"n":67,"t":"Mûsâ, toplumuna “Allah size bir inek kesmenizi emrediyor` demişti. ‘Bizimle alay mı ediyorsun?” dediler. O da, “Câhillerden olmaktan Allah`a sığınırım” dedi."},{"n":68,"t":"“Bizim adımıza Rabbine dua et, bize ineğin nasıl olduğunu açıklasın” dediler. Mûsâ, “Allah diyor ki, o ne yaşlı ne de körpe; ikisi arasında bir inektir. Size emredileni, hemen yapın” dedi."},{"n":69,"t":"Bu defa, “Bizim için Rabbine dua et, bize onun rengini açıklasın” dediler. Mûsâ da, “Allah diyor ki, sarı renkli, parlak tüylü, bakanların içini açan bir renktedir” dedi."},{"n":70,"t":"“Bizim için Rabbine dua et de onun nasıl bir inek olduğunu bize açıklasın, nasıl bir inek keseceğimizi anlayamadık. Biz, inşallah emredileni yerine getiririz” dediler."},{"n":71,"t":"O inek, henüz boyunduruk altına alınmayan, yer sürmeyen, ekin sulamayan, serbest dolaşan, hiç alacası bulunmayan bir inektir.” “İşte şimdi gerçeği anlattın” dediler ve bunun üzerine onu bulup kestiler, ama az kalsın kesmeyeceklerdi."},{"n":72,"t":"Hani siz, bir adam öldürmüştünüz ve kâtili hakkında birbirinizle tartışmıştınız. Fakat Allah, gizlediğinizi ortaya çıkaracaktır."},{"n":73,"t":"“Haydi, şimdi öldürülen bu adama, kesilen ineğin bir parçasıyla vurun” dedik. Allah ölüleri bu şekilde diriltir ve size âyetlerini gösterir. Umulur ki, aklınızı kullanırsınız."},{"n":74,"t":"Sonra bu mucizenin ardından kalpleriniz katılaştı, taş gibi, hatta daha da katı oldu. Hâlbuki taşın öylesi vardır ki, ondan ırmaklar fışkırır; öylesi vardır ki, yarılıp içinden su akar; öylesi de vardır ki, Allah`a olan saygısından dolayı yuvarlanır. Allah yaptıklarınızdan habersiz değildir."},{"n":75,"t":"Artık onların, size inanacaklarını mı umuyorsunuz? Onlardan bir zümre vardı ki, Allah`ın kelâmını dinlerler ve kavrayıp anladıktan sonra, bile bile onda değişiklik yaparlardı."},{"n":76,"t":"Münafıklar, müminlerle karşılaştıklarında, “İman ettik” derler. Birbirleriyle baş başa kaldıklarında ise, “Allah`ın size açtıklarını, Rabbiniz katında sizin aleyhinize delil getirmeleri için mi onlara anlatıyorsunuz; bunları düşünemiyor musunuz?” derler."},{"n":77,"t":"Allah`ın, onların gizlediklerini ve açığa vurduklarını bildiğini bilmiyorlar mı?"},{"n":78,"t":"Onların arasında kitabı bilmeyen cahiller vardır. Bildikleri sadece kendilerine anlatılan asılsız kuruntulardır. Onlar sadece zanda bulunuyorlar."},{"n":79,"t":"Elleriyle kitabı yazıp sonra onu az bir bedel karşılığında satmak için, “Bu, Allah katındandır” diyenlere yazıklar olsun! Elleriyle yazdıklarından ötürü vay haline onların! Kazandıklarından ötürü vay haline onların!"},{"n":80,"t":"“Allah`tan bir söz mü aldınız; çünkü Allah asla sözünden caymaz; yoksa Allah hakkında bilmediğiniz bir şeyi mi söylüyorsunuz?”"},{"n":81,"t":"Hayır! Kim bir kötülük eder de, kötülüğü kendisini çepeçevre kuşatırsa, işte o kimseler cehennemliklerdir. Onlar orada uzun süreli kalırlar."},{"n":82,"t":"İman edip yararlı iş yapanlara gelince, onlar da cennetliklerdir. Onlar orada süreli kalırlar."},{"n":83,"t":"Sadece Allah`a kulluk edeceksiniz; ana babaya, yakın akrabaya, yetimlere ve yoksullara iyilik edeceksiniz. İnsanlara doğru olanı söyleyiniz, namazı kılınız, zekâtı veriniz. Sonunda azınız müstesnâ, yüz çevirerek dönüp gittiniz."},{"n":84,"t":"Hatırlayınız ki, sizden, “Birbirinizin kanını akıtmayınız, birbirinizi yurtlarınızdan çıkartmayınız” diye sağlam söz almıştık. Sonra siz bunu kabullendiniz ve birbirinize karşı şahitlik ettiniz."},{"n":85,"t":"Bu sözleşmeyi kabul eden sizler, verdiğiniz sözün aksine birbirinizi öldürüyor ve aranızdan bir grubu yurtlarından çıkarıyorsunuz. Günah ve düşmanlıkta onlara karşı birleşip yardımlaşıyorsunuz. Onları yurtlarından çıkarmak size haram olduğu halde, size esir olarak geldiklerinde, fidyeleşip esir değişimi yapıyorsunuz. Siz kitabın bir kısmına inanıyor, bir kısmını inkâr mı ediyorsunuz? Sizden böyle yapanların cezası, dünya hayatında rüsvaylıktan başka bir şey değildir. Kıyamet gününde de onlar, en şiddetli azaba iletilecekler. Allah, yaptıklarınızdan habersiz değildir."},{"n":86,"t":"Âhirete karşılık dünya hayatını tercih eden bu kişilerin azapları hafifletilmeyecek ve kendilerine yardım da edilmeyecektir."},{"n":87,"t":"Yemin olsun biz Mûsâ`ya Kitab`ı verdik. Ondan sonra peş peşe peygamberler gönderdik. Meryem oğlu İsâ`ya da mucizeler verdik ve onu Rûhulkudüs/Cebrail ile destekledik. Nefsinizin arzulamadığı şeyleri söyleyen bir peygamber geldikçe ona karşı kibirlendiniz, bir kısmını yalanladınız, bir kısmını da öldürdünüz."},{"n":88,"t":"Yahudiler, “Kalplerimiz perdelidir” dediler. Hayır, küfür ve isyanları sebebiyle Allah onlara lanet etmiştir; bu yüzden çok azı inanır."},{"n":89,"t":"Daha önce kâfirlere karşı zafer isterlerken, kendilerine Allah katından, yanlarındakilerini doğrulayan bir kitap gelip de öğrendikleriyle karşılaşınca inkâr ettiler. İşte Allah`ın laneti böyle inkârcılaradır."},{"n":90,"t":"Kendilerini ne kötü şey karşılığında sattılar! Çekemediklerinden dolayı, Allah`ın, kullarından dilediğine vahiy indirmesini ve Allah`ın indirdiğini inkâr ettiler. Bu inkârları sebebiyle gazap üstüne gazaba uğradılar. İnanmayanları utanç verici azap beklemektedir."},{"n":91,"t":"Kendilerine “Allah`ın indirdiğine inanın” denilince, “Biz sadece bize indirilen kitaba inanırız” derler ve ondan başkasını inkâr ederler. Halbuki Kur`ân, ellerinde bulunanı doğrulayıcı olarak gelmiş hak kitaptır. Onlara de ki, “Şâyet siz gerçekten inanıyor idiyseniz, daha önce Allah`ın peygamberlerini neden öldürüyordunuz?”"},{"n":92,"t":"Andolsun ki Mûsâ size en açık delilleri getirdi. Sonra ardından buzağıyı ilâh edindiniz. Siz zâlimsiniz."},{"n":93,"t":"“Eğer inanıyorsanız, inancınız size ne kötü şeyler emrediyor!”"},{"n":94,"t":"“Şayet âhiret yurdu Allah katında diğer insanlara değil de sadece size ait ise ve bu iddianızda da doğru iseniz, haydi ölümü temenni ediniz.”"},{"n":95,"t":"Onlar, kendi elleriyle yaptıkları ameller sebebiyle hiçbir zaman ölümü temenni etmeyeceklerdir. Allah zâlimleri iyi bilir."},{"n":96,"t":"Onları, insanlar içinde dünya hayatına en çok düşkün olanlar olarak bulacaksın. İçlerinden şirk koşanlar bin sene yaşamak ister. Fakat bu kadar yaşasa da, bu uzun ömür onları azaptan uzaklaştıramaz. Allah onların yaptıklarını eksiksiz görür."},{"n":97,"t":"“Cebrâil`e düşman olanlar bilsinler ki, Cebrâil Kur`ân`ı senin gönlüne Allah`ın izniyle indirdi. Kur`ân, kendinden önce gelen kitapları doğrulayıcı, müminler için rehber ve müjdedir.” Kim Allah`a, meleklerine, peygamberlerine, Cebrâîl`e ve Mîkâil`e düşman olursa, bilsin ki Allah da inkârcıların düşmanıdır."},{"n":98,"t":"“Cebrâil`e düşman olanlar bilsinler ki, Cebrâil Kur`ân`ı senin gönlüne Allah`ın izniyle indirdi. Kur`ân, kendinden önce gelen kitapları doğrulayıcı, müminler için rehber ve müjdedir.” Kim Allah`a, meleklerine, peygamberlerine, Cebrâîl`e ve Mîkâil`e düşman olursa, bilsin ki Allah da inkârcıların düşmanıdır."},{"n":99,"t":"Andolsun ki, sana apaçık âyetler indirdik. Onları fâsıklardan başka kimse inkâr etmez."},{"n":100,"t":"Ne zaman, onlar bir antlaşma yaptılarsa, yine kendilerinden bir grup onu bozmadı mı? Zaten onların çoğu iman etmez."},{"n":101,"t":"Onlara, yanlarındaki kitabı doğrulayan peygamber geldiği zaman, kendilerine kitap verilenlerden bir grup, güya hakikati bilmiyorlarmış gibi, Allah`ın kitabını arkalarına atarak ondan yüz çevirmişlerdi."},{"n":102,"t":"Kitap ehli, Süleyman`ın hükümranlığı hakkında şeytanların vesvesesine uydular. Oysa Süleyman büyü yapıp kâfir olmadı. Fakat şeytanlar kâfir oldular; çünkü insanlara sihri ve Bâbil`deki Hârut ve Mârut isimli iki meleğe indirileni öğretiyorlardı. Halbuki bu iki melek, “Biz sadece imtihan için gönderildik, sakın yanlışa inanıp da kâfir olmayasınız” demeden hiç kimseye sihir öğretmezlerdi. Onlar, bu iki melekten, karı ile kocanın arasını açacak şeyleri öğreniyorlardı. Oysa büyücüler, Allah`ın izni olmadan kimseye zarar veremezler. Onlar, kendilerine faydalı olanı değil, zararlı olanı öğrenirler. Büyüye başvuranların âhiretten nasiplerinin olmayacağını iyi bilmektedirler. Kendilerini sattıkları şey ne kötüdür! Keşke bunu bilselerdi!"},{"n":103,"t":"Eğer onlar, iman edip sakınsalardı, Rablerinden çok daha iyi bir ödül alacaklardı. Keşke bilselerdi!"},{"n":104,"t":"Ey iman edenler! Peygamber`e “Bizi güt!” demeyiniz, “Bizi gözet!” deyiniz ve onu dinleyiniz. İnanmayanlara acıklı bir azap vardır."},{"n":105,"t":"Size Rabbinizden bir hayır indirilmesini ne kitap ehlinden kâfir olanlar ne de müşrikler isterler. Halbuki Allah, rahmetini dilediğine verir. Allah çok büyük lütuf sahibidir."},{"n":106,"t":"Biz, daha iyisini veya benzerini getirmedikçe bir âyeti ortadan kaldırmayız veya unutturmayız. Allah`ın her şeye gücü yettiğini bilmez misin?"},{"n":107,"t":"Göklerin ve yerin mülkiyet ve hükümranlığının Allah`a ait olduğunu da bilmez misin? Sizin için Allah`tan başka ne bir dost ne de bir yardımcı vardır."},{"n":108,"t":"Yoksa siz de, daha önce Mûsâ`ya sorulduğu gibi Peygamberinize sorular sormak mı istiyorsunuz? Kim küfrü imanla değiştirirse, kesinlikle düz yoldan sapmış olur."},{"n":109,"t":"Kitap ehlinin büyük bir çoğunluğu, hakikat kendilerine açıkça belli olduktan sonra, içlerindeki haset yüzünden, imanınızdan sonra sizi küfre döndürmek istediler. O halde siz, Allah gayesini gerçekleştirinceye kadar sıkı durun, iyi düşünün, reddedin! Şüphesiz ki Allah`ın gücü her şeye yeter."},{"n":110,"t":"Namazı kılınız, zekâtı veriniz, yaptığınız her iyiliği Allah katında bulacaksınız. Şüphesiz ki Allah, yapmakta olduklarınızı noksansız görür."},{"n":111,"t":"Kitap ehli, “Yahudiler veya Hıristiyanlar hariç, hiç kimse asla cennete giremeyecek” dediler. Bu onların kuruntusudur. Sen de onlara de ki, “Eğer gerçekten doğru söylüyorsanız, delilinizi getiriniz.”"},{"n":112,"t":"Bilakis, kim iyilik yaparak bütün benliğini Allah`a teslim ederse, onun ödülü Rabbinin katındadır. Öyleleri için ne bir korku vardır ne de üzüntü çekerler."},{"n":113,"t":"Yahudiler “Hıristiyanların hiçbir tutar tarafı yoktur” dediler. Hıristiyanlar da “Yahudilerin hiçbir tutar tarafı yoktur” dediler. Halbuki hepsi kitabı okuyorlar. Bilmeyenler de tıpkı onların söylediklerini söylediler. Allah, ihtilafa düştükleri hususlarda, kıyamet günü onlar hakkında hükmünü verecektir."},{"n":114,"t":"Allah`ın mescitlerinde O`nun adının anılmasına engel olan ve mescitlerin harap olmasına çalışandan daha zâlim kim vardır? Aslında bunların mescitlere korkarak girmeleri gerekir. Bunlar için dünyada rezillik, âhirette de büyük azap vardır."},{"n":115,"t":"Doğu da batı da Allah`a aittir. Nereye dönerseniz Allah`ın varlığı oradadır. Şüphesiz ki Allah, her şeyi çepeçevre kuşatan ve her şeyi bilendir."},{"n":116,"t":"“Allah çocuk edindi” dediler. Hâşâ! O, bundan münezzehtir/uzaktır. Oysa göklerde ve yerde olanların hepsi O`nundur; hepsi O`na boyun eğmektedir."},{"n":117,"t":"Allah, göklerin ve yerin yoktan yaratıcısıdır. Bir şeyi dilediğinde ona sadece, “Ol” der, o da hemen oluşmaya başlar."},{"n":118,"t":"“Allah bizimle niçin konuşmuyor, yahut bize niçin bir âyet gelmiyor?” Onlardan öncekiler de tıpkı onların dediklerini demişlerdi. Kalpleri birbirine benzedi. Gerçekleri iyice bilmek isteyenlere âyetleri apaçık gösterdik."},{"n":119,"t":"Doğrusu biz seni müjdeleyici ve uyarıcı olarak hak ile gönderdik. Sen cehennemliklerden sorumlu değilsin."},{"n":120,"t":"“Allah`ın yolu biricik yoldur.” Sana ulaşan bu bilgiden sonra onların arzularını takip edersen, Allah`tan sana ne bir dost, ne de bir yardımcı vardır."},{"n":121,"t":"Kendilerine kitap verdiklerimizin bazısı, onu, hakkını gözeterek okurlar. Çünkü onlar ona iman ederler. Onu inkâr edenler var ya, gerçekten zarara uğrayanlar onlardır."},{"n":122,"t":"Ey İsrâiloğulları! Size verdiğim nimeti ve sizi âlemlere üstün kıldığımı hatırlayınız."},{"n":123,"t":"Hiç kimsenin hiçbir kimseye fayda veremeyeceği, kimseden bedel kabul edilmeyeceği, şefaatin kimseye fayda vermeyeceği ve kâfirlere yardım edilmeyeceği bir günden sakınınız."},{"n":124,"t":"Bir zamanlar Rabbi, İbrâhim`i birtakım sorularla imtihan etti, o da onları tamamen cevaplandırınca, “Ben seni insanlara önder yapacağım” dedi. İbrâhim de, “Soyumdan da önderler yap!” dedi. Allah, “Sözüm zâlimleri içermez” dedi."},{"n":125,"t":"Beytullah`ı insanların toplantı yeri ve güvenlik mekânı yaptığımızı hatırla! İbrâhim`in makamından namaz kılma yeri edininiz. İbrâhim ve İsmail`e, “Tavaf edenler, itikâfa girenler, rükû ve secdeye varanlar için Beyt`imi temiz tutunuz” diye emretmiştik."},{"n":126,"t":"“İnkâr edeni de az bir süre faydalandırır, sonra onu cehennem azabına sürüklerim. Orası ne kötü bir yerdir!”"},{"n":127,"t":"“Ey Rabbimiz! Bizden bu hizmeti kabul buyur; çünkü sen her şeyi duyan ve her şeyi bilensin.”"},{"n":128,"t":"“Ey Rabbimiz! Bizi sana teslim olanlar kıl; neslimizden de sana teslim olan bir ümmet yetiştir. Bize ibadet yerlerimizi göster. Tövbemizi kabul et; çünkü sen tövbeleri ziyadesiyle kabul edensin ve çok merhametlisin.”"},{"n":129,"t":"“Ey Rabbimiz! Onlara, içlerinden senin âyetlerini okuyacak, kitap ve hikmet öğretecek, onların ruhlarını arındıracak bir peygamber gönder. Çünkü üstün gelen, her şeyi yerli yerince yapan sensin.”"},{"n":130,"t":"İbrâhim`in yolundan, kendini bilmezlerden başka kim yüz çevirir? Andolsun ki, biz onu dünyada seçtik; şüphesiz o, âhirette de iyilerdendir."},{"n":131,"t":"Hani Rabbi, İbrâhim`e, “Teslim ol!” deyince, o da, “Âlemlerin Rabbine teslim oldum” demişti."},{"n":132,"t":"Bunu İbrâhim de oğullarına vasiyet etti. Yakub da, “Ey oğullarım! Allah sizin için bu dini seçti. O halde Müslüman olarak ölünüz” dedi."},{"n":133,"t":"Yoksa Yakub`a ölüm geldiğinde siz orada mıydınız? O zaman Yakub, oğullarına, “Benden sonra kime kulluk edeceksiniz?” diye sormuştu. Onlar da, “Senin ve ataların İbrâhim, İsmail ve İshak`ın ilâhı olan tek ilâha kulluk edeceğiz; biz sadece O`na teslim olmuşuz” diye cevap vermişlerdi."},{"n":134,"t":"Şimdi o toplumlar geçip gittiler, onların kazandıkları kendilerine yazılacak, sizin kazandıklarınız ise size; ve siz onların yaptıklarından dolayı yargılanacak değilsiniz."},{"n":135,"t":"“Hayır! Biz, Hanif olan İbrâhim`in yoluna uyarız. O, müşriklerden değildi.”"},{"n":136,"t":"“Biz, Allah`a ve bize indirilene; İbrâhim, İsmail, İshak, Yakub ve onların torunlarına indirilene; Mûsâ ve İsâ`ya verilenlere, Rableri tarafından diğer peygamberlere verilenlere, onlardan hiçbirisinin arasında fark gözetmeksizin inandık ve biz sadece Allah`a teslim olduk” deyiniz."},{"n":137,"t":"Eğer onlar da sizin inandığınız gibi inanırlarsa, doğru yolu bulmuş olurlar; dönerlerse mutlaka ayrılık içine düşmüş olurlar. Onlara karşı Allah sana yeter. O işitendir; bilendir."},{"n":138,"t":"Biz Allah`ın manevi rengiyle boyandık. Allah`tan daha güzel rengi kim verebilir? Biz sadece O`na kulluk ederiz."},{"n":139,"t":"“Allah hakkında bizimle mücadele mi ediyorsunuz? Halbuki O, bizim de Rabbimizdir, sizin de. Bizim yaptıklarımız bize, sizin yaptıklarınız da size aittir. Biz O`na gönülden bağlanmışız.”"},{"n":140,"t":"“Siz mi daha iyi bilirsiniz, yoksa Allah mı? Allah katında bir tanıklığı gizleyenden daha zâlim kimdir? Allah yaptıklarınızdan habersiz değildir.”"},{"n":141,"t":"Onlar bir ümmetti, gelip geçtiler. Onların kazandıkları kendilerine, sizin kazandıklarınız da size aittir. Siz onların yaptıklarından sorguya çekilmeyeceksiniz."},{"n":142,"t":"«Doğu da Allah`ındır, Batı da Allah`ındır. O, kimi dilerse doğru yola iletir."},{"n":143,"t":"İnsanların sorunlarını çözesiniz/insanlara şâhit olasınız diye, sizi orta noktada olan bir toplum yaptık; böylece Peygamber de sizin sorunlarınızı çözer/size şâhit olur. Biz, Peygambere uyanı, topuğu üzerinde geriye dönenden ayıralım diye, senin eskiden yöneldiğin Kâbe`yi kıble yaptık. Bu, Allah`ın yol gösterdiği kimselerden başkasına elbette ağır gelir. Allah sizin imanınızı hiçe sayacak değildir. Şüphesiz ki Allah, insanlara karşı şefkatlidir; merhametlidir."},{"n":144,"t":"Biz, yüzünü göğe doğru çevirdiğini görüyoruz. İşte şimdi, seni memnun olacağın bir kıbleye döndürüyoruz. Artık yüzünü Mescid-i Harâm`a doğru çevir. Siz de hepiniz, nerede olursanız olunuz, yüzlerinizi o tarafa doğru çeviriniz. Şüphesiz kitap ehli, Peygamberin, Rablerinden gelen gerçek olduğunu çok iyi bilir. Allah onların yapmakta olduklarından habersiz değildir."},{"n":145,"t":"Sen, kitap ehline her türlü âyeti getirsen, yine de onlar senin kıblene dönmezler. Sen de onların kıblesine dönecek değilsin. Onlar da birbirlerinin kıblesine dönmezler. Sana gelen bilgiden sonra eğer onların arzularına uyarsan, şüphesiz zâlimlerden olursun."},{"n":146,"t":"Kendilerine kitap verdiklerimiz, peygamberi, çocuklarını tanıdıkları gibi tanırlar. Buna rağmen onlardan bir grup, bile bile gerçeği gizler."},{"n":147,"t":"Hakikat Rabbindendir. O halde şüphelenenlerden olma."},{"n":148,"t":"Herkesin yöneldiği bir yönü/gayesi vardır. Siz hayır işlerinde yarışınız. Nerede olursanız olunuz, sonunda Allah hepinizi bir araya getirir. Şüphesiz ki Allah`ın gücü her şeye yeter."},{"n":149,"t":"Nereden yola çıkarsan çık, yüzünü Mescid-i Harâm yönüne çevir. Bu emir, Rabbinden sana gelen bir gerçektir. Allah, yaptıklarınızdan habersiz değildir."},{"n":150,"t":"Nereden yola çıkarsan çık, yüzünü Mescid-i Haram yönüne çevir. Nerede olursanız olunuz, yüzünüzü o yöne çeviriniz ki haksızlık edenleri müstesna, insanların, aleyhinizde bir delili bulunmasın. Onlardan çekinmeyiniz, sadece benden çekininiz. Böylece size olan nimetimi tamamlayayım da belki doğru yolu bulursunuz."},{"n":151,"t":"Nitekim kendi içinizden size âyetlerimizi okuyan, sizi arındıran, size kitabı ve hikmeti talim edip bilmediklerinizi öğreten bir peygamber gönderdik."},{"n":152,"t":"Öyleyse beni anınız ki ben de sizi anayım. Bana şükrediniz, bana nankörlük etmeyiniz."},{"n":153,"t":"Ey iman edenler! Sabır ve dua ile yardım elde etmeye çalışınız. Çünkü Allah, sabredenlerle beraberdir."},{"n":154,"t":"Allah yolunda öldürülenlere “ölüler” demeyiniz; aksine onlar diridirler, fakat siz anlayamazsınız."},{"n":155,"t":"Elbette sizi korku, açlık; mallar, canlar ve ürünlerden eksiltmekle deneriz. Sabredenleri müjdele!"},{"n":156,"t":"Sabredenler, kendilerine bir musibet geldiğinde, “Biz Allah`ın kuluyuz ve biz O`na döneceğiz” derler."},{"n":157,"t":"İşte Rablerinden af ve rahmet onlaradır ve doğru yola girenler de onlardır."},{"n":158,"t":"Şüphesiz, Safâ ile Merve Allah`ın nişanlarındandır. Her kim Beytullah`ı hac veya umre niyetiyle ziyaret ederse, onları tavaf etmesinde kendisine bir günah yoktur. Her kim gönüllü olarak bir iyilik yaparsa, şüphesiz ki, Allah onu kabul eder ve hakkıyla bilir."},{"n":159,"t":"İndirdiğimiz açık delilleri ve kitapta insanlara apaçık gösterdiğimiz doğru yolu gizleyenlere hem Allah hem de bütün lanet ediciler lanet eder."},{"n":160,"t":"Ancak, tövbe edip durumlarını düzeltenler ve bildiklerini açıklayanlar istisnadır. Ben onların tövbesini kabul ederim."},{"n":"161-162","t":"Küfredip de kâfir olarak ölenler var ya Allah`ın, meleklerin ve bütün insanların laneti onların üzerinedir. Çok uzun süreli olarak o laneti taşırlar; azapları hafifletilmez ve kendilerine mühlet de verilmez."},{"n":163,"t":"Hepinizin tanrısı bir tek tanrıdır. O`ndan başka hiçbir tanrı yoktur; O, iyiliği bütün varlıkları kapsayandır, çok merhametlidir."},{"n":164,"t":"Şüphesiz göklerin ve yerin yaratılışında, gece ve gündüzün birbiri ardınca gelişinde, insanlara yararlı şeyler taşıyarak denizde seyreden gemilerde, Allah`ın gökten yağmur indirip onunla arzı ölmüşken diriltmesinde, oradaki hayvanları üretip yaymasında, gök ile yer arasında Allah`ın emrine boyun eğmiş rüzgârları ve bulutları şu yandan bu yana yöneltmesinde, aklını kullanan bir topluluk için nice deliller vardır."},{"n":165,"t":"Bazı insanlar, Allah`tan başkalarını O`na denk tanrılar edinirler; onları Allah`ı sever gibi severler. İman edenlerin Allah`a olan sevgileri çok daha fazladır. Keşke zâlimler, azabı gördüklerinde anlayacakları gibi, bütün kuvvetin Allah`a ait olduğunu ve O`nun azabının çok şiddetli olduğunu önceden anlayabilselerdi."},{"n":166,"t":"İşte o zaman kendilerine uyulan ve arkalarından gidilenler, uyanlardan hızla uzaklaşır ve azabı görürler. Neticede aralarındaki bağlar kopup parçalanmıştır."},{"n":167,"t":"Uyanların, “Keşke dünyaya bir daha dönsek de, onların bizden uzaklaştıkları gibi, biz de onlardan uzaklaşsak!” diyecekleri vakit, Allah onlara bütün yaptıklarını kendilerini sarmış pişmanlıklar halinde gösterecek ve onlar ateşten çıkamayacaklar."},{"n":168,"t":"Ey insanlar! Yeryüzündeki yiyeceklerin helâl ve temiz olanlarından yiyiniz, şeytanın adımlarını takip etmeyiniz; gerçekten o, sizin açık düşmanınızdır."},{"n":169,"t":"Şeytan, size ancak kötüyü, çirkini ve Allah hakkında bilmediğiniz şeyleri söylemenizi emreder."},{"n":170,"t":"Onlara, “Allah`ın indirdiğine uyunuz” dendiğinde, “Hayır, biz atalarımızı üzerinde bulduğumuz şeye uyarız” derler. Ya ataları akıllarını kullanamamış, doğruyu da bulamamış idiyseler de mi?"},{"n":171,"t":"Allah`ın indirdiğine tâbi olma çağrısına aldırış etmeyen kâfirlerin durumu, sadece çobanın bağırıp çağırmasını işiten hayvanların durumuna benzer. Çünkü onlar manen sağır, dilsiz ve kördürler. Bu sebepten dolayı da düşünmezler."},{"n":172,"t":"Ey iman edenler! Size verdiğimiz rızıkların temiz olanlarından yiyiniz. Eğer sadece Allah`a kulluk ediyorsanız, O`na şükrediniz."},{"n":173,"t":"Allah size yalnız leşi, kanı, domuz etini ve Allah`tan başkası için kesilmiş olanı yasaklamıştır. Fakat kim bunlardan yemek zorunda kalırsa, aşırıya kaçmamak ve sınırı aşmamak şartıyla ona günah yoktur. Şüphesiz ki Allah, çok bağışlayandır; çok merhamet edendir."},{"n":174,"t":"Allah`ın indirdiği kitabın bir kısmını gizleyenler ve onu az bir değere değişenler, karınlarına ateşten başka bir şey tıkmış olmazlar; kıyamet günü Allah onlarla konuşmayacak, onları temize çıkartmayacaktır; onlara acıklı bir azap vardır."},{"n":175,"t":"Onlar doğru yol karşılığında sapıklığı, bağışlanmaya bedel olarak da azabı satın almışlardır. Onlar ateşe ne kadar dayanıklıdırlar!"},{"n":176,"t":"Bu azabın sebebi, Allah`ın kitabı hak olarak indirmiş olmasıdır. Kitap hakkında anlaşmazlığa düşenler elbette derin bir ayrılığa düşmüşlerdir."},{"n":177,"t":"İyilik, yüzlerinizi doğu ve batıya çevirmeniz değildir. Asıl iyilik, Allah`a, âhiret gününe, meleklere ve kitaba iman edenin; malını çok sevmesine rağmen onu akrabaya, yetimlere, yoksullara, yolda kalmışlara, dilenenlere, köle ve esirlere verenin; namazı dosdoğru kılanın; zekâtı verenin; sözleştikleri zaman gereğini yerine getirenin; sıkıntıda, darlıkta, hastalıkta ve savaşın kızıştığı zamanda sabır gösterenin eyleminden oluşur. İşte doğru olanlar bunlardır; işte sakınanlar da bunlardır."},{"n":178,"t":"Ey iman edenler! Öldürülenler hakkında size kısas farz kılındı. Hüre hür, köleye köle, kadına kadın. Bununla beraber kim öldürülenin velisi tarafından bağışlanırsa, artık o zaman örfe uymak ve öldürülenin velisine güzellikle diyet ödemek gerekir. Bu, Rabbinizden bir hafifletme ve rahmettir. Kim bundan sonra zulüm yapmaya kalkışırsa, ona acı bir azap vardır."},{"n":179,"t":"Ey akıl sahipleri! Kısasta sizin için hayat vardır. Umulur ki sakınırsınız."},{"n":180,"t":"Birinize ölüm geldiği zaman, eğer bir mal bırakacaksa anaya, babaya, yakınlara uygun bir biçimde vasiyet etmek sakınanlar üzerine bir borçtur."},{"n":181,"t":"Her kim bunu işittikten ve kabullendikten sonra vasiyeti değiştirirse, günahı onu değiştirenleredir. Şüphesiz ki Allah işitir; bilir."},{"n":182,"t":"Her kim, vasiyet edenin bir hata yaptığından veya bir kusur işlediğinden endişe eder ve bunun üzerine mirasçılar arasında bir uzlaşma sağlarsa, kendisine bir günah yoktur. Doğrusu Allah çok affedicidir; merhamet sahibidir."},{"n":"183-184","t":"Ey iman edenler! Oruç, sizden öncekilere farz kılındığı gibi, size de sayılı günlerde farz kılındı ki, takvâya ulaşasınız. Ancak, sizden kim hasta ve yolcu olursa, diğer zamanlarda aynı gün sayısı kadar oruç tutmalıdır. Bunun dışında çeşitli nedenlerle orucu çok zorlukla tutabilecek olanlar, bir fakiri doyuracak kadar fidye vermelidirler. Her kim, yapmakla sorumlu olduğundan daha fazla iyilik yaparsa, kendisine iyilik yapmış olur; eğer bilirseniz, oruç tutmanız sizin için daha hayırlıdır."},{"n":185,"t":"Kur`ân, insanlara bir rehber, bu rehberliğin apaçık delili ve doğruyu yanlıştan ayırt edici bir ölçü olarak Ramazan ayında indirilmiştir. Bundan dolayı, sizden kim bu aya ulaşırsa, bu ayda oruç tutsun. Ancak hasta veya seyahatte olan, başka günlerde aynı günler miktarınca oruç tutsun. Allah sizin için kolaylık diler, zorluk istemez. Bütün bunlar, sayıyı tamamlamanız ve size doğru yolu göstermesine karşılık, Allah`ı tazim etmeniz ve O`na şükretmeniz içindir."},{"n":186,"t":"Kullarım sana beni sorduklarında de ki ben çok yakınım; bana dua ettiğinde, dua edenin isteğine karşılık veririm. O halde, benim davetime uysunlar ve bana güvensinler ki doğru yolu bulabilsinler."},{"n":187,"t":"Oruç gecesinde kadınlarınıza yaklaşmak size helâl kılındı. Onlar sizin için birer elbise, siz de onlar için birer elbisesiniz. Allah sizin kendinize kötülük ettiğinizi bildi ve tövbenizi kabul edip bağışladı. Artık Ramazan gecelerinde hanımlarınıza yaklaşın ve Allah`ın sizin için takdir ettiklerini isteyiniz. Sabahın beyaz ipliği siyah ipliğinden ayırt edilinceye kadar yiyiniz, içiniz, sonra akşama kadar orucu tamamlayınız. Mescitlerde itikafa çekilmiş olduğunuz zamanlarda kadınlarla birleşmeyiniz. Bunlar Allah`ın koyduğu sınırlardır. Sakın bu sınırlara yaklaşmayınız. İşte böylece Allah, âyetlerini insanlara açıklar. Umulur ki korunurlar."},{"n":188,"t":"Mallarınızı aranızda haksız sebeplerle yemeyiniz. Kendiniz bilip dururken, insanların mallarından bir kısmını haram yollarla yemeniz için o malları rüşvet olarak hakimlere vermeyiniz."},{"n":189,"t":"“Onlar, haccın ve insanların öteki faaliyetlerinin vaktini gösterir. Evlere arkalarından girmeniz iyi değildir; asıl iyi Allah`a karşı sorumluluk bilincinde olmaktır. O halde evlere kapılarından giriniz ve Allah`a karşı sorumluluğunuzun bilincinde olunuz ki kurtuluşa eresiniz.”"},{"n":190,"t":"Size savaş açanlara karşı Allah yolunda savaşınız, ama aşırı gitmeyiniz, doğrusu Allah aşırı gidenleri sevmez."},{"n":191,"t":"Sizi öldürmeye teşebbüs edenleri karşılaştığınız her yerde öldürünüz ve sizi çıkardıkları yerden siz de onları çıkartınız; zaten zulüm ve baskı, öldürmekten daha kötüdür. Onlar size savaş açmadıkça Mescid-i Harâm civarında onlarla savaşmayınız, ama eğer sizinle savaşırlarsa onları öldürünüz; kâfirlerin cezası budur."},{"n":192,"t":"Eğer vazgeçerlerse, Allah çok affedicidir; merhamet sahibidir."},{"n":193,"t":"O halde zulüm ve baskı kalmayıncaya ve Allah`ın dini egemen oluncaya kadar onlarla savaşınız. Vazgeçerlerse siz de vazgeçiniz; zâlimlerden başkasına düşmanlık yoktur."},{"n":194,"t":"Haram ay, haram aya karşılıktır. Barışa hürmet de karşılıklıdır. Kim size saldırırsa, siz de ona denk olacak şekilde saldırınız. Allah`tan sakınınız ve biliniz ki, Allah sakınanlarla beraberdir."},{"n":195,"t":"Allah yolunda harcama yapınız. Kendi kendinizi tehlikeye atmayınız ve iyilik yapmaya devam ediniz; Allah iyilik yapanları sever."},{"n":196,"t":"Haccı ve umreyi Allah için tamamlayınız. Eğer yapmaktan alıkonursanız, gücünüzün yeteceği bir kurban kesiniz ve kurban kesilinceye kadar başlarınızı tıraş etmeyiniz. Fakat içinizden hasta olan, yahut başında rahatsızlık olan kimse oruç tutarak veya sadaka vererek veya başka bir ibadet ile özrünü karşılayacak bir şey yapmalıdır. Sağlıklı ve emniyette olduğunuzda, hacdan önce umre yapan gücünün elverdiği türden bir kurban kessin, ama kurbana gücü yetmeyen, hac sırasında üç gün ve döndükten sonra yedi gün, yani tam on gün oruç tutsun. Bütün bunlar, Mescid-i Harâm civarında yaşamayanlar içindir. Allah`tan sakınınız. Bilin ki, Allah`ın vereceği ceza ağırdır."},{"n":197,"t":"cinsel ilişkide bulunmak, günah sayılan davranışları yapmak ve kavga etmek. Ne hayır işlerseniz Allah onu bilir. Azık edininiz, biliniz ki azığın en iyisi takvâdır. Ey akıl sahipleri, benden sakınınız."},{"n":198,"t":"Rabbinizden gelecek bir lütfu aramanızda size herhangi bir günah yoktur. Arafat`tan ayrılıp akın ettiğinizde, Meş‘ar-i Harâm`da Allah`ı anın ve O`nu size gösterdiği şekilde anın. Şüphesiz siz, daha önce yanlış gidenlerden idiniz."},{"n":199,"t":"Sonra dalga dalga ilerleyen öteki kalabalıklarla birlikte, siz de ilerleyiniz ve Allah`tan af dileyiniz. Doğrusu Allah, affedicidir; merhamet sahibidir."},{"n":200,"t":"Hac ibadetlerinizi bitirdiğinizde, atalarınızı andığınız gibi, hatta daha güçlü bir anışla Allah`ı anmaya devam ediniz. Çünkü öyle insanlar vardır ki, “Bize bu dünyada ver” diye dua ederler. Böyle kimseler, âhiretten nasip alamayacaklardır."},{"n":201,"t":"Onlardan bir kısmı da, “Ey Rabbimiz! Bize dünyada iyilik ver, âhirette de iyilik ver. Bizi cehennem azabından koru” derler."},{"n":202,"t":"İşte onlar için kazandıklarından bir nasip vardır. Allah`ın hesabı çok süratlidir."},{"n":203,"t":"Mina`da tayin edilmiş belli günlerde Allah`ı anınız; her kim iki gün içinde acele ederse günaha girmez, kim orada daha uzun kalırsa, o da Allah`a karşı sorumluluğunun bilincinde oldukça, günaha girmemiş olur. O halde Allah`a karşı sorumluluğunuzun bilincinde olunuz ve sonunda Allah`ın huzurunda toplanacağınızı biliniz."},{"n":204,"t":"Bazı insanların dünya hayatı hakkında söyledikleri senin hoşuna gider ve o, kalbindekine Allah`ı da şâhit getirir. Halbuki o, hasımların en yamanıdır."},{"n":205,"t":"O/münafık, bir iş başına geçtiğinde, yeryüzünde bozgunculuk çıkarmaya, kültürü ve nesli helâk etmeye çalışır. Allah bozgunculuğu sevmez."},{"n":206,"t":"Kendisine ne zaman “Allah`a karşı gelmekten sakın” dense, gururu onu günaha sürükler. Artık böylelerine cehennem yetişir. Ne kötü bir yataktır o!…"},{"n":207,"t":"Ama insanlar arasında bazıları da var ki, Allah`ın rızasını kazanmak için benliğini feda eder. Allah da kullarına çok şefkatlidir."},{"n":208,"t":"Ey iman edenler! Hepiniz birden barışa giriniz! Sakın şeytanın peşinden gitmeyiniz. Çünkü o size apaçık bir düşmandır."},{"n":209,"t":"Size apaçık deliller geldikten sonra, eğer barıştan ayrılırsanız, biliniz ki, Allah kudret ve hikmet sahibidir."},{"n":210,"t":"Onlar, sadece buluttan gölgeler içinde Allah`ın ve meleklerin kendilerine gelmesini bekliyorlar. Ama o zaman her şeye karar verilmiş ve her şey Allah`a döndürülmüş olurdu."},{"n":211,"t":"Onlara nice açık âyetler verdik. Kim kendisine geldikten sonra Allah`ın nimetini değiştirirse, bilsin ki Allah`ın cezası şiddetlidir."},{"n":212,"t":"İnkâr edenlere bu dünya hayatı güzel görünür. Bu sebeple, iman edenlerle alay ederler. Ama, kıyamet günü Allah`a karşı sakınma duygusu taşıyanlar, onlardan daha üstün olacaklardır. Allah, dilediği kimselere hesapsız rızık verir."},{"n":213,"t":"İnsanlar bir tek ümmetti; Allah onlara müjdeleyici ve uyarıcı olarak peygamberler gönderdi. Peygamberler aracılığı ile insanların anlaşmazlığa düştükleri konular hakkında aralarında hüküm vermek için hak kitap da indirdi. Halbuki, o konularda anlaşmazlığa düşenler, kendilerine apaçık âyetler geldikten sonra, aralarındaki kıskançlık yüzünden ihtilafa düşen kitap ehlinden başkası değildi. Bunun üzerine Allah, kendi iradesiyle, inananları ihtilafa düştükleri hakikate eriştirdi. Çünkü Allah, dileyeni doğru yola ulaştırır."},{"n":214,"t":"Yoksa siz, sizden önce gelip geçenlerin başına gelenler sizin de başınıza gelmeden cennete gireceğinizi mi sandınız? Yoksulluk ve sıkıntı onlara öylesine dokunmuş ve öyle sarsılmışlardı ki, nihayet Peygamber ve beraberindeki müminler “Allah`ın yardımı ne zaman?” dediler. Bilesiniz ki Allah`ın yardımı yakındır."},{"n":215,"t":"“İyilik umarak yapacağınız harcama, anne babanıza, yakın akrabanıza, yetime, muhtaca ve yolcuya/bitirilemeyen hayır işlerine aittir; her ne iyilik yaparsanız mutlaka Allah onu bilir.”"},{"n":216,"t":"Hoşunuza gitmese de savaş size farz kılındı; mümkündür ki bazen hoşunuza gitmeyen bir şey sizin için iyi, hoşunuza giden bir şey de hakkınızda kötü olabilir. Allah bilir, siz bilemezsiniz."},{"n":217,"t":"“O ayda savaşmak büyük bir günahtır. İnsanları Allah`ın yolundan çevirmek, Allah`ı inkâr etmek, Mescid-i Harâm`ın ziyaretine engel olmak ve halkını oradan çıkarmak ise Allah katında daha büyük bir suçtur. Fitne de, adam öldürmekten daha büyük bir günahtır.” Eğer onların güçleri yeterse, sizi dininizden döndürünceye kadar size karşı savaşa devam ederler. Sizden de kim dininden döner ve kâfir olarak ölürse, onların yaptıkları işler dünyada da ahirette de boşa gider. Onlar cehennemliktir ve orada süreli kalırlar."},{"n":218,"t":"Şüphesiz ki, iman edenler, hicret edip Allah yolunda üstün bir gayretle mücadele verenler, işte ancak onlar Allah`ın rahmetini umabilirler. Allah çok affedicidir; merhamet sahibidir."},{"n":219,"t":"“Her ikisinde de büyük bir günah ve insanlar için birtakım faydalar vardır. Ancak her ikisinin de günahı faydasından büyüktür.” Yine sana iyilik yolunda ne harcayacaklarını soruyorlar. “İhtiyaç fazlasını” de. Allah, düşünesiniz diye size âyetlerini böyle açıklıyor."},{"n":220,"t":"“Onların durumlarını düzeltmek en hayırlı olanıdır. Eğer onlarla birlikte yaşarsanız, onlar sizin kardeşlerinizdir. Allah işleri bozanı da düzelteni de bilir. Eğer Allah dileseydi sizi sıkıntıda bırakırdı. Çünkü Allah güçlüdür; hakimdir.”"},{"n":221,"t":"İman etmedikçe müşrik kadınlarla evlenmeyiniz. İman eden bir cariye, beğendiğiniz müşrik bir kadından kesinlikle daha iyidir. İman etmedikçe müşrik erkekleri de kızlarınızla evlendirmeyiniz. İnanmış bir köle beğenseniz bile müşrik bir kişiden kesinlikle daha iyidir. Müşrikler cehenneme çağırır. Allah ise, izniyle cennete ve affa çağırır. Allah, düşünüp anlasınlar diye âyetlerini insanlara açıklar."},{"n":222,"t":"“O bir eziyettir. Âdet halinde kadınlardan uzak durunuz ve temizleninceye kadar onlara yaklaşmayınız; temizlendiklerinde ise Allah`ın size emrettiği şekilde onlara yaklaşınız. Doğrusu, Allah tövbe edenleri ve temizlenenleri sever.”"},{"n":223,"t":"Eşleriniz sizin için ürün veren topraktır. Öyleyse, toprağınızı dilediğiniz gibi işleyin. Kendiniz için önceden hazırlık yapın. Allah`tan sakının; bilin ki siz Allah`a kavuşacaksınız. Müminleri müjdele!"},{"n":224,"t":"Allah adına yaptığınız yeminleri, iyilik yapmanıza, takvâya ve insanlar arasında barışı gerçekleştirmenize engel kılmayın. Zira Allah, her şeyi duyandır; her şeyi bilendir."},{"n":225,"t":"Allah, düşünmeden yaptığınız yeminlerden dolayı sizi sorumlu tutmaz; ama kalplerinizin eylemlerinden sorumlu tutar. Allah, çok affedicidir; yumuşak davranandır."},{"n":226,"t":"Hanımlarına yaklaşmamaya yemin edenler dört ay bekleyebilirler. Eğer bu müddet zarfında hanımlarına dönerlerse, şüphesiz Allah affedicidir; merhamet sahibidir."},{"n":227,"t":"Eğer boşamaya karar verirlerse, şüphesiz Allah işitendir; bilendir."},{"n":228,"t":"Boşanmış kadınlar, evlenmeksizin üç ay hali boyunca bekleyeceklerdir. Allah`a ve ahiret gününe inanıyorlarsa, rahimlerinde Allah`ın yarattığını gizlemeleri onlara helâl olmaz. Bu süre zarfında barışmak isterlerse, kocalarının onları almaya öncelikle hakları vardır. Erkeklerin, adalet ölçülerine göre kadınlar üzerinde hakları olduğu gibi, kadınların da erkekler üzerinde hakları vardır. Kocalar, eşleri üzerinde önceliğe sahiptirler. Allah kudret ve hikmet sahibidir."},{"n":229,"t":"Boşanma iki defadır/Boşanmada iki celse yapılmış olursa, ondan sonra ya iyilikle tutmak veya güzellikle ayrılmak gerekir. Kadınlara mehir olarak verdiğiniz bir şeyi geri almanız helâl değildir. Meğer ki eşler, Allah`ın sınırlarını yerine getirememekten korkmuş olsunlar. Ancak erkek ve kadının, Allah`ın sınırlarında durmayacaklarından korkarsanız, o zaman kadının ayrılmak için verdiği fidyede hakkından vazgeçmesinde ikisine de bir günah yoktur. İşte bunlar, Allah`ın sınırlarıdır. Sakın bunları aşmayınız. Kim Allah`ın sınırlarını aşarsa işte onlar zâlimlerdir."},{"n":230,"t":"Eğer boşanmayı üçüncü celsede gerçekleştirirse, ondan sonra kadın bir başkası ile evlenmedikçe, erkeğin onu alması kendisine helâl olmaz. İkinci kocası da onu boşarsa, Allah`ın sınırlarını koruyacaklarına inandıkları takdirde, eski karı-kocanın yeniden evlenmelerinde bir sakınca yoktur. Bunlar Allah`ın sınırlarıdır. Allah bunları, öğrenmek isteyenler için açıklıyor."},{"n":231,"t":"Böylece kadınları boşadığınızda ve onlar bekleme sürelerini bitirdiklerinde, artık onları ya iyilikle tutunuz veya iyilikle bırakınız. Ama istekleri dışında, eziyet etmek için alıkoymayınız. Kim böyle yaparsa kendine zulmetmiş olur. Allah`ın âyetlerini alaya almayınız. Allah`ın size olan nimetini ve size öğüt vermek için indirdiği kitap ve hikmeti hatırlayınız. Allah`tan sakınınız ve Allah`ın her şeyi hakkıyla bildiğini biliniz."},{"n":232,"t":"Kadınları boşadığınız ve onlar da bekleme müddetlerini bitirdikleri vakit, aralarında iyilikle anlaştıkları takdirde, eski kocalarıyla evlenmelerine engel olmayınız! İşte bununla, içinizden Allah`a ve ahiret gününe inanan kimselere öğüt verilmektedir. Bu öğüdü tutmanız, kendiniz için en iyisi ve en temizidir. Allah bilir, siz bilemezsiniz."},{"n":233,"t":"Ne çocuğundan dolayı anneye eziyet edilsin, ne de çocuğundan dolayı babaya. Babanın mirasçısına da aynı görev düşer. Eğer anne baba, çocuğun sütten kesilmesine karşılıklı rıza ve danışma ile karar verirlerse, onlara bir günah yoktur; eğer çocuğunuzu süt annelere emanet etmeye karar verirseniz, teslim edeceğiniz çocuğun emniyetini uygun bir şekilde sağladığınız takdirde size bir günah yüklenmez. Allah`tan sakınınız ve biliniz ki Allah bütün yaptıklarınızı görür."},{"n":234,"t":"İçinizden ölenlerin geride bıraktıkları kadınların yeniden evlenmeleri için dört ay on günlük bir bekleme süresi geçirmeleri gerekir. Bekleme süresinin sonuna vardıklarında, kendileriyle ilgili olarak meşru şekilde ne yaparlarsa yapsınlar bir günah yoktur. Allah, bütün yaptıklarınızdan haberdardır."},{"n":235,"t":"İddet bekleyen kadınlarla evlenme hususundaki düşüncelerinizi üstü kapalı bir biçimde anlatmanızda veya onu içinizde gizli tutmanızda size günah yoktur. Allah bilir ki siz onları anacaksınız. Fakat meşru sözler söylemeniz müstesna, sakın onlarla gizlice buluşma sözü vermeyiniz. Farz olan bekleme müddeti dolmadan, nikâh kıymaya kalkışmayınız. Biliniz ki, Allah gönlünüzdekileri bilir. Bu sebeple Allah`tan sakınınız. Şunu iyi biliniz ki Allah affedicidir; merhametlidir."},{"n":236,"t":"Eğer kadınlarla cinsel ilişki kurmadan ve mehir kesmeden onları boşarsanız, bunda size bir günah yoktur. Ancak böyle durumlarda onları örfe uygun olarak faydalandırınız; imkanı geniş olan kendi gücüne, dar olan da kendi gücüne göre... Bu, güzel davrananlar üzerine bir yükümlülüktür."},{"n":237,"t":"Eğer onları, cinsel ilişkiye girmeden boşar da, mehir tayin etmiş bulunursanız, o vakit üzerinize düşen yükümlülük, tayin ettiğiniz mehrin yarısını vermektir. Ancak, kadınların vazgeçmesi veya nikâh bağı elinde bulunanın vazgeçmesi hali müstesna! Mehirden vazgeçmeniz takvâya daha uygundur. Aranızda iyilik ve ihsanı unutmayınız. Şüphesiz ki Allah, yapmakta olduklarınızı hakkıyla görür."},{"n":238,"t":"Namazlara ve orta namaza/ikindi namazına devam ediniz, gönülden bağlılık ve saygı ile Allah`ın huzurunda ayakta durunuz."},{"n":239,"t":"Ama eğer tehlikede iseniz, yaya veya binekli olarak kılınız; güvene kavuşunca Allah`ı anınız, çünkü bilmediklerinizi size öğreten O`dur."},{"n":240,"t":"İçinizden ölüp geride eşler bırakanlar, eşlerinin, evlerinden çıkarılmadan bir yıla kadar geçimlerinin sağlanmasını vasiyet etsinler. Şâyet kendileri çıkarlarsa, onların kendileri hakkında uygun olanı yapmalarında sizin için bir günah yoktur. Allah daima üstündür; hikmet sahibidir."},{"n":241,"t":"Boşanmış olan kadınların örfe uygun olarak geçimlerini sağlamak, takvâ sahipleri üzerine bir yükümlülüktür."},{"n":242,"t":"Aklınızı kullanasınız diye Allah size âyetlerini böyle açıklıyor."},{"n":243,"t":"Sen ölüm korkusuyla yurtlarını terk eden binlerce kişiyi görmedin mi? Ki bu durumda Allah onlara “ölün” demişti ve sonra da onları hayata döndürmüştü. Unutmayın ki Allah, insanoğluna karşı lütufta sınırsızdır, ancak insanların çoğu nankördür."},{"n":244,"t":"Öyleyse Allah yolunda savaşınız ve biliniz ki Allah her şeyi işitendir; her şeyi bilendir."},{"n":245,"t":"Allah`ın kat kat fazlasıyla geriye ödeyeceği bir güzel borcu O`na verecek kimdir? Allah alır ve kat kat fazlasıyla geri verir; hepiniz sonunda O`na döndürüleceksiniz."},{"n":246,"t":"Mûsâ`dan sonra İsrâiloğulları`nın önde gelenlerinin, peygamberlerinden birine, “Bize bir hükümdar tayin et ki Allah yolunda savaşalım” dediklerini bilmez misin? O, “Ya savaşmanız emredilir de savaşmaktan kaçınırsanız?” dediğinde, onlar, “Biz ve çocuklarımız yurtlarımızdan sürülmüşken, Allah yolunda neden savaşmayalım?” diye cevap verdiler. Halbuki savaşmak onlara emredilince birkaçı dışında uzak durdular. Allah zâlimleri iyi bilmektedir."},{"n":247,"t":"Onların peygamberi, toplumunun önde gelenlerine, “Bakın” dedi; “Allah, Tâlût`u size hükümdar olarak tayin etti!” Onlar, “Biz hükümdarlığa ondan daha lâyık iken ve ona fazla bir servet de verilmemişken nasıl bizim üzerimize hüküm sahibi olabilir?” dediler. Peygamber, “Bakın” dedi; “Allah onu sizden daha üstün kılmış, ona derin bilgi ve mükemmel bir beden bahşetmiştir. Allah hükümranlığı istediğine verir; zira Allah, her şeyi kuşatan ve her şeyi bilendir.”"},{"n":248,"t":"Peygamberleri onlara, “Onun hükümranlığının delili, tâbûtun/sandukanın size gelmesidir. Meleklerin taşıdığı o tâbûtun/sandukanın içinde Rabbinizden size bir huzur; Mûsâ ve Hârûn ailelerinin bıraktıklarından bir kalıntı vardır. Eğer inanmış kimseler iseniz sizin için bunda şüphesiz bir ders vardır” dedi."},{"n":249,"t":"Ondan içen benden olmayacak, onu tatmaktan sakınan ise benden olacaktır; ondan sadece bir avuç dolusu içen ise affa mazhar olacaktır.” Ancak birkaçı dışında hepsi ondan içtiler. O ve ona inananlar nehri geçer geçmez ötekiler, “Câlût ve askerlerine karşı bugün hiç gücümüz yok” dediler. Kesin olarak Allah`a kavuşacaklarını bilenler ise, “Nice küçük topluluklar, Allah`ın izniyle büyük kalabalıklara üstün gelmiştir; zira Allah güçlüklere karşı sabırlı olanlarla beraberdir” diye cevap verdiler."},{"n":250,"t":"Onlar Câlût ve kuvvetleriyle karşı karşıya geldiklerinde, “Ey Rabbimiz! Bize zorluklara tahammül gücü bağışla, adımlarımızı sağlam kıl ve hakikati inkâr eden bu topluma karşı bize yardım et!” diye dua ettiler."},{"n":251,"t":"Bunun üzerine, Allah`ın izniyle onları bozguna uğrattılar. Dâvûd da Câlût`u öldürdü; Allah ona hükümranlık ve hikmet verdi ve istediği her şeyin bilgisini öğretti. Eğer Allah, insanlara kendilerini başkalarına karşı savunma gücü vermeseydi, yeryüzü çürüme ve yozlaşmaya maruz kalırdı. Allah, bütün insanlara karşı sınırsız lütuf sahibidir."},{"n":252,"t":"Bunlar Allah`ın âyetleridir. Biz onları sana doğru olarak anlatıyoruz. Şüphesiz sen, Allah tarafından gönderilmiş peygamberlerdensin."},{"n":253,"t":"O peygamberlerin bir kısmını bir kısmına üstün kıldık. Allah onlardan bir kısmıyla konuşmuş, bazılarını derece derece yükseltmiştir. Meryem oğlu İsa`ya da mucizeler verdik ve onu Rûhulkudüs/Cebrail ile güçlendirdik. Allah dileseydi, o peygamberlerden sonra gelen milletler, kendilerine açık deliller geldikten sonra birbirleriyle savaşmazlardı. Fakat onlar ihtilafa düştüler de bazıları iman etti, bazıları da inkâr etti. Allah dileseydi onlar savaşamazlardı; lâkin Allah dilediğini yapar."},{"n":254,"t":"Ey iman edenler! Kendisinde hiçbir alışveriş, dostluk ve şefaatin olmayacağı gün gelmeden önce, size verdiğimiz rızıktan hayır yoluna harcayınız. Biliniz ki, hakikati inkâr edenler zâlimlerin ta kendileridir."},{"n":255,"t":"Allah`tan başka ilah yoktur; her zaman diridir; bütün varlıkların kendi kendine yeterli kaynağıdır. Ne uyuklama tutar O`nu, ne de uyku. Göklerde ve yerde ne varsa O`nundur. O`nun izni olmaksızın katında şefaat edebilecek olan kimdir? O, insanların gözlerinin önünde olanı da arkalarında olanı da bilir; O dilemedikçe insanlar O`nun ilminden hiçbir şey edinemez, hiçbir şey kavrayamazlar. O`nun sonsuz kudreti ve egemenliği gökleri ve yeri kaplar. Onların korunup desteklenmesi O`na ağır gelmez. Gerçekten yüce ve büyük olan yalnızca O`dur."},{"n":256,"t":"Dinde zorlama yoktur. Artık doğru, yanlıştan ayrılmıştır. O halde tâğûtu/insanı Allah`tan uzaklaştıran her şeyi inkâr edip Allah`a inananlar, hiçbir zaman kopmayacak en sağlam kulpa tutunmuşlardır. Zira, Allah her şeyi işitendir; her şeyi bilendir."},{"n":257,"t":"Allah inananların dostudur, onları karanlıklardan aydınlığa çıkarır. İnkâr edenlerin dostları ise tâğûttur; onları aydınlıktan alıp karanlıklara götürür. İşte onlar cehennemliklerdir. Onlar orada uzun süreli kalırlar."},{"n":258,"t":"Allah kendisine hükümdarlık verdiği için şımararak Rabbi hakkında İbrâhim ile tartışmaya gireni görmedin mi? İşte o zaman İbrâhim, “Rabbim hayat veren ve öldürendir” demişti. O da, “Hayat veren ve öldüren benim” demişti. İbrâhim, “Allah güneşi doğudan getirmekte, haydi sen de onu batıdan getir” deyince kâfir apışıp kaldı. Allah zâlimler topluluğunu hidayete erdirmez."},{"n":259,"t":"“Bu halde ne kadar kaldın?” O da, “Bir gün veya bir günden biraz daha az bir süre kaldım” diye cevap vermişti. Allah, “Hayır” dedi. “Bu halde bir asır kaldın! Yiyeceğine ve içeceğine bak; geçen yıllar onları bozmamış ve eşeğine bak; biz bütün bunları insanlara bir ders olasın diye yaptık. Bir de şu insanların ve hayvanların kemiklerine bak. Onları nasıl birleştirip et ile örttüğümüzü düşün!” Bütün bunlar ona açıklanınca, “Şimdi öğrendim ki Allah her şeye kâdirdir” dedi."},{"n":260,"t":"Hani İbrâhim, “Ey Rabbim! Ölüye nasıl hayat verdiğini bana göster!” demişti. O da, “Yoksa inanmıyor musun?” diye sormuştu. İbrâhim, “Evet, inanıyorum ama kalbim tamamen doyuma ulaşsın” deyince Allah, “Dört kuş al ve onlara sana itaat etmeyi öğret, sonra onları her tepeye ayrı ayrı sal; sonra da onları çağır. Uçarak sana gelecekler. Bil ki Allah, her şeyden üstündür, hikmet sahibidir” dedi."},{"n":261,"t":"Allah yolunda mallarını harcayanların durumu, kendisinden yedi başak çıkan ve her başakta yüz tane bulunan bir buğday tohumuna benzer. Allah dilediğine kat kat verir; Allah her şeyi kuşatandır; her şeyi bilendir."},{"n":262,"t":"Mallarını Allah yolunda harcayıp da arkasından başa kakmayan, fakirlerin gönlünü kırmayan kimseler var ya, onların Rabbleri katında has ödülleri vardır. Onlara hiç korku olmadığı gibi, onlar üzülmeyeceklerdir de."},{"n":263,"t":"Güzel söz ve bağışlama, arkasından incitme gelen sadakadan daha iyidir. Allah zengindir; yumuşak davranandır."},{"n":264,"t":"Ey iman edenler! Allah`a ve ahiret gününe inanmadığı halde malını gösteriş için harcayan kimse gibi, başa kakmak ve gönül incitmek suretiyle, yaptığınız hayırları boşa çıkarmayınız. Böylesinin durumu, üzerinde biraz toprak bulunan düz kayaya benzer ki, sağanak bir yağmur isabet etmiş de onu çıplak pürüzsüz kaya haline getirivermiştir. Bunlar kazandıklarından hiçbir şeye sahip olamazlar. Allah, kâfirleri doğru yola iletmez."},{"n":265,"t":"Bir yağmur yağar, bu sayede ürün iki misli artar; yağmur olmadığı zaman da oraya çise düşer de yine ürün verir. Allah yaptığınız her şeyi görür."},{"n":266,"t":"Sizden biri arzu eder mi ki, hurma ve üzüm bağları bulunan ve içinden ırmaklar akan, ayrıca içinde meyvenin her çeşidi bulunan bir bahçesi olsun da tam kendisine ihtiyarlık çöküp, küçük ve güçsüz çocuklarının bulunduğu bir anda ateşli bir kasırga kopsun ve bahçesini kasıp kavursun? İşte Allah düşünesiniz diye size böylece delilerini açıklıyor."},{"n":267,"t":"Ey iman edenler! Kazandıklarınızın temizlerinden ve sizin için rızık olarak yerden çıkarttıklarımızdan infak ediniz. Size verildiğinde, gözünüzü yummadan alamayacağınız kötü malı, hayır diye vermeye kalkışmayınız. Biliniz ki, Allah zengindir; övgüye lâyıktır."},{"n":268,"t":"Şeytan sizi fakirlikle korkutur ve cimriliği emreder. Oysa Allah size bağışlamasını ve lütfunu vaad eder. Allah`ın lütfu boldur; O, her şeyi bilir."},{"n":269,"t":"Allah, dileyene hikmeti verir; kime hikmet verilmişse, ona büyük servet verilmiştir. Ama akıl sahipleri dışında kimse bunu düşünüp anlayamaz."},{"n":270,"t":"Yaptığınız her harcamayı ve adadığınız her adağı elbette Allah bilir. Zâlimler için yardımcı yoktur."},{"n":271,"t":"Yardımları açıktan yapmanız güzeldir; ama fakire gizlice vermeniz sizin için daha hayırlı olur ve günahlarınızın bir kısmını örter. Allah, yaptığınız her şeyden haberdardır."},{"n":272,"t":"Ey Peygamber! İnsanları hidayete erdirmek sana ait değildir; ancak Allah dileyeni hidayete erdirir. Sadece Allah`ın rızasını kazanmak amacıyla başkalarına her ne iyilik yaparsanız bu kendi yararınızadır. Çünkü yapacağınız her iyilik size, olduğu gibi geri dönecek ve size haksızlık yapılmayacaktır."},{"n":273,"t":"Sadakalarınızı, kendilerini Allah yoluna vakfedip yeryüzünde çarşı pazar dolaşmayanlara veriniz. Durumlarını bilmeyen, iffet ve dilenmemelerinden dolayı onları zengin sanır; sen onları yüz ifadelerinden tanırsın. İnsanlardan arsız bir şekilde istemekten kaçınırlar. Onlara ne iyilik yaparsanız, doğrusu Allah hepsini bilir."},{"n":274,"t":"Mallarını gece ve gündüz, gizli ve âşikâr infak edenlerin mükâfatları Rabbleri katındadır. Onlara ne korku vardır, ne de üzülürler."},{"n":275,"t":"Faiz yiyenler, şeytanın çarptığı kimselerin kalkması gibi kalkarlar/davranırlar. Bu hal onların, “Alım satım da tıpkı faiz gibidir” demeleri yüzündendir. Halbuki Allah alım satımı helâl, faizi haram kılmıştır. Bu nedenle, kim Rabbinin öğüdünü dinler ve hemen faizden vazgeçerse, evvelki kazançlarını koruyabilir ve onun hakkında karar vermek artık Allah`a kalır; faize geri dönenlere gelince, içinde süreli kalacakları cehennemin yâranı onlardır."},{"n":276,"t":"Allah faizi mahveder, sadakaları ise bereketlendirir. Allah inatçı nankörleri ve günahta ısrarlı olanları sevmez."},{"n":277,"t":"İman edenlerin, iyi işler yapanların, namazlarını doğru kılanların, zekâtı verenlerin mükâfatları Rableri katındadır. Onlar için ne korku vardır ne de üzülürler."},{"n":278,"t":"Ey iman edenler! Allah`tan sakınınız. Eğer gerçekten inanıyorsanız mevcut faiz alacaklarınızı terk ediniz."},{"n":279,"t":"Eğer böyle yapmazsanız, biliniz ki Allah`a ve Peygamberine savaş açmış olursunuz. Ama eğer tövbe ederseniz, ana paranızı geri almaya hak kazanırsınız. Böylece ne haksızlık yapmış, ne de haksızlığa uğramış olursunuz."},{"n":280,"t":"Eğer borçlu güç durumda ise, rahatlayıncaya kadar ona bir zaman tanıyınız; bir karşılık beklemeden borcu tamamıyla silmek, eğer bilirseniz, sizin kendi iyiliğinize olacaktır."},{"n":281,"t":"Allah`a döndürüleceğiniz, sonra da herkesin kazancının eksiksiz geri verileceği ve hiç kimsenin haksızlığa uğratılmayacağı günden sakınınız."},{"n":282,"t":"Ey iman edenler! Ne zaman belli bir vade ile borç verir veya alırsanız yazıyla tespit ediniz. Bir yazıcı/noter, âdil/tarafsız olarak onu kaydetsin. Hiçbir yazıcı, Allah`ın ona öğrettiği gibi yazmayı reddetmesin. Öylece, olduğu gibi yazsın. Borçlanan kaydettirsin; Rabbine karşı sorumluluğunun bilincinde olsun ve taahhüdünden bir şey eksiltmesin. Eğer borç altına girenin aklî veya bedenî bir zaafı varsa veya kendisi kaydettirebilecek durumda değilse, onun menfaatini kollamakla görevli olan kimse, onu âdil bir şekilde kaydettirsin. İçinizden iki erkeği şahit tutunuz; iki erkek bulunmazsa, kabul edebileceğiniz kimselerden bir erkek ile iki kadını şahit tutunuz ki onlardan biri hata yaparsa diğeri ona hatırlatabilsin. Şahitler çağırıldıklarında şahitlik yapmayı reddetmesinler. Küçük olsun büyük olsun, her anlaşma maddesini vade tarihi ile birlikte yazmaya üşenmeyiniz. Bu, Allah nazarında daha âdil, kanıtlanma açısından daha güvenilir ve sizi şüpheye düşmekten alıkoymakta daha uygun olandır. Ama eğer birbirinize doğrudan doğruya devredeceğiniz hazır mallar ile ilgili ise, onu yazmamanızda bir mahzur yoktur. Birbirinizle alışveriş yapacağınız zaman bir şahit bulundurunuz, ancak ne yazıcı ne de şahit bir zarara uğramasın; eğer onlara zarar verici bir iş yaparsanız unutmayınız ki, bu, sizin için günahkârca bir davranış olacaktır. Allah`a karşı sorumluluğunuzun bilincinde olunuz, çünkü sizi eğiten Allah`tır ve Allah, her şeyin tüm bilgisine sahiptir."},{"n":283,"t":"Eğer seyahatte iseniz ve bir yazıcı/noter bulamazsanız, alınmış taahhütler ile yetinilebilir. Ancak birbirinize güveniyorsanız, kendisine güven duyulan, bu güvene uygun davransın ve Rabbine karşı sorumluluğunun bilincinde olsun. Şahit olduğunuz şeyi gizlemeyiniz; zira onu gizleyen, kalben vebal altındadır. Allah yaptığınız her şeyin bilgisine sahiptir."},{"n":284,"t":"Göklerdeki ve yerdeki her şey Allah`a aittir. İçinizdekileri açığa vursanız da gizleseniz de Allah ondan dolayı sizi hesaba çekecektir ve sonra O, istediğini affedecek, istediğini cezalandıracaktır. Zira Allah her şeye gücü yetendir."},{"n":285,"t":"Peygamber ve onunla birlikte olan müminler, Rabbi tarafından ona indirilene inandılar. Hepsi Allah`a, meleklerine, kitaplarına ve peygamberlerine inandılar. O`nun peygamberleri arasında hiçbir ayırım yapmıyoruz ve “İşittik ve itaat ettik. Bizi bağışla ey Rabbimiz, zira bütün yolculukların varış yeri sensin” derler."},{"n":286,"t":"Allah hiç kimseye taşıyabileceğinden daha fazlasını yüklemez. Kişinin yaptığı her iyilik kendi lehinedir, her kötülük de kendi aleyhine. Ey Rabbimiz! Unutur veya bilmeden hata yaparsak bizi sorgulama! Ey Rabbimiz! Bizden öncekilere yüklediğin gibi bize de ağır yükler yükleme! Ey Rabbimiz! Güç yetiremeyeceğimiz yükleri bize taşıtma! Günahlarımızı affet, bizi bağışla ve bize merhamet et. Sen yüce mevlamızsın, hakikatı inkâr eden topluma karşı bize yardım et!"}],[{"n":1,"t":"Elif, lâm, mîm."},{"n":2,"t":"Allah, kendinden başka tanrı olmayan, sonsuza kadar diri, hayatın ve varlığın kaynağı ve dayanağı, her şeyi hükmüne, iradesine bağlı kılan yaratıcıdır!"},{"n":"3-4","t":"Geçmişte vahyedilen vahiyleri tasdik eden bu ilâhî kelamı sana safha safha indiren O`dur. Geçmişte insanlığa yol gösterici olarak yine Tevrat`ı ve İncil`i de O indirmişti. Doğru ile yanlışı birbirinden ayırt etmeye yarayan gerçeklik bilgisini de. Allah`ın âyetlerini inkâra şartlanmış olanlara gelince, onları acı bir azap beklemektedir; zira Allah kudret sahibidir, kötülüğü cezalandırandır."},{"n":5,"t":"Yerde ve gökte hiçbir şey Allah`a gizli değildir."},{"n":6,"t":"Rahimlerde size istediği şekli veren O`dur. O`ndan başka ilâh yoktur. O kudret ve hikmet sahibidir."},{"n":7,"t":"Sana kitabı indiren O`dur. Onun bazı âyetleri muhkem/anlamları tam bilinen olduğundan kitabın esasını teşkil ederler; diğerleri de müteşâbihtir/araştırılarak manaları bilinecek olan tabiat kanunlarıdır. Kalplerinde eğrilik olanlar, fitne çıkarmak ve onu açıklamak için ondaki müteşâbih âyetlerin peşine düşerler. Halbuki onun açıklamasını ancak Allah ve “ona inandık, hepsi Rabbimiz tarafındandır” diyen ilimde yüksek payeye erişenler bilir. Ancak akıl sahipleri düşünüp anlar."},{"n":8,"t":"Ey Rabbimiz! Bizi doğru yola ilettikten sonra, kalplerimizi haktan bir daha saptırma ve bize rahmetini bağışla, gerçek lütuf sahibi sensin."},{"n":9,"t":"Rabbimiz! Geleceğinde şüphe olmayan bir günde, insanları mutlaka toplayacak olan sensin. Allah, asla sözünden dönmez."},{"n":10,"t":"İnkâr edenlere gelince, ne malları ne de çocukları Allah`a karşı onlara bir fayda sağlayacaktır. İşte onlar ateşin yakıtı olanlardır."},{"n":11,"t":"İnkârcıların yolu Firavun hanedanının ve onlardan öncekilerin tuttuğu yola benzer. Onlar bizim âyetlerimizi yalanladılar; Allah da kendilerini günahları yüzünden yakalayıverdi. Allah`ın cezası çok şiddetlidir."},{"n":12,"t":"“Yakında mağlup olacaksınız ve cehenneme sürüleceksiniz. Orası kalınacak ne kötü bir yerdir!”"},{"n":13,"t":"Savaşta/Bedir`de karşı karşıya gelen iki orduda sizin için bir işaret vardır. Ordunun biri Allah için savaşırken, diğeri O`nu inkâr ediyordu. Gözleriyle diğer tarafı kendilerinin iki misli gördüler. Ama Allah, dilediğini yardımıyla güçlendirir. Elbette bunda basiret/aydınlık sahipleri için bir ibret vardır."},{"n":14,"t":"Kadınlara, çocuklara, altın ve gümüş cinsinden birikmiş hazinelere, soylu atlara, sığırlara ve arazilere yönelik dünyevî zevkler insanoğlu için çekici kılınmıştır. Bütün bu zevkler bu dünya hayatında tadılabilir; ama mutlu son, Allah katında olanıdır."},{"n":15,"t":"“Size o dünyevî zevklerden daha hayırlı olan şeyleri haber vereyim mi? Takvâ sahipleri için Rableri katında, içinden ırmaklar akan, süreli kalacakları cennetler, tertemiz eşler ve Allah`ın hoşnutluğu vardır. Allah kullarını çok iyi görür.”"},{"n":"16-17","t":"Allah, “Ey Rabbimiz! Sana inanıyoruz, bizi affet, günahlarımızı bağışla ve bizi ateşin azabından koru” diyenlerin, zorluklara sabredenlerin ve sözlerini tutanların, Rablerine yürekten bağlı olanların, servetlerini Allah yolunda harcayanların ve seherlerde bütün kalpleriyle af dileyenlerin kalplerindeki her şeyi görür."},{"n":18,"t":"Allah ile melekler, hak ve adaleti gözeten ilim sahipleri, O`ndan başka tanrı olmadığına şahittir. O`ndan başka tanrı yoktur, kudret ve hikmet sahibidir."},{"n":19,"t":"Allah katında din İslâm`dır. Kitap verilenler, kendilerine ilim geldikten sonra, aralarındaki kıskançlık yüzünden ayrılığa düştüler. Allah`ın âyetlerini inkâr edenler bilmelidirler ki, Allah`ın hesabı çok çabuktur."},{"n":20,"t":"“Siz kendinizi O`na teslim ettiniz mi?” Eğer O`na teslim olurlarsa muhakkak doğru yol üzerindedirler; ama yüz çevirirlerse unutma ki, senin görevin sadece mesajı iletmektir; zira Allah, kullarını çok iyi görmektedir."},{"n":21,"t":"Allah`ın âyetlerini inkâr edenlere, peygamberleri haksız yere öldürenlere ve adaleti emreden insanların canına kıyanlara gelince; onlara acıklı azabı bildir."},{"n":22,"t":"İşte onlar, dünyada ve âhirette çabaları boşa giden kimselerdir. Onların hiçbir yardımcısı da yoktur."},{"n":23,"t":"Kendilerine kitaptan bir pay verilenleri görmedin mi? Aralarında hakem olmak için Allah`ın kitabına çağırılıyorlar da, sonra onlardan bir kısmı dönüp yüz çeviriyor."},{"n":24,"t":"Onların bu tutumları, “Bize ateş, sadece sayılı günlerde dokunacaktır” demelerinin bir sonucudur. Dinlerinde uydurdukları yalanlar onları yanıltmıştır."},{"n":25,"t":"O halde, geleceğinde şüphe olmayan güne tanıklık etmeleri için hepsini bir araya topladığımız, her insana yaptıklarının karşılığının tamamen ödeneceği ve kimseye haksızlık yapılmayacağı zaman, onların hali ne olacak?"},{"n":26,"t":"“Ey mutlak egemenlik sahibi Allahım! Sen egemenliği dilediğine verirsin, dilediğinden alırsın; dilediğini yüceltirsin, dilediğini alçaltırsın. Bütün iyilikler senin elindedir. Doğrusu, senin her şeye gücün yeter."},{"n":27,"t":"Gündüzü kısaltarak geceyi uzatır ve geceyi kısaltarak gündüzü uzatırsın. Ölüden diri ve diriden ölü çıkarırsın; dilediğine her türlü hesabın üstünde rızık bağışlarsın.”"},{"n":28,"t":"Müminler, müminleri bırakıp kâfirleri dost edinmesinler; çünkü kendinizi onlardan korumak için bu yola başvurmanız hariç, kim bunu yaparsa, Allah ile bütün bağını koparmış olur. Ancak Allah, kendisine karşı dikkatli olmanız konusunda sizi uyarıyor; çünkü dönüş Allah`adır."},{"n":29,"t":"Kalplerinizdekini gizleseniz de, açığa vursanız da Allah onu bilir. Zira O, göklerdeki ve yeryüzündeki her şeyi bilir; Allah`ın her şeye gücü yeter."},{"n":30,"t":"Herkes, yaptığı iyilik ve kötülükleri karşısında hazır bulacağı günde, kötülükleriyle kendisi arasında uzun bir mesafe bulunmasını isteyecektir. Allah kendisine karşı sizi sakındırıyor. Allah, kullarına karşı çok şefkatlidir."},{"n":31,"t":"“Eğer Allah`ı seviyorsanız bana uyunuz ki, Allah da sizi sevsin ve günahlarınızı bağışlasın. Allah çok bağışlayıcıdır; merhamet sahibidir.”"},{"n":32,"t":"“Allah`a ve Peygamber`e itaat ediniz.” Eğer yüz çevirirlerse, bilsinler ki Allah, kâfirleri sevmez."},{"n":33,"t":"Şüphesiz Allah, Âdem’i, Nûh’u, İbrahim ailesini ve İmrân ailesini âlemler üzerine seçkin kıldı."},{"n":34,"t":"(Onlar) zürriyet olarak birbirinden gelmiş birer nesildir. Allah, en iyi işitendir, en iyi bilendir."},{"n":35,"t":"“Ey Rabbim! Karnımdaki çocuğu hür/erkek bir insan olarak sırf sana adıyorum. Adağımı kabul buyur. Şüphesiz hakkıyla işiten ve bilen sensin.”"},{"n":36,"t":"“Ey Rabbim! Bir kız çocuğu doğurdum. Ona Meryem ismini verdim. Lanetlenmiş şeytana karşı onu ve soyunu korumanı diliyorum.”"},{"n":37,"t":"“Ey Meryem! Bunlar sana nereden geliyor?” Meryem, “Bunlar Allah`tandır, Allah dilediğine hesapsız rızık bağışlar” diye cevap verirdi."},{"n":38,"t":"“Ey Rabbim! Tarafından bana hayırlı bir nesil bağışla; zira sen, her yakarışı duyarsın.”"},{"n":39,"t":"“Allah sana, kendi katından bir sözün gerçekleştiğini doğrulayacak, efendi, iffetli, dürüst ve erdemli bir peygamber olacak olan Yahyâ`yı müjdeliyor.”"},{"n":40,"t":"“İşte böyledir; Allah dilediğini yapar.”"},{"n":41,"t":"“Senin için alâmet, insanlara üç gün -işaretten başka- söz söylememendir. Ayrıca Rabbini çok an, sabah akşam tesbih et!”"},{"n":42,"t":"O zaman melekler, “Ey Meryem!” dediler, “Allah seni seçti ve tertemiz kıldı; seni bütün dünya kadınlarının üstünde bir konuma çıkardı.”"},{"n":43,"t":"“Ey Meryem! Rabbine huşû ile bağlan, secdeye kapan ve rükû edenlerle birlikte rükû et!”"},{"n":44,"t":"Şimdi sana vahyettiğimiz şey, gayb haberlerindendir. Zira, hangisinin Meryem`in hâmisi olacağını kura ile belirlediklerinde sen onlarla birlikte değildin ve birbirleriyle çekişirlerken de yanlarında yoktun."},{"n":45,"t":"“Ey Meryem! Allah sana kendisinden bir kelimeyi müjdeliyor. Adı, Meryem oğlu Mesîh İsâ`dır; dünyada da, âhirette de itibarlı ve Allah`ın kendisine yakın kıldıklarındandır.”"},{"n":46,"t":"O, insanlarla hem beşikte iken, hem de yetişkin bir adam olarak konuşacak; dürüst ve erdemli kişilerden olacak."},{"n":47,"t":"“İşte öyle, Allah dilediğini yaratır, bir şeyin olmasını istediğinde sadece ‘ol` der ve o şey hemen oluşmaya başlar.”"},{"n":48,"t":"Allah ona okuma-yazmayı, hikmeti, Tevrat`ı ve İncil`i öğretecek."},{"n":49,"t":"“Size Rabbinizden bir mucize getirdim; size çamurdan bir kuş sûreti yapar, ona üflerim ve Allah`ın izniyle o, kuş oluverir. Yine Allah`ın izniyle körü ve alacalıyı iyileştirir, ölüleri diriltirim. Ayrıca evlerinizde ne yiyip ne biriktirdiğinizi size haber veririm. Eğer inanan kimselerseniz bunda sizin için bir mesaj vardır.”"},{"n":50,"t":"“Benden önce gelen Tevrat`ı doğrulayıcı olarak ve size haram kılınan bazı şeyleri helâl kılmak için gönderildim. Size Rabbinizden bir âyet getirdim. O halde Allah`tan sakının, bana da itaat edin.”"},{"n":51,"t":"“Şüphesiz Allah, benim de Rabbim, sizin de Rabbinizdir. Öyleyse O`na kulluk edin. Bu doğru bir yoldur.”"},{"n":52,"t":"İsâ, onların hakikati inkâr ettiklerinin farkına varınca, “Allah yolunda bana yardımcı olacaklar kimlerdir?” diye sordu. Havârîler, “Biz, Allah yolunun yardımcılarıyız; Allah`a inandık, şâhit ol ki biz Müslümanlarız” cevabını verdiler."},{"n":53,"t":"“Ey Rabbimiz! İndirdiğine inandık ve peygambere uyduk. Şimdi bizi şâhitlerden yaz” dediler."},{"n":54,"t":"İnanmayanlar İsâ`ya tuzak kurdular; ama Allah onların tuzaklarını boşa çıkardı. Çünkü Allah, tuzak kuranların tümünün üstündedir."},{"n":55,"t":"“Ey İsâ! Seni vefat ettireceğim, seni katıma yükselteceğim, seni inkâr edenlerden arındıracağım ve sana uyanları kıyamete kadar kâfirlerden üstün kılacağım. Sonra dönüşünüz bana olacak. İşte o zaman, ayrılığa düştüğünüz şeyler hakkında aranızda ben hükmedeceğim.”"},{"n":56,"t":"Kâfirlere gelince, onlara bu dünyada da, âhirette de şiddetli bir azap çektireceğim ve onlar için yardım edecek kimse de yoktur."},{"n":57,"t":"İman edip yararlı işler yapanlara Allah ödüllerini tam olarak verecektir. Allah, zâlimleri sevmez."},{"n":58,"t":"Bu bildirdiklerimizi, sana âyetlerden ve hikmet dolu Kur`ân`dan okuyoruz."},{"n":59,"t":"Allah katında İsâ`nın durumu, Âdem`in durumu gibidir. Allah Âdem`i topraktan yarattı; sonra ona, “ol” dedi ve o da oluşmaya başladı."},{"n":60,"t":"Gerçek, Rabbinden gelendir. Öyle ise şüphecilerden olma!"},{"n":61,"t":"“Geliniz, oğullarımızı ve oğullarınızı, kadınlarımızı ve kadınlarınızı, kendimizi ve kendinizi çağıralım, sonra da lanetleşelim; Allah`ın lanetinin yalancılara olmasını dileyelim.”"},{"n":62,"t":"İşte bu, elbette en doğru haberin beyanıdır ve Allah`tan başka bir tanrı yoktur. Muhakkak ki, Allah çok güçlüdür; hikmet sahibidir."},{"n":63,"t":"Eğer haktan yüz çevirirlerse, şüphesiz ki Allah bozguncuları çok iyi bilendir."},{"n":64,"t":"“Şâhit olun, biz Müslümanlarız.”"},{"n":65,"t":"Ey kitap ehli! İbrâhim hakkında niçin tartışıyorsunuz? Halbuki Tevrat ve İncil, kesinlikle ondan sonra indirildi. Siz hiç aklınızı kullanmıyor musunuz?"},{"n":66,"t":"İşte siz böyle kimselersiniz! Haydi bilginiz olan şeyler hakkında tartıştınız; fakat bilgi sahibi olmadığınız konuda niçin tartışıyorsunuz? Halbuki Allah her şeyi bilir, ama siz bilemezsiniz."},{"n":67,"t":"İbrâhim, ne bir Yahûdi, ne de bir Hıristiyan idi; ama kendini Allah`a teslim ederek her türlü bâtıldan yüz çevirmiş bir Müslümandı. Müşriklerden de değildi."},{"n":68,"t":"Muhakkak ki İbrâhim`e en yakın olanlar, ona uyanlar ile şu Peygamber ve müminlerdir. Allah ise iman edenlerin dostu ve koruyucusudur."},{"n":69,"t":"Kitap ehlinin bir kısmı sizi saptırmak istedi; oysa onlar ancak kendilerini saptırırlar da bunun farkına varamazlar."},{"n":70,"t":"Ey kitap ehli! Bizzat kendinizin şâhit olduğunuz Allah`ın mesajlarını niçin inkâr edersiniz?"},{"n":71,"t":"Ey kitap ehli! Niçin hak ile bâtılı karıştırıyor ve bile bile hakkı gizliyorsunuz?"},{"n":72,"t":"“Müminlere indirilmiş olana sabahleyin inanıp akşamleyin inkâr edin. Belki onlar da dinlerinden dönerler.”"},{"n":73,"t":"“Lütuf Allah`ın kudretindedir, onu dilediğine verir. Allah`ın lütfu geniştir. O her şeyi bilendir.”"},{"n":74,"t":"“Rahmetini dilediğine tahsis eder. Allah üstün lütuf sahibidir.”"},{"n":75,"t":"Kitap ehlinden öylesi vardır ki, ona yüklerle emanet bıraksan onu sana öder. Onlardan öylesi de vardır ki ona bir dinar versen, devamlı olarak başına dikilmedikçe onu sana ödemez. Onlar, “Cahillere karşı bize bir sorumluluk yoktur” dedikleri için böyle yapıyorlar ve Allah`a karşı bile bile yalan söylüyorlar."},{"n":76,"t":"Hayır, gerçek onların dediği gibi değil; her kim sözünü yerine getirir ve kötülükten sakınırsa, bilsin ki Allah sakınanları sever."},{"n":77,"t":"Allah`a karşı taahhütlerini ve yeminlerini ufak bir kazanç karşılığında değiştirenler var ya, onlar âhiretin nimetlerinden asla nasiplenmeyeceklerdir; Allah kıyamet günü ne onlarla konuşacak, ne yüzlerine bakacak/ilgilenecek, ne de onları günahlarından arındıracaktır; onları acıklı bir azap beklemektedir."},{"n":78,"t":"Onlardan bir grup var ki, kitapta olmayan bir şeyi siz kitaptan sanasınız diye, dilleriyle kitabı çarpıtırlar ve Allah`tan olmadığı halde, “Bu, Allah katındandır!” derler, böylece bile bile Allah hakkında yalanlar uydururlar."},{"n":79,"t":"Allah`ın kendisine kitap, hikmet ve peygamberlik verdiği bir kimsenin, insanlara “Allah`ı bırakıp bana kul olun!” demesi mümkün değildir. Aksine “İlâhî kelâmın bilgisini öğreterek ve onu derinlemesine inceleyerek Allah adamları olun” der."},{"n":80,"t":"O, melekleri ve peygamberleri tanrı edinmenizi emretmez. Zaten, kendinizi Allah`a teslim ettikten sonra, hiç sizi hakikati inkâra davet eder mi?"},{"n":81,"t":"Allah, peygamberlerden şöyle söz almış ve “Bakın size kitap ve hikmet verdim, şimdi yanınızda bulunanı doğrulayıcı bir peygamber geldiğinde ona mutlaka inanacak ve yardım edeceksiniz. Bunu kabul ettiniz mi? Bu hususta ağır ahdimi üzerinize aldınız mı?” demişti. Onlar da, “Kabul ettik” dediler. “O halde tanık olunuz, ben de sizinle beraber tanık olanlardanım” dedi."},{"n":82,"t":"Artık kim bundan sonra dönerse işte onlar fâsıklardır/yoldan çıkanlardır."},{"n":83,"t":"Onlar Allah`ın dininden başkasını mı arıyorlar? Oysa göklerdeki ve yerdekilerin hepsi, ister istemez O`na teslim olmuştur ve O`na döndürüleceklerdir."},{"n":84,"t":"“Biz Allah`a, bize indirilene, İbrâhim`e, İsmail`e, İshak`a, Yakûb`a ve onun neslinden gelenlere indirilene, Rabbleri tarafından Mûsâ`ya, İsâ`ya ve diğer bütün peygamberlere bahşedilenlere inanırız, onlar arasında hiçbir ayırım yapmayız. Kendimizi Allah`a teslim ederiz."},{"n":85,"t":"Kim İslâm`dan başka bir din ararsa, bu kendisinden asla kabul edilmeyecek ve o, âhirette kaybedenlerden olacaktır."},{"n":86,"t":"İman edip Peygamberin hak olduğuna şâhit olduktan ve hakikatin bütün kanıtları kendilerine geldikten sonra hakikati inkâr etmeyi seçen bir halkı, Allah nasıl doğru yola ulaştırır? Allah, böyle zâlimler topluluğunu doğru yola iletmez."},{"n":87,"t":"İşte onların cezası, Allah`ın, meleklerin ve bütün insanlığın lanetine uğramalarıdır."},{"n":88,"t":"Onlar bu halde kalacaklar; ne azapları hafifletilecek ne de onlara bir mühlet tanınacak."},{"n":89,"t":"Ancak, daha sonra tövbe edip kendilerini düzeltenler hariç tutulacaktır; zira Allah çok affedicidir; merhamet sahibidir."},{"n":90,"t":"İnandıktan sonra hakikati inkâra sapıp inkârcılıkta daha da ileri gidenlerin tövbeleri asla kabul edilmeyecektir. İşte onlar sapıkların ta kendileridirler."},{"n":91,"t":"Gerçekten inkâr edip kâfir olarak ölenler var ya, dünya dolusu altın verecek olsa dahi, onların hiçbirinden fidye kabul edilmeyecektir. Onlar için acı bir azap vardır, hiç yardımcıları da olmayacaktır."},{"n":92,"t":"Sevdiğiniz şeylerden başkaları için harcamadıkça iyiye ulaşamazsınız; her ne harcarsanız şüphesiz Allah ondan tamamıyla haberdardır."},{"n":93,"t":"“Eğer söylediklerinizde samimi iseniz Tevrat`ı getirin de okuyun.”"},{"n":94,"t":"Artık bundan sonra her kim Allah hakkında yalan uydurursa işte onlar zâlimlerdir."},{"n":95,"t":"“Allah doğruyu söylemektedir. O halde, bâtıl olan her şeyden yüz çeviren ve Allah`ın yanı sıra hiçbir şeye ilâhlık yakıştırmayan İbrâhim`in inanç sistemine uyun.”"},{"n":96,"t":"Şüphesiz, âlemlere bereket ve hidayet kaynağı olarak insanlar için kurulan ilk mabet, ev Mekke`dekidir."},{"n":97,"t":"Orada apaçık işaretler vardır ve İbrâhim`in makamı oradadır. Oraya giren güvende olur. Oraya gitmeye gücü yetenlerin Beyt`i haccetmesi, Allah`ın insanlar üzerinde bir hakkıdır. Hakikati inkâr edenlere gelince, bilsinler ki Allah, yarattığı âlemlerden bağımsızdır; her bakımdan kendine yeterlidir."},{"n":98,"t":"“Ey kitap ehli! Allah, yaptığınız her şeye şâhit iken niçin O`nun âyetlerini inkâr ediyorsunuz?”"},{"n":99,"t":"“Ey kitap ehli! Gerçeği görüp bildiğiniz halde, Allah`ın yolunu niçin eğri göstermeye yeltenerek inananları Allah yolundan çevirmeye çalışıyorsunuz? Allah yaptıklarınızdan habersiz değildir.”"},{"n":100,"t":"Ey iman edenler! Kendilerine kitap verilenlerden bir gruba uyarsanız, imanınızdan sonra sizi yeniden inkârcılığa sevk ederler."},{"n":101,"t":"Size Allah`ın âyetleri okunurken, üstelik Allah`ın Peygamberi de aranızda iken nasıl inkâra saparsınız? Her kim Allah`a bağlanırsa, kesinlikle doğru yola iletilmiştir."},{"n":102,"t":"Ey iman edenler! Allah`a karşı sorumluluğunuzun hakkıyla bilincinde olunuz ve ancak Müslümanlar olarak can veriniz."},{"n":103,"t":"Topluca Allah`ın ipine sımsıkı sarılınız, ayrılığa düşmeyiniz, Allah`ın size olan nimetini hatırlayınız; hani birbirinize düşmandınız da, O kalplerinizi kaynaştırdı ve O`nun lütfu ile kardeş oldunuz. Ateşli bir çukurun kenarındayken, ondan sizi O kurtardı. İşte Allah, âyetlerini size böyle açıklıyor ki doğru yolu bulasınız."},{"n":104,"t":"Sizden hayra çağıran, iyiliği emredip kötülüğü meneden bir grup bulunsun. İşte onlar kurtuluşa erenlerdir."},{"n":105,"t":"Hakikatin bütün kanıtları kendilerine geldikten sonra ihtilafa düşüp parçalananlar gibi olmayınız. İşte bunlar için feci bir azap vardır."},{"n":106,"t":"O gün bazı yüzler ağarır, bazı yüzler kararır. Yüzleri kararanlara, “İnanmanızdan sonra inkâr mı ettiniz? O halde inkâr etmenize karşılık azabı tadınız!” denilecek."},{"n":107,"t":"Yüzleri ağaranlar ise Allah`ın rahmeti içindedirler. Orada uzun süreli kalacaklardır."},{"n":108,"t":"İşte bunlar Allah`ın, sana hak olarak okuduğumuz âyetleridir. Allah hiçbir kimseye haksızlık etmek istemez."},{"n":109,"t":"Göklerde ve yerde ne varsa Allah`ındır. Bütün işler Allah`a döndürülür."},{"n":110,"t":"Siz insanlığın iyiliği için yetiştirilmiş hayırlı bir topluluksunuz. İyiliği emreder, kötülükten sakındırırsınız ve Allah`a inanırsınız. Eğer kitap ehli de inansaydı, elbette bu, kendileri için çok iyi olurdu. İçlerinden iman edenler var, fakat çoğu yoldan çıkmışlardır."},{"n":111,"t":"Yoldan çıkan kitap ehli, size incitmekten başka bir zarar veremezler. Sizinle savaşa girecek olsalar, size arkalarını dönüp kaçarlar. Sonra kendilerine yardım da edilmez."},{"n":112,"t":"Onlar Allah`a ve insanlara karşı taahhütlerine bağlanmadıkları sürece, nerede bulunurlarsa bulunsunlar zillete düçar olurlar; çünkü Allah`ın gazabına uğramış ve aşağılanmaya mahkûm edilmişlerdir. Bütün bunlar başlarına geldi; çünkü Allah`ın âyetlerini inkâr etmekte ve peygamberleri haksız yere öldürmekte ısrar ettiler. Bütün bunlar gerçekleşti; çünkü Allah`a isyanda bulundular ve hakkın sınırlarını inatla ihlal ettiler."},{"n":113,"t":"Kitap ehlinin hepsi aynı değildir. Onların arasında, gece boyunca Allah`ın âyetlerini okuyan ve secdeye kapanan dosdoğru insanlar da vardır."},{"n":114,"t":"Onlar, Allah`a ve âhiret gününe inanırlar; doğru olanı emreder, eğri olandan alıkoyarlar ve hayırlı işlerde birbirleriyle yarışırlar. İşte bunlar erdemli insanlardandır."},{"n":115,"t":"Onların yaptığı hiçbir iyilik karşılıksız bırakılmayacaktır; çünkü Allah, takvâ sahiplerini iyi bilir."},{"n":116,"t":"İnkâr edenlere gelince, onların malları da evlatları da Allah`ın azabından korunmak için kendilerine hiçbir fayda sağlamayacaktır. İşte onlar cehennemliklerdir; onlar orada uzun süreli kalacaklardır."},{"n":117,"t":"Onların bu dünya hayatında yapmakta oldukları harcamaların durumu, kendi kendilerine zulmeden bir halkın ekinlerine musallat olan ve onu mahveden dondurucu bir rüzgâra benzer. Onlara haksızlık yapan Allah değildir, fakat onlar kendi kendilerine haksızlık yapıyorlar."},{"n":118,"t":"Ey iman edenler! Sizden olmayan kişileri sırdaş edinmeyiniz. Onlar sizi yoldan çıkarmak için ellerinden gelen hiçbir çabayı esirgemezler ve sizi sıkıntıda görmekten hoşlanırlar. Şiddetli öfke ağızlarından taşmaktadır; kalplerinde sakladıkları ise daha da kötüdür. Aklınızı kullanırsanız, size âyetleri açıkladık."},{"n":119,"t":"“Öfkenizle kahrolun!” Allah, sinelerdekini hakkıyla bilmektedir."},{"n":120,"t":"Eğer bir iyilikle karşılaşırsanız bu onları üzer; başınıza bir kötülük gelince de memnun olurlar. Ama eğer zorluklara karşı sabreder ve samimi davranırsanız, ruh olgunluğu gösterirseniz, onların hileleri size hiçbir zaman zarar veremez. Zira Allah onların bütün yaptıklarını kuşatıcıdır."},{"n":121,"t":"Hatırla o günü, ey Peygamber, inananları savaş düzenine sokmak için sabah erkenden evinden çıkmıştın. Allah her şeyi işitendir; her şeyi bilendir."},{"n":122,"t":"İçinizden iki grubun paniğe kapıldığını da hatırla. Halbuki Allah onlara yakındı. Müminler yalnız Allah`a güven duymalıdır."},{"n":123,"t":"Andolsun, sizler güçsüz olduğunuz halde, Allah size Bedir`de yardım etmişti. Öyleyse Allah`tan sakının ki, O`na şükretmiş olasınız."},{"n":124,"t":"“Rabbinizin gönderilmiş üçbin melekle size yardım etmesi sizin için yeterli değil mi?”"},{"n":125,"t":"Hayır! Ama eğer sıkıntıya göğüs gerer ve Allah`tan sakınırsanız, düşman aniden size saldırdığında, Rabbiniz akın akın gelen beş bin melekle size yardım edecektir."},{"n":126,"t":"Allah bunu, size sadece bir müjde olsun ve böylece kalpleriniz onunla rahatlasın diye yaptı. Zafer, yalnızca mutlak güç ve hikmet sahibi Allah katındandır."},{"n":127,"t":"Allah, kâfirlerden bir kısmının kökünü kessin veya onları perişan etsin de, arzularına ulaşamadan hayal kırıklığı içinde dönüp gitsinler."},{"n":128,"t":"Senin bu hususta yapacağın bir şey yok. Allah onları ya bağışlayacak, yahut cezalandıracaktır; çünkü onlar gerçekten zâlimlerdir."},{"n":129,"t":"Oysa göklerde ve yeryüzünde olan her şey Allah`ındır. O, dilediğini affeder, dilediğini cezalandırır. Allah affedicidir; merhametlidir."},{"n":130,"t":"Ey iman edenler! Faizi kat kat arttırarak yemeyiniz. Allah`tan sakınınız ki kurtuluşa eresiniz."},{"n":131,"t":"Kâfirler için hazırlanan ateşten sakınınız!"},{"n":132,"t":"Allah`a ve Peygamber`ine itaat ediniz ki rahmete kavuşturulasınız."},{"n":133,"t":"Rabbinizin affına mazhar olmak ve sakınanlar için hazırlanan gökler ve yer kadar geniş bir cennete ulaşmak için birbirinizle yarışınız."},{"n":134,"t":"Muttakîler hem bolluk hem de darlık anlarında infak ederler; öfkelerini yutarlar ve insanları affederler. Allah iyilik edenleri sever."},{"n":135,"t":"Onlar, utanç verici bir iş yaptıkları veya kendi kendilerine haksızlık ettikleri zaman Allah`ı anar ve günahlarının affı için yalvarırlar. Zaten günahları Allah`tan başka kim affedebilir? Bunlar yaptıkları fenalık üzerinde bile bile ısrar etmezler."},{"n":136,"t":"Bunların görecekleri karşılık, Rabblerinden bağışlanma ve altından ırmaklar akan cennetlerdir. Onlar orada süreli kalırlar. Hayırlı iş yapanlar için bu ne güzel bir ödüldür!"},{"n":137,"t":"Sizden önce nice milletlerin çöküş olguları gelip geçti. Öyleyse yeryüzünde dolaşınız ve inkâr edenlerin sonunun ne olduğunu görünüz."},{"n":138,"t":"Bu, bütün insanlara açık bir ders ve takvâ sahipleri için bir rehber ve bir öğüttür."},{"n":139,"t":"Gevşeklik göstermeyiniz; üzüntüye kapılmayınız. Eğer gerçekten inanıyorsanız, mutlaka siz en üstün olursunuz."},{"n":140,"t":"Eğer başınıza bir bela gelirse biliniz ki benzer bir belaya başka insanlar da uğramıştır; zira böyle iyi ve kötü günleri insanlara sırayla paylaştırırız. Bu, Allah`ın iman edenleri seçip ayırması ve aranızdan hakikate şâhitlik yapanları seçmesi içindir; çünkü Allah, zâlimleri asla sevmez."},{"n":141,"t":"Bir de Allah, iman edenleri her türlü boş ve yararsız şeylerden arındırmak ve inkârcıları helâk etmek ister."},{"n":142,"t":"Yoksa Allah, içinizden cihad edenleri belli etmeden, sabredenleri ortaya çıkarmadan, cennete gireceğinizi mi sandınız?"},{"n":143,"t":"Andolsun ki siz ölümle yüz yüze gelmeden önce, onu temenni ederdiniz. İşte şimdi onu kendi gözlerinizle görmektesiniz."},{"n":144,"t":"Muhammed sadece bir peygamberdir; ondan önce de peygamberler gelip geçti. Öyleyse, o ölür yahut öldürülürse, topuklarınız üzerinde gerisin geri mi döneceksiniz? Kim topukları üzere geri dönerse Allah`a zarar veremez; fakat şükredenlerin ödülünü Allah verir."},{"n":145,"t":"Hiç kimse, tayin edilmiş belli bir vadeden önce, Allah`ın izni olmadan ölmez. Kim bu dünyanın nimetlerini arzularsa kendisine ondan vereceğiz; kim de âhiretin nimetlerini arzularsa kendisine ondan vereceğiz ve şükredenleri ödüllendireceğiz."},{"n":146,"t":"Nice peygamberler vardır ki, Allah`ın pek çok sevgili kulu onlarla birlikte savaşmışlar, Allah yolunda başlarına gelenden zerre kadar yılmamış, gevşememiş, boyun eğmemişlerdir. Allah sabredenleri sever."},{"n":147,"t":"“Ey Rabbimiz! Günahlarımızı ve işimizdeki taşkınlıklarımızı bağışla; ayaklarımızı sabit kıl; kâfirler topluluğuna karşı bizi muzaffer kıl!”"},{"n":148,"t":"Allah da onlara dünya nimetini, âhiret sevabının güzelliğini verdi. Allah iyi davrananları sever."},{"n":149,"t":"Ey iman edenler! Kâfirlere itaat ederseniz sizi topuklarınızın üzerinde gerisin geri döndürürler ve kaybedenlerden olursunuz."},{"n":150,"t":"Hayır, sizin mevlânız Allah`tır ve O, yardımcıların en iyisidir."},{"n":151,"t":"Allah`ın, hakkında hiçbir delil indirmediği şeyleri O`na ortak koşmaları sebebiyle, kâfirlerin kalplerine yakında korku salacağız. Gidecekleri yer de ateştir. Zâlimlerin varacağı yer ne kötüdür!"},{"n":152,"t":"Allah, elbette size verdiği sözü tuttu. O`nun izniyle düşmanlarınızı yok etmek üzereydiniz; ne var ki Allah size arzuladığınız zaferi gösterdikten sonra gevşediniz, peygamberden gelen emre aykırı davrandınız ve itaatsizlik ettiniz. Aranızda sadece bu dünyaya ilgi duyan kimseler olduğu gibi, âhirete gönül verenler de mevcuttu. Bunun üzerine Allah, sizi sınamak için düşmanları yenmenize mani oldu. Ama Allah günahlarınızı bağışladı; zira Allah`ın inananlara lütfu sınırsızdır."},{"n":153,"t":"O vakit siz, uzaklaşıyor ve kimseye bakmıyordunuz. Peygamber arkanızdan sizi çağırıyordu. Bunun üzerine Allah size, gam üstüne gam verdi ki, kaybettiğinize ve uğradığınız felâkete esef etmeyesiniz. Allah bütün yaptıklarınızdan haberdardır."},{"n":154,"t":"“Evlerinizde de kalmış olsaydınız, içinizden ölümü takdir edilmiş olanlar, devrilecekleri/öldürülecekleri yere mutlaka çıkıp giderlerdi.” Bu başınıza gelenlerin hepsi, Allah`ın göğüslerinizde barındırdığınız her şeyi sınaması ve kalplerinizin içini her türlü boş ve yararsız şeylerden arındırması içindir. Zira Allah, insanların sinelerindeki her şeyi bilir."},{"n":155,"t":"Uhud`da iki ordunun karşılaştığı gün, sizi bırakıp gidenleri, sırf işledikleri bazı hatalar yüzünden şeytan tökezletti. Yine de Allah onları affetti. Çünkü Allah çok bağışlayıcıdır, yumuşak davranandır."},{"n":156,"t":"Ey iman edenler! Sakın sefere veya savaşa çıktıktan sonra kardeşleri hakkında, “Bunlar bizim yanımızda kalsalardı ölmezler veya öldürülmezlerdi” diyen kâfirler gibi olmayınız. Allah bunu onların içine yürek yarası yaptı. Allah yaşatır ve öldürür; Allah, bütün yaptıklarınızı bilir."},{"n":157,"t":"Allah yolunda öldürülür veya ölürseniz, şunu biliniz ki, Allah`ın affı ve rahmeti, onların topladıkları bütün şeylerden daha değerlidir."},{"n":158,"t":"Çünkü ölseniz de öldürülseniz de Allah`ın huzurunda toplanacaksınız."},{"n":159,"t":"O zaman Allah`tan bir rahmet olarak onlara yumuşak davrandın! Şâyet sen, kaba ve katı yürekli olsaydın, hiç şüphesiz, etrafından ayrılıp giderlerdi. Öyleyse onları affet; bağışlanmaları için dua et; iş hakkında onlara danış. Kararını verdiğin zaman da artık Allah`a dayanıp güven. Çünkü Allah kendisine dayanıp güvenenleri sever."},{"n":160,"t":"Allah size yardım ederse, hiç kimse sizi yenemez; ama ya O sizi terk ederse, O`ndan başka kim size yardım edebilir? O halde müminler Allah`a güvensinler."},{"n":161,"t":"Bir peygamberin hıyanet etmesi olacak şey değildir. Kim emanete hıyanet ederse, kıyamet günü hainlik ettiği şeyin günahı boynuna asılı olarak gelir. Sonra herkese, asla haksızlığa uğratılmaksızın, kazandığı tastamam verilir."},{"n":162,"t":"Öyleyse, Allah`ın rızasını kazanmak isteyen kişi ile Allah`ın lanetine uğramış ve varış yeri cehennem olan kişi bir midir? Ne kötü bir duraktır o!"},{"n":163,"t":"Onlar Allah katında farklı derecelere sahiptirler; zira Allah, yaptıkları her şeyi görür."},{"n":164,"t":"Andolsun ki içlerinden, kendilerine Allah`ın âyetlerini okuyan, onları arındırıp kitap ve hikmeti öğreten bir peygamber göndermekle Allah, müminlere büyük bir lütufta bulunmuştur. Halbuki daha önce onlar apaçık sapıklık içindeydiler."},{"n":165,"t":"“O sizin eserinizdir. Kuşkusuz Allah, dilediği her şeyi yapmaya kadirdir.”"},{"n":166,"t":"İki ordunun karşılaştığı gün başınıza gelenler Allah`ın izniyle gerçekleşti. Bu, Allah`ın gerçek müminleri belirlemesi içindi."},{"n":167,"t":"Bu savaş, yine münâfıkları ve kendilerine, “Geliniz, Allah yolunda savaşınız yahut müdafaa ediniz” denildiğinde, “Eğer savaşmayı bilseydik elbette arkanızdan gelirdik” diye cevap verenleri ortaya çıkarması içindi. Onlar o gün kalplerinde olmayanı ağızlarıyla söyleyerek, imandan çok inkâra yaklaştılar. Halbuki Allah, gizlemeye çalıştıklarını çok iyi bilmektedir."},{"n":168,"t":"Evlerinde oturup da kardeşleri hakkında “Bize uysalardı öldürülmezlerdi” diyenlere, “Eğer doğru sözlü insanlar iseniz canlarınızı ölümden kurtarınız bakalım” de!"},{"n":169,"t":"Ve Allah yolunda öldürülenleri ölü saymayın! Aksine onlar diridirler; rızıkları Allah katındadır."},{"n":170,"t":"Allah`ın kendi ihsanından vereceğiyle mutlu olarak arkalarından gelecek ve henüz kendilerine katılmamış olan şehit kardeşlerine de hiçbir keder ve korku bulunmayacağı müjdesinin sevincini duyacaklardır."},{"n":171,"t":"Onlar Allah`tan gelecek olan nimet ve keremin, Allah`ın müminlerin ecrini zayi etmeyeceği müjdesinin sevinci içinde olacaklardır."},{"n":172,"t":"Yara aldıktan sonra yine Allah`ın ve Peygamber`in çağrısına uyanlar, özellikle bunların içinden iyilik yapanlar ve takvâ sahibi olanlar için pek büyük ödül vardır."},{"n":173,"t":"Bir kısım insanlar, müminlere, “Düşmanlarınız size karşı asker topladılar, sakının onlardan!” dediklerinde bu, onların imanlarını bir kat daha arttırdı ve “Allah bize yeter. O, ne güzel vekildir!” dediler."},{"n":174,"t":"Bunun üzerine, kendilerine hiçbir fenalık dokunmadan, Allah`ın nimet ve keremiyle geri geldiler. Böylece Allah`ın rızasına uymuş oldular. Allah, büyük kerem sahibidir."},{"n":175,"t":"İşte o şeytan, ancak kendi dostlarını korkutur. Şu halde, eğer iman etmiş kimseler iseniz onlardan korkmayınız, benden korkunuz."},{"n":176,"t":"İnkârda yarışanlar sana kaygı vermesin. Çünkü onlar Allah`a hiçbir zarar veremezler. Allah onlara, inkarda yarıştıklarından dolayı âhiretten yana bir nasip vermek istemiyor. Onlar için çok büyük bir azap vardır."},{"n":177,"t":"Şüphesiz, iman karşılığında inkârı satın alanlar hiçbir sûrette Allah`a zarar veremezler. Onlar için elem verici bir azap vardır."},{"n":178,"t":"Kâfirler sanmasınlar ki kendilerine mühlet vermemiz onların hayrınadır; onlara mühlet vermemiz günahlarını arttırmaları içindir. Onlar için alçaltıcı bir azap vardır."},{"n":179,"t":"Allah, müminleri içinde bulunduğunuz halde bırakacak değildir. O, iyi ile kötüyü ayıracaktır. Allah, size gaybı bildirecek değildir. Fakat Allah, peygamberlerinden dilediğini seçer. O halde Allah ve peygamberlerine inanınız. Eğer inanır ve sakınırsanız size büyük ödül vardır."},{"n":180,"t":"Allah`ın, lütfundan kendilerine verdiklerini infak etmekte cimrilik gösterenler sanmasınlar ki o, kendileri için hayırdır; tersine bu onlar için şerdir. Cimrilik ettikleri şey, kıyamet gününde boyunlarına dolanacaktır. Göklerin ve yerin mirası Allah`ındır. Allah bütün yaptıklarınızdan haberdardır."},{"n":181,"t":"Gerçekten, “Allah fakir, biz ise zenginiz” diyenlerin sözünü andolsun ki Allah işitmiştir. Onların dediklerini, haksız yere peygamberleri öldürmeleriyle birlikte yazacağız ve diyeceğiz ki, “Tadın o yakıcı azabı!"},{"n":182,"t":"“Bu, dünyada iken kendi ellerinizle yapmış olduğunuzun karşılığıdır. Yoksa Allah, kullarına zulmetmez.”"},{"n":183,"t":"“Benden evvel nice peygamberler en açık deliller ile ve sizin söylediklerinizle geldiler. Eğer doğru insanlar iseniz, niçin onları öldürdünüz?”"},{"n":184,"t":"Eğer seni yalancılıkla itham ettilerse gerçekten, senden önce apaçık mucizeler, sahifeler ve aydınlatıcı kitap getiren nice peygamberler de yalancılıkla itham edildi."},{"n":185,"t":"Her can ölümü tadacaktır. Ancak kıyamet günü yaptıklarınızın karşılığı size tastamam verilecektir. Kim cehennemden uzaklaştırılıp cennete konursa o, gerçekten kurtuluşa ermiştir. Zira bu dünya hayatı, aldatıcı bir zevkten başka bir şey değildir."},{"n":186,"t":"Andolsun ki, mallarınızla ve canlarınızla imtihan edileceksiniz; sizden önce kendilerine kitap verilenlerden ve müşriklerden birçok üzücü söz işiteceksiniz. Eğer sabreder ve sakınırsanız biliniz ki bu, azimle sarılınacak bir iştir."},{"n":187,"t":"“Onu insanlara açıklayınız ve hiçbir şey gizlemeyiniz.” Onlar ise bunu kulak ardı ettiler, onu küçük bir kazançla değiştirdiler. Yaptıkları alış veriş ne kadar kötüdür!"},{"n":188,"t":"Sanma ki bu şekilde başardıklarıyla övünen ve yapmadıklarıyla övülmekten hoşlananlar azaptan kurtulabilecekler. Onlar için elem verici bir azap vardır."},{"n":189,"t":"Göklerin ve yerin hükümranlığı Allah`ındır. Allah`ın gücü her şeye yeter."},{"n":190,"t":"Göklerin ve yerin yaratılışında, gece ile gündüzün birbiri ardınca gelip gidişinde aklı selim sahipleri için gerçekten alınacak dersler vardır."},{"n":191,"t":"“Ey Rabbimiz! Sen bunu, boşuna yaratmadın; seni noksan sıfatlardan uzak tutarız. Bizi cehennem azabından koru!”"},{"n":192,"t":"“Ey Rabbimiz! Doğrusu sen, kimi cehenneme koyarsan, artık onu rüsvâ etmişsindir. Zâlimlerin hiç yardımcıları yoktur.”"},{"n":193,"t":"“Ey Rabbimiz! Gerçek şu ki biz, ‘Rabbinize inanın!` diye imana çağıran bir davetçiyi işittik, hemen iman ettik. Artık bizim günahlarımızı bağışla, kötülüklerimizi ört, ruhumuzu iyilerle beraber al!”"},{"n":194,"t":"“Ey Rabbimiz! Bize, peygamberlerin vasıtasıyla vaad ettiklerini de ikram et ve kıyamet gününde bizi rezil etme; şüphesiz sen vaadinden caymazsın.”"},{"n":195,"t":"“Birbirinizden olduğunuz için erkek olsun, kadın olsun benim yolumda çaba gösterenlerden hiç kimsenin çabasını boşa çıkarmayacağım. Onlar ki, hicret ettiler, yurtlarından çıkarıldılar, benim yolumda eziyete uğradılar, çarpıştılar ve öldürüldüler, and olsun, ben de onların kötülüklerini örteceğim ve onları içinden ırmaklar akan cennetlere koyacağım. Bu ödül Allah tarafındandır. Zira ödüllerin en güzeli, Allah katından olanıdır.”"},{"n":196,"t":"İnkâr edenlerin diyar diyar gezmeleri seni aldatmasın."},{"n":197,"t":"O, gelip geçici bir tatminden ibarettir; ama sonunda varacakları yer cehennemdir. O ne kötü bir meskendir!"},{"n":198,"t":"Fakat Rabblerine karşı sorumluluklarının bilincinde olanlar, içinden ırmaklar akan ve içlerinde uzun süre kalacakları cennetlere kavuşacaklardır. Allah`tan ne güzel bir karşılama! Allah katında olan, gerçek erdem sahipleri için en hayırlı olandır."},{"n":199,"t":"Kitap ehlinden öyleleri vardır ki, Allah`a, hem size indirilene, hem de kendilerine indirilene tam bir samimiyetle ve Allah`a boyun eğerek iman ederler. Allah`ın âyetlerini az bir kazanç için satmazlar. Onların ödülü Rabbleri katındadır; çünkü Allah hesabı çabuk olandır."},{"n":200,"t":"Ey iman edenler! Sabrediniz ve birbirinizle sabırda yarışınız, ülkeyi korumada daima uyanık olunuz ve Allah`a karşı gelmekten sakınınız ki zafere ulaşasınız."}],[{"n":1,"t":"Ey insanlar! Sizi tek bir cevherden/nefisten yaratan, ondan da eşini yaratan ve ikisinden birçok erkek ve kadın üretip yayan Rabbinizden sakınınız. Adını kullanarak birbirinizden dilekte bulunduğunuz Allah`tan ve akrabalık haklarına riayetsizlikten de sakınınız. Şüphesiz Allah sizin üzerinizde gözetleyicidir."},{"n":2,"t":"Yetimlere mallarını veriniz; temizi pis olanla değiştirmeyiniz, onların mallarını sizin mallarınıza katarak kendi helâl ve temiz malınızı kirletip yemeyiniz; çünkü bu, büyük bir günahtır."},{"n":3,"t":"Şayet yetimler hakkında adaleti yerine getiremeyeceğinizden korkarsanız, size helâl olan başka kadınlardan ikişer, üçer, dörder alınız. O kadınlar arasında da adaleti sağlayamayacağınızdan korkarsanız, bir tane alınız; yahut ellerinizin altında bulunanlarla yetininiz. Zulüm ve haksızlık etmemeniz için en uygun olan budur."},{"n":4,"t":"Kadınlara mehirlerini hiçbir karşılık beklemeden veriniz; ama eğer onlar, kendi rızâlarıyla bir kısmını size bırakırlarsa, ondan hoşnutluk ve gönül rahatlığıyla faydalanınız."},{"n":5,"t":"Allah`ın geçiminize dayanak kıldığı mallarınızı aklı ermeyenlere vermeyiniz; o mallarla onları besleyiniz, giydiriniz ve onlara güzel söz söyleyiniz."},{"n":6,"t":"Yetimleri evlenecekleri yaşa gelinceye kadar deneyiniz, sonra aklen olgunlaştıklarını tespit ederseniz, mallarını onlara iade ediniz. Sakın onlar büyümeden önce, aceleyle ve israf ederek mallarını tüketmeyiniz. Zengin olan iffetli olmaya çalışsın, yoksul olan da ihtiyaç ve emeğine uygun olarak yesin! Onlara mallarını geri verdiğiniz zaman da yanlarında şahit bulundurunuz. Hesap sorucu olarak Allah yeter."},{"n":7,"t":"Anne babanın ve akrabanın geride bıraktıklarından erkekler bir pay alacaklardır. Anne babanın ve akrabanın bıraktığında, ister az ister çok olsun, kadınların da bir payı olacaktır. Allah tarafından tayin edilmiş bir paydır bu!"},{"n":8,"t":"Yakınlar, yetimler ve yoksullar miras taksiminde hazır bulunursa, bundan onları da rızıklandırınız ve onlara güzel söz söyleyiniz."},{"n":9,"t":"Geriye zayıf çocuklar bırakmaktan endişe etsinler ve onlar üzerinde titresinler. Allah`tan sakınıp doğru söz söylesinler."},{"n":10,"t":"Şüphesiz yetimlerin mallarını haksız yere yiyenler karınlarına ateş yemiş olurlar. Ve bunlar alevli bir ateşin içine atılacaklardır."},{"n":11,"t":"Allah size, çocuklarınızın alacağı miras hakkında, erkeğe kadının payının iki katını tavsiye eder. Kız çocuklar ikiden fazla iseler, ölenin geriye bıraktığının üçte ikisi onlarındır. Eğer çocuk tek bir kız ise mirasın yarısı onundur. Ölenin bir erkek çocuğu varsa, geriye bıraktığı malından anne babasından her birinin altıda bir hissesi vardır. Eğer çocuğu yok da anne babası ona vâris oluyorsa, annesine üçte bir düşer. Eğer ölenin bir kız kardeşi varsa, annesinin payı altıda birdir. Bu hükümler, ölenin yapacağı vasiyetten ya da borcundan sonradır. Babalarınız ve oğullarınızdan, hangisinin fayda bakımından size daha yakın olduğunu bilmezsiniz. Bunlar Allah`ın koyduğu haklardır. Şüphesiz Allah bilendir; hikmet sahibidir."},{"n":12,"t":"Eğer çocukları yoksa, eşlerinizin yapacakları vasiyetten ya da borçtan sonra geriye bıraktıkları mirasın yarısı sizindir. Çocukları varsa bıraktıklarının dörtte biri sizindir. Sizin de çocuğunuz yoksa, yapacağınız vasiyet ve borçtan sonra bıraktığınızın dörtte biri onlarındır; çocuğunuz varsa, bıraktığınızın sekizde biri onlarındır. Eğer miras bırakan erkek veya kadının evlâdı ve ana babası olmayıp bir erkek veya bir kız kardeşi varsa, her birine altıda bir düşer. Bundan fazla iseler üçte bire ortaktırlar. Bu taksim, zarar verici olmayan vasiyet ve borçtan sonra uygulanır. Bunlar Allah`tan size vasiyettir. Allah bilendir, yumuşak davranandır."},{"n":13,"t":"Bunlar Allah tarafından konulan sınırlardır. Kim Allah`a ve Peygamber`ine itaat ederse Allah onu, içinden ırmaklar akan cennetlere koyacaktır; orada süreli kalacaklardır. İşte büyük kurtuluş budur."},{"n":14,"t":"Kim Allah`a ve Peygamber`ine karşı isyan eder ve sınırlarını aşarsa Allah onu, süreli kalacağı bir ateşe sokar ve onun için alçaltıcı bir azap vardır."},{"n":15,"t":"Kadın kadına hayasızca davranışlarda bulunanlara/lezbiyenlik yapanlara gelince, onların işlediği bu ahlaksızlığa aranızdan dört kişi şahitlik etsin; bunlar onun için şahitlik yaparlarsa, suçlu kadınları ölüm alıp götürünceye yahut Allah onlara tövbe etmeleri suretiyle bir kapı açıncaya kadar, evlerine hapsediniz."},{"n":16,"t":"İçinizden iki erkek fuhuş/livata yaparsa onlara eziyet ediniz; eğer tövbe edip uslanırlarsa, artık onlara eziyetten vazgeçiniz. Çünkü Allah, tövbeleri kabul edendir, merhamet sahibidir."},{"n":17,"t":"Allah`ın kabul edeceği tövbe, ancak bilmeden kötülük edip de sonra tez elden tövbe edenlerin tövbesidir; işte Allah bunların tövbesini kabul eder; Allah her şeyi bilendir, hikmet sahibidir."},{"n":18,"t":"Yoksa kötülükleri yapıp yapıp da, içlerinden birine ölüm gelip çatınca; “Ben şimdi tövbe ettim” diyenlerle, kâfir olarak ölenler için, kabul edilecek tövbe yoktur. Onlar için acı bir azap hazırladık."},{"n":19,"t":"Ey iman edenler! Kadınlara zorla vâris olmanız size helâl değildir. Apaçık bir edepsizlik yapmadıkça, onlara verdiğinizin bir kısmını ele geçirmeniz için de kadınları sıkıştırmayınız. Onlarla iyi geçininiz. Eğer onlardan hoşlanmazsanız da, biliniz ki hoşlanmadığınız bir şeyi Allah büyük bir hayra vesile kılmış olabilir."},{"n":20,"t":"Eğer bir kadını bırakıp başka birini eş almak isterseniz, birincisine yüklerle mehir vermiş olsanız bile hiçbir şeyi geri almayınız. Siz iftira ederek ve apaçık günah işleyerek onu geri alır mısınız?"},{"n":21,"t":"Vaktiyle birbirinizle haşır neşir olduğunuz ve onlar sizden sağlam teminat almış olduğu halde, onu nasıl geri alırsınız?"},{"n":22,"t":"Geçmişte olanlar bir yana, babalarınızın evlendiği kadınlarla evlenmeyiniz, çünkü bu bir hayasızlıktır, çirkin bir şeydir ve kötü bir yoldur."},{"n":23,"t":"Analarınız, kızlarınız, kız kardeşleriniz, halalarınız, teyzeleriniz, kardeş kızları, kız kardeş kızları, sizi emziren analarınız, süt bacılarınız, eşlerinizin anaları, kendileriyle birleştiğiniz eşlerinizden olup evlerinizde bulunan üvey kızlarınız. Eğer onlarla nikâhlanıp da henüz birleşmemişseniz, kızlarını almanızda size bir mahzur yoktur. Kendi sulbünüzden olan oğullarınızın eşlerini ve iki kız kardeşi birden almak da size haram kılındı. Ancak, geçen geçmiştir. Allah çok bağışlayıcıdır; esirgeyicidir."},{"n":24,"t":"Hukuka uygun şekilde nikâhla sahip olduklarınız dışında bütün evli kadınlar size haramdır. Bu, üzerinize farz olan Allah`ın buyruğudur. Bunların dışında kalan bütün kadınlar, kendilerine mal varlığınızdan bir kısmını vermeniz ve hukuki olmayan bir ilişki ile değil de evlilik bağı yoluyla hukuka uygun bir şekilde olmak kaydıyla size helâldir. Kendileriyle evlenmek istediğiniz kadınlara hak ettikleri mehirlerini veriniz; ama bu hukuki yükümlülükten sonra bir şey üzerinde serbestçe anlaşmanızda sizin için bir sakınca yoktur. Şüphesiz Allah her şeyi bilendir; hikmet sahibidir."},{"n":25,"t":"İçinizden, inanmış hür kadınlarla evlenmeye gücü yetmeyen kimse, elleriniz altında bulunan inanmış genç kızlarınızdan/câriyelerinizden alsın. Allah sizin imanınızı en iyi bilendir. Hepiniz birbirinizdensiniz/hepiniz aynı kökten gelmektesiniz. Öyleyse iffetli yaşamaları, zina etmemeleri ve gizli dost tutmamaları şartıyla, sahiplerinin izniyle onlarla evleniniz; ücretlerini/ mehirlerini de güzelce veriniz. Evlendikten sonra bir fuhuş yaparlarsa onlara, hür kadınlara verilen cezanın yarısı uygulanır. Bu cariye ile evlenme, içinizden sıkıntıya düşmekten korkanlar içindir. Sabretmeniz ise sizin için daha iyidir. Allah bağışlayandır; merhamet edendir."},{"n":26,"t":"Allah size bilmediklerinizi açıklamak, sizi sizden önceki iyilerin yollarına iletmek ve sizin günahlarınızı bağışlamak istiyor. Allah, hakkıyla bilendir; işini yerli yerinde yapandır."},{"n":27,"t":"Allah sizin tövbenizi kabul etmek ister, iğreti arzularına uyanlar ise büsbütün yoldan çıkmanızı isterler."},{"n":28,"t":"Allah sizden yükünüzü hafifletmek ister; çünkü insan zayıf yaratılmıştır."},{"n":29,"t":"Ey iman edenler! Karşılıklı rızaya da dayansa, birbirinizin mallarını haksız yere yemeyin; -tabi ki (meşru) ticaret hariç- ve kendinize kıymayın; çünkü Allah sizin için bir rahmet kaynağıdır."},{"n":30,"t":"Bunu düşmanca bir niyetle ve zulüm için yapana gelince; onu ateşe koyacağız; bu ise Allah için kolaydır."},{"n":31,"t":"Uzak durmanız emredilen büyük günahlardan kaçınırsanız, küçük günahlarınızı örteriz ve sizi şerefli bir yere yerleştiririz."},{"n":32,"t":"Allah`ın sizi birbirinizden üstün kıldığı şeyleri hasretle arzu etmeyiniz. Erkeklerin de kazandıklarından bir payları var, kadınların da kazandıklarından bir payları var. Allah`ın lütfunu isteyiniz. Şüphesiz Allah, her şeyi bilmektedir."},{"n":33,"t":"Erkek ve kadından her biri için anne, baba ve akrabanın bıraktığından hisselerini alacak olan vârisler kıldık. Yeminlerinizin bağladığı/kendileriyle anlaşma yaptığınız kimselere de haklarını veriniz. Çünkü Allah, her şeyi görmektedir."},{"n":34,"t":"Erkekler kadınları, Allah`ın kendilerine onlardan daha fazla bağışladığı nimetler ve sahip oldukları servetten yapabilecekleri harcamalarla koruyup gözetirler. Dürüst ve erdemli kadınlar, gerçekten Allah`ın korunmasını buyurduğu mahremiyeti koruyan, sadık ve itaatkâr kadınlardır. Serkeşliklerinden endişe ettiğiniz kadınlara gelince, onlara önce nasihat ediniz, sonra yattıkları yatakta yalnız bırakınız; yine de itaat etmezlerse onları geçici olarak evden uzaklaştırınız. Bundan sonra itaat ederlerse, onları incitmekten kaçınınız. Allah gerçekten yücedir; büyüktür."},{"n":35,"t":"Eğer karı kocanın aralarının açılmasından korkarsanız, erkeğin ailesinden bir heyet ve kadının ailesinden bir heyet oluşturunuz. Eşler barışmak isterlerse, Allah aralarını bulur; şüphesiz Allah her şeyi bilen; her şeyden haberdar olandır."},{"n":36,"t":"Allah`a ibadet ediniz ve O`na hiçbir şeyi ortak koşmayınız. Anne babaya, akrabaya, yetimlere, yoksullara, yakın komşuya, uzak komşuya, yakın arkadaşa, yolda kalmışa/yarıda kalmış faaliyetlere ve ellerinizin altında bulunanlara iyilik yapınız. Doğrusu Allah, kendini beğenip duranları sevmez."},{"n":37,"t":"Bunlar, cimrilik eden ve insanlara cimriliği emreden, Allah`ın kendilerine lütfundan verdiğini gizleyen kimselerdir. Biz, kâfirler için alçaltıcı bir azap hazırladık."},{"n":38,"t":"Allah`a ve âhiret gününe inanmadıkları halde mallarını insanlara gösteriş için infak edenler de, âhirette azaba dûçar olurlar. Şeytan, bir kimseye arkadaş olursa ne kötü bir arkadaştır o!"},{"n":39,"t":"Allah`a ve âhiret gününe iman edip de Allah`ın kendilerine verdiğinden O`nun yolunda infak etselerdi, ne olurdu sanki? Allah onların durumunu hakkıyla bilmektedir."},{"n":40,"t":"Şüphesiz Allah, kimseye zerre kadar haksızlık yapmaz. Eğer hayırlı bir iş varsa onu kat kat arttırır ve rahmetinden büyük bir ödül bahşeder."},{"n":41,"t":"Her ümmetten bir şahit getirdiğimiz ve seni de onlara şahit olarak tutacağımız zaman, halleri nice olacaktır."},{"n":42,"t":"İnkâr edenler ve peygambere âsi olanlar, o gün yerin dibine batırılmayı temenni ederler ve Allah`tan hiçbir haberi gizleyemezler."},{"n":43,"t":"Ey iman edenler! Sarhoş iken, ne söylediğinizi bilinceye kadar namaza yaklaşmayınız. Cünüp iken, yolcu olanlar müstesna, gusül edinceye kadar namaz kılmayınız. Eğer hasta olur veya yolculukta bulunursanız ya da biriniz abdest bozmaktan gelince veya cinsel ilişkide bulunup su da bulamazsanız, o zaman tertemiz toprakla teyemmüm ediniz. Niyetle yüzlerinize ve ellerinize sürünüz. Şüphesiz ki Allah, günahları temizleyendir; çok affedicidir."},{"n":44,"t":"Kendilerine kitabın/Tevrat`ın bilgisi verilenlere baksana! Sapıklığı satın alıyorlar ve sizin de yoldan çıkmanızı istiyorlar."},{"n":45,"t":"Allah, düşmanlarınızı en iyi bilendir. Dost olarak Allah yeter; yardımcı olarak da Allah yeter."},{"n":46,"t":"Yahudi itikadına mensup olanların bir kısmı, bazı kelimelerin yerlerini değiştirirler; dillerini eğerek, bükerek ve dine saldırarak peygambere karşı “işittik ve karşı geldik, dinle, dinlemez olası, bizi güt” derler. Eğer onlar “işittik, itaat ettik, dinle ve bizi gözet” deselerdi şüphesiz kendileri için daha hayırlı ve daha doğru olacaktı; fakat inkârları sebebiyle Allah onları lânetlemiştir. Artık pek azı inanır."},{"n":47,"t":"Ey kitap ehli! Biz, birtakım yüzleri silip dümdüz ederek arkalarına çevirmeden, yahut onları Cumartesi adamları gibi lânetlemeden önce, size gelenleri doğrulamak üzere indirdiğimize iman ediniz; Allah`ın emri mutlaka yerine gelecektir."},{"n":48,"t":"Allah, kendisine ortak koşulmasını asla bağışlamaz; bundan başka günahları, dilediği kimse için bağışlar. Allah`a ortak koşan kimse büyük bir günah ile iftira etmiş olur."},{"n":49,"t":"Kendilerini temize çıkaranların farkında değil misin? Hayır, aksine Allah dilediğini temize çıkarır ve kimseye kıl kadar haksızlık yapılmaz."},{"n":50,"t":"Bak, nasıl da Allah üzerine yalan uyduruyorlar; iğrenç bir günah olarak bu onlara yeter!"},{"n":51,"t":"Kendilerine kitabın/Tevrat`ın bilgisi verilenleri görmedin mi? Putlara ve bâtıla iman ediyorlar; sonra da kâfirler için, “Bunlar, Allah`a iman edenlerden daha doğru yoldadır” diyorlar."},{"n":52,"t":"Bunlar, Allah`ın lânetlediği kimselerdir, Allah`ın lânetlediği kimseye gerçek bir yardımcı bulamazsın."},{"n":53,"t":"Yoksa onların mülkten, hükümranlıktan bir payları mı var? Öyle olsaydı, insanlara çekirdek filizi kadar bir şey bile vermezlerdi."},{"n":54,"t":"Yoksa onlar, Allah`ın lütfundan verdiği şeyler için insanlara haset mi ediyorlar? Oysa İbrâhim soyuna kitabı ve hikmeti verdik ve onlara büyük bir hükümranlık bahşettik."},{"n":55,"t":"Onlardan bir kısmı İbrâhim`e inandı, kimi de ondan yüz çevirdi, onlara kavurucu bir ateş olarak cehennem yeter."},{"n":56,"t":"Şüphesiz ki âyetlerimizi inkâr edenleri, gün gelecek, bir ateşe sokacağız; onların derileri piştikçe, derilerini başka derilerle değiştiririz ki acıyı duysunlar! Allah daima üstündür; işini yerli yerinde yapandır."},{"n":57,"t":"Buna karşılık, inanıp iyi işler yapanları da, içlerinden ırmaklar akan cennetlere koyacağız, orada süreli kalacaklardır; orada tertemiz eşlere sahip olacaklar ve onları koyu bir gölgenin içine koyacağız."},{"n":58,"t":"Allah size, mutlaka emanetleri ehil olanlara vermenizi ve insanlar arasında hükmettiğiniz zaman adaletle hükmetmenizi emreder. Allah size ne kadar güzel öğütler veriyor! Şüphesiz Allah, her şeyi işitendir; her şeyi görendir."},{"n":59,"t":"Ey iman edenler! Allah`a, Peygamber`e ve aranızdan siyasal erkin emanet edildiği kimselere itaat ediniz. Herhangi bir konuda anlaşmazlığa düşerseniz, eğer Allah`a ve âhiret gününe inanıyorsanız onu Allah`a ve Peygamber`e götürünüz. Bu, hem hayırlı, hem de netice bakımından daha güzeldir."},{"n":60,"t":"Sana indirilene ve senden önce indirilenlere inandıklarını ileri sürenleri görmedin mi? Tâğûtu/Allah`a karşı gelen adamı inkâr etmeleri kendilerine emrolunduğu halde, onun önünde davalaşmak istiyorlar. Halbuki şeytan onları büsbütün saptırmak istiyor."},{"n":61,"t":"Onlara, “Allah`ın indirdiğine ve Peygamber`ine geliniz” denildiği zaman, münafıkların senden iyice uzaklaştıklarını görürsün."},{"n":62,"t":"Elleriyle yaptıkları yüzünden başlarına bir felâket gelince hemen, “Biz yalnızca iyilik etmek ve arayı bulmak istedik” diye yemin ederek, sana nasıl gelirler!"},{"n":63,"t":"Ama Allah, onların kalplerindeki her şeyi bilir; o halde onları kendi hallerinde bırak; kendilerine öğüt ver ve onlara kendileri hakkında etkili söz söyle!"},{"n":64,"t":"Zira biz her peygamberi, ancak Allah`ın izniyle kendisine tâbi olunsun diye göndermişizdir. Eğer onlar, kendi kendilerine zulmettikten sonra sana gelip Allah`tan bağışlanma dileselerdi; Peygamber de onların bağışlanması için dua etseydi, Allah`ın tövbeleri kabul edici ve merhamet edici olduğunu tereddütsüz görürlerdi."},{"n":65,"t":"Hayır, Rabbine andolsun ki aralarında çıkan derin anlaşmazlık konusunda seni hakem kılıp, sonra da verdiğin hükümden içlerinde hiçbir sıkıntı duymaksızın onu tam manasıyla kabullenmedikçe iman etmiş olmazlar."},{"n":66,"t":"Fakat biz onlara, “hayatlarınızı feda ediniz” yahut “yurtlarınızı terk ediniz” diye emretmiş olsaydık, çok azı hariç, bunu yapmazlardı. Oysa tavsiye edilen şeyi yapmış olsalardı, bu, kesinlikle onların yararına olurdu ve onları daha güçlü kılardı."},{"n":67,"t":"Bu durumda biz onlara rahmetimizden büyük bir ödül verirdik."},{"n":68,"t":"Onları dosdoğru bir yola yöneltirdik."},{"n":69,"t":"Allah`a ve Peygamber`e itaat edenler, Allah`ın kendilerine lutuflarda bulunduğu peygamberler, doğruyu tasdik edenler, hakka şahitlik edenler ve sâlih kimselerle beraberdirler. Onlar ne güzel arkadaştır!"},{"n":70,"t":"Bu lütuf Allah`tandır. Bilen olarak Allah yeter."},{"n":71,"t":"Ey iman edenler! İster küçük gruplar halinde ister toplu halde savaşa giderken tehlikelere karşı hazırlıklı olunuz!"},{"n":72,"t":"Aranızda mutlaka geride kalanlar olacak ve o zaman başınıza bir felâket geldiğinde, “Onlarla birlikte bulunmamamız Allah`tan bize bir lütuftur” diyecekler."},{"n":73,"t":"Ama Allah`tan size bir zafer ihsan edildiğinde, bu kimseler şüphesiz sizinle kendileri arasında bir sevgi, yani bağlılık sorunu olmamış gibi, “Keşke onlarla birlikte olsaydık da o büyük başarıdan kapsaydık” diyecekler."},{"n":74,"t":"O halde, dünya hayatını verip âhireti alanlar, Allah yolunda savaşsınlar. Kim Allah yolunda savaşır da öldürülür veya galip gelirse, biz ona yakında büyük bir ödül vereceğiz."},{"n":75,"t":"Nasıl olur da, Allah yolunda savaşmayı ve “Ey Rabbimiz! Bizi halkı zâlim olan bu topraklardan kurtarıp özgürlüğe kavuştur ve rahmetinle bizim için bir koruyucu ve destek olarak bir yardımcı gönder” diye yalvaran çaresiz erkekler, kadınlar ve çocuklar için savaşmayı reddedersiniz?"},{"n":76,"t":"İman edenler, Allah`ın uğrunda savaşırlar; inanmayanlar ise tâğût/Allah`a karşı gelenin uğrunda savaşırlar. O halde şeytanın dostlarına karşı savaşınız; şüphe yok ki şeytanın kurduğu düzen zayıftır."},{"n":77,"t":"“Dünya menfaati önemsizdir, Allah`tan korkanlar için âhiret daha hayırlıdır ve size kıl payı kadar haksızlık edilmez.”"},{"n":78,"t":"Nerede olursanız olunuz ölüm size ulaşır; sarp ve sağlam kalelerde olsanız bile! Kendilerine bir iyilik dokunsa “bu Allah`tan” derler; başlarına bir kötülük gelince de “bu senden” derler. “Hepsi Allah`tandır” de! Bu adamlara ne oluyor ki bir türlü laf anlamıyorlar?"},{"n":79,"t":"Sana gelen iyilik, Allah`tandır. Başına gelen kötülük de nefsindendir. Seni insanlara peygamber gönderdik. Şahit olarak Allah yeter."},{"n":80,"t":"Kim peygambere itaat ederse Allah`a itaat etmiş olur; yüz çevirenlere gelince, biz seni onlara bekçilik yapmak için göndermedik."},{"n":81,"t":"Onlar, “Biz sana itaat ediyoruz” derler; ama yanından ayrılınca onlardan bir kısmı, senin dediğinden başkasını gizlice kurar. Allah da onların gizlice kurduklarını yazar. Sen onlara aldırma ve Allah`a dayan; vekil olarak Allah sana yeter."},{"n":82,"t":"Hâlâ Kur`ân üzerinde gereği gibi düşünmeyecekler mi? Eğer o, Allah`tan başkası tarafından gönderilmiş olsaydı onda birçok çelişki bulurlardı."},{"n":83,"t":"Onlara, güven veya korkuya dair bir haber gelse onu yayarlar. Halbuki onu Peygamber`e ve aralarındaki otorite sahiplerine götürselerdi, içlerinden işin iç yüzünü araştırıp çıkaranlar onun ne olduğunu bilirlerdi. Eğer size Allah`ın lütfu ve rahmeti olmasaydı, içinizden pek azı müstesna, şeytana uyardınız."},{"n":84,"t":"O halde sen Allah yolunda savaş; çünkü sen, yalnızca kendi nefsinden sorumlusun ve müminleri teşvik et! Allah kâfirlerin gücünü kırmaya muktedirdir. Çünkü Allah`ın gücü daha çetin ve cezası daha şiddetlidir."},{"n":85,"t":"Kim iyi bir işe aracılık ederse, onun da o işten bir nasibi olur. Kim kötü bir işe aracılık ederse, onun da ondan bir payı olur. Allah her şeyi gözetleyicidir."},{"n":86,"t":"Bir selâmla selâmlandığınızda, daha güzel bir selâmla, yahut aynıyla karşılık veriniz. Şüphesiz Allah, her şeyin hesabını tutmaktadır."},{"n":87,"t":"Elbette sizi kıyamet günü toplayacak olan Allah`tan başka hiçbir tanrı yoktur ve bunda asla şüphe yoktur. Kimin sözü Allah`ın sözünden daha doğru olabilir?"},{"n":88,"t":"Size ne oldu ki münafıklar hakkında iki gruba ayrılıyorsunuz? Oysa yaptıkları işlerden dolayı Allah onları baş aşağı etmiştir. Allah`ın saptırdığını doğru yola iletmek mi istiyorsunuz? Allah birini saptırırsa artık onun için bir çıkış yolu bulamazsınız."},{"n":89,"t":"Sizin de kendileri gibi inkâr etmenizi istediler ki onlarla eşit olasınız. O halde Allah yolunda göç edinceye kadar onlardan hiçbirini dost edinmeyiniz. Eğer yüz çevirirlerse onları yakalayınız, bulduğunuz yerde öldürünüz ve hiçbirini dost ve yardımcı edinmeyiniz."},{"n":90,"t":"Ancak, kendileriyle aranızda antlaşma bulunan bir topluma sığınanlar, yahut ne sizinle ne de kendi toplumlarıyla savaşmak istemediklerinden yürekleri ürküntü içinde size gelenler müstesna. Allah dileseydi onları başınıza belâ ederdi ve sizinle savaşırlardı. Artık onlar sizi bırakıp bir tarafa çekilir de sizinle savaşmazlar ve size barış teklif ederlerse, bu durumda Allah size onların aleyhinde bir yola girme hakkı vermemiştir."},{"n":91,"t":"Hem sizden hem de kendi toplumlarından emin olmak isteyen başkalarını da bulacaksınız. Bunlar her ne zaman fitneye götürülseler ona baş aşağı dalarlar. Eğer sizden uzak durmaz, barış teklif etmez ve ellerini çekmezlerse onları yakalayınız, rastladığınız yerde öldürünüz. İşte onlar üzerine sizin için apaçık yetki verdik."},{"n":92,"t":"Yanlışlık olması dışında, bir mümin bir mümini öldüremez. Yanlışlıkla bir mümini öldürenin, mümin bir köle âzat etmesi ve ölenin ailesine de bir diyet vermesi gerekir. Eğer ölenin ailesi bağışlar, diyetten vazgeçerlerse başka! Öldürülen mümin, düşmanınız olan bir topluluktan ise öldürenin mümin bir köle âzat etmesı gerekir. Eğer öldüren kişi, sizinle kendileri arasında antlaşma bulunan bir topluluktan ise ailesine bir diyet verecek ve mümin bir köle âzat edecektir. Bunları bulamayan kimsenin, Allah tarafından tövbesinin kabulü için iki ay kesintisiz oruç tutması gerekir. Allah bilendir; işini yerli yerince yapandır."},{"n":93,"t":"Her kim bir mümini kasten öldürürse onun cezası, içinde süreli kalacağı cehennemdir. Allah ona gazap etmiş, lânet etmiş ve onun için büyük bir azap hazırlamıştır."},{"n":94,"t":"Ey iman edenler! Allah yolunda savaşa çıktığınız zaman iyi anlayıp dinleyiniz. Size barış teklif edene, dünya hayatının geçici menfaatine göz dikerek “Sen mümin değilsin” demeyiniz. Çünkü Allah`ın nezdinde sayısız ganimetler vardır. Önceden siz de böyleyken Allah size lütfetti; o halde iyi anlayıp dinleyiniz. Şüphesiz Allah bütün yaptıklarınızdan haberdardır."},{"n":"95-96","t":"İnananlardan, özürsüz olarak yerlerinde oturanlar ile mallarıyla ve canlarıyla Allah yolunda cihad edenler bir olmaz. Allah malları ve canlarıyla cihad edenleri derece bakımından oturanlardan üstün kılmıştır. Gerçi Allah hepsine de güzellik vaad etmiştir; ama mücahitlerin ödülünü, kendi katından yüksek dereceler, bağış ve rahmet şeklinde, oturanlarınkinden üstün kılmıştır. Allah bağışlayandır; merhamet edendir."},{"n":97,"t":"Melekler, kendilerine zulmedenlere, canlarını alırken, “Sizin neyiniz vardı?” diye soracaklar. Onlar, “Biz yeryüzünde çok güçsüzdük” şeklinde cevap verecekler. Melekler, “Allah`ın yeri sizin kötülük diyarını terk etmenize yetecek kadar geniş değil miydi?” diyecekler. İşte onların barınağı cehennemdir, orası ne kötü bir gidiş yeridir!"},{"n":98,"t":"Erkekler, kadınlar ve çocuklardan, âciz olup hiçbir çareye gücü yetmeyenler, hiçbir yol bulamayanlar müstesnadır."},{"n":99,"t":"İşte, umulur ki Allah bunları affeder; Allah çok affedicidir; bağışlayıcıdır."},{"n":100,"t":"Allah yolunda hicret eden kimse yeryüzünde gidecek birçok güzel yer ve bolluk, imkân bulur. Kim Allah ve Peygamberi uğrunda hicret ederek evinden çıkar da, sonra kendisine ölüm yetişirse, artık onun ödülü Allah`a düşer. Allah da çok affedicidir; merhamet sahibidir."},{"n":101,"t":"Yeryüzünde sefere çıktığınız zaman, kâfirlerin size kötülük etmelerinden endişe ederseniz, namazı kısaltmanızda size bir günah yoktur. Şüphesiz kâfirler sizin apaçık düşmanınızdır."},{"n":102,"t":"Sen de onların içlerinde bulunup namaz kıldırdığın zaman, onlardan bir kısmı seninle beraber namaza dursunlar, silâhlarını yanlarına alsınlar, böylece namaz kılıp secde ettiklerinde diğerleri arkanızda olsunlar. Sonra henüz namazını kılmamış olan diğer grup gelip, seninle beraber namazlarını kılsınlar ve onlar da ihtiyat tedbirlerini ve silâhlarını alsınlar. Kâfirler, siz silâhlarınızı ve eşyalarınızı bıraktığınızda üstünüze birden baskın yapmak isterler. Eğer size yağmurdan bir eziyet olursa, yahut hasta iseniz, silâhlarınızı bırakmanızda günah yoktur. Yine de tedbirinizi alınız. Şüphesiz Allah, kâfirler için alçaltıcı bir azap hazırlamıştır."},{"n":103,"t":"Namazı bitirince de ayakta, otururken ve yanınız üzerine yatarken Allah`ı anınız. Huzura kavuşunca da namazı dosdoğru kılınız; çünkü namaz müminler üzerine vakitleri belli bir farzdır."},{"n":104,"t":"O düşman topluluğunu takip etmekte gevşeklik göstermeyiniz. Eğer siz acı çekiyorsanız, onlar da sizin çektiğiniz gibi acı çekmektedirler. Üstelik siz, Allah`tan onların ümit etmediklerini ümit ediyorsunuz. Allah her şeyi bilendir; hikmet sahibidir."},{"n":105,"t":"Allah`ın sana gösterdiği şekilde insanlar arasında hükmedesin diye, sana kitabı bir amaç için indirdik; o halde ihanet edenlere taraf olma!."},{"n":106,"t":"Allah`tan af iste; çünkü Allah çok bağışlayıcıdır; merhamet edicidir."},{"n":107,"t":"Kendilerine ihanet edenleri savunma! Çünkü Allah ihanet edenleri ve günahkârları sevmez."},{"n":108,"t":"İnsanlardan gizlerler de Allah`tan gizlemezler/İnsanlardan gizleyebilir ama Allah`tan gizleyemezler. Halbuki geceleyin, O`nun razı olmadığı sözü düzüp dururken, Allah onlarla beraber idi. Allah, yaptıklarını kuşatıcıdır."},{"n":109,"t":"Sizler belki bu dünya hayatında, onları savunabilirsiniz, ya kıyamet günü kim onları Allah`a karşı savunacak, kim onların vekili olacaktır?"},{"n":110,"t":"Kim bir kötülük yapar veya kendine zulmeder de sonra Allah`tan af dilerse, Allah`ı çok bağışlayıcı ve merhamet edici bulacaktır."},{"n":111,"t":"Çünkü günah işleyen kimse, yalnız kendine zarar verir. Allah her şeyi bilendir; hikmet sahibidir."},{"n":112,"t":"Kim bir hata yapar ve günah işler de sonra onu suçsuz bir kimsenin üstüne atarsa, büyük bir iftira ve iğrenç bir günah yüklenmiş olur."},{"n":113,"t":"Allah`ın sana lütfu ve rahmeti olmasaydı, onlardan bir güruh seni saptırmaya yeltenmişti. Onlar yalnızca kendilerini saptırırlar, sana hiçbir zaman zarar veremezler. Allah sana kitabı ve hikmeti indirmiş ve sana bilmediğini öğretmiştir. Allah`ın lütfu sana gerçekten büyük olmuştur."},{"n":114,"t":"Onların fısıldaşmalarının birçoğunda hayır yoktur. Ancak bir sadaka, bir iyilik ya da insanların arasını düzeltmeyi isteyenin fısıldaşması müstesnadır. Kim Allah`ın rızâsını elde etmek için bunu yaparsa, biz ona yakında büyük bir ödül vereceğiz."},{"n":115,"t":"Kendisi için doğru yol belli olduktan sonra, kim Peygambere karşı çıkar ve müminlerin yolundan başka bir yola giderse, onu o yönde bırakırız ve cehenneme sokarız; o ne kötü bir yerdir!"},{"n":116,"t":"Allah kendisine şirk koşulmasını asla bağışlamaz; şirkten başka günahları, dilediği kimse için bağışlar. Kim Allah`a şirk koşarsa büsbütün sapıtmıştır."},{"n":117,"t":"Müşrikler, Allah`ı bırakıp yalnızca birtakım dişi zannettikleri sahte tanrılardan istiyorlar ve isyankâr şeytandan dilekte bulunuyorlar."},{"n":118,"t":"Allah şeytanı lânetlemiş, o da “Yemin ederim ki, kullarından bir pay edineceğim” demişti."},{"n":119,"t":"“Onları mutlaka saptıracağım, mutlaka onları boş kuruntulara sokacağım ve onlara emredeceğim de hayvanların kulaklarını yaracaklar; onlara emredeceğim de Allah`ın yaratışını değiştirecekler!” Kim Allah`ın yerine şeytanı dost tutarsa, elbette açık bir ziyana uğramıştır."},{"n":120,"t":"Şeytan onlara söz verir ve onları ümitlendirir. Fakat şeytanın onlara söz vermesi aldatmacadan başka bir şey değildir."},{"n":121,"t":"Böylelerinin varacakları yer cehennemdir ve oradan kaçış yolu bulamayacaklardır."},{"n":122,"t":"İman eden ve yararlı işler yapanları da içinden ırmaklar akan cennetlere sokacağız; orada süreli kalacaklardır. Bu, Allah`ın gerçek vaadidir. Allah`tan daha doğru sözlü kim olabilir?"},{"n":123,"t":"İş, ne sizin kuruntularınızla, ne de kitap ehlinin kuruntularıyla olur. Kötülük yapan, onunla cezalandırılır ve kendisine Allah`tan başka ne dost ne de yardımcı bulur."},{"n":124,"t":"Erkek olsun kadın olsun, her kim mümin olarak iyi işler yaparsa, işte onlar cennete girerler ve zerre kadar haksızlığa uğramazlar."},{"n":125,"t":"Bütün benliğini Allah`a teslim eden, daima iyilik yapan ve her türlü bâtıldan yüz çeviren İbrâhim`in inanç sistemine, Allah`ın onu sevgisiyle yücelteceğini görerek uyan kişinin dininden daha güzel bir din var mıdır?"},{"n":126,"t":"Göklerde ve yerde ne varsa hepsi Allah`ındır ve Allah her şeyi kuşatmıştır."},{"n":127,"t":"Kendilerine yazılmış olanı vermeyip kendileriyle evlenmek istediğiniz yetim kadınlar, zavallı çocuklar ve yetimlere karşı adaleti yerine getirmeniz hakkında kitapta size okunan âyetler de Allah`ın hükmünü açıklamaktadır. Yaptığınız her hayrı, muhakkak ki Allah bilir.”"},{"n":128,"t":"Eğer bir kadın, kocasının huysuzluğundan, yahut kendisinden yüz çevirmesinden korkarsa, anlaşma ile aralarını düzeltmelerinde ikisine de günah yoktur. Barış daima iyidir. Kıskançlık nefislere yaratılıştan konmuştur. Eğer güzelce geçinir ve Allah`tan sakınırsanız, şüphesiz Allah yaptıklarınızdan haberdardır."},{"n":129,"t":"Ne kadar isteseniz de kadınlar arasında tam adalet yapamazsınız. Öyleyse, birine tamamen meyledip ötekini askıda kocasızmış gibi bırakmayınız. Eğer arayı düzeltir, sakınırsanız, Allah bağışlayandır; merhamet edendir."},{"n":130,"t":"Eğer eşler ayrılırlarsa, Allah her birini lütfuyla besleyip geçindirir. Çünkü Allah lütfunda sınırsızdır; hikmet sahibidir."},{"n":131,"t":"Göklerde ve yerde olan her şey Allah`a aittir. Andolsun ki biz, hem sizden önce kitap verilenlere hem de size Allah`a saygılı olmanızı emrettik. Eğer inkâr ederseniz, biliniz ki göklerde ve yerde ne varsa hepsi Allah`ındır. Allah, zenginliği sınırsız olandır; övülmeye lâyık olandır."},{"n":132,"t":"Göklerde ve yerde olan her şey Allah`a aittir. Vekil olarak Allah yeter."},{"n":133,"t":"Ey insanlar! Allah dilerse sizi yok edip başkalarını getirir. Allah`ın buna gücü yeter."},{"n":134,"t":"Kim dünyanın sevabını isterse, bilsin ki dünyanın da âhiretin de sevabı Allah katındadır. Allah her şeyi işiten ve her şeyi görendir."},{"n":135,"t":"Ey iman edenler! Adaleti titizlikle ayakta tutunuz; kendiniz, anne babanız ve akrabanız aleyhinde de olsa, Allah için şahitlik eden kimseler olunuz. Haklarında şahitlik ettikleriniz zengin olsunlar, fakir olsunlar, Allah onlara sizden daha yakındır. İğreti arzularınıza uyup adaletten sapmayınız. Eğer şahitlik ederken dilinizi eğip bükerseniz ya da doğruyu söylemezseniz, muhakkak ki Allah yaptıklarınızı bilir."},{"n":136,"t":"Ey iman edenler! Allah`a, Peygamberi`ne, ona indirdiği kitaba ve daha önce indirdiği kitaba iman ediniz. Kim Allah`ı, meleklerini, kitaplarını, peygamberlerini ve kıyamet gününü inkâr ederse tam anlamıyla sapıtmıştır."},{"n":137,"t":"İman edip sonra inkâr edenleri, sonra yine iman edip tekrar inkâr edenleri, sonra da inkârlarını arttıranları Allah ne bağışlayacak, ne de onları doğru yola iletecektir."},{"n":138,"t":"Münafıklara kendileri için acı bir azap olduğunu müjdele!"},{"n":139,"t":"Müminleri bırakıp da kâfirleri dost edinenler; onların yanında şeref mi arıyorlar? Şüphesiz bütün şeref yalnızca Allah`a aittir."},{"n":140,"t":"Allah`ın âyetlerinin inkâr edildiğini ve onlarla alay edildiğini işittiğiniz zaman, onlar başka bir söze dalıncaya kadar onlarla beraber oturmayınız; yoksa siz de onlar gibi olursunuz. Şüphesiz Allah, münafıkları ve kâfirleri cehenneme toplayacaktır."},{"n":141,"t":"Kâfirler ve münafıklar, sadece başınıza gelecekleri görmeyi beklerler. Böylece eğer Allah`tan size bir zafer ihsan edilirse, “Sizin yanınızda değil miydik?” derler. Eğer savaşta kâfirlerin bir payı olursa, “Biz size üstünlük sağlayıp sizi müminlerden korumadık mı?” derler. Ama Allah, kıyamet günü aranızda hükmünü verecek, kafirlerin müminlere zarar vermelerine asla izin vermeyecektir."},{"n":142,"t":"Şüphesiz, münafıklar Allah`ı kandırmaya çalışıyorlar; halbuki Allah onların kendi kendilerini kandırmalarını sağlıyor. Onlar namaz için kalktıklarında, gönülsüzce kalkarlar, insanlara gösteriş yaparlar. Allah`ı da nâdiren anarlar."},{"n":143,"t":"Bunların arasında bocalayıp durmaktadırlar; ne onlara bağlanıyorlar, ne bunlara. Allah`ın şaşırttığı kimseye asla bir çıkar yol bulamazsın!"},{"n":144,"t":"Ey iman edenler! Müminleri bırakıp da kâfirleri dost edinmeyiniz; suçluluğunuz konusunda Allah`ın önüne açık bir delil mi koymak istiyorsunuz?"},{"n":145,"t":"Şüphe yok ki münafıklar cehennemin en alt katındadırlar. Artık onlara bir yardımcı bulamazsın."},{"n":146,"t":"Ancak tövbe edenler, hallerini düzeltenler, Allah`a sımsıkı sarılanlar, dinlerini sadece Allah`a tahsis edenler; işte bunlar müminlerle beraberdirler ve Allah ileride bütün müminlere büyük ödül verecektir."},{"n":147,"t":"Eğer şükredici olur ve iman ederseniz, Allah size niçin azap etsin? Allah şükre karşılık verendir; her şeyi bilendir."},{"n":148,"t":"Allah kötü sözün açıkça söylenmesini sevmez; ancak zulme uğrayan müstesnadır. Allah her şeyi işiticidir; bilicidir."},{"n":149,"t":"Bir iyiliği açıklar yahut gizlerseniz veya bir kötülüğü affederseniz, şüphesiz Allah da ziyadesiyle affedicidir; her şeye gücü yetendir."},{"n":"150-151","t":"Allah`ı ve peygamberlerini inkâr edenler, Allah ile peygamberlerinin arasını ayırmak isteyenler, “Kimine inanırız, kimini inkâr ederiz” diyenler, inanmakla inkârın arasında bir yol tutmak isteyenler var ya; işte onlar gerçek kâfirlerdir. Biz de kâfirlere alçaltıcı bir azap hazırlamışızdır."},{"n":152,"t":"Allah`a ve peygamberlerine iman eden ve onlardan hiçbirini diğerlerinden ayırt etmeyenlere gelince; işte Allah bir gün onlara ödüllerini verecektir. Allah çok bağışlayıcıdır; merhamet edicidir."},{"n":153,"t":"Ehli kitap, senden kendilerine gökten bir kitap indirmeni istiyor. Onlar Mûsâ`dan, bundan daha büyüğünü istemişler ve “Bize Allah`ı apaçık göster” demişlerdi. Zulümleri sebebiyle hemen onları yıldırım çarptı. Sonra kendilerine bunca açık mûcizeler gelmişken buzağıya taptılar. Nihayet biz, tövbe ettiklerinden, onları bağışladık ve Mûsâ`ya açık bir hâkimiyet verdik."},{"n":154,"t":"Sînâ Dağı`nı, verdikleri sözün delili olarak üzerlerine yükseltmiştik. Onlara “Kapıdan tevazu içinde giriniz” demiş ve “Sebt kanununu/Cumartesi yasağını ihlâl etmeyiniz” diye uyarmıştık ve kendilerinden sağlam bir söz almıştık."},{"n":155,"t":"Sözlerinden dönmeleri, Allah`ın âyetlerini inkâr etmeleri, haksız yere peygamberleri öldürmeleri ve “Kalplerimiz kılıflıdır” demeleri sebebiyle onları lânetledik, türlü belâlar verdik. Onların kalpleri kılıflı değildi; tam aksine inkârları sebebiyle Allah o kalpler üzerine mühür vurmuştur; pek azı inanır."},{"n":"156-157","t":"Bir de, inkâr etmeleri ve Meryem`e büyük bir iftira atmaları ve “Allah`ın peygamberi Meryem oğlu Îsa`yı öldürdük” demeleri yüzünden onları lânetledik. Halbuki onu ne öldürdüler ne de astılar; fakat sadece onlara öyle olmuş gibi göründü. Onun hakkında ihtilâfa düşenler, bundan dolayı tam bir kararsızlık içindedirler; bu hususta zanna uymak dışında hiçbir bilgileri yoktur ve kesin olarak onu öldürmediler."},{"n":158,"t":"Hayır, Allah onu kendi katına yüceltti. Allah gerçekten kudret ve hikmet sahibidir."},{"n":159,"t":"Nitekim ölümünden önce kitap ehlinden hiç kimse yoktur ki, Îsa`ya inanmamış olsun. Kıyamet gününde de Îsa, onlara şahitlik yapacaktır."},{"n":160,"t":"Yaptıkları zulümler ve birçok insanı Allah yolundan alıkoymaları yüzünden, daha önce kendilerine helâl kılınmış tertemiz şeyleri, Yahudilere haram kıldık."},{"n":161,"t":"Yasaklanmış olmalarına rağmen faizi almaları ve haksız yollarla insanların mallarını yemeleri yüzünden onların küfre sapmalarına korkunç bir azap hazırladık."},{"n":162,"t":"Fakat içlerinden ilimde derinleşmiş olanlar ve müminler, sana indirilene ve senden önce indirilene iman edenler, namazı kılanlar, zekâtı verenler, Allah`a ve âhiret gününe inananlar var ya; işte onlara pek yakında büyük ödül vereceğiz."},{"n":163,"t":"Biz, Nûh`a ve ondan sonraki peygamberlere vahyettiğimiz gibi, sana da vahyettik. Nitekim İbrâhim`e, İsmail`e, İshâk`a, Yâkub`a, torunlara, Îsa`ya, Eyyûb`e, Yûnus`a, Hârûn`a ve Süleyman`a vahyettik. Dâvûd`a da Zebûr`u verdik."},{"n":164,"t":"Bir kısım peygamberleri daha önce sana anlattık; bir kısmını ise sana anlatmadık. Allah, Mûsâ`ya sözünü söyledi."},{"n":165,"t":"Müjdeleyici ve uyarıcı peygamberler gönderdik ki, peygamberler geldikten sonra insanların Allah`a karşı bahaneleri olmasın. Allah mağlup edilemez; işini yerli yerinde yapar."},{"n":166,"t":"Fakat Allah, sana indirdiğine, onu kendi ilmiyle indirdiğine şahitlik eder. Melekler de şahitlik ederler. Şahit olarak Allah yeterlidir."},{"n":167,"t":"İnkâr edip başkalarını da Allah yolundan çevirenler, dönüşü olmayan bir sapıklığa düşmüşlerdir."},{"n":"168-169","t":"İnkâr edip zulme sapanlar var ya; Allah onları asla affedecek değildir. Onları içinde süreli kalacakları cehennem yolu hariç, başka bir yola iletecek de değildir. Bunu yapmak Allah için kolaydır."},{"n":170,"t":"Ey insanlar! Peygamber size Rabbinizden hakikati getirdi. O halde kendi iyiliğiniz için iman ediniz! Eğer inkâr ederseniz, biliniz ki göklerde ve yerde olan her şey Allah`a aittir. Allah her şeyi bilendir; hikmet sahibidir."},{"n":171,"t":"Ey kitap ehli! Dininizde aşırı gitmeyiniz ve Allah hakkında gerçek olandan başkasını söylemeyiniz. Meryem oğlu Îsa, sadece Allah`ın peygamberidir; Îsa Allah`ın, Meryem`e ulaştırdığı “kün”/ol kelimesinin eseridir. Allah`tan bir ruhtur. Şu halde, Allah`a ve Peygamberine iman ediniz. “Tanrı üçtür” demeyiniz; kendi menfaatinize bundan vazgeçiniz. Allah, ancak bir tek Allah`tır. O, çocuğu olmaktan uzaktır. Göklerde ve yerde ne varsa hepsi O`nundur. Vekil olarak Allah yeter."},{"n":172,"t":"Ne Mesih, Allah`a kul olmaktan çekinir, ne de Allah`a yaklaştırılmış melekler. Kim Allah`a kulluktan çekinir ve büyüklük taslarsa, bilsin ki Allah onların hepsini kendi huzurunda toplayacaktır."},{"n":173,"t":"İnanıp iyi işler yapanların ödüllerini eksiksiz ödeyecek ve lütfundan onlara daha fazlasını da verecektir. Kulluktan çekinip büyüklük taslayanlara da acı bir şekilde azap edecektir. Onlar, kendilerine Allah`tan başka ne bir dost, ne de bir yardımcı bulacaklardır."},{"n":174,"t":"Ey insanlar! Rabbinizden size güçlü bir delil geldi ve size aydınlatıcı bir nur indirdik."},{"n":175,"t":"Allah`a iman edenlere ve O`na sımsıkı sarılanlara gelince; Allah onları kendinden bir rahmet ve lütuf içine daldıracak ve onları dosdoğru bir yol ile kendine yöneltecektir."},{"n":176,"t":"Ölen kişinin çocuğu yok, bir kız kardeşi varsa bıraktığı malın yarısı o kız kardeşinindir. Erkek kardeş, ölen kardeşinin çocuğu yoksa, onun mirasının tamamını alır. Eğer ölenin iki kız kardeşi varsa, bıraktığının üçte ikisi onlarındır. Eğer vârisler erkek ve kızdan müteşekkil birçok kardeş olursa, erkeğe, iki kadının payı kadar pay verilir. Şaşırırsınız diye Allah size hükmünü açıklıyor. Allah her şeyi bilendir."}],[{"n":1,"t":"Ey iman edenler! Antlaşmalara sâdık kalınız. Size haram oldukları okunacak olanların dışında kalan hayvanlar, sadece ihramda iken avı helâl saymamak şartıyla, sizin için helâl kılındı. Allah, istediği hükmü verir."},{"n":2,"t":"Ey iman edenler! Ne Allah`ın işaretlerine, ne haram aya, ne kurbana, ne gerdanlıklı kurbanlara, ne de Rabblerinin ihsanını arzu ederek Beyt-i Harâm`a doğru gelenlere saygısızlık ediniz. İhramdan çıktığınız zaman avlanabilirsiniz. Sizi Mescid-i Haram`dan çevirdiklerinden dolayı bir topluma karşı beslediğiniz kin, sizi saldırıya sevk etmesin. İyilik ve takvâ üzerinden yardımlaşınız; günah ve düşmanlık üzerinde yardımlaşmayınız, Allah`tan sakınınız. Çünkü Allah`ın azabı şiddetlidir."},{"n":3,"t":"Leş, kan, domuz eti, Allah`tan başkası adına boğazlanan, boğulmuş, vurulup öldürülmüş, yuvarlanıp ölmüş, boynuzlanıp ölmüş, canavarların yediği hayvanlar ölmeden yetişip kestikleriniz müstesna, dikili taşlar üzerinde boğazlanmış hayvanlar ve fal oklarıyla kısmet aramanız size haram kılındı. Bunlar yoldan çıkmaktır. Bugün kâfirler sizin dininizden ümit kesmişlerdir. Artık onlardan korkmayınız, benden korkunuz. Bugün dininizi sizin için tamamladım, nimetlerimin tamamını size bahşettim ve sizin için din olarak İslâm`ı uygun gördüm. Kim gönülden günaha yönelmiş olmamak üzere, açlık halinde dara düşerse, haram etlerden yiyebilir. Çünkü Allah çok bağışlayıcıdır; çok merhamet edicidir."},{"n":4,"t":"Bütün iyi temiz şeyler size helâl kılınmıştır. Allah`ın size öğrettiğinden öğretip avcı haline getirdiğiniz hayvanların sizin için yakaladıklarından da yiyiniz ve üzerine Allah`ın adını anınız/besmele çekiniz. Allah`tan sakınınız. Allah`ın hesabı pek çabuktur."},{"n":5,"t":"Bugün size bütün temiz şeyler helâl kılındı. Kendilerine kitap verilmiş olup tevhit inancına sahip olanların yemekleri size helâldir. Sizin yemekleriniz de onlara helâldir. Mümin kadınlardan iffetli olanlar ile, daha önce kendilerine kitap verilenlerden iffetli kadınlar da, mehirlerini vermeniz şartıyla, namuslu olmak, zina etmemek ve gizli dost tutmamak üzere size helâldir. İmanı reddedenin ameli boşa gitmiştir ve o, âhirette de kayba uğrayanlardandır."},{"n":6,"t":"Ey iman edenler! Namaz kılmaya kalktığınız zaman yüzlerinizi, dirseklerinize kadar kollarınızı, başlarınızı mesh edip, topuklara kadar ayaklarınızı yıkayınız. Eğer cünüp iseniz boy abdesti alınız. Hasta yahut yolculuk halinde bulunursanız veya biriniz tuvaletten gelirse, ya da kadınlara dokunmuşsanız /cinsi birleşme yapmışsanız ve bu hallerde su bulamamışsanız, temiz toprakla teyemmüm ediniz de yüzünüzü ve dirseklere kadar ellerinizi onunla mesh ediniz. Allah size herhangi bir güçlük çıkarmak istemez; fakat sizi tertemiz kılmak ve size ihsan ettiği nimetini tamamlamak ister; umulur ki şükredersiniz."},{"n":7,"t":"Allah`ın size olan nimetini ve “işittik, itaat ettik” dediğiniz zaman Allah`a karşı altına girdiğiniz taahhüdü hatırlayınız ve Allah`tan sakınınız. Şüphesiz Allah sinelerdekini çok iyi bilir."},{"n":8,"t":"Ey iman edenler! Allah için hakkı ayakta tutan, adaletle şahitlik eden kimseler olunuz. Bir topluluğa duyduğunuz kin, sizi âdil davranmamaya itmesin. Adaletli olunuz; bu takvânın ta kendisidir. Allah`a isyandan sakınınız. Allah yapmakta olduklarınızdan haberdardır."},{"n":9,"t":"Allah, iman eden ve iyi işler yapanlara günahlarının bağışlanacağını ve büyük bir ödülün onların olacağını vaat etmiştir."},{"n":10,"t":"İnkâr eden ve âyetlerimizi yalanlayanlara gelince; onlar cehennemliklerdir."},{"n":11,"t":"Ey iman edenler! Allah`ın size olan nimetini hatırlayınız; hani bir topluluk size el uzatmaya teşebbüs etmişti de, Allah onların ellerini sizden çekmişti. Allah`tan sakınınız. Müminler sadece Allah`a güvensinler."},{"n":12,"t":"“Ben sizinle beraberim. Namazı kılarsanız, zekâtı verirseniz, peygamberime inanır ve onları desteklerseniz, Allah`a güzel bir borç verirseniz, elbette kötülüklerinizi örteceğim ve sizi içinden ırmaklar akan cennetlere koyacağım. Artık bundan sonra kim inkâr ederse, doğru yoldan sapmış olur.”"},{"n":13,"t":"Antlaşmalarını bozduklarından dolayı onları lânetledik ve kalplerini katılaştırdık. Kelimelerin yerlerini değiştiriyorlar. Kendilerine öğretilen hükümlerin önemli bir bölümünü de unuttular. İçlerinden pek azı hariç, onlardan daima bir hainlik görürsün. O halde sıkı dur, iyi düşünüp, reddet! Şüphesiz Allah, iyilik edenleri sever."},{"n":14,"t":"Aynı şekilde “biz Hıristiyanlarız” diyenlerden kesin bir söz almıştık; ama onlar da kendilerine verilen öğütlerin önemli bir bölümünü unuttular. Bu sebeple, kıyamete kadar aralarına düşmanlık ve kin saldık. Yakında Allah onlara yaptıklarını haber verecektir."},{"n":15,"t":"Ey kitap ehli! Peygamberimiz, kitaptan gizlediklerinizin çoğunu açıklamak üzere size geldi; birçok kusurunuzdan da vazgeçiyor. Şu bir gerçek ki, size Allah`tan bir nur, apaçık bir kitap gelmiştir."},{"n":16,"t":"Rızâsını arayanı Allah onunla kurtuluş yollarına iletir ve onları kendi izniyle karanlıklardan aydınlığa çıkarıp dosdoğru bir yola götürür."},{"n":17,"t":"“Eğer Meryem oğlu Îsa`yı, onun annesini ve yeryüzündekilerin hepsini imha etmek isterse, kim Allah`a engel olabilir? Zira göklerin, yerin ve onlar arasında bulunan her şeyin hükümranlığı Allah`a aittir. O, dilediğini yaratır ve Allah her şeye tam manasıyla gücü yetendir.”"},{"n":18,"t":"“Öyle ise günahlarınızdan dolayı size niçin azap ediyor? Doğrusu siz de O`nun yarattığı insanlardansınız. O, dilediğini bağışlar ve dilediğine azap eder. Göklerde, yerde ve ikisinin arasında ne varsa, mülkiyeti Allah`a aittir. Sonunda dönüş de ancak O`nadır.”"},{"n":19,"t":"Ey Ehli kitap! Peygamberlerin arası kesildiği bir sırada size peygamberimiz geldi. Gerçekleri size açıklıyor ki, kıyamette “Bize bir müjdeci ve uyarıcı gelmedi” demeyesiniz. İşte, size müjdeleyici ve uyarıcı gelmiştir. Allah her şeye gücü yetendir."},{"n":20,"t":"Bir zamanlar Mûsâ, kavmine, “Ey kavmim!” demişti, “Allah`ın size bahşettiği nimetleri hatırlayınız; zira O, içinizden peygamber çıkardı ve sizi hükümdarlar kıldı. Dünyada başka hiç kimseye vermediğini size verdi.”"},{"n":21,"t":"“Ey kavmim! Allah`ın size yazdığı mukaddes toprağa giriniz ve arkanıza dönmeyiniz, yoksa kaybederek dönmüş olursunuz.”"},{"n":22,"t":"“Ey Mûsâ! Orada zorba bir halk var; onlar oradan çıkmadıkça biz oraya asla girmeyeceğiz. Eğer oradan çıkarlarsa biz de hemen gireriz.”"},{"n":23,"t":"“Onların üzerine kapıdan giriniz; oraya bir girdiniz mi artık siz zaferi kazanmışsınızdır. Eğer müminler iseniz sadece Allah`a güveniniz.”"},{"n":24,"t":"“Ey Mûsâ! Onlar orada bulunduğu müddetçe biz oraya asla girmeyeceğiz; şu halde sen ve Rabbin gidiniz savaşınız; biz burada oturacağız” dediler."},{"n":25,"t":"Mûsâ, “Rabbim! Ben kendimden ve kardeşimden başkasına hâkim olamıyorum; bizimle bu yoldan çıkmış toplumun arasını ayır” diye yalvardı."},{"n":26,"t":"Allah, “Öyle ise orası, onlara kırk yıl yasaklanmıştır. Yeryüzünde şaşkın şaşkın dolaşacaklar. Artık sen fâsık/yoldan çıkmış toplum için üzülme” dedi."},{"n":27,"t":"Hani birer kurban takdim etmişlerdi de birisinden kabul edilmiş, diğerinden kabul edilmemişti. Kurbanı kabul edilmeyen kardeş, kıskançlık yüzünden, “Andolsun seni öldüreceğim” demişti. Diğeri de, “Allah ancak takvâ sahiplerinden kabul eder” demiş ve şöyle eklemişti:"},{"n":28,"t":"Şu bir gerçek ki ben, âlemlerin Rabbi olan Allah`tan korkarım.”"},{"n":29,"t":"“Ben isterim ki sen, benim günahımı da, senin günahını da yüklenip ateş halkından olasın! Zâlimlerin cezası budur.”"},{"n":30,"t":"Nefsi onu, kardeşini öldürmeye itti; o da nefsine uyarak onu öldürdü, ziyana uğrayanlardan oldu."},{"n":31,"t":"Derken Allah, ona, kardeşinin cesedini nasıl gömeceğini göstermek için yeri eşeleyen bir karga gönderdi; karganın yaptığını görünce, “Yazık bana, şu karga kadar olup da kardeşimin cesedini gömmekten aciz miyim ben?” dedi ve pişman olanlardan oldu!"},{"n":32,"t":"Kim, bir cana veya yeryüzünde bozgunculuk çıkartmaya karşılık olmaksızın, haksız yere bir cana kıyarsa, bütün insanları öldürmüş gibi olur. Her kim bir can kurtarırsa, bütün insanları kurtarmış gibi olur. Peygamberlerimiz onlara apaçık deliller getirdiler; ama bundan sonra da onlardan çoğu yine yeryüzünde aşırıya gitmektedirler."},{"n":33,"t":"Allah`a ve Peygamberi`ne savaş açanların ve yeryüzünde fesadı yaymak için gayret gösterenlerin cezası, ancak ya öldürülmeleri ya asılmaları veya dönekliklerinden dolayı el ve ayaklarının kesilmesi, ya da bulundukları yerden sürülmeleridir. Bu, onların dünyadaki rüsvaylığıdır. Onlar için âhirette de büyük azap vardır."},{"n":34,"t":"Ancak, siz kendilerini yenip ele geçirmeden önce tövbe edenler müstesnadır. Biliniz ki Allah çok bağışlayıcıdır; merhamet sahibidir."},{"n":35,"t":"Ey iman edenler! Allah`a karşı sorumluluğunuzun bilincinde olunuz. O`na daha yakın olmak için bir yol arayınız ve kurtuluşa ermek için O`nun yolunda cihad ediniz."},{"n":36,"t":"Şüphe yok ki kâfirler, yeryüzündeki her şey ve bunun yanında bir o kadarı da kendilerinin olsa, kıyamet gününün azabından kurtulmak için onu fidye verseler, onlardan asla kabul edilmez. Onlar için acı bir azap vardır."},{"n":37,"t":"Ateşten çıkmak isterler, fakat onlar oradan çıkamazlar. Onlar için devamlı bir azap vardır."},{"n":38,"t":"Hırsızlık eden erkek ve kadının, yaptıklarına karşılık bir ceza ve Allah`tan bir ders olmak üzere güçlerini kesiniz. Allah, izzet ve hikmet sahibidir."},{"n":39,"t":"Bu suçu işledikten sonra tövbe edip kendisini ıslâh edene gelince, şüphesiz Allah onun tövbesini kabul eder. Allah, çok bağışlayıcıdır; merhamet sahibidir."},{"n":40,"t":"Bilmez misin ki göklerin ve yerin hükümrânlığı Allah`ındır? O, dilediğini cezalandırır, dilediğini bağışlar. Allah, her şeye gücü yetendir."},{"n":41,"t":"Ey peygamber! Kalpleri inanmamış olduğu halde ağızlarıyla “inandık” diyenlerden ve Yahudilerden inkârda yarışırcasına koşanlar seni üzmesin. Onlar daima yalana ve sana gelmeyenlere kulak verirler. Kelimeleri yerlerinden değiştirirler. “Eğer size şu verilirse hemen alınız, o verilmezse sakınınız” derler. Allah bir kimseyi fitneye düşürmek isterse, Allah`a karşı, onun lehine hiçbir şey yapamazsın. Onlar, Allah`ın, kalplerini temizlemek istemediği kimselerdir. Onlar için dünyada rezillik, âhirette de büyük bir azap vardır."},{"n":42,"t":"Onlar yalanı can kulağı ile dinlerler; haramı tıka basa yerler. Sana geldiklerinde, ister aralarında hüküm ver, ister onlardan yüz çevir. Eğer onlardan yüz çevirirsen, sana hiçbir şekilde zarar veremezler. Ama aralarında hükmedersen, adâletle hükmet! Allah, âdil davrananları sever."},{"n":43,"t":"Onlar, Allah`ın hükümlerini içeren Tevrat`a sahip oldukları halde, nasıl senden hüküm vermeni isterler ve ondan sonra da senin verdiğin hükümlerden yüz çevirirler? Onlar inanmış kimseler değildir."},{"n":44,"t":"Gerçekten Tevrat`ı biz indirdik; onda yol gösterme ve nûr vardır. Teslim olmuş peygamberler, onunla Yahudilere hüküm verirlerdi; kendilerini Tanrı`ya vermiş zâhid ve âbidler de Allah`ın kitabını korumakla görevlendirildiklerinden onunla hüküm verirlerdi ve onu gözetleyip kollarlardı. “Ey Allah`ın kitabına tanık olanlar, insanlardan korkmayınız, benden korkunuz ve benim âyetlerimi az bir paraya satmayınız! Kimler Allah`ın indirdiği ile hükmetmezse işte kâfirler onlardır!”"},{"n":45,"t":"O hak kitabında onlara, “Cana can, göze göz, buruna burun, kulağa kulak, dişe diş ve yaralara karşılık kısas/ödeşme” yazdık. Kim bunu bağışlar, kısâs hakkından vazgeçerse o, kendisi için kefâret olur ve kimler Allah`ın indirdiği ile hükmetmezse zâlimler onlardır!"},{"n":46,"t":"Ardından, o peygamberlerin izleri üzere Meryem oğlu Îsâ`yı gönderdik. Tevrat`tan yanında bulunanı doğruluyordu. Onda hidayet ve ışık olan İncil`i ona verdik. Tevrat`tan yanında olanı doğrulayıcı idi. Doğruya ve güzele kılavuz, takvâya sarılanlara bir öğüttür."},{"n":47,"t":"İncil inanırları, Allah`ın onda indirdiği ile hükmetsinler. Allah`ın indirdiği ile hükmetmeyenler fâsıkların ta kendileridir."},{"n":48,"t":"Ve sana ey peygamber! Gerçekleri ortaya koyan bu kitabı; geçmiş vahiylerden geriye kalan doğruları tasdik edici ve önceki kitaplarda hangi doğruların bulunduğunu kontrol edip, gözetleyici olarak indirdik. Öyleyse ey peygamber! Geçmiş vahyin izleyicileri arasında, Allah`ın indirdiklerine uygun olarak hüküm ver ve sana gelmiş olan hakikatı terk ederek onların arzu ve heveslerine uyma. Biz, her bir toplum için farklı bir sistem ve farklı bir hayat tarzı belirledik. Eğer Allah dileseydi, hepinizi bir tek topluluk yapardı. Ama size verdikleri konusunda, sizi denemek için ayrı ayrı toplumlar olarak yaratmıştır. O halde, hayır işlerinde yarışın. Hepinizin dönüşü Allah`adır. Artık Allah, hakkında ayrılığa düştüğünüz şeyleri size o kıyamette haber verecektir."},{"n":49,"t":"O halde geçmiş vahyin mensupları arasında, Allah`ın indirdiğine göre hüküm ver, onların arzu ve heveslerine uyma, onların sözlerini dikkatle dinle, onlardan sakın ki; Allah`ın sana indirdiği hükümlerin bir kısmını uygulamada seni şaşırtmasınlar. Eğer onlar Allah`ın buyruklarından yüz çevirirlerse bil ki, bir kısım günahlarından dolayı, Allah onları böylece cezalandırmak istiyor. Unutma ki, insanların çoğu hak yoldan çıkan ve ilâhi sınırları aşanlardır."},{"n":50,"t":"Yoksa onlar, câhiliye kanununu nu istiyorlar? İyi anlayanlar için Allah`tan daha iyi kanun koyucu olabilir mi?"},{"n":51,"t":"Ey iman edenler! Yahudileri ve Hıristiyanları dost edinmeyiniz. Çünkü onlar sadece birbirlerinin dostudurlar. İçinizden kim onları vekil edinirse onlardandır. Şüphesiz Allah, zâlimler topluluğuna doğru yolu göstermez."},{"n":52,"t":"Kalplerinde hastalık bulunanların, “Bir felâket gelmesinden korkuyoruz” diyerek, onların arasına koştuklarını görürsün. Belki Allah, fetih ya da kendi katından bir iş getirir de onlar, içlerinde gizlediklerine pişman olurlar."},{"n":53,"t":"O zaman iman edenler, “Bunlar mıdır sizinle beraber olduklarına bütün güçleriyle yemin edenler?” diyeceklerdir. Onların bütün yaptıkları boşa gitmiştir de kaybedenlerden olmuşlardır."},{"n":54,"t":"Ey iman edenler! Sizden kim dininden dönerse, bilsin ki Allah yakında öyle bir toplum getirecek ki, Allah onları sever, onlar da Allah`ı sever. Müminlere karşı alçak gönüllü, kâfirlere karşı güçlü ve şiddetlidirler. Allah yolunda cihad ederler; hiçbir kınayıcının kınamasından korkmazlar. Bu, Allah`ın bir lütfudur, onu dilediğine verir. Allah lütfunda sınırsızdır ve her şeyi bilendir."},{"n":55,"t":"Sizin dostunuz, ancak Allah`tır, peygamberdir ve Allah`ın emirlerine boyun eğerek namazı kılıp zekâtı veren, iman edenlerdir."},{"n":56,"t":"Kim Allah`ı, peygamberini ve inananları dost edinirse bilsin ki, şüphesiz Allah`tan yana olanlar üstün gelirler."},{"n":57,"t":"Ey iman edenler! Sizden önce kendilerine kitap verilenlerden dininizi alay ve oyun konusu edinenleri ve kâfirleri dost edinmeyiniz. Eğer inanıyorsanız Allah`tan sakınınız."},{"n":58,"t":"Namaza çağrıldığınız zaman onu alay ve eğlence konusu yaparlar. Bu davranış, onların düşünmeyen bir toplum olmalarındandır."},{"n":59,"t":"Ey Kitap ehli! Yalnızca Allah`a, bize ve bizden daha önce indirilene inandığımız için mi bizden hoşlanmıyorsunuz? Oysa çoğunuz yoldan çıkmış insanlarsınız."},{"n":60,"t":"Allah katında yeri bundan daha kötü olanı size haber vereyim mi? Allah`ın lanetlediği ve gazap ettiği, aralarından maymunlar, domuzlar ve tâğûta tapanlar çıkardığı kimseler. İşte bunlar, daha kötü olan ve doğru yoldan daha ziyade sapmış bulunanlardır."},{"n":61,"t":"Yanınıza inkârla girip inkârla çıktıkları halde, size geldiklerinde, “inandık” derler. Allah, gizlediklerini daha iyi bilmektedir."},{"n":62,"t":"Onların çoğunun günah işlemede, düşmanlık ve haram yemede yarıştıklarını görürsünüz. Yaptıkları ne kadar kötüdür!"},{"n":63,"t":"Din adamları ve âlimleri, onları günah olan sözleri söylemekten ve haram yemekten menetselerdi ya! İşledikleri ne kötüdür!"},{"n":64,"t":"Yahudiler, “Allah`ın eli bağlıdır/cimridir” dediler. Hay, dedikleri yüzünden elleri bağlanası ve lânet olasılar! Bilâkis, Allah`ın elleri açıktır/cömerttir, dilediği gibi verir. Andolsun ki sana Rabbinden indirilen, onlardan çoğunun azgınlığını ve küfrünü arttırır. Aralarına, kıyamete kadar düşmanlık ve kin soktuk. Ne zaman savaş için bir ateş yakmışlarsa, Allah onu söndürmüştür. Onlar yeryüzünde bozgunculuğa koşarlar; Allah ise bozguncuları sevmez."},{"n":65,"t":"Eğer kitap ehli iman edip kötülüklerden sakınsalardı, elbette kötülüklerini örter ve onları naîm cennetlerine koyardık."},{"n":66,"t":"Eğer onlar Tevrat`ı, İncil`i ve Rabblerinden onlara indirileni doğru dürüst uygulasalardı, elbette hem üstlerinden/gökten hem de ayaklarının altlarından/yerden yerlerdi. Onlardan aşırılığa kaçmayan bir zümre vardır, fakat çoğunun yaptıkları ne kötüdür!"},{"n":67,"t":"Ey Peygamber! Rabbinden sana indirileni tebliğ et! Eğer bunu yapmazsan, O`nun peygamberliğini yapmamış olursun. Allah, seni insanlardan koruyacaktır. Doğrusu Allah, kâfirler topluluğuna rehberlik etmez."},{"n":68,"t":"“Ey kitap ehli! Siz Tevrat`ı, İncil`i ve Rabbinizden size indirileni hakkıyla uygulamadıkça bir şey üzerinde değilsinizdir.” Rabbinden sana indirilen, onlardan çoğunun inkâr ve azgınlığını elbette arttıracaktır. Kâfirler topluluğuna üzülme!"},{"n":69,"t":"İman edenlerle Yahudiler, Hıristiyanlar ve Sâbiîlerden Allah`a ve âhiret gününe inanıp iyi amel işleyenler üzerine asla korku yoktur, onlar üzülecek de değillerdir."},{"n":70,"t":"Gerçek şu ki, biz İsrâiloğulları`ndan kesin bir söz aldık ve onlara peygamberler gönderdik. Ne zaman bir peygamber onlara nefislerinin arzu etmediğini getirdiyse, bir kısmını yalanladılar, bir kısmını da öldürdüler."},{"n":71,"t":"Bir fitne kopmayacak sandılar da kör ve sağır kesildiler. Sonra Allah onların tövbesini kabul etti. Sonra yine çokları kör ve sağır kesildiler. Allah yaptıklarını görüyor."},{"n":72,"t":"“Ey İsrâiloğulları! Benim Rabbim ve sizin Rabbiniz olan Allah`a kulluk ediniz; zira kim Allah`a ortak koşarsa muhakkak ki Allah ona cenneti haram etmiştir ve onun varacağı yer ateştir; zâlimlerin yardımcıları yoktur!”"},{"n":73,"t":"“Allah, üçün üçüncüsüdür” diyenler elbette kâfir olmuşlardır. Oysa yalnız bir tek Tanrı vardır, başka Tanrı yoktur. Bu dediklerinden vazgeçmezlerse, elbette onlardan inkâr edenlere acı bir azap dokunacaktır."},{"n":74,"t":"Hâlâ Allah`a tövbe edip O`ndan af dilemiyorlar mı? Allah bağışlayandır; merhamet edendir."},{"n":75,"t":"Meryem oğlu Mesih, ancak bir peygamberdir. Ondan önce de peygamberler gelip geçmişti. Annesi de dosdoğruydu. İkisi de yemek yerlerdi. Bak, onlara nasıl âyetlerimizi açıklıyoruz, sonra bak nasıl haktan çevriliyorlar?"},{"n":76,"t":"Allah`ı bırakıp size zarar ve yarar vermeye gücü yetmeyen şeylere mi tapıyorsunuz? Oysa Allah işitendir; bilendir."},{"n":77,"t":"“Ey kitap ehli! Dininizde haksız yere haddi aşmayınız. Daha önceden sapan, birçoklarını saptıran ve yolun doğrusundan uzaklaşan bir topluma uymayınız.”"},{"n":78,"t":"İsrâiloğulları`ndan kâfir olanlar, Dâvûd ve Meryem oğlu Îsâ diliyle lânetlenmişlerdir. Bunun sebebi, söz dinlememeleri ve sınırı aşmalarıdır."},{"n":79,"t":"Onlar, işledikleri kötülükten birbirlerini vazgeçirmeye çalışmazlardı. Andolsun, yaptıkları ne kötüdür!"},{"n":80,"t":"Onlardan çoğunun, inkâr edenlerle dostluk ettiklerini görürsün. Nefislerinin onlar için önceden hazırladığı şey ne kötüdür! Allah onlara gazap etmiştir ve onlar azap içinde devamlı kalıcıdırlar."},{"n":81,"t":"Eğer onlar Allah`a, peygambere ve ona indirilene iman etmiş olsalardı, kâfirleri dost edinmezlerdi; fakat onların çoğu fâsıktır."},{"n":82,"t":"İnsanlar içinde iman edenlere düşmanlık bakımından en şiddetli olarak Yahudiler ile şirk koşanları bulacaksın. Onlar içinde iman edenlere sevgi bakımından en yakın olarak da, “Biz Hıristiyanlarız” diyenleri bulacaksın. Çünkü onların içinde keşişler ve rahipler vardır ve onlar kibre kapılmazlar."},{"n":83,"t":"“Ey Rabbimiz! İman ettik; bizi şâhit olanlarla beraber yaz!”"},{"n":84,"t":"“Rabbimizin bizi dürüst ve erdemliler arasına katmasını o kadar şiddetle arzuladığımız halde, nasıl Allah`a ve bize indirilen hakikate inanmakta zaaf gösterebilirdik?”"},{"n":85,"t":"bu, iyilik yapanların ödülüdür;"},{"n":86,"t":"İnkâr eden ve âyetlerimizi yalanlayanlara gelince, işte onlar yakıcı ateşe mahkûmdurlar."},{"n":87,"t":"Ey iman edenler! Allah`ın size helâl kıldığı iyi ve temiz şeyleri haram kılmayınız ve sınırı aşmayınız. Allah sınırı aşanları sevmez."},{"n":88,"t":"Allah`ın size verdiği rızıklardan helâl ve temiz olarak yiyiniz ve inandığınız Allah`tan sakınınız."},{"n":89,"t":"Allah sizi, kasıtsız olarak yaptığınız yeminlerden dolayı sorumlu tutmaz. Fakat bilerek yaptığınız yeminlerden dolayı sizi sorumlu tutar. Bunun kefâreti, ailenize yedirdiğiniz yemeğin orta hallisinden on fakire yedirmek yahut onları giydirmek ya da bir köle âzat etmektir. Bunları bulamayan kişi üç gün oruç tutmalıdır. Yemin ettiğiniz takdirde, yeminlerinizin kefâreti işte budur. Yeminlerinizi koruyunuz. Allah size âyetlerini açıklıyor; umulur ki şükredersiniz."},{"n":90,"t":"Ey İnananlar! Alkol, kumar, dikili taşlar, fal okları şeytan işi birer pisliktir. Bunlardan kaçınınız ki kurtuluşa eresiniz."},{"n":91,"t":"Şeytan, alkol ve kumar ile, aranıza düşmanlık ve kin sokmak, sizi Allah`ı anmaktan ve namazdan alıkoymak istiyor. Artık bunlardan vazgeçecek misiniz?"},{"n":92,"t":"Allah`a ve peygambere itâat ediniz, kötü şeylerden sakınınız. Eğer gösterdiğimiz yoldan dönerseniz, biliniz ki peygamberimize düşen, açıkça tebliğ etmektir."},{"n":93,"t":"İnanıp iyi işler yapanlara, bundan böyle kötülüklerden korunup inandıkları ve iyi işler yaptıkları, sonra korunup inandıkları, sonra yine korunup iyilik ettikleri takdirde, daha önce yediklerinden ötürü bir günah yoktur. Allah, güzel davrananları sever."},{"n":94,"t":"Ey iman edenler! Allah sizi ellerinizin ve mızraklarınızın erişeceği bir av ile dener ki, gizlide kendisinden kimin korktuğunu bilsin. Kim bundan sonra sınırı aşarsa onun için acı bir azap vardır."},{"n":95,"t":"Ey iman edenler! İhramda iken avlanmayınız. Sizden kim avı kasten öldürürse, öldürdüğü hayvanın dengi bir cezası vardır. Buna, Kâbe`ye varacak bir kurban olmak üzere, içinizden adâlet sahibi iki kişi hükmeder. Yahut fakirleri doyurmaktan ibaret bir kefârettir; ya da onun dengi oruç tutmaktır. Ta ki böylece o insan, yaptığı işin cezasını çekmiş olsun. Allah geçmişi affetmiştir. Kim bu suçu tekrar işlerse, Allah ondan öç alır. Allah daima galiptir; intikam alandır."},{"n":96,"t":"Hem size hem de yolculara faydalanmanız için denizde avlanmak ve onu yemek size helâl kılındı. İhramlı iken size kara avı yasaklandı. Huzuruna toplanacağınız Allah`tan sakınınız."},{"n":97,"t":"Allah, Kâbe`yi, o saygıya lâyık evi, insanlar için maddî ve mânevî yönden bellerini doğrultmalarına sebep kıldı. O saygı değer ayı, kurbanı, boynu bağlı kurbanlıkları da böyle yaptı ki Allah`ın, göklerde ve yerde olanları ve her şeyi bilen olduğunu anlayasınız."},{"n":98,"t":"İyi biliniz ki, Allah`ın cezası çetindir. Allah affedicidir; merhamet edicidir."},{"n":99,"t":"Peygamber, tebliğ etmekten başka bir şeyle yükümlü değildir. Allah, sizin açıktan yaptığınız her şeyi ve bütün gizlediklerinizi bilir."},{"n":100,"t":"“Pisliğin çokluğu seni hayrete düşürse bile, pisle temiz bir olmaz. Öyle ise ey akıl sahipleri! Allah`tan sakınınız ki, kurtuluşa eresiniz.”"},{"n":101,"t":"Ey iman edenler! Açıklandığı zaman hoşunuza gitmeyecek şeyleri sormayınız. Eğer Kur`ân indirilirken onları sorarsanız, size açıklanır. Açıklamadığına göre Allah onları affetmiştir. Zira Allah çok bağışlayıcıdır; yumuşak davranandır."},{"n":102,"t":"Sizden önceki insanlar da böyle sorular sormuş ve sonuçta onları inkâr etmişlerdi."},{"n":103,"t":"Allah bahîre, sâibe, vasîle ve hâm diye bir şey yapmamıştır. Fakat inkârcılar, kendi uydurdukları yalanları Allah`a yakıştırırlar ve onların birçoğu akıllarını asla kullanmazlar."},{"n":104,"t":"Onlara, “Allah`ın indirdiğine ve peygamberine geliniz” denildiğinde, “Babalarımızı üzerinde bulduğumuz yol bize yeter” derler. Ataları hiçbir şey bilmiyor ve doğru yol üzerinde bulunmuyor iseler de mi?"},{"n":105,"t":"Ey iman edenler! Siz kendinize bakınız. Siz doğru yolda olunca, sapan kimseler size zarar veremez. Hepinizin dönüşü Allah`adır. Artık O size yaptıklarınızı haber verecektir."},{"n":106,"t":"Ey iman edenler! Birinize ölüm gelip çatınca, vasiyet esnasında içinizden iki âdil kişi aranızda şâhitlik etsin. Yahut seferde iken başınıza ölüm musibeti gelmişse, sizden olmayan başka iki kişi şâhit olsun. Eğer şüpheye düşerseniz, o iki şahidi namazdan sonra alıkor, “Bu vasiyet karşılığında hiçbir şeyi satın almayacağız, akraba menfaatine de olsa Allah`ın şahitliğini saklamayacağız; çünkü böyle yaparsak elbette günahkârlardan oluruz” diye Allah`a yemin ettirirsiniz."},{"n":107,"t":"Bu şâhitlerin sonradan yalan söyleyerek bir günah kazandıkları anlaşılırsa, haklarına şâhitlerin tecavüz ettiği ölüye daha yakın olan mirasçılardan iki kişi onların yerini alır ve “Andolsun ki bizim şâhitliğimiz onların şâhitliğinden daha gerçektir ve biz kimsenin hakkına tecavüz etmeyeceğiz, aksi takdirde biz, elbette zâlimlerden oluruz” diye Allah`a yemin ederler."},{"n":108,"t":"Bu usûl, şâhitliği gerektiği şekilde yapmaya, yahut yeminlerinden sonra yeminlerin mirasçılar tarafından reddedilmesinden korkmalarına çare olarak daha uygundur. Allah`tan sakınınız ve O`nu dinleyiniz. Allah fâsıklar topluluğuna rehberlik etmez."},{"n":109,"t":"Allah, peygamberleri bir araya getirip de, “Size ne cevap verildi?” dediği gün, “Bizim hiçbir bilgimiz yok; gizlilikleri hakkı ile bilen ancak sensin” diyeceklerdir."},{"n":110,"t":"“Ey Meryem oğlu Îsâ! Sana ve annene verdiğim nimetimi hatırla! Hani seni mukaddes ruh/Cebrâil ile desteklemiştim; bu sayede sen beşikte iken yetişkin çağdaki insanlarla konuşuyordun. Sana kitabı okuyup yazmayı, hikmeti, Tevrat ve İncil`i öğretmiştim. Benim iznimle çamurdan kuş şeklinde bir şey yapıyordun da ona üflüyordun, hemen benim iznimle o bir kuş oluyordu. Yine benim iznimle anadan doğma körü ve alacalıyı iyileştiriyordun. Ölüleri benim iznimle hayata getiriyordun. Hani İsrâiloğulları`nı seni öldürmekten engellemiştim; kendilerine apaçık deliller, mucizeler getirdiğin zaman, içlerinden inkâr edenler, ‘Bu apaçık bir sihirden başka bir şey değildir` demişlerdi.”"},{"n":111,"t":"Hani havârîlere, “Bana ve peygamberime iman ediniz” diye ilham etmiştim. Onlar da “İman ettik, bizim Allah`a teslim olmuş kimseler olduğumuza sen de şâhit ol” demişlerdi."},{"n":112,"t":"Hani havârîler, “Ey Meryem oğlu Îsâ! Rabbin bize gökten donatılmış bir sofra indirebilir mi?” demişlerdi. O, “İman etmiş kimseler iseniz, Allah`tan sakınınız” cevabını vermişti."},{"n":113,"t":"Onlar, “Ondan yiyelim, kalplerimiz doyuma ulaşsın; bize doğru söylediğini bilelim ve ona gözleriyle görmüş şâhitler olalım istiyoruz” demişlerdi."},{"n":114,"t":"“Ey Rabbimiz! Bize gökten bir sofra indir, Havarilerle bana, şu anki nesillerimize ve gelecekteki nesillerimize bir bayram ve senden bir delil olsun. Bizi rızıklandır; zaten sen, rızık verenlerin en cömerdisin.”"},{"n":115,"t":"“Şüphesiz ben onu size indireceğim, ama bundan sonra içinizden kim inkâr ederse, kâinatta hiçbir kimseye etmediğim azabı ona edeceğim.”"},{"n":116,"t":"“Hâşâ! Seni tenzih ederim, hakkım olmayan şeyi söylemek bana yakışmaz. Bunu söylemiş olsaydım sen muhakkak bilirdin! Sen benim içimdeki her şeyi bilirsin, halbuki ben senin zâtında olanı bilmem. Gizlilikleri eksiksiz bilen yalnızca sensin!”"},{"n":117,"t":"“Ben onlara, ancak bana emrettiğini söyledim. ‘Benim de rabbim, sizin de rabbiniz olan Allah`a kulluk ediniz` dedim. İçlerinde bulunduğum müddetçe onlar üzerinde kontrolcü idim. Beni vefat ettirince, artık onlar üzerinde gözetleyici yalnız sen oldun. Sen her şeyi hakkı ile görensin.”"},{"n":118,"t":"“Eğer kendilerine azap edersen, şüphesiz onlar senin kullarındır. Eğer onları bağışlarsan, şüphesiz sen izzet ve hikmet sahibisin.”"},{"n":119,"t":"“Bu, doğrulara, doğruluklarının fayda vereceği gündür. Onlara, içinde süreli kalacakları, içinden ırmaklar akan cennetler vardır. Allah onlardan razı olmuştur, onlar da O`ndan razı olmuşlardır. İşte büyük kurtuluş budur.”"},{"n":120,"t":"Göklerin, yerin ve içlerindeki her şeyin mülkiyeti Allah`ındır. O, her şeye hakkıyla gücü yetendir."}],[{"n":1,"t":"Her türlü övgü, gökleri ve yeri yaratan, karanlıkları ve aydınlığı var eden Allah`a aittir. Bunca delilden sonra hakikati inkâr edenler, başka güçleri Rabbleri ile denk tutarlar."},{"n":2,"t":"Sizi balçıktan yaratan ve sonra sizin için bir ömür tayin eden O`dur. Bir de O`nun katında belirli bir ömür/ecel vardır. Fakat siz hâlâ şüphe edip duruyorsunuz."},{"n":3,"t":"O, göklerde ve yerde tek Allah`tır. Sizin içinizi de dışınızı da bilir. Ne kazanacağınızı da bilir."},{"n":4,"t":"Rabblerinin âyetlerinden onlara bir âyet gelmeyedursun; o âyetlerden yüz çevirirler."},{"n":5,"t":"Gerçekten onlar, kendilerine hak geldiğinde, onu yalanlamışlardı. Fakat yakında onlara, alay ettikleri şeyin haberleri gelecektir."},{"n":6,"t":"Onlardan önce nice nesilleri yok ettiğimizi görmezler mi? Size vermediğimiz bütün imkânları kendilerine verdiğimiz, gökten üzerlerine bol bol yağmurlar indirip evlerinin altından ırmaklar akıttığımız toplumları, günahları sebebiyle helâk ettik ve onların ardından başka nesiller yarattık."},{"n":7,"t":"Eğer sana kâğıt üzerine yazılmış bir kitap indirseydik de onlar elleriyle ona dokunmuş olsalardı, yine de o inkâra batmış olanlar, “Bu, apaçık büyüden başka bir şey değildir” derlerdi."},{"n":8,"t":"“Ona bir melek gönderilmeli değil miydi?” dediler. Eğer biz öyle bir melek indirseydik, elbette iş bitirilmiş olur, artık kendilerine göz bile açtırılmazdı."},{"n":9,"t":"Eğer peygamberi bir melek kılsaydık, elbette onu insan sûretine sokar, onları yine düşmekte oldukları kuşkuya düşürürdük."},{"n":10,"t":"Senden önce de peygamberlerle alay edilmişti. Ancak onlardan alay edenleri alaya almış oldukları şey çepeçevre kuşattı."},{"n":11,"t":"“Yeryüzünde dolaşınız ve hakikati yalanlayanların sonlarının ne olduğunu görünüz.”"},{"n":12,"t":"“Rahmeti ve şefkati kendisine ilke edinen Allah`a aittir. Sizi varlığında şüphe olmayan kıyamet gününde elbette toplayacaktır. Kendilerini ziyana sokanlar var ya, işte onlar inanmazlar.”"},{"n":13,"t":"Gece ve gündüzde barınan her şey O`nundur. O her şeyi işitendir; bilendir."},{"n":14,"t":"“Bana, Müslüman olanların ilki olmam ve müşriklerden olmamam emredildi.”"},{"n":15,"t":"“Eğer Rabbime isyan edersem, büyük bir günün azabından korkarım.”"},{"n":16,"t":"O gün kendisinden azap uzaklaştırılana, Allah, rahmetini bağışlamış olur. Bu da apaçık bir kurtuluş olacaktır."},{"n":17,"t":"Eğer Allah başına bir musibet verirse onu O`ndan başka hiç kimse gideremez. Eğer sana bir iyilik verirse, kuşkusuz O`nun gücü her şeye yeter."},{"n":18,"t":"Zira kullarının üzerine otorite sahibi sadece O`dur. O, hikmet sahibidir; her şeyden haberdardır."},{"n":19,"t":"“O sadece tek bir tanrıdır ve ben sizin ortak koştuğunuz şeylerden uzağım.”"},{"n":20,"t":"Kendilerine kitap verdiklerimiz, Peygamberi kendi oğullarını tanıdıkları gibi tanırlar. Kendilerini ziyan edenler var ya, işte onlar inanmazlar."},{"n":21,"t":"Allah`a yalan uyduran ya da O`nun âyetlerini yalanlayanlardan daha zâlim kim olabilir? Şüphesiz zâlimler kurtuluşa eremezler."},{"n":22,"t":"Bir gün onların hepsini bir araya toplayacağız. Sonra da, Allah`a ortak koşanlara, “Nerede boş yere davasını güttüğünüz ortaklarınız?” diyeceğiz."},{"n":23,"t":"“Rabbimiz Allah`a yemin olsun ki, ortak koşanlardan değildik.”"},{"n":24,"t":"Bak da gör, öz benliklerine karşı nasıl yalan söylediler! İftirâ için kullandıkları şeyler, kendilerinden nasıl kaybolup gitti!"},{"n":25,"t":"İçlerinden seni dinleyenler vardır; fakat biz onu anlamalarına engel olmak için kalplerinin üstüne kılıflar, kulaklarının içine de ağırlık koyduk. Onlar her mucizeyi görseler de yine ona inanmazlar. Hatta sana geldiklerinde, seninle tartışırlar. O kâfirler, “Bu, eskilerin masallarından başka bir şey değildir” derler."},{"n":26,"t":"Onlar hem insanları peygambere yaklaşmaktan vazgeçirmeye çalışırlar, hem de kendileri ondan uzaklaşırlar. Ama bu şekilde, yalnız kendilerini mahvederler de, üstelik bunun da farkında olmazlar."},{"n":27,"t":"Ateşin başında durdurulmuş iken onların, “Ah ne olurdu, keşke biz dünyaya geri çevrilseydik de Rabbimizin âyetlerini yalanlamasaydık, inananlardan olsaydık!” dediklerini bir görsen!"},{"n":28,"t":"Hayır! Daha önce gizlemekte oldukları şeyler kendilerine göründü. Eğer dünyaya geri gönderilseler, yine kendilerine yasak edilen şeylere döneceklerdir. Zira onlar gerçekten yalancıdırlar."},{"n":29,"t":"Onlar, “Hayat ancak bu dünyadaki hayatımızdan ibarettir; biz, bir daha da dirilecek değiliz” demişlerdi."},{"n":30,"t":"Rabblerinin huzuruna getirildikleri zaman sen onları bir görsen! Allah onlara, “Öldükten sonra dirilme doğru değil miymiş?” diyecek. Onlar, “Rabbimize andolsun ki evet!” diyecekler. Allah da, “Öyleyse inkâr ettiğinizden dolayı azabı tadın!” diyecek."},{"n":31,"t":"“Dünyada iyi amelleri terk etmemizden dolayı vay halimize!” Dikkat ediniz! Taşıdıkları şey ne kötüdür!"},{"n":32,"t":"Dünya hayatı bir oyun ve eğlenceden başka bir şey değildir. Sakınanlar için âhiret yurdu elbette ki daha hayırlıdır. Hâlâ aklınızı kullanmayacak mısınız?"},{"n":33,"t":"Onların söylediği şeylerin seni üzdüğünü biliyoruz. Gerçekte onlar seni yalanlamıyorlar, fakat o zâlimler, bile bile Allah`ın âyetlerini inkâr ediyorlar."},{"n":34,"t":"Senden önce de peygamberler yalanlanmıştı. Yalanlanmalarına ve eziyet edilmelerine sabrettiler, nihayet onlara yardımımız yetişti. Allah`ın kelimelerini değiştirebilecek kimse yoktur. Sana da peygamberlerin haberinden bir parça gelmiştir."},{"n":35,"t":"Eğer onların yüz çevirmesi sana ağır geldiyse, haydi yerin içine bir tünel aç, ya da göğe bir merdiven daya ki, onlara bir mucize getiresin. Allah dileseydi, elbette onları hidayet üzerinde toplardı. O halde câhillerden olma!"},{"n":36,"t":"Ancak samimiyetle dinleyenler çağrıyı kabul eder. Ölülere gelince, Allah onları diriltecek, sonra da O`na döndürüleceklerdir."},{"n":37,"t":"“Şüphesiz, Allah bir mucize indirmeye kadirdir. Fakat onların çoğu bilmiyorlar.”"},{"n":38,"t":"Yerde yürüyen ne kadar hayvan, kanatlarıyla uçan ne kadar kuş varsa, bütün bunlar sizin gibi birer topluluktur. Biz kitapta hiçbir şeyi eksik bırakmadık. Onlar sonunda Rabbleri önünde toplanırlar."},{"n":39,"t":"Bizim âyetlerimizi yalanlayanlar, karanlıklara gömülmüş sağır ve dilsizlerdir. Allah, sapmayı dileyeni saptırır; doğru yola girmeyi dileyeni de doğru yola yöneltir."},{"n":40,"t":"“Ne dersiniz, size Allah`ın azabı gelse veya o kıyamet gelip çatıverse siz, Allah`tan başkasına mı yalvarırsınız? Doğru sözlü iseniz söyleyin bakalım!”"},{"n":41,"t":"Hayır, yalnız O`na yalvarırsınız da, O dilerse, yakındığınız belâyı uzaklaştırır. Siz, ortak koştuklarınızı unutuverirsiniz."},{"n":42,"t":"Senden önce de milletlere peygamberler göndermiştik. Boyun eğsinler diye onları darlık ve sıkıntıya uğrattık."},{"n":43,"t":"Hiç olmazsa kendilerine böyle baskımız geldiği zaman boyun eğselerdi! Fakat kalpleri iyice katılaştı ve şeytan da onlara yaptıklarını cazip/süslü gösterdi."},{"n":44,"t":"Kendilerine yapılan uyarıları unuttuklarında, üzerlerine her şeyin kapılarını açıverdik. Nihayet, kendilerine verilenler yüzünden şımardıkları sırada onları ansızın yakaladık, birden bire bütün umutlarını yitirdiler."},{"n":45,"t":"Böylece, zulmeden toplumun kökü kesildi. Övgü, âlemlerin Rabbi Allah`a aittir."},{"n":46,"t":"“Ne sanıyorsunuz? Eğer Allah kulaklarınızı sağır, gözlerinizi kör eder, kalplerinizi de mühürlerse, size bunları Allah`tan başka kim geri verebilir? Bakınız, delilleri nasıl açıklıyoruz. Onlar hâlâ yüz çeviriyorlar!”"},{"n":47,"t":"“Söyler misiniz? Size Allah`ın azabı ansızın veya açıkça gelirse, zâlim toplumdan başkası mı helâk olur?”"},{"n":48,"t":"Biz peygamberleri, sadece müjdeleyici ve uyarıcılar olarak göndeririz. Kimler inanır ve uslanırsa, onlara korku yoktur ve onlar üzülmeyeceklerdir."},{"n":49,"t":"Âyetlerimizi yalanlayanlara gelince, yoldan çıkmalarından dolayı azaba çarptırılacaklardır."},{"n":50,"t":"“Kör ile gören hiç bir olur mu? Hâlâ düşünmüyor musunuz?”"},{"n":51,"t":"Rabblerinin huzurunda toplanacaklarından korkanları, Kur`ân ile uyar! Onlar için Rabblerinden başka ne bir dost ne de bir aracı vardır; belki sakınırlar."},{"n":52,"t":"Rabblerinin rızâsını isteyerek sabah akşam O`na yalvaranları yanından kovma! Onların hesabından sana bir sorumluluk, senin hesabından da onlara herhangi bir sorumluluk yoktur ki, onları kovup da zâlimlerden olasın."},{"n":53,"t":"“Aramızda Allah`ın kendilerine lütuf ve ihsanda bulunduğu kimseler de bunlar mı?” demeleri için onların bir kısmını diğerleriyle işte böyle imtihan ettik. Allah şükredenleri hakkıyla değil midir?"},{"n":54,"t":"Âyetlerimize inananlar sana geldiğinde, onlara de ki; “Selâm size! Rabbiniz rahmet ve şefkati kendisine ilke edindi. Gerçek şu ki, sizden kim bilmeyerek bir kötülük yapar, ardından tövbe edip de kendini ıslah ederse, bilsin ki Allah, çok bağışlayandır; çok merhamet edendir.”"},{"n":55,"t":"Böylece suçluların yolu belli olsun diye âyetleri iyice açıklıyoruz."},{"n":56,"t":"“Ben sizin arzularınıza uymam; aksi halde sapıtırım da, hidayete erenlerden olmam.”"},{"n":57,"t":"“Şüphesiz ben Rabbimden gelen apaçık bir kanıta dayanmaktayım ve siz onu yalanlamış oluyorsunuz. Çabucak gelmesini istediğiniz azap, benim yanımda değildir. Hüküm ancak Allah`ındır. O, hakkı anlatır ve en iyi hüküm veren O`dur."},{"n":58,"t":"“Acele istediğiniz şey benim elimde olsaydı, elbette benimle sizin aranızda iş bitirilmişti. Allah, zâlimleri hakkıyla bilir.”"},{"n":59,"t":"Gaybın anahtarları Allah`ın yanındadır; onları O`ndan başkası bilemez. O, karada ve denizde ne varsa bilir. O`nun ilmi dışında bir yaprak bile düşmez. Yerin karanlıkları içindeki tek bir tane, yaş ve kuru ne varsa hepsi apaçık bir kitaptadır."},{"n":60,"t":"Geceleyin sizi öldüren, gündüzün de ne işlediğinizi bilen, sonra belirlenmiş ecel tamamlansın diye gündüzün sizi dirilten O`dur. Sonra dönüşünüz yine O`nadır. Ardından O, yaptıklarınızı size haber verecektir."},{"n":61,"t":"O, kullarının üstünde yegâne kudret ve tasarruf sahibidir. Size koruyucular gönderir. Nihayet birinize ölüm geldi mi, elçilerimiz onun canını alırlar. Onlar vazifede kusur etmezler."},{"n":62,"t":"Sonra insanlar gerçek sahipleri olan Allah`a döndürülürler. Bilesiniz ki, hüküm yalnız O`nundur ve O, hesap görenlerin en çabuğudur."},{"n":63,"t":"‘Eğer bizi bundan kurtarırsan and olsun şükredenlerden olacağız` diye dua edersiniz.”"},{"n":64,"t":"“Ondan ve bütün sıkıntılardan sizi Allah kurtarır. Sonra siz yine O`na ortak koşarsınız.”"},{"n":65,"t":"“Allah`ın size üstünüzden/gökten veya ayaklarınızın altından/yerden bir azap göndermeye ya da birbirinize düşürüp kiminize kiminizin hıncını tattırmaya gücü yeter.” Bak, anlasınlar diye âyetlerimizi nasıl açıklıyoruz!"},{"n":66,"t":"“Ben size vekil değilim.”"},{"n":67,"t":"Her haber, belli bir süreç içinde gerçekleşir. Siz, zaman içinde anlayacaksınız."},{"n":68,"t":"Âyetlerimiz hakkında ileri-geri konuşanları gördüğünde, onlar başka bir söze dalıncaya kadar onlardan uzak dur! Eğer şeytan sana unutturur da onlarla oturursan, hatırladıktan sonra artık o zâlimler topluluğu ile oturma!"},{"n":69,"t":"Takvâ sahiplerine, inanmayanların hesabından herhangi bir sorumluluk yoktur. Fakat korunurlar diye hatırlatmak gerekir."},{"n":70,"t":"Dinlerini bir oyuncak ve bir eğlence edinen ve dünya hayatının aldattığı kimseleri bırak! Kazandıkları sebebiyle hiçbir nefsin felâkete dûçar olmaması için Kur`ân ile öğüt ver! O kimse için Allah`tan başka ne dost vardır, ne de şefaatçi. O, bütün varını fidye olarak verse, yine de ondan kabul edilmez. Onlar kazandıkları günahlar yüzünden helâke sürüklenmişlerdir. İnkâr ettiklerinden dolayı onlar için kaynar sudan ibaret bir içecek ve elem verici bir azap vardır."},{"n":71,"t":"“Allah`ın gösterdiği yol, doğru yolun ta kendisidir ve biz âlemlerin Rabbine teslim olmakla emr olunduk.”"},{"n":72,"t":"“Namazı kılınız, Allah`a saygı duyunuz” diye de emrolunduk. O, huzuruna varıp toplanacağımız Allah`tır."},{"n":73,"t":"O, gökleri ve yeri bir amaç uğruna yaratandır. “Ol” dediği gün her şey oluşmaya başlar. O`nun sözü gerçektir. Sûr`a üflendiği gün de hükümrânlık O`nundur. Gizliyi ve âşikâr olanı bilendir. O, tam hikmet sahibidir ve her şeyden haberdardır."},{"n":74,"t":"“Sen putları tanrı mı ediniyorsun? Doğrusu ben, seni ve kavmini açık bir sapıklık içinde görüyorum.”"},{"n":75,"t":"Böylece biz İbrâhim`e, kesin inananlardan olsun diye göklerin ve yerin melekûtunu/ kainatın işleyiş kanunlarını gösteriyorduk."},{"n":76,"t":"“Budur rabbim” dedi. Yıldız batınca, “Batanları sevmem” dedi."},{"n":77,"t":"“Budur rabbim” dedi. O da batınca, “Rabbim bana doğru yolu göstermeseydi, elbette sapan topluluktan olurdum” dedi."},{"n":78,"t":"“Ey kavmim! Ben sizin Allah`a ortak koştuğunuz şeylerden uzağım.”"},{"n":79,"t":"“Ben, benliğimi tamamen gökleri ve yeri yoktan var edene çevirdim ve artık ben Ona ortak koşanlardan değilim!”"},{"n":80,"t":"“Beni doğru yola iletmiş iken Allah hakkında benimle tartışıyor musunuz? Ben sizin O`na ortak koştuğunuz şeylerden korkmam; ancak Rabbimin dilediği olur! Rabbim, bilgisi ile her şeyi kuşatmıştır. Hâlâ kendinize gelip öğüt almıyor musunuz?”"},{"n":81,"t":"“Hem siz, tanrı oldukları hakkında Allah`ın size hiçbir delil indirmediği şeyleri, O`na ortak koşmaktan korkmuyorsunuz da, ben nasıl sizin O`na ortak koştuğunuz şeylerden korkarım? Şimdi biliyorsanız söyleyiniz, iki topluluktan hangisi, tek Allah`a inananlar mı, yoksa Allah`a ortak koşanlar mı güvende olmaya daha lâyıktır?”"},{"n":82,"t":"İnanıp da imanlarına herhangi bir şirki bulaştırmayanlar var ya, işte güven onlarındır ve onlar doğru yolu bulanlardır."},{"n":83,"t":"İşte bu, kavmine karşı İbrâhim`e verdiğimiz delillerimizdir. Dilediğimiz kimselerin derecelerini yükseltiriz. Şüphesiz ki senin Rabbin hikmet sahibidir; hakkıyla bilendir."},{"n":84,"t":"Biz ona İshâk ve Yâkub`u da armağan ettik; hepsini de doğru yola ilettik. Daha önce de Nûh`u ve onun soyundan Dâvud`u, Süleymân`ı, Eyyûb`u, Yûsuf`u, Mûsâ`yı ve Hârun`u doğru yola iletmiştik. Biz iyi davrananları işte böyle ödüllendiririz."},{"n":85,"t":"Zekeriyyâ, Yahyâ, Îsâ ve İlyâs`ı da doğru yola iletmiştik. Hepsi de iyilerden idi."},{"n":86,"t":"İsmâil, Elyesa‘, Yûnus ve Lût`u da hidayete erdirdik. Hepsini âlemlere üstün kıldık."},{"n":87,"t":"Onların babalarından, çocuklarından ve kardeşlerinden bazılarına da üstün meziyetler verdik. Onları seçkin kıldık ve doğru yola ilettik."},{"n":88,"t":"İşte bu, Allah`ın hidayetidir, kullarından dileyeni ona iletir. Eğer onlar da Allah`a ortak koşsalardı, yapmakta oldukları amelleri elbette boşa giderdi."},{"n":89,"t":"İşte onlar, kendilerine kitap, hikmet ve peygamberlik verdiğimiz kimselerdir. Eğer kâfirler bunları inkâr ederlerse, şüphesiz, yerlerine bunları inkâr etmeyecek bir toplum getiririz."},{"n":90,"t":"“Ben buna karşılık sizden bir ücret istemiyorum. Bu, âlemler için sadece bir öğüttür.”"},{"n":91,"t":"“Öyle ise Mûsâ`nın insanlara bir nûr ve hidayet olarak getirdiği kitabı kim indirdi? Siz onu kâğıtlara yazıp açıklıyor, çoğunu da gizliyorsunuz. Sizin de atalarınızın da bilemediği şeyler, size öğretilmiştir.” Sen, “Allah” de, sonra onları bırak, daldıkları bataklıkta debelenip dursunlar!"},{"n":92,"t":"Bu da, şehirlerin anası olan Mekke`yi ve çevresini uyarman için sana indirdiğimiz, feyiz kaynağı ve kendinden öncekini doğrulayan bir kitaptır. Âhirete inananlar ona da inanırlar, namazlarına devam ederler."},{"n":93,"t":"“Çıkarın canlarınızı!” diye. Allah`a karşı gerçek olmayanı söylemenizden ve O`nun âyetlerine karşı kibirlilik taslamış olmanızdan ötürü bugün alçaklık azabı ile cezalandırılacaksınız."},{"n":94,"t":"Andolsun ki, sizi ilk defa yarattığımız gibi teker teker bize geleceksiniz ve dünyada size verdiğimiz şeyleri arkanızda bırakacaksınız. Sizinle ilgili olarak ortaklarımız sandığınız şefaatçilerinizi de yanınızda göremeyeceksiniz. Andolsun aranızdaki bütün bağlar kopmuş ve tanrı sandığınız şeyler sizden kaybolup gitmiştir."},{"n":95,"t":"Şüphesiz Allah, tohumu ve çekirdeği çatlatandır; ölüden diriyi, diriden de ölüyü çıkarandır. İşte Allah budur. O halde haktan nasıl döndürülüyorsunuz?"},{"n":96,"t":"Allah, sabahı aydınlatandır. O, geceyi dinlenme zamanı, güneş ve ayı vakitlerin tayini için birer hesap ölçüsü kılandır. İşte bu, güçlü olan ve her şeyi pek iyi bilen Allah`ın takdiridir."},{"n":97,"t":"O, kara ve denizin karanlıklarında kendileri ile yol bulasınız diye sizin için yıldızları yaratandır. Gerçekten, bilen bir toplum için âyetleri geniş geniş açıkladık."},{"n":98,"t":"O, sizi bir tek nefisten/cevherden yaratandır. Sizin için bir kalma yeri, bir de emanet olarak konulacağınız yer vardır. Anlayan bir toplum için âyetleri ayrıntılı bir şekilde açıkladık."},{"n":99,"t":"O, gökten su indirendir. İşte biz her çeşit bitkiyi onunla bitirdik. O bitkiden de kendisinde üst üste binmiş taneler bitireceğimiz bir yeşillik, hurmanın tomurcuğundan sarkan salkımlar, üzüm bağları, bir kısmı birbirine benzeyen, bir kısmı da benzemeyen zeytin ve nar bahçeleri meydana getirdik. Meyve verirken ve olgunlaştığı zaman, her birinin meyvesine bakın! Şüphesiz bütün bunlarda, inanan bir toplum için dersler vardır."},{"n":100,"t":"Cinleri Allah`a ortak koştular. Oysa ki, onları da Allah yaratmıştı. Bilgisizce O`na oğullar ve kızlar yakıştırdılar. O`nun şanı yücedir, onların ileri sürdükleri vasıflardan uzaktır."},{"n":101,"t":"O, göklerin ve yerin eşsiz yaratıcısıdır. O`nun eşi olmadığı halde, nasıl çocuğu olabilir? Her şeyi O yaratmıştır ve her şeyi hakkı ile bilen O`dur."},{"n":102,"t":"İşte Rabbiniz Allah O`dur. O`ndan başka tanrı yoktur. O, her şeyin yaratıcısıdır. Öyle ise O`na kulluk ediniz; güvenilip dayanılacak tek varlık O`dur."},{"n":103,"t":"Gözler O`nu göremez; halbuki O, gözleri görür. O, eşyayı pek iyi bilen, her şeyden haberdar olandır."},{"n":104,"t":"Doğrusu size Rabbiniz tarafından basiretler/idrâk kabiliyeti verilmiştir. Artık kim hakkı görürse faydası kendine, kim de kör olursa zararı kendinedir. Ben üzerinize bekçi değilim."},{"n":105,"t":"Böylece biz âyetleri derinlemesine açıklıyoruz ki, “Sen ders almışsın” demesinler; onu kavrayan topluma izah ediyoruz."},{"n":106,"t":"Rabbin tarafından sana vahyolunana uy! O`ndan başka tanrı yoktur. Ortak koşanlardan yüz çevir."},{"n":107,"t":"Allah dileseydi, onlar ortak koşamazlardı. Biz seni onların üzerine bir bekçi kılmadık. Sen onların vekili de değilsin."},{"n":108,"t":"Allah`tan başkasına tapanlara sövmeyiniz! Sonra onlar da bilmeyerek Allah`a söverler. Böylece biz her ümmete kendi işlerini süsledik. Sonunda dönüşleri Rabblerinedir. Artık O, ne yaptıklarını kendilerine bildirecektir."},{"n":109,"t":"“Mucizeler ancak Allah`ın yanındadır.” Hem bilir misiniz, o gelmiş olsa da onlar inanmazlar."},{"n":110,"t":"Gönüllerini ve gözlerini ters çeviririz, ilkin ona inanmadıkları gibi, mucizeyi gördükten sonra da inanmazlar. Onları şaşkın olarak azgınlıkları içinde bırakırız."},{"n":111,"t":"Biz onlara melekleri indirseydik, ölüler kendileriyle konuşsaydı ve her şeyi toplayıp karşılarına getirseydik, Allah dilemedikten sonra yine inanmazlardı; fakat çokları cehalet üretiyorlar."},{"n":112,"t":"Böylece biz, her peygambere insan ve cin şeytanlarını düşman kıldık. Bunlar, aldatmak için birbirlerine yaldızlı sözler fısıldarlar. Rabbin dileseydi, onu da yapamazlardı. Artık onları, uydurdukları şeylerle baş başa bırak."},{"n":113,"t":"Âhirete inanmayanların kalpleri, yaldızlı söze kansın, ondan hoşlansınlar ve işledikleri suçu işlemeye devam etsinler diye böyle yaparlar."},{"n":114,"t":"Allah`tan başka bir hakem mi arayacağım? Halbuki size kitabı açık olarak indiren O`dur. Kendilerine kitap verdiğimiz kimseler, Kur`ân`ın gerçekten Rabbin tarafından indirilmiş olduğunu bilirler. Sakın şüpheye düşenlerden olma!"},{"n":115,"t":"Rabbinin sözü, doğruluk ve adâlet bakımından tamamlanmıştır. O`nun sözlerini değiştirecek kimse yoktur. O işitendir; bilendir."},{"n":116,"t":"Yeryüzündekilerin çoğunluğuna uyarsan, seni Allah`ın yolundan saptırırlar. Onlar zandan başka bir şeye uymazlar ve onlar sadece yalan söylerler."},{"n":117,"t":"Şüphesiz ki Rabbin, yolundan sapanları çok iyi bilir; doğru yolda olanları da en iyi bilen O`dur."},{"n":118,"t":"Eğer Allah`ın âyetlerine inanıyorsanız, Allah`ın adı anılarak kesilen hayvanlardan yiyiniz!"},{"n":119,"t":"Allah`ın adı anılarak kesilenlerden niçin yemeyesiniz? Oysa Allah, çaresiz yemek zorunda kaldığınız dışında, haram kıldığı şeyleri size açıklamıştır. Doğrusu birçoğu bilgisizce, kendi kötü arzularına uyarak saptırıyorlar. Muhakkak ki Rabbin, haddi aşanları çok iyi bilir."},{"n":120,"t":"Günahın açığını da gizlisini de bırakınız! Çünkü günah işleyenler yaptıklarının cezasını mutlaka çekeceklerdir."},{"n":121,"t":"Üzerine Allah`ın adı anılmadan kesilen hayvanlardan yemeyiniz! Şüphesiz bu büyük günahtır. Gerçekten şeytanlar dostlarına, sizinle mücadele etmeleri için telkinde bulunurlar. Eğer onlara uyarsanız, şüphesiz siz de Allah`a ortak koşanlardan olursunuz."},{"n":122,"t":"Ölü iken dirilttiğimiz ve kendisine insanlar arasında yürüyebileceği bir ışık verdiğimiz kimse, karanlıklar içinde kalıp ondan hiç çıkamayacak durumdaki kimse gibi olur mu? İşte kâfirlere, yaptıkları böyle süslü gösterilmiştir."},{"n":123,"t":"Böylece biz her kasabada, oralarda bozgunculuk yapmaları için günahkârlarını liderler yaptık. Onlar yalnız kendilerini aldatırlar, ama farkında olmazlar."},{"n":124,"t":"Onlara bir âyet geldiğinde, “Allah`ın peygamberlerine verilenin benzeri kendilerine verilmedikçe, kesinlikle inanmayacağız” dediler. Allah, peygamberliğini kime vereceğini tam bilendir. Suç işleyenlere, yapmakta oldukları hilelere karşılık Allah tarafından aşağılık ve çetin bir azap erişecektir."},{"n":125,"t":"Allah kimi doğru yola iletmek isterse, onun kalbini İslâm`a açar; kimi de saptırmak isterse, göğe çıkıyormuş gibi kalbini iyice daraltır. Allah, inanmayanların üstüne işte böyle murdarlık verir."},{"n":126,"t":"Bu, Rabbinin doğru yoludur. Biz, öğüt alacak bir kavim için âyetleri ayrıntılı olarak açıkladık."},{"n":127,"t":"Rabbleri katında onlara esenlik yurdu vardır. Yapmakta oldukları işler sebebiyle Allah onların dostudur."},{"n":128,"t":"«Sizin ikametgahınız, Allah`ın dilediği zamanlardan başka, ebedi kalmak üzere ateştir. Şüphesiz Rabbin hikmet sahibidir, herşeyi bilendir.»"},{"n":129,"t":"İşte kazandıkları günahlarından ötürü zâlimlerin bir kısmını diğer bir kısmının peşine böyle takarız."},{"n":130,"t":"“Kendi aleyhimize şâhitlik ederiz.” Dünya hayatı onları aldattı ve kâfir olduklarına dair kendi aleyhlerine şâhitlik edecekler."},{"n":131,"t":"Gerçek şu ki; halkı habersizken, Rabbin haksızlıkla ülkeleri helâk edici değildir."},{"n":132,"t":"Herkesin, yaptıkları işlere göre dereceleri vardır. Rabbin onların yaptıklarından habersiz değildir."},{"n":133,"t":"Kendi kendine yeterli olan ve sınırsız merhamet sahibi yalnızca Rabbindir. O dilerse sizin varlığınıza son verir ve daha sonra dilediğini sizin yerinize geçirir, tıpkı sizi başka insanların soyundan var ettiği gibi."},{"n":134,"t":"Size vaad edilen mutlaka gelecektir. Siz bunu önleyemezsiniz."},{"n":135,"t":"“Ey kavmim! Elinizden geleni yapınız! Ben de yapacağım! Yurdun sonunun kimin lehine olduğunu yakında bileceksiniz. Gerçek şu ki, zâlimler iflâh olmazlar.”"},{"n":136,"t":"Onlar, Allah`ın yarattığı ekin ve davar gibi şeylerden bir pay ayırırlar. Kendi zanlarınca, “Bu, Allah`ındır, bu da ortaklarımızındır” derler. Ortakları için olan Allah`a ulaşmıyor, Allah için olan ortaklarına ulaşıyordu. Bunlar ne kadar kötü hükmediyorlar!"},{"n":137,"t":"Aynen bunun gibi, müşriklerden birçoğuna, Allah`a ortak koştukları putlar, öz evlâtlarını öldürmeyi güzel göstermiştir ki hem onları yok etsinler, hem de dinlerini karmakarışık hale getirsinler. O halde onları, düzdükleri iftirâlarla baş başa bırak!"},{"n":138,"t":"“Bu, tanrılar için ayrılan hayvanlarla ekinler, haramdır. Bunları bizim dilediğimizden başkası yiyemez. Bunlar da, binilmesi yasaklanmış hayvanlardır.” Bir kısım hayvanları da Allah`a iftirâ ederek üzerlerine Allah`ın adını anmadan boğazlarlar. Allah, düzdükleri iftirâlar yüzünden onları cezalandıracaktır."},{"n":139,"t":"“Şu hayvanların karınlarında olanlar, yalnız erkeklerimize aittir; kadınlarımıza ise haram kılınmıştır. Şâyet yavru ölü doğarsa, o zaman kadın-erkek hepsi onda ortaktır. Allah, bu değerlendirmelerinin cezasını verecektir. Şüphesiz ki O, hikmet sahibidir; hakkıyla bilendir.”"},{"n":140,"t":"Akılsızlıkları yüzünden bilgisizce çocuklarını öldüren ve Allah`a iftirada bulunarak Allah`ın onlara rızık olarak verdiği şeyleri kendilerine haram kılanlar elbette hüsrana uğramışlardır. Onlar sapıtmışlar ve doğru yola erememişlerdir."},{"n":141,"t":"Çardaklı ve çardaksız bahçeleri, ürünleri, çeşit çeşit hurmaları, sebzeleri, zeytinleri, narları yaratan O`dur. Her biri meyve verdiği zaman, meyvesinden yiyiniz. Devşirilip toplandığı gün de hakkını/zekât ve sadakasını veriniz. İsraf etmeyiniz, çünkü Allah isrâf edenleri sevmez."},{"n":142,"t":"Hayvanlardan yük taşıyanı da, tüyünden döşek yapılanı da yaratan yine O`dur. Allah`ın size verdiği rızıklardan yiyiniz, şeytanın ardına düşmeyiniz. Şüphesiz o, sizin için apaçık bir düşmandır."},{"n":143,"t":"“O, bunların erkeklerini mi, dişilerini mi, yoksa bu iki dişinin rahimlerinde bulunan yavruları mı haram kıldı? Eğer doğru iseniz bana bir bilgi söyleyiniz.”"},{"n":144,"t":"“O, bunların erkeklerini mi, dişilerini mi, yoksa bu iki dişinin rahimlerinde bulunan yavruları mı haram kıldı? Yoksa Allah`ın size böyle vasiyet ettiğine şâhit mi oldunuz? Bilgisizce, insanları saptırmak için Allah`a karşı yalan uydurandan daha zâlim kimdir? Şüphesiz Allah, zâlimler topluluğunu doğru yola iletmez."},{"n":145,"t":"“Bana vahyedilende, leş veya akan kan veya iğrenç bir şey olan domuz eti ya da üzerinde Allah`tan başka bir ismin anıldığı günahkârca bir kurban dışında, yenmesi yasak olan hiçbir şey bulamıyorum. Ama kişi zaruret içindeyse, başkasına zarar vermemek ve sınırı aşmamak üzere yiyebilir. Rabbin affedicidir; merhamet sahibidir.”"},{"n":146,"t":"Yahudilere bütün tırnaklı hayvanları haram kıldık. Sırtlarında veya bağırsaklarında taşıdıkları ya da kemiğe karışan yağlar hariç olmak üzere sığır ve koyunun iç yağlarını da onlara haram kıldık. Bu, zulümleri yüzünden onlara verdiğimiz cezadır. Biz elbette doğruyu söyleriz."},{"n":147,"t":"“Rabbiniz geniş bir rahmet sahibidir. Bununla beraber, O`nun azabı, suçlular topluluğundan uzaklaştırılamaz.”"},{"n":148,"t":"“Yanınızda bize açıklayacağınız bir bilgi var mı? Siz zandan başka bir şeye uymuyorsunuz ve siz sadece yalan söylüyorsunuz.”"},{"n":149,"t":"“Kesin delil Allah`a aittir. Allah dileseydi elbette hepinizi doğru yola iletirdi.”"},{"n":150,"t":"“Allah şunu yasak etti, diye şehâdet edecek şâhitlerinizi getiriniz!” Eğer onlar şâhitlik ederlerse, sen onlarla beraber şâhitlik etme! Âyetlerimizi yalanlayanların ve âhiret gününe inanmayanların arzularına uyma! Onlar Rabblerine eş tutuyorlar."},{"n":151,"t":"O`na hiçbir şeyi ortak koşmayınız; anne babaya iyilik ediniz; fakirlik korkusuyla çocuklarınızı öldürmeyiniz! Sizin de onların da rızkını biz veririz; kötülüklerin açığına da gizlisine de yaklaşmayınız ve Allah`ın yasakladığı cana haksız yere kıymayınız! İşte, aklınızı kullanasınız diye Allah size bunları emretti.”"},{"n":152,"t":"“Rüşd çağına erişinceye kadar yetimin malına, sadece en iyi tutumla yaklaşınız; ölçü ve tartıyı adaletle yapınız! Biz, herkese ancak gücünün yettiği kadarını yükleriz. Söz söylediğiniz zaman, yakınlarınız dahi olsa adaletli olunuz; Allah`a verdiğiniz sözü tutunuz. İşte, düşünüp öğüt alasınız diye Allah size bunları emretti.”"},{"n":153,"t":"“Şüphesiz bu, benim dosdoğru yolumdur. Buna uyunuz, başka yollara uymayınız; zira o yollar sizi Allah`ın yolundan ayırır. İşte, sakınmanız için Allah size bunları emretti.”"},{"n":154,"t":"Sonra, güzel davrananlara nimetimizi tamamlamak, her şeyi açıklamak, bir kılavuz ve rahmet olmak üzere Mûsâ`ya kitabı verdik ki onlar Rablerine kavuşacaklarına inanabilsinler."},{"n":155,"t":"Bu Kur`ân da bizim indirdiğimiz mübarek bir kitaptır. Buna uyunuz ve sakınınız ki size merhamet edilsin."},{"n":"156-157","t":"“Kitap, yalnız bizden önceki iki topluluğa indirildi, biz ise onların okumasından gerçekten habersizdik” demeyesiniz, yahut “Eğer bize kitap indirilseydi, biz onlardan daha çok doğru yolda olurduk” demeyesiniz diye bu kitabı indirdik. İşte size de Rabbinizden açık bir delil, kılavuz ve rahmet geldi. Allah`ın âyetlerini yalanlayıp onlardan yüz çevirenden daha zâlim kim olabilir? Âyetlerimizden yüz çevirenleri, yüz çevirmelerinden dolayı azabın en kötüsüyle cezalandıracağız!"},{"n":158,"t":"«Bekleyin bakalım, biz de bekliyoruz.»"},{"n":159,"t":"Dinlerini parça parça edip gruplara ayrılanlarla senin hiçbir ilişkin yoktur. Onların işi Allah`a kalmıştır. Sonra Allah, onlara yaptıklarını haber verecektir."},{"n":160,"t":"Kim Allah`ın huzuruna bir güzellik getirirse ona, getirdiğinin on katı vardır. Kim de kötülük getirirse, o sadece getirdiğinin dengi ile cezalandırılır. Onlar haksızlığa uğratılmazlar."},{"n":161,"t":"“Rabbim beni dosdoğru yola, dosdoğru dine, Hanîf olan İbrâhim`in dinine iletmiştir. İbrâhim, ortak koşanlardan değildi.”"},{"n":162,"t":"“Şüphesiz benim namazım, kurbanım, hayatım ve ölümüm, hepsi âlemlerin Rabbi Allah içindir.”"},{"n":163,"t":"“O`nun ortağı yoktur. Bana sadece bu emrolundu ve ben Müslümanların ilkiyim.”"},{"n":164,"t":"“Allah her şeyin Rabbi iken, O`ndan başka rab mi arayayım? Herkesin kazandığı yalnız kendisine aittir. Hiçbir suçlu başkasının suçunu yüklenemez. Sonunda dönüşünüz Rabbinizedir. O, ihtilâfa düştüğünüz gerçeği size haber verecektir.”"},{"n":165,"t":"Sizi yeryüzünde iktidar sahipleri yapan O`dur. Verdiği nimetlerle sizi denemek için kiminizi kiminizden derecelerle üstün kılan da O`dur. Şüphesiz Rabbin, cezası çabuk olandır ve gerçekten O, çok bağışlayandır; çok merhamet edendir."}],[{"n":1,"t":"Elif, lâm, mîm, sâd."},{"n":2,"t":"Bu, kendisiyle insanları uyarman ve insanlara öğüt olsun diye sana indirilen bir kitaptır. Artık bu hususta kalbinde bir şüphe olmasın."},{"n":3,"t":"Rabbinizden size indirilene uyunuz! O`nu bırakıp da başka dostların peşlerinden gitmeyiniz! Ne kadar da az öğüt alıyorsunuz!"},{"n":4,"t":"Nice memleketler var ki biz onları helâk ettik. Azabımız onlara geceleyin yahut gündüz istirahat ederlerken geldi."},{"n":5,"t":"Azabımız onlara geldiğinde çağırışları, “Biz gerçekten zâlim kişilermişiz” demelerinden başka bir şey olmadı."},{"n":6,"t":"Elbette kendilerine peygamber gönderilenleri de, gönderilen peygamberleri de sorguya çekeceğiz."},{"n":7,"t":"Onlara bir bilgi ile mutlaka anlatacağız. Biz, onlardan habersiz değiliz."},{"n":8,"t":"O gün, tartı haktır. Kimin tartıları ağır gelirse, işte onlar kurtuluşa erenlerdir."},{"n":9,"t":"Kimin de tartıları hafif gelirse, işte onlar, âyetlerimize karşı haksızlık ettikleri için kendilerini ziyana sokanlardır."},{"n":10,"t":"Doğrusu biz sizi yeryüzünde yerleştirdik ve orada size geçim vasıtaları verdik. Ne kadar da az şükrediyorsunuz!"},{"n":11,"t":"Andolsun sizi yarattık, sonra size biçim verdik ve sonra da meleklere, “Âdem`e secde edin” dedik. İblîs`in dışındakiler secde ettiler; o secde edenlerden olmadı."},{"n":12,"t":"“Sana emrettiğim zaman, seni secde etmekten alıkoyan neydi?” dedi. İblis de, ben O`ndan üstünüm; çünkü beni ateşten, O`nu ise balçıktan yarattın, diye cevap verdi."},{"n":13,"t":"Allah, “Öyle ise, oradan in! Orada büyüklük taslamak senin haddin değildir. Çık, çünkü sen aşağılıklardansın” buyurdu."},{"n":14,"t":"İblîs, “Bana, insanların diriltilecekleri güne kadar mühlet ver” dedi."},{"n":15,"t":"Allah, “Haydi, sen mühlet verilenlerdensin” buyurdu."},{"n":16,"t":"İblîs, “Öyle ise beni azdırmana karşılık, yemin ederim ki ben de onları saptırmak için senin doğru yolunun üstüne oturacağım” dedi."},{"n":17,"t":"“Sonra onlara elbette önlerinden, arkalarından, sağlarından, sollarından sokulacağım ve sen, onların çoklarını şükredenlerden bulamayacaksın” dedi."},{"n":18,"t":"`Haydi oradan çabuk çık. İtibarın kalmadı, kovuldun. Andolsun ki, onlardan sana uyanlarla, sizden olanlarla, hepinizle Cehennem’i dolduracağım.` buyurdu."},{"n":19,"t":"Allah, “Ey Âdem! Sen ve eşin cennette yerleşip dilediğinizden yiyiniz. Ancak şu ağaca yaklaşmayınız! Sonra zâlimlerden olursunuz” buyurdu."},{"n":20,"t":"Derken şeytan, birbirine kapalı ayıp yerlerini kendilerine göstermek için onlara vesvese verdi ve “Rabbiniz size bu ağacı sırf melek olursunuz veya ebedî kalanlardan olursunuz diye yasakladı” dedi."},{"n":21,"t":"Onlara, “Ben gerçekten size öğüt verenlerdenim” diye yemin etti."},{"n":22,"t":"Böylece onları hile ile aldattı. Ağacın meyvesini tattıklarında ayıp yerleri kendilerine göründü ve cennet yapraklarından üzerlerine örtmeye başladılar. Rableri onlara, “Ben size o ağacı yasaklamadım mı ve şeytan size apaçık bir düşmandır, demedim mi?” diye seslendi."},{"n":23,"t":"“Ey Rabbimiz! Biz kendimize haksızlık ettik. Eğer bizi bağışlamaz ve bize merhamet etmezsen, elbette ziyan edenlerden oluruz.”"},{"n":24,"t":"“Kiminiz kiminize düşman olarak ininiz! Sizin için yeryüzünde bir süreye kadar yerleşme ve faydalanma vardır.”"},{"n":25,"t":"“Orada yaşayacaksınız, orada öleceksiniz ve oradan çıkarılacaksınız” dedi."},{"n":26,"t":"Ey Âdemoğulları! Size ayıp yerlerinizi örtecek giysi, süslenecek elbise indirdik. Takvâ elbisesi... İşte o daha hayırlıdır. Bunlar Allah`ın âyetlerindendir, belki düşünürler."},{"n":27,"t":"Ey Âdemoğulları! Şeytan, anne babanızı, ayıp yerlerini kendilerine göstermek için elbiselerini soyarak cennetten çıkardığı gibi sizi de aldatmasın! Çünkü o ve yandaşları, sizin onları görmeyeceğiniz yerden sizi görürler. Şüphesiz biz şeytanları, inanmayanların dostları kıldık."},{"n":28,"t":"“Allah kötülüğü emretmez. Allah`a karşı bilmediğiniz şeyleri mi söylüyorsunuz?”"},{"n":29,"t":"“Rabbim tevhidi emretti. Her secde ettiğinizde yüzlerinizi O`na çeviriniz ve dini yalnız Allah`a has kılarak, O`na yalvarınız. İlkin sizi yarattığı gibi yine O`na döneceksiniz.”"},{"n":30,"t":"Allah, bir grubu doğru yola iletti, bir gruba da sapıklık müstehak oldu. Çünkü onlar Allah`ı bırakıp şeytanları kendilerine dost edindiler. Böyle iken, kendilerinin doğru yolda olduklarını sanıyorlar."},{"n":31,"t":"Ey Âdemoğulları! Her mescide çıkışınızda/ibadetinizde elbiselerinizi giyiniz; yiyiniz, içiniz, fakat isrâf etmeyiniz; çünkü Allah israf edenleri sevmez."},{"n":32,"t":"“Onlar, dünya hayatında, özellikle de kıyamet gününde müminlerindir.” İşte, bilen bir topluluk için âyetleri böyle açıklıyoruz."},{"n":33,"t":"“Rabbim ancak açık ve gizli kötülükleri, günahı ve haksız yere sınırı aşmayı, hakkında hiçbir delil indirmediği bir şeyi Allah`a ortak koşmanızı ve Allah hakkında bilmediğiniz şeyleri söylemenizi haram kılmıştır.”"},{"n":34,"t":"Her ümmetin bir eceli vardır. Ecelleri gelince, ne bir an geri kalırlar ne de bir an öne gelebilirler."},{"n":35,"t":"Ey Âdemoğulları! Size kendi içinizden âyetlerimi anlatacak peygamberler gelir de, kim sakınır ve kendini düzeltirse, onlara korku yoktur ve onlar üzülmeyecektir."},{"n":36,"t":"Âyetlerimizi yalanlayanlar ve büyüklenip onlardan yüz çevirenler var ya, işte onlar cehennemliklerdir. Onlar orada süreli kalacaklardır."},{"n":37,"t":"Allah`a iftira eden ya da O`nun âyetlerini yalanlayandan daha zâlim kim vardır? Onlara kitaptaki nasipleri erişecektir. Nihayet elçilerimiz gelip canlarını alırken, “Hani, Allah`tan başka yalvardıklarınız nerede?” dediklerinde, “Bizden kayboldular” dediler ve kendi aleyhlerine kendilerinin kâfir olduklarına şâhitlik ettiler."},{"n":38,"t":"“Sizden önce geçmiş cin ve insan toplulukları arasında siz de ateşe giriniz!” Her ümmet girdikçe yoldaşına lânet edecektir. Hepsi birbiri ardından orada toplanınca, sonrakiler öncelikler için, “Ey Rabbimiz! Bizi işte bunlar saptırdılar! Onun için onlara ateşten bir kat daha fazla azap ver!” diyecekler. Allah da, “Zaten herkes için bir kat daha fazla azap vardır, fakat siz bilmezsiniz” diyecektir."},{"n":39,"t":"“Sizin bize bir üstünlüğünüz yok. O halde siz de yaptıklarınıza karşılık azabı tadın.”"},{"n":40,"t":"Bizim âyetlerimizi yalanlayıp da onlara karşı kibirlenmek isteyenler var ya, işte onlara göğün kapıları açılmayacak ve onlar, deve iğne deliğine girinceye kadar cennete giremeyeceklerdir! Suçluları işte böyle cezalandırırız."},{"n":41,"t":"Onlar için cehennem ateşinden döşekler, üzerlerine de örtüler vardır. İşte zâlimleri böyle cezalandırırız."},{"n":42,"t":"Hiç kimseye gücünün üstünde bir şey yapmasını önermediğimiz halde inanıp iyi işler yapanlar cennetliktirler, onlar orada süreli kalacaklardır."},{"n":43,"t":"Onların göğüslerinde kinden ne varsa hepsini çıkarıp atmışızdır. O cennette altlarından ırmaklar akmaktadır. “Lütfedip bizi buraya getiren Allah`a hamdolsun. Allah bizi getirmeseydi biz bunu bulamazdık. Rabbimizin peygamberleri gerçeği getirmişler” dediler. Onlara, “İşte size cennet, yaptıklarınıza karşılık size miras verildi” diye seslenilecektir."},{"n":44,"t":"Cennet ehli, cehennem ehline, “Rabbimizin bize vaad ettiklerinin gerçek olduğunu gördük; siz de Rabbinizin size vaad ettiklerini gerçekleşmiş buldunuz mu?” diye seslenir. “Evet!” derler. Aralarından bir çağrıcı, “Allah`ın lâneti zâlimlerin üzerine olsun!” diye bağırır."},{"n":45,"t":"Onlar, Allah yolundan alıkoyan ve o yolu eğip bükmek isteyen zâlimlerdir. Onlar âhireti de inkâr edenlerdir."},{"n":46,"t":"İki taraf/cennetlikler ve cehennemlikler arasında bir perde ve A‘râf üzerinde de herkesi simâlarından tanıyan adamlar vardır ki, bunlar henüz cennete giremedikleri halde girmeyi umarak cennet ehline, “Selâm size!” diye seslenirler."},{"n":47,"t":"Gözleri cehennem ehli tarafına döndürülünce de, “Ey Rabbimiz! Bizi zâlimler topluluğu ile beraber bulundurma!” derler."},{"n":48,"t":"“Ne çokluğunuz ne de taslamakta olduğunuz büyüklük size bir yarar sağladı.”"},{"n":49,"t":"“Giriniz cennete! Artık size korku yoktur ve siz üzülecek de değilsiniz” derler."},{"n":50,"t":"Cehennem ehli, cennet ehline, “Suyunuzdan veya Allah`ın size verdiği rızıktan biraz da bize veriniz!” diye seslenirler. Onlar da, “Allah bunları kâfirlere haram kılmıştır” derler."},{"n":51,"t":"O kâfirler ki, dinlerini bir eğlence ve oyun edindiler de dünya hayatı onları aldattı. Onlar bugüne kavuşacaklarını unutmuşlardır. Âyetlerimizi inkâr ettikleri ve bugüne kavuşacaklarını unuttukları gibi, biz de bugün onları unutuyoruz."},{"n":52,"t":"Gerçekten, onlara inanan bir toplum için yol gösterici ve rahmet olarak, bilgiye dayalı ayrıntılı açıklamalarda bulunduğumuz bir kitabı ulaştırmıştık."},{"n":53,"t":"“Doğrusu Rabbimizin peygamberleri gerçeği getirmişlerdir. Acaba bizim için şefaatçiler var mı ki, bize şefaat etsinler; yahut daha önce yaptıklarımızdan başkasını yapalım diye geri gönderilebilir miyiz?” Onlar cidden kendilerine yazık ettiler ve uydurdukları şeyler de kendilerinden kaybolup gitti."},{"n":54,"t":"Şüphesiz, Rabbiniz o Allah`tır ki, gökleri ve yeri altı zaman devresi içinde yarattı, sonra kâinat üzerinde hükümrânlığını kurdu. O, geceyi, hemen arkasından kendisini kovalayan gündüze örter. Güneş, ay ve yıldızları da daima irâdesine boyun eğmiş durumda var etmiştir. Bilesiniz ki yaratmak da emretmek de O`na mahsustur. Âlemlerin Rabbi Allah ne yücedir!"},{"n":55,"t":"Rabbinize alçak gönülle ve yüreğinizin ta derinliklerinden gelerek dua ediniz. Doğrusu O, çizgiyi aşanları sevmez."},{"n":56,"t":"Yeryüzü ıslaha kavuştuktan sonra orada bozgunculuk yapmayınız. O`na ürpererek ve ümit ederek dua ediniz. Şüphesiz Allah`ın rahmeti, iyilik edenlere yakındır."},{"n":57,"t":"Rüzgârları rahmetinin önünden müjdeci olarak gönderen O`dur. Nihayet rüzgârlar, ağır bulutları yüklenince onu ölü bir beldeye göndeririz; orada suyu indirir ve onunla türlü türlü meyveler çıkarırız. İşte ölüleri de böyle çıkaracağız. Umulur ki düşünüp ders alırsınız."},{"n":58,"t":"Verimli beldenin bitkisi Rabbinin izni ile çıkar. Çorak olan beldeden ise zararlı bitkiden başkası çıkmaz. İşte biz, şükreden bir kavim için âyetleri böyle açıklıyoruz."},{"n":59,"t":"Andolsun, Nûh`u kavmine gönderdik; “Ey kavmim!” dedi, “Allah`a kulluk ediniz, sizin O`ndan başka tanrınız yoktur. Doğrusu ben, size büyük bir günün azabının inmesinden korkuyorum.”"},{"n":60,"t":"“Biz seni açık bir sapıklık içinde görüyoruz.”"},{"n":61,"t":"“Ey kavmim! Bende bir sapıklık yok, ben âlemlerin Rabbi tarafından gönderilmiş bir peygamberim.”"},{"n":62,"t":"“Size Rabbimin gönderdiği gerçekleri duyuruyorum, size öğüt veriyorum ve Allah tarafından, sizin bilmediğiniz şeyleri biliyorum.”"},{"n":63,"t":"“Korunup da merhamete nail olmanız için, içinizden sizi uyaracak biri aracılığı ile Rabbinizden size bir öğüt gelmesine şaştınız mı?”"},{"n":64,"t":"Onu yalanladılar, biz de onu ve onunla beraber gemide bulunanları kurtardık, âyetlerimizi yalanlayanları boğduk! Çünkü onlar manen kör bir kavim idiler."},{"n":65,"t":"“Ey kavmim! Allah`a kulluk ediniz, sizin O`ndan başka tanrınız yoktur. Hâlâ sakınmayacak mısınız?”"},{"n":66,"t":"“Biz seni kesinlikle bir akılsızlık içinde görüyoruz ve gerçekten seni yalancılardan sanıyoruz.”"},{"n":67,"t":"“Ey kavmim!” dedi. “Ben akılsız değilim; fakat ben âlemlerin Rabbinin gönderdiği bir peygamberim.”"},{"n":68,"t":"“Size Rabbimin vahyettiklerini duyuruyorum ve ben sizin için güvenilir bir öğütçüyüm.”"},{"n":69,"t":"“Sizi uyarmak için, içinizden biri vasıtasıyla Rabbinizden size bir öğüt/ kitap gelmesine şaştınız mı? Düşününüz ki O sizi, Nûh kavminden sonra onların yerine getirdi ve yaratılışta sizi onlardan üstün kıldı. O halde Allah`ın nimetlerini hatırlayınız ki kurtuluşa eresiniz.”"},{"n":70,"t":"“Sen bize, tek Allah`a kulluk etmemiz ve atalarımızın tapmakta olduklarını bırakmamız için mi geldin? Eğer doğrulardan isen, bizi tehdit ettiğin azabı bize getir.”"},{"n":71,"t":"“Üzerinize Rabbinizden bir azap ve bir hışım inmiştir. Haklarında Allah`ın hiçbir delil indirmediği, sadece sizin ve atalarınızın taktığı kuru isimler hususunda benimle tartışıyor musunuz? Bekleyiniz öyleyse, şüphesiz ben de sizinle beraber bekleyenlerdenim.”"},{"n":72,"t":"Onu ve onunla beraber olanları rahmetimizle kurtardık ve âyetlerimizi yalanlayıp da iman etmeyenlerin kökünü kestik."},{"n":73,"t":"“Ey kavmim! Allah`a kulluk ediniz. O`ndan başka tanrınız yoktur. Size Rabbinizden açık bir delil gelmiştir. O da, size bir mûcize olarak Allah`ın şu devesidir. Onu bırakınız, Allah`ın arzında otlasın; ona kötülük etmeyiniz, sonra sizi elem verici bir azap yakalar.”"},{"n":74,"t":"Düşününüz ki Allah, Âd kavminden sonra, yerlerine sizi getirdi. Yeryüzünde sizi yerleştirdi. Onun düzlüklerinde saraylar yapıyorsunuz, dağlarında evler yontuyorsunuz. Artık Allah`ın nimetlerini hatırlayınız da yeryüzünde bozgunculuk yapmayınız."},{"n":75,"t":"“Siz Sâlih`in, Rabbi tarafından gönderildiğini biliyor musunuz?” Onlar da, “Şüphesiz biz onunla ne gönderilmişse ona inananlarız” dediler."},{"n":76,"t":"Büyüklük taslayanlar, “Biz de sizin inandığınızı inkâr edenleriz” dediler."},{"n":77,"t":"Derken, o dişi deveyi ayaklarını keserek öldürdüler ve Rablerinin emrinden dışarı çıktılar da, “Ey Sâlih! Eğer sen gerçekten peygamberlerdensen, bizi tehdit ettiğin azabı bize getir” dediler."},{"n":78,"t":"Bunun üzerine, onları o şiddetli sarsıntı yakaladı da yurtlarında diz üstü çöktüler."},{"n":79,"t":"“Ey kavmim! Andolsun ki ben size Rabbimin vahyettiklerini tebliğ ettim ve size öğüt verdim; fakat siz öğüt verenleri sevmiyorsunuz.”"},{"n":80,"t":"“Sizden önceki milletlerden hiçbirinin yapmadığı fuhşu mu yapıyorsunuz?”"},{"n":81,"t":"“Siz, kadınları bırakıp şehvetiniz yüzünden erkeklere gidiyorsunuz. Doğrusu siz taşkınlık yapan bir topluluksunuz.”"},{"n":82,"t":"“Çıkarın şunları memleketinizden. Çünkü onlar, temizlik taslayan insanlardır.”"},{"n":83,"t":"Biz de onu ve hanımından başka aile fertlerini kurtardık; çünkü hanımı geride kalanlardan idi."},{"n":84,"t":"Üzerlerine şiddetli bir yağmur yağdırdık. Bak, günahkârların sonu nasıl oldu?"},{"n":85,"t":"“Ey kavmim!” dedi, “Allah`a kulluk ediniz, sizin O`ndan başka tanrınız yoktur. Size Rabbinizden açık bir delil geldi. Ölçüyü ve tartıyı tam yapınız; insanların mallarını eksik vermeyiniz, düzeltildikten sonra yeryüzünde bozgunculuk yapmayınız; eğer inanan insanlar iseniz, böylesi sizin için daha iyidir.”"},{"n":86,"t":"“Her yolun başına oturup da, tehdit ederek ona inananları Allah yolundan çevirmeye ve Allah yolunu eğriltmeye çalışmayınız; düşününüz ki siz az idiniz, O sizi çoğalttı ve bakınız bozguncuların sonu nasıl oldu?”"},{"n":87,"t":"“Eğer içinizden bir kısmı benimle gönderilene inanmış, bir kısmı da inanmamış ise, artık Allah, aramızda hükmünü verinceye kadar sabrediniz; O, hükmedenlerin en iyisidir.”"},{"n":88,"t":"“İstemesek de mi?”"},{"n":89,"t":"“Allah, bizi sizin dininizden kurtardıktan sonra eğer tekrar ona dönersek, Allah hakkında yalan söylemiş oluruz. Rabbimiz Allah dilemedikten sonra, sizin dininize dönmemiz bizim için olur şey değildir. Rabbimizin ilmi her şeyi kuşatmıştır. Biz sadece Allah`a dayanırız. Ey Rabbimiz, bizimle kavmimizin arasındaki işi gerçekle açığa çıkar. Muhakkak ki sen gerçekleri açığa çıkaranların en üstünüsün!”"},{"n":90,"t":"“Eğer Şu‘ayb`a uyarsanız, muhakkak siz ziyana uğrarsınız!” dediler."},{"n":91,"t":"Derken o müthiş sarsıntı onları yakalayıverdi; yurtlarında diz üstü çöktüler."},{"n":92,"t":"Şu‘ayb`ı yalanlayanlar, sanki yurtlarında hiç oturmamış gibi oldular. Böylece Şu‘ayb`ı yalanlayanlar; işte asıl ziyana uğrayanlar onlar oldular!"},{"n":93,"t":"Şu‘ayb, onlardan ayrıldı ve “Ey kavmim!” dedi, “Ben size Rabbimin gönderdiği gerçekleri duyurdum ve size öğüt verdim, artık kâfir bir kavme nasıl acırım?”"},{"n":94,"t":"Biz hangi ülkeye bir peygamber gönderdiysek, ora halkını peygambere baş kaldırdıklarından ötürü Allah`a yalvarıp yakarsınlar diye mutlaka yoksulluk ve darlıkla sıkmışızdır."},{"n":95,"t":"Sonra kötülüğü değiştirip yerine iyilik getirdik. Nihayet çoğaldılar ve “Atalarımız da böyle sıkıntı ve sevinç yaşamışlardı” dediler. Biz de onları, kendileri farkına varmadan ansızın yakaladık."},{"n":96,"t":"O peygamberlerin gönderildiği ülkelerin halkı inanıp günahtan sakınsalardı, elbette onların üstüne gökten ve yerden nice bereket kapıları açardık; fakat yalanladılar, biz de ettikleri yüzünden onları yakalayıverdik."},{"n":97,"t":"Yoksa o ülkelerin halkı, geceleyin uyurlarken kendilerine azabımızın gelmeyeceğinden emin miydiler?"},{"n":98,"t":"Ya da o ülke halkı, kuşluk vakti eğlenirlerken kendilerine azabımızın gelmeyeceğinden emin mi oldular?"},{"n":99,"t":"Allah`ın azabından emin mi oldular? Fakat ziyana uğrayan topluluktan başkası, Allah`ın böyle mühlet vermesinden emin olamaz."},{"n":100,"t":"Önceki sahiplerinden sonra yeryüzüne vâris olanlara hâlâ şu gerçek belli olmadı mı ki, eğer biz dileseydik onları da günahlarından dolayı musibete uğratırdık! Biz onların kalplerini mühürleriz de onlar gerçekleri işitmezler/anlamazlar."},{"n":101,"t":"İşte o ülkeler... Onların haberlerinden bir kısmını sana anlatıyoruz. Andolsun ki, peygamberleri onlara apaçık deliller getirmişlerdi. Fakat önceden yalanladıkları gerçeklere iman edecek değillerdi. İşte, kâfirlerin kalplerini Allah böyle mühürler."},{"n":102,"t":"Onların çoğunda, sözünde durma diye bir şey bulamadık. Gerçek şu ki, onların çoğunu yoldan çıkmış bulduk."},{"n":103,"t":"Onlardan sonra, Mûsâ`yı mûcizelerimizle Firavun`a ve onun ileri gelen adamlarına gönderdik. Âyetlerimize haksızlık ettiler, fakat bak, bozguncuların sonu nasıl oldu?"},{"n":104,"t":"“Ey Firavun! Ben âlemlerin Rabbi tarafından gönderilen bir peygamberim.”"},{"n":105,"t":"“Allah hakkında yalnız gerçek olanı söylemek benim üzerime borçtur. Size Rabbinizden açık bir delil getirdim; artık İsrâiloğulları`nı benimle birlikte serbest bırak!”"},{"n":106,"t":"“Eğer bir mûcize getirdiysen ve gerçekten doğru söylüyorsan, onu ortaya çıkar.”"},{"n":107,"t":"Bunun üzerine Mûsâ asâsını yere attı, o hemen tam anlamıyla bir ejderha oluverdi."},{"n":108,"t":"Elini çıkardı. Birdenbire o da seyredenlere bembeyaz görünüverdi."},{"n":109,"t":"“Bu çok usta bir sihirbazdır.”"},{"n":110,"t":"“Sizi yurdunuzdan çıkarmak istiyor. Ne buyurursunuz?”"},{"n":111,"t":"“Onu da kardeşini de beklet; şehirlere toplayıcılar gönder.”"},{"n":112,"t":"“Bütün usta sihirbazları sana getirsinler.”"},{"n":113,"t":"Sihirbazlar Firavun`a geldiler, “Eğer üstün gelen biz olursak, bize kesin bir ödül var mı?” dediler."},{"n":114,"t":"Firavun, “Evet, hem de siz bana yakınlardan olacaksınız” dedi."},{"n":115,"t":"“Ey Mûsâ! Sen mi önce atacaksın, yoksa ilk atan biz mi olalım?” dediler."},{"n":116,"t":"“Siz atın” dedi. Onlar atınca, insanların gözlerini büyülediler, onları korkuttular ve büyük bir sihir gösterdiler."},{"n":117,"t":"Biz de Mûsâ`ya “Asânı at!” diye vahyettik. Bir de baktılar ki, bu onların uydurduklarını yakalayıp yutuyor."},{"n":118,"t":"Böylece gerçek ortaya çıktı ve onların yapmakta oldukları yok olup gitti."},{"n":119,"t":"İşte Firavun ve kavmi, orada yenildi ve küçük düşerek geri döndüler."},{"n":120,"t":"Sihirbazlar derhal secdeye kapandılar."},{"n":121,"t":"“Biz âlemlerin Rabb`ine inandık.”"},{"n":122,"t":"“Mûsâ ve Hârûn`un Rabbi`ne!”"},{"n":123,"t":"“Demek ben size izin vermeden ona inandınız ha! Bu, şehirde tezgâhladığınız bir tuzaktır ki, bununla şehir halkını oradan çıkarmak peşindesiniz. Yakında anlayacaksınız.”"},{"n":124,"t":"“Dönekliğinizden dolayı ellerinizi ve ayaklarınızı keseceğim, sonra da hepinizi asacağım.”"},{"n":"125-126","t":"Onlar, “Biz zaten Rabbimize döneceğiz. Sen sadece, Rabbimizin âyetleri bize geldiğinde onlara inandığımız için bizden intikam alıyorsun. Ey Rabbimiz! Bize bol bol sabır ver, Müslüman olarak canımızı al!” dediler."},{"n":127,"t":"“Mûsâ`yı ve kavmini, seni ve tanrılarını bırakıp yeryüzünde bozgunculuk yapsınlar diye mi bırakacaksın?” Firavun, “Biz onların oğullarını öldürüp kadınlarını sağ bırakacağız. Elbette biz onları ezecek üstünlükteyiz” dedi."},{"n":128,"t":"“Allah`tan yardım isteyiniz ve sabrediniz. Şüphesiz ki yeryüzü Allah`ındır. Kullarından dilediğini ona vâris kılar. Sonuç, Allah`tan sakınıp günahtan uzak duranlarındır.”"},{"n":129,"t":"Onlar da, “Sen peygamber olarak gelmeden önce de geldikten sonra da bize işkence edildi” dediler. Mûsâ, “Umulur ki Rabbiniz düşmanınızı helâk eder ve onların yerine sizi yeryüzüne hâkim kılar da nasıl hareket edeceğinize bakar” dedi."},{"n":130,"t":"Andolsun ki, Firavun`a uyanlar ders alsınlar diye, onları yıllarca kuraklık ve ürün kıtlığı ile cezalandırdık."},{"n":131,"t":"Onlara bir iyilik, bolluk gelince, “Bu bizim hakkımızdır” derler; eğer kendilerine bir fenâlık gelirse, Mûsâ ve onunla beraber olanların uğursuzluğuna sayarlardı. Bilesiniz ki onlara gelen uğursuzluk Allah katındandır, fakat onların çoğu bunu bilmezler."},{"n":132,"t":"“Bizi büyülemek için ne mucize getirirsen getir, biz sana inanacak değiliz.”"},{"n":133,"t":"Biz de ayrı ayrı mucizeler olarak onların üzerine tûfan, çekirge, haşere, kurbağa ve kan gönderdik. Yine de büyüklük tasladılar ve günahkâr bir kavim oldular."},{"n":134,"t":"Azap üzerlerine çökünce, “Ey Mûsâ! Sana verdiği söz hürmetine, bizim için Rabbine dua et! Eğer bizden azabı kaldırırsan, mutlaka sana inanacağız ve muhakkak İsrâiloğulları`nı seninle göndereceğiz” dediler."},{"n":135,"t":"Ulaşacakları bir müddete kadar onlardan azabı kaldırınca, hemen sözlerinden dönüverdiler."},{"n":136,"t":"Biz de, âyetlerimizi yalanlamaları ve onlardan gafil kalmaları sebebiyle kendilerinden intikam aldık ve onları denizde boğduk."},{"n":137,"t":"Hor görülüp ezilen topluluğu da, içini bereketlerle doldurduğumuz ülkenin doğu ve batısına mirasçı kıldık. Rabbinin İsrâiloğulları`na verdiği güzel söz, sabretmeleri nedeniyle yerine geldi. Firavun ve kavminin yapmakta olduklarını, yapıp yükselttiklerini yerle bir ettik."},{"n":138,"t":"“Siz gerçekten câhil bir toplumsunuz.”"},{"n":139,"t":"“Şu gördüklerinizin içinde bulundukları din çökmüştür. Yapmakta oldukları da boşa çıkacaktır.”"},{"n":140,"t":"“Ben, size tanrı olarak Allah`tan başkasını mı arayacakmışım? Halbuki O, sizi âlemlere üstün kılmıştır.”"},{"n":141,"t":"“Sizi Firavun hânedanından kurtarmıştık. Size azabın en kötüsü ile işkence ediyorlardı. Oğullarınızı öldürüyor, kadınlarınızı diri bırakıyorlardı. İşte bunda Rabbiniz tarafından büyük bir imtihan vardır.”"},{"n":142,"t":"“Kavmimin içinde benim yerime geç; onları ıslah et, bozguncuların yoluna uyma!”"},{"n":143,"t":"“Seni noksan sıfatlardan uzak tutarım, tövbe edip sana yöneldim. Ben iman edenlerin ilkiyim.”"},{"n":144,"t":"“Ey Mûsâ! Gönderdiğim âyetlerimle, konuşmamla seni insanların üstüne seçip yücelttim. Sana verdiğimi al ve şükredenlerden ol.”"},{"n":145,"t":"Öğüt ve her şeyin açıklamasına dair ne varsa hepsini Mûsâ için levhalarda yazdık. “Bunları kuvvetle tut, kavmine de onun en güzelini almalarını emret! Yakında size yoldan çıkmışların yurdunu göstereceğim.”"},{"n":146,"t":"Yeryüzünde haksız yere kibirlenenleri âyetlerimden uzak tutacağım. Onlar bütün mucizeleri görseler de iman etmezler. Doğru yolu görseler, onu yol edinmezler. Ama azgınlık yolunu görseler, onu yol edinirler. Bu durum, onların âyetlerimizi yalanlamalarından ve ondan gafil olmalarından ileri gelmektedir."},{"n":147,"t":"Delillerimizi ve âhirete kavuşmayı yalanlayanların bütün amelleri boşa gitmiştir. Onlar yapmakta olduklarının karşılığında başka bir ceza mı göreceklerdi ki?"},{"n":148,"t":"Mûsâ`nın arkasından kavmi, ziynet takımlarından böğürebilen bir buzağı heykelini tanrı edindiler. Görmediler mi ki o, onlarla ne konuşuyor ne de onlara yol gösteriyor. Onu tanrı olarak benimsediler ve zâlimler oldular."},{"n":149,"t":"“Eğer Rabbimiz bize acımaz ve bizi bağışlamazsa, mutlaka ziyana uğrayanlardan olacağız!”"},{"n":150,"t":"“Ey annem oğlu! Bu topluluk beni horlayıp hırpaladı. Neredeyse canımı alıyorlardı. Bir de sen düşmanları bana güldürtme! Beni şu zâlim topluluk ile bir tutma!”"},{"n":151,"t":"Mûsâ da, “Ey Rabbim! Beni ve kardeşimi bağışla! Bize merhamet et, zira sen merhametlilerin en merhametlisisin!” dedi."},{"n":152,"t":"Buzağıyı tanrı edinenler var ya, yakında onlara Rablerinin gazabı ve dünya hayatında bir zillet ulaşacaktır. Biz, iftiracıları böyle cezalandırırız."},{"n":153,"t":"Kötülükleri yaptıktan sonra tövbe edip de iman edenlere gelince; şüphesiz ki o tövbe edip inandıktan sonra, Rabbin elbette bağışlayandır; merhamet edendir."},{"n":154,"t":"Öfkesi dinince, Mûsâ levhaları aldı. Onlardaki yazıda Rablerinden korkanlar için yol gösterme ve rahmet vardı."},{"n":155,"t":"“Ey Rabbim! Dileseydin onları da beni de daha önce helâk ederdin. İçimizden birtakım beyinsizlerin işlediği yüzünden bizi helâk edecek misin? Bu, senin imtihanından başka bir şey değildir. Onunla dileyeni saptırır, dileyeni de doğru yola iletirsin. Bizim velîmiz sensin, bizi bağışla, bize merhamet et! Sen bağışlayanların en üstünüsün.”"},{"n":156,"t":"“Kimi dilersem, onu azabıma uğratırım; rahmetim ise her şeyi kuşatmıştır. Ayrıca rahmetimi, sakınanlara, zekâtı verenlere ve âyetlerimize inananlara yazacağım.”"},{"n":157,"t":"Onlar ki, yanlarındaki Tevrat ve İncil`de yazılmış bulacakları ümmî/annesinden doğduğu gibi saf peygambere uyarlar; peygamber onlara iyiliği emreder, kötülükten alıkoyar, güzel şeyleri onlara helâl kılar, pis şeyleri onlara yasaklar. Sırtlarındaki ağırlıklarını indirir, üzerlerindeki zincirleri kırıp atar. Ona inanan, onu destekleyen, ona yardım eden, onunla indirilen ışığa uyan kişiler, kurtuluşa erenlerin ta kendileridir."},{"n":158,"t":"“Ey insanlar! Gerçekten ben, göklerin ve yerin sahibi olan Allah`ın hepinize gönderdiği peygamberiyim. Ondan başka tanrı yoktur; O, diriltir ve öldürür. O halde Allah`a ve Peygamberi`ne iman ediniz. Allah`a ve O`nun sözlerine inanan o anasından doğduğu gibi ahlaklı olan peygambere iman edip uyunuz ki doğru yolu bulasınız.”"},{"n":159,"t":"Mûsâ toplumunda hak ile doğru yolu bulan ve onun sayesinde âdil davranan bir topluluk vardır."},{"n":160,"t":"Biz İsrâiloğulları`nı, on iki kabileye ayırdık. Kavmi kendisinden su isteyince, Mûsâ`ya, “Asânı taşa vur!” diye vahyettik. Ondan on iki pınar fışkırdı. Her oymak su içeceği yeri belledi. Onların üzerlerine bulutları gölgelik yaptık, kendilerine kudret helvası ve bıldırcın indirdik. Size verdiğimiz rızıkların temizlerinden yiyiniz! Fakat onlar emirlerimizi dinlememekle bize değil, kendilerine zulmediyorlardı."},{"n":161,"t":"“Bu ülkede yerleşiniz ve oranın ürünlerinden dilediğiniz gibi yararlanınız ve bunu yaparken ‘Bizden günahlarımızın yükünü kaldır` diye niyaz ediniz! Saygıda bulunarak kapıdan giriniz ki, sizin günahlarınızı bağışlayalım. İyilik yapanları kat kat ödüllendireceğiz.”"},{"n":162,"t":"Fakat onlardan zâlim olanlar kendilerine söylenen sözü başka bir sözle değiştirdiler. Biz de zulmetmeleri sebebiyle üzerlerine gökten bir belâ, bir âfet gönderdik."},{"n":163,"t":"Deniz kıyısında bulunan şehir halkının durumunu onlara sor! Hani onlar Cumartesi gününe saygısızlık gösterip haddi aşıyorlardı. Çünkü Cumartesi tatili yaptıkları gün, balıklar meydana çıkarak akın akın onlara gelirdi, Cumartesi tatili yapmadıkları gün de gelmezlerdi. İşte böylece biz, yoldan çıkmalarından dolayı onları imtihan ediyorduk."},{"n":164,"t":"İçlerinden bir grup, “Allah`ın helâk edeceği, yahut şiddetli bir azapla cezalandıracağı bir topluma ne diye öğüt verip duruyorsunuz?” deyince onlar, “Rabbimize karşı bir mazeret olsun diye ve bir de sakınırlar ümidiyle” şeklinde cevap verdiler."},{"n":165,"t":"Kendilerine verilen öğüdü unuttuklarında, kötülükten alıkoyanları kurtarıp, zulmedenleri de yapmakta oldukları kötülüklerden dolayı şiddetli bir azap ile cezalandırdık."},{"n":166,"t":"Sonra da, kendilerine yasaklanan şeyleri yapmakta küstahça direttikleri zaman onlara, “Aşağılık maymunlar olun!” dedik."},{"n":167,"t":"Rabbin, kıyamet gününe kadar kendilerine azabın en kötüsünü yapacak kimseleri üzerlerine göndereceğini bildirmişti. Rabbin cezayı çabuk verendir. Yine de O, çok affedici, çok merhametlidir."},{"n":168,"t":"Onları yeryüzünde birçok topluluğa böldük. İçlerinden bazıları iyi kimselerdi; bazıları ise böyle değildi. İyi olmayanları, yanlışlarından belki dönerler diye, iyilik ve kötülüklerle imtihan ettik."},{"n":169,"t":"Onların ardından da, âyetleri tahrif karşılığında şu değersiz dünya malını alıp, “Nasıl olsa bağışlanacağız” diyerek kitaba vâris olan birtakım kötü kimseler geldi. Onlara, ona benzer bir menfaat daha gelse onu da alırlar. Peki, kitapta Allah hakkında gerçekten başka bir şey söylemeyeceklerine dair onlardan söz alınmamış mıydı ve onlar kitaptakini okumamışlar mıydı? Âhiret yurdu, sakınanlar için daha hayırlıdır. Hâlâ aklınız ermiyor mu?"},{"n":170,"t":"Kitaba sarılıp namazı dosdoğru kılanlar var ya, işte biz böyle barışsever iyilerin ödülünü zayi etmeyiz."},{"n":171,"t":"Bir zamanlar, dağı İsrailoğulları`nın tepesine bir gölgelik gibi çekmiştik de onu üstlerine düşüyor sanmışlardı. “Size verdiğimiz kitabı kuvvetle tutunuz ve içindekini hatırınızdan çıkarmayınız ki korunabilesiniz” dedik."},{"n":172,"t":"“Ben sizin Rabbiniz değil miyim?” Onlar da, “Evet, buna şâhit olduk” dediler."},{"n":173,"t":"Ya da “Daha önce atalarımız şirke batmıştı. Biz de onların ardından gelen bir soyuz. Gerçeği çiğneyenler yüzünden bizi helâk mi edeceksin?” demeyesiniz."},{"n":174,"t":"İşte, biz de âyetleri böyle açık açık dile getiriyoruz ki, günah işlemiş olanlar belki bizden yana dönerler."},{"n":175,"t":"Onlara şu adamın haberini oku! Kendisine âyetlerimizi vermiştik; fakat onlardan sıyrılıp çıktı. Ondan dolayı şeytan kendisini takip etti ve sonunda azgınlardan oldu."},{"n":176,"t":"Üstüne varsan da dilini sarkıtarak solur, kendi haline bıraksan da... Âyetlerimizi yalanlayan toplumun örneği işte budur. Bu hikâyeyi anlat ki, düşünsünler."},{"n":177,"t":"Âyetlerimizi yalanlayan ve kendine zulmedegelen gürûhun durumu ne kötü misaldir!"},{"n":178,"t":"Allah`ın doğru yola yönelttiği kişi, hidayettedir. O`nun sapıklık içinde bıraktığı kimselere gelince, onlar kaybedenlerin ta kendileridir."},{"n":179,"t":"Andolsun ki, kalpleri olup düşünmeyen, gözleri olup görmeyen, kulakları olup dinlemeyen cinleri ve insanları cehennem için yarattık. Bunlar hayvan gibidirler; hatta daha da aşağıdırlar. İşte gâfil olanlar böyleleridir."},{"n":180,"t":"En güzel isimler Allah`ındır. Bu güzel isimlerle O`na dua ediniz! Uygun olmayan isimlerle O`nu isimlendirenleri terk ediniz! Onlar yapmakta olduklarının cezasını yakında çekeceklerdir."},{"n":181,"t":"Yarattıklarımızdan öyle bir millet var ki, daima hakka iletir ve adâleti hak ile yerine getirir."},{"n":182,"t":"Âyetlerimizi yalanlayanları, hiç bilemeyecekleri yerden adım adım helâke yaklaştırırız."},{"n":183,"t":"Onlara mühlet veriyorum; cezalandırmam çok çetindir."},{"n":184,"t":"Kendilerinden biri olan peygamberde delilik olmadığını düşünmediler mi? O, apaçık bir uyarıcıdır."},{"n":185,"t":"Göklerin ve yerin hükümranlığı konusunda, Allah`ın yarattığı her şeyi ve ecellerinin yaklaşmış olabileceğini düşünmediler mi? O halde Kur`ân`dan sonra hangi söze inanacaklar?"},{"n":186,"t":"Allah`ın saptırdığını doğru yola götürecek kimse yoktur. Allah onları azgınlıkları içinde şaşkın olarak bırakır."},{"n":187,"t":"“Onun ilmi Allah katındadır. Fakat insanların çoğu bu gerçeği bilmiyorlar.”"},{"n":188,"t":"“Allah dilemedikçe ben kendime bir fayda ve zarar verecek güce sahip değilim. Eğer gaybı bilseydim, elbette iyiliği arttırırdım ve bana kötülük de dokunmazdı. Ben sadece, inanan bir toplum için bir uyarıcı ve müjdeleyiciyim.”"},{"n":189,"t":"Sizi tek bir cevherden yaratan ve gönlünün huzura kavuşacağı eşini de o cevherden var eden, Allah`tır. Eşine sarılınca, eşi hamile kaldı ve onu bir müddet taşıdı. Gebeliği ağırlaşınca, karı koca, Rableri Allah`a, “Bize kusursuz bir çocuk verirsen andolsun, şükredenlerden olacağız” diye yalvardılar."},{"n":190,"t":"Allah onlara kusursuz bir çocuk verince, kendilerine verdiği evlat konusunda Allah`a ortaklar koştular. Allah onların ortak koştuğu şeylerden uzaktır."},{"n":191,"t":"Kendileri yaratılmakta olan ve bir şey yaratamayan putları mı Allah`a ortak koşuyorlar?"},{"n":192,"t":"Oysa, putlar onlara da yardım edecek güçte değil ve kendilerine de yardım edemezler."},{"n":193,"t":"O putları doğru yola çağırsanız size uyamazlar. Onları çağırsanız da sussanız da sizin için birdir."},{"n":194,"t":"Allah`tan başka yalvardıklarınız, sizin gibi kullardır. Eğer doğru sözlü iseniz, onları çağırın da size cevap versinler."},{"n":195,"t":"“Ortaklarınızı çağırınız, sonra bana tuzak kurup göz açtırmayınız.”"},{"n":196,"t":"Şüphesiz ki benim koruyanım, kitabı indiren Allah`tır ve o bütün iyi kullarını görüp gözetir."},{"n":197,"t":"Allah`ın dışında taptıklarınızın, ne size yardıma güçleri yeter ne de kendilerine yardım edebilirler."},{"n":198,"t":"Onları doğru yola çağırmış olsanız, işitmezler. Onları sana bakar görürsün, oysa onlar görmezler."},{"n":199,"t":"Sen, affetme yolunu tut/tedbirini al! Uygun olanı emret, câhillerden yüz çevir!"},{"n":200,"t":"Şayet şeytan, senin içine bir vesvese düşürürse Allah`a sığın; çünkü O, işitir; bilir."},{"n":201,"t":"Takvâ sahipleri var ya, onlara şeytan tarafından bir vesvese dokunduğunda, düşünüp hemen görürler."},{"n":202,"t":"Şeytanın kardeşleri onları azgınlığa çekerler, hiç yakalarını bırakmazlar."},{"n":203,"t":"“Ben ancak Rabbim tarafından bana vahyolunana uyarım. Bu kitap, Rabbinizden gelen göz açıcı belgeler olup, inanmış bir topluma rehber ve rahmettir.”"},{"n":204,"t":"Kur`ân okunduğu zaman susup onu dinleyiniz ki, size merhamet edilsin!"},{"n":205,"t":"Sen ey Peygamber, alçak gönüllülükle, korku ve duyarlık içinde, sesini yükseltmeden, sabah akşam kendi içinde Rabbini an ve sakın gafillerden biri olma!"},{"n":206,"t":"Şüphesiz, Rabbine yakın olanlar, O`na kulluk yapmaktan asla kibre kapılmazlar; O`nu noksan sıfatlardan uzak tutar ve sadece O`na secde ederler."}],[{"n":1,"t":"“Ganimetler Allah ve Peygamberi`ne aittir. O halde Allah`tan sakınınız, aranızda barış ve esenliği sağlayınız. Eğer müminler iseniz, Allah ve Rasûlü`ne itaat ediniz.”"},{"n":2,"t":"Müminler ancak o kişilerdir ki, Allah anıldığında yürekleri ürperir ve onlara Allah`ın âyetleri okunduğunda, bu onların imanlarını arttırır ve onlar yalnız Rablerine güvenip dayanırlar."},{"n":3,"t":"Onlar namazı dosdoğru kılarlar ve kendilerine rızık olarak verdiğimiz şeylerden Allah yolunda harcarlar."},{"n":4,"t":"İşte onlar gerçek müminlerdir. Rableri katında yüksek dereceler, bağışlanma ve onlar için bol rızık vardır."},{"n":5,"t":"Hani, müminlerden bir grup tamamen isteksiz olmasına rağmen Rabbin seni hak uğruna öz yurdundan çıkartmıştı."},{"n":6,"t":"İş apaçık ortaya çıktıktan sonra bile, hak konusunda seninle çekişiyorlardı. Sanki onlar, göz göre göre ölüme sürükleniyorlardı."},{"n":7,"t":"Hatırlayınız ki, Allah size iki gruptan/kervan veya Kureyş ordusundan birinin sizin olduğunu vaad ediyordu. Siz de kuvvetsiz olanın kervanın sizin olmasını istiyordunuz. Oysa Allah, sözleriyle hakkı gerçekleştirmek ve Kureyş ordusunu yok ederek kâfirlerin ardını kesmek istiyordu."},{"n":8,"t":"Bu istek, günahkârların hoşuna gitmese de hakkı gerçekleştirmek ve bâtılı ortadan kaldırmak içindi."},{"n":9,"t":"“Hiç kuşkunuz olmasın, ben size meleklerden birbiri ardınca bin tanesiyle yardım ulaştıracağım.”"},{"n":10,"t":"Allah bunu, sadece bir müjde olsun ve o sayede kalpleriniz huzur ve rahatlık bulsun diye yaptı. Yardım yalnız ve yalnız Allah katındadır. Hiç şüphesiz Allah, mülkünde galiptir; işlerini yerli yerinde yapandır."},{"n":11,"t":"O zaman sizi, Allah`tan bir güven olmak üzere hafif bir uyku bürüyordu; sizi onunla manen temizlemek, şeytanın pisliğini sizden gidermek, kalplerinizi birbirine bağlamak, ayaklarınızı sağlam bastırmak için üzerinize gökten bir su indiriyordu."},{"n":12,"t":"“Ben sizinle beraberim. İmanı olanları sağlamlaştırınız. İnkâr edenlerin kalplerine korku salacağım. Vurun boyunlarına, vurun onların bütün parmaklarına!”"},{"n":13,"t":"Bu durum, onların Allah ve O`nun peygamberine karşı çıkmalarındandır. Kim Allah ve O`nun peygamberine karşı çıkarsa bilsin ki Allah, azabında çok zorludur."},{"n":14,"t":"İşte bu yenilgi, size Allah`ın azabıdır. İşte siz o azabı tadınız! İnkârcılara bir de cehennem ateşinin azabı vardır."},{"n":15,"t":"Ey iman edenler! İnkâr edenlerle savaşmak üzere karşılaştığınızda, sakın onlara arkanızı dönmeyiniz!”"},{"n":16,"t":"Tekrar savaşmak için bir tarafa çekilmek veya diğer bir birliğe ulaşıp mevzi tutma durumu dışında, kim öyle bir günde onlara arka çevirirse, elbette o, Allah`ın azabını hak etmiş olarak döner. Onun yeri de cehennemdir; orası, varılacak ne kötü yerdir!"},{"n":17,"t":"Savaşta onları siz öldürmediniz, onları Allah öldürdü. Attığın zaman sen atmadın, fakat Allah attı. Bunu da müminleri güzel bir imtihanla sınamak için yaptı. Doğrusu Allah işitendir; bilendir."},{"n":18,"t":"İşte size Allah`ın lütfu! Allah, kâfirlerin tuzaklarını boşa çıkartır."},{"n":19,"t":"Zafer mi istiyordunuz, işte zafer size ulaştı. Eğer vazgeçerseniz, hakkınızda daha hayırlı olur. Eğer dönerseniz, biz de döneriz. Topluluğunuz çok da olsa, size zerre kadar yarar sağlamaz. Allah müminlerle beraberdir."},{"n":20,"t":"Ey iman edenler! Allah ve Peygamberine itaat ediniz, işittiğiniz halde O`ndan yüz çevirmeyiniz!"},{"n":21,"t":"İşitmedikleri halde “işittik” diyenler gibi olmayınız!"},{"n":22,"t":"Şüphesiz Allah katında canlıların en kötüsü, düşünmeyen sağırlar ve dilsizlerdir."},{"n":23,"t":"Allah onlarda bir hayır görseydi, elbette onlara işittirirdi. Fakat işittirseydi bile onlar yüz çevirerek dönerlerdi."},{"n":24,"t":"Ey inananlar! Hayat verecek şeylere sizi çağırdığı zaman, Allah ve Peygamberine uyunuz ve biliniz ki, Allah kişi ile onun kalbi arasına girer; siz mutlaka O`nun huzurunda toplanacaksınız."},{"n":25,"t":"Bir de öyle bir fitneden sakınınız ki, o fitne, içinizden sadece zulmedenlere erişmekle kalmaz, umuma yayılır ve hepsini perişan eder. Biliniz ki Allah, azabında çok zorludur."},{"n":26,"t":"Yeryüzünde az olduğunuz ve zayıf sayıldığınız için insanların sizi kapıp götürmesinden korktuğunuz zamanları hatırlayınız. Bunun için Allah size yer ve yurt verip barındırdı, yardımıyla destekledi ve şükredesiniz diye size iyi ve hoş rızıklar da verdi."},{"n":27,"t":"Ey inananlar! Allah`a ve Peygamberine ihanet etmeyiniz! Bile bile, size güvenilen şeylere ihanet etmiş olursunuz."},{"n":28,"t":"Doğrusu, mallarınızın ve çocuklarınızın sizin için bir sınav olduğunu, büyük ödülün Allah`ın katında bulunduğunu biliniz!"},{"n":29,"t":"Ey iman edenler! Eğer Allah`tan sakınırsanız, O, size iyiyi kötüden ayıracak bir kabiliyet verir; günahlarınızı örter ve sizi bağışlar. Çünkü Allah büyük lütuf sahibidir."},{"n":30,"t":"Hani, inkârcılar seni bağlayıp bir yere hapsetmek ya da öldürmek veya seni yurdundan çıkarmak için tuzak kuruyorlardı. Onlar tuzak kurarken, Allah da karşı tuzak kuruyordu. Allah tuzağı boşa çıkaranların en güçlüsüdür."},{"n":31,"t":"“İşittik; istesek biz de bunun benzerini elbette söyleyebiliriz. Bu, öncekilerin masallarından başka bir şey değildir.”"},{"n":32,"t":"Hani yine onlar, “Allahımız! Eğer bu kitap senin katından gelen gerçek ise, gökten üzerimize taş yağdır veya bize elem verici bir azap ver!” demişlerdi."},{"n":33,"t":"Halbuki sen onların içinde iken Allah onlara azap verecek değildir ve aralarındaki müminler bağışlanma dilerken de şüphesiz Allah onlara azap etmez."},{"n":34,"t":"Onlar Mescid-i Harâm`ın yöneticileri olmadıkları halde müminleri oradan geri çevirirlerken, Allah onlara ne diye azap etmeyecek? Oranın yöneticileri takvâ ehlinden başkası değildir. Fakat onların çoğu bunu bilmez."},{"n":35,"t":"Onların Beytullah`taki duaları da ıslık çalmak ve el çırpmaktan başka bir şey değildir. Ey inkârcılar! İnkâr etmekte olduğunuz şeylerden ötürü şimdi azabı tadınız!"},{"n":36,"t":"Şüphesiz ki kâfirler mallarını, insanları Allah yolundan alıkoymak için harcıyorlar, daha da harcayacaklardır; ama sonunda bu, onlara yürek acısı olup en sonunda mağlûp olacaklardır. İnkârda ısrar edenler ise cehennemde toplanacaklardır."},{"n":37,"t":"Bu toplanma, Allah`ın murdârı temizden ayırması ve bütün murdârların bir kısmını diğer bir kısmının üstüne koyup yığarak cehenneme atması içindir. İşte onlar ziyana uğrayanların ta kendileridir."},{"n":38,"t":"İnkâr edenlere, iman edip sana düşmanlıktan vazgeçerlerse, geçmiş günahlarının bağışlanacağını söyle! Yok eğer inkâra geri dönerlerse, kendilerinden öncekilerin hali gözlerinin önündedir."},{"n":39,"t":"Yeryüzünde fitne/din farklılığının getirdiği baskı ortadan kalkıp din tamamen Allah`ın oluncaya kadar onlarla savaşınız. İnkâr ve fitneden vazgeçerlerse şüphesiz ki Allah onların yaptıklarını çok iyi görür."},{"n":40,"t":"Eğer yüz çevirirlerse biliniz ki, Allah sizin sahibinizdir. O, ne güzel sahip ve ne güzel yardımcıdır!"},{"n":41,"t":"Eğer Allah`a ve bir de hak ile bâtılın ayrıldığı, iki ordunun karşılaştığı gün, kulumuza indirdiğimize iman etmişseniz biliniz ki, savaşta elde ettiğiniz ganimetlerin beşte biri Allah`a, Peygamber`e, yakınlarına, yetimlere, yoksullara ve yolda kalmış olanlara aittir. Allah, her şeye gücü yetendir."},{"n":42,"t":"Hatırlayınız ki, Bedir Savaşı`nda siz vadinin yakın yamacında Medine tarafında idiniz; onlar da uzak yamacında Mekke tarafında idiler. Kervan sizden daha aşağıda, deniz sahilinde idi. Eğer savaş için sözleşmiş olsaydınız, sözleştiğiniz vakit hususunda ihtilâfa düşerdiniz. Fakat Allah gerekli olan emri yerine getirmesi, helâk olanın açık bir delille gözüyle gördükten sonra helâk olması, yaşayanın da açık bir delille yaşaması için böyle yaptı. Çünkü Allah hakkıyla işitendir; bilendir."},{"n":43,"t":"Hatırla ki Allah, uykunda sana onları az gösterdi. Eğer onları sana çok gösterseydi, elbette çekinecek ve bu iş hakkında münakaşaya girişecektiniz. Fakat Allah sizi bundan kurtardı. Şüphesiz O, kalplerin iç yüzünü bilir."},{"n":44,"t":"Allah, olacak bir işi yerine getirmek için savaş alanında karşılaştığınız zaman, onları sizin gözünüzde az gösteriyor, sizi de onların gözünde azaltıyordu. Bütün işler Allah`a döner."},{"n":45,"t":"Ey iman edenler! Herhangi bir topluluk ile karşılaştığınız zaman sebat ediniz ve Allah`ı çok anınız ki başarıya erişesiniz."},{"n":46,"t":"Allah`a ve Peygamber`ine itaat ediniz, birbirinizle çekişmeyiniz, sonra korkuya kapılıp dağılırsınız da sosyal gücünüz gider. Sabrediniz! Çünkü Allah sabredenlerle beraberdir."},{"n":47,"t":"İnsanlara çalım satarak, gösteriş yaparak yurtlarından çıkan ve Allah yolundan alıkoyanlar gibi olmayınız. Allah, onların yaptıklarını çepeçevre kuşatmıştır."},{"n":48,"t":"Hani şeytan onlara yaptıklarını süslü gösterdi de, “Bugün insanlardan size galip gelecek kimse yoktur; şüphesiz ben de sizin yardımcınızım” dedi. Fakat iki ordu birbirini görünce ardına döndü ve “Ben sizden uzağım, ben sizin görmediklerinizi görüyorum, ben Allah`tan korkuyorum, Allah`ın azabı şiddetlidir” dedi."},{"n":49,"t":"Münafıklar ve kalplerinde hastalık bulunanlar, sizin için, “Bunları dinleri aldatmış” diyorlardı. Oysa kim Allah`a dayanırsa Allah daima galiptir; hüküm ve hikmet sahibidir."},{"n":50,"t":"Görseydin o inkâr edenleri. Melekler onların canlarını alırken yüzlerine ve arkalarına vuruyorlar ve “Haydi yakıcı azabı tadın!” diyorlardı."},{"n":51,"t":"İşte bu, ellerinizle yapıp ettikleriniz yüzündendir. Şüphesiz Allah, kullara zulmedici değildir."},{"n":52,"t":"Bunlar da tıpkı Firavun ailesi ve onlardan öncekilerin gidişi gibi davrandılar. Onlar da Allah`ın âyetlerini inkâr etmişlerdi; Allah onları, günahları yüzünden yakalayıp cezalandırmıştı. Şüphesiz Allah güçlüdür; cezası çok çetindir."},{"n":53,"t":"Bu böyledir. Bir toplum, kendilerinde bulunanı değiştirmedikçe, Allah da onlara verdiği nimeti değiştirmez. Şüphesiz Allah işitendir; bilendir."},{"n":54,"t":"Firavun`un adamlarının ve onlardan öncekilerin yaptığı gibi, bunlar da Rabblerinin âyetlerini yalanladılar. Biz de günahlarına karşılık onları yok ettik ve Firavun taifesini suda boğduk. Bunların hepsi zâlim kimselerdi."},{"n":55,"t":"Allah katında canlıların en kötüsü kâfirlerdir; artık onlar inanmazlar."},{"n":56,"t":"Sen kendileriyle anlaşma yaptığın halde onlar, hiç çekinmeden her defasında anlaşmalarını bozarlar."},{"n":57,"t":"Savaşta onları yakalarsan, onlarla birlikte arkalarında bulunan kimseleri de dağıt ki ders alsınlar."},{"n":58,"t":"Bir kavmin ihanet etmesinden korkarsan, sen de aynı şekilde onlarla yaptığın antlaşmayı onlara at; çünkü Allah, ihanet edenleri sevmez."},{"n":59,"t":"İnkâr edenler, bizim elimizden kurtulup geçtiklerini sanmasınlar. Onlar bizi âciz bırakamazlar."},{"n":60,"t":"Onlara karşı gücünüzün yettiğince kuvvet hazırlayınız. Ordugâhlarda atlar besleyiniz. Böylece hem Allah`ın düşmanını, hem kendi düşmanınızı, hem de onlardan başka sizin bilmediğiniz, Allah`ın bildiği düşman kimseleri korkutursunuz. Allah yolunda ne harcarsanız size eksiksiz ödenir; siz asla haksızlığa uğratılmazsınız."},{"n":61,"t":"Eğer onlar barışa yanaşırlarsa sen de ona yanaş ve Allah`a tevekkül et! Çünkü Allah her şeyi işitendir; her şeyi bilendir."},{"n":62,"t":"Eğer sana hile yapmak isterlerse bil ki Allah sana yeter. O, seni yardımıyla ve müminlerle destekleyendir."},{"n":63,"t":"Müminlerin kalplerini kaynaştırmıştır. Sen yeryüzünde bulunan her şeyi verseydin, yine onların gönüllerini kaynaştıramazdın; fakat Allah onların gönüllerini kaynaştırdı. Çünkü Allah, mutlak galiptir; hikmet sahibidir."},{"n":64,"t":"Ey Peygamber! Sana ve sana uyan müminlere Allah yeter."},{"n":65,"t":"Ey Peygamber! Müminleri savaşa teşvik et! Eğer sizden sabırlı yirmi kişi bulunursa, iki yüz kâfire galip gelirler. Eğer sizden yüz kişi olursa, kâfir olanlardan bin kişiye galip gelirler. Çünkü onlar anlamayan bir topluluktur."},{"n":66,"t":"Şimdi Allah yükünüzü hafifletti, sizde bir zayıflık olduğunu bildi. O halde sizden sabırlı yüz kişi bulunursa, onlardan iki yüz kişiye galip gelir. Eğer sizden bin kişi olursa, Allah`ın izniyle onlardan iki bin kişiye galip gelirler. Allah sabredenlerle beraberdir."},{"n":67,"t":"Yeryüzünde ağır basıncaya kadar, hiçbir peygambere esir sahibi olmak yaraşmaz. Siz geçici dünya malını istiyorsunuz; halbuki Allah sizin için âhireti istiyor. Allah güçlüdür; hikmet sahibidir."},{"n":68,"t":"Allah tarafından önceden verilmiş bir hüküm olmasaydı, aldığınız fidyeden ötürü size mutlaka büyük bir azap dokunurdu."},{"n":69,"t":"Artık elde ettiğiniz ganimetten helâl ve temiz olarak yiyiniz. Allah`tan sakınınız. Şüphesiz ki Allah, bağışlayandır; merhamet edendir."},{"n":70,"t":"Eğer Allah kalplerinizde hayır olduğunu bilirse, sizden alınandan daha hayırlısını size verir ve sizi bağışlar. Çünkü Allah bağışlayandır; merhamet edendir."},{"n":71,"t":"Esirler sana ihanet etmek isterlerse, daha önce Allah`a da ihanet etmişlerdi de Allah onlara karşı sana imkân ve kudret vermişti. Allah bilendir; hikmet sahibidir."},{"n":72,"t":"İman edip de hicret edenler, Allah yolunda mallarıyla, canlarıyla cihad edenler ve muhacirleri barındırıp yardım edenler var ya, işte onların bir kısmı diğer bir kısmının dostlarıdır. İman edip de hicret etmeyenlere gelince, onlar hicret edinceye kadar size onların mirasından hiçbir pay yoktur. Eğer onlar din hususunda sizden yardım isterlerse, sizinle aralarında sözleşme bulunan bir kavim aleyhine olmaksızın, yardım etmeniz gerekir. Allah bütün yaptıklarınızı hakkıyla görmektedir."},{"n":73,"t":"İnkârcılar da birbirlerinin yardımcılarıdır. Eğer siz Allah`ın emirlerini yerine getirmezseniz, yeryüzünde bir fitne ve büyük bir fesat olur."},{"n":74,"t":"İman edip de Allah yolunda hicret ve cihad edenler, muhacirleri barındırıp onlara yardım edenler var ya, işte gerçek müminler onlardır. Onlar için af ve bol rızık vardır."},{"n":75,"t":"Sonradan iman eden ve hicret edip de sizinle beraber cihad edenler de sizdendir. Allah`ın kitabına göre, yakın akrabalar birbirlerine daha uygundur. Şüphesiz ki Allah, her şeyi hakkıyla bilendir."}],[{"n":1,"t":"Allah ve Peygamber`inden kendileriyle antlaşma yapmış olduğunuz müşriklere bir ihtar!"},{"n":2,"t":"Yeryüzünde dört ay daha serbestçe dolaşınız ve biliniz ki siz Allah`ı asla âciz bırakamazsınız; Allah ise kâfirleri rezil edecektir."},{"n":3,"t":"Allah ve Rasûlü müşriklerle ilişkisini kesmiştir. Eğer tövbe ederseniz, bu sizin için daha hayırlıdır; eğer yüz çevirirseniz biliniz ki, siz Allah`ı âciz bırakacak değilsiniz. Kâfirlere elem verici azabı müjdele!"},{"n":4,"t":"Ancak, kendileriyle antlaşma yaptığınız müşriklerden antlaşma şartlarına uyan hiçbir şeyi size eksik bırakmayan ve sizin aleyhinize herhangi bir kimseye arka çıkmayanlar bu hükmün dışındadır. Onlara verdiğiniz söze, süresi bitinceye kadar riayet ediniz. Allah, sakınanları sever."},{"n":5,"t":"Haram aylar çıkınca sizinle savaşan müşrikleri bulduğunuz yerde öldürünüz; onları yakalayınız; onları hapsediniz ve onları her gözetleme yerinde oturup bekleyiniz. Eğer tövbe eder, namazı dosdoğru kılar, zekâtı da verirlerse, artık onları serbest bırakınız. Allah affedendir; merhamet edendir."},{"n":6,"t":"Müşriklerden biri senden güvence isterse, Allah`ın kelâmını anlaması için ona fırsat ver; sonra yine Müslüman olmazsa onu güven içinde bulunacağı bir yere ulaştır. İşte bu müsamaha, onların bilmeyen bir kavim olmalarından dolayıdır."},{"n":7,"t":"Şirk koşanların Allah katında ve Peygamber`inin yanında nasıl antlaşmaları olabilir? Ancak Mescid-i Harâm`da antlaştıklarınız hariçtir. Onlar size dürüst davrandıkça siz de onlara dürüst davranınız; çünkü Allah, müttakîleri/sakınanları sever."},{"n":8,"t":"Evet Allah ve Peygamber`i katında onların nasıl antlaşması olabilir? Eğer onlar size galip gelselerdi, sizin hakkınızda ne and ne de antlaşma gözetirlerdi. Ağızlarıyla sizi razı ederler; fakat kalpleri sizi istemez. Zaten onların çoğu yoldan çıkmış kimselerdir."},{"n":9,"t":"Allah`ın âyetlerini az bir değere sattılar da, böylece insanları Allah yolundan engellediler. Onların yaptıkları gerçekten ne kötüdür!"},{"n":10,"t":"Bir mümine karşı ne and ne de antlaşma gözetirler. İşte saldırganlar onlardır."},{"n":11,"t":"Tövbe eder, namaz kılar ve zekât verirlerse artık onlar dinde kardeşlerinizdir. Biz, anlayacak bir topluluğa âyetlerimizi böyle açıklıyoruz."},{"n":12,"t":"Antlaşmalarından sonra yeminlerini bozar ve dininize saldırırlarsa, küfrün önderlerine karşı savaşınız! Çünkü onların yeminleri yoktur. Böyle yaparsanız umulur ki yaptıklarına son verirler."},{"n":13,"t":"Yeminlerini bozan, Peygamber`i yurdundan çıkarmaya gayret eden bir topluluğa karşı savaşmayacak mısınız? Üstelik size saldırıyı önce onlar başlattı. Yoksa onlardan korkuyor musunuz? Eğer müminler iseniz, biliniz ki asıl çekinilmesi gereken Allah`tır."},{"n":14,"t":"Onlarla savaşınız ki, Allah sizin ellerinizle cezalandırsın, rezil etsin onları; sizi onlara karşı galip kılsın ve mümin toplumun kalplerini ferahlatsın!"},{"n":15,"t":"Kâfirlerin kalplerinden öfkeyi gidersin. Allah dileyenin tövbesini kabul eder. Allah bilendir; hikmet sahibidir."},{"n":16,"t":"Yoksa Allah sizden, cihad edip Allah, Peygamber ve müminlerden başkasını kendilerine sırdaş edinmeyenleri ortaya çıkarmadan, kendi halinize bırakılacağınızı mı sandınız? Allah yaptıklarınızdan haberdardır."},{"n":17,"t":"Müşrikler, kendilerinin kâfirliğine bizzat şahitlik ederken, Allah`ın mescidlerini imar etme yükümlülüğüne sahip değillerdir. Onların bütün amelleri boşa gitmiştir ve onlar ateşte süreli kalacaklardır."},{"n":18,"t":"Allah`ın mescidlerini ancak Allah`a ve âhiret gününe iman eden, namazını dosdoğru kılan, zekâtı veren ve Allah`tan başkasından korkmayan kimse imar eder. İşte doğru yola ermişlerden olmaları umulanlar bunlardır."},{"n":19,"t":"Ey müşrikler! Siz hacılara su vermeyi ve Mescid-i Harâm`ı onarmayı, Allah`a ve âhiret gününe iman edip de Allah yolunda cihad edenlerin imanıyla bir mi tutuyorsunuz? Halbuki onlar Allah katında eşit değillerdir. Allah, zâlimler topluluğunu hidayete erdirmez."},{"n":20,"t":"İman edip de hicret edenlerin, Allah yolunda mal ve canlarıyla cihad edenlerin mertebeleri Allah katında daha üstündür. Kurtuluşa erenler de işte, onlardır."},{"n":21,"t":"Rableri onlara, tarafından bir rahmet ve hoşnutlukla, kendileri için, içinde tükenmez nimetler bulunan cennetler müjdeler."},{"n":22,"t":"Onlar orada süreli kalacaklardır. Şüphesiz en büyük ödül, Allah katında olandır."},{"n":23,"t":"Ey iman edenler! Eğer küfrü imana tercih ediyorlarsa, babalarınızı ve kardeşlerinizi dost edinmeyiniz. Sizden kim onları dost edinirse, işte onlar zâlimlerin ta kendileridir."},{"n":24,"t":"Eğer babalarınız, oğullarınız, kardeşleriniz, eşleriniz, hısım ve akrabanız, kazandığınız mallar, kaybolmasından korktuğunuz ticaret, hoşlandığınız meskenler size Allah`tan, Peygamber`inden ve Allah yolunda cihad etmekten daha sevgili ise, artık Allah emrini yerine getirinceye kadar bekleyiniz. Allah, fâsıklar topluluğunu doğru yola erdirmez."},{"n":25,"t":"Yemin olsun ki, Allah size birçok yerde yardım etti. Huneyn Savaşı`nda da size yardım etti. Hani çokluğunuz sizi böbürlendirmiş, fakat bu hal, sizi hezimete uğramaktan kurtaramamıştı. Yeryüzü bütün genişliğine rağmen size dar gelmişti, sonunda gerisin geri dönmüştünüz."},{"n":26,"t":"Sonra Allah, Peygamber`in ve müminlerin üzerine güven duygusunu indirdi. Sizin görmediğiniz ordular indirdi de kâfirlere azap etti. İşte bu, o kâfirlerin cezasıdır."},{"n":27,"t":"Artık bunun ardından Allah yine dileyenin tövbesini kabul eder. Çünkü Allah affedendir; merhamet sahibidir."},{"n":28,"t":"Ey iman edenler! Biliniz ki müşrikler sadece bir pisliktir. Artık onlar bu yıllardan sonra Mescid-i Harâm`a yaklaşmasınlar. Eğer yoksulluktan endişe ederseniz, Allah dilerse kendi lütfundan sizi zengin edecektir. Allah bilendir; hikmet sahibidir."},{"n":29,"t":"Kendilerine kitap verilenlerden Allah`a ve âhiret gününe inanmayan, Allah ve Peygamber`inin haram kıldığını haram saymayan ve hak dini kendine din edinmeyen kimselerle, boyun büküp kendi elleriyle cizye verinceye kadar savaşınız."},{"n":30,"t":"Yahudiler, “Üzeyir, Allah`ın oğludur” dediler. Hıristiyanlar da, “Mesîh, Allah`ın oğludur” dediler. Bu, onların ağızlarında geveledikleri sözlerdir. Sözlerini daha önce kâfir olmuş kimselerin sözlerine benzetiyorlar. Allah onları kahretsin! Nasıl da döndürülüyorlar!"},{"n":31,"t":"Yahudiler Allah`ı bırakıp bilginlerini, hahamlarını; Hıristiyanlar da rahiplerini ve Meryem oğlu Mesîh`i rabler edindiler. Halbuki onlara sadece tek ilâha kulluk etmeleri emrolundu. O`ndan başka tanrı yoktur. O, bunların ortak koştukları şeylerden uzaktır."},{"n":32,"t":"Allah`ın nûrunu ağızlarıyla söndürmek istiyorlar. Allah ise kâfirler hoşlanmasa da nûrunu tamamlamaktan asla vazgeçmez."},{"n":33,"t":"Müşrikler hoşlanmasalar da dinini bütün dinlere üstün kılmak için Peygamber`ini hidayet ve hak din ile gönderen O`dur."},{"n":34,"t":"Ey iman edenler! Hahamlardan ve rahiplerden birçoğu insanların mallarını haksız yollardan yerler ve Allah`ın yolundan alıkoyarlar. Altın ve gümüşü yığıp da onları Allah yolunda harcamayanlar yok mu, işte onlara elem verici bir azabı müjdele!"},{"n":35,"t":"“İşte bu, kendiniz için biriktirdiğiniz servettir. Artık yığdığınız şeylerin azabını tadınız.”"},{"n":36,"t":"Allah`ın gökleri ve yeri yarattığı günden beri geçerli olan evrensel yasasına göre O`nun katında ayların sayısı onikidir. Bunlardan dördü haram aylardır. Bu dosdoğru dindir. Sakın bu aylarda konmuş yasakları çiğneyerek kendinize zulmetmeyiniz. Allah`a ortak koşanlar nasıl size karşı topyekün savaşıyorlarsa, siz de onlarla topyekün savaşınız ve biliniz ki, Allah kötülüklerden sakınanlarla beraberdir."},{"n":37,"t":"Haram ayını başka bir aya ertelemek, küfürde daha ileri gitmektir. İnkâr edenler onunla saptırılır. O haram ayını bir yıl helâl sayarlar, bir yıl haram sayarlar ki, Allah`ın haram kıldığının sayısını denk getirip, Allah`ın haram kıldığını helâl yapsınlar. Yaptıkları işin kötülüğü, kendilerine süslü gösterildi. Allah kâfirler toplumuna yol göstermez."},{"n":38,"t":"Ey insanlar, size ne oldu ki “Allah yolunda topluca savaşa çıkın!” denildiği zaman olduğunuz yere çakılıp kalıyorsunuz? Âhiret yerine dünya hayatına mı razı oldunuz? Ama dünya hayatının malı âhiretin yanında pek azdır."},{"n":39,"t":"Eğer size emredildiği gibi topyekün seferber olmazsanız, Allah sizi hiç gecikmeden pek acı bir azaba düçar eder ve yerinize bir başka topluluk getirir de, (savaşa çıkmamakla) O’na en küçük bir zarar vermiş olmazsınız. Allah, her şeye hakkıyla güç yetirendir."},{"n":40,"t":"Hani iki kişiden biri olduğu halde, inkâr edenler kendisini Mekke`den çıkardıkları sırada ikisi mağarada iken arkadaşına, “Üzülme, Allah bizimle beraberdir!” diyordu. Bunun üzerine Allah, ona güven duygusunu indirmiş ve kendisini sizin görmediğiniz ordularla desteklemişti de inanmayanların sözünü alçaltmıştı. Yüce olan yalnızca Allah`ın sözüdür. Allah daima üstündür, işlerini yerli yerinde yapandır."},{"n":41,"t":"Şarlar zor da kolay da olsa mutlaka seferber olunuz ve Allah yolunda mallarınızla, canlarınızla cihad ediniz. Eğer bilirseniz bu sizin için daha hayırlıdır."},{"n":42,"t":"Eğer kolay elde edilebilecek bir dünya malı ve kısa sürecek bir yolculuk olsaydı, o münafıklar mutlaka sana uyup peşinden gelirlerdi. Fakat meşakkatli yol onlara uzun göründü. Gerçi onlar, “gücümüz yetseydi mutlaka sizinle beraber sefere çıkardık” diyerek kendilerini helâk edercesine, Allah`a yemin edecekler. Oysa Allah onların mutlaka yalan söylediklerini biliyor."},{"n":43,"t":"Allah seni affetsin. Doğru söyleyenler sana iyice belli olup yalancıları bilinceye kadar, onlara niçin izin verdin?"},{"n":44,"t":"Allah`a ve âhiret gününe iman edenler, mal ve canlarıyla savaşmaktan geri kalmak için senden izin istemezler. Allah takvâ sahiplerini bilir."},{"n":45,"t":"Senden, ancak Allah`a ve âhiret gününe inanmayan, gönüllerini şüpheye kaptıran kimseler geri kalmak için izin ister."},{"n":46,"t":"Eğer onlar savaşa çıkmak isteselerdi ona bir hazırlık yaparlardı. Fakat Allah onların davranışlarını çirkin gördü ve onları alıkoydu; onlara, “Âciz olanlarla beraber oturunuz” denildi."},{"n":47,"t":"Şayet onlar sizinle beraber savaşa çıkmış olsalardı, size bozgunculuktan başka bir katkıları olmazdı ve fitne çıkarmak için aranıza koşarlardı. İçinizde onlara kulak verenler vardır. Allah, haksızlık yapanları bilir."},{"n":48,"t":"Aslında onlar, daha önce de karışıklık çıkarmak istemişlerdi; sana karşı birtakım işler çeviriyorlardı. Sonunda gerçek ortaya çıktı ve beğenmedikleri halde Allah`ın buyruğu üstün geldi."},{"n":49,"t":"Onlardan, “Bana izin ver, beni denemeye kalkma!” diyenler vardır. Dikkat ediniz ki, onlar zaten denenmektedirler. Cehennem, inkârcıları kuşatmıştır."},{"n":50,"t":"Sana bir iyilik gelirse, onların ağırına gider. Eğer sana bir kötülük gelse, “Biz önceden önlemimizi aldık” deyip, sevinerek geri dönerler."},{"n":51,"t":"“Allah`ın bize yazdığından başkası başımıza gelmez. O, bizim sıkı dostumuzdur.” İnananlar sadece Allah`a güvensinler."},{"n":52,"t":"“Bize ancak iki güzel şeyden birinin gelmesini mi bekliyorsunuz? Oysa biz, Allah`ın kendi katından veya bizim elimizle sizi azaba uğratmasını bekliyoruz. Öyle ise bekleyiniz, biz de doğrusu sizinle birlikte beklemekteyiz.”"},{"n":53,"t":"“İster gönüllü, ister zorla veriniz; nasıl olsa sizden kabul edilmeyecektir. Çünkü siz yoldan çıkmış bir topluluksunuz.”"},{"n":54,"t":"Verdiklerinin kabul olmasına engel olan hususlar, özellikle Allah`ı ve Peygamberini inkâr etmeleri, namaza üşenerek gelmeleri ve istemeyerek sadaka vermeleridir."},{"n":55,"t":"Artık, onların malları ve çocukları da seni imrendirmesin! Allah bunlarla, onlara dünya hayatında azap etmeyi ve canlarının kâfir olarak çıkmasını ister."},{"n":56,"t":"Mutlaka sizden olduklarına dair Allah`a yemin ederler. Halbuki onlar sizden değildir, fakat onlar korkak bir topluluktur."},{"n":57,"t":"Eğer sığınacak bir yer veya barınacak mağaralar ya da girilecek bir delik/kovuk bulsalardı, koşarak o tarafa yönelip giderlerdi."},{"n":58,"t":"Onlardan sadakaların taksimi hususunda seni ayıplayanlar da vardır. Sadakalardan onlara da verilirse razı olurlar, şayet bunlardan kendilerine verilmezse hemen kızarlar."},{"n":59,"t":"Eğer onlar, Allah ve Peygamberinin kendilerine verdiğine razı olup, “Allah bize yeter, yakında bize Allah da lütfundan verecek, Rasûlü de. Biz, Allah`a düşkün kimseleriz ” deselerdi kendileri için daha hayırlı olurdu."},{"n":60,"t":"Sadakalar/zekâtlar Allah`tan bir farz olarak ancak, yoksullara, düşkünlere, zekât memurlarına, gönülleri ısındırılmış olanlara, kölelere, borçlulara, Allah yolunda çalışıp cihad edenlere, yolda kalana/toplumun bitirilemeyen işlerine aittir. Allah hakkıyla bilen, işini yerli yerince yapandır."},{"n":61,"t":"“O, sizin için bir hayır kulağıdır. Çünkü o, Allah`a inanır, müminlere güvenir ve o, sizden iman edenler için de bir rahmettir.” Allah`ın Peygamberine eziyet edenler için mutlaka elem verici bir azap vardır."},{"n":62,"t":"Sizi hoşnut etmek için Allah`a yemin ederler. Eğer gerçekten iman etmiş olsalardı, Allah`ı ve Peygamberini hoşnut etmek için çalışırlardı."},{"n":63,"t":"Bilmezler mi ki, Allah`a ve Peygamberine kim karşı koymaya kalkışırsa, ona süreli kalacağı cehennem ateşi vardır. İşte bu, büyük rezilliktir."},{"n":64,"t":"“Alay edin bakalım, Allah çekindiğiniz şeyleri ortaya çıkaracaktır.”"},{"n":65,"t":"“Allah ile, ilkeleri ve peygamberiyle mi alay ediyorsunuz?”"},{"n":66,"t":"Özür dilemeyiniz! Şüphesiz, inandıktan sonra inkâr ettiniz. İçinizden bir grubu affetsek bile, bir gruba da suç işlemekte olduklarından dolayı azap ederiz."},{"n":67,"t":"Münafıkların erkekleri de kadınları da birbirinin aynıdır. Kötülüğü emrederler, iyilikten alıkoyarlar, ellerini sıkarak cimrilik ederler. Onlar Allah`ı unuttu, Allah da onları unuttu. Münafıklar fâsıkların ta kendileridir."},{"n":68,"t":"Allah, erkek münafıklara da kadın münafıklara da, kâfirlere de süreli kalacakları cehennem ateşini vaad etti. O, onlara yeter. Allah onlara lânet etmiştir. Onlar için devamlı bir azap vardır."},{"n":69,"t":"Ey münafıklar, siz de tıpkı sizden öncekiler gibisiniz. Onlar kuvvetçe sizden daha zorlu, mal ve çocuklar bakımından daha zengindiler. Onlar kendi nasipleriyle zevk sürdüler. Tıpkı sizden öncekilerin kendi nasipleriyle zevklendikleri gibi, siz de kendi payınıza düşenle zevk sürdünüz. Tıpkı onların zevke dalıp gittiği gibi, siz de zevke dalıp gittiniz. İşte böylelerinin amelleri dünyada da âhirette de boşa çıkmıştır. Asıl ziyana uğrayanlar da onlardır."},{"n":70,"t":"O halde hiç göz önüne almazlar mı, kendilerinden öncekilerinin başlarına gelenleri, Nuh toplumunun başlarına gelenleri, Ad ve Semud toplumlarının başına gelenleri, İbrahim toplumunun, Medyen halkının altüst olmuş o şehirlerin başına gelenleri? Bunların hepsine kendi içlerinden çıkarılan elçiler, hakkı ortaya koyan apaçık delillerle gelmişlerdi. Fakat bu toplumlar onlara karşı çıktılar, dolayısıyla Allah onlara zulmetmedi, fakat onlar kendilerine zulmederek, yaratılış gayelerine aykırı hareket etmişlerdi."},{"n":71,"t":"İnanmış erkekler ve inanmış kadınlar da birbirlerinin samimi dostlarıdır/birbirlerini desteklerler. İyiyi emreder, kötülükten sakındırırlar. Namazı kılar, zekâtı verir, Allah`a ve Peygamberine itaat ederler. İşte bunlara Allah rahmet edecektir. Kuşkusuz Allah, mülkünde galiptir; hikmet sahibidir."},{"n":72,"t":"Allah inanmış erkeklere ve inanmış kadınlara, içlerinden ırmaklar akan, içinde süreli kalacakları cennetler ve Adn cennetlerinde hoş meskenler söz vermiştir. Allah`ın rızası hepsinden büyüktür. İşte büyük kurtuluş budur."},{"n":73,"t":"“Ey Peygamber! Kâfirlerle ve münafıklarla cihad et, onlara sert davran! onların varacakları yer cehennemdir. Ne kötü bir gidiş yeridir o!”"},{"n":74,"t":"Münafıklar söylemediklerine dair Allah adına yemin ediyorlar. Halbuki o küfür sözünü söylediler. Müslüman olduktan sonra inkâr ettiler, başaramadıkları bir şeye yeltendiler. Sırf Allah ve Peygamberi, Allah`ın lütfuyla kendilerini zengin etti diye, şimdi öç almaya kalktılar; Allah ve Peygamberinin iyiliğine karşı böyle nankörlük ettiler. Eğer tövbe ederlerse kendileri için daha iyi olur. Yok eğer dönerlerse Allah onlara dünyada da âhirette de acı bir biçimde azap edecektir. Yeryüzünde onların ne velisi/koruyucusu, ne de yardımcısı vardır."},{"n":75,"t":"Onlardan kimi de, “Eğer Allah, lütfundan bize de verirse elbette sadaka vereceğiz ve iyilerden olacağız” diye Allah`a and içti."},{"n":76,"t":"Ne zaman ki Allah lütfundan onlara verdi, O`nun verdiğinde cimrilik ettiler ve yüz çevirerek sözlerinden döndüler."},{"n":77,"t":"Allah`a verdikleri sözden döndüklerinden ve yalan söylediklerinden dolayı Allah, kendisiyle karşılaşacakları güne kadar onların kalplerine iki yüzlülük sokmuştur."},{"n":78,"t":"Bilmediler mi ki Allah, onların sırlarını ve gizli konuşmalarını bilir ve Allah, gizlileri eksiksiz bilendir!"},{"n":79,"t":"Sadakalar hakkında gönülden davranan müminlere dil uzatanları ve ancak güçleri kadar bulup verenlerle alay eden kimseleri de, Allah maskaraya çevirecektir. Onlar için can yakıcı bir azap da vardır."},{"n":80,"t":"Onlar için ister af dile, ister dileme; onlar için yetmiş defa af dilesen de Allah onları asla affetmeyecektir. Bu, onların Allah ve Peygamberini inkâr etmelerinden dolayıdır. Allah, fâsıklar topluluğunu hidayete erdirmez."},{"n":81,"t":"“Cehennem ateşi daha sıcaktır.” Keşke anlasalardı!"},{"n":82,"t":"Artık kazanmış oldukları günahlara karşılık az gülsünler, çok ağlasınlar."},{"n":83,"t":"“Benimle asla çıkmayacaksınız, yanımda hiçbir düşmanla savaşmayacaksınız. Çünkü siz başlangıçta oturup kalmaya razı oldunuz. Şimdi de geri kalanlarla beraber oturunuz.”"},{"n":84,"t":"Onlar arasından ölenin namazını sakın kılma, mezarı başında da durma! Çünkü onlar Allah`ı ve Peygamberini inkâr ettiler ve yoldan çıkmış olarak öldüler."},{"n":85,"t":"Onların mal ve çocukları seni imrendirmesin. Allah bunlarla, onlara dünyada azap etmek ve canlarının inkârcı olarak çıkmasını ister."},{"n":86,"t":"“Allah`a inanınız ve Peygamberinin yanında savaşınız” diye bir sûre indirildiği zaman, onların güçlüleri savaşa gitmemek için senden izin isterler ve “Bizi bırak, oturanlarla beraber kalalım” derler."},{"n":87,"t":"Geride kalan kadınlarla beraber bulunmaya razı oldular. Artık kalpleri mühürlenmiştir ve bu yüzden anlamazlar."},{"n":88,"t":"Fakat, Peygamber ve beraberindeki müminler, mal ve canlarıyla cihad ettiler. İşte bütün iyilikler onlarındır ve onlar kurtuluşa erenlerin ta kendileridir."},{"n":89,"t":"Allah, onlara içinde süreli kalacakları ve içinden ırmaklar akan cennetler hazırlamıştır. Büyük kurtuluş işte budur."},{"n":90,"t":"Bedevîlerden kendilerine izin verilmesi için özür beyan edenler geldi. Allah`a ve Peygamberine yalan söyleyenler ise, özür bile beyan etmeden geri kalıp oturdular. Onlardan inkâr edenlere, can yakıcı azap gelecektir."},{"n":91,"t":"Zayıflar, hastalar ve kendilerine savaş için donanım sağlama imkanına sahip olmayanlar, Allah`a ve O`nun elçisine karşı bağlı kalıp, hayırlı davrandıkları takdirde, sorumlu tutulmayacaklardır. İyilik yapanları, sorumlu tutmak için bir sebep yoktur. Çünkü Allah çok acıyıp, esirgeyen ve gerçek bağışlayandır."},{"n":92,"t":"Kendilerine binek sağlaman için sana geldiklerinde, “Sizi bindirecek bir şey bulamıyorum” deyince, harcayacak bir şey bulamamanın üzüntüsünden gözleri yaş dökerek geri dönen kimselere de sorumluluk yoktur."},{"n":93,"t":"Sorumluluk sadece, zengin oldukları halde senden izin isteyenleredir. Çünkü onlar geri kalan kadınlarla beraber olmaya razı oldular. Allah da onların kalplerini mühürledi; artık onlar neyin doğru olduğunu bilemezler."},{"n":94,"t":"“Boşuna özür dilemeyiniz! Size asla inanmayız; çünkü Allah, yaptıklarınızı bize bildirmiştir. Amellerinizi Allah da görecektir, Peygamberi de. Sonra, görüleni ve görülmeyeni bilene döndürüleceksiniz de, yapmakta olduklarınızı size haber verecektir.”"},{"n":95,"t":"Yanlarına vardığınız zaman, kendilerinden yüz çeviresiniz diye Allah`a yemin edeceklerdir. Siz de onlarla yüzleşmeyiniz. Çünkü onlar murdardır. Yaptıklarının karşılığı olarak varacakları yer cehennemdir."},{"n":96,"t":"Onlardan razı olasınız diye size yemin edecekler. Fakat siz onlardan razı olsanız bile, Allah, fâsıklar topluluğundan asla razı olmaz."},{"n":97,"t":"Bedevîler, inkâr ve iki yüzlülükte daha ileridirler. Allah`ın, Peygamberine indirdiğinin sınırlarını bilmemek, durumlarına daha uygundur. Allah her şeyi bilendir; işini yerli yerinde yapandır."},{"n":98,"t":"Bedevîlerden, verdiğini angarya sayanlar ve başınıza belâlar dolanmasını gözetenler vardır. Kötü belâlar onların başına dolansın. Allah işitir; bilir."},{"n":99,"t":"Bedevîlerden, Allah`a ve âhiret gününe inanan, verdiğini Allah katında yakınlıklar ve Peygamberinin dualarını elde etmeye sebep sayanlar da vardır. Biliniz ki, o verdikleri, onlar için Allah`a yakın olmanın sebebidir. Allah onları rahmetinin içine alacaktır. Doğrusu Allah, bağışlar; merhamet eder."},{"n":100,"t":"Muhacir ve ensarın ilkleri ile güzel davranmada onlara uyanlardan Allah razı olmuştur. Onlar da O`ndan memnun olmuştur. Allah onlara, içinde süreli kalacakları, içinden ırmaklar akan cennetleri hazırlamıştır. İşte bu, büyük kurtuluştur."},{"n":101,"t":"Çevrenizdeki bedevî Araplar ile Medine halkından birtakım münafıklar vardır ki, münafıklıkta maharet kazanmışlardır. Sen onları bilmezsin, onları biz biliriz. Onlara iki defa azap edeceğiz; sonra da büyük azaba götürülürler."},{"n":102,"t":"Diğerleri ise günahlarını itiraf ettiler; iyi bir ameli, kötü bir amelle karıştırdılar. Umulur ki Allah onların tövbesini kabul eder. Çünkü Allah çok bağışlayandır; çok merhamet sahibidir."},{"n":103,"t":"Onların mallarından sadaka al; bununla onları günahlardan temizlersin, onları arındırıp yüceltirsin. Onlar için dua et! Çünkü senin duan onlar için sükûnettir, onları yatıştırır. Allah her şeyi işitendir; bilendir."},{"n":104,"t":"Allah`ın, kullarının tövbesini kabul edeceğini, sadakaları O`nun alacağını ve Allah`ın, tövbeyi çok kabul eden ve pek esirgeyen olduğunu hâlâ bilmezler mi?"},{"n":105,"t":"“Yapacağınızı yapınız! Amelinizi Allah da, Peygamberi de, müminler de görecektir. Sonra, görüleni ve görülmeyeni bilen Allah`a döndürüleceksiniz de, O size yapmakta olduklarınızı haber verecektir.”"},{"n":106,"t":"Sefere katılmayanlardan diğer bir grup da Allah`ın emrine bırakılmışlardır. O, bunlara ya azap eder veya tövbelerini kabul eder. Allah çok bilendir; hikmet sahibidir."},{"n":107,"t":"Zarar vermek için, nankörlük için, inananları fırkalara bölmek için, daha önceden Allah ve Rasûlü ile savaşmış kişiye gözetleme yeri kurmak için tutup bir mescid yapmışlardır. “İyilik ve güzellikten başka bir şey istemiş değiliz” diye, gerile gerile yemin de ederler. Allah şahittir ki, onlar kesinlikle yalancıdırlar."},{"n":108,"t":"Böyle bir mescidde sakın namaza durma! Daha ilk gününde takvâ üzerine kurulan bir mescid, içinde namaz kılman için çok daha uygundur. O mescidde temizlenmek arzusu taşıyan kimseler vardır. Allah, temizlenenleri sever."},{"n":109,"t":"Peki, binasını Allah`a saygı ve Allah rızası üzerine kuran mı daha güvendedir, yoksa binasını sel artıklarının ucundaki yarın kenarına kurup da onunla birlikte cehenneme yuvarlanan mı? Allah, zâlimler topluluğuna kılavuzluk etmez."},{"n":110,"t":"Kurdukları bina, kalpleri parçalanıncaya kadar yüreklerinde bir kuşku olmaya devam edecektir. Allah her şeyi bilen, işlerini yerli yerinde yapandır."},{"n":111,"t":"Allah müminlerden, mal ve canlarını, kendilerine verilecek cennet karşılığında satın almıştır. Çünkü onlar Allah yolunda savaşırlar, öldürürler, ölürler. Bu, Tevrat`ta, İncil`de ve Kur`ân`da Allah üzerinde hak bir vaaddir. Sözünde Allah`tan daha vefalı kim var? O halde, O`nunla yaptığınız bu alışverişten dolayı müjdeler olsun size! İşte bu, büyük bir kazançtır."},{"n":112,"t":"Allah`a tevbe edenler, ibadet edenler, hamdedenler, yeryüzünde dolaşanlar (saihun), rüku edenler, secde edenler, iyilikle emredenler, kötülükten sakındıranlar, Allah`ın koyduğu sınırları gözetenler! İşte bu mü`minleri müjdele!"},{"n":113,"t":"Cehennem halkı oldukları belli olduktan sonra akraba bile olsalar, Allah`a ortak koşanlar için af dilemek, ne peygamberin ne de müminlerin yapacağı bir iştir."},{"n":114,"t":"İbrâhim`in, babası için af dilemesi, sadece ona verdiği sözden ötürü idi. Fakat onun, Allah düşmanı olduğu kendisine belli olunca ondan uzak durdu. Şüphesiz ki İbrâhim, çok yumuşak huyluydu; pek sabırlı idi."},{"n":115,"t":"Allah, bir toplumu doğru yola ilettikten sonra, sakınmaları gereken şeyleri kendilerine açıklamadıkça onları saptıracak değildir. Allah, her şeyi bilendir."},{"n":116,"t":"Göklerin ve yerin mülkü Allah`ındır; yaşatan ve öldüren O`dur. Sizin Allah`tan başka ne bir dost, ne de yardımcınız vardır."},{"n":117,"t":"Andolsun ki Allah, Peygambere, içlerinden bir grubun gönülleri az kalsın eğrilmek üzere iken dar zamanda ona tâbi olan muhacirlere ve ensara yöneldi. Sonra onların tövbelerini kabul buyurdu. Çünkü O, onları affedendir; onlara merhamet edendir."},{"n":118,"t":"Seferden geride bırakılan üç kişinin de tövbesini kabul etmiştir. Bütün genişliğine rağmen yeryüzü onlara dar gelmiş, vicdanları kendilerini sıkıştırmıştı. Allah`tan başka sığınacak kimse olmadığını anladılar. Sonra onlara yöneldi ki tövbe etsinler. Şüphesiz Allah, tövbeleri kabul eden ve rahmeti sınırsız olandır."},{"n":119,"t":"Ey iman edenler! Allah`a itaat ediniz ve doğrularla beraber olunuz."},{"n":120,"t":"Medine halkına da, onların çevresindeki bedevîlere de Allah`ın Peygamberinden geri kalmak ve kendi canlarını onun canından önde tutmak yakışmaz. Çünkü Allah yolunda uğrayacakları bir susuzluk, bir yorgunluk, bir açlık, kâfirleri şaşırtan bir adım atmaları ve düşmana karşı herhangi bir başarı kazanmaları, kendileri için iyi bir amel olarak mutlaka yazılacaktır. Çünkü Allah iyi davrananların amellerini asla boşa çıkarmaz."},{"n":121,"t":"Küçük büyük bir masraf yapmaları, bir vâdiyi geçmeleri, mutlaka onların lehine yazılır ki, Allah onları, yaptıklarının en güzeliyle ödüllendirsin."},{"n":122,"t":"İnananların hepsinin birden savaşa çıkmaları doğru değildir. Onların her kesiminden bir grubun, dinde derin bilgiler edinmek ve sefere çıkan topluluk geri döndüğünde korunmaları ümidiyle onları uyarmak için, arkada kalmaları gerekmez mi?"},{"n":123,"t":"Ey İman edenler! Kâfirlerden yakınınızda olanlara karşı savaşınız ve sizde yenilmez bir kuvvet görsünler. Biliniz ki Allah sakınanlarla beraberdir."},{"n":124,"t":"“Bu sizin hanginizin imanını arttırdı?” Müminlere gelince, işte bu sûre onların imanlarını arttırır ve onlar sevinirler."},{"n":125,"t":"Kalplerinde hastalık olanlara gelince, onların da murdarlıklarına murdarlık katmış ve onlar kâfir olarak ölüp gitmişlerdir."},{"n":126,"t":"Onlar, her yıl bir veya iki defa imtihan edildiklerini görmüyorlar mı? Sonra da ne tövbe ediyorlar ne de ders alıyorlar."},{"n":127,"t":"Bir sûre indirildiği zaman birbirlerine bakar, “Sizi birisi görüyor mu?” diye sorarlar, sonra da giderler. Anlamayan bir kavim oldukları için Allah onların kalplerini imandan çevirmiştir."},{"n":128,"t":"Andolsun size kendinizden öyle bir peygamber gelmiştir ki, sizin sıkıntıya uğramanız ona çok ağır gelir. O, size çok düşkündür; müminlere karşı çok şefkatlidir; merhametlidir."},{"n":129,"t":"“Bana Allah yeter; O`ndan başka ilâh yoktur. Ben sadece O`na güvenip dayanırım. O, yüce arşın sahibidir.”"}],[{"n":1,"t":"Elif, lâm, râ. İşte şunlar, hikmet dolu kitabın âyetleridir."},{"n":2,"t":"İçlerinden birine, “İnsanları uyar, iman edenlere de kendileri için Allah katında yüksek bir doğruluk derecesi bulunduğunu müjdele!” diye vahiy göndermemiz insanlara şaşırtıcı mı geldi? İnkâr edenler, “Bu adam açık bir büyücüdür” dediler."},{"n":3,"t":"Şüphesiz ki Rabbiniz, gökleri ve yeri altı devirde/evrede yaratan, sonra da arşın üzerinde hükmedip işleri yöneten Allah`tır. O`nun izni olmadan kimse kendiliğinden şefaat edemez. Rabbiniz Allah işte budur. O`na kulluk ediniz. Hâlâ düşünmüyor musunuz?"},{"n":4,"t":"Hepinizin dönüşü O`nadır. Allah`ın verdiği söz gerçektir. Doğrusu O, önce yaratmaya başlar, sonra inanıp yararlı iş yapanları adaletle ödüllendirmek için yaratmayı tekrarlar. İnkârcılara, inkâr etmelerinden dolayı kızgın bir içecek ve acıklı bir azap vardır."},{"n":5,"t":"Güneşi ışık kaynağı, ayı aydınlık yapan, yılların sayısını ve hesaplamayı bilmeniz için aya konak yerleri düzenleyendir. Allah bunları bir amaç uğruna yaratmıştır. O, bilen bir topluma âyetlerini açıklamaktadır."},{"n":6,"t":"Gece ile gündüzün değişmesinde, Allah`ın göklerde ve yerde yarattığı şeylerde, sakınan bir toplum için nice deliller vardır."},{"n":7,"t":"Huzurumuza çıkacaklarını beklemeyenler, dünya hayatına razı olup onunla doyuma ulaşanlar ve âyetlerimizden habersiz olanlar vardır."},{"n":8,"t":"İşte onların, kazanmış oldukları günahlar yüzünden varacakları yer ateştir."},{"n":9,"t":"İnanıp yararlı işler yapanlara gelince, imanları sebebiyle Rableri, onları içinden ırmaklar akan nimet dolu cennetlerine iletir."},{"n":10,"t":"“Bütün övgüler âlemlerin rabbi Allah`adır.”"},{"n":11,"t":"Eğer Allah insanlara, hayrı çarçabuk istedikleri gibi, şerri de acele verseydi, elbette onların ecelleri bitirilmiş olurdu. Fakat bize kavuşmayı beklemeyenleri biz, azgınlıkları içinde bocalar bir halde bırakırız."},{"n":12,"t":"İnsana bir zarar dokunduğunda yan yatarak, oturarak veya ayakta durarak bize dua eder; fakat biz ondan sıkıntısını kaldırınca, sanki kendisine dokunan bir zarardan ötürü bize dua etmemiş gibi geçip gider. İşte, böylece haddi aşanlara yapmakta oldukları şeyler süslü gösterildi."},{"n":13,"t":"Andolsun, sizden önce, peygamberleri kendilerine açık belgeler getirmişken inanmayarak haksızlık ettikleri zaman, nice nesilleri yok ettik. İşte, suçlu topluluğu böyle cezalandırırız."},{"n":14,"t":"Sonra da, sizin nasıl davranacağınızı görmek için onların ardından sizi yeryüzünde iktidara getirdik."},{"n":15,"t":"“Onu kendiliğimden değiştiremem. Ben ancak bana vahyolunana uyarım. Doğrusu, Rabbime karşı gelirsem, büyük günün azabından korkarım.”"},{"n":16,"t":"“Eğer Allah dileseydi, onu size okuyamazdım, Allah da onu size bildirmezdi. Ben bundan önce bir ömür boyu içinizde durmuştum. Hâlâ aklınızı kullanmıyor musunuz?”"},{"n":17,"t":"Allah`a karşı yalan uydurandan veya O`nun âyetlerini yalanlayandan daha zâlim kim olabilir? Bilesiniz ki suçlular asla iflah olmazlar."},{"n":18,"t":"“Siz Allah`a göklerde ve yerde bilmeyeceği bir şeyi mi haber veriyorsunuz? Hâşâ! O, onların ortak koştuklarından uzak ve yücedir.”"},{"n":19,"t":"İnsanlar bir topluluk halindeydi, sonradan ayrılığa düştüler. Eğer daha önce Rabbinden verilmiş bir söz olmasaydı, ayrılığa düştükleri şeyler hakkında aralarında hüküm hemen verilirdi."},{"n":20,"t":"“Gayb ancak Allah`a aittir. Bekleyiniz, ben de sizinle beraber bekleyenlerdenim.”"},{"n":21,"t":"“Allah`ın tuzağı daha süratlidir. Şüphesiz, elçilerimiz/yazıcı melekler kurduğunuz tuzakları yazıyorlar.”"},{"n":22,"t":"Sizi karada ve denizde yürüten Allah`tır. Bulunduğunuz gemi, içindekileri hoş bir rüzgârla götürürken yolcular neşelenirler. Bir kasırga çıkıp, onları her yönden dalgaların sardığı ve çepeçevre kuşatıldıklarını anladıkları anda ise dini sırf Allah`a has kılarak, “Bizi bu tehlikeden kurtarırsan andolsun şükredenlerden olacağız” diye Allah`a yalvarırlar."},{"n":23,"t":"Allah onları kurtarınca, hemen yeryüzünde haksız yere taşkınlıklara başlarlar. “Ey insanlar! Dünya hayatında yaptığınız taşkınlık aleyhinizedir. Bununla sadece dünya menfaatini elde edersiniz. Sonunda dönüşünüz bizedir, o zaman yapmış olduklarınızı size bildiririz.”"},{"n":24,"t":"Dünya hayatı, gökten indirdiğimiz suyu gören bitkinin haline benzer. İnsanların ve hayvanların yiyeceği topraktan çıkan bitkiler gürleşir, birbiriyle sarmaş dolaş olur. Yeryüzü zînetini takınır, rengârenk süslenir. Sahiplerinin de, bunlar üzerinde, kudret sahibi olduklarını düşündükleri bir sırada, gece veya gündüz planımız icra edilince, sanki dün yerlerinde yokmuş gibi, köklerinden koparılıp biçilmiş çer-çöp haline gelir. Gelişmeye devam eden, tefekkür-düşünme ağına sahip, faydalı sonuçlar elde edebilen toplumlar için biz, Allah’ın birliğini ve kudretini gösteren âyetleri, sosyal hayat için gerekli ikazları işte böyle ayrıntılı açıklıyoruz."},{"n":25,"t":"Allah esenlik yurduna çağırıyor ve O, dileyeni doğru yola iletiyor."},{"n":26,"t":"Güzel davrananlara daha güzel karşılık, bir de daha fazlası vardır. Onların yüzlerine ne bir kara leke bulaşır ne de bir zillet. İşte onlar cennet ehlidirler. Onlar, orada süreli kalacaklardır."},{"n":27,"t":"Kötülük kazananlara ise kötülüklerine denk ceza vardır. Fakat yüzlerini bir zillet de kaplar. Onları Allah`ın azabından kurtaracak kimse yoktur. Onların yüzleri sanki karanlık geceden bir parçaya bürümüştür. İşte onlar da cehennem ehlidir. Onlar orada süreli kalacaklardır."},{"n":28,"t":"O gün onları bir araya topladıktan sonra, şirk koşanlara, “Haydi siz ve ortak koştuklarınız, yerlerinize!” deriz. Artık aralarını açmışızdır. Koştukları ortaklar, “Siz sadece bize tapmıyordunuz ki” derler."},{"n":29,"t":"“Bu yüzden bizimle sizin aranızda şahit olarak Allah yeter. Şüphesiz ki biz sizin bize tapmanızdan tamamen habersizdik.”"},{"n":30,"t":"İşte orada herkes, geçmişte yaptıklarını karşısında bulur. Artık onlar gerçek sahipleri olan Allah`a döndürülürler ve uydurdukları şeyler, kendilerinden kaybolup gider."},{"n":31,"t":"“Hâlâ sakınmıyor musunuz?”"},{"n":32,"t":"İşte O, gerçek Rabbiniz olan Allah`tır. Artık haktan sonra sapıklıktan ne kalır ki? O halde nasıl döndürülüyorsunuz?"},{"n":33,"t":"İşte böylece Rabbinin, yoldan çıkanlar hakkındaki “Onlar inanmazlar” sözü gerçekleşmiş oldu."},{"n":34,"t":"“Allah yoktan yaratıp onu yeniden hayata döndürür. O halde nasıl saptırılıyorsunuz?”"},{"n":35,"t":"“Allah hakka iletir. Öyle ise hakka götüren mi uyulmaya lâyıktır, yoksa hidayet verilmedikçe kendi kendine doğru yolu bulamayan mı? Size ne oluyor? Nasıl böyle yanlış hükmediyorsunuz?”"},{"n":36,"t":"Onların çoğu, zandan başka bir şeye uymaz. Şüphesiz zan, haktan hiçbir şeyin yerini tutmaz. Allah, onların yapmakta olduklarını çok iyi bilendir."},{"n":37,"t":"Bu Kur`ân, Allah`tan başka varlıklar tarafından uydurulabilecek bir kitap değildir. Kur`ân, kendinden öncekini tasdik etmekte ve onu açıklamaktadır. Onda şüphe yoktur; o, alemlerin Rabbindendir."},{"n":38,"t":"“Eğer doğru iseniz, Allah`tan başka, gücünüzün yettiklerini çağırınız da, onun benzeri bir sûre getiriniz.”"},{"n":39,"t":"Bilâkis, onlar ilmini kavrayamadıkları ve yorumu kendilerine asla gelmemiş olan Kur`ân`ı yalanladılar. Onlardan öncekiler de böyle yalanlamışlardı. Şimdi bak, zâlimlerin sonu nasıl oldu?"},{"n":40,"t":"İçlerinden kimi var ki ona inanır, kimi de ona inanmaz. Rabbin bozguncuları en iyi bilendir."},{"n":41,"t":"“Benim işim bana, sizin işiniz de size aittir. Siz benim yaptığımdan uzaksınız, ben de sizin yaptığınızdan uzağım.”"},{"n":42,"t":"İçlerinde seni dinleyenler de vardır. Peki, hele bir de akıllarını kullanmıyorlarsa, sağırlarsa sen mi işittireceksin?!"},{"n":43,"t":"Onlardan sana bakanlar da vardır. Peki, körleri sen mi doğru yola ileteceksin? Hele gönül gözleriyle de görmüyorlarsa!"},{"n":44,"t":"Şüphesiz ki Allah, insanlara hiçbir şekilde zulmetmez; fakat onlar kendilerine zulmederler."},{"n":45,"t":"Onları huzuruna toplayacağı gün, gündüzün bir saatinden başka, dünyada durmamış gibidirler; birbirleriyle tanışırlar. Allah`a kavuşmayı yalanlayıp da doğru yolu tutmayanlar, hüsrana uğramışlardır."},{"n":46,"t":"Onlara vaad ettiğimiz azabın bir kısmını sana göstersek de, göstermeden seni vefat ettirsek de, dönüşleri bizedir. Sonunda Allah, işlemiş olduklarına tanıklık edecektir."},{"n":47,"t":"Her ümmetin bir peygamberi vardır. Peygamberleri geldiğinde, aralarında adaletle hüküm verilir ve onlara asla zulmedilmez."},{"n":48,"t":"“Doğru iseniz bu vaad ne zaman?”"},{"n":49,"t":"“Ben kendime bile, Allah`ın istediği dışında ne bir zarar ne de bir fayda verme gücüne sahibim.” Her ümmetin bir eceli vardır. Ecelleri geldiği zaman, artık ne bir saat geri kalırlar ne de ileri giderler."},{"n":50,"t":"“Ne dersiniz? Allah`ın azabı size geceleyin veya gündüz vaktinde gelirse ne yaparsınız? Suçlular ondan hangisini istemekte acele ediyorlar?”"},{"n":51,"t":"“Başınıza belâ geldikten sonra mı O`na iman edeceksiniz, şimdi mi? Halbuki azabın gelmesini istemekte acele ediyordunuz.”"},{"n":52,"t":"Sonra zulmedenlere, “Süreli azabı tadınız” denilecek. Kazanmakta olduğunuzdan başkasının karşılığını mı bulacaksınız?"},{"n":53,"t":"“Evet, Rabbime yemin ederim ki, o şüphesiz gerçektir ve siz âciz bırakacak değilsiniz.”"},{"n":54,"t":"Zulmeden herkes, yeryüzündeki bütün servete sahip olsa azaptan kurtulmak için elbette onu feda eder ve azabı gördükleri zaman, için için yanarlar. Aralarında adaletle hükmedilir ve onlara zulmedilmez."},{"n":55,"t":"Bilesiniz ki, göklerde ve yerde olan her şey Allah`ındır. Yine bilesiniz ki, Allah`ın vaadi haktır, fakat onların çoğu bilmez."},{"n":56,"t":"O, hem diriltir, hem de öldürür ve yalnız O`na döndürüleceksiniz."},{"n":57,"t":"Ey insanlar! Rabbinizden size bir öğüt, sinelerdekine bir şifa, müminler için bir hidayet ve rahmet gelmiştir."},{"n":58,"t":"Söyle onlara, Allah`ın bu lütfu ve rahmetiyle sevinsinler. Bu, onların toplayıp biriktirdiği her şeyden daha üstündür."},{"n":59,"t":"“Allah mı size izin verdi, yoksa Allah`a iftira mı ediyorsunuz?”"},{"n":60,"t":"Yalanı Allah`a yakıştıranlar, kıyamet günü hakkında ne düşünüyorlar? Allah, insanlara karşı elbette lütuf sahibidir, fakat onların çoğu şükretmiyor."},{"n":61,"t":"Ne zaman sen bir iş yapsan, ne zaman Kur`ân`dan bir şey okusan ve siz ne zaman bir iş yaparsanız, o işe daldığınız zaman biz mutlaka üstünüzde şahidizdir. Ne yerde ne gökte zerre miktarı bir şey Rabbinden gizli kalabilir! Bundan daha küçüğü de daha büyüğü de apaçık bir kitapta kayıtlıdır."},{"n":62,"t":"Bilesiniz ki, Allah`ın dostlarına korku yoktur; onlar üzülmeyeceklerdir."},{"n":63,"t":"Onlar iman edip takvâya erişmişlerdir."},{"n":64,"t":"Dünya hayatında da âhirette de onlara müjde vardır. Allah`ın sözlerinde asla değişme yoktur. İşte bu, büyük kurtuluşun tâ kendisidir."},{"n":65,"t":"Onların sözleri seni üzmesin; şeref bütünüyle Allah`a aittir. Allah işitendir; bilendir."},{"n":66,"t":"Biliniz ki, göklerde ve yerde kim varsa onların hepsi yalnız Allah`ındır. O halde Allah`tan başka ortaklara tapanlar neyin ardına düşüyorlar? Doğrusu onlar zandan başka bir şeyin ardına düşmüyorlar ve onlar sadece yalan söylüyorlar."},{"n":67,"t":"Sizin için geceyi dinlenmeniz, gündüzü de aydınlatsın diye yaratan O`dur. Şüphesiz bunda, dinleyen bir toplum için dersler vardır."},{"n":68,"t":"Müşrikler, “Allah çocuk edindi” dediler. Hâşâ! O bundan uzaktır. Onun çocuğa ihtiyacı yoktur. Göklerde ve yerde ne varsa O`nundur. Bu hususta yanınızda herhangi bir delil yoktur. Allah hakkında bilmediğiniz bir şeyi mi söylüyorsunuz?"},{"n":69,"t":"“Allah hakkında yalan uyduranlar asla kurtuluşa ulaşamazlar.”"},{"n":70,"t":"“Dünyada biraz nimetlenme vardır; ardından dönüşleri bizedir. Sonra da, inkâr ettiklerinden dolayı şiddetli azabı onlara tattıracağız.”"},{"n":71,"t":"“Ey kavmim! Eğer benim aranızda durmam ve Allah`ın âyetlerini hatırlatmam size ağır geliyorsa, ben sadece Allah`a güvenip dayanırım. Siz de ortaklarınızla beraber toplanıp, yapacağınızı kararlaştırınız. Sonra işiniz başınıza dert olmasın. Ondan sonra aldığınız kararı bana uygulayınız ve bana mühlet de vermeyiniz.”"},{"n":72,"t":"“Eğer yüz çeviriyorsanız, zaten ben sizden bir ücret istemedim. Benim ücretim Allah`tan başkasına ait değildir ve bana Müslümanlardan olmam emrolundu.”"},{"n":73,"t":"Yine de onu yalanladılar; biz de hem onu hem de onunla beraber gemide bulunanları kurtardık ve onları iktidar sahibi yaptık. Âyetlerimizi yalanlayanları da boğduk. Bak ki, uyarılanların sonu nasıl oldu!"},{"n":74,"t":"Sonra Nûh`un ardından birçok peygamberi kendi toplumlarına gönderdik. Onlara mucizeler getirdiler. Fakat onlar daha önce yalanladıkları şeye inanacak değillerdi. İşte, haddi aşanların kalplerini biz böyle mühürleriz."},{"n":75,"t":"Sonra onların ardından da Mûsâ ile Hârun`u, Firavun ve toplumuna mucizelerimizle gönderdik, fakat onlar kibirlendiler ve günahkâr bir toplum oldular."},{"n":76,"t":"Katımızdan onlara hak gelince, “Bu elbette apaçık bir sihirdir” dediler."},{"n":77,"t":"Mûsâ, “Size hak geldiğinde onun için hep böyle mi dersiniz? Bu bir sihir midir? Halbuki sihirbazlar iflah olmazlar” dedi."},{"n":78,"t":"“Babalarımızı üzerinde bulduğumuzdan bizi döndüresin ve yeryüzünde ululuk sizin ikinizin olsun diye mi bize geldin? Biz size inanacak değiliz.”"},{"n":79,"t":"Firavun, “Bana bütün bilgili büyücüleri getirin!” dedi."},{"n":80,"t":"Büyücüler gelince Mûsâ onlara, “Atacağınızı atın!” dedi."},{"n":81,"t":"Onlar iplerini ve değneklerini atınca Mûsâ, “Sizin getirdiğiniz şey büyüdür, Allah onu mutlaka boşa çıkaracaktır. Çünkü Allah bozguncuların işini düzeltmez!” dedi."},{"n":82,"t":"“Suçlular istemese de Allah, sözleriyle gerçeği ortaya çıkaracaktır!”"},{"n":83,"t":"Firavun ve etrafındakilerin, kendilerine işkence etmesinden korkuya düştükleri için, halktan bir grup gençten başka kimse Mûsâ`ya iman etmedi. Çünkü Firavun, yeryüzünde ululuk taslayan bir diktatör ve haddi aşanlardan biri idi."},{"n":84,"t":"“Ey kavmim! Eğer Allah`a inandıysanız ve O`na teslim olduysanız sadece O`na güvenip dayanın.”"},{"n":85,"t":"“Sadece Allah`a dayandık. Ey Rabbimiz! Bizi o zâlimler topluluğu için deneme konusu kılma!”"},{"n":86,"t":"“Bizi rahmetinle o kâfirler topluluğundan kurtar!”"},{"n":87,"t":"Biz de Mûsâ ve kardeşine, “Kavminiz için Mısır`da evler hazırlayınız ve evlerinizi namaz kılınacak yerler yapınız, namazlarınızı da dosdoğru kılınız. Ey Mûsâ! Müminleri müjdele!” diye vahyettik."},{"n":88,"t":"“Ey Rabbimiz! Gerçekten sen, Firavun ve kavmine dünya hayatında ziynet ve nice mallar verdin. Ey Rabbimiz! Onlara bu nimetleri, insanları senin yolundan saptırsınlar ve elem verici cezayı görünceye kadar iman etmesinler diye mi verdin? Ey Rabbimiz! Onların mallarını yok et, kalplerine sıkıntı ver.”"},{"n":89,"t":"Allah, “İkinizin de duası kabul edilmiştir. O halde siz doğruluğa devam edin ve sakın o bilmezlerin yoluna gitmeyin!” dedi."},{"n":90,"t":"İsrâiloğulları`nı denizden geçirdik; Firavun ve askerleri de zulmetmek ve saldırmak için onların arkalarına düştü. Nihayet boğulma tehlikesiyle burun buruna gelince Firavun, “Gerçekten İsrâiloğulları`nın inandığından başka tanrı olmadığına inandım, ben de Müslümanlardanım” dedi."},{"n":91,"t":"“Şimdi mi? Oysa daha önce isyan etmiş, bozgunculardan olmuştun.”"},{"n":92,"t":"“Bugün senin bedenini kurtaracağız ki senden sonra gelenlere ders olasın. Ama insanların çoğu âyetlerimizden gâfildir.”"},{"n":93,"t":"Andolsun biz, İsrâiloğulları`nı iyi bir yere yerleştirdik ve onlara güzel rızıklar verdik. Kendilerine bilgi gelinceye kadar ayrılığa düşmediler de, bilgi geldikten sonra ayrılığa düştüler. Şüphesiz Rabbin, kıyamet günü, anlaşmazlığa düştükleri şey hakkında aralarında hüküm verecektir."},{"n":94,"t":"Sana indirdiğimizden şüphede isen, senden önce kitap okuyanlara sor! Andolsun, sana Rabbinden gerçek geldi. Sakın şüphelenenlerden olma!"},{"n":95,"t":"Asla, Allah`ın âyetlerini de yalanlayanlardan olma, yoksa kaybedenlerden olursun."},{"n":96,"t":"Haklarında Rabbinin azap kelimesi sabit olanlar inanmazlar."},{"n":97,"t":"Onlara bütün âyetler gelmiş olsa bile, elem verici azabı görünceye kadar inanmazlar."},{"n":98,"t":"Yûnus`un toplumundan başka, herhangi bir ülke halkının da inanıp, inançlarının kendilerine fayda vermesi gerekmez miydi? Yûnus`un toplumu inanınca dünya hayatındaki azabı onlardan kaldırdık ve bir süreye kadar onları refah içinde yaşattık."},{"n":99,"t":"Eğer Rabbin dileseydi, yeryüzündekilerin hepsi elbette iman ederlerdi. O halde sen, inanmaları için insanları zorlayacak mısın?"},{"n":100,"t":"Allah`ın izni olmadan hiç kimse inanamaz. O, akıllarını kullanmayanları murdar kılar."},{"n":101,"t":"“Göklerde ve yerde neler var, bakın da ders alın!” Fakat inanmayan bir topluma deliller ve uyarılar fayda sağlamaz."},{"n":102,"t":"“O halde bekleyiniz, ben de sizinle beraber bekleyenlerdenim.”"},{"n":103,"t":"Sonra biz, peygamberlerimizi ve aynı şekilde iman edenleri kurtarırız. İnananları kurtarmamız, üzerimize bir haktır."},{"n":104,"t":"“Ey İnsanlar! Benim dinimden şüphede iseniz, biliniz ki ben Allah`ı bırakıp da sizin taptıklarınıza tapmam; fakat ancak, sizi öldürecek olan Allah`a kulluk ederim. Bana, inananlardan olmam emrolundu.”"},{"n":105,"t":"“Hanîf olarak yüzünü dine çevir; sakın müşriklerden olma” diye emrolundum."},{"n":106,"t":"Allah`ı bırakıp da sana fayda ve zarar vermeyecek şeylere tapma! Eğer bunu yaparsan, o takdirde sen elbette zâlimlerden olursun."},{"n":107,"t":"Eğer Allah sana bir zarar dokundurursa, onu yine O`ndan başka giderecek yoktur. Eğer Allah sana bir hayır dilerse, O`nun lütfunu geri çevirecek de yoktur. O, lütfunu kullarından dilediğine ulaştırır. O, affedicidir; merhamet sahibidir."},{"n":108,"t":"“Ey İnsanlar! Size Rabbinizden hak olan Kur`ân gelmiştir. Artık kim doğru yola gelirse, ancak kendisi için gelecektir. Kim de saparsa, o da ancak kendi aleyhine sapacaktır. Ben sizin üzerinize vekil değilim.”"},{"n":109,"t":"“Sen, sana vahyolunana uy ve Allah hükmedinceye kadar sabret! O hâkimlerin en üstünüdür.”"}],[{"n":1,"t":"Elif, lâm, râ. Bu, hikmet sahibi ve her şeyden haberdar olan Allah tarafından âyetleri önce sağlam kılınmış, sonra da detaylandırılıp açıklanmış bir kitaptır."},{"n":2,"t":"“Allah`tan başkasına kesinlikle kulluk etmeyiniz. Şüphesiz ben size Allah`tan gelen bir uyarıcıyım; bir müjdeciyim.”"},{"n":3,"t":"“Rabbinizden af dileyesiniz ve O`na tövbe edesiniz ki, sizi belirtilmiş bir süreye kadar güzelce yaşatsın ve her fazilet sahibine faziletinin karşılığını versin. Eğer yüz çevirirseniz, ben sizin için büyük bir günün azabından korkarım.”"},{"n":4,"t":"“Dönüşünüz Allah`adır. O her şeyi yapacak güçtedir.”"},{"n":5,"t":"“İyi biliniz ki onlar, O`ndan gizlenmek için sinelerini bükerler. Yine iyi biliniz ki, onlar örtülerine büründükleri zaman dahi, Allah onların içlerinde gizlediklerini ve açığa vurduklarını hep bilir. Çünkü O, sinelerin özünü bilendir.”"},{"n":6,"t":"Yeryüzünde hareket eden hiçbir canlı yoktur ki rızkı Allah`a bağlı olmasın. Ayrıca O, her canlının bulunduğu yeri ve sonunda bırakılacağı mekânı bilir. Bütün bunlar apaçık bir kitapta yer almış bulunmaktadır."},{"n":7,"t":"Gökleri ve yeri altı evrede yaratan Allah`tır. Onun kudret tahtı suyu kullanmasında idi. Hanginizin davranışça daha iyi olduğunu tesbit etmek için sizi imtihan etmektedir. Eğer sen, “Ölümden sonra diriltileceksiniz” desen, kâfirler hemen, “Bu, apaçık sihirden başka bir şey değildir” diye karşılık verirler."},{"n":8,"t":"Andolsun, eğer biz onlardan azabı sayılı bir süreye kadar ertelersek, elbette, “Onun gelmesini engelleyen nedir?” derler. Bilesiniz ki, kendilerine azap geldiği gün, bir daha onlardan uzaklaştırılacak değildir. Alay etmekte oldukları şey, onları çepeçevre kuşatmış olacaktır."},{"n":9,"t":"Eğer insana tarafımızdan bir rahmet tattırır da sonra bunu ondan çekip geri alırsak, tamamen ümitsiz ve nankör olur."},{"n":10,"t":"Eğer kendisine dokunan bir zarardan sonra ona bir nimet tattırırsak, “Elbette kötülükler benden gitti” der. Çünkü o şımarıktır; kibirlidir."},{"n":11,"t":"Ancak sabredip güzel iş yapanlar böyle değildir. İşte onlar için, bir bağışlama ve büyük bir ödül vardır."},{"n":12,"t":"Belki de sen, müşriklerin “Ona gökten bir hazine indirilseydi veya onunla beraber bir melek gelseydi ya!” demelerinden dolayı, sana vahyolunan âyetlerin bir kısmını tebliğ etmeyi terk edeceksin ve bu yüzden ruhun daralacaktır. İyi bil ki, sen sadece bir uyarıcısın. Allah ise her şeye vekildir.”"},{"n":13,"t":"“Eğer doğru iseniz, Allah`tan başka çağırabildiklerinizi yardıma çağırın da onun gibi uydurulmuş on sûre getirin.”"},{"n":14,"t":"Eğer size cevap veremiyorlarsa, biliniz ki, o ancak Allah`ın ilmi ile indirilmiştir ve O`ndan başka tanrı yoktur. Artık siz Müslüman oluyor musunuz?"},{"n":15,"t":"Kim, yalnızca dünya hayatını ve süsünü isterse, işlerinin karşılığını onlara orada tam olarak veririz ve onlar orada hiçbir zarara uğratılmazlar."},{"n":16,"t":"İşte onlar, âhirette kendileri için ateşten başka hiçbir şeyleri olmayan kimselerdir. Dünyada yaptıkları boşa gitmiştir, yapmakta oldukları şeyler de bâtıldır."},{"n":17,"t":"Rabbinin katından bir belgesi ve onun ardından O`ndan gelen bir tanığı bulunanlar ve ondan önce de önlerinde Mûsâ`nın kitabı önder ve rahmet olarak duranlar; işte onlar Kur`ân`a inanırlar. Hangi topluluk onu inkâr ederse, ona söz verilen yer ateştir. Senin de bundan şüphen olmasın. Doğrusu, o, Rabbinden bir gerçektir. Fakat insanların çoğu inanmaz."},{"n":18,"t":"Allah`a karşı yalan uydurandan daha zâlim kimdir? Bunlar Rabblerine sunulurlar ve tanıklar da, “Rabblerine karşı yalan söyleyenler bunlardır” derler. Biliniz ki, Allah`ın laneti zâlimler üzerinedir."},{"n":19,"t":"Onlar Allah`ın yolundan alıkoyanlar ve onun eğriliğini isteyenlerdir. İşte bunlar, âhireti inkâr edenlerdir."},{"n":20,"t":"İşte bunlar, Allah`ı yeryüzünde âciz bırakamazlar. Onların Allah`tan başka yakın dostları da yoktur. Onlara azap kat kat olacaktır. Çünkü, onlar gerçekleri duymaya dayanamaz ve göremezlerdi."},{"n":21,"t":"İşte bunlar, kendilerine yazık edenlerdir. Uydurup durdukları şeyler de yanlarından kaybolmuştur."},{"n":22,"t":"Şüphesiz, âhirette de en çok kaybedenler bunlar olacaktır."},{"n":23,"t":"İnanıp da güzel işler yapan ve Rabblerine gönülden boyun eğenlere gelince, işte onlar cennet ehlidir. Onlar orada süreli kalırlar."},{"n":24,"t":"Bu iki grubun durumu, kör ve sağır ile gören ve işiten kimsenin durumu gibidir. Bunlar hiç eşit olur mu? Hâlâ ders almıyor musunuz?"},{"n":25,"t":"Andolsun, Biz Nûh`u kavmine peygamber gönderdik. Onlara, “Ben sizin için apaçık bir uyarıcıyım” dedi."},{"n":26,"t":"“Allah`tan başkasına tapmayın! Ben, size gelecek elem verici bir günün azabından korkuyorum.”"},{"n":27,"t":"“Biz seni sadece bizim gibi bir insan olarak görüyoruz. Bizden, basit görüşle hareket eden alt tabakamızdan başkasının sana uyduğunu ve sizin bize karşı bir üstünlüğünüzü de görmüyoruz. Bilakis, sizin yalancılar olduğunuzu düşünüyoruz.”"},{"n":28,"t":"“Ey kavmim! Bakın, bende Rabbim tarafından verilen açık bir delil varsa, O kendi tarafından bana bir rahmet vermiş ise ve siz de ona karşı körleşmiş iseniz, ben ne yapabilirim? Siz onu istemediğiniz halde biz sizi ona zorlayacak mıyız?”"},{"n":29,"t":"“Ey kavmim! Allah`ın emirlerini bildirmeye karşılık sizden herhangi bir mal istemiyorum. Benim ödülüm ancak Allah`a aittir. Ben iman edenleri kovacak değilim; çünkü onlar Rabblerine kavuşacaklardır. Fakat ben sizi, bilgisizce davranan bir kalabalık olarak görüyorum.”"},{"n":30,"t":"“Ey kavmim! Ben onları kovarsam, beni Allah`ın azabından kim korur? Düşünmüyor musunuz?”"},{"n":31,"t":"“Ben size, ‘Allah`ın hazineleri benim yanımdadır` demiyorum, gaybı da bilmem. ‘Ben bir meleğim` de demiyorum. Sizin hor gördüğünüz kimseler için, ‘Allah onlara asla bir hayır vermeyecektir` diyemem. Onların kalplerinde olanı, Allah daha iyi bilir. Onları kovarsam ben gerçekten zâlimlerden olurum."},{"n":32,"t":"“Ey Nûh! Bizimle gerçekten tartıştın ve bize karşı mücâdelede çok ileri gittin. Eğer doğrulardan isen, kendisiyle bizi tehdit ettiğini bize getir!”"},{"n":33,"t":"“Onu size ancak dilerse Allah getirir. Siz, Allah`ı aciz bırakacak değilsiniz.”"},{"n":34,"t":"“Eğer Allah sizi azgınlık içinde bırakmak istiyorsa, ben size öğüt vermek istesem de öğüdüm size fayda vermez. Çünkü O sizin Rabbinizdir. O`na döndürüleceksiniz.”"},{"n":35,"t":"“Onu uydurduysam günahı bana. Fakat ben sizin işlediğiniz günahlardan uzağım.”"},{"n":36,"t":"Nûh`a, “Senin toplumundan inanmış olanların dışında başka kimse inanmayacaktır. Onların yaptıklarına üzülme!”"},{"n":37,"t":"`Gözlerimizin önünde, gözetimimiz altında, vahyimiz uyarınca gemileri inşa et. Zulmetmiş, haksızlık etmiş, hakkı tanımamış olanlar konusunda bana başvurma. Onlar kesinlikle boğulacaklar.`"},{"n":38,"t":"Nûh gemiyi yaparken, kavminin ileri gelenleri yanından her geçtiklerinde onunla alay ediyorlardı. O da, “Bizimle alay ediyorsunuz ama, biz de sizin alay ettiğiniz gibi sizinle alay edeceğiz.” dedi."},{"n":39,"t":"“Rezil edecek azabın kime geleceğini ve sürekli azabın kime ineceğini göreceksiniz!” dedi."},{"n":40,"t":"Sonunda buyruğumuz gelip tandırda sular kaynamaya başlayınca, “Her cinsten birer çifti ve aleyhine hüküm verilmiş olanın dışında kalan ehlini ve inananları gemiye bindir” dedik. Ancak, pek az kimse onunla beraber inanmıştı."},{"n":41,"t":"Nûh, “Gemiye binin, onun yürümesi ve durması Allah`ın adıyladır; doğrusu, Rabbim bağışlayandır; merhamet edendir” dedi."},{"n":42,"t":"Gemi dağlar gibi dalgalar içinde onları götürürken Nûh, bir kenarda ayrı kalmış oğluna, “Ey yavrucuğum! Bizimle beraber sen de gemiye bin, inkârcılarla beraber olma” diye seslendi."},{"n":43,"t":"Oğlu, “Dağa sığınırım, beni sudan kurtarır” deyince, Nûh, “Bugün acıdıkları dışında, Allah`ın buyruğundan kurtarabilecek bir şey yoktur” dedi. Aralarına dalga girdi ve oğlu da boğulanlara karıştı."},{"n":44,"t":"“Ey yeryüzü! Suyunu içeri çek ve ey gök, sen de suyunu tut” denildi. Su çekildi, iş de böylece bitirildi. Gemi ise Cûdî`ye oturdu. “Haksızlık yapan toplum yok olsun” denildi."},{"n":45,"t":"“Ey Rabbim! Şüphesiz oğlum da ailemdendir. Senin vaadin ise elbette haktır. Sen hükmedenlerin en iyi hükmedenisin.”"},{"n":46,"t":"Allah, “Ey Nûh! O senin ailenden değildir. Çünkü o, doğru olmayan bir iş yapmıştır. Öyleyse, hakkında bilgin olmayan şeyi benden isteme. Doğrusu, câhillerden olman konusunda seni uyarıyorum” dedi."},{"n":47,"t":"Nûh, “Rabbim! Doğrusu, hakkında bilgim olmayan şeyi senden istemekten sana sığınırım. Eğer beni affetmezsen ve bana merhamet etmezsen kaybedenlerden olurum.” dedi."},{"n":48,"t":"“Ey Nûh! Sana ve seninle beraber olan topluluklara, bizden bir esenlik ve bereket olmak üzere gemiden in!” denildi. Ama birçok topluluğun geçimini de sağlayacağız. Sonra onlara, bizden acıklı bir azap değecektir."},{"n":49,"t":"“Ey Muhammed! İşte bunlar sana vahyettiğimiz gayb haberlerindendir. Bundan önce onları ne sen biliyordun ne de kavmin. O halde sabret! Çünkü iyi sonuç, sakınanlarındır.”"},{"n":50,"t":"“Ey kavmim! Allah`a kulluk ediniz. Sizin O`ndan başka tanrınız yoktur. Yoksa sırf yalan uyduranlardan olursunuz.”"},{"n":51,"t":"“Ey kavmim! Buna karşılık sizden bir ücret istemiyorum. Benim ücretim, ancak beni yaratana aittir. Düşünmüyor musunuz?”"},{"n":52,"t":"“Ey kavmim! Rabbinizden af dileyiniz. Sonra, O`na tövbe ediniz ki, size gökten bol bol yağmur göndersin, gücünüze güç katsın. Günah işleyerek Allah`tan yüz çevirmeyiniz.”"},{"n":53,"t":"“Ey Hûd! Sen bize açık bir mucize getirmedin, biz de senin sözünle tanrılarımızı bırakacak değiliz ve biz sana iman edecek de değiliz.”"},{"n":54,"t":"“Ben, Allah`ı şâhit tutuyorum; siz de şahit olunuz ki ben sizin ortak koştuklarınızdan uzağım.”"},{"n":55,"t":"“O`ndan başka taptıklarınızın hepsinden uzağım. Haydi, hepiniz bana tuzak kurun; sonra da bana mühlet vermeyin.”"},{"n":56,"t":"“Ben, benim de Rabbim, sizin de Rabbiniz olan Allah`a dayandım. Çünkü yeryüzünde hiçbir varlık yoktur ki, Allah onun perçeminden tutmuş olmasın. Şüphesiz, Rabbim dosdoğru yoldadır.”"},{"n":57,"t":"“Eğer yüz çevirirseniz, şüphesiz ‘benimle size gönderileni` size bildirdim. Rabbim sizden başka bir kavmi yerinize getirir de o kavme hiçbir zarar veremezsiniz. Çünkü benim Rabbim her şeyi koruyup gözetendir.”"},{"n":58,"t":"Emrimiz gelince, Hûd`u ve onunla beraber iman edenleri tarafımızdan bir rahmetle kurtardık, onları ağır bir azaptan kurtuluşa erdirdik."},{"n":59,"t":"O`nun peygamberlerine âsî oldular ve inatçı bir zorbanın emrine uydular."},{"n":60,"t":"Onlar hem bu dünyada hem de kıyamet gününde lanete tâbî tutulacaklar. Biliniz ki, ‘Âd halkı Rabblerini inkâr ettiler. Yine biliniz ki Hûd`un kavmi ‘Âd, Allah`ın rahmetinden uzak olsun."},{"n":61,"t":"“Ey kavmim! Allah`a kulluk ediniz. Sizin O`ndan başka tanrınız yoktur. Sizi topraktan yaratan ve sizi orada yaşatan O`dur. O halde ondan af dileyiniz; sonra da O`na tövbe ediniz. Çünkü Rabbim, kullarına yakındır; duaları kabul edendir.”"},{"n":62,"t":"“Ey Sâlih! Sen bundan önce içimizde ümit beslenen biri idin. Şimdi babalarımızın taptıklarına tapmaktan bizi alıkoyuyor musun? Doğrusu biz, bizi kendisine çağırdığın şeyden ciddi bir şüphe içindeyiz.”"},{"n":63,"t":"Sâlih dedi ki, “Ey kavmim! Eğer ben Rabbimden gelen apaçık bir delil üzerinde isem ve O, bana kendinden bir rahmet vermişse, buna ne dersiniz? Bu durumda O`na âsî olursam, beni Allah`tan kim korur? O zaman siz bana zarar vermekten başka bir şey yapmış olmazsınız.”"},{"n":64,"t":"“Ey kavmim! İşte size mucize olarak Allah`ın devesi. Onu bırakın, Allah`ın mülkünde yesin. Ona kötülük etmeyiniz; sonra sizi yakın bir azap yakalar.”"},{"n":65,"t":"“Yurdunuzda üç gün daha yaşayın.” Bu söz, yalanlanamayan bir tehdit idi."},{"n":66,"t":"Emrimiz gelince, Sâlih`i ve onunla beraber iman edenleri, bizden bir rahmet olarak azaptan ve o günün zilletinden kurtardık. Şüphesiz Rabbin kuvvetlidir; galip gelendir."},{"n":67,"t":"Zulmedenleri de o korkunç ses yakaladı ve yurtlarında diz üstü çöke kaldılar."},{"n":68,"t":"Sanki orada hiç şenlik kurmamış gibi oldular. İyi biliniz ki Semûd kavmi Rabblerini inkâr ettiler ve iyi bilin ki Semûd kavmi defolup gittiler."},{"n":69,"t":"Andolsun ki peygamberlerimiz İbrâhim`e müjde getirdiler ve “Selâm” dediler. O da, “Selâm” dedi ve hemen kızartılmış bir buzağı getirdi."},{"n":70,"t":"Yemeğe ellerini uzatmadıklarını görünce, onları yadırgadı ve onlardan dolayı içine bir korku girdi. “Korkma! Biz melekleriz; Lût kavmine gönderildik” dediler."},{"n":71,"t":"O anda hanımı ayakta idi ve bu sözleri duyunca güldü. Ona da İshâk`ı, İshâk`ın ardından da Ya‘kûb`u müjdeledik."},{"n":72,"t":"Hanımı, “Olacak şey değil! Ben bir kocakarı, bu kocam da bir ihtiyar iken çocuk mu doğuracağım? Bu, gerçekten şaşılacak bir şey!” dedi."},{"n":73,"t":"“Allah`ın emrine şaşıyor musun? Ey ev halkı! Allah`ın rahmeti ve bereketleri sizin üzerinizdedir. Şüphesiz ki O, övülmeye lâyıktır; iyiliği boldur.”"},{"n":74,"t":"İbrâhim`den korku gidip kendisine müjde gelince, Lût kavmi hakkında bizimle mücâdeleye başladı."},{"n":75,"t":"İbrâhim cidden yumuşak huylu, duygusal, kendini Allah`a vermiş biri idi."},{"n":76,"t":"“Ey İbrâhim! Bundan vazgeç. Çünkü Rabbinin emri gelmiştir. Onlara, geri çevrilemeyecek bir azap kesinlikle gelecektir!”"},{"n":77,"t":"Elçilerimiz/melekler, Lût`a gelince, Lût onların yüzünden üzüldü ve onlardan dolayı içi daraldı da, “Bu, çetin bir gündür” dedi."},{"n":78,"t":"Lût`un kavmi, koşarak onun yanına geldi. Daha önce de o kötü işleri yapmaktaydılar. Lût, “Ey kavmim! İşte şunlar kızlarımdır; sizin için onlar daha temizdir. Allah`tan korkun ve misafirlerimin önünde beni rezil etmeyin! İçinizde aklı başında bir adam yok mu?” dedi."},{"n":79,"t":"“Senin kızlarında bir hakkımız olmadığını biliyorsun. Sen bizim ne istediğimizi elbette bilirsin.”"},{"n":80,"t":"Lût, “Keşke benim size karşı koyacak bir gücüm olsaydı veya güçlü bir kaleye sığınabilseydim!” dedi."},{"n":81,"t":"“Ey Lût! Biz Rabbinin elçileriyiz. Onlar sana asla dokunamazlar. Sen gecenin bir kısmında ailenle yola çıkıp yürü. Hanımından başka, sizden hiçbiri geride kalmasın. Çünkü onlara gelecek olan azap, şüphesiz ona da isabet edecektir. Onlara vaad olunan helâk zamanı, sabah vaktidir. Sabah yakın değil mi?”"},{"n":82,"t":"Emrimiz gelince, oranın altını üstüne getirdik ve üzerlerine sağanak halinde balçıktan pişirilmiş taşlar yağdırdık."},{"n":83,"t":"O taşlar Rabbin katında işaretlenerek yağdırılmıştır. Onlar zâlimlerden uzak değildir."},{"n":84,"t":"“Ey kavmim! Allah`a kulluk ediniz! Sizin için ondan başka tanrı yoktur. Ölçüyü ve tartıyı eksik yapmayınız. Zira ben sizi hayır içinde görüyorum ve gerçekten sizin için kuşatıcı bir günün azabından korkuyorum.”"},{"n":85,"t":"“Ey kavmim! Ölçüyü ve tartıyı adâletle yapınız; insanlara eşyalarını eksik vermeyiniz; yeryüzünde bozguncular olarak dolaşmayınız.”"},{"n":86,"t":"“Eğer mümin iseniz, Allah`ın bıraktığı sizin için daha hayırlıdır. Ben üzerinize bekçi değilim.”"},{"n":87,"t":"“Ey Şu‘ayb! Babalarımızın taptıklarını, yahut mallarımız hususunda dilediğimizi yapmaktan vazgeçmemizi sana imanın/dinin mi emrediyor? Oysa sen yumuşak huylu ve çok akıllısın.”"},{"n":88,"t":"“Ey kavmim! Eğer benim, Rabbim tarafından verilmiş apaçık bir delilim varsa ve O bana tarafından güzel bir rızık vermişse buna ne dersiniz? Size yasak ettiğim şeylerin aksini yaparak size aykırı davranmak istemiyorum. Ben sadece gücümün yettiği kadar ıslah etmek istiyorum. Fakat başarmam Allah`ın yardımı iledir. Yalnız O`na güvenip dayandım ve bütün benliğimle O`na yöneldim.”"},{"n":89,"t":"“Ey kavmim! Sakın bana karşı düşmanlığınız Nûh kavminin veya Hûd kavminin yahut Sâlih kavminin başlarına gelenler gibi, size de bir musibet getirmesin! Lût kavmi de sizden uzak değildir.”"},{"n":90,"t":"“Rabbinizden bağışlanma dileyiniz; sonra O`na tövbe ediniz. Muhakkak ki Rabbim çok merhametlidir; çok sever.”"},{"n":91,"t":"“Ey Şu‘ayb! Söylediklerinin çoğunu anlamıyoruz ve içimizde seni cidden zayıf görüyoruz! Eğer kabilen olmasa, seni mutlaka taşlayarak öldürürüz. Sen bizden üstün değilsin.”"},{"n":92,"t":"“Ey kavmim! Size göre benim kabilem Allah`tan daha mı güçlü ve değerli ki, Allah`ı arkanıza atıp unuttunuz. Şüphesiz ki Rabbim, yapmakta olduklarınızı çepeçevre kuşatıcıdır.”"},{"n":93,"t":"“Ey kavmim! Bulunduğunuz yerde elinizden geleni yapın! Ben de yapacağım! Kendisini rezil edecek azabın geleceği şahsın ve yalancının kim olduğunu yakında öğreneceksiniz! Bekleyiniz! Ben de sizinle beraber beklemekteyim.”"},{"n":94,"t":"Emrimiz gelince, Şu‘ayb`ı ve onunla beraber iman edenleri tarafımızdan bir rahmetle kurtardık; zulmedenleri ise korkunç bir gürültü yakaladı da yurtlarında diz üstü çöke kaldılar."},{"n":95,"t":"Sanki orada hiç barınmamışlardı. Biliniz ki, Semûd kavmi Allah`ın rahmetinden uzak olduğu gibi Medyen kavmi de uzak oldu."},{"n":"96-97","t":"Andolsun, Mûsâ`yı da âyetlerimizle ve açık bir kanıtla Firavun`a ve ileri gelenlerine gönderdik. Ama onlar Firavun`un emrine uydular. Oysa Firavun`un emri, akla uygun değildi."},{"n":98,"t":"Kıyamet günü kavminin önüne geçecek ve onları suya götürür gibi ateşe götürecektir. Ne kötü varış yeridir o götürüldükleri yer!"},{"n":99,"t":"Hem burada hem kıyamet gününde peşlerine lanet takılmıştır. Ne kötü destektir o arkalarına takılmış olan!"},{"n":100,"t":"İşte bu, memleketlerin haberlerindendir. Biz onu sana anlatıyoruz; bugüne kadar izleri kalan da vardır, biçilmiş ekin gibi yok olan da."},{"n":101,"t":"Onlara biz zulmetmedik. Fakat onlar kendilerine zulmettiler. Rabbinin emri geldiğinde, Allah`ı bırakıp taptıkları tanrıları onlara hiçbir şey sağlamadı, ziyanlarını arttırmaktan başka bir şeye de yaramadı."},{"n":102,"t":"Rabbin, haksızlık eden memleketleri yakaladığında, O`nun yakalayışı işte böyledir. Şüphesiz onun yakalaması pek elem vericidir; pek çetindir."},{"n":103,"t":"İşte bunda, âhiret azabından korkanlar için elbette bir ders vardır. O gün bütün insanların bir araya toplandığı bir gündür ve o gün herkesin hazır bulunduğu bir gündür."},{"n":104,"t":"Biz kıyamet gününü sadece sayılı bir müddete kadar bekletiriz."},{"n":105,"t":"Kıyamet geldiği gün Allah`ın izni olmadan hiç kimse konuşamaz. Onlardan kimi bedbaht, kimi de mutludur."},{"n":106,"t":"Bedbaht olanlar ateştedir, orada olanların bir nefes alıp vermeleri vardır ki!"},{"n":107,"t":"Rabbinin dilediği hariç, onlar gökler ve yer durdukça o ateşte süreli kalacaklardır. Çünkü Rabbin, istediğini hakkı ile yapandır."},{"n":108,"t":"Mutlu olanlara gelince, onlar da cennettedirler. Rabbinin dilediği hariç, gökler ve yer durdukça onlar da orada süreli kalacaklardır. Bu, bitmez-tükenmez bir lütuftur."},{"n":109,"t":"Artık, onların taptıkları putlardan dolayı herhangi bir şüpheniz olmasın. Onlar da, daha önce babalarının taptığı gibi putlara tapıyorlar. Biz onların nasiplerini kesinlikle eksiksiz ödeyeceğiz."},{"n":110,"t":"Biz Mûsâ`ya Kitâb`ı vermiştik de onda ihtilafa düşüldü. Rabbinin önceden verilmiş bir sözü olmasaydı, aralarında hüküm verilirdi. Elbette onlar Kur`ân hakkında derin bir şüphe içindedirler."},{"n":111,"t":"Rabbin onların her birinin yaptığının karşılığını tam olarak verecektir. Çünkü O, onların yapmakta olduklarından haberdardır."},{"n":112,"t":"O halde seninle beraber tövbe edenlerle birlikte emrolunduğun gibi dosdoğru ol! Aşırı gitmeyiniz. Çünkü O, yaptıklarınızı çok iyi görendir."},{"n":113,"t":"Zulmedenlere meyletmeyiniz; sonra ateş size de dokunur. Sizin Allah`tan başka dostlarınız yoktur. Sonra yardım da göremezsiniz."},{"n":114,"t":"Gündüzün iki tarafında ve geceye yakın saatlerde namaz kıl. İyilikler kötülükleri giderir. İşte bu, Allah`ı ananlara bir öğüttür."},{"n":115,"t":"Sabırlı ol! çünkü Allah, güzel iş yapanların ödülünü zâyi etmez."},{"n":116,"t":"Fakat ne yazık ki, sizden önceki kuşaklar arasından yeryüzünde bozgunculuktan alıkoyacak akıl ve iz‘ân sahibi erdemli insanlar çıkmadı. Fakat onlardan az bir kısmını kurtardık. Zulmedenler ise, kendilerine verilen refahın peşine düştüler. Zaten günahkâr idiler."},{"n":117,"t":"Halkı ıslah edici olduğu halde Rabbin haksız yere memleketleri helâk etmez."},{"n":118,"t":"Rabbin dileseydi bütün insanları tek bir millet yapardı. Fakat onlar ihtilaf etmeye devam ediyorlar."},{"n":119,"t":"Ancak Rabbinin merhamet ettikleri müstesnadır. Zaten Rabbin onları bunun için yarattı. Yani, Rabbinin, “Andolsun ki, cehennemi hem insanlar hem de cinlerle dolduracağım” sözü yerini buldu."},{"n":120,"t":"Peygamberlerin haberlerinden senin kalbini teskin edeceğimiz her haberi anlatıyoruz. Bunda sana gerçeğin bilgisi, müminlere de bir öğüt ve bir uyarı gelmiştir."},{"n":121,"t":"“Elinizden geleni bulunduğunuz yerde yapınız! Biz de yapmaktayız.”"},{"n":122,"t":"“Bekleyiniz! Biz de beklemekteyiz.”"},{"n":123,"t":"Göklerin ve yerin gaybı yalnız Allah`a aittir. Her iş O`na döndürülür. Öyle ise O`na kulluk et ve O`na dayan. Rabbin, yaptıklarınızdan gâfil değildir."}],[{"n":1,"t":"Elif, lâm, râ. Bunlar, apaçık kitabın âyetleridir."},{"n":2,"t":"Aklınızı kullanasınız diye biz onu Arapça bir Kur`ân olarak indirdik."},{"n":3,"t":"Biz, bu Kur`ân`ı sana vahyetmekle, geçmiş milletlerin haberlerini en güzel bir şekilde anlatıyoruz. Gerçek şu ki, sen bundan önce bu haberleri bilmeyenlerdendin."},{"n":4,"t":"“Babacığım! Ben rüyamda on bir yıldızla güneşi ve ayı gördüm; onları bana secde ederken gördüm.”"},{"n":5,"t":"Babası, “Yavrucuğum!” dedi, “Rüyanı sakın kardeşlerine anlatma; sonra sana bir tuzak kurarlar! Çünkü şeytan insana apaçık bir düşmandır.”"},{"n":6,"t":"“İşte böylece Rabbin seni seçecek, sana olayların ve sözlerin yorumunu öğretecek. Tıpkı bundan önce ataların İbrâhim ve İshâk üzerine o nimeti tamamladığı gibi, hem senin hem de Ya‘kûb soyunun üzerinde nimetini tamamlayacaktır. Çünkü senin Rabbin her şeyi bilendir; hikmet sahibidir.”"},{"n":7,"t":"Andolsun ki, Yûsuf ve kardeşlerinde, almak isteyenler için dersler vardır."},{"n":8,"t":"“Yûsuf ile kardeşi, babamıza bizden daha sevgilidir. Halbuki biz kalabalık bir cemaatiz. Şüphesiz ki babamız apaçık bir yanılgı içindedir.”"},{"n":9,"t":"“Yûsuf`u öldürün veya onu bir yere atın ki babanızın sevgi ile yönelişi yalnız size kalsın! Ondan sonra da tövbe ederek iyi kimseler olursunuz.”"},{"n":10,"t":"Onlardan biri, “Yûsuf`u öldürmeyiniz; eğer mutlaka yapacaksanız onu kuyunun dibine atın da, geçen kervanlardan biri onu alsın” dedi."},{"n":11,"t":"“Ey babamız! Sana ne oluyor da Yûsuf hakkında bize güvenmiyorsun? Oysa biz, onun iyiliğini istemekteyiz.”"},{"n":12,"t":"“Yarın onu bizimle beraber gönder de, bol bol gezsin, oynasın. Biz onu mutlaka koruruz.”"},{"n":13,"t":"“Onu götürmeniz beni mutlaka üzer. Siz ondan habersizken, onu bir kurdun yemesinden korkarım.”"},{"n":14,"t":"“Hakikaten biz böylesine kalabalık olduğumuz halde, eğer onu kurt yerse, o zaman biz gerçekten aciz kimseler sayılırız.”"},{"n":15,"t":"Onu götürüp de kuyunun dibine atmaya ittifakla karar verdikleri zaman, biz Yûsuf`a, “Andolsun ki sen onların bu işlerini, onlar farkına varmadan kendilerine haber vereceksin” diye vahyettik."},{"n":16,"t":"Akşamleyin, ağlayarak babalarına geldiler."},{"n":17,"t":"“Ey babamız!” dediler, “Biz yarış yapmak üzere uzaklaşmış, Yûsuf`u da eşyamızın yanına bırakmıştık. Onu kurt yemiş! Fakat biz doğru söyleyenler olsak da sen bize inanmazsın.”"},{"n":18,"t":"“Bilakis; nefisleriniz size bir işi güzel gösterdi. Artık bana düşen, hakkıyla sabretmektir. Anlattığınız karşısında, yardım edecek olan ancak Allah`tır.”"},{"n":19,"t":"“Müjde” dedi, “İşte bir erkek çocuk!” Onu ticaret için sakladılar. Halbuki Allah onların ne yaptıklarını biliyordu."},{"n":20,"t":"Nihayet onu düşük bir fiyata sattılar. Onlar ona karşı isteksiz idiler."},{"n":21,"t":"Onu satın alan Mısırlı, hanımına, “Ona iyi bak, belki bize yararı dokunur ya da onu evlât ediniriz” dedi. Böylece biz Yûsuf`a o yerde güzel bir imkân verdik ki ona olayların yorumunu öğretelim. Allah, emrini yerine getirendir, fakat insanların çoğu bilmezler."},{"n":22,"t":"Yûsuf ergenlik çağına erişince, ona hüküm ve ilim verdik. İşte, güzel davrananları biz böyle ödüllendiririz."},{"n":23,"t":"Evinde bulunduğu kadın, onunla ilişkiye girmek istedi. Kapıları iyice kapattı ve “haydi gel” dedi. O da, “Allah`a sığınırım! Zira kocanız benim velinimetimdir, bana güzel davrandı. Gerçek şu ki, zâlimler iflah olmaz” dedi."},{"n":24,"t":"Andolsun ki, kadın ona meyletmişti. Eğer Rabbinin gerçeğe dikkat çeken delilini görmeseydi, o da ona meyletmiş olacaktı. Böylece biz, kötülüğü ve fuhşu ondan uzak tutuyorduk. Çünkü o, ihlaslı kullarımızdandı."},{"n":25,"t":"“Senin ailene kötülük etmek isteyenin cezası, zindana atılmaktan veya elem verici bir işkenceden başka ne olabilir!”"},{"n":26,"t":"“Eğer gömleği önden yırtılmışsa, kadın doğru söylemiştir; bu adam ise yalancılardandır.”"},{"n":27,"t":"Ama eğer gömleği arkadan yırtılmışsa kadın yalan söylemiştir o ise doğru söyleyenlerdendir.`"},{"n":28,"t":"“Şüphesiz bu sizin tuzaklarınızdandır. Sizin tuzaklarınız gerçekten çok yamandır.”"},{"n":29,"t":"“Ey Yûsuf! Sen bunları söylemekten vazgeç! Ey kadın! Sen de günahının affını dile! Çünkü sen günahkarlardan oldun.”"},{"n":30,"t":"“Azizin karısı genç uşağının nefsinden gönlünü eğlendirmek istemiş. Aşktan yüreğinin zarı delinmiş. Biz onu açık bir sapıklık içinde görüyoruz.”"},{"n":31,"t":"Kadın, onların dedikodu şeklindeki oyunlarını işitince, onlara haber gönderdi. Kendilerine, yaslanarak yiyebilecekleri bir sofra hazırladı ve her birine bir bıçak verdi. Yûsuf'a da, “Karşılarına çık” dedi. Nihayet Yûsuf'u görünce onu öylesine yücelttiler ki, bu yüzden bıçakla kendi ellerini kestiler ve şöyle dediler: “Aman Allah'ım! Bu bir insan değil; asil bir melek bu!”"},{"n":32,"t":"“İşte budur o, hakkında beni kınadığınız. Vallâhi, ben onunla gönlümü eğlendirmek istedim de o mâsum bir tavırla bundan çekindi. Ama, eğer kendisine emrettiğimi yapmazsa, yemin ediyorum zindana tıkılacak ve horlananlardan olacaktır.”"},{"n":33,"t":"Yûsuf, “Ey Rabbim! Bana zindan, bunların benden istediklerinden daha iyidir. Eğer onların hilelerini benden çevirmezsen, onlara meyleder ve câhillerden olurum!” dedi."},{"n":34,"t":"Rabbi onun duasını kabul etti ve onların hilesini ondan uzaklaştırdı. Çünkü O, çok iyi işitendir; çok iyi bilendir."},{"n":35,"t":"Sonunda, kesin delilleri görmelerine rağmen halkın dedikodusunu kesmek için yine de onu bir zamana kadar zindana atmayı uygun buldular."},{"n":36,"t":"“Ben rüyamda şarap sıktığımı gördüm.” Diğeri de, “Ben de başımın üstünde kuşların yemekte olduğu bir ekmek taşıdığımı gördüm. Bunun yorumunu bize haber ver! Çünkü biz seni güzel davrananlardan görüyoruz” dedi."},{"n":37,"t":"“Size yedirilecek yemek gelmeden önce onun yorumunu mutlaka size haber vereceğim. Bu, Rabbimin bana öğrettiklerindendir. Şüphesiz ben, Allah`a inanmayan bir toplumun dininden uzaklaştım. Onlar âhireti inkâr edenlerin ta kendileridir.”"},{"n":38,"t":"“Atalarım İbrâhim, İshâk ve Ya‘kûb`un dinine uydum. Allah`a herhangi bir şeyi ortak koşmak bize yaraşmaz. Bu, Allah`ın bize ve insanlara olan lütfundandır. Fakat insanların çoğu şükretmezler.”"},{"n":39,"t":"“Ey zindan arkadaşlarım! Çeşitli tanrılar mı daha iyi, yoksa gücüne karşı durulmaz olan bir tek Allah mı?”"},{"n":40,"t":"“Allah`ı bırakıp da taptıklarınız, sizin ve atalarınızın taktığı birtakım isimlerden başka bir şey değildir. Allah onlar hakkında herhangi bir delil indirmemiştir. Hüküm sadece Allah`a aittir. O size kendisinden başkasına ibadet etmemenizi emretmiştir. İşte dosdoğru din budur. Fakat insanların çoğu bilmezler.”"},{"n":41,"t":"“Ey zindan arkadaşlarım! Rüyalarınıza gelince, biriniz daha önce olduğu gibi efendisine şarap içirecek; diğeri ise asılacak ve kuşlar onun başından yiyecekler. Yorumunu sorduğunuz iş kesinleşmiştir.”"},{"n":42,"t":"“Beni efendinin yanında an.” Fakat şeytan ona, efendisine Yûsuf`u anmayı unutturdu. Dolayısıyla birkaç sene daha zindanda kaldı."},{"n":43,"t":"“Ben rüyamda yedi zayıf ineğin yedi semiz ineği yediğini gördüm. Ayrıca, yedi yeşil başak ve bir o kadar da kurumuş başak görüyorum. Efendiler! Eğer rüya yorumlamasını biliyorsanız, bu rüyamı bana yorumlayınız.”"},{"n":44,"t":"“Bunlar karmakarışık düşlerdir. Biz böyle düşlerin yorumunu bilenlerden değiliz.”"},{"n":45,"t":"“Ben size rüyanızın yorumunu öğrenip haber veririm, beni hemen zindana gönderin.”"},{"n":46,"t":"Böylece hapishanede Yûsuf`un yanına gitti ve ona, “Ey Yûsuf, ey özü sözü doğru arkadaş!” dedi. “Rüyada görülen yedi zayıf ineğin yedi semiz ineği yemesi ve yedi yeşil başakla bir o kadar kurumuş başak ne anlama gelir, bunu bana yorumla! Ümit ederim ki bu soruyu soran insanların yanına dönerim de belki onlar da doğruyu öğrenirler.”"},{"n":47,"t":"“Yedi sene âdetiniz üzere ekin ekersiniz. Sonra da yiyeceklerinizden az bir miktar hariç, biçtiklerinizi başağında bırakınız.”"},{"n":48,"t":"“Sonra bunun ardından, saklayacağınızdan az bir miktar tohumluk hariç, o yıllar için biriktirdiklerinizi yiyip bitirecek yedi kıtlık yılı gelecektir.”"},{"n":49,"t":"“Sonra bunun ardından da bir yıl gelecek ki, o yılda insanlara Allah tarafından yardım edilir ve bol bol meyve sıkarlar.”"},{"n":50,"t":"“Efendine dön de ona ‘Ellerini kesen o kadınların zoru neydi?` diye sor! Şüphesiz benim Rabbim onların hilesini çok iyi bilir.”"},{"n":51,"t":"“Şimdi gerçek ortaya çıktı. Ben, onun nefsinden murat almak istemiştim. Şüphesiz ki o, doğru söyleyenlerdendir.”"},{"n":52,"t":"“Bu, onun yokluğunda ona ihanet etmediğimi ve Allah`ın ihânet edenlerin hilesini başarıya ulaştırmayacağını herkesin bilmesi içindir.”"},{"n":53,"t":"“Nefsimi temize çıkarmıyorum. Çünkü nefis, Rabbimin merhamet ettiği durumlar hariç, olanca gücüyle kötülüğü emreder. Ama Rabbim, affedicidir; merhamet sahibidir.”"},{"n":54,"t":"“Onu bana getiriniz; onu kendime özel danışman tayin edeyim.” Onunla konuşunca, “Bugün sen, katımda yüksek makam sahibisin ve güvenilir birisin” dedi."},{"n":55,"t":"Yûsuf, “Beni ülkenin hazineleri üstüne bakan tayin et! Çünkü ben onları çok iyi korurum; bu işi bilirim” dedi."},{"n":56,"t":"Böylece Yûsuf`a, orada dilediği gibi hareket etmek üzere ülke içinde yetki verdik. Biz dilediğimiz kimseye rahmetimizi ulaştırırız. Güzel davrananların ödülünü zayi etmeyiz."},{"n":57,"t":"İman edip de yanlıştan sakınanlar için âhiret ödülü daha değerlidir."},{"n":58,"t":"Yûsuf`un kardeşleri gelip onun huzuruna girdiler. Yûsuf onları tanıdı, ama onlar onu tanımıyorlardı."},{"n":59,"t":"“Sizin baba-bir kardeşinizi de bana getiriniz. Görmüyor musunuz, ben ölçeği tam dolduruyorum ve ben misafirperverlerin en iyisiyim.”"},{"n":60,"t":"Eğer onu bana getirmezseniz, artık benim yanımda size verecek bir ölçek erzak yoktur, bana hiç yaklaşmayınız."},{"n":61,"t":"“Onu babasından istemeye çalışacağız, şüphesiz bunu yapacağız” dediler."},{"n":62,"t":"“Sermayelerini yüklerinin içine koyunuz. Olur ki, ailelerine döndüklerinde bunun farkına varırlar da belki geri gelirler.”"},{"n":63,"t":"Babalarına döndüklerinde, “Ey babamız! Erzak bize yasaklandı. Kardeşimizi bizimle beraber gönder de, erzak ölçüp alabilelim. Biz onu mutlaka koruyacağız” dediler."},{"n":64,"t":"“Daha önce kardeşi Yûsuf hakkında size ne kadar güvendiysem, bunun hakkında da size aynı şekilde güveneyim, öyle mi? Allah en güçlü koruyucudur. O merhamet edenlerin en merhametlisidir.”"},{"n":65,"t":"“Ey babamız! Daha ne istiyoruz. İşte sermayemiz de bize geri verilmiş. Yine onunla ailemize erzak getiririz, kardeşimizi koruruz ve bir deve yükü de fazla alırız. Çünkü bu getirdiğimiz, az bir miktardır.”"},{"n":66,"t":"“Şu söylediğimize Allah vekildir.”"},{"n":67,"t":"“Ey oğullarım! Bir tek kapıdan girmeyiniz, ayrı ayrı kapılardan giriniz. Gerçi ben Allah`ın takdir ettiği bir şeyi sizden savamam. Hüküm yalnız Allah`ındır. Ben yalnız O`na dayandım. Tevekkül sahipleri de ona güvenip dayansın!”"},{"n":68,"t":"Babalarının emrettiği yerlerden şehre girdiklerinde, bu onlardan Allah`ın herhangi bir takdirini uzak tutamazdı; sadece Ya‘kûb`un içindeki bir isteği gerçekleştirmişti. Ya‘kûb, bizim ona öğretmemizden dolayı bilgi sahibi idi. Ama halkın çoğu bunu bilmezdi."},{"n":69,"t":"Yûsuf`un yanına girdiklerinde, öz kardeşini yanına aldı ve ona, “Bilesin ben senin kardeşinim. Onların yaptıklarına üzülme!” dedi."},{"n":70,"t":"Yûsuf, onların yüklerini hazırlatırken değerli bir kâseyi, öz kardeşinin yüküne koydu. Sonra da arkadan biri, “Ey kafile, siz mutlaka hırsızlarsınız!” diye bağırdı."},{"n":71,"t":"Yûsuf`un kardeşleri, sesin geldiği taraftakilere dönerek, “Ne kaybettiniz?” diye sordular."},{"n":72,"t":"“Hükümdarın kâsesini kaybettik; bulup getirene bir deve yükü bahşiş var” dediler. Çağırıcı, “Ben de buna kefilim” diye ilâve etti."},{"n":73,"t":"Kardeşleri, “Allah`a yemin ederiz ki, bizim yeryüzünde fesat çıkarmak için gelmediğimizi siz de biliyorsunuz. Bir hırsız da değiliz” dediler."},{"n":74,"t":"“Peki siz yalancı iseniz, bunun cezası nedir?”"},{"n":75,"t":"“Cezası, kayıp eşya kimin yükünde bulunduysa, ona aittir. Biz hırsızları böyle cezalandırırız.”"},{"n":76,"t":"Bunun üzerine Yûsuf, kendi kardeşinin yükünden önce onların yüklerini aramaya başladı. Sonra da eşyayı, kardeşinin yükünden çıkarttı. İşte biz Yûsuf`a böyle bir tedbir öğrettik; yoksa kralın hukukuna göre kardeşini alıkoyamayacaktı. Ancak Allah`ın dilemesi hariç. Biz kimi dilersek onu derecelerle yükseltiriz. Zira her ilim sahibinin üstünde daha iyi bilen birisi vardır."},{"n":77,"t":"“Eğer o çalmışsa, daha önce onun bir kardeşi de çalmıştı” dediler. Yûsuf bunu içinde sakladı, onlara açmadı. Yûsuf içinden, “Çok kötü durumdasınız ve Allah anlattığınızı daha iyi bilir” dedi."},{"n":78,"t":"Kardeşleri, “Ey Aziz! Doğrusu, onun yaşlı kalmış bir babası vardır. Bizden birini onun yerine al! Doğrusu, iyi davrananlardan olduğunu görüyoruz” dediler."},{"n":79,"t":"Yûsuf, “Allah korusun! Biz malımızı kimde bulmuşsak, ancak onu alıkoyarız. Yoksa haksızlık etmiş oluruz” dedi."},{"n":80,"t":"“Babanızın, Allah adına sizden kesin söz aldığını ve daha önce Yûsuf`a yaptığınız işi bilmiyor musunuz? Babam gelmeme izin verinceye veya hükmedenlerin en iyisi olan Allah, benim için hüküm verinceye kadar buradan ayrılmayacağım.”"},{"n":81,"t":"Ey babamız! Doğrusu, oğlun hırsızlık yaptı. Biz bildiğimizden başka bir şey görmedik. Gaybı da bilmeyiz.”"},{"n":82,"t":"“Bulunduğumuz kasabanın halkına ve beraberinde geldiğimiz kervana da sorabilirsin. Andolsun, doğru söylüyoruz.”"},{"n":83,"t":"“Hayır, nefisleriniz sizi böyle bir işe sürükledi. Bana düşen, güzel bir sabırdır. Umulur ki, Allah onların hepsini bana getirir. Çünkü O, bilendir; hikmet sahibidir.”"},{"n":84,"t":"Onlardan yüz çevirdi ve “âh Yûsuf`um ah!” diye sızlandı. Kederini içine gömmesi yüzünden gözlerine boz/perde geldi."},{"n":85,"t":"Oğulları, “Allah`a andolsun ki sen hâlâ Yûsuf`u anıyorsun. Sonunda hasta olacaksın ya da büsbütün helâk olacaksın” dediler."},{"n":86,"t":"Ya‘kûb, “Ben, sadece gam ve kederimi Allah`a arz ediyorum. Ben sizin bilmeyeceğiniz şeyleri Allah tarafından vahiy ile biliyorum” dedi."},{"n":87,"t":"Ya‘kûb, konuşmasına devamla, “‘Ey oğullarım! Gidiniz de Yûsuf`u ve kardeşini iyice araştırınız. Allah`ın rahmetinden ümit kesmeyiniz! Çünkü kâfirler topluluğundan başkası Allah`ın rahmetinden ümit kesmez” dedi."},{"n":88,"t":"“Ey Aziz! Bize ve çocuklarımıza darlık dokundu, değersiz bir sermaye ile geldik; ama sen bizim için tam ölçü ver, bize bağışta bulun. Şüphesiz, Allah bağışta bulunanları ödüllendirir.”"},{"n":89,"t":"“Sizler cahil iken, Yûsuf`a ve kardeşine yaptıklarınızı hatırlıyor musunuz?”"},{"n":90,"t":"“Â, yoksa sen Yûsuf musun?” dediler. “Ben Yûsuf`um, bu da kardeşimdir” dedi. “Allah bize lütfetti. Doğrusu, kim Allah`tan sakınır ve sabrederse, Allah iyilik edenlerin ödülünü vermemezlik etmez.”"},{"n":91,"t":"Kardeşleri, “Vallâhi, Allah seni bizden üstün kıldı. Doğrusu biz suç işlemiştik!” dediler."},{"n":92,"t":"Bunun üzerine Yûsuf, “Bugün size kınamak yok, Allah sizi bağışlar. O, merhamet edenlerin en merhametlisidir” dedi."},{"n":93,"t":"“Şu benim gömleğimi götürün de onu babamın yüzüne koyun, görecek duruma gelir. Bütün ailenizi bana getirin.”"},{"n":94,"t":"Kafile Mısır`dan ayrılınca, babaları yanındakilere, “Eğer bana bunamış demezseniz, inanın ben Yûsuf`un kokusunu alıyorum” dedi."},{"n":95,"t":"Onlar da, “Vallâhi sen hâlâ eski şaşkınlığındasın” dediler."},{"n":96,"t":"Müjdeci gelince, gömleği onun yüzüne koyar koymaz, Yakub görür oldu. Bunun üzerine Ya‘kûb, “Ben size Allah tarafından vahiy ile sizin bilemeyeceğiniz şeyleri bilirim, demedim mi?” dedi."},{"n":97,"t":"“Ey babamız! Allah`tan bizim günahlarımızın affını dile! Çünkü biz gerçekten günahkârlar idik.”"},{"n":98,"t":"Ya‘kûb, “Sizin için Rabbimden af dileyeceğim. Çünkü O, affedicidir; merhamet sahibidir.”"},{"n":99,"t":"“Allah`ın dileğiyle emniyet içinde Mısır`a giriniz.”"},{"n":100,"t":"“Babacığım, işte bu, benim önceden gördüğüm rüyanın yorumudur. Rabbim onu gerçekleştirdi. O, bana çok güzel lütuflarda bulundu. Çünkü şeytan benimle kardeşlerimin arasını bozduktan sonra, O, beni zindandan çıkardı. Sizi de çölden getirdi. Şüphesiz ki Rabbim dilediğine lütfedicidir. Şüphesiz O, her şeyi bilendir; hikmet sahibidir.”"},{"n":101,"t":"“Ey Rabbim! Bana hükümranlık verdin ve bana sosyal olguların yorumunu da öğrettin. Ey gökleri ve yeri yoktan yaratan! Sen dünyada da âhirette de benim sahibimsin. Beni Müslüman olarak öldür ve beni iyiler arasına kat!”"},{"n":102,"t":"İşte bu, Yûsuf kıssası, insanlığa ders olsun diye anlatılan, bilmediğiniz tarihin, gayb âleminin ibret verici haberlerindendir. Onu sana vahyediyoruz. Onlar sinsice hile planları yaparak, birlikte planlarına karar verdikleri zaman, sen onların yanında değildin."},{"n":103,"t":"Sen ne kadar üstüne düşsen de insanların çoğu iman edecek değillerdir."},{"n":104,"t":"Halbuki sen bunun karşılığında onlardan bir ücret istemiyorsun. Kur`ân, âlemler için ancak bir öğüttür."},{"n":105,"t":"Göklerde ve yerde nice deliller vardır ki, onlardaki delillerden yüzlerini çevirip geçerler."},{"n":106,"t":"Onların çoğu, Allah`a iman etmiyorlar, sadece şirk koşuyorlar."},{"n":107,"t":"Allah tarafından kuşatıcı bir felaket gelmesi veya farkında olmadan kıyametin ansızın kopması karşısında kendilerini güvende mi gördüler?"},{"n":108,"t":"“İşte benim yolum budur. Ben ve beni izleyenler, Allah`a bir aydınlık üzere çağırıyorum. Allah`ı noksan sıfatlardan uzak tutarım ve ben ortak koşanlardan değilim.”"},{"n":109,"t":"Senden önce de, şehir halkından seçip kendilerine vahyettiğimiz erkeklerden başkasını peygamber olarak göndermedik. Kâfirler yeryüzünde dolaşıp da kendilerinden öncekilerin sonunun nasıl olduğunu görmediler mi? Sakınanlar için âhiret yurdu elbette daha iyidir. Hâlâ aklınızı kullanmıyor musunuz?"},{"n":110,"t":"Nihayet peygamberler ümitlerini yitirip de kendilerinin yalancı sanıldıklarını anladıklarında, onlara yardımımız gelir ve dilediğimiz kimse kurtuluşa erdirilir. Suçlular topluluğundan azabımız asla geri çevrilmez."},{"n":111,"t":"Andolsun, onların olgularında akıl sahipleri için pek çok ders vardır. Kur`ân, uydurulabilecek bir söz değildir. Fakat Kur`ân, kendinden öncekileri tasdik eden, her şeyi açıklayan; iman eden toplum için bir rahmet ve bir rehberdir."}],[{"n":1,"t":"Elif, lâm, mîm, râ. Bunlar, kitabın âyetleridir. Sana Rabbinden indirilen haktır. Fakat insanların çoğu anlamazlar."},{"n":2,"t":"Görmekte olduğunuz gökleri direksiz olarak yükselten, sonra hükümranlık tahtını/tüm kâinatı kaplayan, Güneş`i ve Ay`ı emrine boyun eğdiren Allah`tır. Bunların her biri belirli bir vakte kadar akıp gitmektedir. O, Rabbinize kavuşacağınıza kesin olarak inanmanız için her işi düzenleyip âyetleri açıklamaktadır."},{"n":3,"t":"Yeryüzünü döşeyen, onda oturaklı dağlar ve ırmaklar yaratan ve orada bütün meyvelerden çifter çifter yaratan O`dur. Geceyi de gündüzün üzerine O örtüyor. Şüphesiz bütün bunlarda düşünen bir toplum için dersler vardır."},{"n":4,"t":"Yeryüzünde birbirine komşu kıtalar, üzüm bağları, ekinler, çatallı ve çatalsız hurmalıklar vardır. Bunların hepsi bir su ile sulanır; yemişlerinde onların bir kısmını bir kısmına üstün kılarız. İşte bunlarda akıllarını kullanan bir toplum için dersler vardır."},{"n":5,"t":"Şaşıyorsan, asıl şaşılacak şey onların, “Biz toprak olduğumuz zaman yeniden mi yaratılacağız?” demeleridir. İşte onlar, Rabblerine nankörlük edenlerdir. Onlar, boyunlarında tasmalar bulunanlardır. Onlar ateş ehlidir. Onlar orada uzun süreli kalacaklardır."},{"n":6,"t":"Senden, iyilikten önce kötülüğü çabucak istiyorlar. Halbuki önlerinden pek çok örnek gelip geçti. Doğrusu insanlar kötülük ettikleri halde Rabbin onlar için affedicidir. Rabbinin azabı elbette çok şiddetlidir."},{"n":7,"t":"“Ona Rabbinden bir mucize indirilseydi ya!” Sen ancak bir uyarıcısın ve her toplumun da bir rehberi vardır."},{"n":8,"t":"Allah, her dişinin neyi taşımakta olduğunu, gebe kalacağını, rahimlerin neyi eksiltip neyi arttıracağını bilir. Onun katında her şey bir ölçüye bağlıdır."},{"n":9,"t":"O, gaybı da, görünen âlemi de bilendir, çok büyüktür; yücedir."},{"n":10,"t":"Sizden sözü saklayan da açıklayan da, geceye sığınıp gizlenen de gündüz yol alan da, O`nun için birdir."},{"n":11,"t":"Onun önünde ve arkasında Allah`ın emriyle onu koruyan takipçiler/melekler vardır. Bir toplumu oluşturan fertler kendi iç dünyalarındakini değiştirinceye kadar, Allah onların oluşturduğu toplumu değiştirmez. Allah bir topluma kötülük diledi mi, artık onun için geri çevrilme diye bir şey yoktur. Onların Allah`tan başka yardımcıları da yoktur."},{"n":12,"t":"Bir korku ve ümit vesilesi olarak şimşeği size gösteren ve ağır bulutları yaratan O`dur."},{"n":13,"t":"Gök gürlemesi, Allah`ı överek tesbih eder ve melekler de korkularından onu yüceltirler. Onlar pek güçlü olan Allah hakkında tartışırken O, yıldırımları gönderir de dilediğini onlarla çarpar. O, tuzağı çetin olandır."},{"n":14,"t":"Gerçek dua, yalnız Allah`a yöneltilen çağrıdır. Müşriklerin Allah dışında çağrı yönelttikleri putlar, onların hiçbir dileklerine cevap veremezler. Böyleleri ağzına su gelsin diye avuçlarını ona doğru açan kimseye benzerler ki, asla bu yolla ağzına su gelmez. İşte kâfirlerin çağrısı böylesine boşunadır."},{"n":15,"t":"Göklerde ve yerde bulunanlar da, onların gölgeleri de sabah akşam, ister istemez, sadece Allah`a secde ederler."},{"n":16,"t":"“Allah her şeyi yaratandır. O, birdir. Karşı durulmaz güç sahibidir.”"},{"n":17,"t":"Köpük, atılır gider; insanlara yararlı olansa toprakta kalır. Allah, işte bu şekilde örnekler verir."},{"n":18,"t":"Rabblerinin çağrısına uyanlara en güzel ödül vardır. O`nun çağrısına gelmeyenler ise, yeryüzünde olan her şey ve bir katı daha onların olsa, kurtulmak için bunları feda ederlerdi. Onlara hesabın en kötüsü vardır. Varacakları yer de cehennemdir. O ne kötü yataktır!"},{"n":19,"t":"Rabbinden sana indirilenin hak olduğunu bilen kişi, kör olan biri ile aynı mıdır? Sadece akıl sahipleri düşünürler."},{"n":20,"t":"Onlar, Allah`a verdikleri söze sadık kalanlar ve antlaşmayı bozmayanlardır."},{"n":21,"t":"Onlar, Allah`ın bitiştirilmesini emrettiği şeyi bitiştirirler. Rabblerine saygı duyarlar ve hesabın kötüsünden korkarlar."},{"n":22,"t":"Onlar, Rabblerinin rızasını arzulayarak sabrederler; namazı kılarlar, kendilerine verdiğimiz rızıklardan gizli ve açık dağıtırlar ve kötülüğü güzellikle savarlar. İşte bu dünyanın iyi sonucu bu amelleri yapanlar içindir."},{"n":23,"t":"‘Adn cennetleri bunlar içindir. Atalarından, eşlerinden ve zürriyetlerinden iyi olanlarla birlikte oraya girerler. Meleklerse her kapıdan yanlarına sokulurlar."},{"n":24,"t":"“Sabrettiğiniz için selâm size. Ahiret yurdunun ödülü ne güzeldir!” derler."},{"n":25,"t":"Allah`a verdikleri sözü, onu antlaşma haline getirdikten sonra bozanlara, Allah`ın bitiştirilmesini emrettiği şeyi bitiştirmeyenlere ve yeryüzünde bozgunculuk çıkaranlara gelince, böyleleri için lanet vardır ve yurdun en kötüsü de onların olacaktır."},{"n":26,"t":"Allah dilediğine rızkını bollaştırır da, daraltır da. Onlar dünya hayatıyla şımardılar. Oysa âhiretin yanında dünya hayatı, geçici bir faydadan başka bir şey değildir."},{"n":27,"t":"“Doğrusu, Allah dileyeni saptırır, bütün benliğiyle kendisine yöneleni de doğru yola iletir.”"},{"n":28,"t":"Bunlar, iman edenler ve gönülleri Allah`ın zikri ile doyuma ulaşanlardır. Bilesiniz ki kalpler, ancak Allah`ı anmakla doyuma ulaşır."},{"n":29,"t":"İman edip iyi işler yapanlara ne mutlu! Varılacak güzel yurt da onlar içindir."},{"n":30,"t":"“O benim Rabbimdir. O`ndan başka tanrı yoktur. O`na güvenirim ve dönüşüm de O`nadır.”"},{"n":31,"t":"Eğer, Kur`ân ile dağlar yürütülmüş veya yeryüzü parçalanmış yahut ölüler konuşturulmuş olsaydı, kâfirler yine inanmazlardı. Halbuki bütün işler Allah`a aittir. İnananlar hâlâ anlamadılar mı; Allah dilerse, bütün insanları yola getirebilirdi. Allah`ın sözü yerine gelene kadar, yaptıklarından ötürü, inkâr edenlerin ya başlarına yahut evlerinin yakınına düşecek bir vurucu felâketin gelmesi kaçınılmazdır. Doğrusu, Allah verdiği sözden caymaz."},{"n":32,"t":"Andolsun, senden önceki peygamberlerle de alay edildi; ancak ben inkâr edenlere mühlet verdim; sonra da onları yakaladım. Azabım nasılmış!"},{"n":33,"t":"“Onlara bir ad bulun. Yoksa siz Allah`a yeryüzünde bilemeyeceği bir şeyi mi haber veriyorsunuz? Yahut boş laf mı ediyorsunuz?” Doğrusu inkâr edenlere hileleri süslü gösterildi ve onlar doğru yoldan alıkoydular. Allah kimi saptırırsa, artık onu doğru yola iletecek yoktur."},{"n":34,"t":"Onlara dünya hayatında azap vardır. Ama, âhiret azabı daha şiddetlidir. Onları Allah`tan koruyacak kimse de yoktur."},{"n":35,"t":"Altından ırmaklar akar; yemişi de süreklidir, gölgesi de. İşte takvâ sahiplerinin sonu budur. İnkâr edenlerin sonu da ateştir."},{"n":36,"t":"“Bana, sadece Allah`a kulluk etmem ve O`na ortak koşmamam emrolundu. Ben yalnız O`na çağırıyorum ve dönüş de yalnız O`nadır.”"},{"n":37,"t":"İşte biz o Kur`ân`ı Arapça bir hikmet kaynağı olarak indirdik. Eğer sana gelen bu ilimden sonra onların arzularına uyarsan, Allah`tan sana ne bir dost nasip olur, ne de bir koruyucu."},{"n":38,"t":"Andolsun, biz senden önce de peygamberler gönderdik; onlara da eşler ve çocuklar verdik. Hiçbir peygamber Allah`ın izni olmadıkça herhangi bir mucize getiremez. Her ecel için bir yazı/belirlenmiş bir vakit vardır."},{"n":39,"t":"Allah dilediğini siler; dilediğini sabit bırakır. Kitabın anası/anayasa O`nun katındadır."},{"n":40,"t":"Ya onlara vaad ettiğimiz şeylerin bir kısmını sana gösteririz; yahut da seni vefat ettiririz. O halde tebliğ etmek sana, hesap sormak da bize düşer."},{"n":41,"t":"Bizim o yer küreye gelip nasıl onu uçlarından eksilttiğimizi görmediler mi? Hüküm veren Allah`tır; O`nun hükmünün ardına düşüp onu iptal edecek yoktur. O, hesabı çabuk görendir."},{"n":42,"t":"Onlardan önce geçenler de tuzak kurmuşlardı. Oysa tuzakların tamamı Allah`a aittir. Çünkü Allah, herkesin ne elde ettiğini ve edeceğini bilir. İnkârcılar da dünyanın sonunun kimin olduğunu bileceklerdir."},{"n":43,"t":"“Benim ile sizin aranızda tanık olarak Allah ve kitabı bilenler yeter.”"}],[{"n":1,"t":"Elif, lâm, râ. Bu, Rabblerinin izniyle insanları karanlıklardan aydınlığa, yani her şeye galip ve övgüye lâyık olan Allah`ın yoluna çıkarman için sana indirdiğimiz bir kitaptır."},{"n":2,"t":"Göklerde ve yerde ne varsa hepsi kendisinin olan Allah`ın yoluna. Şiddetli azaptan dolayı kâfirlerin vay haline!"},{"n":3,"t":"O kâfirler, dünya hayatını âhirete tercih ederler, Allah yolundan alıkoyarlar ve onun yolunu eğri göstermek isterler. İşte onlar uzak bir sapıklık içindedirler."},{"n":4,"t":"Onlara iyice açıklasın diye her peygamberi yalnız kendi kavminin dili ile gönderdik. Artık Allah dileyeni saptırır, dileyeni de doğru yola iletir. Çünkü O, güçlüdür; hikmet sahibidir."},{"n":5,"t":"Andolsun ki biz, Mûsâ`yı, “Toplumunu karanlıklardan aydınlığa çıkar ve onlara Allah`ın günlerini hatırlatıp bellet!” diye âyetlerimizle gönderdik. Şu bir gerçek ki, bunda iyice sabreden, çokça şükreden herkes için nice deliller vardır."},{"n":6,"t":"“Allah`ın üzerinizdeki nimetini hatırlayınız! Hani, O sizi Firavun`un hanedanından, adamlarından kurtarmıştı. Onlar size azabın en kötüsüyle acı çektiriyorlar, erkek çocuklarınızı doğruyorlar, kadınlarınızı sağ bırakıyorlardı.” İşte bunda sizin için Rabbinizden gelen çok büyük bir imtihan vardır."},{"n":7,"t":"“Eğer şükrederseniz, ben de sizin için nimetimi mutlaka arttıracağım. Eğer nankörlük ederseniz, hiç şüphesiz benim azabım çok çok şiddetlidir.”"},{"n":8,"t":"“Siz ve yeryüzünde bulunanların tümü inkâr etseniz, hiç şüphesiz Allah mutlak zengindir; övülmeye lâyıktır.”"},{"n":9,"t":"“Biz, size gönderileni inkâr ettik ve bizi kendisine çağırdığınız şeye karşı derin bir kuşku içindeyiz.”"},{"n":10,"t":"“Siz de bizim gibi bir insandan başka bir şey değilsiniz. Siz, bizi atalarımızın tapmış olduğu şeylerden döndürmek istiyorsunuz. Öyleyse bize, bu iddianız konusunda apaçık bir delil getiriniz!”"},{"n":11,"t":"“Evet, biz sizin gibi bir insandan başkası değiliz. Fakat Allah, nimetini kullarından dilediğine lütfeder. Allah`ın izni olmadan bizim size bir delil getirmemize imkân yoktur. Müminler ancak Allah`a dayansınlar.”"},{"n":12,"t":"“Hem, bize yollarımızı göstermiş olduğu halde ne diye biz, Allah`a dayanıp güvenmeyelim? Sizin bize verdiğiniz eziyete elbette katlanacağız. Allah`a güvenip dayananlar bunda süreklilik göstersinler!”"},{"n":13,"t":"“Elbette sizi ya yurdumuzdan çıkaracağız ya da mutlaka yolumuza döneceksiniz!” Rabbleri de onlara, “Zâlimleri mutlaka helâk edeceğiz!” diye vahyetti."},{"n":14,"t":"“Ey inananlar! Onlardan sonra sizi mutlaka o yerde yerleştireceğiz. İşte bu, makamımdan korkan ve tehdidimden sakınan kimselere aittir.”"},{"n":15,"t":"Peygamberler fetih istediler, Allah da verdi. Her inatçı zorba da hüsrana uğradı."},{"n":16,"t":"Ardından da cehennem vardır ve orada kendisine irinli su içirilecektir."},{"n":17,"t":"Onu yudumlamaya çalışacak, fakat boğazından geçiremeyecek ve ona her yandan ölüm gelecek, oysa o ölecek değildir. Bundan öte şiddetli bir azap da vardır."},{"n":18,"t":"Rabblerini inkâr edenlerin amelleri, fırtınalı bir günde rüzgârın tarumar ettiği küle benzer. Kazandıklarından hiçbir şey elde edemezler. İşte bu, dönüşü olmayan sapıklığın ta kendisidir."},{"n":"19-20","t":"Allah`ın, gökleri ve yeri bir amaç uğruna yarattığını görmedin mi? O dilerse sizi ortadan kaldırıp yepyeni bir halk getirir. Bu, Allah`a güç değildir."},{"n":21,"t":"“Allah bize yol gösterseydi, biz de size yol gösterirdik. Artık şimdi sızlansak da sabretsek de bizim için birdir, kaçıp sığınacak bir yerimiz yoktur!”"},{"n":22,"t":"“Şüphesiz Allah, size gerçek olanı (ahireti) vaad etmişti. Ben de size (ahiretin olmadığını) vaad etmiştim. Söz verdim ama (gördüğünüz gibi) yalancı çıktım. Zaten benim sizi zorlayacak bir gücüm de yoktu. Ben sizi sadece (isyana ve inkâra) çağırdım, (işinize geldiği için) siz de hemen bana geliverdiniz. O hâlde beni kınamayın, kendinizi kınayın. Artık ben sizi kurtaramam, siz de beni kurtaramazsınız. Aslında, beni Allah`a ortak koşmanızı (Allah`ın peygamberlerine uymak yerine benim arkamdan koşmanızı) onaylamış da değildim. Hiç kuşkusuz zalimlere pek de acıklı bir azap vardır."},{"n":23,"t":"İman edip de iyi işler yapanlar, Rabblerinin izniyle içinde uzun süreli kalacakları ve zemininden ırmaklar akan cennetlere sokulacaklardır. Orada birbirleriyle karşılaştıkça söyleyecekleri söz, “selâm”dır."},{"n":24,"t":"Görmedin mi Allah nasıl bir örnekleme yaptı. Güzel söz, kökü yerde sabit, dalları gökte olan verimli bir ağaca benzer."},{"n":25,"t":"O ağaç, Rabbinin izniyle meyvesini her zaman verir. Allah, insanlara böyle örnekler verir ki, düşünebilsinler."},{"n":26,"t":"Çirkin bir söz de, gövdesi toprağın üstünde destek bulamamış bir ağaca benzer."},{"n":27,"t":"Allah, sağlam sözle iman edenleri hem dünya hayatında hem de âhirette sapasağlam tutar. Zâlimleri ise saptırır. Allah dilediğini yapar."},{"n":28,"t":"Allah`ın nimetine nankörlükle karşılık veren ve sonunda toplumlarını helâk yurduna sürükleyenleri görmedin mi?"},{"n":29,"t":"Onlar cehenneme girecekler. O, ne kötü karargâhtır!"},{"n":30,"t":"“Biraz daha oyalanınız! Sonunda dönüşünüz ateşedir.”"},{"n":31,"t":"İnanan kullarıma söyle! “Namazı kılsınlar; kendilerine verdiğimiz rızıklardan, hiçbir alış verişin, hiçbir dostluğun olmadığı gün gelmeden önce gizli ve âşikâr infak etsinler.”"},{"n":32,"t":"Gökleri ve yeri yaratan, gökten suyu indirip onunla rızık olarak size türlü meyveler çıkaran; izni ile denizde yüzüp gitmeleri için gemileri emrinize veren; nehirleri de sizin için akıtan O`dur."},{"n":33,"t":"Düzenli seyreden güneşi ve ayı size faydalı kılan; geceyi ve gündüzü de istifadenize sunan O`dur."},{"n":34,"t":"O size istediğiniz her şeyden verdi. Allah`ın nimetini sayacak olsanız sayamazsınız. Doğrusu insan çok zâlimdir; çok nankördür!"},{"n":35,"t":"“Ey Rabbim! Bu şehri güvenli kıl, beni ve oğullarımı putlara tapmaktan uzak tut!”"},{"n":36,"t":"“Ey Rabbim! Onlar insanlardan birçoğunu şaşırttılar. Artık bundan böyle kim bana uyarsa o bendendir; kim bana karşı gelirse, şüphesiz sen, affedicisin; merhamet sahibisin.”"},{"n":37,"t":"“Ey Rabbimiz! Ben çocuklarımdan bazısını ekilebilir toprağı olmayan vadiye, senin Kutsal Ev`inin yakınına yerleştirdim. Ey Rabbimiz! Namazı dosdoğru kılsınlar diye böyle yaptım. Artık sen de insanlardan bir kısmının gönüllerini onlara meylettir ve meyvelerden onlara rızık ver! Umulur ki bu nimetlere şükrederler.”"},{"n":38,"t":"“Ey Rabbimiz! Sen bizim gizlediğimizi ve açığa vurduğumuzu bilirsin.” Ne yerde ne de gökte hiçbir şey Allah`a gizli kalmaz."},{"n":39,"t":"“İhtiyarlık çağımda bana İsmail`i ve İshak`ı lütfeden Allah`a hamdolsun! Şüphesiz Rabbim, duayı işitendir.”"},{"n":40,"t":"“Ey Rabbim! Beni, soyumdan gelenleri, namazı devamlı kılanlardan eyle! Ey Rabbimiz! Duamı kabul et!”"},{"n":41,"t":"“Ey Rabbimiz! Hesabın görüleceği gün beni, anamı, babamı ve bütün müminleri bağışla!”"},{"n":42,"t":"Sakın, Allah`ı zâlimlerin yaptıklarından habersiz sanma! Sadece Allah onları, korkudan gözlerin dışarı fırlayacağı bir güne erteliyor."},{"n":43,"t":"O gün başlarını dikerek koşarlar; bakışları kendilerine dönmez. Yüreklerinin içi de bomboştur."},{"n":44,"t":"Kendilerine azabın geleceği güne karşı insanları uyar ki, zâlimler, “Ey Rabbimiz!” derler, “Bizi yakın bir süreye kadar ertele de senin çağrına uyalım, peygamberlere tâbi olalım!” Peki önceden, sizin için son olmadığına yemin etmemiş miydiniz?"},{"n":45,"t":"Siz de kendilerine zulmedenlerin yurtlarında oturdunuz. Onlara nasıl muamele ettiğimiz size apaçık belli oldu. Size misaller de verdik."},{"n":46,"t":"Kâfirler tuzaklarını kurdular. Onların tuzakları sebebiyle dağlar yerinden oynayacak nitelikte olsa bile, tuzakları Allah`ın katındadır."},{"n":47,"t":"O halde sakın Allah`ın peygamberlerine verdiği sözden cayacağını sanma! Çünkü Allah mutlak üstündür; öç alandır."},{"n":"48-49","t":"Yerin başka bir yere, göklerin başka göklere dönüştürüleceği ve insanların bir olan ve gücüne karşı durulamaz olan Allah`ın huzuruna çıktıkları gün, işte o gün, günahkârların zincirlere vurulmuş olduğunu görürsün."},{"n":50,"t":"Onların gömlekleri katrandandır; yüzlerini de ateş bürümektedir."},{"n":51,"t":"Allah herkese kazandığının karşılığını vermek için onları diriltecektir. Şüphesiz Allah, hesabı çabuk görendir."},{"n":52,"t":"İşte bu, kendisiyle uyarılsınlar, Allah`ın ancak bir tek tanrı olduğunu bilsinler ve akıl sahipleri iyice düşünüp öğüt alsınlar diye, insanlara bir bildiridir."}],[{"n":1,"t":"Elif, lâm, râ. Bunlar, kitabın ve apaçık bir Kur`ân`ın âyetleridir."},{"n":2,"t":"İnkâr edenler zaman zaman, “Keşke Müslüman olsaydık!” diye derin bir özlem duyarlar."},{"n":3,"t":"Bırak onları, yesinler, eğlensinler ve boş ümitler onları oyalayadursun. İleride yaptıklarının yanlış olduğunu bilecekler."},{"n":4,"t":"Biz, hiçbir toplumu ilâhî kitaptan haberdar kılmadan helâk etmedik."},{"n":5,"t":"Hiçbir millet, kendi ecelini ne ileri alabilir ne de geciktirebilir."},{"n":6,"t":"“Ey kendisine Kur`ân indirilen! Sen mutlaka bir delisin.”"},{"n":7,"t":"“Doğru sözlülerden isen, bize melekleri getirsene!”"},{"n":8,"t":"Biz melekleri ancak bir amaç için indiririz. O zaman onlara mühlet verilmez."},{"n":9,"t":"Kur`ân`ı kesinlikle biz indirdik; elbette onu yine biz koruyacağız."},{"n":10,"t":"Andolsun ki senden önce gelip geçmiş topluluklar arasından peygamberler gönderdik."},{"n":11,"t":"Onlar, gelen peygamberi mutlaka alaya alırlardı."},{"n":12,"t":"Böylece biz de o alayı suçluların kalplerine sokarız."},{"n":13,"t":"Geçmişteki milletlerin durumu ortada iken, yine de ona inanmazlar."},{"n":"14-15","t":"Onlara gökten bir kapı açsaydık da oraya çıkmaya koyulsalardı; “şüphesiz ki gözlerimiz döndü; hayır, büyüye uğramış bir topluluk olduk” derlerdi."},{"n":16,"t":"Gerçekten de biz gökyüzüne büyük takımyıldızları/burçlar serpiştirdik ve onları seyredenler için süsleyip bezedik."},{"n":17,"t":"Onu kovulmuş her türlü şeytana karşı koruduk."},{"n":18,"t":"Ancak, kulak hırsızlığına kalkışan olursa, onun peşine de parlak bir ateş alevi takılır."},{"n":19,"t":"Yeryüzünü yaydık, oraya sabit dağlar diktik ve orada her şeyi ölçülü bitirdik."},{"n":20,"t":"Orada hem sizin için hem de sizin rızık veremeyeceğiniz varlıklar için geçimlikler var ettik."},{"n":21,"t":"Katımızda hazineleri olmayan hiçbir şey yoktur. Biz onu ancak bilinen bir ölçüye göre indiririz."},{"n":22,"t":"Biz, rüzgârları dölleyici olarak gönderdik ve böylece gökten su indirdik de sizi onunla suladık. Yoksa, siz o suyu depolayamazdınız."},{"n":23,"t":"Doğrusu biz diriltiriz, öldürürüz ve hepsinin vârisi biz kalırız."},{"n":24,"t":"Andolsun biz sizden önce gelip geçenleri de biliriz; geri kalanları da biliriz."},{"n":25,"t":"Şüphesiz, Rabbin onları toplayacaktır. Çünkü O, işini yerli yerince yapan, her şeyi bilendir."},{"n":26,"t":"Andolsun biz insanı kuru bir çamurdan, şekillenmiş kara balçıktan yarattık."},{"n":27,"t":"Cinleri de daha önce zehirli ateşten yaratmıştık."},{"n":28,"t":"“Ben kupkuru bir çamurdan, şekillenmiş kara balçıktan bir insan yaratacağım.”"},{"n":29,"t":"“Ona şekil verdiğim ve ona ruhumdan üflediğim zaman, siz hemen onun için secdeye kapanın!”"},{"n":30,"t":"Meleklerin hepsi de hemen secde ettiler."},{"n":31,"t":"Yalnız İblis, secdeye kapananlar arasında olmayı reddetti."},{"n":32,"t":"Allah, “Ey İblis! Secde edenlerle beraber olmayışının sebebi nedir?” dedi."},{"n":33,"t":"İblis, “Ben, kuru bir çamurdan, şekillenmiş kara balçıktan yarattığın bir insana secde edecek değilim” dedi."},{"n":34,"t":"Allah «Öyleyse defol oradan, artık sen rahmetimden kovulmuşsun» dedi."},{"n":35,"t":"“Muhakkak ki kıyamet gününe kadar lanet senin üzerine olacaktır.”"},{"n":36,"t":"İblis, “Ey Rabbim! Öyle ise, öldükten sonra dirilme gününe kadar bana mühlet ver!” dedi."},{"n":"37-38","t":"Allah, “Sen bilinen bir vakte kadar kendilerine mühlet verilenlerdensin” buyurdu."},{"n":39,"t":"“Ey Rabbim! Beni azdırmana karşılık ben de yeryüzünde onlara kötü davranışları süsleyeceğim ve ihlâslı kulların hariç onların hepsini mutlaka azdıracağım!”"},{"n":40,"t":"“Ey Rabbim! Beni azdırmana karşılık ben de yeryüzünde onlara kötü davranışları süsleyeceğim ve ihlâslı kulların hariç onların hepsini mutlaka azdıracağım!”"},{"n":41,"t":"“Benim doğru yolum budur.”"},{"n":42,"t":"“Şüphesiz, senin, kullarım üzerinde bir hakimiyetin yoktur. Ancak, azgınlardan sana uyanlar müstesna.”"},{"n":43,"t":"Muhakkak cehennem, onların hepsine vaad olunan yerdir."},{"n":44,"t":"Cehennemin yedi kapısı vardır. Onlardan her kapı için birer grup ayrılmıştır."},{"n":45,"t":"Takvâ sahipleri, elbette cennetlerde ve pınar başlarında olacaklar."},{"n":46,"t":"Oraya esenlik ve emniyetle giriniz!"},{"n":47,"t":"Biz, onların gönüllerindeki kini söküp attık; onlar artık köşkler üzerinde karşı karşıya oturan kardeşler olacaklar."},{"n":48,"t":"Onlara orada hiçbir yorgunluk dokunmayacak ve onlar oradan çıkarılmayacaktır."},{"n":49,"t":"Kullarıma, benim çok bağışlayıcı ve merhamet sahibi olduğumu haber ver!"},{"n":50,"t":"Benim azabımın elem verici bir azap olduğunu da bildir!"},{"n":51,"t":"Onlara İbrâhim`in misafirlerinden de haber ver!"},{"n":52,"t":"Onun yanına girdikleri zaman, “Selâm” dediler. İbrâhim, “Biz sizden çekiniyoruz” dedi."},{"n":53,"t":"“Korkma, biz sana bilgin bir oğul müjdeliyoruz.”"},{"n":54,"t":"İbrâhim, “Bana ihtiyarlık çökmesine rağmen beni müjdeliyor musunuz? Beni ne ile müjdeliyorsunuz?” dedi."},{"n":55,"t":"Melekler, “Sana gerçeği müjdeledik, sakın ümitsizliğe düşenlerden olma!” dediler."},{"n":56,"t":"İbrâhim, “Rabbinin rahmetinden sapıklardan başka kim ümit keser?” dedi."},{"n":57,"t":"İbrâhim, “Ey elçiler! Başka ne işiniz var?” dedi."},{"n":58,"t":"“Biz, suçlu bir topluma gönderildik.”"},{"n":59,"t":"“Ancak Lût ailesi hariç, inananların hepsini kurtaracağız.”"},{"n":60,"t":"“Lût`un karısı müstesna; biz onun geri kalanlardan olmasını takdir ettik.”"},{"n":61,"t":"Elçiler Lût ailesine gelince,"},{"n":62,"t":"Lût onlara, “Hakikaten siz tanınmayan kimselersiniz” dedi."},{"n":63,"t":"“Bilakis, biz sana, onların şüphe etmekte oldukları şeyi getirdik.”"},{"n":64,"t":"“Sana gerçeği getirdik; biz, hakikaten doğru söyleyenleriz.”"},{"n":65,"t":"“Gecenin bir bölümünde aile fertlerini yola çıkar, sen de arkalarından yürü! Sizden hiç kimse, sakın dönüp de arkasına bakmasın; istenen yere gidiniz.”"},{"n":66,"t":"“Sabaha çıkarlarken mutlaka onların ardı kesilmiş olacaktır.”"},{"n":67,"t":"Şehir halkı, birbirlerini kutlayarak geldiler."},{"n":68,"t":"Lût onlara, “Bunlar benim misafirlerimdir. Sakın beni utandırmayınız!”"},{"n":69,"t":"“Allah`tan sakının, beni rezil etmeyin!” dedi."},{"n":70,"t":"Bunun üzerine onlar da, “Biz seni başkalarının işine karışmaktan men etmemiş miydik?” dediler."},{"n":71,"t":"Lût, “Eğer düşündüğünüzü yapacaksanız, işte kızlarım, onlarla evlenin!” dedi."},{"n":72,"t":"Senin ömrüne andolsun ki onlar, sarhoşluklarının içinde bocalıyorlardı."},{"n":73,"t":"Güneş doğarken onları o korkunç ses yakaladı."},{"n":74,"t":"Böylece ülkelerinin üstünü altına getirdik. Üzerlerine de balçıktan pişirilmiş taşlar yağdırdık."},{"n":75,"t":"İşte bunda feraset/güçlü anlayış sahipleri için işaretler vardır."},{"n":76,"t":"Onlar hâlâ gözler önünde duran bir yol üzerindedirler."},{"n":77,"t":"Hakikaten bunda iman edenler için büyük bir ders vardır."},{"n":78,"t":"Eyke halkı da gerçekten zâlim idiler."},{"n":79,"t":"Biz onlardan da intikam aldık. İkisi de açık bir yol üzerindedir."},{"n":80,"t":"Andolsun, Hicr halkı da peygamberleri yalanlamıştı."},{"n":81,"t":"Biz onlara mucizelerimizi vermiştik; fakat onlar yüz çevirmişlerdi."},{"n":82,"t":"Onlar, dağlardan emniyet içinde kalacakları evler oyarlardı."},{"n":83,"t":"Onları da sabaha çıkarlarken o korkunç ses yakaladı."},{"n":84,"t":"Kazandıkları kendilerine hiçbir yarar sağlamadı."},{"n":85,"t":"Biz gökleri, yeri ve bunlar arasında bulunanları bir amaç için yarattık. O saat de mutlaka gelecektir. Şimdi sen onlara karşı iyice tedbirli ol!"},{"n":86,"t":"Şüphesiz Rabbin her şeyi yaratan ve her şeyi bilendir."},{"n":87,"t":"Andolsun ki biz sana tekrarlanan yedi âyeti ve yüce Kur`ân`ı verdik."},{"n":88,"t":"Sakın onlardan bazı sınıflara verdiğimiz dünya nimetine göz dikme, onlardan dolayı üzülme ve müminlere alçak gönüllü ol!"},{"n":89,"t":"“Şüphesiz ben apaçık bir uyarıcıyım.”"},{"n":90,"t":"“Nitekim biz, bölücülere azabı indirmişizdir.”"},{"n":91,"t":"Onlar, Kur`ân`ı bölüp ayıranlardır."},{"n":"92-93","t":"“Rabbin hakkı için, mutlaka onların hepsini yaptıklarından dolayı sorguya çekeceğiz.”"},{"n":94,"t":"“Sana emrolunanı açıkça ortaya koy ve Allah`a ortak koşanlardan yüz çevir!”"},{"n":95,"t":"“Seninle alay edip, ilâhî mesajı küçümseyenlere karşı biz sana yeteriz.”"},{"n":96,"t":"“Onlar Allah ile beraber başka bir tanrı edinenlerdir. Yakında gerçeği bileceklerdir.”"},{"n":97,"t":"“Andolsun, onların söyledikleri şeylerden dolayı senin canının sıkıldığını biliyoruz.”"},{"n":98,"t":"“Sen şimdi Rabbini hamd ile tesbîh et ve secde edenlerden ol!”"},{"n":99,"t":"“Sana yakîn/kesin bilgi ya da ölüm gelinceye kadar Rabbine ibadet et!”"}],[{"n":1,"t":"Allah`ın emri gelmiştir. Artık onu istemekte acele etmeyiniz! Allah, onların koştukları ortaklardan uzaktır, yücedir."},{"n":2,"t":"“Benden başka tanrı olmadığına dair uyarıda bulunun ve benden sakınınız!”."},{"n":3,"t":"Allah gökleri ve yeri bir amaç ile yarattı. O, koştukları ortaklardan uzaktır."},{"n":4,"t":"O, insanı nutfeden/meniden yani erlik suyundan yarattı. Öyleyken, insan apaçık bir hasım kesildi."},{"n":5,"t":"O, hayvanları da yaratmıştır. Onlarda sizi sıcak tutacak ve daha birçok faydalı şeyler vardır. Onlardan kimini de yersiniz."},{"n":6,"t":"Akşamleyin getirirken de sabahleyin salıverirken de onlarda sizin için bir güzellik vardır."},{"n":7,"t":"Hayvanlar, kendi kendinize zor varacağınız şehirlere ağırlıklarınızı taşırlar. Doğrusu Rabbiniz affedicidir; merhamet sahibidir."},{"n":8,"t":"Atları, katırları ve eşekleri binmeniz ve süs için yarattı. Bilmediğiniz nice şeyler yaratmaktadır."},{"n":9,"t":"Yolun doğrusu Allah`ındır. Yolun eğrisi de vardır. O, dileseydi hepinizi doğru yola iletirdi."},{"n":10,"t":"Gökten size su indiren O`dur. İçeceğiniz ondandır, hayvanları otlattığınız bitkiler de onunla biter."},{"n":11,"t":"Allah, o su ile size ekinler, zeytinler ve hurma ağaçları, bağlar ve her türlü ürünü yetiştirir. Düşünen topluma bunda ders vardır."},{"n":12,"t":"Geceyi, gündüzü, güneşi, ayı sizin hizmetinize verdi. Yıldızlar onun buyruğuna boyun eğmektedir. Aklını kullananlara bunda dersler vardır."},{"n":13,"t":"Yeryüzünde rengârenk şeyleri de sizin için yaratmıştır. Öğüt alacak topluma bunda ders vardır."},{"n":14,"t":"Taze et yemeniz, takındığınız süsleri elde etmeniz, Allah`ın bol nimetlerinden faydalanmanız ve şükretmeniz için gemilerin de yara yara gittiğini gördüğün denize boyun eğdiren de O`dur."},{"n":"15-16","t":"Sizi sallar diye yeryüzüne sabit dağlar, ırmaklar ve doğru yolda olasınız diye yollar ve işaretler yerleştirdi. Onlar yıldızlarla da yol bulurlar."},{"n":17,"t":"Yaratan, yaratmayana hiç benzer mi? Düşünüp anlamaz mısınız?"},{"n":18,"t":"Allah`ın nimetini saymaya kalksanız bile onu sayamazsınız. Allah affedicidir; merhamet sahibidir."},{"n":19,"t":"Allah gizlediğinizi de açıkladığınızı da bilir."},{"n":20,"t":"Allah`ı bırakıp da taptıkları varlıklar, hiçbir şey yaratamazlar. Çünkü onlar kendileri yaratılmışlardır."},{"n":21,"t":"Onlar diri değil, ölüdürler. Ne zaman dirileceklerinin de bilincinde değillerdir."},{"n":22,"t":"Tanrınız tek bir tanrıdır. Ama, âhirete inanmayanların kalpleri inkâr etmektedir. Onlar büyüklük taslarlar."},{"n":23,"t":"Doğrusu Allah, gizlediklerini de açıkladıklarını da bilir. O, büyüklük taslayanları asla sevmez."},{"n":24,"t":"Onlara, “Rabbiniz ne indirdi?” denildiği zaman; “Öncekilerin masallarını” derler."},{"n":25,"t":"Kıyamet gününde kendi günahlarını tam olarak taşımaları ve bilgisizce saptırmakta oldukları kimselerin günahlarından da bir kısmını yüklenmeleri için öyle derler. Bak ki yüklenecekleri şey ne kötüdür!"},{"n":26,"t":"Onlardan öncekiler de peygamberlere hile yapmışlardı. Sonunda Allah da onların binalarını temellerinden söktü, tavan da tepelerine çöktü. Bu azap onlara, fark edemedikleri bir yerden gelmişti."},{"n":27,"t":"“Şüphesiz bugün rezillik ve kötülük kâfirleredir.”"},{"n":28,"t":"“Hayır, Allah, sizin yaptıklarınızı çok iyi bilendir.”"},{"n":29,"t":"O halde, içinde süreli kalacağınız cehennemin kapılarından giriniz! Kibirlenenlerin yeri ne kötüdür!"},{"n":30,"t":"Sakınanlara, “Rabbiniz ne indirdi?” dendiğinde, “iyilik” derler. Bu dünyada iyi davranışlara iyilik vardır. Âhiret yurdu ise daha iyidir. Sakınanların yurdu ne güzeldir!"},{"n":31,"t":"Onlar, içinden ırmaklar akan dâimî mutluluk cennetlerine girerler. Orada diledikleri her şey vardır. İşte Allah, sakınanları böyle ödüllendirir."},{"n":32,"t":"Melekler, iyi insanlar olarak canlarını aldığı kimselere, “Size selâm olsun! Yapmış olduğunuza karşılık cennete giriniz” derler."},{"n":33,"t":"İlle kendilerine meleklerin gelmesini, yahut Rabbinin buyruğunun gelmesini mi bekliyorlar? Onlardan öncekiler de öyle yapmıştı. Allah onlara zulmetmedi, fakat onlar kendi kendilerine zulmediyorlardı."},{"n":34,"t":"Nihayet yaptıklarının kötülükleri onlara ulaştı ve alay ettikleri şey, onları kuşattı."},{"n":35,"t":"Allah`a ortak koşanlar, “Allah dileseydi ne biz ne de atalarımız, O`ndan başka bir şeye tapmazdık ve O`nsuz hiçbir şeyi haram kılmazdık” dediler. Onlardan öncekiler de böyle yapmıştı. Peygamberlere düşen, yalnız açıkça tebliğ etmek değil midir?"},{"n":36,"t":"Andolsun ki biz, “Allah`a kulluk ediniz ve tâğûttan sakınınız!” diye her ümmete bir peygamber gönderdik. Allah onlardan bir kısmını doğru yola iletti. Onlardan bir kısmı da sapıklığı hak ettiler. Yeryüzünde geziniz de görünüz, inkâr edenlerin sonu nasıl olmuştur."},{"n":37,"t":"Rasûlüm, sen onların hidayete ermesine çok düşkünlük göstersen de, bil ki Allah`ın saptırdığı kimseyi kimse hidayete erdiremez. Onların yardımcıları da yoktur."},{"n":38,"t":"“Ölen kimseyi Allah`ın diriltemeyeceği” üzerine bütün güçleriyle Allah`a yemin ettiler. Hayır, Allah buna gerçekten söz vermiştir. Fakat insanların çoğu bilmezler."},{"n":39,"t":"Çünkü, hakkında ayrılığa düştükleri şeyi onlara Allah anlatacak ve inkârcılar da yalancı olduklarını bileceklerdir."},{"n":40,"t":"Bir şeyin olmasını istediğimiz zaman, ona sözümüz sadece “ol!” dememizdir. O da hemen oluşmaya başlar."},{"n":41,"t":"Zulme uğratıldıktan sonra Allah yolunda hicret edenlere gelince, onları dünyada güzel bir şekilde yerleştireceğiz. Eğer bilirlerse, âhiretin ödülü elbette daha büyüktür."},{"n":42,"t":"Onlar sabredenler ve Rabblerine güven bağlayan kimselerdir."},{"n":43,"t":"Senden önce de, kendilerine vahyettiğimiz kişilerden başkasını peygamber olarak göndermedik. Eğer bilmiyorsanız, Kur`ân`ı bilenlere sorunuz!"},{"n":44,"t":"Apaçık mucizelerle ve kitaplarla gönderildiler. Kendilerine indirileni insanlara açıklaman için ve düşünsünler diye, sana da bu Kur`ân`ı indirdik."},{"n":"45-46","t":"Tuzak kuranlar, Allah`ın kendilerini yere geçirmeyeceğinden veya kendilerine bilemeyecekleri bir yerden azabın gelmeyeceğinden veya onlar dönüp dolaşırlarken Allah`ın kendilerini yakalamayacağından emin mi oldular? Onlar Allah`ı âciz bırakacak değillerdir."},{"n":47,"t":"Yoksa Allah`ın kendilerini yavaş yavaş tüketerek cezalandırmayacağından emin mi oldular? Şüphesiz Rabbin affedicidir; merhamet sahibidir."},{"n":48,"t":"Kâfirler Allah`ın yarattığı varlıkları görmüyorlar mı? Onların gölgeleri Allah`ın iradesine boyun eğip kendi içyapılarında hareket edip dönerek Allah`a saygı ile yere kapanmaktadırlar."},{"n":49,"t":"Göklerde bulunanlar, yerdeki canlılar ve bütün melekler, büyüklük taslamadan Allah`a secde ederler."},{"n":50,"t":"Onlar, kendi güçlerinin üstünde olan Rabblerinden korkarlar ve kendilerine ne emrolunursa onu yaparlar."},{"n":51,"t":"“İki tanrı edinmeyiniz! O ancak bir Tanrıdır. O halde yalnız benden korkunuz!”"},{"n":52,"t":"Göklerde ve yerde ne varsa, O`nundur; kalıcı ve sürekli olan din de yalnız O`nundur. “O halde Allah`tan başkasından mı korkuyorsunuz?”"},{"n":53,"t":"Nimet olarak size ulaşan ne varsa, Allah`tandır. Sonra size bir zarar dokunduğu zaman yalnız O`na yalvarırsınız."},{"n":54,"t":"Sonra da sizden o zararı giderdiğinde, içinizden bir grup hemen Rabblerine ortak koşarlar."},{"n":55,"t":"Kendilerine verdiklerimize karşılık nankörlük etmeleri için böyle yaptılar. O halde bir süre daha faydalanınız, fakat yakında hakikati bileceksiniz."},{"n":56,"t":"Kendilerine verdiğimiz rızıktan, ne olduğunu bilmedikleri tanrılarına pay ayırırlar. Allah`a yemin olsun ki, uydurup durduğunuz şeylerden, mutlaka sorguya çekileceksiniz."},{"n":57,"t":"Onlar, kızların Allah`a ait olduğunu iddia ediyorlar. Hâşâ! Allah bundan uzaktır. Beğendikleri de kendilerinin oluyor."},{"n":58,"t":"Onlardan birine kızı olduğu müjdelendiği zaman, öfkesini yutkunarak yüzü kapkara olur."},{"n":59,"t":"Kendisine verilen müjdenin kötülüğünden dolayı kavminden gizlenir. Onu, aşağılık duygusu içinde yanında mı tutsun, yoksa toprağa mı gömsün! Bakınız ki verdikleri hüküm ne kadar kötüdür!"},{"n":60,"t":"Kötü sıfat, âhirete inanmayanlar içindir. En yüce sıfatlar ise Allah`a aittir. Çünkü O, her şeyden üstündür; hikmet sahibidir."},{"n":61,"t":"Eğer Allah, zulümlerinden dolayı insanları hemen cezalandıracak olsaydı, yeryüzünde hiçbir canlı bırakmazdı. Fakat, onları belli bir süreye kadar erteler. Ecelleri geldiği zaman onlar ne bir saat geri kalabilirler ne de öne geçebilirler."},{"n":62,"t":"Hoşlarına gitmeyen şeyleri Allah`a mal ediyorlar. En güzel şeylerin de kendilerine ait olduğunu söylüyorlar. Şüphesiz, onlara ateş vardır ve onlar ateşte terk olunacaklardır."},{"n":63,"t":"Allah`a andolsun ki, senden önceki topluluklara da peygamberler gönderdik. Fakat şeytan onlara işlerini süslü gösterdi. Bugün de onların dostudur. Onlar için elem verici bir azap vardır."},{"n":64,"t":"Biz bu kitâbı sana sadece, hakkında ihtilafa düştükleri şeyi insanlara açıklayasın ve iman eden bir topluma da rehber ve rahmet olsun diye indirdik."},{"n":65,"t":"Allah gökten su indirdi ve onunla ölümünden sonra yeri diriltti. Doğrusu, dinleyen topluma bunda bir ders vardır."},{"n":66,"t":"Şüphesiz sizin için hayvanlarda da büyük bir ders vardır. Karınlarındaki fışkı ile kan arasından gelen, içenlerin boğazından kolayca geçen hâlis bir süt içiriyoruz size."},{"n":67,"t":"Hurma ağacının ve üzümlerin ürünlerinden sarhoşluk veren içecek ve güzel rızık elde edersiniz. Aklını kullanan toplum için bunda bir işaret vardır."},{"n":"68-69","t":"Rabbin bal arısına, “Dağlardan, ağaçlardan ve kurulmuş kovanlardan yuvalar edin, sonra da her türlü üründen ye de, Rabbinin işlek olan yollarından yürü!” diye vahyetti. Karınlarından, insanlara şifa olan türlü türlü renkte içecek çıkar. Düşünen topluma bunda bir ders vardır."},{"n":70,"t":"Sizi Allah yarattı; sonra sizi vefat ettirir. Daha önce bilgili iken hiçbir şeyi bilmez hale gelsin diye, sizden bazı kimseler ömrün en kötü çağına kadar yaşatılacak. Şüphesiz ki Allah her şeyi bilendir; sonsuz kudret sahibidir."},{"n":71,"t":"Allah rızık alanında bir bölümünüzü diğerlerinizden üstün kıldı. Üstün konumdakiler rızıklarını, buyrukları altındaki yoksullarla paylaşmıyorlar ki, herkes eşit geçim düzeyine kavuşsun. Acaba Allah`ın nimetlerini inkar mı ediyorsunuz?"},{"n":72,"t":"Allah size kendi nefislerinizden eşler yarattı; eşlerinizden de sizin için çocuklar ve torunlar verdi ve sizi temiz gıdalarla rızıklandırdı. Onlar hâlâ bâtıla inanıp Allah`ın nimetine nankörlük mü ediyorlar?"},{"n":73,"t":"Müşrikler, Allah`ı bırakıp da kendilerine göklerde ve yerde olan rızıktan hiçbir şey veremeyen ve buna asla güçleri yetmeyen şeylere tapıyorlar."},{"n":74,"t":"Allah`a birtakım benzerler icat etmeyiniz! Çünkü Allah her şeyi bilir, siz ise bilemezsiniz."},{"n":75,"t":"Allah, hiçbir şeye gücü yetmeyen ve başkasının malı olan bir köle ile, kendisine katımızdan verdiğimiz güzel rızıktan gizlice ve açıkça veren kimseyi örnek veriyor. Bunlar hiç eşit olur mu? Övgü Allah`a aittir; fakat çoğu bunu bilmez."},{"n":76,"t":"Biri, hiçbir şeye gücü yetmeyen, efendisine yük olan, bir yere gönderse bir iyilik getiremeyen bir dilsiz; şimdi bu, doğru yolda olarak adâletle iş yapan kimse ile bir olur mu?"},{"n":77,"t":"Göklerin ve yerin gaybı Allah`a aittir. Kıyametin kopması ise, göz açıp kapama gibi veya daha az bir zamandan ibarettir. Şüphesiz ki Allah, her şeye gücü yetendir."},{"n":78,"t":"Siz hiçbir şey bilmezken Allah sizi analarınızın karnından çıkardı; şükredesiniz diye size kulaklar, gözler ve kalpler verdi."},{"n":79,"t":"Göğün boşluğunda emre boyun eğdirilmiş olarak uçuşan kuşları görmediler mi? Onları orada Allah`tan başkası tutamaz. Şüphesiz bunda inanan bir toplum için deliller vardır."},{"n":80,"t":"Allah evlerinizi size bir huzur ve sükün yeri yaptı. Size hayvanların derilerinden yolculuk günlerinizde ve ikamet günlerinizde kolayca taşıyabileceğiniz barınaklar; yünlerinden, tüylerinden ve kıllarından bir süreye kadar kullanabileceğiniz giyimlikler ve geçimlikler var etmiştir."},{"n":81,"t":"Allah, yarattıklarından size gölgeler yapmış, dağlarda barınaklar var etmiş, sizi sıcaktan koruyacak giysiler ve savaşta sizi koruyacak zırhlar yaratmıştır. İslâm`a girip esenlik kazanasınız diye, size olan nimetini böyle tamamlıyor."},{"n":82,"t":"Eğer yüz çevirirlerse, sana, “ancak açıkça bildirmek” düşer."},{"n":83,"t":"Onlar Allah`ın nimetini bilirler, sonra da inkâr ederler. Onların çoğu nankördür."},{"n":84,"t":"Her milletten bir tanık getireceğimiz gün, artık inkâr edenlere özür dileme izni verilmez ve özürleri de dinlenmez."},{"n":85,"t":"Haksızlık edenler azabı gördüklerinde, ne azapları hafifletilir ne de onlara bir süre verilir."},{"n":86,"t":"Allah`a ortak koşanlar, ortaklarını gördükleri zaman, “Ey Rabbimiz! Senden başka yalvardığımız ortaklarımız işte bunlardır” derler. Koştukları ortaklar onlara, “Doğrusu, siz tam yalancısınız” diye laf atarlar."},{"n":87,"t":"O gün, ortak koşanlar Allah`a teslim olurlar ve uydurup durdukları ortaklar ortaklıktan kaybolurlar."},{"n":88,"t":"İnkâr edip de Allah yolundan alıkoyanlar var ya, işte onların yapmakta oldukları bozgunculukları sebebiyle azaplarını kat kat arttıracağız."},{"n":89,"t":"O gün her ümmetin içinden kendilerine birer şâhit göndereceğiz. Seni de hepsinin üzerine şâhit olarak getireceğiz. Ayrıca bu kitabı da sana, her şey için bir açıklama, bir hidayet ve rahmet kaynağı ve Müslümanlar için bir müjde olarak indirdik."},{"n":90,"t":"Gerçek şu ki, Allah adâleti, iyiliği ve akrabaya yardım etmeyi emreder; yüz kızartıcı işleri, fenalığı ve azgınlığı yasaklar. O, düşünüp öğüt alasınız diye size öğüt veriyor."},{"n":91,"t":"Sözleştiğiniz zaman Allah`ın ahdini yerine getiriniz! Yeminleri, Allah`ı kendinize kefil göstererek pekiştirdikten sonra bozmayınız. Doğrusu Allah, yaptığınızı bilir."},{"n":92,"t":"Bir milletin diğer bir milletten daha çok olmasından dolayı, ipliğini iyice eğirip katladıktan sonra örgüsünü bozan kadın gibi, aranızdaki yeminlerinize hile sokarak bozmayınız! Şüphesiz, Allah onunla sizi deniyor ve aranızda anlaşmazlığa düştüğünüz şeyi kıyamet günü elbette size açıklayacaktır."},{"n":93,"t":"Allah dileseydi hepinizi bir tek ümmet yapardı; fakat O, dileyeni saptırır, dileyeni de doğru yola iletir. Yaptıklarınızdan elbette sorgulanacaksınız."},{"n":94,"t":"Birbirinizi aldatmak için yemin etmeyiniz; yoksa sağlam basmış olan ayak sürçebilir ve Allah`ın yolundan alıkoymuş olacağınızdan dolayı da acı azabı tadarsınız. Üstelik büyük bir azaba da uğrarsınız."},{"n":95,"t":"Allah`ın antlaşmasını az bir değere satmayınız! Eğer gerçeği biliyorsanız, Allah`ın katında olan, sizin için çok daha iyidir."},{"n":96,"t":"Sizde olanlar tükenir; ama Allah katında olan tükenmez! Elbette sabırlı davrananlara, yapmakta olduklarının ödülünü en güzeli ile ödeyeceğiz."},{"n":97,"t":"Erkek veya kadın olsun her kim inanmış olarak iyi bir iş yaparsa, onu hoş bir hayatla yaşatırız ve onların ödülünü yaptıklarının en güzeli ile veririz."},{"n":98,"t":"Kur`ân okuduğun zaman, o kovulmuş şeytandan Allah`a sığın!"},{"n":99,"t":"İman edip de yalnız Rabblerine güvenip dayananlar üzerinde şeytanın bir hakimiyeti yoktur."},{"n":100,"t":"Şeytanın hakimiyeti, ancak onu dost edinenlere ve onu Allah`a ortak koşanlaradır."},{"n":101,"t":"“Sen sadece düpedüz bir iftiracısın.” Halbuki Allah ne indirdiğini en iyi bilendir, onların çoğu bilmiyorlar."},{"n":102,"t":"“Kur`ân`ı Kutsal Rûh/Cebrâil, Rabbinin katından, inananların inançlarını pekiştirmek için ve Müslümanlara rehber ve müjde olarak gerçekle indirmiştir.”"},{"n":103,"t":"Andolsun ki biz, onların “Kur`ân`ı ona bir insan öğretiyor” demekte olduklarını biliyoruz. Nisbet etmeye uğraştıkları adamın dili yabancıdır. Oysaki bu Kur`ân apaçık bir Arapça`dır."},{"n":104,"t":"Allah`ın âyetlerine inanmayanlara Allah kılavuzluk etmez. Onlar için acıklı bir azap vardır."},{"n":105,"t":"Allah`ın âyetlerine inanmayanlar, ancak yalan uydurur. İşte onlar yalancıların ta kendileridir."},{"n":106,"t":"Kalbi imanla dolu olduğu halde, zorlananın dışında olan kimse inandıktan sonra Allah`ı inkâr eder ve gönlünü inkârcılığa açarsa, bunlara Allah katında bir öfke vardır ve büyük azap da onlaradır."},{"n":107,"t":"Bu, onların âhirete karşı dünya hayatını tercih etmelerinden ve Allah`ın da inkâr eden toplumu doğru yola getirmemesinden ötürüdür."},{"n":108,"t":"İşte, Allah`ın, gönüllerini, kulaklarını ve gözlerini mühürlediği kimseler bunlardır. Onlar gafillerin ta kendileridir."},{"n":109,"t":"Şüphesiz ki, âhirette kaybedecek olanlar da bunlardır."},{"n":110,"t":"Şüphesiz Rabbin, eziyet edildikten sonra hicret edip ardından da sabrederek cihad edenlerin yardımcısıdır. Bütün bunlardan sonra Rabbin elbette çok affedicidir; merhamet sahibidir."},{"n":111,"t":"O gün, herkes gelip kendi canını kurtarmak için uğraşır. Herkese yaptığının karşılığı eksiksiz ödenir. Onlara asla zulmedilmez."},{"n":112,"t":"Bu ülke güvenli, huzurlu idi; ona rızkı her yerden bol bol gelirdi. Sonra onlar, Allah`ın nimetlerine karşı nankörlük ettiler. Allah da onlara yaptıklarından dolayı açlık sıkıntısını ve korkuyu tattırdı."},{"n":113,"t":"Andolsun ki, onlara kendilerinden peygamber geldi de, onu yalanladılar. Onlar zulmederlerken azap onları yakalayıverdi."},{"n":114,"t":"Artık, Allah`ın size verdiği rızıktan helâl ve temiz olarak yiyiniz! Eğer yalnız Allah`a kulluk/ibadet ediyorsanız, O`nun nimetine şükrediniz!"},{"n":115,"t":"Allah size, sadece ölü hayvanı, kanı, domuz etini ve Allah`tan başkası adına kesilen hayvanı haram kıldı. Ancak kim mecbur kalırsa aşırı gidip ihtiyacının ötesine geçmemek şartıyla, bu yasaklamanın dışındadır. Çünkü Allah affedicidir; merhamet sahibidir."},{"n":116,"t":"Dillerinizin uydurduğu yalana dayanarak, “Bu helâldir, şu da haramdır” demeyin! Çünkü Allah`a karşı yalan uydurmuş olursunuz. Şüphesiz Allah`a karşı yalan uyduranlar kurtuluşa eremezler."},{"n":117,"t":"Kazandıkları pek az bir menfaattir. Halbuki onlar için elem verici bir azap vardır."},{"n":118,"t":"Sana anlattıklarımızı daha önce Yahudilere de haram kılmıştık. Biz onlara haksızlık etmedik; aksine onlar kendi kendilerine zulmediyorlardı."},{"n":119,"t":"Sonra şüphesiz Rabbin, câhillik sebebiyle kötülük yapan, bunun ardından tövbe edip durumunu düzeltenleri bağışlayacaktır. Çünkü onlar tövbe ettikten sonra uslandılar. Bütün bunlardan sonra Rabbin elbette affedicidir; merhamet sahibidir."},{"n":120,"t":"Gerçek şu ki, İbrâhim, Hakk`a yönelen, Allah`a itaat eden bir önder idi. Allah`a ortak koşanlardan değildi."},{"n":121,"t":"Allah`ın nimetlerine şükredici idi. Çünkü Allah, onu seçmiş ve doğru yola iletmişti."},{"n":122,"t":"Ona dünyada güzellik verdik. Elbette o, âhirette de iyilerdendir."},{"n":123,"t":"Sonra da sana, “Doğru yola yönelerek İbrâhim`in yoluna uy! O müşriklerden değildi” diye vahyettik."},{"n":124,"t":"Cumartesi tatili, ancak onda ihtilaf edenlere farz kılınmıştı. Kıyamet günü Rabbin, muhakkak onların ihtilâfa düştükleri şey hakkında aralarında hüküm verecektir."},{"n":125,"t":"Sen, Rabbinin yoluna hikmet ve güzel öğütle çağır ve onlarla en güzel şekilde mücâdele et! Rabbin, kendi yolundan sapanları en iyi bilendir ve O, hidayete erenleri de çok iyi bilir."},{"n":126,"t":"Eğer ceza verecekseniz, size yapılan işkencenin dengi ile ceza veriniz. Fakat sabrederseniz, elbette o, sabredenler için daha hayırlıdır."},{"n":127,"t":"Sabret! Senin sabrın da ancak Allah`ın yardımı iledir. Onlardan dolayı kederlenme; kurmakta oldukları tuzaktan kaygı duyma!"},{"n":128,"t":"Çünkü Allah, takvâ sahipleriyle, yani güzel amel işlemekte devamlı olanlarla beraberdir."}],[{"n":1,"t":"Bir gece, kendisine âyetlerimizden/kâinatın işleyiş kanunlarından bir kısmını gösterelim diye kulunu Mescid-i Harâm`dan, çevresini mübarek kıldığımız Mescid-i Aksâ`ya yürüten Allah, noksan sıfatlardan uzaktır. O, işitendir; görendir."},{"n":2,"t":"Mûsâ`ya kitâbı verdik ve onu İsrâiloğulları`na, “Benden başka bir vekil edinmeyin” diye rehber yaptık."},{"n":3,"t":"Ey Nûh ile beraber gemide taşıyarak kurtardıklarımızın soyundan olanlar! Doğrusu Nûh, çok şükreden biri idi."},{"n":4,"t":"Kitapta İsrâiloğulları`na, “Andolsun, yeryüzünde iki defa bozgunculuk yaptınız ve büyüklendikçe büyüklendiniz” diye bildirmiştik."},{"n":5,"t":"Birincisinin vakti geldiği zaman, pek güçlü olan kullarımızı üzerinize saldık ve evlerin arasında dolaştılar. Bu yerine gelmiş bir vaad idi."},{"n":6,"t":"Sonra sizi onlara yeniden üstün getirdik. Servet ve çocuklarla gücünüzü arttırdık, sayınızı daha da çoğalttık."},{"n":7,"t":"İyi davranırsanız, kendinize iyi davranmış olursunuz; eğer kötü davranırsanız kendinize kötü davranmış olursunuz. Artık diğer cezalandırma zamanı geldiğinde, yüzünüzü kara etsinler, daha önce girdikleri gibi yine mescide girsinler; ele geçirdiklerini yerle bir edecek kimselerin tekrar gelmesi olağandır."},{"n":8,"t":"Rabbinizin size merhamet etmesi ihtimal dahilindedir; fakat siz yine bozgunculuğa dönerseniz, biz de sizi yine cezalandırırız. Biz cehennemi kâfirler için bir hapishane yaptık."},{"n":"9-10","t":"Şüphesiz bu Kur`ân, dosdoğru olanı gösterir ve iyi işler yapan müminlere büyük ödül olduğunu ve âhirete inanmayanlara da acı bir azap hazırladığımızı bildirir."},{"n":11,"t":"İnsan, iyiliği istediğini zannederek kötülüğü ister. Çünkü insan çok acelecidir."},{"n":12,"t":"Biz, geceyi ve gündüzü iki delil yaptık; sonra gecenin karanlığını silip gündüzün aydınlığını gösterici yaptık ki, Rabbinizden bir lütuf isteyesiniz, yılların sayısını ve hesabını bilesiniz. Biz her şeyi açık açık anlattık."},{"n":13,"t":"Her insanın amelini boynuna doladık yani mahşere amelleri boynuna takılı olarak gelecektir. İnsan için kıyamet gününde, açılmış olarak önüne konacak bir kitap çıkarırız."},{"n":14,"t":"“Kitabını oku! Bugün sana hesap sorucu olarak kendi öz benliğin yeter!”"},{"n":15,"t":"Her kim doğru yolu izlemeyi seçerse, bunu kendi iyiliği için yapmış olacaktır. Her kim de yoldan saparsa, bu kendi kötülüğüne olacaktır; kimse kimsenin suçunu taşıyacak değildir. Ayrıca, biz bir peygamber göndermedikçe azap etmeyiz."},{"n":16,"t":"Bir toplumu yok etmek istediğimizde, onların refaha gömülmüş seçkinlerine son uyarılarımızı iletiriz ve onlar eğer günahkârca yaşamaya devam ederlerse cezalandırıcı yargı artık o toplum için kaçınılmaz olur ve biz de onu darmadağın ederiz."},{"n":17,"t":"Nûh`tan bu yana biz böyle nicelerini yok ettik. Çünkü kullarının günahlarını bütünüyle görüp haberdar olmakta senin Rabbin gibisi yoktur."},{"n":18,"t":"Kim bu geçici dünyayı dilerse ona, yani dilediğimiz kimseye dilediğimiz kadarını dünyada hemen veririz, sonra da onu, kınanmış ve kovulmuş olarak gireceği cehenneme sokarız."},{"n":19,"t":"Kim de âhireti diler ve bir mümin olarak ona yaraşır bir çaba ile çalışırsa, işte bunların çalışmaları kabul edilir."},{"n":20,"t":"Hepsine, bunlara da ötekilere de Rabbinin ihsanından veririz. Rabbinin ihsanı kısıtlanmış değildir."},{"n":21,"t":"Baksana, biz insanların kimini kiminden nasıl üstün kılmışız! Elbette ki âhiret, derece ve üstünlük farkları bakımından daha büyüktür."},{"n":22,"t":"“Allah`la beraber bir başka tanrı edinme! Sonra yerilmiş ve yardımcısız olarak oturup kalırsın.”"},{"n":23,"t":"Çünkü Rabbin, başkasına değil, yalnızca O`na kulluk etmenizi, anne babaya iyi davranmanızı emretti. Onlardan biri veya her ikisi senin yanında yaşlanırlarsa kendilerine öf bile deme; onları azarlama; ikisine de güzel söz söyle!"},{"n":24,"t":"Onlara alçak gönüllüce ve esirgeyerek kol kanat geresin ve “Ey Rabbim!” diyesin, “Onları beni küçükken sevgi ve şefkatle besleyip büyüttükleri gibi, sen de onlara merhamet eyle!”"},{"n":25,"t":"Rabbiniz sizin içinizdekini çok iyi bilir. Eğer siz iyi olursanız, şunu biliniz ki Allah, kötülükten yüz çevirerek tövbeye yönelenleri bağışlayıcıdır."},{"n":26,"t":"Bir de akrabaya, yoksula ve yolcuya/çaresiz kalana hakkını ver! Gereksiz yere de saçıp savurma!"},{"n":27,"t":"Zira böylesine saçıp savuranlar şeytanların dostlarıdır. Şeytan ise Rabbine karşı çok nankördür."},{"n":28,"t":"Eğer sen kendin de Rabbinin katından ihtiyaç duyduğun bir lütfu arama çabası içinde olduğun için onlara ilgisiz kalmak zorunda isen, o zaman hiç değilse onlara işleri kolaylaştırıcı söz söyle!"},{"n":29,"t":"Elini boynuna bağlayıp cimri kesilme ve büsbütün de açıp tutumsuz olma! Yoksa pişman olur, açıkta kalırsın."},{"n":30,"t":"Şüphesiz senin Rabbin, rızkı dilediğine bolca verendir ve dilediğine de ölçülü verendir. Kullarının durumunu, bütün açıklığıyla görerek haberdar olan da O`dur."},{"n":31,"t":"Fakirliğe düşme endişesi ile evlatlarınızı öldürmeyiniz! Onların da sizin de rızkınızı veren Biz’iz. Şüphesiz ki onları öldürmek büyük bir suçtur."},{"n":32,"t":"Zinaya yaklaşmayın. Çünkü o, şübhesiz bir hayaasızlıkdı, kötü bir yoldur."},{"n":33,"t":"Haklı bir sebep olmadıkça Allah`ın muhterem kıldığı cana kıymayınız! Bir kimse haksız yere öldürülürse, onun velisine yetki verdik. Ancak bu veli kısasta ileri gitmesin! Ona verdiğimiz yetkiyle, alacağı yardımı almıştır."},{"n":34,"t":"Yetimin malına da, -kendisi (ergenlik çağına erinceye kadar) yapacağınız en uygun ve olumlu tasarruflar dışında- yaklaşmayın. Yine, verdiğiniz her (meşru) söze sadık kalın! Şüphesiz söz veren herkes bundan dolayı hesaba çekilecektir."},{"n":35,"t":"Ölçtüğünüz zaman ölçüyü tam tutunuz; tartıyı da doğru teraziyle yapınız! Böylesi, daha iyi ve sonuç olarak da daha güzel olacaktır."},{"n":36,"t":"Bilmediğin şeyin ardına düşme! Çünkü işitme duyusu, görme duyusu ve gönül, bunların hepsi bundan sorguya çekilecektir."},{"n":37,"t":"Yeryüzünde böbürlenerek dolaşma! Çünkü sen, ne yeri yarabilir ne de boyca dağlara ulaşabilirsin."},{"n":38,"t":"Bütün bunların doğurduğu kötülük, Rabbinin katında asla hoş karşılanmamaktadır."},{"n":39,"t":"İşte bunlar, Rabbinin sana vahyettiği hikmetlerdendir. Allah ile birlikte başka tanrı edinme! Sonra kınanmış ve uzaklaştırılmış olarak cehenneme atılırsın."},{"n":40,"t":"Rabbiniz erkek çocukları size özel kıldı da, kendisine melekleri kız çocuğu mu edindi? Gerçekten, siz çok büyük söz söylüyorsunuz?"},{"n":41,"t":"Andolsun, bu Kur`ân`da düşünüp anlamaları için bunları açık açık anlatıyoruz; fakat bu, sadece onların nefretini arttırıyor."},{"n":42,"t":"“Onların dedikleri gibi Allah`la beraber tanrılar olsaydı, o takdirde kâinatın hükümranlığı kudretinde olan Allah`a ulaşmak için çareler arayacaklardı."},{"n":43,"t":"Her şeyden yüce olan Allah, onların söylediklerinden uzaktır."},{"n":44,"t":"Yedi gök ile yer ve onların içinde yer alan her şey O`nun noksan sıfatlardan uzak olduğunu hatırlatmaktadır. Ayrıca kâinatta olan her şey yüce Allah`ın övgüye layık olduğunu da hatırlatmaktadır. Ne var ki siz, onların tesbihini/ bu hatırlatmasını anlayamıyorsunuz. O, yumuşak davranandır; bağışlayıcıdır."},{"n":45,"t":"Kur`ân okuduğun zaman, senin ile âhirete inanmayanlar arasına gizli bir engel koyarız."},{"n":46,"t":"Âhirete inanmayanlar Kur`ân`ı anlarlar diye kalplerine örtüler ve kulaklarına da ağırlık koyduk. Çünkü, Kur`ân`da Rabbini yalnız andığın zaman, onlar canları sıkılarak arkalarını dönerler."},{"n":47,"t":"Seni dinlerlerken niye dinlediklerini de, gizli toplantılarında haksızlık yapanların, “Siz ancak büyülenmiş bir adama uyuyorsunuz” dediklerini de biliyoruz."},{"n":48,"t":"Baksana, senin için ne türlü benzetmeyi yaptılar! Bu yüzden öylesine saptılar ki, artık doğru yolu bulamayacaklardır."},{"n":49,"t":"“Sahi biz, bir kemik yığını ve kokuşmuş bir toprak olmuş iken, yepyeni bir yaratılış ile diritileceğiz, öyle mi?”"},{"n":50,"t":"“Yakın olsa gerek.”"},{"n":51,"t":"“Yakın olsa gerek.”"},{"n":52,"t":"Allah sizi çağıracağı gün, kendisine hamd ederek çağrısına uyarsınız ve çok az kaldığınızı sanırsınız."},{"n":53,"t":"Kullarıma söyle! Sözün dosdoğru olanını söylesinler. Sonra şeytan aralarını bozar. Çünkü şeytan, insanın apaçık düşmanıdır."},{"n":54,"t":"Rabbiniz, sizi en iyi bilendir. Dilerse size merhamet eder; dilerse sizi cezalandırır. Biz, seni onların üzerine bir vekil olarak göndermedik."},{"n":55,"t":"Rabbin, göklerde ve yerde olan herkesi en iyi bilendir. Gerçekten biz, peygamberlerin kimini kiminden üstün kıldık. Dâvûd`a da Zebûr`u verdik."},{"n":56,"t":"“Allah`ı bırakıp da ilâh olduğunu ileri sürdüklerinize yalvarınız! Ne var ki onlar, sizin sıkıntınızı ne uzaklaştırabilirler ne de değiştirebilirler.”"},{"n":57,"t":"İşte, bunların yalvardıklarının kendileri, Rabblerine nasıl daha yakın olacaklarının yolunu ararlar; O`nun rahmetini umar ve azabından korkarlar. Doğrusu, Rabbinin azabı çekinmeye değer."},{"n":58,"t":"Ne kadar ülke varsa hepsini kıyamet gününden önce toplumsal bozulmadan dolayı ya helâk edecek veya en çetin bir şekilde onlara azap edeceğiz. Bu, kitapta yazılıdır."},{"n":59,"t":"Mucizeler göndermekten bizi alıkoyan husus, öncekilerin mucizeleri yalanlamış olmasıdır. Nitekim Semûd kavmine gözle görülebilen bir mucize olarak dişi deveyi vermiştik de, onu haksız yere öldürmüşlerdi. Oysa Biz, mucizeleri yalnız korkutmak için göndeririz."},{"n":60,"t":"Hani sana, “Rabbin, insanları kuşatmıştır” demiştik. Sana gösterdiğimiz görüntüyü ve Kur`ân`da lanetlenen ağacı sadece insanları sınamak için meydana getirdik. Biz onları korkutuyoruz da, bu onlara büyük bir azgınlıktan başka bir şey sağlamıyor."},{"n":61,"t":"“Ben, çamurdan yarattığına secde eder miyim?” dedi."},{"n":62,"t":"“Şu, benden üstün kıldığını gördün mü? Andolsun eğer beni kıyamet gününe kadar ertelersen, onun zürriyetini, pek azı hariç, kökünden koparıp sürükleyeceğim” dedi."},{"n":63,"t":"“Defol git! Onlardan kim sana uyarsa, cezanız cehennemdir, ne mükemmel bir ceza!”"},{"n":64,"t":"“Onlardan gücünün yettiği kimseleri davetinle şaşırt; süvarilerinle ve yayalarınla onların üzerine yaygarayı bas; mallarda ve evlatlarda onlara ortak ol, kendilerine vaadlerde bulun!” Şeytan, insanlara aldatmadan başka bir şey vadetmez."},{"n":65,"t":"“Benim kullarıma gelince; senin onlara gücün yetmez. Vekil olarak Rabbin yeter.”"},{"n":66,"t":"Bol nimetinden elde edesiniz diye Rabbiniz sizin için denizde gemiler yüzdürür. Doğrusu O, size acır."},{"n":67,"t":"Denizde bir sıkıntıya düştüğünüz zaman, Allah`tan başka yalvardıklarınız ortadan kaybolur. Ama O sizi karaya çıkarıp kurtarınca da, yüz çevirirsiniz. Zaten insan çok nankördür."},{"n":68,"t":"O`nun karada da sizi yere batırmasından veya başınıza taş yağdırmayacağından güvende misiniz? Sonra kendinize bir koruyucu da bulamazsınız."},{"n":69,"t":"Ya da sizi tekrar denize döndürerek, üzerinize bir kasırga gönderip, inkâr etmenizden dolayı sizi suda boğmayacağından güvende misiniz? Sonra bundan dolayı bizi arayıp soracak bir destekçi bulamazsınız."},{"n":70,"t":"Andolsun, biz Âdemoğulları`nı şan ve şeref sahibi kıldık. Onları karada ve denizde taşıdık; temiz besinlerle onları rızıklandırdık. Yine onları yarattıklarımızın birçoğundan cidden üstün kıldık."},{"n":71,"t":"Her insan topluluğunu önderleriyle birlikte çağıracağımız o günde, kimin amel defteri sağından verilirse onlar, en küçük bir haksızlığa uğramamış olarak amel defterlerini okuyacaklar."},{"n":72,"t":"Bu dünyada manen kör olan kimse âhirette de kördür; üstelik iyice yolunu şaşırmıştır."},{"n":73,"t":"Bize karşı başka bir şey uydurman için, az kalsın sana vahyettiğimiz şeyden seni saptıracaklardı. O zaman seni dost edineceklerdi."},{"n":74,"t":"Eğer seni sebatkâr kılmasaydık yani engellemeseydik, gerçekten neredeyse onlara birazcık meyledecektin."},{"n":75,"t":"O zaman, hiç şüphesiz sana hayatın ve ölümün sıkıntılarını kat kat tattırırdık; sonra bize karşı kendin için bir yardımcı da bulamazdın!"},{"n":76,"t":"Yine onlar seni yurdundan çıkarmak için neredeyse dünyayı başına dar edecekler. O takdirde senin ardından kendileri de fazla kalamazlar."},{"n":77,"t":"Senden önce gönderdiğimiz peygamberler hakkındaki kanun da budur. Bizim kanunumuzda hiçbir değişiklik bulamazsın."},{"n":78,"t":"Güneşin sarkmasından gecenin kararmasına kadar namaz kıl ve sabahın Kur`ân`ını da unutma. Çünkü sabahın Kur`ân`ı görülecek şeydir."},{"n":79,"t":"Gecenin bir kısmından uyanarak, sana mahsus bir artı değer/nâfile olmak üzere, namaz kıl! Böylece Rabbinin seni, övülmüş bir makama ulaştırması umulur."},{"n":80,"t":"“Ey Rabbim! Gireceğim her işe doğruluk ve içtenlik üzere girmemi, bitireceğim her işten de doğruluk ve içtenlik göstererek çıkmamı sağla! Bana katından yardımcı bir güç ver!”"},{"n":81,"t":"“Hak geldi, bâtıl gitti; zaten bâtıl yok olup gitmeye mahkûmdur.”"},{"n":82,"t":"Biz Kur`ân`dan, müminlere gönüllere şifâ ve rahmet olan şeyler indiriyoruz. Ama bu, zâlimlere ziyan arttırmaktan başka bir katkıda bulunmaz."},{"n":83,"t":"İnsana nimet verdiğimiz zaman yüz çevirip yan çizer; ona bir zarar ziyan dokunacak olsa iyice karamsarlığa düşer."},{"n":84,"t":"“Herkes, kendi mizaç ve meşrebine göre iş yapar. Bu durumda kimin doğru bir yol tuttuğunu Rabbiniz en iyi bilendir.”"},{"n":85,"t":"“Rûh, Rabbimin emrindendir. Size ancak az bir bilgi verilmiştir.”"},{"n":86,"t":"Andolsun, dilesek sana vahyettiğimizi ortadan kaldırırız; sonra bu durumda sen de bize karşı hiçbir koruyucu bulamazsın."},{"n":87,"t":"Ancak Rabbinin rahmeti sayesinde vahiy kesilmedi. Çünkü O`nun sana büyük lütfu vardır."},{"n":88,"t":"“Andolsun, bu Kur`ân`ın bir benzerini ortaya koymak üzere insanlar ve cinler bir araya gelseler, birbirlerine destek de olsalar, benzerini getiremezler.”"},{"n":89,"t":"Muhakkak ki biz, bu Kur`ân`da insanlara her türlü misali çeşitli şekillerde anlattık. Yine de insanların çoğu inkârcılıktan vazgeçmedi."},{"n":90,"t":"Onlar, “Sen” dediler, “Bizim için yerden bir kaynak fışkırtmadıkça sana asla inanmayacağız.”"},{"n":91,"t":"“Veya senin bir hurma bahçen ve üzüm bağın olmalı; öyle ki içlerinden gürül gürül ırmaklar akıtmalısın.”"},{"n":92,"t":"“Yahut, iddia ettiğin gibi üzerimize gökten parçalar yağdırmalısın veya Allah`ı ve melekleri gözümüzün önüne getirmelisin.”"},{"n":93,"t":"“Rabbimi tenzih ederim. Ben, sadece beşer bir peygamberim.”"},{"n":94,"t":"Zaten, kendilerine hidayet rehberi geldiğinde, insanların buna inanmalarını sırf, “Allah, peygamber olarak bir beşer mi gönderdi?” demeleri engellemiştir."},{"n":95,"t":"“Eğer yeryüzünde yerleşmiş, gezip dolaşanlar melekler olsaydı, elbette onlara gökten peygamber olarak bir melek gönderirdik.”"},{"n":96,"t":"“Benimle sizin aranızda gerçek şâhit olarak Allah yeterlidir. Zira O, kullarını bilip görmektedir.”"},{"n":97,"t":"Allah kimi doğru yola iletirse, işte doğru yolu bulan odur; kimi de şaşırtırsa, artık onlara Allah`tan başka dost bulamazsın. Kıyamet gününde onları kör, dilsiz ve sağır bir halde yüzükoyun haşr ederiz. Onların varacağı ve kalacağı yer, ateşi sönmeye yüz tutunca onun alevini arttıracağımız cehennemdir."},{"n":98,"t":"İşte onların bu cezası, âyetlerimizi inkâr etmiş olmalarından ve “Biz kemik ve ufalanmış toprak olduğumuz zaman da mı, yeniden yaratılarak dirileceğiz?” demelerindendir."},{"n":99,"t":"Düşünmezler mi ki, gökleri ve yeri yaratmış olan Allah`ın, kendilerinin benzerini de yaratmaya gücü yeter. Allah onlara şüphe götürmeyen bir süre belirledi. Öyleyken, haksızlık yapanlar inkârcılıktan vazgeçmezler."},{"n":100,"t":"“Rabbimin rahmet hazinelerine siz sahip olsaydınız, tükenir korkusuyla yine de cimrilik ederdiniz. Aslında insan pek cimridir.”"},{"n":101,"t":"Andolsun, Mûsâ`ya apaçık dokuz mu‘cize verdik. İsrâiloğullarına sor! Kendilerine Mûsâ geldiği zaman, Firavun, “Ey Mûsâ! Ben, seni büyülenmiş sanıyorum” dedi."},{"n":102,"t":"Mûsâ da, “Andolsun, göklerin ve yerin Rabbinin göz açıcı belgeleri olarak bunları indirdiğini biliyorsundur. Doğrusu, Ey Firavun! Senin yok olacağını sanıyorum” dedi."},{"n":103,"t":"Firavun onları ülkeden çıkarmak istedi. Biz de onu ve beraberindekilerin hepsini suda boğduk."},{"n":104,"t":"Bundan sonra İsrâiloğulları`na, “Bu yerde siz oturunuz! Âhiret vaadi gerçekleşince, hepinizi karmakarışık bir topluluk olarak getiririz” dedik."},{"n":105,"t":"Biz Kur`ân`ı hak olarak indirdik; o da hakkı getirdi. Seni yalnız müjdeci ve uyarıcı olarak gönderdik."},{"n":106,"t":"Biz onu Kur`ân olarak, insanlara ağır ağır okuman için, bölüm bölüm ayırdık ve peyderpey indirdik."},{"n":107,"t":"“Kur`ân`a ister inanın, ister inanmayın; şu bir gerçek ki, bundan önce kendilerine ilim verilenlere okunduğunda, derhal yüz üstü secdeye kapanırlar.”"},{"n":108,"t":"`Rabbimizi tenzih ve tesbih ederiz. Rabbimizin va’di mutlaka yerine getirilir.` de."},{"n":109,"t":"Ağlayarak yüzüstü yere kapanırlar. Kur`ân onların saygısını arttırır."},{"n":110,"t":"“İster Allah deyiniz, ister Rahmân deyiniz! Hangisini deseniz olur. Çünkü en güzel isimler, O`na aittir. Namazında yüksek sesle okuma; onda sesini fazla da kısma; ikisinin arası bir yol tut!”"},{"n":111,"t":"“Övgü, çocuk edinmemiş olan, egemenliğinde ortağı bulunmayan, âcizlikten kurtaracak bir yardımcıya ihtiyacı olmayan Allah`a aittir. O`nu gereği gibi yücelt!”"}],[{"n":1,"t":"Bütün övgüler, kuluna kitabı indiren ve ona hiçbir eğrilik koymayan Allah`a aittir."},{"n":"2-4","t":"Onu dosdoğru bir kitap olarak indirdi ki Allah`ın katından gelecek şiddetli azaba karşı uyarsın; iyi işler yapan müminlere de, kendileri için, içinde süreli bulunacakları güzel bir ödül olduğunu müjdelesin ve “Allah çocuk edindi” diyenleri de uyarsın."},{"n":5,"t":"Bu hususta ne kendilerinin ne de atalarının bir bilgisi vardır. Ağızlarından ne büyük söz çıkıyor! Onlar yalandan başka bir şey söylemiyorlar."},{"n":6,"t":"Herhalde sen, onlar bu söze inanmıyorlar diye üzüntüden kendini helâk edeceksin."},{"n":7,"t":"Biz yeryüzündeki şeyleri, kendisine süs olsun diye yarattık ki, onların hangisinin daha güzel amel yaptığını deneyelim."},{"n":8,"t":"Biz, elbette yerin üzerindekileri kupkuru bir toprak yapacağız."},{"n":9,"t":"Yoksa sen, sadece Kehf ve Rakîm sahiplerinin, bizim şaşılacak âyetlerimizden olduğunu mu sandın?"},{"n":10,"t":"O gençler mağaraya sığınmışlar ve “Rabbimiz, bize katından rahmet ver ve bize şu durumumuzdan bir kurtuluş yolu hazırla!” demişlerdir."},{"n":11,"t":"Bunun üzerine biz de o mağarada onların kulaklarına nice yıllar perde koyduk/onları uykuya daldırdık."},{"n":12,"t":"Sonra da iki gruptan hangisinin kaldıkları müddeti daha iyi hesap edeceğini görelim diye onları uyandırdık."},{"n":13,"t":"Biz sana onların başından geçenleri gerçek olarak anlatıyoruz. Gerçekten onlar, Rabblerine inanmış gençlerdi. Biz de onların hidayetini arttırdık."},{"n":14,"t":"“Bizim Rabbimiz, göklerin ve yerin Rabbidir. Biz O`ndan başkasına tanrı demeyiz. Yoksa saçma sapan konuşmuş oluruz.”"},{"n":15,"t":"“Şu bizim toplumumuz Allah`tan başka tanrılar edindiler. Bâri bu tanrılar konusunda açık bir delil getirseler. Öyle ise, Allah hakkında yalan uydurandan daha zâlim var mı?”"},{"n":16,"t":"“Madem ki siz onlardan ve onların Allah`ın dışında tapmakta oldukları varlıklardan uzaklaştınız, o halde mağaraya sığının ki, Rabbiniz size rahmetini yaysın ve işinizde sizin için fayda ve kolaylık sağlasın.”"},{"n":17,"t":"Ve yıllarca güneşin doğarken, onların mağarasını sağ taraftan yalayıp geçtiğini, batarken de onlara dokunmadan sol yandan geçip gittiğini ve onların mağaranın genişce bir bölümünde bulunduğunu görürdün, Allah`ın ayetlerinden biriydi bu. Allah kime yol gösterirse, doğru yolu bulan odur, kimi de saptırırsa, artık ona kesin olarak doğru yolu gösterecek bir dost bulamazsın."},{"n":18,"t":"Mağaradakiler uykuda iken sen onları uyanık sanırdın. Biz onları sağa ve sola döndürüyorduk. Köpekleri de dirseklerini eşiğe uzatmıştı. Onları görmüş olsaydın, geri dönüp onlardan kaçardın ve için korku ile dolardı."},{"n":19,"t":"Birbirine sorsunlar diye onları böylece uyandırdık. İçlerinden biri, “Ne kadar kaldınız?” dedi. “Bir gün veya bir günden az kaldık” dediler. “Ne kadar kaldığınızı Rabbiniz daha iyi bilir. Birinizi şu para ile şehre gönderin de, yiyeceklerin en iyisine baksın ve size yiyecek getirsin, nazik davransın ve sakın sizi kimseye duyurmasın!”"},{"n":20,"t":"“Doğrusu, eğer onlar sizi ele geçirirse ya taşlayarak öldürürler veya kendi yollarına döndürürler ve bu durumda asla kurtulamazsınız” dedi."},{"n":21,"t":"Böylece Allah`ın vaadinin gerçek olduğunu ve kıyametin kopacağından şüphe edilemeyeceğini bilmeleri için, insanların onları bulmalarını sağladık. Çünkü, halk onların durumunu aralarında tartışıyorlardı. “Onların adına bir bina yapın” diyorlardı. Oysa, onları en iyi Rabbleri bilir. Tartışmayı kazananlar, “Onlar adına elbette bir mescit yapacağız” dediler."},{"n":22,"t":"“Onların sayısını en iyi Rabbim bilir. Onlar hakkında bilgisi olan çok azdır. Onlar hakkında bu yüzeysel anlatılanların dışında kimseyle tartışma ve onlar hakkında başkalarından bilgi isteme!”"},{"n":"23-24","t":"Allah`ın dilemesine bağlamadıkça, hiçbir şey için, “Bunu yarın yapacağım” deme! Bunu unuttuğun takdirde Allah`ı an ve “Umarım Rabbim beni doğruya bundan daha yakın olan bir yolla iletir” de!"},{"n":25,"t":"Onlar mağaralarında üç yüzyıl ve buna ilâveten dokuz yıl kalmışlardır."},{"n":26,"t":"“Ne kadar kaldıklarını Allah daha iyi bilir. Göklerin ve yerin gizlisi O`na aittir. O ne kadar güzel görür ve ne kadar güzel işitir! Onların, O`ndan başka bir yöneticisi yoktur. O, kendi hükümranlığına kimseyi ortak etmez."},{"n":27,"t":"Rabbinin kitabından sana vahyolunanı oku! O`nun kelimelerini değiştirecek kimse yoktur. O`ndan başka bir sığınak da bulamazsın."},{"n":28,"t":"Sabah akşam Rabblerine O`nun rızasını dileyerek dua edenlerle birlikte candan sabret! Dünya hayatının süsünü arayarak gözlerini onlardan ayırma! Kalbini bizi anmaktan gafil kıldığımız, kötü arzularına uymuş ve işi gücü aşırılık olan kimseye boyun eğme!"},{"n":29,"t":"“Hak, Rabbinizdendir. Dileyen inansın, dileyen inkâr etsin. Biz, zâlimlere öyle bir cehennem hazırladık ki, onun duvarları kendilerini çepeçevre kuşatmıştır. Susuzluktan imdat dileyecek olsalar imdatlarına, erimiş maden gibi yüzleri haşlayan bir su ile cevap verilir. Ne fena bir içecek ve ne kötü bir kalma yeri!”"},{"n":30,"t":"İman edip de iyi davranışlarda bulunanlar bilmelidirler ki biz, güzel iş yapanların ödülünü vermemezlik etmeyiz."},{"n":31,"t":"İşte onlara, içinde ırmaklar akan adn cennetleri vardır. Onlar ‘Adn cennetlerinde tahtlar üzerinde kurularak orada altın bileziklerle bezenecekler; ince ve kalın ipeklerden yeşil elbiseler giyecekler. Ne güzel karşılık ve ne güzel bir kalma yeri!"},{"n":32,"t":"Onlara şu iki adamı örnek alarak anlat! Birine iki üzüm bağı vermiş, bu bağların etrafını hurmalarla donatmış, aralarında da ekinler bitirmiştik."},{"n":33,"t":"İki bağın ikisi de yemişlerini vermiş, hiçbirini eksik bırakmamıştı. İkisinin arasından bir de ırmak fışkırtmıştık."},{"n":34,"t":"“Ben servetçe senden daha zenginim, insan sayısı bakımından da senden daha güçlüyüm.”"},{"n":35,"t":"“Bu bahçenin batacağını hiç sanmam.”"},{"n":36,"t":"Hoş, ben Son Saat`in bir gün gerçekleşeceğini de düşünemiyorum ya! Fakat Rabbime döndürülecek olsam bile, sonuçta bundan daha iyisini bulacağımdan eminim.\""},{"n":37,"t":"“Seni topraktan, sonra da meniden yaratan, sonra da seni adam kılığına koyanı mı inkâr ediyorsun?”"},{"n":38,"t":"“Fakat, O Allah, benim Rabbimdir. Rabbime kimseyi ortak koşmam.”"},{"n":39,"t":"“Bağına girdiğinde, her ne kadar sen beni mal ve çocuk bakımından daha az görüyorsan da, ‘Allah dilemiş! Her güç Allah iledir` demeli değil miydin?”"},{"n":40,"t":"Umulur ki Rabbim bana senin bahçenden daha iyisini verir ve seninkinin üzerine de gökten hesap görecek bir yıldırım (afet) gönderir de, orası kaygan, kuru bir yer olur."},{"n":41,"t":"Yahut suyu dibe çekilir de bir daha onu asla bulamazsın."},{"n":42,"t":"Derken onun serveti kuşatılıp yok edildi. Böylece, bağı uğruna yaptığı masraflardan ötürü ellerini ovuşturup kaldı. Bağın çardakları yere çökmüştü. “Âh, keşke, Rabbime hiçbir ortak koşmamış olsaydım!” diyordu."},{"n":43,"t":"Kendisine Allah`tan başka yardım edecek destekçileri olmadığı gibi, kendi kendini kurtaracak güçte de değildi."},{"n":44,"t":"İşte burada yardım ve dostluk, Hak olan Allah`a mahsustur. Ödülü en iyi olan O, en güzel sonucu veren yine O`dur."},{"n":45,"t":"“Dünya hayatı, gökten indirdiğimiz bir su gibidir ki, bu su sayesinde yeryüzünün bitkisi birbirine karışmış; arkasından rüzgârın savurduğu çerçöp haline gelmiştir. Allah, her şey üzerinde iktidar sahibidir.”"},{"n":46,"t":"Servet ve çocuklar dünya hayatının süsüdür; ölümsüz olan iyi işler ise Rabbinin nezdinde hem sevapça daha iyi hem de ümit bağlamaya daha lâyıktır."},{"n":47,"t":"Dağları yürüttüğümüz gün, yeryüzünü dümdüz görürsün. Hiçbirini bırakmaksızın insanların hepsini bir araya getiririz."},{"n":48,"t":"İnsanlar, sıra sıra Rabblerinin huzuruna çıkarılırlar. Andolsun ki, sizi ilk defa yarattığımız gibi bize geldiniz. Fakat, size bir buluşma sözü vermediğimizi sanmıştınız, değil mi?"},{"n":49,"t":"Kitap ortaya konunca, suçluların orada yazılı bulunanlardan korktuklarını görürsün. Onlar, “Vay halimize! Ne oluyor bu kitaba! Küçük büyük hiçbir şey bırakmadan hepsini sayıyor?” derler. Yaptıklarını hazır bulurlar. Ama Rabbin hiç kimseye haksızlık etmez."},{"n":50,"t":"Hani biz meleklere, “Âdem`e secde ediniz” demiştik. İblîs hariç olmak üzere, onlar hemen secde ettiler. İblîs cinlerdendi; Rabbinin emrinden dışarı çıktı. “Şimdi siz, beni bırakıp da onu ve onun zürriyetini dost mu ediniyorsunuz? Oysa onlar sizin düşmanınızdır. Zâlimler için bu ne fenâ bir takastır!”"},{"n":51,"t":"Ben İblîs`i ve soyunu ne göklerin ve yerin yaratılışına ne de kendilerinin yaratılışına şâhit tuttum. Ben, yoldan çıkanları yardımcı edinecek değilim."},{"n":52,"t":"Allah, “Bana ortak olduklarını sandıklarınızı çağırınız!” dediği gün, onları çağırırlar, fakat hiçbiri çağrılarına cevap veremez. Aralarına bir uçurum koyarız."},{"n":53,"t":"Suçlular ateşi görecekler ve oraya düşmekte olduklarını anlayacaklar; ondan kurtuluş yolu da bulamayacaklardır."},{"n":54,"t":"Andolsun ki biz, bu Kur`ân`da insanlara her örneği açıkladık. Ama insan tartışmaya her şeyden daha düşkündür."},{"n":55,"t":"Kendilerine hidayet geldiğinde insanları iman etmekten ve Rabblerinden af dilemekten alıkoyan şey, sadece öncekilerin başına gelenlerin kendi başlarına da gelmesini, yahut azabın göz göre göre kendilerine gelmesini beklemeleridir."},{"n":56,"t":"Biz peygamberleri, sadece müjdeleyici ve uyarıcılar olarak göndeririz. Kâfir olanlar ise hakkı yerinden kaydırıp ortadan kaldırmak için bâtıl uğruna mücâdele verirler. Âyetlerimizi ve kendilerine yapılan tehditleri de alay konusu edinirler."},{"n":57,"t":"Rabbinin âyetleri kendisine hatırlatıldığında onlardan yüz çevirip, önceden yaptığı günahtan oluşan amelleri unutandan daha zâlim kim vardır? Bu nedenle Biz âyetleri anlamamaları için kalplerine örtüler, duymamaları için kulaklarına da ağırlıklar koyduk. Sen onları doğru yola çağırsan da asla doğru yola gelmezler."},{"n":58,"t":"Rabbin çok bağışlayıcı ve merhamet sahibidir. Eğer onları, yaptıklarından dolayı cezalandıracak olsaydı, onlara azabı hemen indiriverirdi. Fakat onlar için kaçıp kurtulamayacakları bir vakit belirlenmiştir."},{"n":59,"t":"İşte, zulmettiklerinden dolayı helâk ettiğimiz ve helâkleri için bir süre tayin ettiğimiz şehirler."},{"n":60,"t":"Mûsâ`nın, genç adamına, “Ya iki denizin birleştiği yere ulaşacağım ya da uzun bir süre yürüyeceğim” dediği ânı hatırla!"},{"n":61,"t":"Onlar, iki denizin birleştiği yere ulaşınca, balıklarını unuttular. Derken balık da yolunu bulup denize dalarak gözden kayboldu."},{"n":62,"t":"İkisi de orayı geçip gittiklerinde Mûsâ, genç adamına, “Kuşluk yemeğimizi getir. Bu yolculuğumuzdan dolayı iyice yorulduk” dedi."},{"n":63,"t":"Genç adamı, “Gördün mü, kayaya sığındığımızda, balığı orada unuttum. Onu hatırlamamı bana şeytan unutturdu. Balık, şaşılacak şekilde denizde yolunu bulup gitti” dedi."},{"n":64,"t":"Mûsâ, “İşte arzu ettiğimiz de buydu” dedi. Hemen geldikleri yoldan izlerini takip ederek geri döndüler."},{"n":65,"t":"Orada katımızdan kendisine rahmet verdiğimiz ve yine katımızdan kendisine ilim öğrettiğimiz kullarımızdan birini buldular."},{"n":66,"t":"Mûsâ ona, “Sana öğretilmiş olan yol gösterici ilimden bana öğretmen için seninle gelebilir miyim?” dedi."},{"n":67,"t":"O kul, “Sen benimle birlikte olmaya sabredemezsin.”"},{"n":68,"t":"“Hakkında hiçbir bilgin olmayan şeylere sen nasıl sabredeceksin?” dedi."},{"n":69,"t":"Mûsâ, “İnşâallâh benim sabırlı olduğumu ve sana hiçbir işte karşı gelmeyeceğimi görürsün” dedi."},{"n":70,"t":"“Eğer bana uyacaksan, hakkında sana açıklama yapıncaya kadar bana hiçbir şey sormayacaksın” dedi."},{"n":71,"t":"Bunun üzerine yürüdüler. Nihayet gemiye bindikleri zaman o, gemiyi deliverdi. Mûsâ, “Gemidekileri boğmak için mi gemiyi deldin? Gerçekten sen çok tehlikeli bir iş yaptın!” dedi."},{"n":72,"t":"O kul, “Sen benimle beraber bulunmaya dayanamazsın, dememiş miydim?” dedi."},{"n":73,"t":"Mûsâ, “Unuttuğum şeyden dolayı beni kınama ve bana bu işimden dolayı bir güçlük çıkarma” dedi."},{"n":74,"t":"Yine yürüdüler. Nihayet bir erkek çocuğuna rastladılar. O kul, hemen onu öldürdü. Mûsâ, “Bir can karşılığı olmadan temiz bir çocuğa kıydın ha? Doğrusu sen, çirkin bir iş yaptın!” dedi."},{"n":75,"t":"O kul, “Ben sana, sen benimle beraber bulunmaya dayanamazsın, dememiş miydim?” dedi."},{"n":76,"t":"“Eğer bundan sonra sana bir şey sorarsam, artık bana arkadaş olma, benden sana özür ulaştı; o zaman benden ayrılabilirsin.”"},{"n":77,"t":"Yine yürüdüler. Nihayet bir şehir halkına varıp onlardan yemek istediler. Şehir halkı onları misafir etmekten kaçındı. Derken orada yıkılmak üzere bulunan bir duvarla karşılaştılar. O kul hemen onu doğrulttu. Mûsâ, “Dileseydin, elbet buna karşı bir ücret alırdın” dedi."},{"n":78,"t":"“İşte bu, artık ayrılmamızın sebebidir. Şimdi sana, sabredemediğin şeylerin iç yüzünü haber vereceğim.”"},{"n":79,"t":"“O gemi, denizde çalışan birtakım yoksul kimselere aitti. Ona hasar vermek istedim. Çünkü arkasında her sağlam gemiyi zorla gasp eden bir kral vardı.”"},{"n":80,"t":"“O çocuk ise, onun anne ve babası inanmış kimselerdi. Eğer çocuk yaşarsa onları azdırmasından ve inkâra sürüklemesinden korktuk.”"},{"n":81,"t":"“Rabblerinin onlara, ondan daha iyisini ve kendilerine karşı daha merhametli bir çocuk vermesini istedik.”"},{"n":82,"t":"“Duvara gelince o da, şehirdeki iki yetim çocuğa aitti. Duvarın altında onlara ait bir hazine vardı. Babaları da iyi bir kimse idi. Rabbin onların ergenlik çağına ulaşıp da hazinelerini çıkarmalarını, kendi katından bir rahmet olarak istedi. Ben, bunları kendiliğimden yapmadım. İşte bu anlattıklarım senin sabredemediğin şeylerin yorumudur.”"},{"n":83,"t":"“Size ondan biraz bahsedeceğim.”"},{"n":84,"t":"Şüphesiz, biz, ona yeryüzünde imkan sağladık ve kendisine her şeye ulaşacağı bilgiyi verdik."},{"n":85,"t":"O da bir yol tutup gitti."},{"n":86,"t":"Nihayet güneşin battığı yere varınca, güneşi kopkoyu bir suda batıyormuş gibi gördü. Orada bir topluluğa rastladı. “Ey Zülkarneyn! Onları ister cezalandır, ister onlara karşı iyi davran!” dedik."},{"n":87,"t":"“Haksızlık edeni cezalandıracağız; sonra da o, Rabbine döndürülecek. Rabbi de onu görülmemiş bir ceza ile cezalandıracaktır.”"},{"n":88,"t":"Ancak inanıp yararlı iş yapana gelince, onun için güzel ödül vardır. Biz ona kendi emirlerimizden kolay olanı söyleyeceğiz."},{"n":89,"t":"Sonra doğru sebep ve vesilelere, meşrû araçlara başvurarak başka bir hedefe yöneldi."},{"n":90,"t":"Sonunda güneşin doğduğu yere varınca, güneşi, kendilerine güneşten başka bir örtü vermediğimiz bir topluluğun üzerine doğuyor buldu."},{"n":91,"t":"İşte onun durumu böyledir. Onun bilgi olarak sahip olduğu her şeyi biz biliriz."},{"n":92,"t":"Sonra yine bir yol tutup gitti."},{"n":93,"t":"Sonunda iki set arasına varınca, bunların ötesinde, neredeyse hiçbir sözü anlamayan bir topluluk buldu."},{"n":94,"t":"“Ey Zülkarneyn! Şüphesiz Ye`cüc ve Me`cüc burada bozgunculuk yapmaktadırlar. Bizimle onların arasına bir set yapman için sana bir ödeme yapabilir miyiz?”"},{"n":95,"t":"“Rabbimin bana verdiği imkan sizinkinden daha iyidir. Bana bedenen yardım ediniz de sizinle onların arasına sağlam bir set yapayım.”"},{"n":96,"t":"“Bana demir kütleleri getirin!” Kütleler iki dağın arasını doldurunca, “Körükleyin!” dedi. Demirler akkor haline gelince, “Bana erimiş bakır getirin de üzerine dökeyim” dedi."},{"n":97,"t":"Ye`cüc ve Me`cüc onu ne aşmaya ne de onda bir delik açmaya güç yetirebildiler."},{"n":98,"t":"Zülkarneyn, “Bu, Rabbimden bir rahmettir. Rabbimin vaadi gelince onu yerle bir eder. Rabbimin vaadi bir gerçektir” dedi."},{"n":99,"t":"O gün biz onları, birbirine çarparak çalkalanır bir halde bırakmışızdır. Sûr`a da üfürülmüş, böylece onları bütünüyle bir araya getirmişizdir."},{"n":"100-101","t":"Dünyada iken gözleri beni hatırlatan her şeye karşı perdeli, kulak vermeye de dayanamayan kâfirleri, o gün cehennemle yüz yüze getireceğiz."},{"n":102,"t":"Kâfirler, beni bırakıp da kullarımı dostlar edineceklerini mi sandılar? Biz cehennemi kâfirler için bir konak olarak hazırladık."},{"n":103,"t":"“Size, işler bakımından en çok ziyana uğrayanları bildirelim mi?”"},{"n":104,"t":"Onlar, iyi işler yaptıklarını sandıkları halde, dünya hayatında çabaları boşa giden kimselerdir."},{"n":105,"t":"İşte onlar, Rabblerinin âyetlerini ve O`na kavuşmayı inkâr eden, bu yüzden amelleri boşa giden kimselerdir. Biz onlar için kıyamet gününde hiçbir ölçü/değerlendirmeye tabi tutmayacağız."},{"n":106,"t":"İşte, inkâr ettikleri, âyetlerimi ve peygamberlerimi alaya aldıkları için onların cezası cehennemdir."},{"n":107,"t":"İman edip iyi amel yapanlara gelince, onlar için makam olarak Firdevs cennetleri vardır."},{"n":108,"t":"Orada uzun süreli kalacaklardır. Oradan hiç ayrılmak istemezler."},{"n":109,"t":"“Rabbimin kelimelerini yazmak için denizler mürekkep olsa, bir o kadarını daha ilâve etsek, Rabbimin kelimeleri tükenmeden denizler tükenirdi.”"},{"n":110,"t":"“Ben de sadece sizin gibi bir insanım. Bana sizin tanrınızın tek bir Tanrı olduğu vahyolunuyor. Kim Rabbine kavuşmak isterse iyi amel yapsın ve kullukta hiçbir kimseyi Rabbine ortak koşmasın.”"}],[{"n":1,"t":"Kâf, hâ, yâ, ‘ayn, sâd."},{"n":2,"t":"Bu, Rabbinin, kulu Zekeriyyâ`ya olan rahmetini hatırlatmadır."},{"n":3,"t":"Hani o, gizli bir sesle Rabbine yalvarmıştı:"},{"n":4,"t":"“Ey Rabbim,” dedi, “Vücudumda kemiklerim zayıfladı, saçım başım ağardı. Ey Rabbim, sana ettiğim dua sayesinde hiç bedbaht olmadım.”"},{"n":"5-6","t":"“Doğrusu ben, arkamdan iş başına gelecek olan yakınlarımdan endişe ediyorum. Karım da kısırdır. Tarafından bana şahsiyetli/velî bir çocuk ver ki bana ve Ya`kub oğullarına mirasçı olsun. Ey Rabbim, onu beğendiğin bir insan yap!”"},{"n":7,"t":"“Ey Zekeriyyâ! Biz sana öyle bir oğul müjdeliyoruz ki, onun adı Yahyâ`dır. Daha önce ona kimseyi adaş yapmadık.”"},{"n":8,"t":"Zekeriyyâ, “Ey Rabbim! Benim nasıl bir çocuğum olur? Oysa benim hanımım kısır, ben de son derece yaşlandım” dedi."},{"n":9,"t":"O çocuğu yaratmak benim için kolaydır. Nitekim bundan önce de seni yaratmıştım. Oysa sen hiç yoktun.”"},{"n":10,"t":"“İşaretin sapasağlam olduğun halde üç gece insanlarla konuşamamandır” buyurdu."},{"n":11,"t":"Bunun üzerine Zekeriyyâ, mabedden kavminin karşısına çıkarak onlara, “Sabah-akşam tesbîhte bulunun” diye işaret verdi."},{"n":12,"t":"Allah, “Ey Yahyâ! Kitaba kuvvetle sarıl!” dedi. Biz ona, henüz çocuk iken kitabı anlama kabiliyetini verdik."},{"n":13,"t":"Ona kalp yumuşaklığı ve temizliği verdik. O, çok sakınan birisi idi."},{"n":14,"t":"Ana babasına çok iyi davranırdı; isyankar bir zorba değildi."},{"n":15,"t":"Doğduğu gün, öleceği gün ve diri olarak kabirden kalkacağı gün, ona selâm/rahmet olsun!"},{"n":16,"t":"Kitapta Meryem`i de an! O, ailesinden ayrılmış ve doğu yönünde bir yere çekilmişti."},{"n":17,"t":"Onlarla kendi arasına bir perde çekmişti. Derken, biz ona ruhumuzu Cebrail`i gönderdik de, ona düzgün bir insan şeklinde göründü."},{"n":18,"t":"“Eğer saygılı biri isen, senden Rahmân`a sığınırım.”"},{"n":19,"t":"Rûh/melek, “Ben, ancak Rabbinin sana gönderdiği bir elçiyim, sana temiz bir oğlan bağışlamak için geldim” dedi."},{"n":20,"t":"Meryem, “Bana bir insan dokunmamışken, ben kötü bir kadın da değilim, nasıl oğlum olabilir?” dedi."},{"n":21,"t":"“Bu, bana kolaydır. Çünkü biz, onu insanlara bir delil ve kendimizden bir rahmet kılacağız. Bu, karara bağlanmış bir hükümdür.”"},{"n":22,"t":"Meryem ona hamile kaldı. Bunun üzerine onunla uzak bir yere çekildi."},{"n":23,"t":"Doğum sancısı onu bir hurma ağacına dayanmaya sevketti. “Âh, keşke” dedi; “Bundan önce ölseydim de unutulup gitseydim.”"},{"n":24,"t":"“Tasalanma! Rabbin senin alt yanında bir su arkı vücuda getirmiştir.”"},{"n":25,"t":"“Hurma ağacının gövdesini kendine doğru silkele ki, üzerine taze, olgun hurma dökülsün.”"},{"n":26,"t":"Ben çok merhametli olan Allah`a oruç adadım; artık bugün hiçbir insanla konuşmayacağım.”"},{"n":27,"t":"“Ey Meryem! Hakikaten sen iğrenç bir şey yaptın!”"},{"n":28,"t":"“Ey Hârûn`un kız kardeşi! Senin baban kötü bir insan değildi; annen de iffetsiz değildi.”"},{"n":29,"t":"Bunun üzerine Meryem çocuğu gösterdi. “Biz beşikteki bir bebek ile nasıl konuşuruz?” dediler."},{"n":30,"t":"“Ben Allah`ın kuluyum. O, bana Kitâb`ı verdi ve beni peygamber yaptı.”"},{"n":31,"t":"“Nerede olursam olayım O, beni mübarek kıldı; yaşadığım sürece bana namazı ve zekâtı emretti.”"},{"n":32,"t":"“Beni anneme saygılı kıldı; beni bedbaht bir zorba yapmadı.”"},{"n":33,"t":"“Doğduğum gün, öleceğim gün ve diri olarak kabirden kaldırılacağım gün selâm banadır.”"},{"n":34,"t":"İşte budur Meryem oğlu İsa, onların şüpheye düştükleri şey hakkında, gerçek söz budur."},{"n":35,"t":"Çocuk edinmek Allah`a yaraşmaz. O, yücedir. Bir işe hükmederse, ona “ol” der, o da oluşmaya başlar."},{"n":36,"t":"Doğrusu Allah, benim de Rabbim, sizin de Rabbinizdir. O`na kulluk ediniz. Doğru yol budur."},{"n":37,"t":"Sonra gruplar kendi aralarında ayrılığa düştüler. Büyük günü görecek olduğu zaman da vay o kâfirlerin haline!"},{"n":38,"t":"Bize gelecekleri gün, ne güzel işitecekler ve ne güzel görecekler! Fakat, haksızlık yapanlar o gün apaçık bir şaşkınlık içindedirler."},{"n":39,"t":"Sen onları pişmanlık günü hakkında uyar. Çünkü onlar gafletin içine dalmış oldukları halde ve henüz iman etmemişken iş olup bitmiştir."},{"n":40,"t":"Yeryüzüne ve onun üzerindekilere ancak biz vâris oluruz ve onlar ancak bize döndürülürler."},{"n":41,"t":"Kitapta bir de İbrâhim`i an! Gerçek şu ki o, özü-sözü doğru bir peygamber idi."},{"n":42,"t":"“Babacığım! İşitmeyen, görmeyen ve sana bir faydası olmayan şeylere niçin tapıyorsun?”"},{"n":43,"t":"“Ey babacığım! Bana, senin hiç haberdar olmadığın bir bilgi ulaştı. Öyleyse buna uy ki seni dosdoğru bir yola götüreyim.”"},{"n":44,"t":"“Ey babacığım! Şeytana kulluk etme! Çünkü şeytan Rahmân olan Allah`a isyan etmiştir.”"},{"n":45,"t":"“Ey babacığım! Ben senin başına Rahmân olan Allah katından bir azabın çökmesinden korkuyorum. O azap başına geldiği zaman, şeytanın dostu olursun.”"},{"n":46,"t":"Babası, “Ey İbrâhim! Sen benim tanrılarımdan yüz mü çeviriyorsun?” dedi. “Eğer vazgeçmezsen andolsun seni taşlarım! Uzun bir zaman benden uzak dur!”"},{"n":47,"t":"İbrâhim, “Selâm sana” dedi. “Rabbimden senin için af dileyeceğim. Çünkü O, bana karşı çok lütufkârdır.”"},{"n":48,"t":"“Sizden de, Allah`ın dışında taptığınız şeylerden de uzaklaşıyor ve Rabbime yalvarıyorum. Umulur ki, Rabbime dua etmemle bedbaht olmam.”"},{"n":49,"t":"Nihayet İbrâhim, onlardan ve Allah`tan başka taptıkları şeylerden uzaklaşıp bir tarafa çekildiğinde, biz ona İshak ve Ya‘kûb`u bağışladık ve her birini peygamber yaptık."},{"n":50,"t":"Onlara rahmetimizden bağışta bulunduk, kendilerine haklı ve yüksek bir şöhret nasip ettik."},{"n":51,"t":"Kitapta Mûsâ`yı da an! Gerçekten o ihlâs sahibi idi ve hem rasûl hem de nebî idi."},{"n":52,"t":"Ona Tûr dağının sağ tarafından seslendik ve onu fısıldaşırcasına kendimize yaklaştırdık."},{"n":53,"t":"Rahmetimizin bir sonucu olarak ona kardeşi Hârûn`u da bir peygamber olarak bahşettik."},{"n":54,"t":"Kitapta İsmâil`i de an!. Gerçekten o, sözüne sâdıktı. Rasûl ve nebî idi."},{"n":55,"t":"Ailesine/halkına namazı ve zekâtı emrederdi. Rabbi katında da hoşnutluk kazanmış bir kimse idi."},{"n":56,"t":"Kitapta İdrîs`i de an.! Gerçekten o, pek doğru bir insan, bir peygamberdi."},{"n":57,"t":"Onu yüce bir makama yüceltmiştik."},{"n":58,"t":"İşte bunlar, Allah`ın kendilerine nimetler verdiği peygamberlerden, Âdem`in soyundan, Nûh ile birlikte taşıdıklarımızdan, İbrâhim ve İsrâil`in/Yakup`un soyundan doğruya ulaştırdığımız ve peygamber olarak seçtiğimiz kimselerdendir. Onlara, çok merhametli olan Allah`ın âyetleri okunduğunda ağlayarak secdeye kapanırlardı."},{"n":59,"t":"Sonra bunların ardından namazı kılmayan ve nefislerine uyan bir nesil geldi. Bunlar, elbette cehennem çukuruna atılacaklardır."},{"n":60,"t":"Ancak, tövbe edip, inanıp yararlı iş yapanlar hariç. Bunlar cennete girecekler ve hiçbir haksızlığa uğramayacaklardır."},{"n":61,"t":"Rahmân`ın kullarına vaad ettiği, görmedikleri adn cennetlerine gireceklerdir. Şüphesiz Allah`ın sözü kesindir."},{"n":62,"t":"Orada boş söz değil, hoş söz/selâm duyarlar ve orada, sabah akşam kendilerine ait rızıkları vardır."},{"n":63,"t":"Kullarımızdan takvâ sahibi kimselere verdiğimiz cennet işte budur."},{"n":64,"t":"“Biz ancak Rabbinin emri ile ineriz. Önümüzde, arkamızda ve bunlar arasında olan her şey O`na aittir. Senin Rabbin unutkan değildir.”"},{"n":65,"t":"Allah, göklerin, yerin ve ikisi arasındaki her şeyin Rabbidir. Şu halde O`na kulluk et; O`na kulluk etmek için sabırlı olunuz. O`nun bir benzeri olduğunu biliyor musun?"},{"n":66,"t":"“Öldüğüm zaman sahiden diri olarak çıkarılacak mıyım?”"},{"n":67,"t":"İnsan düşünmez mi ki, daha önce hiçbir şey olmadığı halde biz kendisini yaratmışızdır?"},{"n":68,"t":"Öyle ise, Rabbine andolsun ki, elbette onları şeytanlarla birlikte mahşerde toplayacağız; sonra onları diz üstü çökmüş vaziyette cehennemin çevresinde hazır bulunduracağız."},{"n":69,"t":"Sonra her milletten, Rahmân olan Allah`a en çok âsi olanlar hangileri ise onları çekip ayıracağız."},{"n":70,"t":"Sonra, orayı boylamaya daha çok lâyık olanları elbette biz en iyi biliriz."},{"n":71,"t":"Ey tekrar dirilişi inkâr edenler! İçinizden oraya uğramayacak hiçbir kimse yoktur. Bu, Rabbin için kesinleşmiş bir hükümdür."},{"n":72,"t":"Sonra biz, Allah`tan sakınanları cehennemden uzak tutarız; zâlimleri de diz üstü çökmüş olarak orada bırakırız."},{"n":73,"t":"“Bu iki insan topluluğundan, konum olarak hangisi daha üstün ve güçlü, meclis ve topluluk bakımından hangisi daha güzeldir?” deyip duruyorlar."},{"n":74,"t":"Oysa, biz onlardan önce gelip geçen, onlardan daha güçlü ve dış görünüş olarak onlardan daha üstün olan nice nesilleri helâk ettik."},{"n":75,"t":"“Kim sapıklık içinde ise, Rahmân ona uzun bir süre tanısın. Sonunda onlar uyarıldıkları azabı veya kıyamet saatini görünce, o zaman kimlerin yerinin daha kötü ve taraftarlarının daha zayıf olduğunu öğreneceklerdir.”"},{"n":76,"t":"Allah, doğru yolda gidenlerin hidayetini arttırır. Kalıcı olan iyi işler, Rabbinin katında hem ödül bakımından daha iyi, hem de sonuç olarak daha hayırlıdır."},{"n":77,"t":"Âyetlerimizi inkâr eden ve “Muhakkak sûrette bana mal ve evlat verilecek” diyen adamı gördün mü?"},{"n":78,"t":"Gaybın bilgisi mi önüne açıldı, yoksa rahmeti bol olan Allah`dan kesin söz mü aldı?"},{"n":79,"t":"Kesinlikle hayır! Biz onun söylediklerini yazacağız ve azabını uzattıkça uzatacağız."},{"n":80,"t":"Onun dediğine biz vâris oluruz, kendisi de bize yapayalnız gelir."},{"n":81,"t":"Onlar kendilerine bir itibar ve kuvvet olsun diye Allah`tan başka tanrılar edindiler."},{"n":82,"t":"Hayır. O düzmece ilahlar, müşriklerin kendilerine yönelik tapınmalarını reddedecekler ve onlara karşı çıkacaklardır."},{"n":83,"t":"Görmedin mi? Biz, kâfirlerin üzerine kendilerini isyankârlığa sevk eden şeytanları gönderdik."},{"n":84,"t":"Öyle ise onlar hakkında acele etme! Biz onlar için teker teker sayıyoruz."},{"n":"85-86","t":"Takvâ sahiplerini Rahmân`ın huzurunda, O`na gelmiş konuklar olarak topladığımız gün, suçluları suya götürür gibi cehenneme süreriz."},{"n":87,"t":"O gün, Rahmân`ın katında bir söz almamış olandan başkası asla şefaatte bulunamayacaktır."},{"n":88,"t":"“Rahmân çocuk edindi” dediler."},{"n":89,"t":"Gerçekten siz, pek çirkin bir şey ortaya attınız."},{"n":"90-91","t":"Rahmân`a çocuk isnadında bulunmaları yüzünden, neredeyse gökler çatlayacak, yer yarılacak, dağlar yıkılıp düşecektir."},{"n":92,"t":"Halbuki çocuk edinmek Rahmân`ın şânına yakışmaz."},{"n":93,"t":"Göklerde ve yerde olan herkes, istisnasız birer kul olarak Rahmân`a gelecektir."},{"n":94,"t":"O, bunların hepsini kuşatmış ve sayılarını tespit etmiştir."},{"n":95,"t":"Bunların hepsi de kıyamet gününde O`nun huzuruna tek başına gelecektir."},{"n":96,"t":"İman edip iyi amellerde bulunanlara gelince, Allah onlar için bir sevgi yaratacaktır."},{"n":97,"t":"Biz Kur`ân`ı, sadece Allah`tan sakınanları müjdeleyesin ve şiddetle karşı çıkan bir topluluğu uyarasın diye, senin dilinle kolaylaştırdık."},{"n":98,"t":"Çünkü onlardan önce nice nesilleri yok ettik. Şimdi sen, onlardan herhangi birinden bir varlık işareti hissedebiliyor veya onlara ait cılız bir ses işitebiliyor musun?"}],[{"n":1,"t":"Tâ, hâ."},{"n":"2-3","t":"Biz, Kur`ân`ı sana sıkıntıya düşesin diye değil, Allah`a saygılı olana bir öğüt olsun diye indirdik."},{"n":4,"t":"Kur`ân, yeri ve yüksek gökleri yaratan tarafından indirilmiştir."},{"n":5,"t":"Rahmân, hükümranlık tahtına kurulmuştur."},{"n":6,"t":"Göklerde, yerde ve ikisi arasında bulunan şeyler ile toprağın altında olanlar, hep O`nundur."},{"n":7,"t":"Eğer sen sözü açıktan söylersen, şüphesiz Allah gizli olanı, gizlinin gizlisini de bilir."},{"n":8,"t":"Allah`tan başka tanrı yoktur; en güzel isimler O`nundur."},{"n":9,"t":"Mûsâ`nın olgusunun haberi sana ulaştı mı?"},{"n":10,"t":"Hani o, bir ateş görmüştü de, ailesine/toplumuna, “Durun! Ben bir ateş gördüm, ya ondan size bir kor getiririm ya da ateşin yanında bir rehber bulurum” demişti."},{"n":11,"t":"Mûsâ ateşin yanına gelince, “Ey Mûsâ!” diye seslenildi."},{"n":12,"t":"\"Benim, Ben! Senin Rabbin! Şimdi ayakkabılarını çıkar! Çünkü sen iki kez kutsal kılınmış vadidesin!"},{"n":13,"t":"Ben seni seçtim. Artık vahyolunanları dinle!"},{"n":14,"t":"Şüphesiz ben Allah`ım; benden başka tanrı yoktur. Bana kulluk et, beni anmak için namaz kıl!"},{"n":15,"t":"Herkese uğraştığının karşılığı gösterilsin diye, zamanını neredeyse kendimden bile gizli tutacağım kıyamet mutlaka gelecektir."},{"n":16,"t":"`Kıyamet gününe iman etmeyen, şahsî arzu ve ihtiraslarına uyan kimseler sakın seni ondan, Kıyamete inanmaktan alıkoymasın. Sonra helâk olursun.`"},{"n":17,"t":"“Ey Mûsâ! Sağ elindeki nedir?” diye soruldu."},{"n":18,"t":"Mûsâ, “O benim değneğimdir; ona dayanırım, onunla davarlarıma yaprak silkelerim, daha birçok işte faydalanırım” dedi."},{"n":19,"t":"Allah, “Yere at onu, ey Mûsâ!” dedi."},{"n":20,"t":"Mûsâ onu hemen yere attı. Bir de ne görsün, hızla sürünen bir yılana dönüştü."},{"n":21,"t":"Allah, “Al onu! Korkma! Biz onu şimdi ilk haline sokacağız” dedi."},{"n":22,"t":"“Bir de elini koltuğunun altına sok ki, bir başka mucize olmak üzere o, kusursuz ve lekesiz beyazlıkta çıksın.”"},{"n":23,"t":"“Ta ki, sana en büyük âyetlerimizden bazılarını gösterelim.”"},{"n":24,"t":"“Firavun`a git! Çünkü o iyice azdı.”"},{"n":25,"t":"Mûsâ, “Rabbim!” dedi. “Yüreğime genişlik ver.”"},{"n":26,"t":"“İşimi bana kolaylaştır.”"},{"n":"27-28","t":"“Dilimden bağı çöz ki sözümü anlasınlar.”"},{"n":29,"t":"“Bana ailemden bir de yardımcı ver.”"},{"n":30,"t":"“Kardeşim Hârûn`u.”"},{"n":"31-32","t":"“Onun sayesinde arkamı kuvvetlendir ve onu işime ortak kıl.”"},{"n":"33-34","t":"“Böylece seni gereği gibi noksan sıfatlardan uzak tutalım ve gereği gibi analım.”"},{"n":35,"t":"“Şüphesiz sen, bizi görmektesin.”"},{"n":36,"t":"Allah, “Ey Mûsâ! İstediğin sana verildi” dedi."},{"n":37,"t":"“Andolsun biz sana bir defa daha lütufta bulunmuştuk.”"},{"n":38,"t":"“Bir zaman, vahyedilecek şeyi annene vahy etmiştik.”"},{"n":39,"t":"Mûsâ`yı sandığa koy, suya at; su onu sahile bıraksın; onu benim de düşmanım, onun da düşmanı olan biri alacaktır. Gözümün önünde yetiştirilmen için senin üzerine tarafımdan bir sevgi attım."},{"n":40,"t":"Kız kardeşin gidip, “Ona bakacak birini size göstereyim mi?” diyordu. Böylece seni annene geri verdik ki gözü aydın olsun, üzülmesin. Sen, bir de adam öldürmüştün; o zaman da seni tasadan kurtarmış ve seni iyice denemiştik. Medyen halkı arasında yıllarca kaldın. Sonra takdir ettiğimiz bir vakitte bize geldin, ey Mûsâ!"},{"n":41,"t":"Seni kendim için yetiştirdim."},{"n":42,"t":"“Sen ve kardeşin, âyetlerimizi götürün, beni anmakta gevşek davranmayın!”"},{"n":43,"t":"“Firavun`a gidin! Doğrusu o azmıştır.”"},{"n":44,"t":"“Ona yumuşak söz söyleyin, belki düşünür veya saygı duyar.”"},{"n":45,"t":"«Rabbimiz, biz gerçekten, onun bize karşı `taşkın bir tutum takınmasından` ya da `azgın davranmasından` korkmaktayız.»"},{"n":46,"t":"Yüce Allah, “Korkmayın, çünkü ben, sizinle beraberim; işitir ve görürüm.”"},{"n":47,"t":"Doğrusu, biz senin Rabbinin peygamberleriyiz. İsrâiloğullarını bizimle beraber gönder; onlara bir eziyet etme! Rabbinden sana bir âyet getirdik. Selam/esenlik doğru yolda gidene olsun.”"},{"n":48,"t":"“Doğrusu bize, yalanlayıp sırt çevirene azap edileceği vahyolundu.”"},{"n":49,"t":"Firavun, “Ey Mûsâ! Sizin Rabbiniz de kimmiş!” dedi."},{"n":50,"t":"Mûsâ, “Bizim Rabbimiz, her şeye yaratılışını veren, sonra ona doğru yolu gösterendir” dedi."},{"n":51,"t":"Firavun, “Öyleyse önceki nesillerin durumu nedir?” dedi."},{"n":52,"t":"Mûsâ, “Onların bilgisi Rabbimin katında bir kitaptadır. Rabbim yanılmaz ve unutmaz” dedi."},{"n":53,"t":"Allah, yeri size beşik yapan ve onda size yollar açan, gökten de su indirendir. Biz o suyla çeşitli bitkilerden çiftler çıkardık."},{"n":54,"t":"Yiyiniz; hayvanlarınızı otlatınız. Şüphesiz bunda akıl sahipleri için işaretler vardır."},{"n":55,"t":"Sizi topraktan yarattık; yine sizi oraya döndüreceğiz ve bir defa daha sizi oradan çıkaracağız."},{"n":56,"t":"Andolsun biz, Firavun`a bütün delillerimizi gösterdik; yine de yalanladı, kabul etmemekte diretti."},{"n":57,"t":"“Bizi yaptığın büyü ile yurdumuzdan çıkarasın diye mi geldin, ey Mûsâ?”"},{"n":58,"t":"“Biz de kesinlikle sana benzeri bir büyü getireceğiz. Bizim de sizin de anlaşacağımız uygun bir yerde buluşmamız için bir vakit belirle!” dediler."},{"n":59,"t":"Mûsâ, “Buluşma vaktiniz, bayram günü olsun, insanlar kuşluk vaktinde toplansınlar” dedi."},{"n":60,"t":"Bunun üzerine Firavun dönüp gitti. Büyücüleri toplayıp geldi."},{"n":61,"t":"Mûsâ büyücülere, “Size yazıklar olsun! Allah`a karşı yalan uydurmayınız. Çünkü Allah, sizi azapla helâk eder. Şüphesiz kim Allah`a iftira etmişse kaybetmiştir” dedi."},{"n":62,"t":"Büyücüler yapacakları işlerini aralarında tartıştılar ve birbirleriyle gizlice konuştular."},{"n":63,"t":"Onlar şöyle dediler, “Mûsâ ve kardeşi kesinlikle büyücüdürler. Büyüleri ile sizi yurdunuzdan çıkarmak, sizin ideal yönetiminizi ortadan kaldırmak istiyorlar.”"},{"n":64,"t":"“Büyü ile ilgili bütün hünerlerinizi birleştiriniz, sonra birlik halinde karşılarına geliniz. Bugün üstün gelen istediğini elde edecektir.”"},{"n":65,"t":"Büyücüler, “Ey Mûsâ! Hünerini ya önce sen ortaya koy ya da biz koyalım” dediler."},{"n":66,"t":"Mûsâ, “Hayır, siz koyunuz” dedi. Bir de baktı ki, büyülenmiş değnekleri ve ipleri, sihirleri Mûsâ`ya doğru sanki yürüyorlarmış gibi geldi."},{"n":67,"t":"Bu yüzden Mûsâ, içinde bir korku hissetti."},{"n":68,"t":"“Korkma, sen elbette daha üstünsün” dedik."},{"n":69,"t":"“Sağ elindekini at da onların yaptıklarını yutsun; onların yaptıkları sadece büyücü düzenidir. Büyücü, nereden gelirse gelsin başarı kazanamaz” dedik."},{"n":70,"t":"Sonunda büyücüler, “Biz Hârûn ve Mûsâ`nın Rabbine inandık” deyip secdeye kapandılar."},{"n":71,"t":"Firavun, “Ben size izin vermeden O`na nasıl inanırsınız? Şüphesiz O, size büyü öğreten büyüğünüzdür. Dönekliğinizden dolayı kesinlikle sizin ellerinizi ve ayaklarınızı keseceğim, sizi hurma dallarına asacağım. Hangimizin azabının daha şiddetli ve kalıcı olduğunu öğreneceksiniz” dedi."},{"n":"72-73","t":"Büyücüler, “Seni, bize gelen delillere ve bizi yaratana asla tercih etmeyeceğiz. Yapacağını yap! Senin hükmün ancak bu dünya hayatında geçerlidir. Biz şüphesiz, kendi hatalarımızı ve bize zorla yaptırdığın büyüyü bağışlaması için Rabbimize iman ettik. En üstün ve kalıcı olan Allah`tır” dediler."},{"n":74,"t":"Kim günahkâr olarak Rabbine gelirse bilsin ki kesinlikle onun için cehennem vardır. Orada ne ölür, ne dirilir."},{"n":75,"t":"Kim de inanmış ve iyi ameller yapmış olarak Allah`ın huzuruna gelirse, işte böyleleri için de yüksek dereceler vardır."},{"n":76,"t":"İçlerinden ırmaklar akan, çok uzun süreli olarak kalacakları ‘Adn cennetleri işte bu arınanların ödülüdür."},{"n":77,"t":"“Kullarımla beraber geceleyin yola çık ve onlara denizin ortasında kupkuru bir yol tutuver; arkanızdan yetişirler diye korkup kaygılanma!”"},{"n":78,"t":"Firavun, onların arkasına ordusuyla düşüp denize dalınca, deniz onları çepeçevre kuşatıp boğuverdi."},{"n":79,"t":"Firavun, toplumunu saptırdı ve onlara doğru yolu göstermedi."},{"n":80,"t":"“Ey İsrâiloğulları! Sizi düşmanınızın elinden kurtarmış, sizinle Tûr`un sağ tarafında sözleşmiş ve size kudret helvasıyla bıldırcın eti indirmiştik.”"},{"n":81,"t":"“Verdiğimiz nimetlerin temizlerinden yiyiniz, aşırı gitmeyiniz! Aksi taktirde gazabıma uğrarsınız. Benim öfkem kime inerse, biliniz ki o mahvolmuştur.”"},{"n":82,"t":"“Doğrusu ben, tövbe edeni, inanıp yararlı işler yapanı, sonra da doğru yola gideni bağışlarım.”"},{"n":83,"t":"Allah, “Kavmini geride yalnız bırakacak kadar seni acele ettiren nedir ey Mûsâ?” dedi."},{"n":84,"t":"Mûsâ, “Ey Rabbim! Onlar ardımdadır. Hoşnut olman için sana acele geldim” dedi."},{"n":85,"t":"Allah, “Doğrusu, biz, senden sonra toplumunu imtihan ettik. Sâmirî onları yoldan çıkardı” dedi."},{"n":86,"t":"Mûsâ, toplumuna kızgın ve üzgün olarak döndü. “Ey ulusum! Rabbiniz size güzel vaadde bulunmadı mı? Uzun bir zaman mı geçti, yoksa Rabbinizin öfkesine mi uğramak istediniz de, bana verdiğiniz sözden caydınız?” dedi."},{"n":87,"t":"Onlar, “Sana verdiğimiz sözden kendi başımıza caymadık. Ancak o ulusun süs eşyalarından bize yükler dolusu taşıtıldı. Biz onları ateşe attık; aynı şekilde Sâmirî de attı” dediler."},{"n":88,"t":"Sâmirî onlara, böğüren bir buzağı heykeli yaptı. Bunun üzerine, “İşte bu, sizin de Mûsâ`nın da tanrısıdır. Fakat o bunu unuttu” dediler."},{"n":89,"t":"Görmüyorlar mıydı ki, o heykel onlara ne söz söyleyebilir; ne zarar ne de fayda verebilirdi?"},{"n":90,"t":"Hârûn ise onlara önceden, “Ey ulusum! Siz bu buzağı ile deneniyorsunuz. Sizin gerçek Rabbiniz, Rahmân`dır. Bana uyunuz ve emrime itaat ediniz!” demişti."},{"n":91,"t":"Onlar, “Asla!” dediler. “Mûsâ bize dönünceye kadar ona tapmaktan vazgeçmeyeceğiz.”"},{"n":"92-93","t":"Mûsâ döndüğünde, “Ey Hârûn!” dedi. “Sana ne engel oldu da, bunların sapıklığa düştüklerini gördüğün vakit peşimden gelmedin? Emrime âsi mi oldun?”"},{"n":94,"t":"Hârûn, “Ey anamın oğlu!” dedi, “Saçımı sakalımı yolma! Emin ol ki ben senin; ‘İsrâiloğullarının arasına ayrılık düşürdün, sözümü tutmadın!` demenden korktum.”"},{"n":95,"t":"Mûsâ, “Ey Sâmirî! Ya senin yaptığın nedir?” dedi."},{"n":96,"t":"Sâmirî, “Onların görmedikleri bir şey gördüm ve o elçinin bastığı yerden bir avuç avuçladım. Bunu ziynet eşyalarının eritildiği potaya attım. Bunu böyle nefsim bana hoş gösterdi” dedi."},{"n":97,"t":"Mûsâ, “Defol!” dedi; “Artık hayatın boyunca sen; ‘bana dokunmayın!` diyeceksin. Ayrıca senin için, kurtulamayacağın bir ceza günü var. Tapmakta olduğun tanrına bak! Yemin ederim, biz onu yakacağız. Sonra da onu parça parça edip denize savuracağız.”"},{"n":98,"t":"“Sizin tanrınız yalnızca, kendisinden başka tanrı olmayan Allah`tır. O`nun ilmi her şeyi kuşatmıştır.”"},{"n":99,"t":"Ey Peygamber! İşte böylece, geçmiştekilerin haberlerinden bir kısmını sana anlatıyoruz. Şüphesiz ki, tarafımızdan sana bir öğüt verdik."},{"n":100,"t":"Kim ondan yüz çevirirse, şüphesiz ki, kıyamet gününde o ağır bir günah yükünü yüklenecektir."},{"n":101,"t":"Sırtlarında uzun süreli kalan bu yük, kıyamet günü onlar için ne kötüdür!"},{"n":102,"t":"Sûr`a üflenildiği gün, işte o gün, suçluları gözleri korkudan göğermiş bir halde toplarız."},{"n":103,"t":"“Siz dünyada sadece on gün kaldınız” diyerek aralarında fısıldaşırlar."},{"n":104,"t":"Aralarında konuştuklarını biz daha iyi biliriz. En akıllıları ise, “Sadece bir gün eğleştiniz” der."},{"n":105,"t":"“Rabbim onları ufalayıp savuracak.”"},{"n":106,"t":"“Böylece yerini dümdüz, bomboş bırakacaktır.”"},{"n":107,"t":"“Orada ne bir iniş ne de bir yokuş görebileceksin.”"},{"n":108,"t":"“O gün insanlar, davetçiye uyacaklar. Ona karşı yan çizme yoktur. Artık, Rahmân`ın hürmetine sesler kısılmıştır. Bu yüzden fısıltıdan başka bir ses işitemezsin.”"},{"n":109,"t":"“O gün, Rahmân`ın izin verdiğinden ve sözünden hoşnut olduğundan başkasının şefaati fayda vermez.”"},{"n":110,"t":"“O, insanların geleceklerini de geçmişlerini de bilir. Onlar, bilgi olarak Allah`ı kuşatamazlar.”"},{"n":111,"t":"Bütün yüzler, diri ve her şeye hâkim olan Allah için eğilip boyun bükmüştür. Zulüm yüklenen ise gerçekten perişan olmuştur."},{"n":112,"t":"Her kim, mümin olarak iyi işlerden yaparsa, artık o, ne zulümden ne de hakkının çiğnenmesinden korkar."},{"n":113,"t":"Biz, onu Arapça bir Kur`ân olarak indirdik. Onda uyarıları ayrıntılı olarak açıkladık ki, belki saygılı olurlar, yahut onlara bir hatırlatma yapar."},{"n":114,"t":"Gerçek hükümdar olan Allah yücedir. Kur`ân sana vahyedilirken, vahiy bitmeden önce tekrarlamakta acele etme ve “Rabbim, ilmimi arttır!” de!"},{"n":115,"t":"Andolsun ki, daha önce Âdem`e emretmiştik, fakat unuttu; onu gayretli de bulamadık."},{"n":116,"t":"Meleklere, “Âdem`e secde ediniz!” demiştik. İblîs`ten başka herkes secde etmişti."},{"n":"117-119","t":"“Ey Âdem! Doğrusu bu, senin ve eşinin düşmanıdır. Sakın sizi cennetten çıkarmasın, yoksa mutsuz olursun. Zira cennette ne acıkırsın ne de çıplak kalırsın; orada ne susarsın, ne de güneşin sıcağında kalırsın” dedik."},{"n":120,"t":"Ama, şeytan ona vesvese verip, “Ey Âdem! Sana sonsuzluk ağacını ve çökmesi olmayan bir hükümranlık göstereyim mi?” dedi."},{"n":121,"t":"Bunun üzerine ikisi de ağaçtan yedi, ayıp yerleri görünüverdi. Cennet yapraklarıyla örtünmeye koyuldular. Âdem, Rabbine baş kaldırdı ve yolunu şaşırdı."},{"n":122,"t":"Rabbi yine de onu seçip tövbesini kabul etti, ona doğru yolu gösterdi."},{"n":123,"t":"Allah onlara şöyle dedi, “Birbirinize düşman olarak hepiniz oradan ininiz. Elbet size benden bir yol gösteren gelir. Benim yoluma uyan ne sapar ne de mutsuz olur.”"},{"n":124,"t":"Benim kitabımdan yüz çevirenin dar bir geçimi olur ve kıyamet günü de onu kör olarak haşr ederiz."},{"n":125,"t":"-Ben görmekte olan biriyken, beni niye kör olarak haşrettin Rabbim?\""},{"n":126,"t":"Allah, “İşte böyle, âyetlerimiz sana gelmişti de, sen onları unutmuştun. Bu gün de öylece unutulursun” der."},{"n":127,"t":"İşte, yüz çevirenleri, Rabbinin âyetlerine inanmayanları böyle cezalandıracağız. Hem, âhiretin azabı daha çetin ve daha süreklidir."},{"n":128,"t":"Yurtlarında dolaştıkları nice nesilleri helâk etmiş olmamız, onları doğru yola iletmedi mi? Şüphesiz bunda akıl sahipleri için dersler vardır."},{"n":129,"t":"Eğer Rabbin tarafından önceden verilmiş bir söz ve belirlenmiş bir süre olmasaydı, onlar dünyada da kesinlikle azap görürlerdi."},{"n":130,"t":"Onların söylediklerine sabret! Güneşin doğmasından ve batmasından önce Rabbini övgü ile tesbih et/namaz kıl! Gece saatlerinde de O`nu övgü ile tesbih et/namaz kıl! Gündüzün belli vakitlerinde buna devam et ki mutlu olasın!"},{"n":131,"t":"Kendilerini sınamak için dünya hayatının süsü olarak onlara verdiğimiz çeşit çeşit nimetlere göz dikme! Rabbinin nimeti hem daha üstün, hem de daha süreklidir."},{"n":132,"t":"Ailene namazı emret; kendin de ona sabırla devam et! Senden rızık istemiyoruz; biz seni rızıklandırıyoruz. Güzel sonuç, takvâ sahiplerinin olacaktır."},{"n":133,"t":"Onlar, “Muhammed bize Rabbinden bir mucize getirmeli değil miydi?” dediler. Onlara önceki kitaplarda bulunan belgeler gelmedi mi?"},{"n":134,"t":"Eğer, onları Muhammed`den önce bir azaba uğratarak yok etseydik, “Ey Rabbimiz! Bize bir peygamber gönderseydin de alçak ve rezil olmazdan önce ilkelerine uysaydık olmaz mıydı?” diyeceklerdi."},{"n":135,"t":"“Herkes gözlemektedir; siz de gözleyiniz! Şüphesiz doğru-düzgün yolun yolcularının kimler olduğunu ve kimlerin doğru yolda bulunduğunu bileceksiniz."}],[{"n":1,"t":"İnsanların hesapları yaklaştı; fakat onlar hâlâ gaflet içinde yüz çevirmektedirler."},{"n":2,"t":"Rabblerinden kendilerine gelen her yeni öğüdü alaya alarak dinlerler."},{"n":3,"t":"Kalpleri başka şeylerle oyalanarak haksızlık edenler, aralarında fısıldaşarak, “Bu da sizin gibi bir insandan başka bir şey değildir. Siz göre göre büyüyü mü kabul edip inanacaksınız?” derler."},{"n":4,"t":"Peygamber, “Rabbim, gökte ve yerde söyleneni bilir. O her şeyi işiten ve her şeyi bilendir” dedi."},{"n":5,"t":"Onlar, “Hayır, bunlar karışık rüyalardır, onu kendisi uydurmuştur. Hayır o şairdir. Haydi, önceki peygamberler gibi bir belge getirsin!” dediler."},{"n":6,"t":"Bunlardan önce helâk ettiğimiz toplumların da hiçbiri iman etmemişti, şimdi bunlar mı iman edecekler?"},{"n":7,"t":"Biz, senden önce, kendilerine vahyettiğimiz kişilerden başkasını peygamber olarak göndermedik. Eğer bilmiyorsanız Kur`ân`ı bilenlere sorunuz!"},{"n":8,"t":"Biz onları yiyip içmeyen birer ceset kılmadık ve onlar ölümsüz de değillerdir."},{"n":9,"t":"Sonra biz onlara verdiğimiz sözü yerine getirdik. Onları ve dilediklerimizi kurtardık. Aşırı gidenleri de helâk ettik."},{"n":10,"t":"Andolsun size, içinde şerefiniz bulunan bir kitap indirdik. Aklınızı kullanmıyor musunuz?"},{"n":11,"t":"Biz, halkı zulüm yapan nice ülkeleri yerle bir ettik. Ondan sonra yerlerine başka topluluklar vücuda getirdik."},{"n":12,"t":"Azabımızı hissettiklerinde, oralardan kaçmaya başladılar."},{"n":13,"t":"“Kaçmayınız! İçinde bulunduğunuz refaha ve evlerinize dönünüz! Çünkü size sorular sorulacak.”"},{"n":14,"t":"“Vay başımıza gelenlere!” dediler. “Gerçekten biz zâlim insanlarmışız.”"},{"n":15,"t":"Biz, kendilerini kuruyup biçilmiş ekine, sönmüş ateş külüne çevirinceye kadar, bu feryatları sürüp gider."},{"n":16,"t":"Gökleri, yeri ve bu ikisi arasında var olan hiçbir şeyi, bir oyun olarak yaratmadık."},{"n":17,"t":"Eğer bir eğlence edinmek isteseydik, herhalde bunu kendi tarafımızdan edinirdik. Biz, bunu yapanlardan değiliz."},{"n":18,"t":"Tersine biz, hakkı bâtılın tepesine bindiririz de o, bâtılın işini bitirir. Bir de bakarsınız ki, bâtıl yok olup gitmiştir. O halde Allah`a yakıştırdığınız sıfatlardan ötürü, yazıklar olsun size!"},{"n":19,"t":"Göklerde ve yerde var olan herkes/her şey O`na aittir. O`nun huzurunda bulunanlar, O`na ibadet etmek hususunda kibirlenmezler ve yorulmazlar."},{"n":20,"t":"Onlar bıkıp usanmaksızın gece gündüz Allah`ı tesbih ederler/anarlar."},{"n":21,"t":"Yoksa müşrikler yerden birtakım tanrılar edindiler de onlar mı diriltecekler?"},{"n":22,"t":"Eğer yerde ve gökte Allah`tan başka tanrılar bulunsaydı, yer ve gök, kesinlikle bozulup gitmişti. Demek ki arşın Rabbi olan Allah, onların yakıştırdıkları sıfatlardan uzaktır."},{"n":23,"t":"Allah, yaptığından sorumlu tutulamaz, onlar ise sorguya çekileceklerdir."},{"n":24,"t":"“Haydi delillerinizi getiriniz! İşte, benimle beraber olanların kitabı ve benden öncekilerin kitabı. Hayır, onların çoğu hakkı bilmezler; bu yüzden de yüz çevirirler."},{"n":25,"t":"Senden önce hiçbir peygamber göndermedik ki, ona “Benden başka ilâh yoktur, o halde bana kulluk ediniz” diye vahyetmiş olmayalım."},{"n":26,"t":"“Rahmân çocuk edindi” dediler. Hâşâ! O, bundan uzaktır. Bilakis onlar, lütuf ve ihsana mazhar olmuş kullardır."},{"n":27,"t":"Allah`tan önce konuşmazlar; onlar, sadece O`nun emri ile hareket ederler."},{"n":28,"t":"Allah, onların önlerindekini de arkalarındakini de bilir. Allah`ın rızasına ulaşmış olanlardan başkasına şefaat etmezler. Onlar, Allah korkusundan titrerler."},{"n":29,"t":"“Allah`tan başka ben de bir tanrıyım” derse, işte onu cehennemle cezalandırırız. Zâlimlerin cezasını böyle veririz."},{"n":30,"t":"İnkâr edenler, göklerin ve yerin birbirine yapışık olduğunu, bizim onları ayırdığımızı ve bütün canlıları sudan yarattığımızı görmüyorlar mı? Buna rağmen inanmayacaklar mı?"},{"n":31,"t":"İnsanları sarsmaması için yerin üstüne sabit dağlar yerleştirdik. Dağlar arasında geçitler ve yollar açtık ki yollarını bulabilsinler."},{"n":32,"t":"Gökyüzünü de korunmuş bir tavan gibi yaptık. Oysa onlar bundaki delilleri görmezlikten geliyorlar."},{"n":33,"t":"Geceyi ve gündüzü, güneşi ve ayı yaratan O`dur. Onların her biri bir yörüngede akıp gitmektedirler."},{"n":34,"t":"Biz, senden önce hiçbir beşere sonsuz yaşam vermedik. Şimdi sen ölürsen, sanki onlar sonsuz mu kalacaklar?"},{"n":35,"t":"Her canlı ölümü tadacaktır. Bir deneme olarak sizi iyilikle ve kötülükle imtihan ederiz. Siz ancak bize döndürüleceksiniz."},{"n":36,"t":"İnkârcılar seni gördüklerinde, “Sizin tanrınızı diline dolayan bu mudur?” diye seni alaya almaktan başka bir şey yapmazlar. Oysa kendileri, çok merhametli olan Allah`ı anmayı inkâr ediyorlar."},{"n":37,"t":"İnsan aceleci olarak yaratılmıştır. Âyetlerimi yakında size göstereceğim, artık onların çabuk gelmesini istemeyiniz."},{"n":38,"t":"İnkâr edenler, “Doğru söylüyorsanız bizi tehdit ettiğiniz azap ne zaman?” derler."},{"n":39,"t":"İnkâr edenler, yüzlerinden ve sırtlarından ateşi savamayacakları, kendilerine yardım dahi edilemeyeceği zamanı bir bilselerdi!"},{"n":40,"t":"Bilakis, kendilerine o öyle ani gelir ki, onları şaşırtır. Artık ne reddedebilirler onu, ne de kendilerine mühlet verilir."},{"n":41,"t":"Andolsun, senden önceki peygamberlerle de alay edildi; ama onları alaya alanları, o alay konusu ettikleri şey kuşatıverdi."},{"n":42,"t":"“Allah`a karşı sizi gece gündüz kim koruyacak?” Buna rağmen onlar Rabblerini anmaktan yüz çevirirler."},{"n":43,"t":"Yoksa kendilerini bize karşı savunacak birtakım tanrıları mı var? O tanrılar, kendilerine bile yardım edecek güçte değildirler. Onlar bizden de alâka ve destek görmezler."},{"n":44,"t":"Doğrusu biz o inkârcıları ve babalarını dünya nimetlerinden yararlandırdık. Öyle ki uzun süre bu şekilde yaşadılar. Onlar, bizim, şimdi bulundukları topraklara gelip, oraları azar azar ele geçirdiğimizi görmüyorlar mı? Onlar inananlara galip geleceklerini mi sanıyorlar?"},{"n":45,"t":"“Ben sizi ancak vahiyle uyarıyorum.” Fakat manen sağır olanlar, uyarıldıkları zaman, bu çağrıyı duymazlar."},{"n":46,"t":"Andolsun, Rabbinin azabı onlara hafifçe dokunsa, “Vah bize! Doğrusu, biz haksızlık yaptık” derler."},{"n":47,"t":"Biz, kıyamet günü için adâlet terazileri kurarız. Artık kimseye, hiçbir şekilde haksızlık edilmez. Yapılan iş, bir hardal tanesi ağırlığında bile olsa onu getiririz. Hesap gören olarak biz yeteriz."},{"n":48,"t":"Andolsun, Mûsâ ve Hârûn`a eğriyi doğrudan ayıran kitabı, takvâ sahipleri için ışık ve hatırlatıcı bilgi kaynağı olarak verdik."},{"n":49,"t":"Takvâ sahipleri, görmedikleri halde Rabblerine bilinçli bir şekilde saygı duyarlar; onlar kıyametten korkan kimselerdir."},{"n":50,"t":"İşte bu Kur`ân da bizim indirdiğimiz hayırlı ve faydalı bir öğüttür. Şimdi onu inkâr mı ediyorsunuz?"},{"n":51,"t":"Andolsun ki, daha önce İbrâhim`e de doğru düşünme yeteneği vermiştik. Biz onu biliyorduk."},{"n":52,"t":"İbrâhim, babasına ve toplumuna, “Şu karşısına geçip tapmakta olduğumuz heykeller de ne oluyor?” demişti."},{"n":53,"t":"Onlar da, “Babalarımızı bunlara tapar bulduk” demişlerdi."},{"n":54,"t":"İbrâhim, “Andolsun ki, sizler de babalarınız da apaçık bir sapıklık içindesiniz” dedi."},{"n":55,"t":"Onlar da, “Sen bize gerçeği mi getirdin, yoksa bizimle oyun mu oynuyorsun?” dediler."},{"n":56,"t":"“Hayır, sizin Rabbiniz, yarattığı göklerin ve yerin de Rabbidir ve ben buna şâhitlik edenlerdenim/inananlardanım.”"},{"n":57,"t":"Allah`a yemin ederim ki, siz ayrılıp gittikten sonra putlarınıza bir oyun oynayacağım."},{"n":58,"t":"Onlar gidince hepsini paramparça edip içlerinden büyüğünü, ona başvursunlar diye sağlam bıraktı."},{"n":59,"t":"Putperestler, “Bunu tanrılarımıza kim yaptı? Muhakkak o, zâlimlerden biridir” dediler."},{"n":60,"t":"Bazıları, “Bunları diline dolayan bir genç duyduk; kendisine İbrâhim denilirmiş” dediler."},{"n":61,"t":"“O halde, onu hemen insanların gözü önüne getirin, belki şâhitlik ederler” dediler."},{"n":62,"t":"“İbrâhim, bunu tanrılarımıza sen mi yaptın?” dediler."},{"n":63,"t":"İbrâhim, “Hayır, onu şu büyükleri yapmıştır, konuşabiliyorlarsa onlara sorun” dedi."},{"n":"64-65","t":"Kendi kendilerine dönüp birbirlerine, “Doğrusu siz zâlimlerdensiniz” dedikten sonra, gönüllerindeki eski inançları depreşerek, “Ey İbrâhim! Sen bunların konuşmayacağını bilirsin” dediler."},{"n":"66-67","t":"İbrâhim, “O halde, Allah`ı bırakıp size hiçbir fayda ve zarar veremeyecek olan putlara mı tapıyorsunuz? Size de, Allah`ı bırakıp taptıklarınıza da yazıklar olsun! Aklınızı kullanmıyor musunuz?” dedi."},{"n":68,"t":"Putperestler, “Eğer bir şey yapacaksanız, onu yakın da, tanrılarınıza yardım edin” dediler."},{"n":69,"t":"Biz, “Ey ateş! İbrâhim`e karşı serin ve esenlik ol!” dedik."},{"n":70,"t":"Ona tuzak kurmak istediler. Biz de onları daha çok kayba uğrattık."},{"n":71,"t":"Biz, İbrâhim ve Lût`u kurtararak âlemler için kutsal kıldığımız topraklara ulaştırdık."},{"n":72,"t":"İbrâhim`e İshâk`ı ve ilâve bir bağış olmak üzere Ya‘kûb`u verdik. Her birini iyi kimseler kıldık."},{"n":73,"t":"Onları, emrimiz doğrultusunda insanlara yol gösteren önderler yaptık; onlara iyi işler yapmayı, namaz kılmayı, zekât vermeyi vahyettik. Onlar, bize hep kulluk ettiler."},{"n":74,"t":"Lût`a gelince, ona da hüküm ve ilim verdik; onu çirkin işler yapmakta olan halkından kurtardık. Zira onlar, gerçekten fena işler yapan kötü bir topluluktu."},{"n":75,"t":"Lût`u rahmetimize aldık; doğrusu o, iyilerdendi."},{"n":76,"t":"Nûh da, daha önce yalvarmıştı; onun da duasını kabul etmiştik. Kendisini ve ailesini büyük sıkıntıdan kurtardık."},{"n":77,"t":"Nuh`u, âyetlerimizi inkâr eden kavimden koruduk. Gerçekten onlar, fena bir kavimdi. Bu yüzden hepsini suya gömdük."},{"n":78,"t":"Dâvûd ve Süleymân`ı da hatırla! Bir zaman bir ekin konusunda hüküm veriyorlardı. Bir grup insanın koyun sürüsü, geceleyin başıboş bir durumda bu ekinin içine dağılıp ziyan vermişti. Biz onların hükmünü görüp bilmekte idik."},{"n":79,"t":"Böylece hükmü Süleymân`a biz anlatmıştık. Her ikisine de sağlam bir muhakeme gücü ve ilim vermiştik. Kuşları ve tesbih eden dağları da Dâvûd`a boyun eğdirdik. Biz her şeyi yaparız."},{"n":80,"t":"Dâvûd`a, sizi her türlü korkuya karşı koruması için zırh yapmayı öğrettik. Bütün bunlar için şükrediyor musunuz?"},{"n":81,"t":"Süleymân`ın emrine de zorlu rüzgârı verdik. Onun emriyle, içinde bereketler yarattığımız ülkeye doğru eserdi. Biz her şeyi biliriz."},{"n":82,"t":"Şeytanlar arasında da, onun için dalgıçlık eden ve bundan başka işler görenler vardı. Biz onları gözetim altında tutuyorduk."},{"n":83,"t":"Eyyûb`u da hatırla! Hani Rabbine, “Başıma bir belâ geldi. Sen, merhametlilerin en merhametlisisin” diye niyaz etmişti."},{"n":84,"t":"Biz de onun duasını kabul etmiş ve başına gelen sıkıntıyı kaldırmıştık. Katımızdan bir rahmet ve kulluk edenlere bir hatıra olmak üzere, ona tekrar ailesini ve olanlarla beraber bir katını daha vermiştik."},{"n":85,"t":"İsmâil`i, İdrîs`i ve Zülkifl`i de an. Hepsi de sabreden kimselerdendi."},{"n":86,"t":"Onları rahmetimize kabul ettik. Onlar hakikaten iyi kimselerdendi."},{"n":87,"t":"Zü`n-Nûn`u/Yunus`u da hatırla! O, öfkeli bir halde geçip gitmişti; bizim kendisini aslâ sıkıştırmayacağımızı zannetmişti. Nihayet karanlıklar içinde, “Senden başka hiçbir tanrı yoktur. Seni tenzih ederim. Gerçekten ben zâlimlerden oldum” diye yalvardı."},{"n":88,"t":"Bunun üzerine onun da duasını kabul ettik ve onu kederden kurtardık. İşte biz müminleri böyle kurtarırız."},{"n":89,"t":"“Ey Rabbim! Beni yalnız bırakma! Sen vârislerin en üstünüsün.”"},{"n":90,"t":"Biz de duasını kabul ettik ve ona Yahyâ`yı bahşettik. Eşini de kendisi için elverişli hale getirdik. Gerçekten bütün peygamberler hayır işlerinde koşuşurlar, umarak ve korkarak bize yalvarırlardı. Onlar bize gönülden saygı duyuyorlardı."},{"n":91,"t":"İffetini koruyan Meryem`e ruhumuzdan üflemiş, onu ve oğlunu âlemlere ders kılmıştık."},{"n":92,"t":"İşte, sizin bu dininiz, tek bir dindir ve ben de Rabbinizim, artık bana kulluk ediniz."},{"n":93,"t":"Ama insanlar din konusunda aralarında bölündüler; hepsi bize döneceklerdir."},{"n":94,"t":"İnanmış olarak iyi amel yapanların çalışması inkâr edilmeyecektir. Biz onu yazmaktayız."},{"n":95,"t":"Helâk ettiğimiz ülke halkının bize dönmemesi imkânsızdır."},{"n":"96-97","t":"Nihayet Ye`cûc ve Me`cûc setleri açıldığı ve onlar her tepeden akın ettiği zaman, verilen gerçek söz yaklaştığında inkâr edenlerin gözleri donakalır! “Yazıklar olsun bize! Gerçekten biz, bu durumdan habersizmişiz, hatta biz zâlim kimselermişiz” derler."},{"n":98,"t":"Siz ve Allah`tan başka taptıklarınız, cehennemin yakıtısınız. Hepiniz oraya gireceksiniz."},{"n":99,"t":"Eğer onlar birer tanrı olsalardı cehenneme girmezlerdi. Hepsi orada çok uzun süreli olarak kalacaktır."},{"n":100,"t":"Cehennemde onlara inim inim inlemek düşer. Onlar orada hiçbir şey işitmezler."},{"n":101,"t":"Ama gerçekten kendileri için, katımızdan iyilik ve güzellik yazılmış bulunanlara gelince, böyleleri cehennemden uzak tutulacaklardır."},{"n":102,"t":"Onlar, cehennemin uğultusunu duymazlar; gönüllerinin dilediği nimetler içinde çok uzun süreli kalırlar."},{"n":103,"t":"En büyük dehşet bile onları tasalandırmaz. Melekler kendilerini, “Size söz verilen gün, işte bugündür” diye karşılarlar."},{"n":104,"t":"Göğü, kitap sayfalarını dürer gibi dürdüğümüz zaman, yaratmaya ilk başladığımız gibi, katımızdan verilmiş bir söz olarak yaratmayı tekrar edeceğiz. Biz bunu yapacağız."},{"n":105,"t":"Andolsun Zikir`den/Tevrat`tan sonra Zebûr`da da, “Yeryüzüne iyi kullarım vâris olacaktır” diye yazmıştık."},{"n":106,"t":"İşte bunda, Allah`a kulluk eden bir toplum için bir mesaj vardır."},{"n":107,"t":"Biz seni ancak âlemlere merhametimiz gereği gönderdik."},{"n":108,"t":"“Bana, Tanrınız ancak bir tek tanrıdır” diye vahyolunuyor. O`na teslim olacak mısınız?"},{"n":109,"t":"“Ben sizin hepinize eşit şekilde açıkladım. Artık tehdit edildiğiniz şeyin yakın mı, yoksa uzak mı olduğunu bilmem.”"},{"n":110,"t":"Şüphesiz O, sözün açığını da bilir; gizlediklerinizi de bilir."},{"n":111,"t":"“Bilmem, belki de o azabın ertelenmesi, sizi sınamak ve bir süreye kadar yaşatmak içindir.”"},{"n":112,"t":"“Ey Rabbim, onlar hakkında adâletle hükmünü ver! Bizim Rabbimiz, Rahmân`dır. Sizin anlattıklarınıza karşı yardımı umulandır.”"}],[{"n":1,"t":"Ey insanlar! Rabbinize saygı gösterin! Çünkü son saatin sarsıntısı gerçekten büyük olacaktır."},{"n":2,"t":"O sarsıntıyı gördüğünüzde, her emzikli emzirdiğini unutur; her hamile, çocuğunu düşürür; insanları da sarhoş olmadıkları halde sarhoş bir halde görürsün; Fakat Allah`ın azabı çok şiddetlidir."},{"n":3,"t":"İnsanlardan öyleleri vardır ki, Allah hakkında bilgisizce tartışırlar ve her inatçı şeytana uyarlar."},{"n":4,"t":"“Kim şeytanı dost edinirse, şeytan onu yoldan çıkarır ve onu alevli cehennem azabına sürükler.”"},{"n":5,"t":"Ey insanlar! Öldükten sonra dirilmekten şüphede iseniz; doğrusu, biz sizi topraktan, sonra nutfeden/meniden yani erlik suyundan, sonra yapışkandan/döllenmiş yumurta hücresinden, sonra da yaratılışı belli belirsiz bir et parçasından yaratmış olduğumuzu size açıklıyoruz. Dilediğimizi belli bir süreye kadar rahimlerde tutarız; sonra sizi çocuk olarak çıkarırız; böylece yetişip ergenlik çağına varırsınız. Kiminiz ölür, kiminiz de ömrünün en verimsiz çağına kadar götürülür de, bilirken bir şey bilmez olur. Yeryüzünü görürsün ki kupkurudur; fakat biz ona su indirdiğimiz zaman yeryüzü kıpırdanır, kabarır, her çeşitten iç açıcı bitkiler verir."},{"n":6,"t":"Bunlar, Allah`ın gerçek olduğunu gösterir. O, ölüleri diriltir. O`nun her şeye gücü yeter."},{"n":7,"t":"Kendinde şüphe olmayan kıyamet vakti gelecek ve Allah, kabirlerde olanları diriltip kaldıracaktır."},{"n":"8-9","t":"İnsanlardan bazısı, bir bilgisi, bir rehberi ve aydınlatıcı bir kitabı olmadığı halde, sırf Allah yolundan saptırmak için yanını eğip bükerek Allah hakkında tartışmaya kalkar. Onun için dünyada bir rezillik vardır; kıyamet gününde ise ona yakıcı azabı tattıracağız."},{"n":10,"t":"İşte bu, önceden yapıp ettikleri yüzündendir. Elbette Allah, kullarına haksızlık edici değildir."},{"n":11,"t":"Allah`a iman ile küfür sınırında kulluk eden insanlar da vardır. Kendisine bir iyilik dokunursa, buna çok memnun olur. Eğer kendisine bir musibet dokunursa, yüzüstü döner. O, dünyasını da, âhiretini de kaybetmiştir. İşte kıyas kabul etmeyecek kayıp budur."},{"n":12,"t":"O, Allah`ı bırakıp, kendisine faydası da zararı da dokunamayacak olan şeylere yalvarır. Bu, büsbütün uzak olan sapıklığın ta kendisidir."},{"n":13,"t":"O, zararı faydasından daha yakın olan bir varlığa yalvarır. O, ne kötü bir yardımcı, ne kötü bir dosttur!"},{"n":14,"t":"Şüphesiz ki Allah, inanıp iyi amelde bulunanları, içinden ırmaklar akan cennetlere koyar. Şüphesiz, Allah dilediğini yapar."},{"n":15,"t":"Her kim Allah`ın, Peygamberine dünya ve âhirette yardım etmeyeceğini sanıyorsa, göğe ulaşacak bir çare arasın; sonra eğer mümkünse o yardımı kessin. Baksın bu hilesi, kızdığı yardımı engelleyecek mi?"},{"n":16,"t":"İşte böyle biz, Kur`ân`ı apaçık âyetler halinde indirdik. Şüphesiz Allah dileyeni doğru yola iletir."},{"n":17,"t":"Gerçek şu ki, inananlar, Yahûdî inancını benimseyenler ve Sâbiîler, Hıristiyanlar ve Mecûsîler, bir de Allah`a şirk koşanlar arasında, Allah kıyamet günü hükmünü verecektir. Allah her şeye şâhittir."},{"n":18,"t":"Göklerde ve yerde olanların; güneş, ay, yıldızlar, dağlar, ağaçlar, hayvanlar ve insanların birçoğunun Allah`a boyun eğdiklerini görmüyor musun? İnsanlardan birçoğu da azabı hak etmiştir. Allah`ın hakir kıldığına saygı duyacak kimse yoktur. Doğrusu, Allah dilediğini yapar."},{"n":19,"t":"Şu iki grup, Rabbleri hakkında çekişen iki hasımdır. İnkâr edenler için ateşten bir elbise biçilmiştir. Onların başlarının üstünden kaynar su dökülecektir."},{"n":20,"t":"Bununla karınlarının içindeki organları ve derileri eritilecektir."},{"n":21,"t":"Bir de onlar için demir kamçılar vardır."},{"n":22,"t":"Istıraptan dolayı oradan her çıkmak istediklerinde, oraya geri döndürülürler ve onlara, “Tadın yakıcı azabı!” denir."},{"n":23,"t":"Şüphesiz Allah, inanıp iyi amel işleyenleri, içinden ırmaklar akan cennetlere koyar. Orada altın bilezikler ve inciler takınırlar. Onların oradaki elbiseleri de ipektir."},{"n":24,"t":"Onlar, sözün en doğrusuna/temizine, bütün övgülere lâyık Allah`ın yoluna iletilmişlerdir."},{"n":25,"t":"Şüphesiz, inkâr edenlere, insanları Allah`ın yolundan, yerli ve yabancı bütün insanlar için eşit kıldığımız Mescid-i Harâm`dan alıkoyanlara ve orada haktan ayrılarak zulmetmek isteyenlere acıklı bir azabı tattıracağız."},{"n":26,"t":"“Bana hiçbir şeyi ortak koşma, tavaf edenler, orada kıyama duranlar, rükû ve secde edenler için evimi temizle!”"},{"n":27,"t":"“İnsanlar için haccı ilan et! Yaya olarak veya uzak yollardan gelen yorgun develer üzerinde sana gelsinler.”"},{"n":28,"t":"“Kendileri için orada bulunan faydaları görsünler; belli günlerde kendilerine verdiğimiz hayvanlardan Allah`ın adını anarak kurban kessinler. Bu kurbanlardan yiyiniz, yoksullara da yediriniz!”"},{"n":29,"t":"“Sonra beden temizliği yapsınlar. Adaklarını yerine getirsinler. Eski evi tavaf etsinler!”"},{"n":30,"t":"Yapılması gerekenler işte bunlardır. Kim Allah`ın koyduğu yasaklara saygı gösterirse, bu durum onun için Rabbinin katında daha iyidir. Haram olduğu okunanlar dışında evcil havyanlar size helâl kılındı. Artık putların pisliğinden uzak durunuz, yalan söylemekten de kaçınınız!"},{"n":31,"t":"Hiçbir şeyi ortak koşmadan samimi bir şekilde Allah`a yöneliniz. Kim Allah`a ortak koşarsa, onun durumu sanki gökten düşen ve kuşlar tarafından kapılıp kaçırılan ya da rüzgârın uzak bir yere savurduğu eşya gibidir."},{"n":32,"t":"Evet, bu böyledir. Her kim Allah`ın hükümlerine saygı gösterirse şüphesiz bu, kalplerin takvâsındandır."},{"n":33,"t":"Bunlarda sizin için belli bir süreye kadar faydalar vardır. Sonra varacakları yer Beyt-i Atîk`tir."},{"n":34,"t":"Allah`ın kendilerine rızık olarak verdiği kurbanlıklar üzerine Allah`ın adını ansınlar diye, biz her ümmet için kurban kesmeyi farz kıldık. İşte sizin tanrınız tek bir Tanrı`dır. O halde O`na teslim olun. O`na samimiyetle boyun eğenleri müjdele!"},{"n":35,"t":"Onlar, Allah anıldığında kalpleri ürperenler, başlarına gelene sabredenler, namazı dosdoğru kılanlar ve verdiğimiz rızklardan Allah rızası için harcayanlardır."},{"n":36,"t":"Biz, büyükbaş hayvanları da sizin için Allah`ın işaretlerinden kıldık. Onlarda sizin için hayır vardır. Şu halde onlar, ayakları üzerinde dururken üzerlerine Allah`ın ismini anınız. Yan üstü yere düştüklerinde ise, canı çıktığında onlardan hem kendiniz yiyiniz, hem de kanaatkâr olup dilenmeyene de, dilenene de veriniz. İşte bu hayvanları biz, şükredesiniz diye sizin istifadenize sunduk."},{"n":37,"t":"Bu kurbanların ne etleri ne de kanları Allah`a ulaşır! Fakat Allah`a ulaşacak olan sizin takvânızdır. Sizi doğru yola erdirdiğinden dolayı Allah`ı büyük tanıyasınız diye, bu hayvanları sizin istifadenize sundu. Güzel davrananları müjdele!"},{"n":38,"t":"Şüphesiz, Allah inananları korur. Allah hainleri ve nankörleri hiç sevmez."},{"n":39,"t":"Zulme uğrayanlara, kendilerine savaş açılmış müminlere savaş izni verildi. Allah onlara yardım etmeye elbette gücü yetendir."},{"n":40,"t":"Onlar haksız yere ve sırf “Rabbimiz Allah`tır” dedikleri için, haksız bir şekilde yurtlarından çıkarılmışlardır. Allah insanların bir kesimini diğerleriyle engellemeseydi, içinde Allah`ın adı çokça anılan manastırlar, kiliseler, havralar ve mescitler yıkılıp giderdi. Andolsun ki, Allah`a yardım edenlere O da yardım eder. Allah kuvvetlidir; güçlüdür."},{"n":41,"t":"Eğer onlara yeryüzünde iktidar verirsek namazı kılar, zekâtı verir, iyiliği emreder ve kötülükten sakındırırlar. İşlerin sonu Allah`a varır."},{"n":42,"t":"Eğer seni yalanlarlarsa, bilesin ki senden önce Nûh, ‘Âd ve Semûd kavimleri de peygamberlerini yalanlamışlardı."},{"n":43,"t":"İbrâhim`in kavmi ve Lût`un kavmi de."},{"n":44,"t":"Medyen halkı da yalanlamıştı. Mûsâ da yalanlanmıştı. Ben o kâfirlere süre tanıdım. Sonra onları yakalayıverdim. Bir görseydin benim cezalandırmam nasıl olmuştu!"},{"n":45,"t":"Nice zulme dalmış ülke halkını yok ettik. Artık duvarları çatıları üzerine çökmüş, kuyuları kullanılmaz olmuş, yüce sarayları terkedilmiştir."},{"n":46,"t":"Yeryüzünde dolaşmıyorlar mı ki, düşünecek kalpleri ve işitecek kulakları olsun. Gerçek şu ki, gözler kör olmaz, fakat asıl sinelerdeki kalpler kör olur."},{"n":47,"t":"Onlar senden azabın çabuk gelmesini istiyorlar. Allah vaadinden asla dönmez. Rabbin katında bir gün, sizin saydıklarınızdan bin yıl gibidir."},{"n":48,"t":"Zulmedip dururlarken, kendilerine süre tanıdığım nice ülkeler vardır. Sonunda onları yakalayıp yok ettim. Dönüş yalnız banadır."},{"n":49,"t":"“Ey insanlar! Ben, ancak sizin için apaçık bir uyarıcıyım.”"},{"n":50,"t":"İman edip iyi amel işleyen kimseler için af ve güzel rızık vardır."},{"n":51,"t":"Karşı çıkarak âyetlerimizi etkisiz kılmaya gayret edenlere gelince, işte onlar cehennemliklerdir."},{"n":52,"t":"Biz, senden önce hiçbir rasûl ve nebi göndermedik ki o, bir temennide bulunduğunda, şeytan onun dileğine ille de beşeri arzular katmaya kalkışmasın. Ne var ki Allah, şeytanın katacağı şeyi iptal eder. Sonra Allah, kendi âyetlerini sağlam olarak yerleştirir. Allah, bilendir; hikmet sahibidir."},{"n":53,"t":"Böyle yapar ki, şeytanın attığını, kalplerinde hastalık olanlar ve kalpleri katılaşanlar için bir imtihan yapsın. Zâlimler uzak bir ayrılık içindedirler."},{"n":54,"t":"Kendilerine ilim verilmiş olanlar da Kur`ân`ın, senin Rabbinden gelenin hak olduğunu bilsinler de ona inansınlar; böylece kalpleri ona saygı duysun. Şüphesiz Allah, inananları doğru yola iletir."},{"n":55,"t":"İnkâr edenler, kendilerine son saat ansızın gelinceye ya da her kurtulma gayretinin sonuçsuz kalacağı günün azabı gelinceye kadar, Kur`ân hakkında hep şüphe içinde olacaklardır."},{"n":56,"t":"O gün hükümranlık Allah`ındır. Allah, onların arasında hükmeder. İnanıp iyi amel yapanlar nimet cennetlerindedirler."},{"n":57,"t":"İnkâr edip âyetlerimizi yalanlayanlara da, aşağılatan bir azap vardır."},{"n":58,"t":"Allah yolunda hicret edip sonra öldürülen veya ölenlere gelince, Allah onları pek güzel rızklarla rızıklandıracaktır. Şüphesiz ki Allah, rızık verenlerin en hayırlısıdır."},{"n":59,"t":"Kesinlikle onları hoşlanacakları bir yerde konaklatacaktır. Şüphesiz Allah, her şeyi bilir; son derece yumuşak davranandır."},{"n":60,"t":"İşte bu böyledir! Kim kendisine yapılana denk bir karşılık verir, sonra tekrar saldırıya uğrarsa, Allah ona elbette yardım eder. Çünkü Allah, çok affedicidir; çok bağışlayıcıdır."},{"n":61,"t":"Bu, kolaydır. Zira Allah geceyi gündüze, gündüzü de geceye katar. Allah her şeyi duyar ve görür."},{"n":62,"t":"Bu, böyledir. Çünkü gerçek tanrı Allah`tır. O`ndan başka taptıkları ise bâtıldır. Şüphesiz en yüce ve en büyük olan Allah`tır."},{"n":63,"t":"Allah`ın gökten yağmur yağdırdığını ve bu sebeple yeryüzünün yemyeşil olduğunu görmez misin? Şüphesiz Allah, lütuf sahibidir; her şeyden haberdardır."},{"n":64,"t":"Göklerde ve yerde ne varsa O`nundur. Allah`ın hiçbir şeye ihtiyacı yoktur ve bütün övgüler O`nadır."},{"n":65,"t":"Allah`ın yerde olan her şeyi, emriyle denizlerde seyreden gemileri, sizin emrinize verdiğini görmüyor musun? İzni olmadan yere düşmesinler diye, gök cisimlerini tutar. Çünkü Allah, insanlara karşı son derece şefkatli ve merhametlidir."},{"n":66,"t":"Size hayat veren, sonra öldüren, sonra yine diriltecek olan Allah`tır. Gerçekten insan çok nankördür."},{"n":67,"t":"Biz her ümmete, uygulayacakları bir ibadet şekli öğrettik. Öyle ise, onların bu konuda seninle çekişmelerine müsaade etme! Sen, Rabbine davet et! Zira sen gerçekten doğru bir yoldasın."},{"n":68,"t":"Eğer seninle mücadeleye girişirlerse, “Allah yaptıklarınızı çok iyi bilmektedir” de!"},{"n":69,"t":"Allah, kıyamet gününde, aranızda ayrılığa düştüğünüz konularda hükmünü verecektir."},{"n":70,"t":"Allah`ın göklerde ve yerde olan her şeyi bildiğini bilmez misin? Şüphesiz bunların tamamı bir kitaptadır. Bu iş, Allah`a kolaydır."},{"n":71,"t":"Onlar, Allah`ı bırakıp haklarında hiçbir delil indirmediği ve hiçbir bilgilerinin olmadığı şeylere tapıyorlar. Zâlimlerin hiçbir yardımcıları olmayacaktır."},{"n":72,"t":"“Size bundan daha kötüsünü haber vereyim mi? Allah`ın inkâr edenler için belirlediği ateş! Gidilecek ne kötü bir yerdir!”"},{"n":73,"t":"Ey insanlar! Size bir örnek verilmektedir; onu dikkatle dinleyiniz! Allah`tan başka taptıklarınız bunun için bir araya gelseler bile bir sineği dahi yaratamazlar. Sinek onlardan bir şey kapsa, bunu ondan geri alamazlar. İsteyen de âciz, kendinden istenen de."},{"n":74,"t":"Onlar Allah`ı gereği gibi değerlendiremediler. Şüphesiz Allah çok kuvvetlidir; çok üstündür."},{"n":75,"t":"Allah, meleklerden de insanlardan da elçiler seçer. Şüphesiz Allah, işitendir; görendir."},{"n":76,"t":"Onların önlerindekini de arkalarındakini de bilir. Bütün işler Allah`a döndürülür."},{"n":77,"t":"Ey iman edenler! Rükû ediniz, secde ediniz. Rabbinize kulluk ediniz! İyi işler yapınız ki kurtuluşa eresiniz."},{"n":78,"t":"Allah yolunda, hakkını vererek cihad ediniz! Sizi O seçti. Din hususunda üzerinize hiçbir zorluk yüklemedi; ceddiniz İbrâhim`in dininde de böyleydi. Peygamberin size şahit olması, sizin de insanlara şahit olmanız için, Allah gerek daha önce gelmiş kitaplarda, gerekse Kur`ân`da, size Müslümanlar adını verdi. Öyleyse namazı kılınız, zekâtı veriniz ve Allah`a sımsıkı sarılınız! O, sizin dostunuzdur. Ne güzel dosttur; ne güzel yardımcıdır!"}],[{"n":1,"t":"Müminler kesinlikle kurtuluşa ermiştir."},{"n":2,"t":"Ki onlar namazlarını huşû içinde kılarlar."},{"n":3,"t":"Boş şeylerden yüz çevirirler."},{"n":4,"t":"Arınmak için çalışırlar."},{"n":5,"t":"İffetlerini korurlar."},{"n":6,"t":"Ancak eşleri ve ellerinin altında sahip oldukları hariç. Bunlarla ilişkilerinden dolayı kınanmazlar."},{"n":7,"t":"Ama bunun ötesine gitmek isteyen olursa, işte onlar haddi aşanlardır."},{"n":8,"t":"Müminler emanetleri korur ve verdikleri sözleri yerine getirirler."},{"n":9,"t":"Namazlarını korurlar/eda ederler."},{"n":10,"t":"İşte asıl vâris olacaklar onlardır."},{"n":11,"t":"Onlar Firdevs`e vâris olacaklar ve orada çok uzun süreli kalacaklardır."},{"n":12,"t":"Andolsun ki biz, insanı çamurun özünden yarattık."},{"n":13,"t":"Sonra onu döl suyu damlası halinde sağlam bir yere yerleştirdik."},{"n":14,"t":"Sonra bu döl suyu damlasından, döllenmiş hücreyi yarattık; sonra bu döllenmiş hücreden de cenini ve ceninden kemikleri yarattık; sonra da kemiklere et giydirip onu yepyeni bir varlık halinde ortaya çıkarttık. Yaratanların en üstünü olan Allah`ın şanı ne yücedir!"},{"n":15,"t":"Sonra bunun ardından kesinlikle öleceksiniz."},{"n":16,"t":"Sonra kıyamet günü tekrar diriltileceksiniz."},{"n":17,"t":"Andolsun biz, sizin üzerinizde yedi yol/yörünge yarattık. Biz yarattıklarımızdan habersiz değiliz."},{"n":18,"t":"Gökten uygun bir ölçüde yağmur indirip onu yeryüzünde durdurduk. Bizim onu gidermeye de elbet gücümüz yeter."},{"n":19,"t":"Böylece, yağmur suyunun sayesinde sizin yararınıza hurma bahçeleri ve üzüm bağları meydana getirdik. Bunlarda sizin için birçok meyve vardır ve siz onlardan yersiniz."},{"n":20,"t":"Tûr-i Sînâ`da da bir ağaç daha meydana getirdik ki, bu ağaç hem yağ, hem de yiyenlerin ekmeğine katık edecekleri zeytin verir."},{"n":21,"t":"Hayvanlarda da alınacak dersler vardır. Onların karınlarında oluşandan size içiririz. Onlarda sizin için birçok fayda daha vardır. Etlerinden de yersiniz."},{"n":22,"t":"Onların üzerinde ve gemilerde taşınırsınız."},{"n":23,"t":"Andolsun ki, Nûh`u kavmine gönderdik ve o, “Ey kavmim! Allah`a kulluk ediniz. Sizin için O`ndan başka bir tanrı yoktur. Hâlâ sakınmaz mısınız?” dedi."},{"n":24,"t":"“Bu, sizin gibi bir insandan başka bir şey değildir. Size üstünlük taslamak istiyor. Eğer Allah dileseydi, kesinlikle melekleri indirirdi. Bunları geçmiş atalarımızdan duymadık.”"},{"n":25,"t":"“Bu, deliden başka bir şey değildir. Öyleyse bir süreye kadar onu gözetleyip bekleyelim bakalım.”"},{"n":26,"t":"Nûh da, “Ey Rabbim, yalanlamalarına karşı bana yardım et!” dedi."},{"n":27,"t":"“Bizim kontrolümüz ve tâlimatımızla gemiyi yap. Emrimiz gelip de sular kaynayınca, her cinsten birer çifti ve aleyhinde hüküm verilmiş olanlar dışında aileni de gemiye bindir. Zâlimler hakkında benden bir şey isteme! Şüphesiz onlar boğulacaklardır.”"},{"n":28,"t":"“Sen ve beraberindekiler gemiye binip yerleşince, ‘Bizi bu zâlim toplumdan kurtaran Allah`a hamdolsun` de!”"},{"n":29,"t":"“Ey Rabbim! Beni uğurlu bir yere indir. Bunu en iyi yapan sensin, de!”"},{"n":30,"t":"Şüphesiz bu olguda dersler vardır. Biz, kesinlikle denemekteyiz."},{"n":31,"t":"Sonra bunların ardından başka bir nesil meydana getirdik."},{"n":32,"t":"Onlara içlerinden, “Allah`a kulluk ediniz, sizin O`ndan başka hiçbir tanrınız yoktur, saygı duymuyor musunuz?” diyen bir peygamber gönderdik."},{"n":33,"t":"“Bu da sizin gibi, insandan başka bir şey değildir. Yediğinizden yiyor, içtiğinizden içiyor.”"},{"n":34,"t":"Eğer sizin gibi bir insana itaat ederseniz, o zaman siz kaybedersiniz."},{"n":35,"t":"O size, ölüp de toprak ve kemik yığını haline gelmişken tekrar dirileceğinizi mi söylüyor?"},{"n":36,"t":"Oysa bu size söylenenler, gerçek olmaktan ne kadar uzak!"},{"n":37,"t":"“Bizim dünya hayatından başka hayatımız yoktur. Burada ölür ve burada yaşarız. Biz, asla tekrar diriltilmeyeceğiz.”"},{"n":38,"t":"“O, Allah hakkında yalan uyduran bir kişiden başka biri değildir. Biz, ona asla inanmıyoruz.”"},{"n":39,"t":"O peygamber, “Rabbim! Beni yalanlamalarına karşılık bana yardımcı ol!” dedi."},{"n":40,"t":"“Pek yakında onlar mutlaka pişman olacaklar!”"},{"n":41,"t":"Nitekim, gerçekleşmesi kaçınılmaz olan korkunç bir ses yakalayıverdi onları! Kendilerini hemen sel süprüntüsüne çevirdik. Zâlimler topluluğunun canı cehenneme!"},{"n":42,"t":"Sonra onların ardından başka nesiller getirdik."},{"n":43,"t":"Hiçbir ümmet, ecelini ne öne alabilir, ne de erteleyebilir."},{"n":44,"t":"Sonra birbiri peşinden peygamberlerimizi gönderdik. Her ümmete peygamberi geldikçe onu hep yalanladılar. Onları birbiri peşinden yok edip, hepsini birer efsaneye çevirdik. İnanmayan millete lanet olsun!"},{"n":"45-46","t":"Sonra Mûsâ ve kardeşi Hârûn`u, Firavun ve ileri gelenlerine âyetlerimizle ve kesin delillerimizle gönderdik. Kibirlendiler ve zaten büyüklük taslayan bir topluluktular."},{"n":47,"t":"“Kavimleri bize kölelik ederken, bizim gibi olan bu iki adama inanır mıyız?”"},{"n":48,"t":"Böylece onları yalanladılar ve bu sebeple helâk edilenlerden oldular."},{"n":49,"t":"Andolsun biz Mûsâ`ya, belki onlar yola gelirler diye kitabı verdik."},{"n":50,"t":"Meryem oğlunu ve annesini de bir ders kıldık; onları yerleşmeye elverişli, suyu bulunan bir tepeye yerleştirdik."},{"n":51,"t":"Ey peygamberler! Temiz şeylerden yiyiniz, iyi işler yapınız; doğrusu ben yaptıklarınızı bilirim."},{"n":52,"t":"Şüphesiz bu insanlar bir tek ümmet olarak sizin ümmetinizdir; ben de sizin Rabbinizim. Öyle ise bana itaat ediniz."},{"n":53,"t":"Ama insanlar, aralarındaki inanç bağını keserek kendi aralarında parça parça oldular. Her grup kendilerinde bulunan ile sevinip böbürlenmektedirler."},{"n":54,"t":"Onları bir süreye kadar, gaflet ve sapıklıkları ile baş başa bırak!"},{"n":"55-56","t":"Kendilerine mal ve çocuklar vererek, onlara iyiliklerde bulunmaya acele ettiğimizi mi sanıyorlar? Hayır, farkında değiller."},{"n":"57-59","t":"Rablerine olan saygıdan dolayı kötülükten sakınanlar, Rablerinin âyetlerine inananlar, Rablerine ortak koşmayanlar,"},{"n":60,"t":"Onlar ki Rablerinin huzuruna çıkacakları korkusuyla kalpleri titreyerek verirler."},{"n":61,"t":"İşte onlar iyilikte yarışırlar."},{"n":62,"t":"Biz, herkesi ancak gücü oranında sorumlu tutarız. Katımızda hakikati konuşan bir kitap vardır, onlar haksızlığa uğratılmazlar."},{"n":63,"t":"Ama, inkârcıların kalpleri bundan habersizdir. Bundan başka onların yapageldikleri işler de vardır."},{"n":64,"t":"Sonunda şımarmış zenginlerini azapla yakaladığımız zaman feryat ederler."},{"n":65,"t":"“Bugün feryat etmeyiniz, doğrusu katımızdan bir yardım göremezsiniz.”"},{"n":"66-67","t":"“Âyetlerim size okunduğunda büyüklük taslayıp, gece ağzınıza geleni söyleyerek ardınıza dönüyordunuz.”"},{"n":68,"t":"Onlar bu Kur`ân`ı hiç düşünmediler mi? Yoksa kendilerine, daha önce geçmişteki atalarına gelmeyen bir şey mi geldi?"},{"n":69,"t":"Yoksa peygamberlerini henüz tanımadılar da, bu yüzden mi onu inkâr ediyorlar?"},{"n":70,"t":"Yoksa onda bir delilik olduğunu mu söylüyorlar? Hayır; o, kendilerine hakkı getirmiştir. Onların çoğu ise gerçeklerden hoşlanmamaktadır."},{"n":71,"t":"Eğer hak, onların arzularına uysaydı, elbette gökler ve yer ile bunlarda bulunanlar bozulur giderdi. Hayır, biz onlara şan ve şereflerini getirdik, fakat onlar kendi şereflerine sırt çevirdiler."},{"n":72,"t":"Yoksa sen onlardan bir karşılık mı istiyorsun? Rabbinin vereceği karşılık daha değerlidir. O, rızık verenlerin en iyisidir."},{"n":73,"t":"Sen onları doğru bir yola çağırıyorsun."},{"n":74,"t":"Ama âhirete inanmayanlar ısrarla yoldan çıkıyorlar."},{"n":75,"t":"Biz onlara acısak ve içinde bulundukları sıkıntıyı gidersek, yine de iyice körleşerek azgınlıklarında direnirlerdi."},{"n":76,"t":"Andolsun ki, biz onları sıkıntıya düşürdük de yine Rablerine boyun eğmediler ve niyazda bulunmadılar."},{"n":77,"t":"Sonunda onlara şiddetli bir azap kapısı açtığımız zaman, ümitsiz kalıverdiler."},{"n":78,"t":"Oysa, sizin için kulaklar, gözler ve gönüller var eden O`dur. Ne de az şükrediyorsunuz!"},{"n":79,"t":"Sizi yeryüzünde yaratıp, çoğalmanızı sağlayan O`dur ve O`nun huzurunda toplanacaksınız."},{"n":80,"t":"Dirilten de, öldüren de O`dur. Gece ile gündüzün birbiri ardından gelmesi de O`nun eseridir. Hâlâ aklınızı kullanmayacak mısınız?"},{"n":81,"t":"“Hayır; yine de öncekilerin dediklerini derler.”"},{"n":82,"t":"“Ölüp, toprak ve bir yığın kemik olduğumuzda mı diriltileceğiz? Andolsun ki, biz ve daha önce de babalarımız tehdit edilmişti; bu, öncekilerin masallarından başka bir şey değildir” demişlerdi."},{"n":83,"t":"“Ölüp, toprak ve bir yığın kemik olduğumuzda mı diriltileceğiz? Andolsun ki, biz ve daha önce de babalarımız tehdit edilmişti; bu, öncekilerin masallarından başka bir şey değildir” demişlerdi."},{"n":84,"t":"“Biliyorsanız, dünya ve içinde bulunanlar kimindir?”"},{"n":85,"t":"“Allah`ındır” diyecekler. “Öyleyse düşünmüyor musunuz?” de!"},{"n":86,"t":"“Yedi göğün Rabbi ve büyük hükümranlık tahtının sahibi kimdir?” de!"},{"n":87,"t":"“Allah`tır” diyecekler. “Öyleyse sakınmıyor musunuz?” de!"},{"n":88,"t":"“Biliyorsanız, her şeyin sahipliği ve idaresi elinde olan, koruyup kollayan fakat kendisi korunup kollanmayan kimdir?” de!"},{"n":89,"t":"“Allah`tır” diyecekler. “Öyleyse nasıl büyüleniyorsunuz?” de!"},{"n":90,"t":"Doğrusu biz onlara hakkı getirdik; onlar ise yalancılardır."},{"n":91,"t":"Allah çocuk edinmemiştir; O`nunla beraber hiçbir tanrı yoktur. Öyle olsaydı her tanrı, kendi yarattığını sevk ve idare eder, onlardan biri diğerine üstün gelmeye çalışırdı. Allah, müşriklerin yakıştırdıkları sıfatlardan uzaktır."},{"n":92,"t":"Allah, gaybı/görünmeyeni ve görüneni de bilendir. O, müşriklerin ortak koştukları şeylerden çok yücedir."},{"n":"93-94","t":"“Ey Rabbim! Eğer onlara vaad edilen azabı bana göstereceksen, beni o zâlimlerin içinde bırakma” de!"},{"n":95,"t":"Biz onlara vaad ettiğimizi sana elbette gösterebiliriz."},{"n":96,"t":"Kötülüğü, en iyi olan ile sav! Biz onların yakıştırmakta oldukları şeyi çok iyi bilmekteyiz."},{"n":97,"t":"“Rabbim! Kötü insanların kışkırtmalarından sana sığınırım.”"},{"n":98,"t":"“Tanrım! Yanımda bulunmalarından da sana sığınırım.”"},{"n":99,"t":"Sonunda onlardan biri ölümün eşiğine geldiğinde der ki; «Ya Rabb`i, beni geri çeviriniz.»"},{"n":100,"t":"“Tâ ki boşa geçirdiğim dünyada iyi iş yapayım.” Hayır! Onun söylediği bu söz, boş laftan ibarettir. Onların gerisinde ise, yeniden diriltilecekleri güne kadar süren bir engel vardır."},{"n":101,"t":"Sûra üflendiği zaman artık aralarında akrabalık bağları kalmayacaktır; birbirlerini de arayıp sormazlar."},{"n":102,"t":"Sevap tartıları ağır gelenler, işte onlar, mutluluğa erenlerdir."},{"n":103,"t":"Tartıları hafif gelenler, işte onlar, kendilerine yazık edenlerdir; çok uzun süreli cehennemde kalacaklardır."},{"n":104,"t":"Ateş onların yüzlerini yakar, dişleri sırıtıp kalır."},{"n":105,"t":"“Size âyetlerim okunurdu da, onları yalanlardınız, değil mi?”"},{"n":106,"t":"“Ey Rabbimiz! Azgınlığımız bizi yendi; biz, zâlimler topluluğu olduk.”"},{"n":107,"t":"“Ey Rabbimiz! Bizi buradan çıkar! Eğer, bir daha ettiklerimize dönersek, artık belli ki biz zâlim insanlarız.”"},{"n":108,"t":"Allah, “Sinin orada! Benimle konuşmayın!” diyecek."},{"n":"109-110","t":"“Çünkü kullarımdan bir topluluk, ‘Ey Rabbimiz! İnandık; bizi bağışla, bize merhamet et, sen çok merhametlisin` derdi de siz ise onlarla dalga geçerdiniz. Öyle ki, bu tavrınız size beni anmayı unutturmuştu. Siz onların yaptıklarına gülüyordunuz.”"},{"n":111,"t":"Ama her türlü güçlüklere göğüs germelerinden dolayı, bugün onları mükafatlandırdım. İşte ateşten kurtulup muradına erenler onlardır."},{"n":112,"t":"Allah, onlara “Yeryüzünde kaç yıl kaldınız?” diye sorar."},{"n":113,"t":"“Bir gün veya günün bir kısmı kadar kaldık. İşte, sayanlara sor!” derler."},{"n":114,"t":"“Sadece az bir süre kaldınız; keşke siz bunu bilmiş olsaydınız.”"},{"n":115,"t":"“Sizi sadece boş yere yarattığımızı ve sizin hakikaten huzurumuza geri getirilmeyeceğinizi mi sandınız?”"},{"n":116,"t":"Allah yüceler yücesi, mutlak hüküm ve egemenlik sahibidir. Nihâî gerçektir. O`ndan başka tanrı yoktur. O, hükümranlık tahtının sahibidir."},{"n":117,"t":"Kim, hakkında hiçbir delile sahip olmadığı halde Allah ile beraber başka bir tanrıya taparsa, bunun hesabını Rabbinin huzurunda verecektir. Gerçek şu ki, kâfirler kurtuluşa eremezler."},{"n":118,"t":"“Rabbim! Beni bağışla, bana merhamet et! Sen, merhamet edenlerin en iyisisin.”"}],[{"n":1,"t":"Bu, hükümlerini farz kılarak indirdiğimiz bir sûredir. Bu sûrede düşünüp öğüt alasınız diye apaçık deliller de indirdik."},{"n":2,"t":"Zina eden kadın ve zina eden erkekten her birine yüz değnek vurunuz; Allah`a ve âhiret gününe inanıyorsanız, Allah`ın cezasında onlara acıyacağınız tutmasın. Müminlerden bir grup da onlara uygulanan cezaya şahit olsun."},{"n":3,"t":"Zina eden erkek, ancak zina eden veya müşrik olan bir kadınla evlenebilir. Zina eden kadınla da ancak zina eden veya müşrik olan erkek evlenir. Bu durum, müminlere çirkin gösterilmiştir."},{"n":4,"t":"Namuslu kadınlara zina isnadında bulunup, sonra bunu ispat için dört şahit getiremeyenlere seksen değnek vurunuz ve artık onların şahitliğini hiçbir zaman kabul etmeyiniz. Onlar fâsıktırlar."},{"n":5,"t":"Ancak, bundan sonra tövbe edip ıslah olanlar müstesnadır. Allah çok bağışlayıcı ve merhamet sahibidir."},{"n":6,"t":"Eşlerini zina ile suçlayıp kendilerinden başka şahitleri bulunmayan kimselere gelince, onlardan her birinin şahitliği, kendisinin mutlaka doğru söyleyenlerden olduğuna dört defa Allah`ı şahit tutmasıdır."},{"n":7,"t":"Beşinci yemininde, eğer yalan söyleyenlerden ise, Allah`ın lanetinin kendi üzerinde olmasını diler."},{"n":8,"t":"Kadının da dört defa Allah`ı şahit tutup, kocasının mutlaka yalan söyleyenlerden olduğuna şahitlik etmesi, kendisinden cezayı kaldırır."},{"n":9,"t":"Beşinci yemininde, eğer kocası doğrulardan ise, Allah`ın gazabının kendi üzerine olmasını diler."},{"n":10,"t":"Allah`ın size yönelik lütfu ve rahmeti olmasaydı ve Allah, tövbeleri çok kabul eden bir hikmet sahibi olmasaydı, ne yapardınız?"},{"n":11,"t":"O iftirayı atanlar şüphesiz içinizden bir gruptur. Bu olayın, hakkınızda bir kötülük olduğunu sanmayınız. Tam aksine sizin için daha hayırlı olmuştur. Onlardan her biri işlediği suçun cezasını çekecektir. İçlerinden önderlik yapıp suçun büyüğünü yüklenen kişiye ise, büyük bir azap vardır."},{"n":12,"t":"İftirayı duyduğunuzda, inanan erkek ve kadınlar kendi kendilerine iyi zanda bulunup da, “Bu, apaçık bir iftiradır” demeleri gerekmez miydi?"},{"n":13,"t":"İftira edenlerin buna dört şahit getirmeleri gerekirdi. Onlar bu şahitleri getirmedikleri sürece Allah katında yalancıdırlar."},{"n":14,"t":"Allah`ın size dünyada ve âhirette lütuf ve merhameti olmasaydı, bu iftiradan dolayı başınıza kesinlikle büyük bir felaket gelecekti."},{"n":15,"t":"Çünkü siz bu olayı dillerinize dolayıp, hakkında herhangi bir bilginiz olmadığı halde aranızda yayıyordunuz ve onu basit bir hadise sayıyordunuz. Oysa bu, Allah katında büyük bir olaydır."},{"n":16,"t":"Bu iftirayı duyduğunuzda, “Bunu dilimize dolamak bize yakışmaz; bu, büyük bir iftiradır” demeliydiniz."},{"n":17,"t":"İnanmış kişiler iseniz, Allah bir daha öyle bir şeye dönmemeniz için size öğüt veriyor."},{"n":18,"t":"Allah bu suretle âyetlerini size açıklıyor. Allah, her şeyi bilir; hikmet sahibidir."},{"n":19,"t":"İnananlar arasında çirkin şeylerin yayılmasını isteyen kimseler için dünyada da âhirette de çetin bir azap vardır. Allah bilir, siz bilmezsiniz."},{"n":20,"t":"Allah`ın lütuf ve merhameti size olmasaydı, bir de Allah son derece şefkat ve merhametli olmasaydı, haliniz nice olurdu!"},{"n":21,"t":"Ey inananlar! Şeytanın adımlarını izlemeyiniz! Kim şeytanın ardına takılırsa, bilsin ki o, hayâsızlığı ve fenâlığı emreder. Allah`ın size lütuf ve merhameti olmasaydı, hiçbiriniz asla temize çıkamazdı. Fakat Allah dileyeni temize çıkarır. Allah her şeyi işitir; her şeyi bilir."},{"n":22,"t":"Sizden fazilet ve servet sahibi kimseler, yakınlığı bulunanlara, yoksullara ve Allah yolunda hicret edenlere bir şey vermemeye yemin etmesinler; affetsinler, hoş görsünler. Allah`ın sizi bağışlamasını istemez misiniz? Allah, bağışlayandır; merhamet edendir."},{"n":23,"t":"İffetli, saf ve namuslu, inanmış kadınlara zina iftirasında bulunanlar, dünya ve âhirette lanetlenmişlerdir. Onlar için büyük bir azap vardır."},{"n":24,"t":"O gün, yaptıklarından dolayı dilleri, elleri ve ayakları kendileri aleyhinde tanıklık edecektir."},{"n":25,"t":"O gün, Allah onların hak ettikleri cezalarını eksiksiz verecektir. Onlar kesin olarak, Allah`ın apaçık gerçek olduğunu bileceklerdir."},{"n":26,"t":"Kötü kadınlar kötü erkekler için, kötü erkekler de kötü kadınlar içindir. Temiz kadınlar temiz erkekler için, temiz erkekler de temiz kadınlar içindir. Onlar, kötülerin nitelendirmelerinden uzaktırlar. Onlar için bağışlama ve güzel bir rızık vardır."},{"n":27,"t":"Ey iman edenler! Kendi evlerinizden başka evlere, sahiplerinden izin almadan ve onlara selâm vermeden girmeyiniz. Bu, sizin için daha iyidir, her halde bunu düşünüp anlarsınız."},{"n":28,"t":"Orada bir kimse bulamadıysanız, size izin verilinceye kadar oraya girmeyiniz. Eğer size, “Geri dönün!” denilirse, hemen dönünüz. Çünkü bu, sizin için daha erdemli bir davranıştır. Allah yaptıklarınızı bilir."},{"n":29,"t":"İçinde kendinize ait eşyaların bulunduğu, oturulmayan evlere girmenizde herhangi bir sakınca yoktur. Allah, sizin açığa vurduklarınızı da, gizledikleriniz de bilir."},{"n":30,"t":"Mümin erkeklere, harama bakmamalarını ve iffetlerini korumalarını söyle! Çünkü bu, kendileri için daha güzel bir davranıştır. Şüphesiz Allah, onların yaptıklarından haberdardır."},{"n":31,"t":"Mümin kadınlara da, gözlerini haramdan sakınmalarını ve namuslarını korumalarını söyle! Görünmesi zorunlu olanlar dışında, ziynetlerini teşhir etmesinler. Başörtülerini yakalarının üzerine salsınlar. Kocaları, babaları, kayınpederleri, kendi oğulları, kocalarının oğulları, erkek kardeşleri, erkek kardeşlerinin oğulları, kız kardeşlerinin oğulları, mümin kadınlar, ellerinin altında bulunanlar; erkeklerden, ailenin kadınına şehvet duymayan hizmetçi ve tâbi kimseler, yahut henüz kadınların gizli kadınlık özelliklerinin farkında olmayan çocuklardan başkasına ziynetlerini göstermesinler. Gizlemekte oldukları ziynetleri anlaşılsın diye ayaklarını yere vurmasınlar. “Ey müminler! Hep birden Allah`a tövbe ediniz ki kurtuluşa eresiniz.”"},{"n":32,"t":"İçinizdeki bekârları, kölelerinizden ve câriyelerinizden evlenmeye elverişli olanları evlendiriniz. Yoksulluk içindeyseler, Allah onları lütfu ile zenginleştirir. Allah lütfu bol olandır; her şeyi bilendir."},{"n":33,"t":"Evlenmeye imkanı olmayanlar ise, Allah kendilerini lütfu ile zenginleştirene kadar iffetli davransınlar. Kölelerinizden, hür olmak için bedel vermek isteyenlerin, onlarda bir iyilik görürseniz, bedel vermelerini kabul ediniz. Onlara, Allah`ın size verdiği maldan veriniz. Dünya hayatının geçici menfaatini elde etmek için, özellikle iffetli olmak isteyen genç kızlarınızı fuhşa zorlamayınız. Kim onları buna zorlarsa, Allah, hiç şüphesiz zorlayanı değil, zorlanan kadınları bağışlar; merhamet eder."},{"n":34,"t":"Andolsun ki size, açıklayıcı âyetler, sizden önce gelip geçenlerden bir örnek ve saygılı olanlara bir öğüt indirdik."},{"n":35,"t":"Allah, göklerin ve yerin nûrudur. O`nun nûru, içinde kandil bulunan bir oyuğa/lambaya benzer. Kandil, bir cam içerisindedir. Cam, sanki inciden bir yıldızdır. Ne doğuya ne batıya ait olan mübarek bir zeytin ağacının yağından yakılır. Öyle ki, ateş değmese de neredeyse yağı ışık verir. O, nûr üstüne nûrdur. Allah dileyen kimseyi nûruna iletir. Allah, insanlara örnekler verir. Allah, her şeyi bilir."},{"n":36,"t":"Bu kandil birtakım evlerdedir ki, Allah o evlerin yücelmesine ve içlerinde isminin anılmasına izin vermiştir. Orada sabah akşam O`nu tesbih ederler/anarlar."},{"n":37,"t":"Toptan alım-satımların, ithalat ve ihracatın ve çarşılarda, pazarlardaki alışverişlerin, ticarî muamelelerin, kendilerini Allah’ı zikirden, Allah’ın övünç kaynağı kelâmını okumaktan, namazı adâbına riayet ederek aksatmadan kılmaktan, vicdanlarını, servetlerini, sosyal bünyelerini arındıran, berekete vesile olan zekâtı vermekten alıkoyamayacağı yiğit, samimi dindar insanlar, Allah’ı tesbih ederler. Onlar akılların, kalplerin ve gözlerin allak bullak olduğu bir günden korkarlar."},{"n":38,"t":"Allah, onları işlediklerinin en güzeliyle ödüllendirir ve lütfundan onlara fazlasıyla verir. Allah, dilediğini hesapsız şekilde rızıklandırır."},{"n":39,"t":"İnkâr edenlerin amelleri, engin çöllerdeki serap gibidir. Susayan kimse onu su sanır; fakat oraya geldiğinde hiçbir şey bulamaz. Orada Allah`ın kudretini bulur ve O da hesabını görür. Allah, hesabı çabuk görendir."},{"n":40,"t":"Yahut engin bir denizdeki yoğun karanlıklar gibidir. Onu, üst üste dalgalar ve dalgaların üstünde bulutlar örter; karanlıklar üstünde karanlıklar, insan elini dışarı çıkarttığı zaman, neredeyse onu göremez bile. Allah`ın ışık vermediği kimsenin ışığı olmaz."},{"n":41,"t":"Göklerde ve yerde olan kimselerin, sıra sıra uçan kuşların, Allah`ı yücelttiğini görmez misin? Her biri kendi duasını ve yüceltmesini bilir. Allah, onların yaptıklarını bilendir."},{"n":42,"t":"Göklerin ve yerin egemenliği Allah`ındır. Dönüş Allah`adır."},{"n":43,"t":"Görmez misiniz ki Allah, bulutları sürüyor, sonra onları bir araya getirip sonra üst üste yığıyor. Sen de onların arasından yağmur yağdığını görüyorsun. Gökten, içinde dolu bulunan dağlar gibi bulutlar indirir. Dilediğine onu uğratır, dilediğinden de uzak tutar. Bulutların şimşeğinin parıltısı neredeyse gözlerini kör edecektir!"},{"n":44,"t":"Allah geceyi ve gündüzü birbiri ardından getirir. Doğrusu, gözlem yapanlar için bunda dersler vardır."},{"n":45,"t":"Allah, bütün canlıları sudan yaratmıştır. Kimi karnı üzerinde sürünür, kimi iki ayakla yürür, kimi de dört ayakla yürür. Allah dilediğini yaratır. Doğrusu Allah`ın gücü her şeye yeter."},{"n":46,"t":"Andolsun ki biz her şeyi güzelce açıklayan âyetler indirdik. Allah, dileyeni doğru yola iletir."},{"n":47,"t":"Bazı kimseler «Allah`a ve Peygamber`e inandık ve direktiflerine uymayı kabul ettik» derler. Fakat bazıları bu sözlerinden sonra sırt çevirirler. Bunlar mü`min değildirler."},{"n":48,"t":"Zira onlar aralarında hüküm versin diye Allah`a ve O`nun Rasulü`ne çağrıldıklarında, hiç değilse bir kısmı hemen yüz çeviriverirler;"},{"n":49,"t":"Ama, haklı çıkacaklarını bilirlerse, başlarını eğerek gelirler."},{"n":50,"t":"Kalplerinde hastalık mı var, yoksa şüphe mi ediyorlar? Yahut Allah`ın ve Peygamberinin onlara haksızlık yapacağından mı korkuyorlar? Hayır! Onlar sadece haksızlık etmektedirler."},{"n":51,"t":"Aralarında hüküm verilmek üzere Allah`a ve Peygamberine çağırıldıkları vakit “İşittik, itaat ettik” demek, ancak inananların sözüdür. İşte başarıya erenler onlardır."},{"n":52,"t":"Allah`a ve Peygamberine itaat eden, Allah`ı sayan ve O`na saygılı olan kimseler, işte onlar kurtulanlardır."},{"n":53,"t":"“Yemin etmeyiniz, itaatiniz bilinmektedir. Allah yaptıklarınızdan haberdardır.”"},{"n":54,"t":"“Allah`a itaat ediniz, Peygambere itaat ediniz! Eğer yüz çevirirseniz biliniz ki, onun görevi tebliğ vazifesini yapmak, sizin vazifeniz de sorumluluklarınızı yapmanızdır. Eğer ona itaat ederseniz doğru yolu bulursunuz. Peygambere düşen, sadece apaçık bildirimde bulunmaktır.”"},{"n":55,"t":"Allah, onlardan öncekilere yaptığı gibi, sizden inanıp iyi amellerde bulunanları da yeryüzünde iktidar sahibi kılacağını, kendileri için seçtiği dini yerleştireceğini ve korkularından sonra onları güvene kavuşturacağını vaad etmiştir. “Onlar bana kulluk eder ve hiçbir şeyi ortak koşmazlar. Bundan sonra kimler inkâr ederse, işte onlar yoldan çıkmışlardır.”"},{"n":56,"t":"Namazı kılınız, zekâtı veriniz, Peygamber`e itaat ediniz ki merhamet göresiniz."},{"n":57,"t":"İnkâr edenlerin yeryüzünde Allah`ı âciz bırakacaklarını sanmayasınız! Onların varacağı yer cehennemdir. Orası ne kötü bir varış yeridir!"},{"n":58,"t":"Ey inananlar! Ellerinizin altında olan köle ve cariyeler ve sizden henüz ergenliğe ermemiş çocuklar, sabah namazından önce, öğle vaktinde soyunduğunuzda ve yatsı namazından sonra yanınıza gireceklerinde üç defa izin istesinler. Bu vakitler, örtülmesi gereken yerlerinizin açık bulunabileceği üç vakittir. Bu vakitlerin dışında birbirinizin yanına girip çıkmakta size de, onlara da bir sorumluluk yoktur. Allah, hükümlerini size böyle açıklar. Allah her şeyi bilendir; hikmet sahibidir."},{"n":59,"t":"Çocuklarınız ergenlik çağına gelince, büyüklerinizin izin istediği gibi, onlar da izin istesinler. Allah size ilkelerini böyle açıklar. Allah bilgindir; hikmet sahibidir."},{"n":60,"t":"Evlenmeyi arzu etmeyen, çocuktan kesilmiş kadınlara, süslerini açığa vurmamak şartıyla, dış giysilerini çıkarmaktan ötürü sorumluluk yoktur; ama iffetli davranmaları kendileri için daha iyi olur. Allah her şeyi işitir; her şeyi bilir."},{"n":61,"t":"Evlerinizde veya babalarınızın, annelerinizin, erkek kardeşlerinizin, kız kardeşlerinizin, amcalarınızın, halalarınızın, dayılarınızın, teyzelerinizin veya kahyası olup anahtarları elinizde olan evlerde ya da can arkadaşlarınızın evlerinde yemek yemenizde size de, kör olana da zorluk yok, topal olana da, hasta olana da zorluk yoktur. Toplu olarak veya ayrı ayrı yemenizde de size bir zorluk yoktur. Evlere girdiğiniz zaman, birbirinize Allah katından mutlu, hoş yaşam dileyerek selâm veriniz. Allah, hükümleri düşünürsünüz diye size böyle açıklıyor."},{"n":62,"t":"Müminler, ancak Allah`a ve Peygamberine inanmış kimselerdir. Onlar Peygamber ile ortak bir iş üzerindeyken, ondan izin istemedikçe bırakıp gitmezler. Senden izin isteyenler, gerçekten Allah`a ve Peygamberine iman etmiş kimselerdir. Öyleyse bazı işleri için senden izin istediklerinde, sen de onlardan dilediğine izin ver; onlar için Allah`tan af dile; Allah affedicidir; merhamet sahibidir."},{"n":63,"t":"Ey Müminler! Peygamberi kendi aranızda birbirinizi çağırır gibi çağırmayınız. İçinizden, sıvışıp gidenleri elbette Allah bilmektedir. Bundan dolayı, onun emrine aykırı davrananlar, başlarına bir belâ gelmesinden veya kendilerine çok elemli bir azap isabet etmesinden sakınsınlar."},{"n":64,"t":"Dikkat ediniz, göklerde ve yerde ne varsa hepsi Allah`ındır. O, sizin ne durumda olduğunuzu bilir. O`na döndürüldükleri gün ne yaptıklarını insanlara haber verecektir. Allah, her şeyi bilir."}],[{"n":1,"t":"Bütün insanlara bir uyarı olsun diye kuluna, hakla bâtılı ayıran kitabı indiren Allah, yüceler yücesidir."},{"n":2,"t":"Göklerin ve yerin mülkiyeti yalnız O`na aittir. Hiçbir zaman çocuk edinmemiştir. Hükümranlığında O`nun hiçbir ortağı da olmamıştır. O her şeyi yaratmış ve her şeye belli bir şekil vermiştir."},{"n":3,"t":"Putperestler Allah`ı bırakıp hiçbir şey yaratamayan, kendileri yaratılmış olan ve kendilerine ne zarar ne de fayda verebilen, ne öldürmeye ne yaşatmaya ve ne de tekrar diriltmeye gücü yeten putları, tanrı edindiler."},{"n":4,"t":"İnkâr edenler, “Bu Kur`ân, Muhammed`in uydurduğu bir yalandır. Bu uydurmada ona başka bir topluluk da yardım etmiştir” dediler. Kâfirler, bu sözleriyle haksızlık edip yalan söylemişlerdir."},{"n":5,"t":"Kâfirler, “Kur`ân âyetleri, öncekilerin masallarıdır. Onları kendisi yazdırmıştır. Bunlar sabah-akşam kendisine okunmaktadır” dediler."},{"n":6,"t":"“Kur`ân`ı, göklerde ve yerdeki sırları bilen Allah indirmiştir. Şüphesiz Allah, çok affedicidir; çok merhametlidir.”"},{"n":7,"t":"“Bu ne biçim peygamber ki, bizler gibi yemek yiyor, çarşılarda dolaşıyor? O`na kendisiyle birlikte, uyarıcı olarak görünür bir melek gönderilseydi ya."},{"n":8,"t":"“Yahut kendisine bir hazine verilseydi veya meyvelerinden yiyeceği bir bahçesi olsaydı ya!” Bu zâlimler, “Sizler sırf büyülenmiş bir adama uyuyorsunuz” dediler."},{"n":9,"t":"“Ey Peygamber! Bak, nasıl böyle örnekler verip sapıttılar. Artık onlar hiçbir çıkış yolu bulamazlar.”"},{"n":10,"t":"Dilerse sana bunların dediklerinden daha iyisini, içinden ırmaklar akan bahçeleri verebilecek ve senin için köşkler yapabilecek olan Allah, yüceler yücesidir."},{"n":11,"t":"Doğrusu onlar, kıyameti de yalanlamışlardı. Biz ise, kıyameti inkâr edenler için alevli bir ateş hazırladık."},{"n":12,"t":"O ateş uzaktan kendilerine göründüğünde, onun kaynama sesini ve uğultusunu işitirler."},{"n":13,"t":"Elleri boyunlarına bağlı olduğu halde orada dar bir yere atıldıklarında, ölümü çağırırlar."},{"n":14,"t":"“Bugün yalnız bir defa yok olmayı istemeyiniz. Aksine birçok defa yok olmayı isteyiniz.”"},{"n":15,"t":"“Bu mu daha iyi, yoksa takvâ sahiplerine vaad edilen sürelilik cenneti mi? Orası, onlar için bir ödül ve bir varış yeridir.”"},{"n":16,"t":"“Onlar için orada süreli kalmak üzere diledikleri her şey vardır. İşte bu, Rabbinin üzerine aldığı ve yerine getirilmesi istenen bir sözdür.”"},{"n":17,"t":"Bu kullarımı siz mi saptırdınız, yoksa kendileri mi doğru yoldan saptılar?”"},{"n":18,"t":"“Senin şanın yücedir, senden başka dostlar edinmek bize yaraşmaz; fakat sen onlara ve atalarına o kadar bol nimet verdin ki, sonunda seni anmayı unuttular ve helâk olmayı hak eden bir topluluk oldular.”"},{"n":19,"t":"İşte, tanrı dedikleriniz de sizi yalanladılar. Artık ne azabı geri çevirmeye gücünüz yeter, ne de bir yardım bulabilirsiniz! İçinizden, haksızlık eden kimseye büyük bir azap tattırırız."},{"n":20,"t":"Senden önce gönderdiğimiz bütün peygamberler de yemek yerlerdi, çarşılarda gezerlerdi. Biz, birbirinizle sizi imtihan ediyoruz, bakalım sabredecek misiniz? Rabbin her şeyi görmektedir."},{"n":21,"t":"Bizimle karşılaşmayı ummayanlar/inanmayanlar, “Bize ya melekler indirilmeli, ya da Rabbimizi görmeliyiz” derler. Andolsun ki kendi kendilerini büyük gördüler, azgınlıkta çok ileri gittiler."},{"n":22,"t":"Melekleri görecekleri gün, işte o gün, suçlulara hiçbir sevinç haberi yoktur. Melekler, “Müjde size yasaktır, yasak!” derler."},{"n":23,"t":"Yaptıkları her işi ele alıp, hepsini değersizleştireceğiz."},{"n":24,"t":"O gün, cennetlikler en iyi bir karargâh ve en güzel bir konaktadırlar."},{"n":25,"t":"O gün gök yarılıp parçalanır, bulutlar ortaya çıkar ve melekler bölük bölük indirilirler."},{"n":26,"t":"O gün gerçek egemenlik sadece Rahmân`a aittir. İnkârcılara çok zor bir gün olacaktır."},{"n":27,"t":"“Âh, keşke peygamberin yolunu tutsaydım!”"},{"n":28,"t":"“Vah bana, keşke falancayı dost edinmeseydim!”"},{"n":29,"t":"“Çünkü Kur`ân bana gelmişken, gerçekten o, beni Kur`ân`dan uzaklaştırdı. Şeytan, insanı yüzüstü bırakıp rezil rüsvâ eder.”"},{"n":30,"t":"“Ey Rabbim! Kavmim bu Kur`ân`ı terk edilmiş bıraktılar.”"},{"n":31,"t":"İşte biz böylece her peygamber için suçlulardan düşmanlar var ettik. Hidayet verici ve yardımcı olarak Rabbin sana yeter."},{"n":32,"t":"İnkâr edenler, “Kur`ân ona bir defada topluca indirilmeli değil miydi?” dediler. Biz onu senin kalbine iyice yerleştirmek için böylece yaptık ve onu tane tane okuduk."},{"n":33,"t":"Onların sana getirdikleri hiçbir örnek yoktur ki, sana doğrusunu ve daha açığını getirmeyelim."},{"n":34,"t":"Yüzüstü cehenneme sürülüp toplanacak olanlar; işte onların yerleri en kötü yer, yolları en sapık yoldur."},{"n":35,"t":"Andolsun biz, Mûsâ`ya kitabı verdik, kardeşi Hârûn`u da ona yardımcı tayin ettik."},{"n":36,"t":"“Âyetlerimizi yalanlayan o topluma gidiniz!” Sonunda biz onları yerle bir ettik."},{"n":37,"t":"Nûh`un toplumunu da hatırla! Onlar peygamberlerini yalanladıklarında onları suda boğduk ve kendilerini insanlara ders yaptık. Zâlimlere acıklı bir azap hazırladık."},{"n":38,"t":"Ve Ad ve Semud kavmi, Dess sakinleri ve bunlar arasında yaşamış olan bir çok nesil de (öyle oldu)."},{"n":39,"t":"Bunların her birini bilinen örneklerle uyarıp, hepsini helâk ettik."},{"n":40,"t":"Andolsun müşrikler, felâket yağmurunun helâk ettiği o ülkeye uğradılar. Orayı görmediler mi? Doğrusu onlar, öldükten sonra dirileceklerini beklemiyorlardı."},{"n":41,"t":"“Allah`ın, peygamber olarak gönderdiği bu mu?”"},{"n":42,"t":"“Şâyet tanrılarımıza inanmakta direnmeseydik, az kalsın bizi ilâhlarımızdan saptıracaktı.” Azabı gördükleri zaman, asıl kimin yolunun sapık olduğunu bileceklerdir!"},{"n":43,"t":"Nefsinin arzusunu tanrı edineni gördün mü? Sen ona koruyucu olabilir misin?"},{"n":44,"t":"Yoksa sen, onların büyük çoğunluğunun gerçekten senin davetini dinleyeceğini, yahut akıllarını kullanacaklarını mı sanıyorsun? Onlar ancak hayvan gibidirler. Hatta onlar yolca daha da sapıktırlar."},{"n":45,"t":"Rabbinin gölgeyi nasıl uzattığını görmedin mi? Eğer dileseydi, onu elbet hareketsiz kılardı. Sonra biz, güneşi ona delil kıldık."},{"n":46,"t":"Sonra onu yavaş yavaş kendimize çekmekteyiz."},{"n":47,"t":"Sizin için geceyi örtü, uykuyu istirahat kılan, gündüzü de çalışıp rızık arama vakti yapan O`dur."},{"n":"48-49","t":"Rüzgârları rahmet yağmurunun önünde müjdeleyici olarak gönderen O`dur. Ölü toprağı diriltmemiz ve yarattığımız hayvan ve insanlara su vermemiz için gökten tertemiz su indiriyoruz."},{"n":50,"t":"Gerçek şu ki, düşünüp öğüt almaları için suyu, ülkeler arasında bir nizama göre dağıtmışızdır. Buna rağmen insanların çoğu nankörlükte direnmiştir."},{"n":51,"t":"Biz, her ülkeye bir uyarıcı göndermeyi diledik."},{"n":52,"t":"Sen inkârcılara boyun eğme ve Kur`ân ile onlara karşı büyük cihad ile cihad et!"},{"n":53,"t":"Birinin suyu tatlı ve serinletici, diğerininki tuzlu ve acı olan iki denizi salıverip, aralarında da karışmalarını önleyen bir perde koyan, Allah`tır."},{"n":54,"t":"İnsanı sudan yaratarak ona soy sop veren de O`dur. Rabbinin her şeye gücü yeter."},{"n":55,"t":"Böyle iken, Allah`ı bırakıp kendilerine ne fayda ne de zarar verebilen şeylere kulluk ediyorlar. Zaten kâfir, Rabbine sırtını dönen kişidir."},{"n":56,"t":"Biz seni, ancak müjdeleyici ve uyarıcı olarak gönderdik."},{"n":57,"t":"“Bunun için, sizden, Rabbine doğru bir yol tutmayı isteyen kimseler olmanız dışında herhangi bir karşılık istemiyorum.”"},{"n":58,"t":"Ölümsüz ve daima diri olan Allah`a güvenip dayanınız. O`nu övgü ile anınız! Kullarının günahlarını O`nun bilmesi yeter."},{"n":59,"t":"Gökleri, yeri ve ikisinin arasındakileri altı devirde/evrede yaratan, sonra hükümranlığı yetkisine alan Rahmân`dır. Bunu bir bilene sor!"},{"n":60,"t":"Onlara, “Rahmân`a secde ediniz!” denildiğinde, “Rahmân da neymiş! Bize emrettiğin şeye secde eder miyiz hiç?” derler ve bu emir onların nefretini arttırır."},{"n":61,"t":"Gökte burçları var eden, onların ortasında bir ışık kaynağı ve nurlu bir ay barındıran Allah, yüceler yücesidir."},{"n":62,"t":"Ders almak veya şükretmek isteyen kimseler için gece ile gündüzü birbiri ardınca getiren de O`dur."},{"n":63,"t":"Rahmân`ın has kulları yeryüzünde vakarla yürürler. Cahil kimseler onlara laf attığında, “Selâm” derler."},{"n":64,"t":"Gecelerini, Rablerine secde ederek ve ayakta durarak geçirirler."},{"n":65,"t":"“Ey Rabbimiz! Bizden cehennem azabını uzaklaştır. Doğrusu onun azabı devamlıdır.”"},{"n":66,"t":"Gerçekten, orası ne kötü bir yer ve ne kötü bir duraktır!"},{"n":67,"t":"Onlar mallarını harcadıklarında israfa gitmezler, cimrilik de yapmazlar. Bu ikisi arasında orta bir yol tutarlar."},{"n":68,"t":"Onlar, Allah ile birlikte başka bir tanrıya kulluk etmezler. Haksız yere Allah`ın haram kıldığı cana kıymazlar. Zina etmezler. Kim bunları yaparsa cezasını bulur."},{"n":69,"t":"Kıyamet günü onun azabı kat kat arttırılır. Orada horlanmış olarak çok uzun süreli kalacaktır."},{"n":70,"t":"Ancak tövbe eden, inanan ve yararlı iş yapanlar hariç. Allah onların kötülüklerini iyiliklerle değiştirecektir. Allah, çok bağışlayıcıdır; çok merhametlidir."},{"n":71,"t":"Kim tövbe eder ve yararlı iş yaparsa bilsin ki onun tövbesi kesinlikle Allah`a ulaşacaktır."},{"n":72,"t":"yalan ve sahte olandan şahitlik etmezler; yararsız ve anlamsız olan şeylerle karşılaştıklarında vakarla geçip giderler."},{"n":73,"t":"Rabblerinin âyetleri kendilerine hatırlatıldığında, kulaklarını kapatarak ve gözlerini yumarak onları görmezlikten gelmezler."},{"n":74,"t":"Onlar, “Ey Rabbimiz! Bize gözümüzü aydınlatacak eşler, çocuklar bağışla ve bizi, Allah`a saygılı olanlara önder yap!” derler."},{"n":75,"t":"İşte onlar, sabrettiklerinden dolayı, cennetin en yüksek dereceleriyle ödüllendirilirler ve orada selâm ve sevgi ile karşılanacaklardır."},{"n":76,"t":"Çok uzun süreli olarak orada kalacaklardır. Orası ne güzel bir karargah ve ne güzel bir yerdir!"},{"n":77,"t":"“Eğer dualarınız olmasaydı Rabbim sizi ne yapardı? Fakat siz yalanladınız; bu yalanlamanız, yakanızı bırakmayacaktır.”"}],[{"n":1,"t":"Tâ, sîn, mîm."},{"n":2,"t":"Bunlar, apaçık kitabın âyetleridir."},{"n":3,"t":"Sen, inanmıyorlar diye neredeyse kendini helâk edeceksin."},{"n":4,"t":"Dilersek onlara gökten bir mucize indiririz de mecbur kalıp boyun eğerler."},{"n":5,"t":"Onlara Rahmân`dan hiçbir yeni hatırlatma gelmez ki, ondan yüz çevirmesinler."},{"n":6,"t":"Nitekim Kur`ân`ı da yalanladılar. Ama alay edip durdukları şeyin haberleri yakında onlara gelecektir."},{"n":7,"t":"Yeryüzüne bir bakmazlar mı? Orada her güzel çiftten nice bitkiler yetiştirdik."},{"n":8,"t":"Şüphesiz bunda yaratıcının varlığına dair kesin delil vardır; ama çoğu iman etmezler."},{"n":9,"t":"Şüphesiz senin Rabbin, mutlak galip ve sonsuz merhamet sahibidir."},{"n":"10-11","t":"Hani Rabbin Mûsâ`ya, “O zâlimler topluluğuna, Firavun`un kavmine git! Hâlâ sakınmayacaklar mı onlar?” diye seslenmişti."},{"n":12,"t":"“Ey Rabbim! Doğrusu, beni yalanlamalarından korkuyorum.”"},{"n":13,"t":"“Bu durumda içim daralır, dilim dönmez. Onun için Hârûn`a da peygamberlik ver!”"},{"n":14,"t":"“Onlara karşı benim bir suçum var. Beni öldürmelerinden korkuyorum.”"},{"n":15,"t":"“Hayır! Asla endişe etme! İkiniz, mucizelerimizle gidiniz. Şüphesiz biz, sizinle beraberiz, işitmekteyiz.”"},{"n":16,"t":"‘Biz, âlemlerin Rabbinin peygamberleriyiz; İsrâiloğullarını bizimle beraber gönder!` deyiniz.”"},{"n":17,"t":"‘Biz, âlemlerin Rabbinin peygamberleriyiz; İsrâiloğullarını bizimle beraber gönder!` deyiniz.”"},{"n":18,"t":"“Seni küçükken elimizde büyütmedik mi? Yanımızda yıllarca kalmadın mı? Oysa sen sonunda yapacağını yaptın. Sen nankörlerdensin.”"},{"n":19,"t":"“Seni küçükken elimizde büyütmedik mi? Yanımızda yıllarca kalmadın mı? Oysa sen sonunda yapacağını yaptın. Sen nankörlerdensin.”"},{"n":"20-22","t":"Mûsâ, “O işi, daha ne yaptığımı bilmez biriyken işledim. Bu yüzden sizden korkup kaçtım; sonra, Rabbim bana ilim ve hikmet verip beni peygamberlerden kıldı. Başıma kaktığın bu nimet, İsrâiloğulları`nı kendine köle yapmandan dolayıdır” dedi."},{"n":23,"t":"“Âlemlerin Rabbi dediğin de nedir?”"},{"n":24,"t":"“Eğer işin gerçeğini düşünüp anlayan kişiler olsanız; O, göklerin, yerin ve ikisi arasında bulunanların Rabbidir.”"},{"n":25,"t":"Firavun, etrafındakilere, “Duymuyor musunuz?” dedi."},{"n":26,"t":"Mûsâ, “O, sizin de, evvelki atalarınızın da Rabbidir” dedi."},{"n":27,"t":"Firavun, “Size gönderilen peygamberiniz kesinlikle delidir” dedi."},{"n":28,"t":"Mûsâ, “ Eğer düşünüp anlarsanız O, doğunun, batının ve ikisinin arasında bulunanların Rabbidir” dedi."},{"n":29,"t":"Firavun, “Eğer benden başka tanrı edinirsen, seni kesinlikle hapsederim” dedi."},{"n":30,"t":"Mûsâ, “Sana apaçık bir mucize getirirsem de mi?” dedi."},{"n":31,"t":"Firavun, “Eğer doğru söylüyorsan, haydi getir onu!” dedi."},{"n":32,"t":"Bunun üzerine Mûsâ, asasını yere attı. Bir de ne görsünler, asa apaçık koca bir yılan oluverdi."},{"n":33,"t":"Elini de koynundan çıkardı, bir de ne görsünler; bembeyaz olmuş."},{"n":"34-35","t":"Firavun çevresindeki ileri gelenlere, “Bu, doğrusu, çok bilgili bir sihirbazdır!” dedi. “Sizi sihriyle yurdunuzdan çıkarmak istiyor. Şimdi ne buyurursunuz?”"},{"n":"36-38","t":"İleri gelenler dediler ki, “Onu ve kardeşini alıkoy! Şehirlere haberciler sal! Bütün usta büyücüleri çağırsınlar.” Büyücüler, belli bir günün tayin edilen vaktinde bir araya getirildi."},{"n":39,"t":"Halk da, “Haydi, gelmiyor musunuz?” diye davet edildi."},{"n":40,"t":"Halk, “Sihirbazlar üstün gelirse, biz de belki onlara uyarız” dediler."},{"n":"41-42","t":"Sihirbazlar geldiklerinde, Firavun`a, “Biz üstün gelirsek, bize bir ödül vereceksin, değil mi?” dediler. Firavun, “Evet, o taktirde siz gözde kimselerden olacaksınız” dedi."},{"n":43,"t":"“Ne atacaksanız atın!” dedi. Onlar da iplerini ve değneklerini attılar ve “Firavun`un onuru için elbette bizler galip geleceğiz” dediler. Sonra Mûsâ asasını yere bıraktı. Bir de ne görsünler, onların sihirlerini yutuveriyor."},{"n":44,"t":"“Ne atacaksanız atın!” dedi. Onlar da iplerini ve değneklerini attılar ve “Firavun`un onuru için elbette bizler galip geleceğiz” dediler. Sonra Mûsâ asasını yere bıraktı. Bir de ne görsünler, onların sihirlerini yutuveriyor."},{"n":45,"t":"“Ne atacaksanız atın!” dedi. Onlar da iplerini ve değneklerini attılar ve “Firavun`un onuru için elbette bizler galip geleceğiz” dediler. Sonra Mûsâ asasını yere bıraktı. Bir de ne görsünler, onların sihirlerini yutuveriyor."},{"n":"46-48","t":"Bu durum karşısında sihirbazlar hemen secdeye kapanarak, “Biz, âlemlerin Rabbine inandık” dediler. “Mûsâ`nın ve Hârûn`un Rabbine.”"},{"n":49,"t":"Firavun, “Ben size izin vermeden ona inanıyorsunuz, öyle mi?” diye çıkıştı. “Doğrusu o, size sihri öğreten büyüğünüzdür. Andolsun, yakında bileceksiniz, bana karşı gelip döneklik yapmanız yüzünden ellerinizi ve ayaklarınızı doğrayacağım, hepinizi asacağım” dedi."},{"n":"50-51","t":"İnanan sihirbazlar, “Zararı yok, biz elbette Rabbimize döneceğiz, inananların ilki olmamızdan dolayı, Rabbimizin, günahlarımızı bağışlayacağını umarız” dediler."},{"n":52,"t":"Biz, Mûsâ`ya, “Kullarımı geceleyin yola çıkar; elbette izleneceksiniz” diye bildirdik."},{"n":"53-56","t":"Bu arada Firavun, şehirlere, “Doğrusu bunlar, bizi öfkelendiren döküntü azınlıklardır; elbette hepimiz uyanık olmalıyız” diyen haberciler gönderdi."},{"n":"57-60","t":"Bunun üzerine Firavun`un adamlarını bahçelerden, pınar başlarından, hazinelerden ve şerefli makamlardan çıkardık. Böylece onlara İsrâiloğulları`nı mirasçı kıldık. Ancak Firavun`un adamları, güneş doğarken İsrâiloğulları`nın ardına düştüler."},{"n":"61-62","t":"İki topluluk birbirini gördüğünde, Mûsâ`nın adamları, “İşte yakalandık” dediler. Mûsâ, “Hayır! Rabbim benimle beraberdir, bana elbette bir çıkış yolu gösterecektir” dedi."},{"n":63,"t":"Bunun üzerine Mûsâ`ya, “Değneğinle denize vur!” diye bildirdik. Deniz ortadan yarıldı; her parçası yüce bir dağ gibi oldu."},{"n":64,"t":"Ötekileri, Firavun’un ordusunu da oraya yaklaştırdık."},{"n":65,"t":"Mûsâ ve beraberinde bulunanların hepsini kurtardık."},{"n":66,"t":"Sonra ötekilerini suda boğduk."},{"n":67,"t":"Şüphesiz bunda bir ders vardır, ama çokları inanmamaktadır."},{"n":68,"t":"Şüphesiz Rabbin, mutlak galip ve merhamet sahibidir."},{"n":69,"t":"“Ancak, babalarımızı da böyle yaparken bulduk” demişlerdi."},{"n":70,"t":"“Ancak, babalarımızı da böyle yaparken bulduk” demişlerdi."},{"n":71,"t":"\"Birtakım putlara tapıyoruz. Onların önünde toplanıp tapınmaya devam edeceğiz.\""},{"n":72,"t":"“Ancak, babalarımızı da böyle yaparken bulduk” demişlerdi."},{"n":73,"t":"“Ancak, babalarımızı da böyle yaparken bulduk” demişlerdi."},{"n":74,"t":"“Ancak, babalarımızı da böyle yaparken bulduk” demişlerdi."},{"n":75,"t":"“Eski atalarınızın ve sizin nelere taptıklarınızı görüyor musunuz? Doğrusu onlar benim düşmanımdır. Dostum, ancak âlemlerin Rabbidir. Beni yaratan da, doğru yola eriştiren de O`dur. Beni yediren de, içiren de O`dur. Hasta olduğumda bana O şifa verir. Beni öldürecek, sonra da diriltecek O`dur. Âhiret gününde, yanılmalarımı bana bağışlamasını umduğum O`dur. Rabbim! Bana ilim ve egemenlik ver ve beni iyiler arasına kat!”"},{"n":76,"t":"“Eski atalarınızın ve sizin nelere taptıklarınızı görüyor musunuz? Doğrusu onlar benim düşmanımdır. Dostum, ancak âlemlerin Rabbidir. Beni yaratan da, doğru yola eriştiren de O`dur. Beni yediren de, içiren de O`dur. Hasta olduğumda bana O şifa verir. Beni öldürecek, sonra da diriltecek O`dur. Âhiret gününde, yanılmalarımı bana bağışlamasını umduğum O`dur. Rabbim! Bana ilim ve egemenlik ver ve beni iyiler arasına kat!”"},{"n":77,"t":"“Eski atalarınızın ve sizin nelere taptıklarınızı görüyor musunuz? Doğrusu onlar benim düşmanımdır. Dostum, ancak âlemlerin Rabbidir. Beni yaratan da, doğru yola eriştiren de O`dur. Beni yediren de, içiren de O`dur. Hasta olduğumda bana O şifa verir. Beni öldürecek, sonra da diriltecek O`dur. Âhiret gününde, yanılmalarımı bana bağışlamasını umduğum O`dur. Rabbim! Bana ilim ve egemenlik ver ve beni iyiler arasına kat!”"},{"n":78,"t":"“Eski atalarınızın ve sizin nelere taptıklarınızı görüyor musunuz? Doğrusu onlar benim düşmanımdır. Dostum, ancak âlemlerin Rabbidir. Beni yaratan da, doğru yola eriştiren de O`dur. Beni yediren de, içiren de O`dur. Hasta olduğumda bana O şifa verir. Beni öldürecek, sonra da diriltecek O`dur. Âhiret gününde, yanılmalarımı bana bağışlamasını umduğum O`dur. Rabbim! Bana ilim ve egemenlik ver ve beni iyiler arasına kat!”"},{"n":79,"t":"“Eski atalarınızın ve sizin nelere taptıklarınızı görüyor musunuz? Doğrusu onlar benim düşmanımdır. Dostum, ancak âlemlerin Rabbidir. Beni yaratan da, doğru yola eriştiren de O`dur. Beni yediren de, içiren de O`dur. Hasta olduğumda bana O şifa verir. Beni öldürecek, sonra da diriltecek O`dur. Âhiret gününde, yanılmalarımı bana bağışlamasını umduğum O`dur. Rabbim! Bana ilim ve egemenlik ver ve beni iyiler arasına kat!”"},{"n":80,"t":"“Eski atalarınızın ve sizin nelere taptıklarınızı görüyor musunuz? Doğrusu onlar benim düşmanımdır. Dostum, ancak âlemlerin Rabbidir. Beni yaratan da, doğru yola eriştiren de O`dur. Beni yediren de, içiren de O`dur. Hasta olduğumda bana O şifa verir. Beni öldürecek, sonra da diriltecek O`dur. Âhiret gününde, yanılmalarımı bana bağışlamasını umduğum O`dur. Rabbim! Bana ilim ve egemenlik ver ve beni iyiler arasına kat!”"},{"n":81,"t":"“Eski atalarınızın ve sizin nelere taptıklarınızı görüyor musunuz? Doğrusu onlar benim düşmanımdır. Dostum, ancak âlemlerin Rabbidir. Beni yaratan da, doğru yola eriştiren de O`dur. Beni yediren de, içiren de O`dur. Hasta olduğumda bana O şifa verir. Beni öldürecek, sonra da diriltecek O`dur. Âhiret gününde, yanılmalarımı bana bağışlamasını umduğum O`dur. Rabbim! Bana ilim ve egemenlik ver ve beni iyiler arasına kat!”"},{"n":82,"t":"“Eski atalarınızın ve sizin nelere taptıklarınızı görüyor musunuz? Doğrusu onlar benim düşmanımdır. Dostum, ancak âlemlerin Rabbidir. Beni yaratan da, doğru yola eriştiren de O`dur. Beni yediren de, içiren de O`dur. Hasta olduğumda bana O şifa verir. Beni öldürecek, sonra da diriltecek O`dur. Âhiret gününde, yanılmalarımı bana bağışlamasını umduğum O`dur. Rabbim! Bana ilim ve egemenlik ver ve beni iyiler arasına kat!”"},{"n":83,"t":"“Eski atalarınızın ve sizin nelere taptıklarınızı görüyor musunuz? Doğrusu onlar benim düşmanımdır. Dostum, ancak âlemlerin Rabbidir. Beni yaratan da, doğru yola eriştiren de O`dur. Beni yediren de, içiren de O`dur. Hasta olduğumda bana O şifa verir. Beni öldürecek, sonra da diriltecek O`dur. Âhiret gününde, yanılmalarımı bana bağışlamasını umduğum O`dur. Rabbim! Bana ilim ve egemenlik ver ve beni iyiler arasına kat!”"},{"n":"84-89","t":"“Sonraki nesiller arasında benim doğrulukla anılmamı sağla. Beni nimet cennetine vâris olaylardan eyle. Babamı da bağışla; o, doğrusu şaşırmışlardandır. İnsanların diriltileceği gün, Allah`a temiz bir kalple gelenden başkasına mal ve oğulların fayda vermeyeceği gün, beni utandırma!”"},{"n":"90-91","t":"O gün cennet, Allah`a karşı saygılı olanlara yaklaştırılır. Cehennem de azgınlar için ortaya çıkarılır."},{"n":"92-95","t":"Onlara, “Allah`tan başka taptıklarınız nerededir? Size yardım ediyorlar mı veya kendilerine yardımları dokunuyor mu?” denilir. Onlar, azgınlar ve İblis`in adamları tepe taklak hepsi oraya atılırlar."},{"n":96,"t":"“Vallahi, biz apaçık bir sapıklıkta idik; çünkü biz sizi âlemlerin Rabbine eşit tutmuştuk; biz apaçık bir sapıklık içindeymişiz. Şimdi ne şefaatçimiz ne de bir dostumuz vardır. Keşke geriye dönüşümüz olsa da inananlardan olsak.”"},{"n":97,"t":"“Vallahi, biz apaçık bir sapıklıkta idik; çünkü biz sizi âlemlerin Rabbine eşit tutmuştuk; biz apaçık bir sapıklık içindeymişiz. Şimdi ne şefaatçimiz ne de bir dostumuz vardır. Keşke geriye dönüşümüz olsa da inananlardan olsak.”"},{"n":98,"t":"“Vallahi, biz apaçık bir sapıklıkta idik; çünkü biz sizi âlemlerin Rabbine eşit tutmuştuk; biz apaçık bir sapıklık içindeymişiz. Şimdi ne şefaatçimiz ne de bir dostumuz vardır. Keşke geriye dönüşümüz olsa da inananlardan olsak.”"},{"n":99,"t":"“Vallahi, biz apaçık bir sapıklıkta idik; çünkü biz sizi âlemlerin Rabbine eşit tutmuştuk; biz apaçık bir sapıklık içindeymişiz. Şimdi ne şefaatçimiz ne de bir dostumuz vardır. Keşke geriye dönüşümüz olsa da inananlardan olsak.”"},{"n":100,"t":"“Vallahi, biz apaçık bir sapıklıkta idik; çünkü biz sizi âlemlerin Rabbine eşit tutmuştuk; biz apaçık bir sapıklık içindeymişiz. Şimdi ne şefaatçimiz ne de bir dostumuz vardır. Keşke geriye dönüşümüz olsa da inananlardan olsak.”"},{"n":101,"t":"“Vallahi, biz apaçık bir sapıklıkta idik; çünkü biz sizi âlemlerin Rabbine eşit tutmuştuk; biz apaçık bir sapıklık içindeymişiz. Şimdi ne şefaatçimiz ne de bir dostumuz vardır. Keşke geriye dönüşümüz olsa da inananlardan olsak.”"},{"n":102,"t":"“Vallahi, biz apaçık bir sapıklıkta idik; çünkü biz sizi âlemlerin Rabbine eşit tutmuştuk; biz apaçık bir sapıklık içindeymişiz. Şimdi ne şefaatçimiz ne de bir dostumuz vardır. Keşke geriye dönüşümüz olsa da inananlardan olsak.”"},{"n":"103-104","t":"Bunda şüphesiz bir ders vardır, ama çoğu inanmamaktadır. Doğrusu Rabbin, güçlüdür, acıyandır."},{"n":105,"t":"Nûh kavmi de peygamberleri yalanladı."},{"n":106,"t":"“Sakınmaz mısınız? Bakın ben size gönderilmiş güvenilir bir peygamberim. Artık, Allah`a saygı duyun ve bana itaat edin. Hem bunun için sizden dünyevî bir karşılık da istemiyorum. Benim karşılığımı verecek olan, ancak âlemlerin Rabbidir. Onun için, Allah`a saygı duyun ve bana itaat edin!”"},{"n":107,"t":"“Sakınmaz mısınız? Bakın ben size gönderilmiş güvenilir bir peygamberim. Artık, Allah`a saygı duyun ve bana itaat edin. Hem bunun için sizden dünyevî bir karşılık da istemiyorum. Benim karşılığımı verecek olan, ancak âlemlerin Rabbidir. Onun için, Allah`a saygı duyun ve bana itaat edin!”"},{"n":108,"t":"“Sakınmaz mısınız? Bakın ben size gönderilmiş güvenilir bir peygamberim. Artık, Allah`a saygı duyun ve bana itaat edin. Hem bunun için sizden dünyevî bir karşılık da istemiyorum. Benim karşılığımı verecek olan, ancak âlemlerin Rabbidir. Onun için, Allah`a saygı duyun ve bana itaat edin!”"},{"n":109,"t":"“Sakınmaz mısınız? Bakın ben size gönderilmiş güvenilir bir peygamberim. Artık, Allah`a saygı duyun ve bana itaat edin. Hem bunun için sizden dünyevî bir karşılık da istemiyorum. Benim karşılığımı verecek olan, ancak âlemlerin Rabbidir. Onun için, Allah`a saygı duyun ve bana itaat edin!”"},{"n":110,"t":"“Sakınmaz mısınız? Bakın ben size gönderilmiş güvenilir bir peygamberim. Artık, Allah`a saygı duyun ve bana itaat edin. Hem bunun için sizden dünyevî bir karşılık da istemiyorum. Benim karşılığımı verecek olan, ancak âlemlerin Rabbidir. Onun için, Allah`a saygı duyun ve bana itaat edin!”"},{"n":111,"t":"“Sana, düşük seviyeli kimseler tâbi olup dururken, biz sana iman eder miyiz hiç!”"},{"n":112,"t":"“Onların yaptıkları hakkında bilgim yoktur. Onların hesabı Rabbime aittir, düşünsenize! Ben iman edenleri kovacak değilim. Ben ancak apaçık bir uyarıcıyım.”"},{"n":113,"t":"“Onların yaptıkları hakkında bilgim yoktur. Onların hesabı Rabbime aittir, düşünsenize! Ben iman edenleri kovacak değilim. Ben ancak apaçık bir uyarıcıyım.”"},{"n":114,"t":"“Onların yaptıkları hakkında bilgim yoktur. Onların hesabı Rabbime aittir, düşünsenize! Ben iman edenleri kovacak değilim. Ben ancak apaçık bir uyarıcıyım.”"},{"n":115,"t":"“Onların yaptıkları hakkında bilgim yoktur. Onların hesabı Rabbime aittir, düşünsenize! Ben iman edenleri kovacak değilim. Ben ancak apaçık bir uyarıcıyım.”"},{"n":116,"t":"“Ey Nûh! Vazgeçmezsen iyi bil ki, taşlanmışlardan olacaksın!”"},{"n":"117-118","t":"Nûh, “Ey Rabbim! Kavmim beni yalanladı, benimle onların arasında sen hüküm ver! Beni ve beraberimdeki inananları kurtar!” dedi."},{"n":"119-122","t":"Bunun üzerine onu ve beraberinde olanları dolu bir gemi içinde taşıyarak kurtardık. Sonra geride kalanları suda boğduk. Doğrusu, bunda ders vardır, ama çoğu inanmamaktadır. Rabbin, şüphesiz güçlüdür, merhamet sahibidir."},{"n":123,"t":"‘Âd kavmi de peygamberlerini yalanladı."},{"n":124,"t":"“Allah`ın emirlerine karşı gelmekten sakınmaz mısınız?”"},{"n":125,"t":"“Şüphesiz ben size gönderilmiş güvenilir bir peygamberim.”"},{"n":126,"t":"“Allah`tan sakının ve bana itaat edin!”"},{"n":127,"t":"“Ben bundan dolayı sizden hiçbir karşılık istemiyorum. Benim karşılığımı ancak âlemlerin Rabbi verecektir.”"},{"n":128,"t":"“Sizler her yüksek yerde övündüğünüz büyük bir köşk mü dikeceksiniz?”"},{"n":129,"t":"“Ebedî kalacağınız ümidiyle saraylar mı edineceksiniz?”"},{"n":130,"t":"“Yakaladığınızda, zorbalar gibi yakalıyorsunuz.”"},{"n":131,"t":"“Artık Allah`tan sakının ve bana itaat edin!”"},{"n":132,"t":"“Size bildiğiniz nimetleri veren Allah`tan sakının!”"},{"n":133,"t":"“Size evcil hayvanlar ve oğullar verdi.”"},{"n":134,"t":"“Bahçeler ve pınarlar verdi.”"},{"n":135,"t":"“Ben hakkınızda büyük bir günün azabından korkarım” dediğinde;"},{"n":136,"t":"Onlar, “Senin ögüt vermen de vermemen de bizim için birdir”;"},{"n":137,"t":"“Bu dediklerin eskilerin yalanlarından başka bir şey değildir.”"},{"n":"138-139","t":"“Biz yaptıklarımızdan dolayı ceza görmeyeceğiz” deyip onu yalanladılar. Biz de onları helâk ettik. Bunda kesinlikle bir ders vardır. Onların çoğu inanmamış olsa da."},{"n":140,"t":"Şüphesiz senin Rabbin çok güçlüdür; çok merhametlidir."},{"n":141,"t":"Semûd kavmi de peygamberlerini yalanladı."},{"n":142,"t":"Kardeşleri Sâlih, onlara, “Allah`ın emirlerine karşı gelmekten sakınmaz mısınız?” demişti."},{"n":143,"t":"“Şüphesiz ben size gönderilmiş güvenilir bir peygamberim.”"},{"n":144,"t":"“Allah`tan sakının ve bana itaat edin!”"},{"n":145,"t":"“Ben bundan dolayı sizden hiçbir karşılık istemiyorum. Benim karşılığımı ancak âlemlerin Rabbi verecektir.”"},{"n":146,"t":"“Burada güven içinde bırakılacağınızı mı sanıyorsunuz?”"},{"n":147,"t":"“Bahçelerin ve pınarların içerisinde.”"},{"n":148,"t":"“Ekinler, salkımlı hurma ağaçları arasında.”"},{"n":149,"t":"“Sevinçle dağlarda evler yaparak?”"},{"n":150,"t":"“Artık Allah`tan sakının ve bana itaat edin!”"},{"n":151,"t":"“Aşırı gidenlerin emrine uymayın!”"},{"n":152,"t":"“Onlar, yeryüzünde bozgunculuk yapıyorlar da insanların iyiliğine çalışmıyorlar” dediğinde;"},{"n":153,"t":"“Şüphesiz sen sadece büyülenenlerden birisin.”"},{"n":154,"t":"“Sen de bizim gibi bir insandan başka bir şey değilsin. Eğer doğru söyleyenlerden isen haydi bize bir mucize getir!” dediler."},{"n":155,"t":"“İşte, mucize bu dişi devedir. Belirli bir gün onun da, sizin de su içme hakkınız vardır.”"},{"n":156,"t":"“Ona bir kötülük yapmayınız! Aksi takdirde başınıza büyük bir felaket gelir.”"},{"n":157,"t":"Buna rağmen onlar deveyi kestiler, ama sonunda pişman oldular."},{"n":158,"t":"Çünkü felâket başlarına geldi. Onların çoğu inanmamış olsa da, bunda kesinlikle bir ders vardır."},{"n":159,"t":"Şüphesiz senin Rabbin çok güçlüdür; çok merhametlidir."},{"n":160,"t":"Lût kavmi de peygamberleri yalanladı."},{"n":161,"t":"“Allah`ın emirlerine karşı gelmekten sakınmaz mısınız? Şüphesiz ben, size gönderilmiş güvenilir bir peygamberim. Allah`tan sakının ve bana itaat edin! Ben, bundan dolayı sizden hiçbir karşılık istemiyorum. Benim karşılığımı ancak âlemlerin Rabbi verecektir."},{"n":162,"t":"“Allah`ın emirlerine karşı gelmekten sakınmaz mısınız? Şüphesiz ben, size gönderilmiş güvenilir bir peygamberim. Allah`tan sakının ve bana itaat edin! Ben, bundan dolayı sizden hiçbir karşılık istemiyorum. Benim karşılığımı ancak âlemlerin Rabbi verecektir."},{"n":163,"t":"“Allah`ın emirlerine karşı gelmekten sakınmaz mısınız? Şüphesiz ben, size gönderilmiş güvenilir bir peygamberim. Allah`tan sakının ve bana itaat edin! Ben, bundan dolayı sizden hiçbir karşılık istemiyorum. Benim karşılığımı ancak âlemlerin Rabbi verecektir."},{"n":164,"t":"“Allah`ın emirlerine karşı gelmekten sakınmaz mısınız? Şüphesiz ben, size gönderilmiş güvenilir bir peygamberim. Allah`tan sakının ve bana itaat edin! Ben, bundan dolayı sizden hiçbir karşılık istemiyorum. Benim karşılığımı ancak âlemlerin Rabbi verecektir."},{"n":"165-166","t":"Allah`ın sizin için yarattığı eşlerinizi bırakıp da, erkeklerle mi cinsel ilişkiye giriyorsunuz? Doğrusu siz sapık bir toplumsunuz.”"},{"n":167,"t":"“Ey Lût! Bizi kınamaya bir son vermezsen, kesinlikle sürgün edilenlerden olacaksın.”"},{"n":"168-169","t":"Lût, “Ben kesinlikle, yaptığınız bu işe kızanlardanım. Ey Rabbim! Beni ve ailemi onların yaptıklarından kurtar!” dedi."},{"n":"170-171","t":"Bunun üzerine biz de onu ve helâk olanların içerisinde kalan bir kocakarı dışında bütün ailesini kurtardık."},{"n":"172-173","t":"Sonra diğerlerini yerle bir ettik. Üzerlerine bir yağmur yağdırdık. Ne kötü bir yağmurdu, o uyarılanların yağmuru!"},{"n":"174-175","t":"Bunda kesinlikle bir ders vardır. Onların çoğu inanmamış olsa da. Şüphesiz senin Rabbin çok güçlüdür; çok merhametlidir."},{"n":176,"t":"Eyke halkı da peygamberleri yalanladı."},{"n":177,"t":"“Allah`ın emirlerine karşı gelmekten sakınmaz mısınız?”"},{"n":178,"t":"“Şüphesiz ben, size gönderilmiş güvenilir bir peygamberim.”"},{"n":179,"t":"“Allah`tan korkun ve bana itaat edin.”"},{"n":180,"t":"“Ben, bundan dolayı sizden hiçbir karşılık istemiyorum. Benim karşılığımı ancak âlemlerin Rabbi verecektir.”"},{"n":181,"t":"“Ölçüyü ve tartıyı eksiksiz yapınız! İnsanların hakkını kısanlardan olmayınız!”"},{"n":182,"t":"“Doğru terazi ile tartınız!”"},{"n":183,"t":"“İnsanların eşyalarını eksiltmeyiniz! Yeryüzünde kesinlikle bozgunculuk yapmayınız!”"},{"n":184,"t":"“Sizi ve sizden önceki nesilleri yaratandan sakınınız!”"},{"n":185,"t":"“Sen sadece büyülenenlerden birisin.”"},{"n":186,"t":"“Sen de sırf bizim gibi bir insansın. Senin kesinlikle yalancılardan olduğunu sanıyoruz.”"},{"n":187,"t":"“Haydi, eğer doğru söyleyenlerden isen üzerimize gökten bir kütle düşür!” dediler."},{"n":188,"t":"Şu‘ayb, “Rabbim, sizin ne yaptığınızı daha iyi bilir” dedi."},{"n":189,"t":"Bunun üzerine onu yalanladılar. Derken o gölge gününün çetin azabı onları yakıp yok etti. Şüphesiz o, korkunç bir günün azabı idi."},{"n":190,"t":"Çoğu inanmamış olsa da bunda kesinlikle bir ders vardır."},{"n":191,"t":"Şüphesiz senin Rabbin çok güçlüdür; çok merhametlidir."},{"n":192,"t":"Şüphesiz Kur`ân, âlemlerin Rabbinin indirmesidir."},{"n":"193-195","t":"Kur`ân`ı, Rûhulemîn/Cebrâil, uyarıcılardan olasın diye, apaçık Arap diliyle, senin kalbine indirmiştir."},{"n":196,"t":"Kur`ân, şüphesiz daha öncekilerin kitaplarında da vardır."},{"n":197,"t":"İsrâiloğullarının bilginlerinin onu bilmesi, onlar için bir delil değil midir?"},{"n":"198-199","t":"Biz, Kur`ân`ı Arapça bilmeyenlerden birine indirseydik de bunu onlara o okusaydı, yine ona iman etmezlerdi."},{"n":"200-201","t":"Onu, günahkârların kalplerine böyle soktuk. Bu yüzden, acıklı azabı görünceye kadar ona iman etmezler."},{"n":202,"t":"O azap onlara ansızın gelir. Onlar hiç farkedemezler."},{"n":203,"t":"“Acaba bize mühlet verilir mi?” derler."},{"n":204,"t":"Onlar, azabımızın çabuk gelmesini mi istiyorlar?"},{"n":205,"t":"Hiç düşündün mü; onları yıllarca dünya nimetleri içerisinde yaşatsak,"},{"n":206,"t":"Sonra da kendilerine uyarıldıkları azap gelse;"},{"n":207,"t":"Bekletilmiş olmaları kendilerine ne fayda verecek?"},{"n":208,"t":"Biz hiçbir memleketi, kendilerine uyarıcılar göndermeden yok etmedik."},{"n":209,"t":"Bu, bir uyarıdır. Biz, asla hiçbir kimseye haksızlık yapmayız."},{"n":210,"t":"Kur`ân`ı şeytanlar indirmemiştir."},{"n":211,"t":"Bu, ne onlara düşer, ne de ona güç yetirebilirler."},{"n":212,"t":"Çünkü şeytanlar, kulak hırsızlığından uzak tutulmuşlardır."},{"n":213,"t":"Artık Allah`la birlikte hiçbir tanrıya kulluk etme! Aksi takdirde cezalandırılanlardan olursun."},{"n":214,"t":"Yakın akrabalarını uyar!"},{"n":215,"t":"Sana uyan müminlere karşı son derece alçakgönüllü ol!"},{"n":216,"t":"Eğer yakın akrabaların sana karşı gelirlerse, onlara “Yaptıklarınızdan uzağım” de!"},{"n":"217-219","t":"Namaza kalktığında ve secde edenlerle birlikte dolaştığında seni gören güçlü ve merhametli olan Allah`a güven!"},{"n":220,"t":"Şüphesiz O, her şeyi duyar; her şeyi bilir."},{"n":221,"t":"“Şeytanların ise kime ineceğini size haber vereyim mi?”"},{"n":222,"t":"“Onlar, günaha, iftiraya düşkün olan herkesin üstüne inerler.”"},{"n":223,"t":"“Bunlar, şeytanlara kulak verirler ve onların çoğu yalancıdırlar.”"},{"n":224,"t":"“Şairlere gelince, onlara da sapıklar uyarlar.”"},{"n":"225-226","t":"“Onların her vadide başı boş dolaştıklarını ve gerçekte yapmadıkları şeyleri söylediklerini görmedin mi?”"},{"n":227,"t":"Ancak iman edip iyi işler yapanlar, Allah`ı çok çok ananlar ve haksızlığa uğradıklarında kendilerini savunanlar başkadır. Zulmedenler hangi devrimle devrileceklerini bileceklerdir."}],[{"n":1,"t":"Tâ, sîn. Bunlar, Kur`ân`ın ve apaçık bir kitabın âyetleridir."},{"n":2,"t":"İnananlara rehber ve müjdedir."},{"n":3,"t":"Onlar ki namazı kılarlar, zekâtı verirler ve âhirete de kesin olarak inanırlar."},{"n":4,"t":"Âhirete inanmayanların amellerini kendilerine süslemişizdir, onlar körü körüne bocalarlar."},{"n":5,"t":"İşte bunlar, azabı en ağır olanlardır; âhirette en çok ziyana uğrayacaklar da onlardır."},{"n":6,"t":"“Ey Muhammed! Bu Kur`ân sana, bilge ve bilgin olan Allah tarafından verilmektedir.”"},{"n":7,"t":"“Gerçekten ben, bir ateş gördüm. Gidip size ondan bir haber getireceğim, yahut bir ateş parçası getireceğim, umarım ki ısınırsınız.”"},{"n":8,"t":"“Ateşteki kimse de, ateşin çevresindekiler de kutsal kılınmıştır. Âlemlerin Rabbi olan Allah, bütün noksanlıklardan uzaktır.”"},{"n":9,"t":"“Ey Mûsâ! Gerçek şu ki, ben güçlü ve bilge olan Allah`ım.”"},{"n":10,"t":"“Asânı at!” Mûsâ onu yılan gibi deprenir görünce, dönüp arkasına bakmadan kaçtı. “Ey Mûsâ! Korkma! Çünkü benim huzurumda peygamberler korkmaz.”"},{"n":11,"t":"“Ancak, kim zulmeder, sonra işlediği kötülük yerine iyilik yaparsa, bilsin ki ben çok bağışlayıcıyım; çok merhamet sahibiyim.”"},{"n":12,"t":"“Elini koynuna sok da kusursuz, bembeyaz çıksın. Dokuz mucize ile Firavun ve kavmine git! Çünkü onlar artık yoldan çıkmış bir kavim olmuşlardır.”"},{"n":13,"t":"“Bu, apaçık bir sihirdir” dediler."},{"n":14,"t":"Kendileri de mucizelerimize kesin olarak inandıkları halde, zulüm ve kibirlerinden dolayı, onları bile bile inkâr ettiler. Bozguncuların sonunun nasıl olduğuna bir bak!"},{"n":15,"t":"“Bizi, mümin kullarının birçoğundan üstün kılan Allah`a hamd olsun!”"},{"n":16,"t":"“Ey insanlar! Bize kuşların dili öğretildi ve bize her şeyden biraz verildi. Şüphesiz bu apaçık bir lütuftur.”"},{"n":17,"t":"Cinlerden, insanlardan ve kuşlardan ordular, Süleyman`ın huzurunda bir araya getirildi. Onlar, düzenli bir biçimde sevk ediliyorlardı."},{"n":18,"t":"“Ey karıncalar! Yuvalarınıza giriniz ki Süleyman ve orduları farkında olmayarak sizi ezmesinler.”"},{"n":19,"t":"“Rabbim! Bana ve ebeveynime lütfettiğin nimetine şükretmeme, hoşnut olacağın hayırlı ve barışçıl bir iş yapmama imkan ver ve rahmetinle beni iyilik ve barışı seven iyi kullarının arasına sok!”"},{"n":20,"t":"“Hüdhüd`ü neden göremiyorum, yoksa kayıplara mı karıştı?”"},{"n":21,"t":"“Ona acımasızca azap edeceğim, belki de onu boğazlayacağım; ya da bana mutlaka açık bir kanıt getirecek.”"},{"n":22,"t":"“Senin fark edemediğin bir şeyi fark ettim ve sana Sebe`den doğru bir haber getirdim!”"},{"n":23,"t":"“Sebe`lilere hükmeden bir kadın buldum. Kendisine her şeyden bir pay verilmiş, kocaman bir tahtı var.”"},{"n":24,"t":"“Onu ve toplumunu, Allah`ı bırakıp güneşe secde eder buldum. Şeytan onlara, yapıp ettiklerini süslü gösterip onları yoldan saptırmış. Artık doğruyu bulamazlar.”"},{"n":25,"t":"“Göklerde ve yerdeki sırrı açığa çıkaran, onların gizlediklerini de açıkladıklarını da bilen Allah`a secde etmemek gayretindeler.”"},{"n":26,"t":"“O Allah ki, O`ndan başka tanrı yoktur. O büyük hükümranlık tahtının Rabbidir.”"},{"n":27,"t":"“Doğru mu söyledin, yoksa yalancılardan mısın, göreceğiz!”"},{"n":28,"t":"“Şu yazımı götürüp onlara at! Sonra onlardan uzaklaş da bak bakalım, nasıl davranacaklar.”"},{"n":29,"t":"Sebe` melikesi, “Beyler, ulular! Bana çok önemli bir mektup bırakıldı” dedi."},{"n":30,"t":"“Mektup Süleyman`dandır, rahmet ve merhametin kaynağı olan Allah`ın adıyla başlamaktadır.”"},{"n":31,"t":"“Sakın bana başkaldırmayın, teslim olarak gelin!”, diye yazmaktadır.”"},{"n":32,"t":"“Beyler, ulular! Bu işimde bana bir fikir veriniz; siz benim yanımda bulunmadıkça, bir iş hakkında kesin bir karar vermem.”"},{"n":33,"t":"İleri gelenler, “Biz güçlü, kuvvetli kimseleriz; zorlu savaş erbabıyız; buyruk ise senindir; artık ne buyuracağını sen düşün!” diye cevap verdiler."},{"n":"34-35","t":"Melike, “Hükümdarlar bir memlekete girdiler mi, orayı perişan ederler ve halkının ulularını alçaltırlar. Herhalde onlar da böyle yapacaklardır. Ben onlara, bir hediye göndereyim de, bakayım elçiler ne ile dönecekler?” dedi."},{"n":36,"t":"“Siz bana mal ile yardım mı ediyorsunuz? Allah`ın bana verdiği, size verdiğinden daha değerlidir. Hediyenizle ben değil, siz sevinirsiniz.”"},{"n":37,"t":"“Hediyeyi onlara geri götür; onlara asla karşı koyamayacakları bir ordu ile gelir, onları oradan hor ve hakir olarak çıkarırım.”"},{"n":38,"t":"“Ey ileri gelenler! Onlar teslimiyet gösterip bana gelmeden önce, hanginiz o melikenin tahtını bana getirebilir?”"},{"n":39,"t":"Cinlerden bir ifrit, “Sen makamından kalkmadan ben onu sana getiririm. Gerçekten bu işe gücüm yeter ve bana güvenebilirsiniz” dedi."},{"n":40,"t":"“Bu, Rabbimin lütfundandır. Kendisine şükür mü edeceğim, yoksa nankörlük mü edeceğim, diye beni denemek istiyor. Şükreden, kendisi için şükretmiş olur; nankörlük edene gelince, Rabbim hiçbir şeye muhtaç değildir, çok ikram sahibidir.”"},{"n":41,"t":"“Onun tahtını tanınmaz hale getiriniz, bakalım tanıyabilecek mi, yoksa tanıyamayacak mı?”"},{"n":42,"t":"Melike gelince, “Senin tahtın da böyle mi?” dendi. “Tıpkı o” dedi. “Zaten bize daha önce bilgi verilmişti ve biz teslim olmuştuk.”"},{"n":43,"t":"Melikeyi Allah`tan başka taptığı şeyler tevhid inancından alıkoymuştu. Çünkü kendisi inkârcı bir kavimdendi."},{"n":44,"t":"Ona, “Köşke gir!” denildi. Melike köşkü görünce derin bir su sandı ve bacaklarını sıvadı. Süleyman, “O sırçadan cilalı, şeffaftır” dedi. Melike, “Rabbim, ben kendime zulmetmişim. Artık Süleyman ile beraber âlemlerin Rabbi Allah`a teslim oldum” dedi."},{"n":45,"t":"“Andolsun ki, Allah`a kulluk edin!” demesi için Semûd kavmine kardeşleri Sâlih`i gönderdik. Hemen birbirleriyle çekişen iki zümre oluverdiler."},{"n":46,"t":"“Ey kavmim! İyilik dururken niçin kötülüğe koşuyorsunuz? Allah`tan af dileseniz olmaz mı? Belki size merhamet edilir.”"},{"n":47,"t":"“Senin ve beraberindekilerin yüzünden uğursuzluğa uğradık.” Sâlih, “Size çöken uğursuzluğun sebebi Allah katındandır. Hayır, siz imtihana çekilen bir kavimsiniz” dedi."},{"n":48,"t":"O şehirde dokuz çete vardı; bunlar ülkede bozgunculuk yapıyorlar, iyilik tarafına hiç yanaşmıyorlardı."},{"n":49,"t":"“O`nu öldürmediğimiz gibi, öldüreni de bilmiyoruz ve şüphe yok ki biz, doğru söylüyoruz” dediler."},{"n":50,"t":"Onlar böyle bir tuzak kurdular. Biz de, kendileri farkında olmadan onların planlarını alt üst ettik."},{"n":51,"t":"Bak, işte tuzaklarının sonucu nasıl oldu? Onları da kavimlerini de toptan helâk ettik."},{"n":52,"t":"İşte, haksızlıkları yüzünden çökmüş evleri! Anlayan bir kavim için elbette bunda bir ders vardır."},{"n":53,"t":"İman edip sakınanları ise kurtardık."},{"n":54,"t":"“Göz göre göre hâlâ o hayâsızlığı yapacak mısınız?”"},{"n":55,"t":"“Siz ille de kadınları bırakıp şehvetle erkeklere yaklaşacak mısınız? Doğrusu siz, cehalet üreten bir toplumsunuz.”"},{"n":56,"t":"Toplumunun cevabı sadece, “Lût ailesini memleketinizden çıkarın; çünkü onlar, temizliği seven insanlardır” oldu."},{"n":57,"t":"Bunun üzerine onu ve ailesini kurtardık. Karısı müstesna; çünkü onun, geride kalmasını gerekli bulduk."},{"n":58,"t":"Geride kalanların üzerine bir yağmur yağdırdık. Uyarılanların bu yağmuru ne kötü idi!"},{"n":59,"t":"“Hamdolsun Allah`a, selâm olsun seçkin kıldığı kullarına! Allah mı daha üstün, yoksa O`na koştukları ortaklar mı?”"},{"n":60,"t":"Onlar mı daha güçlü, yoksa gökleri ve yeri yaratan, gökten size su indiren mi? O su ile, bir ağacını bile bitirmeye gücünüzün yetmediği güzel güzel bahçeler bitirdik. Allah`tan başka bir tanrı mı var? Doğrusu onlar sapıklıkta devam eden bir güruhtur."},{"n":61,"t":"Onlar mı daha güçlü, yoksa yeryüzünü oturmaya elverişli kılan ve aralarında nehirler akıtan, orada sabit dağlar yaratan, iki deniz arasında engel koyan mı? Allah`tan başka bir tanrı mı var? Doğrusu onların çoğu bilmiyorlar."},{"n":62,"t":"Onlar mı daha güçlü, yoksa darda kalana kendisine yalvardığı zaman karşılık veren ve sıkıntıyı gideren, sizi yeryüzünün hakimleri kılan mı? Allah`tan başka bir tanrı mı var? Ne kadar da kıt düşünüyorsunuz!"},{"n":63,"t":"Onlar mı daha güçlü, yoksa karanın ve denizin karanlıkları içinde size yolu bulduran, rahmetinin önünde rüzgârları müjdeci olarak gönderen mi? Allah`tan başka bir tanrı mı var? Allah, onların ortak koştuklarından çok yücedir, uzaktır."},{"n":64,"t":"“Onlar mı daha güçlü, yoksa ilk baştan yaratan, sonra yaratmayı tekrar eden ve sizi hem gökten hem de yerden rızıklandıran mı? Allah`tan başka bir tanrı mı var? Eğer doğru söylüyorsanız siz kesin delilinizi getiriniz!”"},{"n":65,"t":"“Gökte ve yerde olan akıllı varlıklar gaybı bilmezler. Gayb bilgisi Allah`ın tekelindedir. Akıllılar, tekrar diriltilecekleri zamanı da bilmezler.”"},{"n":66,"t":"Açıkçası, onların âhiret hakkındaki bilgileri yetersiz kalmıştır. Dahası, bu hususta şüphe içindedirler. Bunun da ötesinde, onlar âhiretten yana cahildirler."},{"n":67,"t":"“Şimdi biz ve atalarımız toz toprak olduktan sonra, gerçekten diriltilip çıkarılacak mıyız?”"},{"n":68,"t":"“Andolsun ki bu tehdit, bize ve atalarımıza daha önce de söylendi. Bu, öncekilerin masallarından başka bir şey değildir.”"},{"n":69,"t":"“Yeryüzünde gezin de, günahkârların âkıbetinin ne olduğunu bir görün!”"},{"n":70,"t":"Onların yüzünden tasalanma! Kurmakta oldukları tuzaklar yüzünden canını sıkma!"},{"n":71,"t":"Onlar, “Eğer doğru sözlü iseniz bu tehdit ne zaman gerçekleşecek?” derler."},{"n":72,"t":"“Çarçabuk gelmesini istediğiniz azabın bir kısmı herhalde yakında başınıza gelecektir.”"},{"n":73,"t":"Şüphesiz Rabbin, insanlara karşı lütuf sahibidir; fakat insanların çoğu şükretmezler."},{"n":74,"t":"Rabbin, elbette onların kalplerinin gizlediklerini de, açığa vurduklarını da bilir."},{"n":75,"t":"Gökte ve yerde göze görünmeyen hiçbir şey yoktur ki, apaçık bir kitapta bulunmasın."},{"n":76,"t":"Doğrusu bu Kur`ân, İsrâiloğulları`na, hakkında ihtilaf edegeldikleri konuların pek çoğunu anlatmaktadır."},{"n":77,"t":"Doğrusu Kuran, inananlara doğruluk rehberi ve rahmettir."},{"n":78,"t":"Rabbin elbette İsrâiloğulları arasında hükmünü verecektir. O, mutlak galiptir; her şeyi bilendir."},{"n":79,"t":"Rasûlüm; işini sağlam tutarak Allah`a güven! Çünkü sen, apaçık hakikat üzeresin."},{"n":80,"t":"Sen, şüphesiz, manen ölülere işittiremezsin; dönüp giden manen sağırlara da çağrıyı duyuramazsın."},{"n":81,"t":"Manen körleri sapıklıklarından döndürüp doğru yola iletemezsin; ancak âyetlerimize inanıp teslim olanlara duyurabilirsin."},{"n":82,"t":"O söz, tepelerine indiğinde, yerden onlar için canlı bir yaratık çıkarırız da, o onlara, insanların bizim âyetlerimize gereğince inanmadıklarını söyler."},{"n":83,"t":"O gün, her ümmet içinden âyetlerimizi yalan sayanlardan bir grup toplarız da onlar toplu olarak hesap yerine sevk edilirler."},{"n":84,"t":"“Siz benim âyetlerimi iyice anlamadan yalan saydınız, öyle mi? Değilse, yaptığınız ne idi?”"},{"n":85,"t":"Zulüm etdikleri sebebiyle üzerlerine o söz vukuua gelmişdir. Artık onlar söz de söyleyemeyeceklerdir."},{"n":86,"t":"Geceyi dinlensinler diye karanlık, gündüzü çalışsınlar diye aydınlık olarak yarattığımızı görmediler mi? Doğrusu bunda inanacak toplum için dersler vardır."},{"n":87,"t":"Sûra üfürüldüğü gün, Allah`ın diledikleri müstesna, gökte olanlar da yerde olanlar da dehşet içinde kalırlar. Hepsi Allah`a boyunları bükülmüş olarak gelirler."},{"n":88,"t":"Dağları, yerinde cansız gibi durur görürsün. Oysa onlar bulutların geçişi gibi geçerler. Bu, her şeyi sağlam yapan Allah`ın sanatıdır. Doğrusu O, yaptıklarınızdan haberdardır."},{"n":89,"t":"Kim bir iyilik yaparsa, ona daha iyisi verilir; o günün korkusundan güvende olurlar."},{"n":90,"t":"Kötülük yapanlar, yüzüstü ateşe atılırlar. “Yaptıklarınızdan başka bir şeyle mi cezalandırılıyorsunuz?” denir."},{"n":91,"t":"“Ben, sadece uyaranlardan biriyim.”"},{"n":92,"t":"“Ben, sadece uyaranlardan biriyim.”"},{"n":93,"t":"“Övgü Allah`adır. O, âyetlerini size gösterecek, siz de onları tanıyacaksınız. Rabbin, yaptıklarınızdan habersiz değildir.”"}],[{"n":1,"t":"Tâ, sîn, mîm."},{"n":2,"t":"Bunlar, apaçık kitabın âyetleridir."},{"n":3,"t":"Sana, Firavun ile Mûsâ arasında geçen olayların bir bölümünü, inanacak olanlar için bütün gerçeği ile anlatacağız."},{"n":4,"t":"Firavun, orada zorbalığa kalktı, halkını çeşitli gruplara ayırdı. Onlardan bir grubu zayıflatıyor, oğullarını kestiriyor, kadınlarını sağ bırakıyordu. Çünkü o, bozgunculardandı."},{"n":5,"t":"Biz de istiyorduk ki, o yerde ezilenlere lütfedelim, onları önderler yapalım ve onları ötekilerin mülküne mirasçı yapalım."},{"n":6,"t":"Onları o yerde iktidara getirelim de Firavun`a, Hâmân`a ve onların askerlerine, ezdikleri gruptan korktukları şeyi gösterelim."},{"n":7,"t":"Mûsâ`nın annesine, “Çocuğu emzir, başına bir şey gelmesinden korkuyorsan, onu Nil nehrine bırakıver. Korkma, üzülme! Çünkü biz, onu sana geri vereceğiz ve onu peygamberlerden biri yapacağız” diye vahyettik."},{"n":8,"t":"Nihayet Firavun ailesi onu yitik çocuk olarak nehirden aldı. Çocuk, sonunda kendileri için bir düşman ve bir tasa olacaktı. Çünkü Firavun, Hâmân ve askerleri yanılıyorlardı."},{"n":9,"t":"Firavun`un karısı çocuğu sandıktan çıkarınca, “Bana da, sana da göz bebeği olacak. Onu öldürmeyiniz; belki bize faydası dokunur, ya da onu evlat ediniriz” dedi. Halbuki onlar, işin sonunu sezemiyorlardı."},{"n":10,"t":"Mûsâ`nın annesi, pek kaygılandı. Güvende olması için kalbini pekiştirmeseydik, neredeyse durumu açığa vuracaktı."},{"n":11,"t":"Annesi, Mûsâ`nın ablasına, “Onu izle!” dedi. O da, kimse farkına varmadan, Mûsâ`yı uzaktan gözetledi."},{"n":12,"t":"Önceden, sütannelerinin memesini emmemesini sağladık. Mûsâ`nın ablası, “Size, sizin adınıza ona bakacak, iyi davranacak bir aileyi tavsiye edeyim mi?” dedi."},{"n":13,"t":"Böylece biz onu, anasına “Gözü aydın olsun, gam çekmesin, Allah`ın verdiği sözün gerçek olduğunu bilsin” diye, geri verdik. Fakat onların çoğu bilmezler."},{"n":14,"t":"Mûsâ ergenlik çağına gelip olgunlaşınca, ona güçlü bir muhakeme yeteneği ve ilim verdik. Güzelliğe sevdalı olanları böyle ödüllendiririz."},{"n":15,"t":"Mûsâ, halkının habersiz olduğu bir zamanda şehre girdi. Orada, biri kendi tarafından, diğeri düşman tarafından olan iki adamı birbiriyle dövüşür buldu. Kendi tarafından olanı, düşmana karşı ondan yardım diledi. Mûsâ da ötekine bir yumruk vurup ölümüne sebep oldu. Bunun üzerine, “Bu, şeytan işidir. O, gerçekten saptırıcıdır; apaçık bir düşmandır” dedi."},{"n":16,"t":"Mûsâ, “Ey Rabbim! Kendime haksızlık ettim, beni bağışla!” dedi. Allah da onu bağışladı. Çünkü Allah, bağışlayandır; çok merhamet edendir."},{"n":17,"t":"Mûsâ, “Ey Rabbim! Bana verdiğin nimete yemin olsun ki, suçlulara arka çıkmayacağım” dedi."},{"n":18,"t":"“Doğrusu sen, besbelli bir azgınsın.”"},{"n":19,"t":"Mûsâ, ikisinin de düşmanı olan kimseyi yakalamak isteyince, o kişi, “Ey Mûsâ! Dün bir cana kıydığın gibi beni de mi öldürmek istiyorsun? Sen arabuluculardan olmayı istemiyorsun, ancak yeryüzünde bir zorba olmak istiyorsun” dedi."},{"n":20,"t":"Şehrin en ileri gelenlerinden biri koşarak geldi ve “Ey Mûsâ! İleri gelenler, seni öldürmek için aralarında görüşüyorlar. Hemen uzaklaş! Doğrusu ben sana öğüt verenlerdenim” dedi."},{"n":21,"t":"Bunun üzerine Mûsâ, korku içinde çevresini gözetleyerek oradan çıktı. “Ey Rabbim! Beni, zâlim toplumdan kurtar!” dedi."},{"n":22,"t":"Medyen`e doğru yöneldiğinde, “Umarım, Rabbim beni doğru yola iletir” dedi."},{"n":23,"t":"Mûsâ, Medyen suyuna varınca, davarlarını sulayan bir insan topluluğu buldu. Onların gerisinde, hayvanlarını engellemeye çalışan iki kız gördü. Onlara, “Sıkıntınız nedir?” dedi. Kızlar da, “Çobanlar ayrılana kadar biz hayvanlarımızı sulamayız. Babamız çok yaşlıdır, onun için bu işi biz yapıyoruz” dediler."},{"n":24,"t":"Mûsâ, onların davarlarını suladı. Sonra gölgeye çekildi. “Ey Rabbim! Doğrusu bana indireceğin her iyiliğe muhtacım” dedi."},{"n":25,"t":"O sırada, kızlardan biri utana utana ona geldi ve “Babam, sulama ücretini ödemek için seni çağırıyor” dedi. Mûsâ, babalarına gelince, başından geçeni anlattı. O da, “Korkma, artık zâlim toplumdan kurtuldun” dedi."},{"n":26,"t":"İki kızdan biri, “Babacığım! Onu ücretli olarak tut; ücretle tuttuklarının en iyisi bu güçlü ve güvenilir adamdır” dedi."},{"n":27,"t":"Kızların babası, “Bana sekiz yıl çalışmana karşılık bu iki kızdan birini sana nikâhlamak istiyorum. Eğer on yıla tamamlarsan, o senden bir lütuf olur. Ama sana bir sıkıntı vermek istemem. İnşaallah beni iyi kimselerden bulacaksın” dedi."},{"n":28,"t":"Mûsâ, “Bu seninle benim aramdadır. Demek ki, bu iki süreden hangisini doldurursam doldurayım, bir düşmanlığa uğramayacağım. Söylediklerimize Allah vekildir” dedi."},{"n":29,"t":"Mûsâ, süreyi tamamlayınca ailesi ile birlikte yola çıktı. Tûr Dağı tarafından bir ateş gördü. Ailesine, “Siz burada bekleyin; ben bir ateş gördüm, belki oradan size bir haber yahut tutuşmuş bir odun getiririm de ısınırsınız.” dedi."},{"n":30,"t":"“Ey Mûsâ! Bil ki ben, bütün âlemlerin Rabbi olan Allah`ım.”"},{"n":31,"t":"“Değneğini at!” Mûsâ, değneğin yılan gibi kıvrıldığını görünce, dönüp arkasına bakmadan kaçtı. “Ey Mûsâ, dön gel; korkma, şüphesiz güvende olanlardansın” denildi."},{"n":32,"t":"“Elini koynuna koy, lekesiz, bembeyaz çıksın. Ellerini koltuk altına çek, korkun kalmasın.” Bu ikisi, Firavun ve ileri gelenlerine karşı Rabbinin iki mucizesidir. Doğrusu onlar yoldan çıkmış bir topluluktu."},{"n":33,"t":"“Ey Rabbim! Ben onlardan birini öldürmüştüm; beni öldürmelerinden korkuyorum.”"},{"n":34,"t":"“Kardeşim Hârûn`un dili benimkinden daha düzgündür. Onu, beni destekleyen bir yardımcı olarak benimle gönder; çünkü beni yalanlamalarından korkuyorum” dedi."},{"n":35,"t":"Allah, “Seni kardeşinle destekleyeceğiz; mucizelerimizle ikinize bir kudret vereceğiz ki, onlar size el uzatamayacaklar. Siz ve size uyanlar üstün geleceksiniz” dedi."},{"n":36,"t":"Mûsâ, onlara apaçık mucizelerimizle gelince, “Bu, sadece uydurma bir sihirdir. Önceki atalarımızdan, böylesini işitmemiştik” dediler."},{"n":37,"t":"“Rabbim, kendi katından kimin hidayet getirdiğini ve iyi sonucun kime ait olacağını en iyi bilendir. Elbette zâlimler zafere ulaşamazlar.”"},{"n":38,"t":"Firavun, “Ey ileri gelenler! Sizin için benden başka bir ilâh tanımıyorum. Ey Hâmân! Benim için çamur üzerine ateş yak; bana bir kule yap, Mûsâ`nın tanrısına çıkayım; ama ben, onun yalancılardan olduğunu sanıyorum,” dedi."},{"n":39,"t":"Firavun ve askerleri, ülkede haksız yere büyüklük tasladılar. Gerçekten bize döndürülmeyeceklerini sandılar."},{"n":40,"t":"Biz de, onu ve askerlerini yakalayıp denize atıverdik. Bak işte, zâlimlerin sonu nasıl oldu?"},{"n":41,"t":"Onları, ateşe çağıran öncüler kıldık. Kıyamet günü onlar yardım görmeyeceklerdir."},{"n":42,"t":"Bu dünyada arkalarına lanet taktık. Onlar kıyamet gününde kötülenmişler arasında olacaklardır."},{"n":43,"t":"Andolsun ki biz, ilk nesilleri helâk ettikten sonra, insanlar düşünüp öğüt alsınlar diye Mûsâ`ya, aydınlanma kaynağı, rehber ve rahmet olarak kitabı verdik."},{"n":44,"t":"Mûsâ`ya emrimizi bildirdiğimiz zaman, sen, batı yönünde Mûsâ`yı bekleyenler arasında değildin, onu görenler arasında da yoktun."},{"n":45,"t":"Ama biz nice nesiller var ettik. Üzerlerinden yıllar geçti. Medyen halkı arasında bulunmadığından onlara âyetlerimizi okumuyordun, fakat biz sürekli peygamberler gönderiyorduk."},{"n":46,"t":"Sen, Mûsâ`ya seslendiğimiz zaman Tûr`un yanında da değildin. Senden önce kendilerine uyarıcı gelmeyen bir toplumu uyarman için Rabbinden bir rahmet olarak gönderildin; belki düşünürler."},{"n":47,"t":"\"Rabbimiz! Keşke bize bir elçi gönderseydin de biz de Senin mesajlarına uyup inanan kimselerden olsaydık, olmaz mıydı?\" demesinler diye (gönderdik seni)."},{"n":48,"t":"Ama onlara katımızdan gerçek gelince, “Mûsâ`ya verildiği gibi buna da mucize verilmesi gerekmez mi?” derler. Daha önce Mûsâ`ya verileni de inkâr etmemişler miydi? “Yardımlaşan iki sihirbaz” demişlerdi; “hepsini inkâr edenleriz” demişlerdi."},{"n":49,"t":"“Eğer doğru sözlü iseniz, Allah katından bu ikisinden daha doğru bir kitap getirin de ona uyayım.”"},{"n":50,"t":"“Eğer sana cevap veremezlerse, onların sadece heveslerine uyduklarını bil! Allah`tan doğru bir rehber olmadan hevesine uyan kimseden daha sapık kim vardır? Şüphesiz Allah, haksızlık eden toplumu doğru yola eriştirmez.”"},{"n":51,"t":"Andolsun ki, düşünüp öğüt alsınlar diye, sözü birbiri ardınca yetiştirmişizdir."},{"n":52,"t":"Kendilerine daha önceden kitap verdiklerimiz, Kur`ân`a inanırlar."},{"n":53,"t":"`Biz ona inandık. Şüphesiz o Rabbimizden (gelen) bir gerçektir. Biz zaten bundan önce de Müslümanlar idik` derler."},{"n":54,"t":"İşte, her şeye (rağmen hakta) direnmelerine, kötülüğü iyilikle savmalarına ve kendilerine rızık olarak verdiklerimizden infak etmelerine karşılık, kendilerine iki kat ecir verilecek olan böyleleridir."},{"n":55,"t":"Onlar boş söz işittiklerinde ondan yüz çevirirler. “Bizim amellerimiz bize, sizin amelleriniz size. Size selâm olsun. Biz câhillerle arkadaş olmayız” derler."},{"n":56,"t":"Sen sevdiğini hidayete erdiremezsin; bilakis Allah dileyene hidayet verir ve hidayete girecek olanları en iyi O bilir."},{"n":57,"t":"“Biz seninle beraber doğru yola uyarsak, yurdumuzdan atılırız” dediler. “Biz onları, kendi katımızdan bir rızık olarak her şeyin ürünlerinin toplanıp getirildiği, güvenli, dokunulmaz bir yere yerleştirmedik mi? Fakat onların çoğu bilmezler.”"},{"n":58,"t":"Refahın şımarttığı nice memleketleri helâk etmişizdir. İşte yerleri! Kendilerinden sonra oralarda pek az oturulabilmiştir. Onlara biz vâris olmuşuzdur."},{"n":59,"t":"Rabbin, ana kentlerine âyetlerimizi okuyacak bir peygamber göndermedikçe, onları helâk etmiş değildir. Ancak, halkı zâlim olan ülkeleri yok ederiz."},{"n":60,"t":"Size verilen şeyler, dünya hayatının geçim vasıtası ve süsüdür. Allah katında olanlar ise, daha değerli ve daha kalıcıdır. Aklınızı kullanmayacak mısınız?"},{"n":61,"t":"Şu halde, kendisine güzel bir söz verdiğimiz ve ardından o söze kavuşan kimse, sadece dünya hayatının geçici menfaat ve zevkini yaşattığımız, sonra kıyamet gününde huzurumuza getirilenler arasında bulunan kimse gibi midir?"},{"n":62,"t":"O gün Allah onlara, “Benim ortağım olduklarını iddia ettikleriniz neredeler?” diye seslenir."},{"n":63,"t":"O gün, söz aleyhlerine gerçekleşmiş olanlar, “Ey Rabbimiz! Şunlar azdırdığımız kimselerdir. Biz nasıl azmışsak, onları da öyle azdırdık. Onlardan uzaklaşıp sana geldik, zaten onlar bize tapmıyorlardı” derler."},{"n":64,"t":"“Allah`a koştuğunuz ortaklarınızı çağırınız” denir. Onlar da çağırırlar ama, taptıkları kendilerine cevap vermezler. Cehennem azabını görünce, “Dünyadayken doğru yolda olsalardı!” diye hayıflanırlar."},{"n":65,"t":"“Peygamberlere ne cevap verdiniz?”"},{"n":66,"t":"İşte o gün, onlara bütün haberler körleşmiştir. Birbirlerine soramazlar."},{"n":67,"t":"Fakat tövbe eden, inanan ve iyi amel yapanlara gelince; onun kurtuluşa erenler arasında olması umulur."},{"n":68,"t":"Rabbin, dilediğini yaratır ve seçer. Onlar için seçim hakkı yoktur. Allah onların koştukları ortaklardan uzaktır ve yücedir."},{"n":69,"t":"Rabbin, gönüllerinin gizlediklerini ve açığa vurduklarını bilir."},{"n":70,"t":"Allah O`dur, O`ndan başka tanrı yoktur. Başında ve sonunda övgü O`nadır; egemenlik de O`nundur. Yalnız O`na döndürüleceksiniz."},{"n":71,"t":"“Düşünmez misiniz? Eğer Allah, geceyi üzerinize kıyamete kadar sürekli kılsa, Allah`tan başka size bir ışık getirebilecek tanrı kimdir? Duymuyor musunuz?”"},{"n":72,"t":"“Düşünmez misiniz? Eğer Allah gündüzü üzerinize kıyamete kadar sürekli kılsa, Allah`tan başka hangi tanrı, içinde istirahat edeceğiniz geceyi size getirebilir? Görmüyor musunuz?”"},{"n":73,"t":"Allah, dinlenmeniz için geceyi ve lütfedip verdiği rızkı aramanız için gündüzü var etmiştir. Bunlar, O`nun rahmetinden ötürüdür. Artık belki şükredersiniz."},{"n":74,"t":"“Ortağım olduklarını iddia ettikleriniz nerededir?”"},{"n":75,"t":"Her ümmetten bir tanık çıkarır ve “Kesin delilinizi ortaya koyunuz” deriz. O zaman, gerçeğin Allah`a ait olduğunu, uydurduklarının kendilerini bırakıp kaçtığını anlarlar."},{"n":76,"t":"“Şımarma! Bil ki Allah şımaranları sevmez.”"},{"n":77,"t":"“Allah`ın sana verdiğinden âhiret yurdunu iste; ama dünyadan da nasibini unutma. Allah sana iyilik ettiği gibi, sen de iyilik et. Yeryüzünde bozgunculuğu arzulama. Şüphesiz ki Allah, bozguncuları sevmez.”"},{"n":78,"t":"Kârûn, “Bu servet bana, ancak bendeki bir ilimden dolayı verilmiştir” demişti. Allah`ın ondan önce, ondan daha güçlü ve topladığı şey daha çok olan nice nesilleri yok ettiğini bilmez mi? Suçluların suçları kendilerinden sorulmaz."},{"n":79,"t":"Kârûn, gösteriş içinde toplumun karşısına çıktı. Dünya hayatını isteyenler, “Keşke Kârûn`a verildiği gibi bize de verilse; doğrusu o, büyük bir şans sahibidir” demişlerdi."},{"n":80,"t":"“Yazıklar olsun size! İman edip iyi işler yapanlara göre Allah`ın sevabı/nimeti daha iyidir. Ona da ancak sabredenler kavuşabilir.”"},{"n":81,"t":"Nihayet biz, onu da, sarayını da yerin dibine geçirdik. Allah`a karşı ona yardım edebilecek yandaşları da yoktu; o, kendini kurtarabilecek kimselerden de değildi."},{"n":82,"t":"Daha dün onun yerinde olmayı isteyenler, “Demek ki Allah, kullarından dilediğinin rızkını genişletiyor; dilediğine de daraltıyor. Şâyet Allah bize lütufta bulunmuş olmasaydı, bizi de yerin dibine geçirirdi. Vay! Demek ki inkârcılar iflah olmazmış!” demeye başladılar."},{"n":83,"t":"İşte âhiret yurdu! Biz onu yeryüzünde büyüklük taslamayan ve bozgunculuk çıkarmak istemeyen kimselere veririz. Sonuç, takvâ sahiplerinindir."},{"n":84,"t":"Kim iyilik getirirse, ona bundan daha üstünü vardır. Kim de kötülük getirirse, o kötülükleri işleyenler ancak yaptıkları kadar ceza görürler."},{"n":85,"t":"“Rabbim, kimin hidayeti getirdiğini ve kimin apaçık bir sapıklık içinde olduğunu en iyi bilendir.”"},{"n":86,"t":"Bu kitabın sana indirileceğini ummuyordun. Ancak Rabbinin bir merhameti gereği sana indirildi. Artık asla inkâr edenlere destek olma!"},{"n":87,"t":"Allah`ın âyetleri sana indirildikten sonra, sakın onlar seni bu âyetlerden alıkoymasınlar. Rabbine davet et. Asla müşriklerden olma!"},{"n":88,"t":"Allah ile birlikte başka bir tanrıya tapıp yalvarma! Ondan başka tanrı yoktur. O`nun zatından başka her şey yok olacaktır. Hüküm O`nundur ve siz ancak O`na döndürüleceksiniz."}],[{"n":1,"t":"Elif, lâm, mîm."},{"n":2,"t":"İnsanlar, imtihandan geçirilmeden, sadece “İman ettik” demeleriyle bırakılacaklarını mı sanıyorlar?"},{"n":3,"t":"Andolsun ki biz onlardan öncekileri de imtihandan geçirmişizdir. Elbette Allah, doğruları ortaya çıkaracak, yalancıları da mutlaka ortaya koyacaktır."},{"n":4,"t":"Yoksa, kötülükleri yapanlar bizden kaçabileceklerini mi sanıyorlar? Ne kadar yanlış hüküm veriyorlar!"},{"n":5,"t":"Allah`a kavuşmayı uman bilsin ki, Allah`ın belirlediği vakit gelecektir. Allah her şeyi işitir; her şeyi bilir."},{"n":6,"t":"Hak uğrunda cihad eden, sadece kendisi için cihad etmiş olur. Şüphesiz ki Allah, kimseye muhtaç değildir."},{"n":7,"t":"İman edip iyi amel işleyenlerin elbette kötülüklerini örteriz ve onlara yaptıklarının daha güzeli ile karşılık veririz."},{"n":8,"t":"Biz, insana, anne babasına iyilik etmeyi emrettik. Eğer onlar seni, tanrılığı hakkında hiçbir bilgin olmayan bir şeyi bana ortak koşmaya zorlarlarsa, artık bu durumda onlara itaat etme! Dönüşünüz yalnız banadır. Yaptıklarınızı size haber vereceğim."},{"n":9,"t":"İnanıp iyi amel yapanları kesinlikle iyi kulların arasına koyacağız."},{"n":10,"t":"İnsanlardan, “Allah`a inandık” diyenler vardır. Fakat Allah uğrunda eziyete uğrayınca, insanların işkencelerini Allah`ın azabı gibi sayarlar. Eğer Rabbin katından bir yardım gelecek olursa, “Kesinlikle biz de sizinle birlikte idik” derler. Allah herkesin sinelerinde olanları en iyi bilen değil midir?”"},{"n":11,"t":"Allah kesinlikle kimlerin gerçekten inandığını ve kimlerin de münâfık olduğunu bilmektedir."},{"n":12,"t":"Kâfirler, iman edenlere, “Bizim yolumuza uyun, sizin günahlarınızı biz yüklenelim” derler. Halbuki onların hiçbir günahını yüklenecek değillerdir. Onlar, kesinlikle yalan söylemektedirler."},{"n":13,"t":"Onlar, elbette kendi yükleriyle birlikte başka yükleri de taşımak zorunda kalacaklardır. Uydurup durdukları temelsiz iddialardan dolayı kıyamet günü kesinlikle sorguya çekileceklerdir."},{"n":14,"t":"Andolsun ki biz Nûh`u kendi kavmine gönderdik. O, bin yıldan elli yıl eksik bir süre onların arasında kaldı. Sonunda onlar zulümlerini sürdürürken tûfan kendilerini yakalayıverdi."},{"n":15,"t":"Fakat Nûh`u ve onunla birlikte gemide bulunanların hepsini kurtardık ve bunu, bütün insanlara bir ders kıldık."},{"n":16,"t":"“Allah`a kulluk ediniz. O`na karşı gelmekten sakınınız! Eğer bilmiş olsanız, bu sizin için daha iyidir.”"},{"n":17,"t":"“Siz Allah`ı bırakıp sadece birtakım putlara tapıyorsunuz ve aslı olmayan sözler uyduruyorsunuz. Doğrusu, Allah`tan başka taptıklarınızın size rızık vermeye güçleri yetmez. Artık rızkı Allah katında arayınız. O`na kulluk ediniz, O`na şükrediniz. Siz O`na döndürüleceksiniz.”"},{"n":18,"t":"Eğer yalanlarsanız, biliniz ki sizden önce de nice toplumlar peygamberlerini yalanlamışlardı. Peygamberin üzerinde, apaçık tebliğden başka bir görev yoktur."},{"n":19,"t":"Onlar Allah`ın yaratmaya nasıl başladığını, sonra onu nasıl tekrarladığını görmüyorlar mı? Şüphesiz bunu yapmak Allah`a kolaydır."},{"n":20,"t":"“Yeryüzünde dolaşınız da bakınız ki Allah yaratmaya nasıl başlamıştır? İşte Allah, aynı şekilde sonraki yaratmayı da yapacaktır. Şüphesiz Allah`ın her şeye gücü yeter.”"},{"n":21,"t":"“Dilediğine azap eder; dilediğine de merhamet eder. Sizler O`na döndürüleceksiniz.”"},{"n":22,"t":"“Sizler ne yerde ne gökte Allah`ı âciz bırakabilirsiniz. Sizin Allah`tan başka dostunuz ve yardımcınız da yoktur.”"},{"n":23,"t":"Allah`ın âyetlerini ve O`na kavuşmayı inkâr edenlere gelince; onlar benim rahmetimden ümit kesmiş olanlardır. Onlar için acıklı bir azap vardır."},{"n":24,"t":"İbrâhim`in sözlerine kavminin cevabı sadece, “Onu öldürünüz, yahut yakınız!” demek oldu. Ama Allah, onu ateşten kurtardı. Doğrusu bunda, inanan toplum için dersler vardır."},{"n":25,"t":"“Dünya hayatında, aranızdaki sevgiden dolayı, Allah`ı bırakıp putlar edindiniz; sonra kıyamet günü birbirinizi tanımazlıktan gelecek ve birbirinize lanet okuyacaksınız. Varacağınız yer cehennemdir ve hiç yardımcınız da yoktur.”"},{"n":26,"t":"Bunun üzerine, Lût, İbrâhim`e inandı. İbrâhim, “Doğrusu ben, Rabbime hicret ediyorum. Şüphesiz O, mutlak güç ve hikmet sahibidir” dedi."},{"n":27,"t":"İbrâhim`e, İshâk ve Ya‘kûb`u bağışladık. Peygamberliği ve kitapları, onun soyundan gelenlere verdik. Ona dünyada ödülünü verdik. Şüphesiz o, âhirette de iyilerdendir."},{"n":28,"t":"Lût`u da gönderdik. O, toplumuna demişti ki, “Gerçekten siz, daha önce hiçbir toplumun yapmadığı cinsel ahlâksızlığı yapıyorsunuz.”"},{"n":29,"t":"“Siz ille de erkeklere yaklaşacak, yol kesecek ve toplantılarda edepsizlikler yapacak mısınız/grup seks mi yapacaksınız?”"},{"n":30,"t":"Lût, “Ey Rabbim! Bozgunculara karşı bana yardım et!” dedi."},{"n":31,"t":"“Biz, bu memleketin halkını helâk edeceğiz. Çünkü oranın halkı zâlim/cinsel ahlaksızlıkta ileri giden kimselerdir.”"},{"n":32,"t":"“Biz, orada kimlerin bulunduğunu çok iyi biliyoruz. Onu ve ailesini elbette kurtaracağız. Yalnızca karısı müstesna; o, azapta kalacaklar arasındadır.”"},{"n":33,"t":"Elçilerimiz Lût`a gelince, Lût onlar hakkında ve onları korumak için ne yapacağını bilemedi. Ona, “Korkma, tasalanma! Çünkü biz seni de aileni de kurtaracağız. Yalnızca geri kalacaklar arasında bulunan karın müstesna” dediler."},{"n":34,"t":"Biz bu ülke halkının üzerine, yoldan çıkmalarına karşılık, gökten bir azap indireceğiz."},{"n":35,"t":"Andolsun ki biz, aklını kullanacak bir toplum için orada apaçık bir ders bırakmışızdır."},{"n":36,"t":"Medyen`e de, soydaşları Şuayb`i (göndermiştik); ve o \"Ey kavmim!\" demişti, \"Allah`a kulluk edin ki Ahiret Günü`ne umutla bakabilesiniz; dahası, kötülüğü yaygınlaştırarak yeryüzünde ahlaki çürümeye meydan vermeyin!\""},{"n":37,"t":"Fakat onu yalanladılar; bu yüzden, kendilerini bir sarsıntı yakalayıverdi ve yurtlarında dizüstü çöküverdiler."},{"n":38,"t":"Âd ve Semûd toplumlarını da helâk ettik. Helâkleri, evlerinin kalıntılarından size belli olmaktadır. Şeytan onlara yaptıklarını güzel gösterip, onları doğru yoldan çıkarmıştı. Oysa onlar gerçeği görebilirlerdi."},{"n":39,"t":"Kârûn`u, Firavun`u ve Hâmân`ı da helâk ettik. Mûsâ onlara apaçık deliller getirmişti de onlar yeryüzünde büyüklük taslayıp, kabul etmediler. Oysa bizden kaçıp kurtulamazlardı."},{"n":40,"t":"Herbirini günahından dolayı yakaladık. Kiminin üzerine taşlar savuran rüzgârlar gönderdik; kimini korkunç bir ses yakaladı, kimini yerin dibine geçirdik, kimini de suda boğduk. Allah onlara zulmetmiyor, asıl onlar kendi kendilerine zulmediyorlardı."},{"n":41,"t":"Allah`tan başka dostlar edinenlerin durumu, dişi örümceğin durumu gibidir. O, bir yuva edinir. Halbuki yuvaların en çürüğü şüphesiz dişi örümceğin yuvasıdır. Keşke bilselerdi!"},{"n":42,"t":"Şüphesiz Allah, onların kendisinden başka ne tür bir şeye yalvardıklarını bilir. O, çok güçlüdür ve hikmet sahibidir."},{"n":43,"t":"İşte bu örnekleri biz, bütün insanlara veriyoruz. Oysa onları ancak bilenler anlar."},{"n":44,"t":"Allah, gökleri ve yeri bir amaç uğruna yarattı. Bunda, inanacaklar için bir ders vardır."},{"n":45,"t":"Sana kitaptan vahyedileni oku, namazı dosdoğru kıl! Çünkü namaz, yüz kızartıcı şeylerden ve kötülüklerden alıkoyar. Allah`ı anmak en büyük ibadettir. Allah ne yaptığınızı bilir."},{"n":46,"t":"Zulmedenleri/şirk koşanları hariç, kitap ehli ile en güzel bir şekilde tartışınız ve “Bize indirilene de, size indirilene de inandık. Bizim tanrımız da, sizin tanrınız da birdir. Biz O`na teslim olmuşuzdur” deyiniz."},{"n":47,"t":"Böylece sana kitabı indirdik. İşte, kendilerine kitap verdiklerimiz ona inanırlar. Çevrendekilerden de ona inananlar vardır. Âyetlerimizi, ancak inkârcılar bile bile tanımazlar."},{"n":48,"t":"Sen daha önce bir kitaptan okuyup sağ elinle de yazarak kopya çekmiş değilsin. Öyle olsaydı, saçmalayanlar şüpheye düşerlerdi."},{"n":49,"t":"Oysa tam aksine, Kur`ân, kendilerine ilim verilenlerin gönüllerinde apaçık âyetler halindedir. Bizim âyetlerimizi zâlimlerden başkası inkâr edemez."},{"n":50,"t":"Onlar, “Ona, Rabbinden ayetler/mucizeler indirilseydi ya!” dediler. De ki, “Mucizeler yalnız Allah`ın katındadır. Ben, sadece apaçık bir uyarıcıyım.”"},{"n":51,"t":"Kendilerine okunan bu Kitab`ı sana indirmiş olmamız onlara yetmiyor mu? Bu olay, mü`minler için ders alınacak, düşündürücü bir rahmettir."},{"n":52,"t":"“Benimle sizin aranızda şahit olarak Allah yeter. O, göklerde ve yerde ne varsa bilir. Bâtıla inanıp Allah`ı inkâr edenler var ya, işte ziyana uğrayacaklar onlardır.”"},{"n":53,"t":"Senden, azabı çabucak getirmeni istiyorlar. Eğer belirlenmiş bir süre olmasaydı, o azap kesinlikle onlara gelirdi. Fakat onlar farkında değilken azap ansızın kendilerine geliverecektir."},{"n":54,"t":"Senden, azabı çabucak getirmeni istiyorlar. Hiç şüpheleri olmasın, cehennem, kâfirleri çepeçevre kuşatacaktır."},{"n":55,"t":"O gün azap, onların hem üstlerinden hem ayaklarının altından saracak ve Allah onlara, “Yaptıklarınızı tadın!” diyecektir."},{"n":56,"t":"“Ey iman eden kullarım! Elbette benim yarattığı yeryüzü geniştir. O halde yalnız bana kulluk ediniz!”"},{"n":57,"t":"Her can ölümü tadacaktır, sonra bize döndürüleceksiniz."},{"n":58,"t":"İman edip iyi ameller işleyenleri, elbette onları, içinde çok uzun süreli kalmak üzere, içinden ırmaklar akan cennet köşklerine yerleştireceğiz. Böyle iyi amel yapanların ödülü ne güzeldir!"},{"n":59,"t":"Onlar, sabreden ve yalnız Rabblerine güvenip dayanan kimselerdir."},{"n":60,"t":"Besinlerini temin edemeyen nice canlılar vardır. Onları da sizi de besleyen Allah`tır. O, her şeyi duyar, her şeyi bilir."},{"n":61,"t":"Onlara, “Gökleri ve yeri kimin yarattığını, güneşe ve aya kimin boyun eğdirdiğini” sorsan, kesinlikle “Allah” diyecekler. Nasıl döndürülüyorlar?"},{"n":62,"t":"Allah, kullarından dilediğine bol rızık verir, dilediğine de kısar. Allah her şeyi bilir."},{"n":63,"t":"“Bütün övgüler Allah`a aittir. Fakat onların çoğu bunu akletmezler.”"},{"n":64,"t":"Bu dünya hayatı oyun ve eğlenceden başka bir şey değildir. Şüphesiz âhiret yurdu ise, çok uzun süreli yaşanacak yerdir. Keşke bilseler!"},{"n":65,"t":"Gemiye bindikleri zaman, içten inanarak Allah`a yalvarırlar. Ama Allah, onları kurtarıp karaya çıkarınca bir de bakarsın ortak koşarlar."},{"n":66,"t":"Böylece kendilerine bahşettiğimiz nimetlere karşı nankörlük yapar ve dünyadaki hayatlarından zevk almaya devam ederler. Fakat yakında bileceklerdir."},{"n":67,"t":"Onlar, ülkelerini kutsal ve güvenli bir yer haline getirdiğimizi görmezler mi? Oysa onların çevresindeki insanlar sürekli saldırılara uğramaktadırlar. Onlar, bâtıla inanıp Allah`ın nimetini inkâr mı ediyorlar?"},{"n":68,"t":"Kendi uydurduğu yalanları Allah`a isnat eden veya ona gelen hakikati yalanlayandan daha zâlim kim olabilir? Cehennem, inkârcıların barınağı değil mi?"},{"n":69,"t":"Bizim davamız uğrunda Kur`an ile mücadele edenlere, elbette onlara yollarımızı göstereceğiz. Şüphesiz, Allah güzeli hayata geçirenlerle beraberdir."}],[{"n":1,"t":"Elif, lâm, mîm."},{"n":"2-5","t":"Rumlar, en yakın yerde yenildiler. Onlar, bu yenilgilerinden sonra birkaç yıl içinde yeneceklerdir. İş, eninde sonunda Allah`a aittir. İşte o gün, inananlar, isteyene yardım eden Allah`ın yardımına sevineceklerdir. Allah, güçlüdür; merhamet sahibidir."},{"n":6,"t":"Bu, Allah`ın verdiği sözdür. Allah, verdiği sözden dönmez. Fakat insanların çoğu bilmezler."},{"n":7,"t":"Onlar, dünya hayatının sadece görünen kısmını bilirler. Oysa onlar, gerçekten âhiretten habersizdirler."},{"n":8,"t":"Kendi kendilerine, Allah`ın, gökleri, yeri ve ikisinin arasındakileri ancak bir amaç için ve sonu belirli bir süreye bağlı olarak yarattığını düşünmezler mi? İnsanlardan birçoğu, Rablerine kavuşacaklarını inkâr etmektedirler."},{"n":9,"t":"Yeryüzünde dolaşıp da, kendilerinden öncekilerin sonlarının nasıl olduğuna bakmazlar mı? Onlar kendilerinden daha kuvvetli idiler; toprağı ekmişler, orayı bunlardan daha fazla imar etmişlerdi. Peygamberleri de onlara nice açık deliller getirmişti. Sonunda Allah, onlara haksızlık etmedi. Onlar kendi kendilerine haksızlık ediyorlardı."},{"n":10,"t":"Sonra, kötülük yapanların sonu çok kötü oldu. Çünkü onlar, Allah`ın âyetlerini yalanlıyorlar ve alaya alıyorlardı."},{"n":11,"t":"Allah, ilkin varlıkları yaratır, sonra da bunu tekrarlar/tekrar diriltir; sonunda hep O`na döndürüleceksiniz."},{"n":12,"t":"Kıyametin kopacağı gün, günahkârlar büsbütün ümitlerini kaybedeceklerdir."},{"n":13,"t":"Allah`a koştukları ortaklarından kendilerine hiçbir şefaatçi çıkmayacaktır. Zaten onlar, ortaklarını da inkâr edeceklerdir."},{"n":14,"t":"Kıyamet kopacağı gün, işte o gün birbirlerinden ayrılacaklardır."},{"n":15,"t":"İman edip iyi ameller işleyenlere gelince, onlar cennette bol nimet ve sevince kavuşacaklardır."},{"n":16,"t":"Âyetlerimizi ve âhiret buluşmasını inkar edenlere gelince, işte onlar azapla yüz yüze bırakılacaklardır."},{"n":"17-18","t":"O halde, akşama ulaştığınızda, sabaha kavuştuğunuzda, gündüzün sonunda ve öğle vaktine eriştiğinizde Allah`ı tesbîh ediniz/namaz kılınız! Göklerde ve yerde övgü O`na aittir."},{"n":19,"t":"Ölüden diriyi, diriden de ölüyü O çıkartıyor; yeryüzünü ölümünün ardından O canlandırıyor. İşte siz de böyle çıkartılacaksınız."},{"n":20,"t":"Sizi topraktan yaratması, ardından insan olarak yeryüzüne dağılmanız, O`nun varlığının delillerindendir."},{"n":21,"t":"Kaynaşmanız için size kendinizden eşler yaratıp aranızda sevgi ve merhamet meydana getirmesi de O`nun delillerindendir. Doğrusu bunda düşünen bir toplum için dersler vardır."},{"n":22,"t":"Gökleri ve yeri yaratması, lisanlarınızın ve renklerinizin değişik olması yine O`nun varlığının delillerindendir. Şüphesiz bunda bilenler için dersler vardır."},{"n":23,"t":"Gece olsun, gündüz olsun, uyumanız ve Allah`ın lütfundan nasibinizi aramanız da O`nun varlığının delillerindendir. Şüphesiz bunda, dinleyen bir kavim için dersler vardır."},{"n":24,"t":"Size korku ve ümit vermek üzere şimşeği gösteriyor, gökten su indirip ölümünün ardından yeri onunla diriltiyor olması O`nun varlığının delillerindendir. Doğrusu bunda aklını kullanan toplum için dersler vardır."},{"n":25,"t":"Göğün ve yerin O`nun emri ile durması da O`nun varlığının delillerindendir. Sonra sizi topraktan bir çağırma ile çağıracak; siz de hemen çıkıvereceksiniz."},{"n":26,"t":"Göklerde ve yerde olanlar hep O`nundur. Hepsi O`na boyun eğmiştir."},{"n":27,"t":"İlkin varlıkları yaratıp, sonra yaratmayı tekrarlayan O`dur. İkinci yaratma O`nun için pek kolaydır. Göklerde ve yerde en yüce sıfat O`nundur. O, sonsuz güç ve hikmet sahibidir."},{"n":28,"t":"“Size verdiğimiz mallarda hizmetçilerinizden ortaklarınız var mı? Siz ve hizmetçileriniz mallarda eşit misiniz? Bu konuda birbirinizden çekindiğiniz gibi onlardan da çekinir misiniz?” İşte biz akıllarını kullanan insanlara âyetlerimizi böyle açıklıyoruz."},{"n":29,"t":"Hayır, zulmedenler, hiç bir bilgiye dayanmaksızın kendi heva (istek ve tutku)larına uymuşlardır. Allah`ın saptırdığını kim hidayete erdirebilir? Onların hiç bir yardımcıları yoktur."},{"n":30,"t":"Böylece sen, bâtıl olan her şeyden arınmış olarak, yüzünü kararlı bir şekilde Allah`ın, insanları üzerinde yarattığı doğa/fıtrat kanununa/ dine çevir! Allah`ın, insanın doğasına yerleştirdiği fıtrata uygun davran ki, Allah`ın yaratmasında bir değişime meydan verilmesin. Bu, gerçek dinin amacıdır; fakat insanların çoğu bilmez."},{"n":31,"t":"Bütün kalbinizle Allah`a yönelenler olarak O`na saygı duyunuz; namazı kılınız; müşriklerden olmayınız!"},{"n":32,"t":"Dinlerini parçalayan ve gruplara ayrılanlardan olmayınız! Her grup, kendilerinde olan ile böbürlenmektedir."},{"n":33,"t":"İnsanlara bir sıkıntı dokunduğunda, Rabblerine yönelerek yalnız O`na yalvarırlar. Fakat katından onlara bir rahmet/çözüm tattırınca, bir de bakarsın ki onlardan bir grup yine Rabblerine ortak koşuyorlar."},{"n":34,"t":"Kendilerine bahşettiğimiz nimetlere karşı nankörlük etsinler bakalım. Haydi, sefa sürün; fakat yakında öğreneceksiniz."},{"n":35,"t":"Yoksa biz onlara, bizden başkasına kulluk yapmalarını söyleyen bir delil mi gönderdik?"},{"n":36,"t":"İnsanlara katımızdan bir bolluk tattırdığımızda buna sevinirler. Fakat yaptıklarından dolayı başlarına bir kötülük geldiğinde hemen ümitsizliğe düşerler."},{"n":37,"t":"Onlar, Allah`ın rızkı dilediğine bol verdiğini, dilediğine ölçülü verdiğini görmezler mi? Bunda, şüphesiz inanan insanlar için dersler vardır!"},{"n":38,"t":"Yakın akrabaya hakkını ver, yoksula ve yolda kalmışa da! Bu, Allah`ın rızasını kazanmak isteyenler için daha iyidir. Onlar kurtuluşa ereceklerdir."},{"n":39,"t":"İnsanların mallarında artış olsun diye verdiğiniz herhangi bir faiz, Allah katında artmaz. Allah`ın rızasını umarak verdiğiniz zekâta gelince, işte zekâtı veren o kimseler, evet işte onlar sevaplarını ve mallarını kat kat arttıranlardır."},{"n":40,"t":"Sizi yaratan, sonra sizi besleyen, sonra öldürüp ardından tekrar diriltecek olan Allah`tır. Sizin ortak koştuklarınızdan bunları yapacak birisi var mı? Allah, onların ortak koştuklarından uzak ve yücedir."},{"n":41,"t":"İnsanların bizzat kendilerinin işledikleri yüzünden, karada ve denizde çürüme ve bozulma başladı. Allah, belki geri dönerler diye yaptıklarının bazı sonuçlarını onlara tattıracaktır."},{"n":42,"t":"“Yeryüzünde dolaşınız da öncekilerin sonlarının nasıl olduğuna ibretle bakınız. Onların çoğu ortak koşuyordu.”"},{"n":43,"t":"Allah tarafından gelecek ve hiçbir kimsenin geri çeviremeyeceği o gün gelmeden önce yönünü bu dosdoğru dine çevir. O gün insanlar, yaptıklarına göre gruplara ayrılırlar."},{"n":44,"t":"Kim inkâr ederse inkârı kendi aleyhine olur. Yararlı bir iş yapanlar da cennette kendileri için yer hazırlamaktadırlar."},{"n":45,"t":"Çünkü Allah, inanıp yararlı iş yapanları kendi lütfundan ödüllendirir. O, kâfirleri asla sevmez."},{"n":46,"t":"Şükredesiniz diye, sonsuz rahmetinden size tattırması, emri ile gemilerin seyretmesi ve lütfundan rızkınızı aramanız için rüzgârları yağmurun müjdecileri olarak göndermesi de Allah`ın varlığının delillerindendir."},{"n":47,"t":"Senden önce nice peygamberleri kendi toplumlarına göndermiştik. Onlara apaçık deliller getirmişlerdi. Biz, sonunda suçlulardan öç aldık. İnananlara yardım etmeyi üzerimize almışızdır."},{"n":48,"t":"Allah, rüzgârları gönderip bulutları harekete geçirir. Onları gökyüzünde dilediği gibi yayıp kütleler haline getirir. Sen yağmuru bulutlardan yağarken görürsün. Bu yağmuru kullarından dilediklerine yağdırınca, hemen sevinirler."},{"n":49,"t":"Oysa onlar daha evvel, yağmurdan önce ümitsizliğe düşmüşlerdi."},{"n":50,"t":"Allah`ın rahmetinin belirtilerine bak! Nasıl ölümünden sonra toprağa hayat veriyor. Şüphesiz O, ölüleri de böyle diriltecektir. O`nun her şeye gücü yeter."},{"n":51,"t":"Biz onlara bir rüzgâr göndersek de o bitkileri sapsarı olmuş görseler, kesinlikle inkârlarını sürdürürler."},{"n":52,"t":"Elbette sen manen ölülere duyuramazsın; arkalarını dönüp giderlerken manen sağırlara o daveti işittiremezsin."},{"n":53,"t":"Manen körleri de sapıklıklarından doğru yola iletemezsin. Ancak teslimiyet göstererek âyetlerimize iman edebileceklere duyurabilirsin."},{"n":54,"t":"Sizi önce zayıf yaratıp sonra bu zayıflığın ardından size güç veren, sonra bu gücün ardından sizi tekrar zayıf ve yaşlı kılan Allah`tır. Allah, dilediğini yaratır. O, her şeyi bilendir; her şeye gücü yetendir."},{"n":55,"t":"Kıyamet koptuğu gün, suçlular dünyada ancak pek kısa kaldıklarına yemin ederler. İşte onlar dünyada haktan böyle döndürülüyorlardı."},{"n":56,"t":"“Andolsun ki, siz Allah`ın yazısında yeniden dirilme gününe kadar kaldınız. İşte bugün dirilme günüdür. Fakat siz onu bilmiyordunuz.”"},{"n":57,"t":"Artık o gün, zulmedenlerin mazeretleri fayda vermeyeceği gibi, onlardan kendilerini düzeltmeleri de istenmeyecektir."},{"n":58,"t":"“Siz, sadece bâtıl şeyler ortaya koymaktasınız.”"},{"n":59,"t":"İşte, gerçeği bilmeyenlerin kalplerini Allah böyle mühürlemektedir."},{"n":60,"t":"Sen şimdi sabret! Şüphesiz Allah`ın vaadi gerçektir. Kesin inanca sahip olmayanlar, sakın seni gevşekliğe sevketmesin!"}],[{"n":1,"t":"Elif, lâm, mîm."},{"n":2,"t":"Bunlar, hikmet dolu kitabın âyetleridir."},{"n":3,"t":"Güzel işler yapanlar için bir rehber ve bir rahmet kaynağıdırlar."},{"n":4,"t":"Güzeli hayata geçirenler, namazı dosdoğru kılarlar, zekâtı verirler; onlar âhirete de kesin olarak iman ederler."},{"n":5,"t":"İşte onlar, Rabblerinin göstermiş olduğu doğru yol üzerindedirler ve onlar mutluluğa ereceklerdir."},{"n":6,"t":"Bazı insanlar vardır ki, cahillikleri yüzünden başkalarını Allah yolundan saptırmak ve o yolu eğlence vesilesi edinmek için boş laf satın alırlar. İşte onlar için aşağılayıcı bir azap vardır."},{"n":7,"t":"Ona âyetlerimiz okunduğu zaman sanki bunları işitmemiş, sanki kulaklarında ağırlık varmış gibi kibirlenerek yüz çevirirler. Sen de ona acıklı bir azabı müjdele!"},{"n":"8-9","t":"İnanıp yararlı iş yapanları ise nimetlerle dolu, süreli olarak kalacakları cennetler bekliyor. Bu, Allah`ın gerçek bir vaadidir. O`nun gücü her şeye yeter; her işinde hikmet vardır."},{"n":10,"t":"Allah, gökleri, görebileceğiniz direkler olmadan yarattı. Sizi sarsmasın diye yeryüzüne sabit dağlar koydu ve orada her çeşit canlının çoğalmasını sağladı. Biz, gökyüzünden su indirip orada her türlü faydalı bitkiler yetiştirmişizdir."},{"n":11,"t":"Bunların hepsi Allah`ın yarattığıdır. O`ndan başkasının ne yarattığını bana gösteriniz. Hayır; zâlimler apaçık sapıklık içindedirler."},{"n":12,"t":"Andolsun biz, Lokmân`a “Allah`a şükret” diye hikmet verdik. Şükreden ancak kendisi için şükretmiş olur. Nankörlük eden de bilsin ki Allah, hiçbir şeye muhtaç değildir; her türlü övgüye lâyıktır."},{"n":13,"t":"“Yavrucuğum! Allah`a asla ortak koşma! Çünkü şirk, büyük bir zulümdür.”"},{"n":14,"t":"Biz, insana, anne babasına iyi davranmasını emrettik. Annesi onu, sıkıntı üstüne sıkıntı çekerek karnında taşıdı. Sütten kesilmesi iki yıl içinde oldu. “Bana ve anne babana şükret!” dedik. Dönüş sadece banadır."},{"n":15,"t":"Eğer anne baban seni bir şeyi körü körüne bana ortak koşman için zorlarlarsa, onlara itaat etme! Onlarla dünyada iyi geçin! Bana yönelenlerin yoluna uy! Sonunda dönüşünüz ancak banadır. O zaman size, yapmış olduklarınızı haber vereceğim."},{"n":16,"t":"“Yavrucuğum! Yaptığın iş bir hardal tanesi ağırlığında bile olsa ve bu, bir kayanın içinde veya göklerde yahut yerin derinliklerinde bulunsa, yine de Allah onu ortaya çıkarır. Doğrusu Allah en ince işleri görüp bilmektedir; her şeyden haberdardır.”"},{"n":17,"t":"“Yavrucuğum! Namazı dosdoğru kıl, iyiliği emret, kötülükten sakındırmaya çalış, başına gelenlere sabret! Doğrusu bunlar, azim ve kararlılık gösterilmeye değer şeylerdendir.”"},{"n":18,"t":"“Küçümseyerek insanlardan yüzçevirme ve yeryüzünde böbürlenerek yürüme! Zira Allah, kendini beğenmiş, övünüp duran kimseleri asla sevmez.”"},{"n":19,"t":"“Yürüyüşünde ölçülü ve dengeli ol, sesini alçalt! Unutma ki, seslerin en çirkini eşek sesidir.”"},{"n":20,"t":"Allah`ın, göklerde ve yerde bulunan her şeyi sizin emrinize boyun eğdirdiğini, açık ve gizli bütün nimetlerini size bolca verdiğini görmez misiniz? İnsanlardan bazıları, Allah hakkında hiçbir bilgisi olmadan, rehberi ve aydınlatıcı bir kitabı bulunmadan tartışmaya girerler."},{"n":21,"t":"Onlara, “Allah`ın indirdiğine uyunuz” denince; “Babalarımızı üzerinde bulduğumuz yola uyarız” derler. Şeytan onları alevli ateşe çağırmış olsa da mı?"},{"n":22,"t":"İyi davranarak kendini Allah`a teslim eden kimse, şüphesiz en sağlam kulpa tutunmuş olur. İşlerin sonucu Allah`a aittir."},{"n":23,"t":"İnkâr edenin inkârı seni üzmesin. Onların dönüşü bizedir. O zaman yaptıklarını kendilerine haber veririz. Şüphesiz ki Allah, sinelerde olanı bilir."},{"n":24,"t":"Onlara biraz geçim sağlar, sonra ağır bir azaba sürükleriz."},{"n":25,"t":"“Övgü, Allah`a aittir. Ama onların çoğu bilmiyorlar.”"},{"n":26,"t":"Göklerde ve yerde ne varsa hepsi Allah`ındır. Şüphesiz yalnızca Allah, kendi kendine yeterlidir; bütün övgüler O`na aittir."},{"n":27,"t":"Yeryüzünde bulunan ağaçlar kalem olsa, yedi denizle desteklenen bir deniz de mürekkep olsa, yine de Allah`ın sözleri yazmakla bitmezdi. Doğrusu Allah, güçlüdür; hikmet sahibidir."},{"n":28,"t":"Hepinizin yaratılması ve yeniden diriltilmesi, tek bir canlının yaratılması ve diriltilmesi gibidir. Şüphesiz ki, Allah her şeyi işitendir; her şeyi görendir."},{"n":29,"t":"Allah`ın, geceyi gündüze ve gündüzü de geceye kattığını, güneşi ve ayı insanların hizmetine verdiğini görmedin mi? Bunlardan her biri belirlenen süreye kadar yörüngelerinde seyredip dururlar. Allah yaptığınız her şeyden haberdardır."},{"n":30,"t":"Bütün bunlar, Allah`ın yegâne gerçek tanrı, O`ndan başka her şeyin bâtıl olduğunu göstermektedir. Çünkü Allah, yücedir; büyüktür."},{"n":31,"t":"Size kudretinin delillerinden bir kısmını göstermek için gemilerin denizde Allah`ın lütfuyla seyrettiğini görmedin mi? Bunda, sabreden ve şükreden herkes için dersler vardır."},{"n":32,"t":"Dağlar gibi dalgalar insanları kuşattığı zaman dini yalnız Allah`a has kılarak O`na yalvarırlar. Allah onları karaya çıkarıp kurtardığı zaman, içlerinden bir kısmı gevşeme gösterirler. Zaten bizim ayetlerimizi nankör gaddarlardan başkası inkâr etmez."},{"n":33,"t":"Ey İnsanlar! Rabbinize karşı saygılı olunuz! Ebeveynin çocuğuna, çocuğun ebeveynine fayda veremeyeceği bir günden sakınınız! Allah`ın verdiği söz elbette gerçektir. Dünya hayatı sakın sizi aldatmasın! Şeytan sizi Allah ile aldatmasın!"},{"n":34,"t":"Şüphesiz, kıyametin bilgisi yalnız Allah katındadır. Yağmuru O yağdırır. Rahimlerde ne olduğunu da bilir. Hiç kimse yarın ne kazanacağını bilemez. Hiç kimse nerede öleceğini de bilemez. Her şeyi bilen ve her şeyden haberdar olan, Allah`tır."}],[{"n":1,"t":"Elif, lâm, mîm."},{"n":2,"t":"Kendinde şüphe olmayan bu kitabı, âlemlerin Rabbi olan Allah indirmektedir."},{"n":3,"t":"Yoksa “onu Muhammed uydurdu” mu diyorlar? Hayır, o, senden önce kendilerine bir uyarıcı gelmemiş olan bir toplumu uyarman için Rabbin tarafından gelen bir haktır/kitaptır. Umulur ki doğru yolu bulurlar."},{"n":4,"t":"Allah, gökleri, yeri ve bunların arasındakileri altı günde/evrede/dönemde yaratan, sonra arşı hakimiyeti altına alandır. O`ndan başka ne bir dost ne de bir şefaatçiniz vardır. Düşünüp ders almıyor musunuz?"},{"n":5,"t":"Allah, gökten yere kâinat ve içindeki varlıklarla, dünya ve ötesi ile ilgili ilâhî planlamayı yapıp yürütüyor, hayatın devamını ve aslî düzeni sağlıyor. Sonra bütün işler, sizin hesaplamalarınıza göre, bin yıl tutan bir günde kaydedilmek için O’nun nezdine yükselir."},{"n":6,"t":"Allah, görülen ve görülmeyen her şeyi bilir; çok güçlüdür; çok merhametlidir."},{"n":7,"t":"O, yarattığı her şeyi en güzel yaratmış ve insanın yaratılışına çamurdan başlamıştır."},{"n":8,"t":"Sonra onun soyunu değersiz bir suyun özünden devam ettirmiştir."},{"n":9,"t":"Sonra ona güzel bir şekil verip kendi ruhundan üflemiştir. Size kulaklar, gözler ve kalpler vermiştir. Ne kadar az şükrediyorsunuz!"},{"n":10,"t":"“Toprağın içinde kaybolduğumuzda, gerçekten biz mi yeniden yaratılacağız?” derler. Gerçekten onlar, Rabblerine kavuşmayı inkâr etmektedirler."},{"n":11,"t":"“Size vekil kılınan ölüm meleği canınızı alacak, sonra Rabbinize döndürüleceksiniz.”"},{"n":12,"t":"O suçluların, Rabblerinin huzurunda başlarını eğerek, “Ey Rabbimiz! Gördük, duyduk. Artık bizi dünyaya geri gönder de iyi işler yapalım. Çünkü biz kesin olarak inandık” diyecekleri anı bir görsen!"},{"n":13,"t":"Biz dileseydik herkesi doğru yola iletirdik. Fakat, “cehennemi tamamen cinlerden ve insanlardan dolduracağım” diye söz verdim."},{"n":14,"t":"Suçlulara, “Bu gününüze kavuşacağınızı unuttuğunuzdan dolayı cezanızı çekin! Biz de sizi unuttuk. Yaptıklarınızdan dolayı süreli azabı tadın!” denilecektir."},{"n":15,"t":"Bizim âyetlerimize ancak, onlar hatırlatıldığında secdeye kapanan, Rabblerini övgü ile tesbih eden ve büyüklük taslamayan kimseler inanırlar."},{"n":16,"t":"Onlar geceleyin yataklarından kalkarlar. Korku ve ümit içinde Rabblerine dua ederler. Verdiğimiz rızıklardan da karşılıksız yardım ederler."},{"n":17,"t":"Yaptıklarına karşılık olarak onlar için, gözleri aydınlatıcı ne mutluluklar saklandığını hiç kimse bilemez."},{"n":18,"t":"İnananla yoldan çıkan bir olur mu? Elbette bir olamazlar."},{"n":19,"t":"İnanıp iyi amelde bulunanlara gelince; onlar için, yaptıklarına karşılık konaklayacakları cennetler vardır."},{"n":20,"t":"Yoldan çıkanlar ateşte konaklayacaklardır. Oradan her çıkmak istediklerinde, tekrar oraya geri döndürülürler ve kendilerine, “Yalanladığınız cehennem azabını tadın!” denir."},{"n":21,"t":"Andolsun ki, biz onlara o büyük azaptan önce pek yakın/dünya azabı da tattıracağız. Belki dönerler!"},{"n":22,"t":"Rabbinin âyetleri kendilerine hatırlatıldıktan sonra onlardan yüz çevirenlerden daha zâlim kim vardır? Biz suçlulardan kesinlikle öç alacağız."},{"n":23,"t":"Andolsun ki biz, Mûsâ`ya kitâbı verdik. Mûsâ`nın ona kavuştuğu hususunda hiç şüphe etme! Biz onu İsrâiloğulları`na bir rehber kıldık."},{"n":24,"t":"Sabretmelerinden dolayı onlardan, bizim emrimizle kendilerine doğru yolu gösteren önderler tayin ettik. Onlar, bizim âyetlerimize kesin olarak inanıyorlardı."},{"n":25,"t":"Şüphesiz ki Rabbin, kıyamet gününde bizzat kendisi, onların aralarında ihtilafa düştükleri konularda hükmünü verecektir."},{"n":26,"t":"Halen yurtlarında gezip dolaştıkları, kendilerinden önceki nice nesilleri helâk edişimiz onları doğru yola sevketmedi mi? Bunlarda elbette dersler vardır. Hâlâ kulak vermiyorlar mı?"},{"n":27,"t":"Kupkuru topraklara suyu ulaştırdığımızı, onunla gerek hayvanlarının gerekse kendilerinin yemekte oldukları ekini çıkarmakta olduğumuzu da görmüyorlar mı? Hâlâ görmeyecekler mi?"},{"n":28,"t":"“Eğer doğru söylüyorsanız, bu hüküm günü ne zaman?”"},{"n":29,"t":"“İnkâr edenlere, hüküm gününde inanmaları hiçbir fayda vermez ve onlara süre de tanınmaz.”"},{"n":30,"t":"Artık onlardan yüz çevir ve bekle! Onlar da beklemektedirler."}],[{"n":1,"t":"Ey Peygamber! Allah`a saygılı ol! İnkârcılara ve münâfıklara itaat etme! Elbette Allah, her şeyi bilmektedir; her şeyi yerli yerince yapmaktadır."},{"n":2,"t":"Rabbinden sana vahyolunana uy! Şüphesiz ki Allah, yaptıklarınızdan haberdardır."},{"n":3,"t":"Allah`a güven! Vekil olarak Allah yeter."},{"n":4,"t":"Allah, hiçbir insanın içine iki kalp koymamıştır. Zıhâr yaptığınız/sırtlarını annenize benzettiğiniz eşlerinizi de analarınızın gibi saymadı ve evlatlıklarınızı da öz oğullarınız olarak tanımadı. Bunlar, sizin dillerinize doladığınız sözlerdir. Allah, gerçeği söylemektedir, doğru yola O iletir."},{"n":5,"t":"Evlatlıklarınızı öz babaları adına çağrınız! Allah katında en doğru olan budur. Eğer babalarının kim olduğunu bilmiyorsanız, bu takdirde onları din kardeşleriniz ve görüp gözettiğiniz kimseler olarak kabul ediniz. Yanılarak yaptıklarınızda size günah yoktur; ama kalplerinizin bile bile yöneldiğinde günah vardır. Allah bağışlayandır; merhamet edendir."},{"n":6,"t":"Peygamber, müminlere kendilerinden daha yakındır. Peygamber`in eşleri müminlerin anneleridir. Akraba olanlar, Allah`ın kitabına göre, birbirlerine diğer müminlerden ve muhacirlerden daha yakındırlar. Ancak, dostlarınıza uygun bir vasiyet yapmanız istisnadır. Bunlar kitapta yazılı bulunmaktadır."},{"n":7,"t":"Bütün peygamberlerden, senden, Nûh`tan, İbrâhim`den, Mûsâ`dan, Meryem oğlu İsâ`dan söz aldığımızı hatırla! Biz onların hepsinden sağlam bir söz aldık."},{"n":8,"t":"Allah, o doğru kişilere ne söylediklerini soracaktır. Allah inkâr edenler için de acıklı bir azap hazırlamıştır."},{"n":9,"t":"Ey iman edenler! Size ordular saldırdığında, onların üzerlerine rüzgâr ve görmediğiniz askerler gönderen Allah`ın, size olan nimetini hatırlayınız! Allah, yaptığınız her şeyi görmektedir."},{"n":10,"t":"Onlar, hem yukarınızdan hem aşağınızdan üzerinize yürüdükleri zaman; gözler yıldığı, yürekler gırtlaklara geldiği ve siz, Allah hakkında türlü türlü zanda bulunduğunuz zaman."},{"n":11,"t":"İşte orada, müminler imtihandan geçirilmişler ve şiddetle sarsılmışlardır."},{"n":12,"t":"Münâfıklar ile kalplerinde hastalık olanlar, “Meğer Allah ve Peygamberi bize boş vaadlerden başka bir şeyde bulunmadı” diyorlardı."},{"n":13,"t":"İçlerinden bir grup da, “Ey Yesrib halkı! Tutunacak bir yeriniz kalmadı, geri dönünüz” demişti. Onlardan başka bir grup da Peygamberden, “Evlerimiz korumasız kaldı” diyerek izin istiyordu. Oysa evleri korumasız değildi. Sadece kaçmak istiyorlardı."},{"n":14,"t":"Medine`nin her yanından üzerlerine saldırılsaydı da, o zaman savaşmaları istenseydi, şüphesiz hemen savaşa katılırlar ve fazla beklemezlerdi."},{"n":15,"t":"Andolsun ki daha önce onlar, sırt çevirip kaçmayacaklarına dair Allah`a söz vermişlerdi. Allah`a verilen söz, mesuliyeti gerektirir."},{"n":16,"t":"“Eğer ölümden veya savaştan kaçarsanız, kaçmanızın size asla bir faydası olmaz! O takdirde de yaşatılacağınız süre çok değildir.”"},{"n":17,"t":"“Eğer Allah, size bir kötülük dilese veya size rahmet dilese, O`nun bu isteğine kim engel olabilir? Onlar kendilerine Allah`tan başka ne bir dost ne de yardımcı bulabilirler.”"},{"n":18,"t":"Allah, sizden savaştan alıkoyanları ve kardeşlerine “Bize katılın!” diyenleri, kesin olarak bilmektedir. Zaten bunların pek azı savaşa gelir."},{"n":19,"t":"Savaşa gelseler de sizin başarılı olmanızı istemezler. Hele korku gelip çattı mı, üzerine ölüm baygınlığı çökmüş gibi gözleri dönerek sana baktıklarını görürsün. Korku gidince, ganimete karşı aç gözlülüklerinden dolayı, size sivri dillerini uzatırlar. Onlar iman etmiş değillerdir, bundan dolayı Allah, onların yaptıklarını boşa çıkarmıştır. Bu, Allah için kolaydır."},{"n":20,"t":"Münâfıklar, düşman birliklerinin gitmediklerini sanıyorlar. O düşman birlikleri yeniden gelecek olsa, onlara koşarak, çölde bedevîlerle birlikte yaşayıp sizin haberlerinizi sormayı temenni ederler. Onlar savaşta sizinle birlikte olsalardı da düşmanla çok az savaşırlardı."},{"n":21,"t":"Şüphesiz, sizden Allah`a ve âhiret gününe kavuşmayı uman ve Allah`ı çok ananlar için, Allah`ın Peygamberinde güzel bir örnek vardır."},{"n":22,"t":"Müminler, düşman gruplarını gördüklerinde, “İşte, Allah`ın ve Peygamberinin bize vaad ettiği budur. Allah ve Peygamberi doğru söylemiştir” derler. Bu durum, onların sadece imanlarını ve teslimiyetlerini arttırmıştır."},{"n":23,"t":"Delikanlı müminler, Allah`a verdikleri sözü yerine getirdiler. Onlardan bir kısmı bu uğurda can verdi, bir kısmı da can vermeyi beklemektedir. Onlar sözlerini asla değiştirmezler."},{"n":24,"t":"Allah, o doğru kişileri doğruluklarından dolayı ödüllendirecek ve münâfıkları da dilerse cezalandıracak veya tövbelerini kabul edecektir. Şüphesiz Allah çok bağışlayıcıdır; çok merhamet sahibidir."},{"n":25,"t":"Allah, inkâr edenleri, kinleriyle birlikte geri çevirdi. Onlar hiçbir başarı elde edemediler. Savaşta, inananlara Allah yeter. Allah çok kuvvetlidir; çok güçlüdür."},{"n":26,"t":"Allah, kitap ehlinden düşman gruplara yardım edenleri kalelerinden indirip, kalplerine korku saldı. Siz onlardan bir grubu öldürüyor, bir grubu da esir alıyordunuz."},{"n":27,"t":"O, sizi onların topraklarına, evlerine, mallarına ve henüz ayak basmadığınız nice topraklara mirasçı kıldı. Allah`ın gücü her şeye yeter."},{"n":28,"t":"“Eğer dünya hayatını ve onun süsünü istiyorsanız, gelin size boşanma bedellerinizi vereyim de sizi güzellikle serbest bırakayım.”"},{"n":29,"t":"“Yok eğer, Allah`ı, Peygamberini ve âhiret yurdunu istiyorsanız, biliniz ki Allah, içinizden güzel davrananlar için büyük bir ödül hazırlamıştır.”"},{"n":30,"t":"Ey Peygamber hanımları! Sizden kim açık/kanıtlanmış bir edepsizlik yaparsa, onun azabı iki katına çıkarılır. Bu, Allah için kolaydır."},{"n":31,"t":"Sizden kim de, Allah ve Rasûl`üne itaat eder ve yararlı iş yaparsa, ona ödülünü iki kat veririz. Ona bol rızık hazırlamışızdır."},{"n":32,"t":"Ey Peygamber hanımları! Siz, kadınlardan herhangi biri gibi değilsiniz. Eğer kötülükten korunursanız, yabancı erkeklere karşı çekici bir eda ile konuşmayınız; sonra kalbinde hastalık bulunan kimse ümide kapılır. Örfe uygun söz söyleyiniz."},{"n":33,"t":"Evlerinizde oturunuz, eski Câhiliye adetinde olduğu gibi açılıp saçılmayınız. Namazı kılınız, zekâtı veriniz; Allah`a ve Peygamberine itaat ediniz. Ey Ehli beyt! Allah, sizden sadece günahı gidermek ve sizi tertemiz yapmak istiyor."},{"n":34,"t":"Evlerinizde okunan Allah`ın âyetlerini ve hikmeti hatırlayınız. Şüphesiz ki Allah, her şeyin içyüzünü bilendir ve her şeyden haberi olandır."},{"n":35,"t":"Müslüman kadınlar ve Müslüman erkekler; mümin erkekler ve mümin kadınlar; itaat eden erkekler, itaat eden kadınlar; özü-sözü doğru erkekler, özü-sözü doğru kadınlar; sadaka veren erkekler, sadaka veren kadınlar; oruç tutan erkekler, oruç tutan kadınlar; ırzlarını koruyan erkekler, ırzlarını koruyan kadınlar; Allah`ı çok anan erkekler, Allah`ı çok anan kadınlar var ya; işte Allah bunlar için bir af ve büyük bir ödül hazırlamıştır."},{"n":36,"t":"Allah ve Peygamberi bir işi emrettiğinde, hiçbir inanmış erkek ve kadının o işte tercih hakkı yoktur. Kim, Allah`ın ve Peygamberinin emrine aykırı hareket ederse, kesinlikle apaçık bir sapıklığa düşmüş olur."},{"n":37,"t":"Allah`ın kendisine nimet verdiği ve senin de kendisine yardım etiğin kişiye, “Eşinden ayrılma, Allah`a saygı duy” dediğin anı hatırla! Oysa sen, içinde Allah`ın açığa çıkaracağı bir şeyi gizliyor ve insanlardan çekiniyordun. Halbuki Allah, çekinmeye daha lâyıktır. Müminlere, evlatlıkları eşlerinden ayrıldıklarında onların boşanmış eşleriyle evlenmelerinde bir sıkıntı olmaması için Zeyd, eşinden ilgisini tamamen kesip ayrılınca onu sana nikâhladık. Allah`ın emri kesinleşmiştir."},{"n":38,"t":"Allah`ın emrettiği bir şeyde peygamberine hiçbir sıkıntı yoktur. Bu, Allah`ın daha önce gelip geçmişlere uyguladığı bir yasasıdır. Allah`ın emri, mutlaka yerini bulur."},{"n":39,"t":"Peygamberler, Allah`ın mesajlarını tebliğ ederler. Allah`tan korkarlar ve O`ndan başka kimseden korkmazlar. Hesap görücü olarak Allah yeter."},{"n":40,"t":"Muhammed, sizin erkeklerinizden hiçbirinin babası değildir. Fakat Muhammed, Allah`ın peygamberi ve peygamberlerin sonuncusudur. Allah her şeyi bilmektedir."},{"n":41,"t":"Ey inananlar! Allah`ı çok anınız!"},{"n":42,"t":"O`nu sabah-akşam tesbih ediniz!"},{"n":43,"t":"Allah ve melekleri, sizleri karanlıklardan aydınlığa çıkarmak için, sizi iyiliklerle kuşatırlar. O, inananlara son derece merhametlidir."},{"n":44,"t":"İnananlar O`nun huzuruna kavuştukları gün Allah`ın onlara iltifatı, “Selâm/esenlik”tir. Allah onlara çok değerli ödül hazırlamıştır."},{"n":45,"t":"Ey Peygamber! Biz seni bir şâhit, müjdeleyici ve uyarıcı olarak gönderdik."},{"n":46,"t":"Allah`ın izni ile Allah`a çağıran bir davetçi ve aydınlatan bir kandil olarak gönderdik."},{"n":47,"t":"İnananlara kendileri için Allah katından büyük bir lütuf olacağını müjdele!"},{"n":48,"t":"Kâfirlere ve münâfıklara itaat etme! Onların eziyetlerine aldırma! Allah`a güven! Koruyucu olarak Allah yeter."},{"n":49,"t":"Ey iman edenler! Mümin kadınları nikâhlayıp sonra kendileriyle cinsel ilşkiye girmeden onları boşarsanız, artık onlar üzerinde sizin sayıp duracağınız bir iddet bekletme hakkınız yoktur. Onlara bir miktar yardımda bulununuz ve onları güzellikle serbest bırakınız!"},{"n":50,"t":"Ey Peygamber! Mehirlerini verdiğin eşlerini ve Allah`ın sana bahşettiği savaş esirleri arasından sağ elinin altında bulunanları sana helâl kıldık. Seninle beraber hicret eden amcanın, halanın, dayının ve teyzenin kızlarını da helâl kıldık. Eğer Peygamber kendisiyle evlenmek isterse, kendisini mehirsiz olarak peygambere bağışlayan herhangi bir mümin kadını da inananlara değil de sadece sana helâl kıldık. Sana bir sıkıntı olmaması için, biz, eşleri ve câriyeleri hakkında onlara neyi farz kıldığımızı kesinlikle biliyoruz. Allah çok bağışlayıcıdır; çok merhametlidir."},{"n":51,"t":"Hanımlarından dilediğinin yanında kalma sırasını erteler, dilediğini de öne alabilirsin. Sırasını ertelediklerinden arzuladıkların olursa onlara dönmende sana bir sakınca yoktur. Böyle yapman onları mutlu etmen, üzülmemelerini sağlaman, kendilerine verdiklerinle hepsinin razı olması için daha uygundur. Allah, sizin kalplerinizde olanı bilir ve son derece yumuşak davranır."},{"n":52,"t":"Artık bundan sonra başka kadınlarla evlenmek sana helâl değildir. Güzellikleri seni büyülese bile, eşlerinden birini boşayıp başkasıyla evlenmen de yasaklanmıştır. Ama câriye hariç. Allah her şeyi gözetlemektedir."},{"n":53,"t":"Ey iman edenler! Siz, zamanını gözetmeksizin, bir yemeğe davet edilmedikçe Peygamber`in evlerine girmeyiniz. Ancak davet edildiğiniz vakit giriniz. Yemeği yediğinizde hemen dağılınız, sohbete dalmayınız. Çünkü bu hareketiniz Peygamber`i üzmekte, fakat o, bunu size söylemekten utanmaktadır. Ama Allah, hakkı söylemekten çekinmez. Peygamber`in hanımlarından bir şey istediğiniz zaman, perde arkasından isteyiniz. Bu, hem sizin kalpleriniz, hem de onların kalpleri için daha temiz bir davranıştır. Sizin, Allah`ın peygamberini üzmeniz ve kendisinden sonra onun hanımlarını nikâhlamanız asla caiz olmaz. Çünkü bu, Allah katında büyük bir günahtır."},{"n":54,"t":"Bir şeyi açığa vursanız da, gizleseniz de, şüphe yok ki Allah, her şeyi gayet iyi bilmektedir."},{"n":55,"t":"Onlara babaları, oğulları, kardeşleri, kardeşlerinin oğulları, kız kardeşlerinin oğulları, mümin kadınları ve ellerinin altında bulunan câriyelerinden dolayı bir günah yoktur. Allah`tan sakınınız; şüphesiz Allah her şeye şâhittir."},{"n":56,"t":"Allah ve melekleri peygambere destek oluyorlar. Ey iman edenler! Siz de peygambere destek olunuz, ona yürekten bağlılığınızı ifade ediniz."},{"n":57,"t":"Şüphesiz, Allah`ı ve Peygamberini incitenlere Allah, dünya ve âhirette lanet eder ve onlara alçaltıcı bir azap hazırlar."},{"n":58,"t":"İnanan erkek ve kadınları, yapmadıkları bir şeyden dolayı incitenler, şüphesiz iğrenç bir iftira ve günah yüklenmiş olurlar."},{"n":59,"t":"Ey Peygamber! Hanımlarına, kızlarına ve inananların hanımlarına, dışarıya çıkarken “üstlerine örtü almalarını” söyle. Bu, onların tanınmasını ve incitilmemesini sağlayan en uygun yoldur. Allah çok bağışlayıcıdır; merhamet sahibidir."},{"n":60,"t":"İşte böyle, eğer ikiyüzlüler, kalplerinde hastalık olanlar ve yalan haberler yayarak (Peygamber`in) kent(in)de huzursuzluk çıkaranlar (düşmanca hareketlerinden) vazgeçmezlerse (ey Muhammed,) onlar üzerinde üstünlük kurmanı sağlarız, o zaman bu (kentte) sana çok az bir süre komşu kalacaklardır:"},{"n":61,"t":"Nerede bulunurlarsa, lanetlenmiş olarak yakalanır ve öldürülürler."},{"n":62,"t":"Allah`ın geçmiştekilere uyguladığı yasası budur ve Allah`ın yasasında bir değişme bulamazsın."},{"n":63,"t":"“Onun bilgisi Allah katındadır. Nereden bileceksin, belki de zamanı çok yakındır.”"},{"n":64,"t":"Allah, kâfirleri lanetlemiş ve onlar için alevli bir ateş hazırlamıştır."},{"n":65,"t":"Onlar, orada süreli olarak kalacaklardır. Ne bir dost ne de bir yardımcı bulacaklardır."},{"n":66,"t":"Yüzleri ateşe çevirildiği gün, “Eyvah bize! Keşke Allah`a ve Peygamberine itaat etseydik” diyeceklerdir."},{"n":67,"t":"“Ey Rabbimiz! Biz önderlerimize ve büyüklerimize itaat ettik de, bizi yoldan çıkardılar.”"},{"n":68,"t":"“Ey Rabbimiz! Onlara iki kat azap ver ve onları şiddetli bir şekilde lanetle!”"},{"n":69,"t":"Ey iman edenler! Siz de Mûsâ`ya eziyet edenler gibi olmayın! Nihayet Allah, onu, dedikleri şeyden temize çıkardı. Mûsâ, Allah katında şerefli idi."},{"n":70,"t":"Ey iman edenler! Allah`a saygı gösterin ve doğru söz söyleyin!"},{"n":71,"t":"Böyle yaparsanız, Allah, işlerinizi düzeltir ve günahlarınızı bağışlar. Kim, Allah`a ve Peygamber`ine itaat ederse büyük bir kurtuluşa ermiş olur."},{"n":72,"t":"Biz emaneti göklere, yere ve dağlara teklif ettik de onlar bunu yüklenmekten çekindiler, sorumluluğundan korktular. Onu insan yüklendi. Doğrusu o çok zâlimdir; çok câhildir."},{"n":73,"t":"Allah, münâfık erkeklere ve münâfık kadınlara, müşrik erkeklere ve müşrik kadınlara azap edecek; inanan erkeklerin ve inanan kadınların da tövbesini kabul buyuracaktır. Allah affedendir; merhamet edendir."}],[{"n":1,"t":"Bütün övgüler, göklerde ve yerde bulunan her şeyin sahibi olan Allah`adır. Âhirette de bütün övgüler O`na olacaktır. O`nun her işinde hikmet vardır ve O, her şeyden haberdardır."},{"n":2,"t":"Yerin içine gireni ve oradan çıkanı, gökten ineni ve oraya yükselen her şeyi bilir. O, çok merhametlidir; çok affedendir."},{"n":3,"t":"“Hayır! Gaybı bilen Rabbim hakkı için, kıyamet mutlaka size gelecektir. Göklerde ve yerde zerre ölçüsünde bir şey O`ndan gizli kalamaz. Bundan daha küçük ve daha büyüğü de şüphesiz apaçık bir kitaptadır.”"},{"n":4,"t":"Allah, inanıp iyi işler yapanları ödüllendirmek için her şeyi bir kitapta toplamıştır. Onlar için bir af ve güzel bir rızık vardır."},{"n":5,"t":"Âyetlerimizi hükümsüz kılmak için gayret edenler, işte bunlar için de en kötüsünden elem verici bir azap vardır."},{"n":6,"t":"Kendilerine ilim verilenler, Rabbinden sana indirilenin gerçek olduğunu, mutlak galip ve övgüye lâyık olan Allah`ın yoluna ilettiğini görürler."},{"n":7,"t":"“Çürüyüp paramparça olduğunuz vakit yeniden dirileceğinizi söyleyerek haber veren kişiyi gösterelim mi?”"},{"n":8,"t":"“Allah hakkında yalan mı uyduruyor, yoksa aklını mı yitirmiş bu?” dediler. Bilakis, âhirete inanmayanlar azaptadırlar ve derin bir sapıklık içindedirler."},{"n":9,"t":"Onlar, gökten ve yerden önlerinde ve arkalarında bulunana bakmıyorlar mı? Dilesek onları yere batırırız, ya da üzerlerine gökten parçalar indiririz. Şüphesiz bunda Rabbine yönelen her kul için bir ders vardır."},{"n":10,"t":"“Ey dağlar ve kuşlar, onunla birlikte Allah`ı teşbihe/anmaya katılını!” dedik. Demiri onun için yumuşattık."},{"n":11,"t":"“Geniş zırhlar imal et, dokumasını ölçülü yap! Ey Dâvûd hanedanı, iyi işler yapınız. Şüphesiz ben yaptıklarınızı görmekteyim” dedik."},{"n":12,"t":"Sabah esintisi bir aylık mesafe, akşam esintisi de bir aylık mesafe olan rüzgârı da Süleyman`ın emrine verdik. Onun için erimiş bakırı kaynağından sel gibi akıttık. Rabbinin izniyle cinlerin de bir kısmı onun emrinde çalışırdı. Cinlerden bizim emrimizden çıkanlara, alevli ateşin azabını tattırırız."},{"n":13,"t":"Cinler Süleyman`a, istediği gösterişli yapılar, heykeller, havuz gibi büyük kazanlar ve ağır tencereler yaparlardı. “Ey Dâvûd ailesi, şükretmek için çalışınız.” Kullarımdan gereği gibi şükredenler azdır."},{"n":14,"t":"Süleyman`ın ölümüne hükmedince, cinlere onun ölümünü ancak değneğini yiyen ağaç kurdu gösterdi. Süleyman yıkılınca anlaşıldı ki, eğer cinler gaybı bilselerdi, o alçaltıcı/ağır işte çalışmayı sürdürmezlerdi."},{"n":15,"t":"Sebe`lilerin yurtlarında Allah`ın kudretine bir işaret vardır. Sağlı sollu iki bahçe vardı. Onlara, “Rabbinizin verdiği rızıktan yiyiniz ve O`na şükrediniz” denildi. Ne güzel bir ülke ve ne güzel affedici bir Rabb!"},{"n":16,"t":"Buna rağmen onlar yüz çevirdiler. Biz de onların üzerlerine barajları yıkan o seli gönderdik. Onların bahçelerini acı yemişli, meyvesiz ve içinde birkaç sedir ağacı bulunan iki verimsiz bahçeye dönüştürdük."},{"n":17,"t":"Bu cezayı, onlara inkârlarından dolayı verdik. Biz, nankörlerden başkasını cezalandırmayız."},{"n":18,"t":"Onların yurdu ile mübarek kıldığımız şehirler arasında, birbirinden görünen beldeler yerleştirdik. Aralarında gidip gelmeyi kolaylaştırdık. “Güven içerisinde oralarda gece ve gündüz gidip geliniz” dedik."},{"n":19,"t":"Onlar, “Ey Rabbimiz! Bizim yolculuk mesafelerimizi uzat!” dediler ve kendilerine yazık ettiler. Biz de onları dillerde dolaşır sözler haline getirdik. Onları tamamen darmadağın ettik. Şüphesiz bunlarda, çok sabreden ve çok şükreden herkes için dersler vardır."},{"n":20,"t":"Andolsun İblis, onlar hakkındaki tahminini doğruya çıkardı. İnanan bir grubun dışında hepsi ona uydular."},{"n":21,"t":"Oysa şeytanın onlara karşı hiçbir gücü yoktu. Ancak âhirete inananlarla, ondan şüphe içerisinde olanları böylece biz biliriz. Rabbin her şeyi gözetip koruyandır."},{"n":22,"t":"“Allah`tan başka tanrı olduklarını iddia ettiğiniz şeylere yalvarıp durunuz. Onlar göklerde ve yerde zerre ağırlığında bir şeye sahip değillerdir. Onların göklerde ve yerde hiçbir ortaklıkları yoktur. Allah`ın onlardan bir yardımcısı da yoktur.”"},{"n":23,"t":"Allah`ın huzurunda, kendisinin izin verdiği kimselerden başkasının şefaati fayda vermez. Nihayet onların kalplerinden korku giderilince, “Rabbiniz ne buyurdu?” derler. “Hakkı buyurdu” dediler. Allah, yücedir; büyüktür."},{"n":24,"t":"“Allah.” “Öyleyse ya biz ya siz, bir doğruluk veya apaçık bir yanlışlık üzerindeyiz.”"},{"n":25,"t":"“Bizim işlediğimizden siz sorumlu değilsiniz, biz de sizin işlediğinizden sorulmayız.”"},{"n":26,"t":"“Rabbimiz bizi bir araya getirecek, sonra aramızda adaletle hüküm verecektir. O, adaletle hüküm veren ve her şeyi bilendir.”"},{"n":27,"t":"“Allah`a ortak kabul ettiklerinizi bana gösteriniz.” Hayır! Doğrusu galip ve her şeyi hikmetle idare eden ancak Allah`tır."},{"n":28,"t":"Biz, seni bütün insanlara sadece müjdeleyici ve uyarıcı olarak gönderdik. Fakat insanların çoğu bunu bilmezler."},{"n":29,"t":"“Eğer doğru söylüyorsanız, bu vaad ettiğiniz kıyamet ne zaman kopacak?”"},{"n":30,"t":"“Sizin için belirlenmiş bir gün vardır. Onu ne bir saat geciktirebilirsiniz, ne de öne alabilirsiniz."},{"n":31,"t":"“Sizler olmasaydınız, biz kesinlikle inananlardan olurduk” diyecekler."},{"n":32,"t":"Büyüklük taslayanlar, güçsüz durumda olanlara, “Size, doğru geldikten sonra sizi biz mi ondan çevirdik? Tam tersine, siz suç işliyordunuz” diye cevap verecekler."},{"n":33,"t":"Güçsüz durumda olanlar, büyüklük taslayanlara, “Hayır! Sizin gece gündüz tuzak kurmanız bizi bu hale düşürdü. Çünkü bize, Allah`ı inkâr etmemizi, O`na ortaklar koşmamızı emrediyordunuz” diyecekler ve azabı gördüklerinde, pişmanlıklarını içlerinde gizleyecekler. Biz de inkâr edenlerin boyunlarına halkalar geçireceğiz. Onlar sadece yaptıklarının karşılığını görecekler."},{"n":34,"t":"Biz, herhangi bir ülkeye bir uyarıcı gönderdiğimizde mutlaka oranın varlıklı ve şımarık kişileri, “Biz, size gönderilmiş şeyi inkâr ediyoruz” demişlerdir."},{"n":35,"t":"“Servet ve soy sop olarak biz, sizden daha güçlüyüz ve bu gücümüzden dolayı da, azaba uğratılmayacağız!”"},{"n":36,"t":"“Şüphesiz ki Rabbim, rızkı dilediğine bolca da verir, kısar da. Fakat, insanların çoğu bunu bilmezler.”"},{"n":37,"t":"Sizi, huzurumuza ne mallarınız ne de çocuklarınız yaklaştıracaktır. İman edip iyi amelde bulunanlar müstesnadır. İşte onlar için yaptıklarından dolayı kat kat ödül vardır. Onlar cennet odalarında güven içinde olacaklardır."},{"n":38,"t":"Âyetlerimizi geçersiz kılmaya gayret edenlere gelince, işte onlar da azaba atılacaklardır."},{"n":39,"t":"“Şüphesiz ki Rabbim, kullarından dilediğine rızkı bolca da verir, kısar da. Siz hayır için ne harcarsanız, Allah onun yerini doldurur. O, rızk verenlerin en hayırlısıdır.”"},{"n":40,"t":"Onların hepsini toplayacağı gün, Allah meleklere, “Bunlar mı size tapıyorlardı?” diye sorar."},{"n":41,"t":"Melekler, “Hâşâ! Seni tenzih ederiz. Sen bizim velimizsin, onlar değil. Tam aksine, onlar cinlere tapıyorlardı. Onların çoğu onlara inanıyorlardı” diyecekler."},{"n":42,"t":"O gün, bir kısmınız bir kısmınıza ne bir fayda sağlar ne de zarar verebilir. Biz, zâlimlere, “Tadın yalanlamakta olduğunuz azabı!” deriz."},{"n":43,"t":"Onlara apaçık âyetlerimiz okunduğu zaman, “Bu, sizi babalarınızın taptıklarından alıkoymak isteyen bir adamdan başkası değildir” dediler. “Bu, sırf uydurulmuş bir yalandır” dediler. İnkâr edenler, kendilerine gerçek geldiğinde, “Bu, apaçık bir büyüden başka bir şey değildir” dediler.”"},{"n":44,"t":"Oysa biz, onlara okuyacakları kitaplar vermemiştik. Senden önce de onlara herhangi bir uyarıcı göndermemiştik."},{"n":45,"t":"Onlardan öncekiler de yalanladılar. Oysa bunlar, onlara verdiklerimizin onda birine bile ulaşamamışlardır. Onlar da peygamberlerimizi yalanlamışlardı. Bak, beni inkârın sonu nasıl oldu?"},{"n":46,"t":"Allah için ikişer ikişer ve teker teker kalkınız. Sonra arkadaşınızda kesinlikle hiçbir deliliğin olmadığını iyice düşününüz. O sadece, sizi önünüzdeki şiddetli azaba karşı uyaran birisidir.”"},{"n":47,"t":"“Ben sizden bir karşılık istemiyorum; o, sizin olsun, benim karşılığım ancak Allah`a aittir. O her şeye tanıktır.”"},{"n":48,"t":"“Rabbim elbette gerçeği ortaya koyar. Çünkü O, gaybı en iyi bilendir.”"},{"n":49,"t":"“Hak geldi, bâtıl artık ne bir şeyi ortaya çıkarabilir, ne de geri getirebilir.”"},{"n":50,"t":"“Ben, bir yanlış yaparsam kendi aleyhime yapmış olurum. Eğer doğru bir iş yaparsam biliniz ki bu, Rabbimin bana vahyettiği Kur`ân sayesindedir. Şüphesiz ki O, işitendir; yakındır.”"},{"n":51,"t":"Onların korkuya kapılacakları, hiçbir kaçış yollarının olmayacağı ve yakın bir yerde yakalandıkları anı bir görseydin!"},{"n":52,"t":"Onlar o zaman, “Gerçeğe inandık” derler. Uzak bir yerden ona nasıl ulaşacaklar?"},{"n":53,"t":"Onlar, bu duruma düşmeden önce inkâr etmişler, bilmeden uzaktan taş atmışlardı."},{"n":54,"t":"Bundan önce de benzerlerine yapıldığı gibi, kendileri ile arzuladıkları iman arasına engel konulacak. Çünkü onlar, derin bir şüphe içindeydiler."}],[{"n":1,"t":"Övgü, gökleri ve yeri yoktan yaratan, melekleri ikişer, üçer ve dörder kanatlı elçiler kılan Allah`a aittir. O, yaratmada dilediği kadar arttırır. Çünkü Allah`ın her şeye gücü yeter."},{"n":2,"t":"Allah`ın insanlara verdiği rahmeti önleyebilecek yoktur. O`nun önlediğini de ardından salıverecek yoktur. O çok güçlüdür; bilgedir."},{"n":3,"t":"Ey insanlar! Allah`ın size olan nimetini hatırlayınız; size gökten ve yerden rızık veren Allah`tan başka bir yaratan mı var? O`ndan başka tanrı yoktur. Öyleyse nasıl döndürülüyorsunuz?"},{"n":4,"t":"Eğer seni yalanlıyorlarsa, senden önceki peygamberler de yalanlanmıştır. Bütün işler Allah`a döndürülecektir."},{"n":5,"t":"Ey İnsanlar! Şüphesiz Allah`ın sözü gerçektir. Bu dünya hayatı sizi aldatmasın. Şeytan da sizi Allah ile aldatmasın!"},{"n":6,"t":"Çünkü şeytan, sizin düşmanınızdır; siz de onu düşman edininiz. O, kendi taraftarlarını ancak ateş ehlinden olmaya çağırır."},{"n":7,"t":"İnkâr edenler için elbette çetin bir azap vardır. İman edip iyi işler yapanlara da af ve büyük bir ödül vardır."},{"n":8,"t":"Kötü işleri kendisine güzel gösterilip, kendisi de onları güzel gören kişi, gerçeği gören gibi midir? Şüphesiz ki Allah dileyeni saptırır, dileyeni de doğru yola iletir. Artık onlara üzülerek kendini mahvetme! Çünkü Allah onların yaptıklarını çok iyi bilmektedir."},{"n":9,"t":"Bulutları sürükleyen rüzgârların estiricisi Allah`dır. Biz bulutları ölü bir yöreye göndererek onlar aracılığı ile ölü toprağı diriltiriz. İşte yeniden diriliş olayı da böyledir."},{"n":10,"t":"Kim şeref istiyorsa, bilsin ki, şerefin tamamı Allah`ındır. Güzel söz Allah`a yükselir. İyi amel de güzel sözü yüceltir. Kötülükleri planlayanlara şiddetli bir azap vardır. Bunların planları boşa çıkacaktır."},{"n":11,"t":"Allah sizi topraktan, sonra embriyodan yarattı. Sonra sizi çiftler kıldı. O`nun bilgisi olmadan hiçbir dişi ne gebe kalır, ne de doğurur. Bir canlıya ömür verilmesi de, onun ömründen azaltılması da mutlaka bir kitaptadır. Şüphesiz bunlar, Allah`a kolaydır."},{"n":12,"t":"Şu tatlı, susuzluğu giderici ve içimi kolay, şu da tuzlu ve acıdır. Hepsinden de taze et yer ve takınacağınız süs eşyaları çıkarırsınız. O`nun lütfundan (nasib) aramanız için ve olur ki şükredersiniz diye gemilerin onun içinde (suyu) yararak gittiklerini görürsün."},{"n":13,"t":"Allah, geceyi gündüze katar, gündüzü de geceye katar. Güneşi ve ayı insanların hizmetine sunmuştur. Her birisi, belirlenmiş bir süreye kadar yörüngesinde akar gider. İşte, Rabbiniz olan Allah budur. Mülk O`nundur. O`ndan başka taptıklarınız, bir çekirdek zarına bile sahip değillerdir."},{"n":14,"t":"Eğer Allah`tan başka taptıklarınızı çağırırsanız sizin çağırmanızı işitemezler; işitseler bile size cevap veremezler. Kıyamet günü de sizin ortak koşmanızı reddederler. Bu gerçeği sana, her şeyden haberi olan Allah gibi hiç kimse haber veremez."},{"n":15,"t":"Ey insanlar! Allah`a muhtaç olan sizsiniz, ama O hiç kimseye, hiçbir şeye muhtaç değildir ve O övülmeye çok layıktır."},{"n":16,"t":"Allah dilerse sizi yok eder ve yerinize yeni bir halk getirir."},{"n":17,"t":"Bu da Allah`a güç gelen bir şey değildir."},{"n":18,"t":"Hiçbir günahkâr başkasının günahını yüklenemez. Yükü ağır gelen kimse, onu taşımak için başkasını çağırsa, bu çağırdığı akrabası da olsa, onun yükünden bir şey yüklenemez. Sen ancak, görmeden Rabblerine saygı duyanları ve namazı kılanları uyarabilirsin. Kim temizlenirse o, kendi menfaatine temizlenmiş olur. Dönüş Allah`adır."},{"n":"19-22","t":"Görmeyen ile gören, karanlık ile aydınlık, gölge ile sıcak bir olmaz. Diriler ile ölüler de bir olmaz. Şüphesiz ki Allah dileyene işittirir. Sen kabirdekilere işittiremezsin."},{"n":"23-24","t":"Sen, sadece bir uyarıcısın. Biz seni müjdeleyici ve uyarıcı olarak hak ile gönderdik. Her millet için mutlaka bir uyarıcı olmuştur."},{"n":25,"t":"Eğer seni yalanlıyorlarsa, onlardan öncekiler de yalanlamışlardı. Oysa ki peygamberleri onlara açık âyetler, sahifeler ve aydınlatıcı kitap getirmişlerdi."},{"n":26,"t":"Sonra ben, o inkâr edenleri yakaladım. Bak, cezam nasıl oldu!"},{"n":27,"t":"Allah`ın gökten yağmur yağdırdığını görmedin mi? Biz, onunla renkleri farklı farklı meyveler çıkardık. Dağlarda değişik renklerde beyaz, kırmızı ve simsiyah yollar vardır."},{"n":28,"t":"Aynı şekilde, insanlardan, diğer canlılardan ve evcil hayvanlardan da renkleri farklı olanlar vardır. Allah`a ancak bilgili kulları saygı duyar. Şüphesiz ki Allah çok güçlüdür; çok bağışlayıcıdır."},{"n":29,"t":"Allah`ın kitabını okuyanlar, namazı kılanlar ve kendilerine verdiğimiz rızıktan hayır için gizli ve açık harcayanlar, asla zarar etmeyecek bir ticaret umarlar."},{"n":30,"t":"Çünkü Allah, onların ödülünü tam öder ve lütfundan onlara fazlasını da verir. Şüphesiz ki Allah, çok bağışlayandır; şükrün karşılığını bol bol verendir."},{"n":31,"t":"Sana vahyettiğimiz kitap, kendinden öncekini doğrulayıcı olarak gelen gerçektir. Allah, kullarının ihtiyaçlarından haberdardır; her şeyi görendir."},{"n":32,"t":"Sonra bu kitabı kullarımızdan seçtiklerimize miras bıraktık. Onlardan bazısı kendilerine haksızlık ettiler. Bazıları orta yolu tuttular. Kimileri de hayır işlerinde Allah`ın izniyle öne geçtiler. İşte bu en büyük fazilettir."},{"n":33,"t":"Onlar, ‘Adn cennetlerine girecekler. Orada altın bilezikler ve inciler takınacaklardır. Oradaki elbiseleri de ipekten olacaktır."},{"n":34,"t":"“Bizden üzüntüyü gideren Allah`a hamdolsun! Doğrusu Rabbimiz, kesinlikle çok bağışlayandır; iyiliklerin karşılığını fazlasıyla verendir.”"},{"n":35,"t":"“Yine O, bizi kendi lütfuyla, süreli nimet yurduna indirdi. Orada bize ne bir yorgunluk, ne de bitkinlik gelecektir.”"},{"n":36,"t":"İnkâr edenlere de cehennem ateşi vardır. Öldürülmezler ki ölsünler; cehennem azabı da onlara biraz olsun hafifletilmez. İşte biz, bütün inkârcıları böyle cezalandırırız."},{"n":37,"t":"Onlar orada, “Ey Rabbimiz! Bizi çıkar. Daha önce yaptıklarımızın aksine iyi işler yapalım” diye feryat ederler. Kendilerine, “Size, düşünecek kimsenin düşünebileceği kadar bir ömür vermedik mi? Size uyarıcı da gelmedi mi? Şimdi tadın azabı! Zâlimlerin yardımcısı yoktur” denir."},{"n":38,"t":"Allah, göklerin ve yerin gaybını/insanların bilemeyeceği şeyleri bilir. O, kalplerin içinde ne varsa onu da hakkı ile bilendir."},{"n":39,"t":"Sizi yeryüzünde iktidar sahibi yapan O`dur. O halde, kim inkâr ederse, inkârı kendi zararınadır. Kâfirlerin küfrü, Rabbleri katında kendileri için ancak gazabı arttırır. Kâfirlerin inkârı, kendilerine ziyandan başka bir şey getirmez."},{"n":40,"t":"“Allah`tan başka yalvardığınız ortaklarınızı hiç düşündünüz mü? Gösteriniz bana! Onlar yerdeki hangi şeyi yarattılar! Yoksa onların göklerde mi bir ortakları var! Yoksa biz onlara bir kitap mı verdik de onlar, o kitaptaki bir delile dayanıyorlar?” Hayır! O zâlimler/müşrikler, birbirlerine aldatmadan başka bir şey vaad etmiyorlar."},{"n":41,"t":"Şüphesiz Allah, yörüngelerinden sapmamaları için gökleri ve yeri tutar. Eğer onlar sapacak olsalar O`ndan başka onları hiç kimse tutamaz. Şüphesiz O, son derece yumuşak davranır; affeder."},{"n":42,"t":"Eğer kendilerine bir uyarıcı gelirse bütün toplumların en doğruları olacaklarına dair bütün güçleriyle Allah`a yemin ettiler. Ancak kendilerine bir uyarıcı gelince, bu, onların sadece haktan kaçmalarını arttırdı."},{"n":43,"t":"Çünkü onlar yeryüzünde kibirlendiler ve kötü tuzaklar kurdular. Halbuki kişi, kazdığı kuyuya kendi düşer. Onlar öncekilere uygulanan yasayı mı bekliyorlar? Allah`ın yasasında asla bir değişme bulamazsın. Allah`ın yasasında bir başkalaşma da bulamazsın."},{"n":44,"t":"Kendilerinden öncekilerin sonlarının nasıl olduğunu görmek için yeryüzünde gezip dolaşmadılar mı? Onlar, kendilerinden daha güçlü idiler. Göklerde ve yerde Allah`ı âciz bırakacak hiçbir şey yoktur. Şüphesiz O, her şeyi bilir; her şeye gücü yeter."},{"n":45,"t":"Şâyet Allah, insanları yaptıklarıyla hemen cezalandırsaydı, yeryüzünde hiçbir canlı bırakmazdı. Fakat onları belirlenen bir vakte kadar ertelemektedir. Vakitleri gelince Allah, onları cezalandıracaktır. Çünkü Allah kullarını kesinlikle gözlemektedir."}],[{"n":1,"t":"Yâ, sîn."},{"n":2,"t":"Hikmetlerle dolu Kur`ân`a yemin olsun."},{"n":3,"t":"Kesinlikle sen gönderilmiş peygamberlerdensin."},{"n":4,"t":"Dosdoğru bir yol üzerindesin."},{"n":5,"t":"Bu Kur`ân, güçlü ve merhamet sahibi Allah tarafından indirilmiştir."},{"n":6,"t":"Ataları uyarılmamış, bu yüzden kendileri de gaflet içinde kalmış bir toplumu uyarman için indirilmiştir/Ataları uyarıldıkları halde gaflet içinde olan bir toplumu uyarman için indirilmiştir."},{"n":7,"t":"Andolsun ki, onların çoğu gafletlerinin cezasını hak etmişlerdir. Çünkü onlar iman etmiyorlar."},{"n":8,"t":"Biz, onların boyunlarına, çenelerine kadar dayanacak olan demir halkalar geçirdik. Bu yüzden başları yukarı kalkıktır."},{"n":9,"t":"Önlerinden bir set ve arkalarından bir set çektik de onları çepeçevre kuşattık. Artık göremezler."},{"n":10,"t":"Onları uyarsan da uyarmasan da birdir, inanmazlar."},{"n":11,"t":"Sen ancak, Kur`ân`a uyan ve görmeden Rahmân`a saygı duyan kimseyi uyarabilirsin. İşte böylesini bir af ve güzel bir ödülle müjdele."},{"n":12,"t":"Şüphesiz ölüleri ancak biz diriltiriz. Onların yaptıkları her işi ve bıraktıkları her eseri yazarız. Biz, her şeyi apaçık bir kitapta kaydederiz."},{"n":13,"t":"Onlara o ülke halkını örnek ver. Hani, oraya peygamberler gelmişti."},{"n":14,"t":"“Biz, size gönderilen peygamberleriz.”"},{"n":15,"t":"“Siz, bizim gibi birer insandan başka şey değilsiniz. Rahmân hiçbir şey indirmemiştir. Siz sadece yalan söylüyorsunuz!”"},{"n":16,"t":"“Rabbimiz biliyor ki, biz size gönderilmiş peygamberleriz.”"},{"n":17,"t":"“Bize düşen, açık bir tebliğden başka bir şey değildir.”"},{"n":18,"t":"“Sizin yüzünüzden uğursuzlukla karşılaştık, biz sizi uğursuzluk sebebi saymaktayız. Eğer bu işe son vermezseniz, sizi mutlaka taşlayacağız. Bizden size acıklı bir azap kesinlikle dokunacaktır.”"},{"n":19,"t":"“Uğursuzluk şüphesiz sizinle beraberdir. Size öğüt verildi diye mi bütün bunlar? Hayır, siz savurganlığa ve aşırılığa sapmış bir topluluksunuz.”"},{"n":20,"t":"“Ey topluluk, bu peygamberlere uyunuz!”"},{"n":21,"t":"“Sizden herhangi bir ücret istemeyenlere uyunuz! Onlar doğruyu ve güzeli bulanlardır.”"},{"n":22,"t":"“Beni yokken yaratana ne diye kulluk etmeyecek mişim ben? Sizler de O`na döndürüleceksiniz.”"},{"n":23,"t":"“O`ndan başka tanrılar mı edineyim ben? Eğer Rahmân bana bir zorluk dilerse, onların şefaati/yardımı benden hiçbir şeyi savamaz; beni kurtaramazlar.”"},{"n":24,"t":"“Bu durumda ben elbette ki açık bir sapıklığın içine düşerim.”"},{"n":25,"t":"“Ben sizin Rabbinize iman ettim, artık beni dinleyiniz!”"},{"n":26,"t":"“Âh, keşke kavmim, Rabbim`in beni affedip ikram edilenlerden kıldığını bir bilebilseydi!”"},{"n":27,"t":"“Âh, keşke kavmim, Rabbim`in beni affedip ikram edilenlerden kıldığını bir bilebilseydi!”"},{"n":28,"t":"Biz onun ardından kavmi üzerine gökten bir ordu indirmedik, indirecek de değildik."},{"n":29,"t":"Olan, sadece korkunç titreşimli bir sesti. Bir anda sönüverdiler."},{"n":30,"t":"Yazık şu kullara! Kendilerine gelen her peygamberle mutlaka alay ederlerdi."},{"n":31,"t":"Görmediler mi, kendilerinden önce nice nesilleri helâk ettik. Onlar artık bir daha bunlara dönmeyecekler."},{"n":32,"t":"Ancak, onların hepsi huzurumuzda hazır bulundurulacaklardır."},{"n":33,"t":"Ölü toprak, onlar için bir delildir. Biz, ona can veririz ve ondan başak çıkartırız da onlar ondan yerler."},{"n":"34-35","t":"Orada hurma ve üzüm bağları meydana getirdik ve pınarlar akıttık ki meyvelerinden ve ürettiklerinden yesinler. Hiç şükretmezler mi?"},{"n":36,"t":"Bitkilerden, kendilerinden ve daha henüz bilmedikleri nice şeylerden bütün çiftleri yaratan Allah, her türlü eksiklikten uzaktır."},{"n":37,"t":"Gece de onlar için bir delildir. Gündüzü ondan soyup alırız, birden onlar karanlıkta kalıverirler."},{"n":38,"t":"Kendi yörüngesinde seyreden güneş de bir delildir. Bu, her şeye gücü yeten ve her şeyi bilen Allah`ın takdiridir."},{"n":39,"t":"Aya da safhalar belirledik; sonunda kuru bir hurma dalı gibi olur."},{"n":40,"t":"Ne güneş aya ulaşabilir, ne de gece gündüzün önüne geçebilir. Her biri kendi yörüngesinde hareket eder."},{"n":41,"t":"Onların soylarını dolu gemide taşımamız da kendileri için bir ayettir."},{"n":42,"t":"Onun gibi bindikleri binekler yaratmamız da bir delildir."},{"n":43,"t":"Dilersek onları suda boğarız. Hiçbir kimse de onlara yardım edemez ve kurtarılamazlar da."},{"n":44,"t":"Ancak katımızdan bir rahmet olarak boğmuyor ve belli bir süreye kadar onları yaşatıyoruz."},{"n":45,"t":"Onlara, “Önünüzdekinden/ahiret azabından ve arkanızdakinden/dünyanın aldatıcılığından sakınınız ki, size merhamet edilebilsin” denildiğinde hiç aldırmazlar."},{"n":46,"t":"Çünkü Rabblerinin âyetlerinden kendilerine bir âyet gelince, ondan mutlaka yüz çevirmişlerdir."},{"n":47,"t":"“Allah`ın dilediği taktirde doyuracağı kimseleri biz mi doyuracağız? Siz gerçekten apaçık bir sapıklık içindesiniz.”"},{"n":48,"t":"Onlar, “Eğer gerçekten doğru söylüyorsanız, bu vaad ettiğiniz kıyamet ne zaman kopacaktır?” derler."},{"n":49,"t":"Onlar, birbirleriyle çekişip dururken kendilerini ansızın yakalayacak bir sesten başka bir şey beklemiyorlar."},{"n":50,"t":"İşte o anda ne vasiyet edebilirler, ne de ailelerine dönebilirler."},{"n":51,"t":"Sûr`a üfürülünce bir de bakarsın ki onlar bulundukları yerden kalkıp, koşarak Rabblerine giderler."},{"n":52,"t":"İşte o zaman, “Vah bize, kim bizi bulunduğumuz yerden kaldırdı? Rahmân`ın vaad ettiği buymuş. Peygamberler doğru söylemiş” derler."},{"n":53,"t":"Olan, müthiş bir sesten ibarettir. Bunun üzerine onların hepsi hemen huzurumuzda hazır bulunurlar."},{"n":54,"t":"İşte o gün hiçbir kimseye herhangi bir haksızlık yapılmayacaktır. Siz ancak yaptıklarınızın karşılığını göreceksiniz."},{"n":55,"t":"O gün cennetlikler, gerçekten nimetler içinde sefa sürerler."},{"n":56,"t":"Onlar ve eşleri, gölgeler altında koltuklara yaslanacaklardır."},{"n":57,"t":"Orada onlar için her çeşit meyve vardır. Bütün istekleri yerine getirilir."},{"n":58,"t":"Onlara, merhametli Rabbin söylediği selâm vardır."},{"n":59,"t":"“Ey günahkârlar! Bugün şöyle ayrılın!”"},{"n":60,"t":"“Ey Âdemoğulları! ‘Size şeytana tapmayınız; çünkü o sizin apaçık bir düşmanınızdır` demedim mi?”"},{"n":61,"t":"“Bana kulluk ediniz, doğru yol budur, demedim mi?”"},{"n":62,"t":"Yemin olsun, şeytan içinizden birçok nesli saptırmıştı. Hâlâ aklınızı kullanmayacak mısınız?"},{"n":63,"t":"“İşte, bu size vaad edilen cehennemdir.”"},{"n":64,"t":"“İnkârınız sebebiyle bugün oraya giriniz.”"},{"n":65,"t":"O gün onların ağızlarını mühürleriz; yaptıklarını bize elleri anlatır, ayakları da şahitlik eder."},{"n":66,"t":"Dileseydik, onların gözlerini tamamen kör ederdik. O zaman yola koyulmak isterler, ama nasıl görecekler!"},{"n":67,"t":"Dileseydik, oldukları yerde onların şekillerini değiştirirdik de, ne ileriye gitmeye güçleri yeterdi; ne geri gelmeye!"},{"n":68,"t":"Kime uzun ömür verirsek biz, onun gelişmesini tersine çeviririz. Hiç akıllarını kullanmıyorlar mı?"},{"n":69,"t":"Biz peygambere şiir öğretmedik. Zaten ona yaraşmazdı da. O kitap, ancak Allah`tan gelmiş bir öğüt ve apaçık bir Kur`ân`dır."},{"n":70,"t":"Diri olanları uyarabilsin ve kâfirlere ceza hak olsun diye."},{"n":71,"t":"Kendi kudretimizle onlara evcil hayvanlar yarattığımızı, onların da bunlara sahip olduklarını görmezler mi?"},{"n":72,"t":"Bu hayvanları onların emrine verdik. Onların bir kısmını binek olarak kullanırlar, bir kısmını da gıda olarak yerler."},{"n":73,"t":"Bu hayvanlarda onlar için nice faydalar vardır ve içecekleri vardır. Hâlâ şükretmezler mi?"},{"n":74,"t":"Oysa onlar, kendilerine yardım etsinler diye Allah`tan başka tanrılar edinirler."},{"n":75,"t":"Tanrıları onlara yardım edemezler. Aksine onlar tanrılarının “hazır ol” vaziyetindeki askerleridir."},{"n":76,"t":"O halde, onların sözleri sakın seni üzmesin. Şüphesiz biz, onların gizlemekte olduklarını da, açığa vurduklarını da biliyoruz."},{"n":77,"t":"İnsan görmez mi ki, biz onu nutfeden/meni ve yumurtadan yarattık. Bir de bakıyorsun ki, apaçık düşman kesilmiş."},{"n":78,"t":"Kendi yaratılışını unutarak bize karşı misal getirmeye kalkışıyor ve “Şu çürümüş kemikleri kim diriltecek?” diyor."},{"n":79,"t":"“Onları ilk defa yaratmış olan diriltecek. Çünkü O, her türlü yaratmayı çok iyi bilir.”"},{"n":80,"t":"“Size, yemyeşil ağaçtan ateş çıkaran O`dur. Siz ondan ateş yakarsınız.”"},{"n":81,"t":"“Gökleri ve yeri yaratanın onların benzerini yaratmaya gücü yetmez mi? Evet yeter. Çünkü O, her şeyi yaratandır; her şeyi bilendir.”"},{"n":82,"t":"“O, bir şeyi yaratmak istediği zaman, O`nun işi, sadece o şeye ‘ol` demektir; o da hemen oluşmaya başlar.”"},{"n":83,"t":"“Her şeyin mülkiyeti elinde olan Allah, bütün noksanlıklardan uzaktır. Siz yalnız O`na döndürüleceksiniz.”"}],[{"n":"1-4","t":"Sıra sıra dizilenlere, toplayıp sürenlere, Kur`ân okuyanlara andolsun ki sizin tanrınız tektir."},{"n":5,"t":"O, göklerin, yerin ve ikisi arasındakilerin Rabbidir. Doğuş yerlerinin de Rabbidir."},{"n":6,"t":"Biz, o yakın göğü bir süsle, yıldızlarla süsleyip donattık."},{"n":7,"t":"O yakın göğü her türlü inatçı asi şeytandan koruduk."},{"n":8,"t":"Onlar ne kadar çırpınsalar da o yüce konseyi dinleyemezler ve her taraftan atışa tutulurlar."},{"n":9,"t":"Kovulurlar ve onlar için yakalarını bırakmayan bir azap vardır."},{"n":10,"t":"Yüce konseyden/topluluktan bir söz kapan olursa, onu da delice bir alev izler."},{"n":11,"t":"“Yaratılış bakımından kendileri mi daha zor, yoksa bizim yarattıklarımız mı?” Biz onları yapışkan bir çamurdan yarattık."},{"n":12,"t":"Sen hayran kaldın; onlarsa alay ediyorlar."},{"n":13,"t":"Kendilerine öğüt verilse, öğüt almıyorlar."},{"n":14,"t":"Bir âyet görseler, alay ediyorlar."},{"n":15,"t":"“Bu, apaçık büyüden başka bir şey değildir.”"},{"n":16,"t":"“Yani biz öldüğümüz, toprak ve kemik olduğumuz zaman mı diriltileceğiz?”"},{"n":17,"t":"“Önceki atalarımız da mı?”"},{"n":18,"t":"“Evet, siz hem de aşağılanarak diriltileceksiniz.”"},{"n":19,"t":"O iş, sadece korkunç bir sesten ibarettir. Hemen onlar, diriltilmiş olarak bakıyorlardır."},{"n":20,"t":"“Vah bize! Bu ceza günüdür” diyecekler."},{"n":21,"t":"“Bu, yalanlamakta olduğunuz hüküm günüdür.”"},{"n":22,"t":"“Zâlimleri, onların aynı yoldaki arkadaşlarını, Allah`tan başka taptıkları tanrılarını toplayınız. Onlara cehennemin yolunu gösteriniz. Onları tutuklayınız, çünkü onlar sorguya çekilecekler.”"},{"n":23,"t":"“Zâlimleri, onların aynı yoldaki arkadaşlarını, Allah`tan başka taptıkları tanrılarını toplayınız. Onlara cehennemin yolunu gösteriniz. Onları tutuklayınız, çünkü onlar sorguya çekilecekler.”"},{"n":24,"t":"“Zâlimleri, onların aynı yoldaki arkadaşlarını, Allah`tan başka taptıkları tanrılarını toplayınız. Onlara cehennemin yolunu gösteriniz. Onları tutuklayınız, çünkü onlar sorguya çekilecekler.”"},{"n":25,"t":"Size ne oldu ki, birbirinize yardım etmiyorsunuz?"},{"n":26,"t":"Hayır! Onlar o gün teslim olmuşlardır."},{"n":27,"t":"Dönüp birbirlerine soracaklar."},{"n":28,"t":"“Siz, bize sağdan geliyordunuz” diyecekler."},{"n":29,"t":"“Siz zaten inanmıyordunuz.”"},{"n":30,"t":"“Bizim sizi zorlayacak bir gücümüz yoktu. Siz kendiniz, azgın bir toplum olmuştunuz.”"},{"n":31,"t":"“Şimdi bize Rabbimizin azap sözü kesinleşti. Artık birlikte tadacağız.”"},{"n":32,"t":"“Sizi azdırdık, çünkü biz kendimiz azmıştık.”"},{"n":33,"t":"O gün onlar azap çekmede ortaktırlar."},{"n":34,"t":"İşte biz suçlulara böyle yaparız."},{"n":35,"t":"Çünkü onlara, “Allah`tan başka tanrı yoktur” denildiğinde büyüklük taslarlardı."},{"n":36,"t":"“Ne yani, cin çarpmış bir şair için tanrılarımızı terk mi edelim?”"},{"n":37,"t":"Hayır! O, gerçeği getirdi ve peygamberleri de doğruladı."},{"n":38,"t":"Şüphesiz siz acı azabı tadacaksınız."},{"n":39,"t":"Size, sadece yaptıklarınızın karşılığı verilecektir."},{"n":40,"t":"Ancak, Allah`ın hâlis kulları istisna edilecektir."},{"n":41,"t":"Bunlar için bilinen bir rızık vardır."},{"n":"42-44","t":"Türlü meyveler vardır. Onlar nimet cennetlerinde karşılıklı koltuklarda ağırlanacaklardır."},{"n":"45-46","t":"Aralarında bembeyaz, içenlerin lezzet aldığı kaynaklardan doldurulmuş kadehler dolaştırılacaktır."},{"n":47,"t":"O içecekte ne sersemletme vardır, ne de ondan dolayı sarhoş olurlar."},{"n":48,"t":"Yanlarında, gözlerini kendilerinden ayırmayan güzel gözlü eşleri olacaktır."},{"n":49,"t":"Onlar, gün yüzü görmemiş yumurta gibi bembeyazdır."},{"n":50,"t":"İşte o zaman, birbirlerine dönerek soracaklar."},{"n":51,"t":"İçlerinden biri, “Benim, bir arkadaşım vardı” der."},{"n":52,"t":"“Sen de, öldükten sonra dirilmeye inananlardan mısın?”"},{"n":53,"t":"“Biz ölüp kemik ve toprak haline geldiğimiz zaman, dirilip cezalandırılacak mıyız?”"},{"n":54,"t":"“Siz onun durumuna vâkıf olmak ister misiniz?” dedi."},{"n":55,"t":"Etrafına bakınıp, birden onu cehennemin ortasında görecek."},{"n":56,"t":"“Allah`a andolsun ki, az kalsın beni de helâk edecektin.”"},{"n":57,"t":"“Eğer Rabbimin nimeti olmasaydı, ben de seninle birlikte orada olanlardan olacaktım.”"},{"n":"58-59","t":"“Biz, birinci ölümün dışında. bir daha ölmeyeceğiz, değil mi? Biz azap da görmeyeceğiz.”"},{"n":60,"t":"İşte asıl büyük mutluluk ve kurtuluş budur."},{"n":61,"t":"Çalışanlar bunun için çalışsın!"},{"n":62,"t":"“İkram olarak bu mu daha iyidir, yoksa zakkum ağacı mı?”"},{"n":63,"t":"Biz o ağacı, zâlimler için bir azap kıldık."},{"n":64,"t":"O, cehennemin dibinde biten bir ağaçtır."},{"n":65,"t":"Meyveleri şeytanların başları gibidir."},{"n":66,"t":"Onlar kesinlikle ondan yiyip, karınlarını onunla dolduracaklar."},{"n":67,"t":"Sonra, onun üzerine kaynar su karışımı bir içecek içerler."},{"n":68,"t":"Sonra dönüşleri elbette cehennemedir."},{"n":"69-70","t":"Şüphesiz onlar atalarını sapıklıkta buldular ve peşlerinden koşup gittiler."},{"n":71,"t":"Andolsun ki, onlardan önce eski milletlerin çoğu sapıklığa düştü."},{"n":72,"t":"Şüphesiz, biz onlara uyarıcılar göndermiştik."},{"n":73,"t":"Uyarılanların sonucunun ne olduğuna bir bak!"},{"n":74,"t":"Allah`ın ihlâslı kulları müstesna."},{"n":75,"t":"Andolsun, Nûh bize yalvarıp yakardı. Biz de duayı ne güzel kabul ederiz!"},{"n":76,"t":"Kendisini ve ehlini o büyük felâketten kurtardık."},{"n":77,"t":"Sâdece onun soyunu geriye bırakmıştık."},{"n":78,"t":"Sonradan gelenler içinde ona iyi bir ün bıraktık."},{"n":79,"t":"Âlemlerde Nûh`a selâm olsun."},{"n":80,"t":"İşte biz, iyi iş yapanları böyle ödüllendiririz."},{"n":81,"t":"Çünkü o, bizim inanmış kullarımızdan idi."},{"n":82,"t":"Sonra diğerlerini suda boğduk."},{"n":83,"t":"Şüphesiz İbrâhim de Nûh`un milletinden idi."},{"n":84,"t":"Çünkü o, Rabbine samimi bir kalple yönelmişti."},{"n":85,"t":"“Neye tapıyorsunuz?”"},{"n":86,"t":"“Allah`ı bırakıp uydurma tanrılar mı istiyorsunuz?”"},{"n":87,"t":"“Âlemlerin Rabbi hakkında ne düşünüyorsunuz?”"},{"n":88,"t":"İbrâhim yıldızlara bir göz attı."},{"n":89,"t":"“Ben hastayım” dedi."},{"n":90,"t":"Onlar da onu bırakıp uzaklaştılar."},{"n":91,"t":"O da tanrılarına yöneldi, “Yemez misiniz?” dedi."},{"n":92,"t":"“Neyiniz var; konuşmuyorsunuz!”"},{"n":93,"t":"Bütün gücüyle onları kırmaya başladı."},{"n":94,"t":"Kavmi, koşarak ona geldi."},{"n":95,"t":"“Elinizle yonttuklarınıza mı tapıyorsunuz?”"},{"n":96,"t":"“Oysa sizi de, yonttuklarınızı da Allah yaratmıştır.”"},{"n":97,"t":"Kavmi, “Onun için bir yer yapın ve onu ateşe atın” dediler."},{"n":98,"t":"Ona tuzak kurmak istediler. Biz de onları alçaklardan kıldık."},{"n":99,"t":"İbrâhim, “Şüphesiz ben Rabbime gidiyorum. O beni doğru yola eriştirecektir” dedi."},{"n":100,"t":"“Ey Rabbim! Bana sâlihlerden olacak bir çocuk ver” dedi."},{"n":101,"t":"Bunun üzerine ona yumuşak huylu bir erkek çocuk müjdeledik."},{"n":102,"t":"Babasıyla beraber yürüyüp gezecek çağa erişince, “Yavrucuğum! Rüyamda seni boğazladığımı görüyorum; bir düşün; ne dersin?” dedi. O da, “Babacığım! Emrolunduğun şeyi yap! İnşallah beni sabredenlerden bulursun” diye cevap verdi."},{"n":103,"t":"Her ikisi de Allah`ın emrine teslim olunca, babası onu yan üstü yatırdı."},{"n":104,"t":"“Ey İbrâhim! Sen kesinlikle rüyanı doğruladın. İşte biz, iyileri böyle ödüllendiririz.”"},{"n":105,"t":"“Ey İbrâhim! Sen kesinlikle rüyanı doğruladın. İşte biz, iyileri böyle ödüllendiririz.”"},{"n":106,"t":"Şüphesiz bu büyük bir imtihandır."},{"n":107,"t":"Biz ona kurtuluş bedeli olarak büyük bir kurban verdik."},{"n":108,"t":"Sonra gelenler içinde ona iyi bir ün bıraktık."},{"n":109,"t":"İbrâhim`e selâm olsun!"},{"n":110,"t":"İyi iş yapanları işte böyle ödüllendiririz."},{"n":111,"t":"Şüphesiz o, inanmış kullarımızdandı."},{"n":112,"t":"Ona, iyilerden bir peygamber olarak İshâk`ın müjdesini verdik."},{"n":113,"t":"Onu ve İshâk ailesini mübarek kıldık. O ikisinin soyundan iyi iş yapanlar da, kendilerine açıkça zulmedenler de vardır."},{"n":114,"t":"Andolsun, biz Mûsâ ve Hârûn`a da lütufta bulunduk."},{"n":115,"t":"O ikisini ve kavimlerini, o büyük felaketten kurtardık."},{"n":116,"t":"Onlara yardım ettik. Onlar galip oldular."},{"n":117,"t":"Onlara apaçık kitabı verdik."},{"n":118,"t":"Onları doğru yola yönelttik."},{"n":119,"t":"Sonra gelenler içinde onlara iyi bir ün bıraktık."},{"n":120,"t":"Mûsâ ve Hârûn`a selâm olsun."},{"n":121,"t":"Şüphesiz iyi iş yapanları işte böyle ödüllendiririz."},{"n":122,"t":"Onlar, inanmış kullarımızdandı."},{"n":123,"t":"Şüphesiz, İlyâs da peygamberlerdendir."},{"n":124,"t":"“Sakınmıyor musunuz?”"},{"n":125,"t":"“Ba‘l adlı puta tapıyorsunuz da, en güzel yaratıcıyı terk mi ediyorsunuz?”"},{"n":126,"t":"“Sizin ve atalarınızın Rabbi olan Allah`ı bırakıyorsunuz öyle mi?”"},{"n":127,"t":"Onu yalanladılar. Onlar bu sebeple sonunda cehenneme atılacaklardır."},{"n":128,"t":"Ancak Allah`ın samimi kulları hariç."},{"n":129,"t":"Sonra gelenler içinde ona da iyi bir ün bıraktık."},{"n":130,"t":"İlyâs`a da selâm olsun."},{"n":131,"t":"Şüphesiz, iyi iş yapanları işte böyle ödüllendiririz."},{"n":132,"t":"O, inanmış kullarımızdandı."},{"n":133,"t":"Şüphesiz, Lût da peygamberlerdendir."},{"n":134,"t":"Biz, onu ve bütün ailesini kurtarmıştık."},{"n":135,"t":"Sâdece yaşlı bir kadın helâk olanlar arasında kaldı."},{"n":136,"t":"Sonra diğerlerini helâk ettik."},{"n":137,"t":"Sizler sabahleyin, onların helâk oldukları yerden geçersiniz."},{"n":138,"t":"Akşamleyin de. Hiç düşünmez misiniz?"},{"n":139,"t":"Şüphesiz Yûnus da peygamberlerdendir."},{"n":140,"t":"Bir vakit, dolu gemi ile kaçmıştı."},{"n":141,"t":"Kura çekti ve kaybedenlerden oldu."},{"n":142,"t":"Balık onu yuttu. O kınanmayı hak etmişti."},{"n":"143-144","t":"Eğer Allah`ı sıkça ananlardan olmasaydı, kıyamet gününe kadar balığın karnında kalırdı."},{"n":145,"t":"Onu bitkin bir halde açık araziye attık."},{"n":146,"t":"Üzerini kabakgillerden bir bitki ile örttük."},{"n":147,"t":"Onu, nüfusu yüzbin veya daha fazla sayıda olan bir topluma peygamber olarak gönderdik."},{"n":148,"t":"Ona inandılar, bu sebeple biz de onları belli bir süreye kadar refah içinde yaşattık."},{"n":149,"t":"“Kızlar Rabbinin de, erkekler onların mıdır?”"},{"n":150,"t":"“Yoksa biz, melekleri onların gözü önünde kız olarak mı yarattık?”"},{"n":151,"t":"Dikkat ediniz, kesinlikle onlar yalan uydurup duruyorlar."},{"n":152,"t":"“Allah doğurdu” diyorlar. Şüphesiz onlar yalancıdırlar."},{"n":153,"t":"Allah, kızları oğullara tercih mi etmiş?"},{"n":154,"t":"Ne oluyor size? Nasıl hüküm veriyorsunuz?"},{"n":155,"t":"Hiç düşünmüyor musunuz?"},{"n":156,"t":"Yoksa sizin açık bir deliliniz mi var?"},{"n":157,"t":"Doğru sözlülerden iseniz, kitabınızı getiriniz."},{"n":158,"t":"Allah ile, görünmeyen varlıklar arasında bir soy bağı kurdular. Oysa görünmeyen varlıklar, müşriklerin cehenneme hazır edilecekler olduğunu bilmektedirler."},{"n":159,"t":"Allah, onların nitelendirmelerinden uzaktır."},{"n":160,"t":"Allah`ın samimi kulları hariç."},{"n":"161-163","t":"Sizler ve taptıklarınız, cehenneme girecek olandan başkasını kandırıp Allah`ın yolundan çıkaramazsınız."},{"n":164,"t":"“Bizim her birimiz için bilinen bir makam vardır.”"},{"n":165,"t":"“Biz saf tutarız.”"},{"n":166,"t":"“Elbette Allah`ı noksan sıfatlardan uzak tutarız.”"},{"n":"167-169","t":"Müşrikler, “Öncekilere verilenlerden bizde de bir kitap olsaydı, mutlaka Allah`ın ihlaslı kulları olurduk!” diyorlardı."},{"n":170,"t":"Buna rağmen Kur`ân`ı inkâr ettiler. Ama ileride bileceklerdir."},{"n":171,"t":"Andolsun, peygamber kullarımıza söz vermişizdir."},{"n":172,"t":"Doğrusu, onlar yardım göreceklerdir."},{"n":173,"t":"Bizim ordumuz şüphesiz üstün gelecektir."},{"n":174,"t":"Bir süreye kadar onlara aldırış etme."},{"n":175,"t":"Onların halini gözetle; onlar da gözetleyeceklerdir."},{"n":176,"t":"Azabımızı acele mi istiyorlar?"},{"n":177,"t":"O azap yurtlarına indiğinde, uyarılmış olup da yola gelmeyenlerin sabahı ne kötü olur!"},{"n":178,"t":"Bir süreye kadar onlardan yüz çevir."},{"n":179,"t":"Onların halini gözetle; onlar da gözetleyeceklerdir."},{"n":180,"t":"Senin güçlü olan Rabbin, onların nitelendirmelerinden uzaktır."},{"n":181,"t":"Peygamberlere selâm olsun."},{"n":182,"t":"Övgü de âlemlerin Rabbi Allah`a olsun."}],[{"n":"1-2","t":"Sâd. Şeref sahibi Kur`ân`a yemin olsun ki, inkâr edenler bir gurur ve ayrılık içindedirler."},{"n":3,"t":"Onlardan önce nice nesilleri helâk ettik. O zaman yalvardılar, ama kurtuluş zamanı değildi."},{"n":4,"t":"“Bu, büyücüdür; yalancıdır.”"},{"n":5,"t":"“Bütün tanrıları tek bir tanrı mı yaptı? Şüphesiz bu şaşılacak bir şeydir.”"},{"n":6,"t":"“Yolunuza devam ediniz, tanrılarınızı bırakmayınız. Şüphesiz bizden istenen de budur.”"},{"n":7,"t":"“Biz onun söylediklerini, yeni inançlarda duymadık. Kur`ân, onun uydurmasından başka bir şey değildir.”"},{"n":8,"t":"“Kur`ân içimizden sadece ona mı indirildi?” Doğrusu onlar, gönderdiğimiz Kur`ân hakkında şüphe içindedirler. Hayır! Azabımı henüz tatmadılar."},{"n":9,"t":"Yoksa her şeye gücü yeten ve çok cömert Rabbinin rahmet hazineleri onların yanında mıdır?"},{"n":10,"t":"Yoksa göklerin, yerin ve bu ikisi arasında bulunanların mülkiyeti onların mıdır? Öyleyse ne duruyorlar? Göğe yükselme yollarını arasınlar."},{"n":11,"t":"Onlar çeşitli gruplardan oluşmuş, şimdiden mağlub edilmeye mahküm bir ordudur."},{"n":"12-13","t":"Onlardan önce Nûh kavmi, ‘Âd kavmi, kazıklar sahibi Firavun, Semûd, Lût kavmi ve Eyke halkı da yalanladılar. İşte bunlar da birleşik topluluklardı."},{"n":14,"t":"Onların her biri, gönderilen peygamberleri yalanladılar da bu yüzden azabım hak oldu."},{"n":15,"t":"Bunlar da ancak, bir an gecikmesi olmayan korkunç bir ses beklemektedirler."},{"n":16,"t":"“Rabbimiz! Bizim payımızı hesap gününden önce ver!” dediler."},{"n":17,"t":"Onların söylediklerine sabret! Kulumuz Dâvûd`u, o kuvvet sahibi zatı hatırla! O, hep Allah`a yönelirdi."},{"n":18,"t":"Doğrusu biz, dağları Dâvûd`un emrine vermiştik. Gece-gündüz onunla birlikte Allah`ı anmaktadırlar."},{"n":19,"t":"Kuşları da onun emrine topladık. Hepsi Allah`a yönelmektedirler."},{"n":20,"t":"Onun mülkünü güçlendirdik. Kendisine hikmet ve güzel konuşma vermiştik."},{"n":21,"t":"Sana o davacıların öyküsü geldi mi? Hani mabedinin duvarına tırmanmışlardı."},{"n":22,"t":"“Korkma, birbirine haksızlık etmiş iki davalıyız. Aramızda adaletle hükmet, adaletten ayrılma, bizi doğru çözüme ulaştır.”"},{"n":23,"t":"“Bu benim kardeşimdir. Onun doksan dokuz koyunu, benim de bir koyunum var. ‘Onu da bana ver` dedi ve beni konuşmada yendi.”"},{"n":24,"t":"Dâvûd, “Senden, koyununu kendi koyunlarına katmak istemekle, sana haksızlık etmiştir. Ortaklardan birçoğu birbirinin haklarına tecavüz ederler. Ancak inanıp yararlı iş yapanlar hariç. Onlar da çok azdır” dedi. Dâvûd, bizim kendisini denediğimizi anladı. Rabbinden bağışlanma diledi ve secdeye kapanarak tövbe etti."},{"n":25,"t":"Biz de onu, verdiği bu hükümden dolayı bağışladık. Katımızda onun bir yakınlığı ve güzel bir yeri vardır."},{"n":26,"t":"`Ey Davud! Biz seni yeryüzünde halife kıldık. O halde insanlar arasında hak ile hükmet ve keyfe uyma. Yoksa seni Allah`ın yolundan saptırır. Şüphesiz Allah`ın yolundan sapanlar için hesap gününü unutmalarından dolayı çetin bir azap vardır."},{"n":27,"t":"Biz göğü, yeri ve bu ikisinin arasındakileri boş yere yaratmadık. Bu inkâr edenlerin zannıdır. (İçine atılacakları) ateşten dolayı inkâr edenlerin vay haline!"},{"n":28,"t":"Yoksa biz, inanıp yararlı iş yapanlara, yeryüzünde bozgunculuk yapanlar gibi mi davranacağız? Veya Allah`a saygı duyanları günahkârlar gibi mi sayacağız?"},{"n":29,"t":"Sana bu mübarek kitabı, âyetlerini düşünsünler ve aklı olanlar öğüt alsınlar diye indirdik."},{"n":30,"t":"Biz Dâvûd`a Süleyman`ı bağışladık. Süleyman ne iyi bir kuldu! Çünkü o, daima Allah`a yöneliyordu."},{"n":31,"t":"Ona bir akşamüstü, üç ayak üzerine duran, soylu atlar sunulmuştu."},{"n":32,"t":"Süleyman, “Rabbimi hatırlattıklarından dolayı atları severim” dedi. Gözünden kaybolana kadar onlara baktı."},{"n":33,"t":"“Onları bana tekrar getiriniz” dedi. Bacaklarını ve boyunlarını ovmaya başladı."},{"n":34,"t":"Andolsun, biz Süleyman`ı sınayıp tahtının üstüne bir ceset attık. Sonra Allah`a yöneldi."},{"n":35,"t":"“Ey Rabbim! Beni bağışla, bana benden sonra kimsenin ulaşamayacağı bir mülk ver. Şüphesiz bağışlayıcı sadece sensin.”"},{"n":36,"t":"Bunun üzerine biz, rüzgârı onun emrine verdik. Onun emriyle istediği yöne doğru tatlı tatlı esiyordu."},{"n":37,"t":"Bütün usta ve dalgıç şeytanları da emrine verdik."},{"n":38,"t":"Zincirlere vurulmuş başkalarını da."},{"n":39,"t":"İşte bu, bizim ihsanımızdır. “Sen onu ister dilediğine ver, ister verme, sorulmazsın” dedik."},{"n":40,"t":"Katımızda onun bir yakınlığı ve güzel bir yeri vardır."},{"n":41,"t":"Kulumuz Eyyûb`u da hatırla! Bir vakit Rabbine, “Şeytan bana bir bitkinlik ve eziyet verdi” diye yalvarmıştı."},{"n":42,"t":"Ona, “Ayağını yere vur. İşte, yıkanacak ve içilecek soğuk bir su” dedik."},{"n":43,"t":"Katımızdan bir rahmet ve akıl sahiplerine bir öğüt olarak ona ailesini, onlarla birlikte bir o kadarını daha verdik."},{"n":44,"t":"“Eline bir demet sap al ve onunla vur; yeminini bozma” dedik. Şüphesiz biz onu sabırlı bulduk. O ne iyi bir kuldu! O, daima Allah`a yönelirdi."},{"n":45,"t":"Kuvvetli ve basiretli kullarımız İbrâhim, İshâk ve Ya‘kûb`u da hatırla!"},{"n":46,"t":"Biz onları daima âhireti düşünen ihlâslı kullar kıldık."},{"n":47,"t":"Şüphesiz onlar, katımızda seçkin ve iyi kullardı."},{"n":48,"t":"İsmâil`i, Elyesa‘ı, Zülkifl`i de hatırla!; hepsi de iyi kullardandı."},{"n":49,"t":"Bunlar bir öğüttür. Şüphesiz muttakîler için güzel bir gelecek vardır."},{"n":50,"t":"Kendilerine kapıları açılmış ‘Adn cennetleri vardır."},{"n":51,"t":"Onlar, orada koltuklara kurulup yaslanarak, birçok meyveler ve meşrubat isterler."},{"n":52,"t":"Yanlarında, eşlerinden başkasına bakmayan, kendilerine yaşıt eşler vardır."},{"n":53,"t":"İşte, hesap günü için, size vaad edilen budur."},{"n":54,"t":"Şüphesiz bu, bizim vaadimiz olan rızıktır. Onda tükenmek yoktur."},{"n":55,"t":"Bu da bir uyarıdır. Şüphesiz, azgınlar için de kötü bir gelecek vardır."},{"n":56,"t":"Onlar cehenneme girecekler. Orası ne kötü bir kalma yeridir!"},{"n":57,"t":"İşte bu, kaynar su ve irindir. Onu tatsınlar."},{"n":58,"t":"Bu tür çeşit çeşit diğer azaplar da vardır."},{"n":59,"t":"İnkârcıların önderlerine, “İşte bu, sizinle beraber cehenneme girecek topluluktur” denildiğinde, “Onlar rahat yüzü görmesin, onlar mutlaka ateşe gireceklerdir” derler."},{"n":60,"t":"Önderlere uyanlar ise, “Asıl siz rahat yüzü görmeyiniz! Bizi buraya süren sizsiniz. Burası ne kötü bir yerdir!” derler."},{"n":61,"t":"“Rabbimiz! Bunu bizim önümüze kim getirdiyse, onun ateşteki azabını iki kat arttır!” derler."},{"n":62,"t":"“Dünyada kendilerini kötülerden saydığımız kimseleri burada niçin göremiyoruz?”"},{"n":63,"t":"“Alaya aldığımız onlar değil miydi? Yoksa onları gözden mi kaçırdık?”"},{"n":64,"t":"İşte cehennemliklerin bu şekilde tartışması gerçekleşecektir."},{"n":65,"t":"“Ben, sadece bir uyarıcıyım. Tek olan ve her şeyin üstesinden gelen Allah`tan başka hiçbir tanrı yoktur.”"},{"n":66,"t":"“O, göklerin, yerin ve ikisi arasında bulunanların Rabbidir. Onun her şeye gücü yeter ve affedicidir.”"},{"n":67,"t":"“Bu uyardığım husus, evrensel bir haberdir.”"},{"n":68,"t":"“Siz ondan yüz çeviriyorsunuz.”"},{"n":69,"t":"“Melekler topluluğunun aralarında neyi tartıştıkları hakkında benim hiçbir bilgim yoktur.”"},{"n":70,"t":"Ben gelecek tehlikeleri apaçık uyarıcı olduğum içindir ki, bana vahy olunuyor."},{"n":71,"t":"“Ben, çamurdan bir beşer yaratacağım.”"},{"n":72,"t":"“Onu şekillendirip ruhumdan üflediğimde, derhal ona secdeye kapanınız.”"},{"n":73,"t":"Bütün melekler secde ettiler."},{"n":74,"t":"Yalnız İblis secde etmedi. O büyüklük tasladı ve kâfirlerden oldu."},{"n":75,"t":"Allah, “Ey İblis! Kudretimle yarattığıma secde etmekten seni meneden nedir? Böbürlendin mi, yoksa yücelerden misin?” dedi."},{"n":76,"t":"İblis, “Ben ondan daha üstünüm. Beni ateşten, onu çamurdan yarattın” dedi."},{"n":77,"t":"Allah, “Çık oradan, sen kovuldun.”"},{"n":78,"t":"“Ceza gününe kadar lanetim senin üzerine olsun” dedi."},{"n":79,"t":"İblis, “Ey Rabbim! Tekrar diriliş gününe kadar, bana süre ver” dedi."},{"n":"80-81","t":"Allah, “İşte o belli vaktin geleceği güne kadar sen süre verilenlerdensin” dedi."},{"n":"82-83","t":"İblis, “Senin şanına andolsun ki ihlaslı kulların hariç, onların hepsini azdıracağım” dedi."},{"n":84,"t":"Allah, “Gerçek budur ve ben gerçeği söylerim.”"},{"n":85,"t":"“Elbette, sen ve sana uyanların hepsiyle cehennemi dolduracağım” dedi."},{"n":86,"t":"“Ben, tebliğime karşılık sizden bir karşılık istemiyorum. Ben, zorluk çıkaranlardan da değilim.”"},{"n":87,"t":"Bu Kur`ân sadece âlemlere bir öğüttür."},{"n":88,"t":"Onun verdiği haberlerin gerçek olduğunu, bir zaman sonra çok iyi anlayacaksınız."}],[{"n":1,"t":"Bu kitap, her şeye gücü yeten ve her işinde hikmet bulunan Allah tarafından indirilmiştir."},{"n":2,"t":"Bizim bu kitabı sana gerçek olarak indirdiğimizde şüphe yoktur. O halde sen de dini Allah`a has kılarak O`na kulluk et."},{"n":3,"t":"Dikkat ediniz, saf din Allah`a aittir. O`ndan başkasını tanrı edinenler; “Bizi sadece Allah`a yaklaştırsınlar diye onlara kulluk ediyoruz” derler. Şüphesiz ki Allah, ayrılığa düştükleri şeylerde aralarında hüküm verecektir. Elbette Allah yalancı ve inkârcı kimseyi doğru yola iletmez."},{"n":4,"t":"Allah bir çocuk edinmek isteseydi, yarattıklarından dilediğini seçerdi. Hâşâ, O, bundan uzaktır. O, tektir; her şeyin üstesinden gelendir."},{"n":5,"t":"Allah, gökleri ve yeri bir amaç uğruna yarattı. Geceyi gündüze, gündüzü geceye sarar. Güneşi ve ayı emri altına almıştır. Her biri belli bir süreye kadar akıp gider. Dikkat ediniz, O`nun her şeye gücü yeter; affedicidir."},{"n":6,"t":"Sizi bir cevherden yaratmış, sonra o cevherden eşini de var etmiştir. Size evcil hayvanlardan sekiz çift bahşetmiştir. Sizi de annelerinizin karınlarında aşama aşama üç karanlıkta yaratıyor. İşte, Rabbiniz olan Allah budur. Mülk O`nundur. O`ndan başka tanrı yoktur. Öyleyken nasıl oluyor da döndürülüyorsunuz?"},{"n":7,"t":"Eğer inkâr ederseniz, şüphesiz ki Allah size muhtaç değildir. O, kullarının inkârına razı değildir. Eğer şükrederseniz sizden bunu kabul eder. Hiçbir günahkâr diğerinin günahını yüklenemez. Sonra dönüşünüz Rabbinizedir. O da, yaptıklarınızı size haber verecektir. Şüphesiz O sinelerde saklı olan her şeyi bilir."},{"n":8,"t":"“Küfrünle azıcık yaşa, sen ateş halkındansın.”"},{"n":9,"t":"“Bilenlerle bilmeyenler bir olur mu? Doğrusu ancak akıl sahipleri bunları hakkıyla düşünür.”"},{"n":10,"t":"“Ey Allah`ın inanan kulları! Rabbinize karşı gelmekten sakının! Bu dünyada iyilik yapanlara iyilik vardır. Allah`ın arzı geniştir. Yalnızca sabredenlere, ödülleri hesapsız ödenecektir.”"},{"n":11,"t":"“Bana, dini Allah`a has kılarak O`na kulluk etmem emrolundu.”"},{"n":12,"t":"“Bana Müslümanların ilki olmam emrolundu.”"},{"n":13,"t":"“Rabbime karşı gelirsem doğrusu büyük günün azabından korkarım.”"},{"n":14,"t":"“Ben dinimde ihlâs ile ancak Allah`a ibadet ederim.”"},{"n":15,"t":"“Gerçekten iflas edenler, kıyamet günü kendilerini ve ailelerini zarara uğratanlardır. Dikkat ediniz, apaçık kayıp işte budur.”"},{"n":16,"t":"Onları üstlerinden ve altlarından gölgeler gibi ateş kaplayacaktır. İşte Allah kullarını sürekli böyle sakındırıyor. “Ey kullarım! Artık emirlerime karşı gelmekten sakınınız.”"},{"n":17,"t":"Tâğût`a kulluk etmekten uzak durup Allah`a yönelenlere müjdeler olsun. “Sen, bu kullarımı müjdele!”"},{"n":18,"t":"Sözleri dinleyip en güzeline uyanları müjdele. İşte Allah`ın doğru yola ulaştırdığı bunlardır. Gerçek akıl sahipleri de bunlardır."},{"n":19,"t":"Hakkında azap kesinleşmiş olanı, ateştekini, sen mi kurtaracaksın?"},{"n":20,"t":"Fakat Rabblerine saygı duyanlar için, üst üste yapılmış, altlarından ırmaklar akan köşkler vardır. Bu, Allah`ın vaadidir. Allah, verdiği sözden dönmez."},{"n":21,"t":"Görmüyor musun? Allah gökten su indiriyor, onu yerdeki kaynaklara yerleştiriyor, sonra onunla türlü türlü renklerde ekinler yetiştiriyor. Sonra onların kuruyup sapsarı olduklarını görüyorsun. Sonra da onu çer-çöp haline getiriyor. Şüphesiz bütün bunlarda akıl sahipleri için bir ders vardır."},{"n":22,"t":"Allah, kimin gönlünü İslâm`a açmışsa, o, Rabbi`nin katından bir nur üzere olmaz mı? Gönülleri Allah`ı anmak hususunda katılaşmış olanlara yazıklar olsun! İşte bunlar, apaçık sapıklık içindedirler."},{"n":23,"t":"Allah, mana ve lafızları birbiriyle uyumlu ve ikili anlatımlı kitabı, sözlerin en güzeli olarak indirmiştir. Rabblerine saygı duyanlar onu okuyup dinleyince tüyleri ürperir. Sonra bütün benlikleri ve kalpleri Allah`ı anmaya yumuşar. İşte bu kitap, Allah`ın doğru yoludur. Onunla, dileyenleri doğru yola iletir. Allah kimi saptırırsa, artık ona doğru yolu gösterecek hiçbir kimse yoktur."},{"n":24,"t":"Kıyamet günü kötü azaptan yüzünü korumaya çalışacak kimse, azaptan emin olarak gelenle bir midir? Zâlimlere, “Tadın kazandıklarınızı!” denir."},{"n":25,"t":"Onlardan öncekiler de yalanlamışlardı da, onlara farkına varmadıkları bir yerden azap çattı."},{"n":26,"t":"Allah onlara dünya hayatında bir rüsvâylık tattırmıştı. Andolsun ki âhiretin azabı daha büyüktür; keşke bilselerdi!"},{"n":27,"t":"Biz bu Kur`ân`da insanlara, öğüt alsınlar diye her türlü örneği verdik."},{"n":28,"t":"Sakınsınlar diye, onu pürüzsüz Arapça bir Kur`ân olarak indirdik."},{"n":29,"t":"Allah, geçimsiz efendileri olan bir adamla, yalnızca bir kişiye bağlı bir adamı örnek olarak verir. Bu ikisinin durumu eşit midir? Övgü Allah`a mahsustur. Fakat onların çoğu bilmezler."},{"n":30,"t":"Şüphesiz, sen de öleceksin, onlar da ölecekler."},{"n":31,"t":"Sonra sizler, kıyamet günü, Rabbinizin huzurunda kesinlikle birbirinizi dava edeceksiniz."},{"n":32,"t":"Allah hakkında yalan uydurandan ve önüne konulan gerçeği yalanlayandan daha zâlim kimdir? Cehennem, kâfirler için uygun yer değil midir?"},{"n":33,"t":"Ama, hakikati getiren ve onu bütün kalbiyle tasdik edenler var ya; işte, takvâ sahipleri onlardır."},{"n":34,"t":"Onlar için Rabbleri katında diledikleri her şey vardır. İşte bu, iyilik edenlerin ödülüdür."},{"n":35,"t":"Böylece Allah, onların geçmişte yaptıkları en kötü davranışları bile örtecek ve yaptıklarının en güzeline denk olarak ödüllerini verecektir."},{"n":36,"t":"Allah, kuluna yetmez mi? Onlar seni, O`ndan başkaları ile korkutuyorlar. Allah, kimi saptırırsa artık ona doğru yolu gösterecek hiçbir kimse yoktur."},{"n":37,"t":"Allah, kime de doğru yolu gösterirse, artık onu saptıracak da hiçbir kimse yoktur. Allah`ın, her şeyi yapmaya ve her kötülüğü cezalandırmaya gücü yetmez mi?"},{"n":38,"t":"“Bana Allah yeter. Tevekkül edenler ancak O`na güvenip dayanırlar.”"},{"n":39,"t":"“Ey kavmim! Elinizden geleni yapınız, doğrusu ben de yapacağım! Kendisini rezil edecek azap, kime gelecek, kime sürekli azap inecek, yakında bileceksiniz!”"},{"n":40,"t":"“Ey kavmim! Elinizden geleni yapınız, doğrusu ben de yapacağım! Kendisini rezil edecek azap, kime gelecek, kime sürekli azap inecek, yakında bileceksiniz!”"},{"n":41,"t":"Şüphesiz biz bu kitabı sana, insanlar için hak olarak indirdik. Artık, kim doğru yolu seçerse kendi lehinedir; kim de saparsa ancak kendi aleyhine sapmış olur. Sen onların üzerinde vekil değilsin."},{"n":42,"t":"Allah, canları, ölümleri sırasında alır; ölmeyenleri de uykuları sırasında... Sonra, haklarında ölüm hükmü verdiklerini alıkoyar; ötekileri, belirlenen belli bir süreye kadar salıverir. Bunda düşünen bir toplum için dersler vardır."},{"n":43,"t":"“Onlar hiçbir şeye güç yetiremezler ve akıl erdiremezlerse de mi?”"},{"n":44,"t":"“Bütün şefaat Allah`ındır. Göklerin ve yerin hükümranlığı O`nundur. Sonra O`na döndürüleceksiniz.”"},{"n":45,"t":"Allah, tek olarak anıldığında, âhirete inanmayanların içlerini sıkıntı basar. Ama Allah`tan başkası anıldığı zaman hemen sevinir, mutluluk duyarlar."},{"n":46,"t":"“Ey Allah`ım! Ey göklerin ve yerin yoktan yaratıcısı! Ey gizli ve açık her şeyi bilen! Kullarının, arasında ayrılığa düştükleri konularda hüküm verecek sensin.”"},{"n":47,"t":"Şâyet yeryüzünde bulunan her şey ve bununla birlikte bir o kadarı daha zâlimlerin olsaydı, kıyamet gününde o azabın kötülüğünden kurtulmak için kesinlikle onu fidye olarak verirlerdi. Onlara Allah tarafından, hiç hesaba katmadıkları şeyler gösterilecektir."},{"n":48,"t":"Onların kazandıkları kötülükler, o gün açığa çıkmış olacak ve alaya aldıkları şey de kendilerini çepeçevre kuşatacaktır."},{"n":49,"t":"İnsana bir zarar dokunduğu zaman bize yalvarır. Sonra katımızdan ona bir nimet verdiğimizde, “Bu bana yalnızca bilgimden dolayı verilmiştir” der. Hayır, o bir sınavdır. Fakat insanların çoğu bilmezler."},{"n":50,"t":"Bunu onlardan öncekiler de söylemişlerdi de, kazandıkları kendilerine hiçbir fayda vermemişti."},{"n":51,"t":"Kazandıkları kötülüklerin cezası başlarına gelmişti. Aynı şekilde bunlardan zulmedenlerin de kazandıkları kötülüklerinin cezası başlarına gelecektir. Onlar buna asla engel olamayacaklardır."},{"n":52,"t":"Allah`ın, dilediklerine verdiği rızkı genişletip kıstığını bilmezler mi? Şüphesiz bunda, inanan toplum için dersler vardır."},{"n":53,"t":"Ey kendi nefisleri aleyhinde haddi aşan kullarım! Allah`ın rahmetinden ümit kesmeyiniz! Çünkü Allah, bütün günahları bağışlar. Şüphesiz ki O, çok affedicidir; merhamet sahibidir.”"},{"n":54,"t":"“Size azap gelip çatmadan önce Rabbinize dönünüz, O`na teslim olunuz, sonra size yardım edilmez.”"},{"n":"55-56","t":"“Siz farkında olmadan ansızın başınıza azap gelmeden önce, Rabbinizden size indirilen en güzel kitaba uyunuz ki, hiçbir insan, “Allah`a karşı aşırı gittiğim, küçümseyenlerden biri olduğum için yazıklar olsun bana!” demesin."},{"n":57,"t":"`Allah bana doğru yolu gösterme lütfunda bulunsaydı, Allah’a sığınanlardan, emirlerine yapışanlardan, günahlardan arınıp azaptan korunanlardan, kulluk ve sorumluluk şuuruyla, haklarına ve özgürlüklerine sahip çıkarak şahsiyetli davranan, dinî ve sosyal görevlerinin bilincinde olan mü’minlerden olurdum.` diyeceği günden önce Kur’ân’a tâbi olun."},{"n":58,"t":"Ya da azabı gördüğünde, “Keşke dünyaya bir daha gönderilseydim de iyi amel yapanlardan olsaydım” demesin diye."},{"n":59,"t":"“Elbette sana âyetlerim geldi de sen onları yalanladın, sen kibirlendin ve sen inkâr edenlerden oldun.”"},{"n":60,"t":"Kıyamet günü, Allah adına yalan söyleyenleri yüzleri simsiyah olmuş görürsün. Kibirlenenler için cehennemde yer mi yoktur?"},{"n":61,"t":"Allah, takvâ sahiplerini kurtuluşa erdirir. Onlara hiçbir fenalık dokunmaz. Onlar, üzülmezler de."},{"n":62,"t":"Allah, her şeyin yaratıcısıdır ve her şeye vekildir."},{"n":63,"t":"Göklerin ve yerin anahtarları O`nundur. Allah`ın âyetlerini inkâr edenler, işte onlar gerçekten kaybedenlerdir."},{"n":64,"t":"“Ey câhiller! Bana, Allah`tan başkasına kulluk etmemi mi emrediyorsunuz?”"},{"n":65,"t":"“Eğer ortak koşarsan kesinlikle bütün yaptıkların boşa gider ve iflas edenlerden olursun.”"},{"n":66,"t":"Bilakis sen, yalnızca Allah`a kulluk et ve şükredenlerden ol!"},{"n":67,"t":"Onlar Allah`ı gerektiği şekilde takdir edemediler. Kıyamet günü bütün yeryüzü O`nun tasarrufundadır. Gökler O`nun kudret eliyle dürülmüş olacaktır. Allah, onların ortak koşmalarından uzak ve yücedir."},{"n":68,"t":"Sûr`a üflenince, Allah`ın diledikleri hariç olmak üzere, göklerde ve yerde ne/kim varsa hepsi bayılacaktır. Sonra Sûr`a bir daha üflenince, bir de ne göresin, onlar ayağa kalkmış bakıyorlar."},{"n":69,"t":"Yeryüzü Rabbinin nuruyla aydınlanacak. Amel defterleri ortaya konulacak. Peygamberler ve tanıklar getirilecek. Aralarında adaletle hüküm verilecek ve onlar hiçbir haksızlığa uğratılmayacaktır."},{"n":70,"t":"Herkese yaptığının karşılığı eksiksiz ödenecektir. Allah, onların ne yaptıklarını en iyi bilendir."},{"n":71,"t":"İnkâr edenler, gruplar halinde cehenneme sürülecekler. Oraya vardıklarında cehennemin kapıları açılacak; cehennemin bekçileri onlara, “Size, içinizden, Rabbinizin âyetlerini okuyan ve bugüne kavuşacağınıza dair uyarıda bulunan peygamberler gelmedi mi?” derler. “Evet geldi” derler ama, azap sözü kâfirlerin üzerine hak olmuştur."},{"n":72,"t":"Onlara, “Süreli olarak kalacağınız cehennemin kapılarından içeri giriniz” denilecektir. İşte böyle, kibirlenenlerin yeri ne kötüdür!"},{"n":73,"t":"Rabblerine saygı duyanlar da, gruplar halinde cennete götürüleceklerdir. Oraya geldiklerinde ve cennetin kapıları açıldığında, cennetin bekçileri onlara, “Size selâm olsun, hoş geldiniz. Artık süreli kalmak üzere giriniz buraya” derler."},{"n":74,"t":"Onlar, “Bize verdiği sözü yerine getiren, bizi dilediğimiz yerinde konaklayacağımız bu cennet yurduna vâris kılan Allah`a hamdolsun. İman edip iyi amelde bulunanların ödülü ne güzelmiş!” derler."},{"n":75,"t":"Sen, meleklerin de, egemenlik tahtının çevresini kuşatarak, Rabblerini hamd ile övdüklerini görürsün. Artık aralarında adaletle hükmolunmuş ve “âlemlerin Rabbi olan Allah`a hamdolsun” denilmiştir."}],[{"n":1,"t":"Hâ, mîm."},{"n":"2-3","t":"Bu kitap, mutlak galip, hakkıyla bilen, günahı bağışlayan, tövbeyi kabul eden, azabı çetin, lütuf sahibi olan Allah tarafından indirilmiştir. O`ndan başka tanrı yoktur, dönüş ancak O`nadır."},{"n":4,"t":"Allah`ın âyetleri hakkında, inkâr edenlerden başkası tartışmaz. Onların şehirlerde gezip dolaşması seni aldatmasın."},{"n":5,"t":"Onlardan önce Nûh toplumu ve bunların ardından da işbirlikçi gruplar, peygamberlerini yalanlamışlar ve her toplum kendi peygamberini yakalayıp etkisiz hale getirmek istemiştir. Bâtılı hakkın yerine koymak için mücadele etmişlerdi. Bunun üzerine ben onları kıskıvrak yakaladım. İşte, cezalandırmamın nasıl olduğunu gör!"},{"n":6,"t":"İnkâr edenlerin cehennemlik olduklarına dair Rabbinin sözü, böylece gerçekleşti."},{"n":7,"t":"“Ey Rabbimiz, sen rahmet ve bilgi bakımından her şeyi kapladın. Tövbe edip senin yoluna uyanları bağışla, onları cehennem azabından koru!”"},{"n":8,"t":"“Rabbimiz, onları ve babalarından, eşlerinden, çocuklarından iyi olan kimseleri, onlara söz verdiğin Adn cennetlerine koy. Şüphesiz üstün olan sensin; hikmet sahibi olan sensin, sen!”"},{"n":9,"t":"“Onları kötülüklerden koru! O gün sen, kimi kötülüklerden korursan ona merhamet etmişsindir. Bu, en büyük kurtuluştur.”"},{"n":10,"t":"“Allah`ın buğzu, sizin kendinize olan öfkenizden daha büyüktür. Çünkü imana çağırıldığınızda inkâr ederdiniz.”"},{"n":11,"t":"İnkâr edenler, “Ey Rabbimiz! Bizi iki defa öldürdün, iki defa dirilttin. Biz günahlarımızı itiraf ettik. Çıkış için bir yol var mı?” derler."},{"n":12,"t":"Sizin bu cezanızın sebebi, tek olan Allah`a çağırıldığınızda inkâr etmeniz, O`na şirk koşulduğunda inanmış olmanızdır. Artık hüküm, yüce ve büyük olan Allah`ındır."},{"n":13,"t":"Âyetlerini size gösteren ve gökten size rızık indiren O`dur. Ancak O`na yönelenler öğüt alır."},{"n":14,"t":"Kâfirler hoşlanmasa da siz, dini yalnız Allah`a has kılarak O`na dua ediniz."},{"n":15,"t":"O, dereceleri yükseltendir, egemenlik tahtının sahibidir. Buluşma günü hakkında uyarmak için, emrinden olan ruhu/Cebrail`i, kullarından dilediğine indirir."},{"n":16,"t":"O gün onlar ortaya çıkarlar. Hiçbir şeyleri Allah`a gizli kalmaz. “Bugün mülk kimindir?” “Tek ve her şeyin üstesinden gelen Allah`ındır.”"},{"n":17,"t":"Herkes kazandığının karşılığını görür. O gün hiçbir haksızlık yoktur. Şüphesiz Allah, hesabı çabuk görendir."},{"n":18,"t":"Yaklaşan gün hususunda onları uyar! Yürekler gırtlaklara dayanacaktır, habire yutkunacaklar. Zâlimlerin ne bir dostu, ne de sözü dinlenir yardımcıları olacaktır."},{"n":19,"t":"Allah, gözlerin hain bakışını ve sinelerin gizlediğini bilir."},{"n":20,"t":"Allah adaletle hükmeder. O`ndan başka çağırdıkları tanrılar ise, hiçbir şeye hükmedemezler. Çünkü işiten, gören yalnız Allah`tır."},{"n":21,"t":"Onlar, yeryüzünde gezip dolaşmadılar mı ki kendilerinden öncekilerin sonlarının nasıl olduğunu görsünler! Öncekiler, kuvvetçe ve yeryüzündeki eserleri yönünden bunlardan daha da üstündüler. Böyleyken, Allah onları günahları sebebiyle yakaladı. Onları Allah`ın gazabından koruyan da olmadı."},{"n":22,"t":"Bunun sebebi, peygamberleri kendilerine apaçık mucizeler getirdikleri halde inkâr etmeleri idi. Allah da kendilerini yakalayıverdi. Doğrusu O, kuvvetlidir; azabı da pek çetindir."},{"n":"23-24","t":"Andolsun ki biz, Mûsâ`yı mucizelerimizle ve apaçık delille Firavun, Hâmân ve Kârûn`a gönderdik. Onlar, “Bu, yalancı bir büyücüdür” dediler."},{"n":25,"t":"İşte Mûsâ, tarafımızdan kendilerine hakkı getirince, “Onunla beraber, iman edenlerin erkek çocuklarını öldürünüz, kadınlarını sağ bırakınız!” dediler. Ama kâfirlerin tuzağı elbette boşa çıkar."},{"n":26,"t":"“Bırakın beni, Mûsâ`yı öldüreyim; Rabbine yalvarsın!” dedi. “Çünkü ben onun, dininizi değiştireceğinden, yahut yeryüzünde fesat çıkaracağından korkuyorum.”"},{"n":27,"t":"Mûsâ da, “Ben, hesap gününe inanmayan her büyüklük taslayandan, benim de Rabbim, sizin de Rabbinize sığınırım” dedi."},{"n":28,"t":"“Siz bir adamı, ‘Rabbim Allah`tır diyor` diye öldürecek misiniz? Halbuki o, Rabbinizden size apaçık mucizeler getirmiştir. Eğer o yalancı ise yalanı kendisinedir. Eğer doğru söylüyorsa, sizi tehdit ettiği azabın bir kısmı olsun gelip size çatar. Şüphesiz Allah, haddi aşan ve yalancı kimseyi doğru yola eriştirmez.”"},{"n":29,"t":"“Ey kavmim! Bugün yeryüzüne hâkim kimseler olarak hükümranlık sizindir. Ama Allah`ın azabı bize gelip çatarsa, kim bize yardım edebilir?” Firavun, “Ben size kendi görüşümü söylüyorum ve yine size ancak doğru yolu gösteriyorum” dedi."},{"n":30,"t":"“Ey kavmim! Doğrusu ben sizin için, Nûh kavminin, ‘Âd, Semûd ve onlardan sonra gelenlerin durumu gibi toplulukların başlarına gelen bir sonuçtan korkuyorum. Allah, kullarına bir zulüm dileyecek değildir.”"},{"n":31,"t":"“Ey kavmim! Doğrusu ben sizin için, Nûh kavminin, ‘Âd, Semûd ve onlardan sonra gelenlerin durumu gibi toplulukların başlarına gelen bir sonuçtan korkuyorum. Allah, kullarına bir zulüm dileyecek değildir.”"},{"n":"32-33","t":"“Ey kavmim! Gerçekten sizin için o bağırışıp çağırışma gününden, arkanıza dönüp kaçacağınız günden korkuyorum. Sizi Allah`tan kurtaracak kimse yoktur. Allah kimi saptırırsa, artık onu doğru yola iletecek de yoktur.”"},{"n":34,"t":"Andolsun ki daha önce de Yûsuf size açık deliller getirmişti. Siz onun getirdiklerinden de şüpheye düşmüştünüz. Yûsuf ölünce, “Allah ondan sonra bize asla bir peygamber göndermeyecek” demiştiniz. Allah aşırı giden, çok şüpheci olanları işte böyle saptırır."},{"n":35,"t":"Onlar, kendilerine gelmiş hiçbir delil olmadan Allah`ın âyetleri hakkında tartışırlar. Bu, Allah katında da inananlar katında da büyük nefrete sebep olur. Allah, kibirli her zorbanın kalbini böyle mühürler."},{"n":36,"t":"“Ey Hâmân! Bana bir kule yap. Belki yolları bulabilirim.”"},{"n":37,"t":"“Göklerin yollarını. Böylece Mûsâ`nın tanrısını görürüm! Ben, Mûsâ`nın kesinlikle yalancı olduğunu sanıyorum” dedi. İşte Firavun`a, yaptığı kötülük süslü gösterildi ve doğru yoldan alıkonuldu. Firavun`un tuzağı tamamen boşa çıktı."},{"n":38,"t":"O mümin kişi, “Ey kavmim! Siz bana uyunuz, sizi doğru yola götüreceğim” dedi."},{"n":39,"t":"“Ey kavmim! Şüphesiz bu dünya hayatı geçici bir eğlencedir; ama âhiret, gerçekten kalınacak yurttur.”"},{"n":40,"t":"“Kim bir kötülük işlerse, ona denk bir ceza görür. Kadın veya erkeklerden kim mümin olarak yararlı bir iş yaparsa, işte onlar cennete girecekler; orada onlara hesapsız rızık verilecektir.”"},{"n":41,"t":"“Ey kavmim! Nedir bu hal? Ben sizi kurtuluşa çağırıyorum; siz beni ateşe çağırıyorsunuz.”"},{"n":42,"t":"“Siz beni Allah`ı inkâr etmeye ve hiç bilmediğim nesneleri O`na ortak koşmaya çağırıyorsunuz; ben ise sizi, her şeye gücü yeten ve çok bağışlayan Allah`a çağırıyorum.”"},{"n":43,"t":"“Gerçek şu ki, sizin beni çağırdığınız şeyin dünya ve âhirette çağrıya değer bir tarafı yoktur. Dönüşümüz Allah`adır; aşırı gidenler de ateş ehlinin kendileridir.”"},{"n":44,"t":"“Size söylediklerimin doğruluğunu yakında öğreneceksiniz. Ben işimi Allah`a bırakıyorum. Şüphesiz Allah, kullarının yaptığı her şeyi görmektedir.”"},{"n":45,"t":"Nihayet Allah bu zatı, onların kurdukları tuzakların kötülüklerinden korudu. Firavun`un ailesini ise kötü azap kuşatıverdi."},{"n":46,"t":"Onlar sabah-akşam o ateşe sokulurlar. Kıyametin kopacağı günde kendilerine, “Firavun ailesini en çetinine sokunuz” denilecektir."},{"n":47,"t":"Şimdi ateşin birazını bizden savabilir misiniz?” diyecekler."},{"n":48,"t":"Büyüklük taslayanlar, “Hepimiz ateşin içindeyiz. Şüphesiz ki Allah, kulları arasında hüküm vermiştir” diyecekler."},{"n":49,"t":"Ateştekiler, cehennemin bekçilerine, “Rabbinize yalvarın da, bizden bir gün olsun azabı hafifletsin!” diyecekler."},{"n":50,"t":"Bekçiler, “Peygamberleriniz size apaçık deliller getirmediler mi?” diyecekler. Onlar da, “Getirdiler” cevabını vereceklerdir. Bunun üzerine bekçiler de, “O halde kendiniz yalvarınız” diyecekler. Halbuki kâfirlerin yalvarması boşunadır."},{"n":51,"t":"Şüphesiz, peygamberlerimize ve iman edenlere, hem dünya hayatında, hem şâhitlerin şâhitlik edeceği günde yardım ederiz."},{"n":52,"t":"O gün zâlimlere, özür dilemeleri hiçbir fayda sağlamaz. Onlar için hem lanet, hem de kötü barınak vardır."},{"n":"53-54","t":"Şüphesiz ki biz, Mûsâ`ya doğru yolu gösteren rehberi verdik. İsrâiloğulları`nı da doğru yolu gösterici ve akıl sahiplerini uyarıcı olarak Kitab`a mirasçı kıldık."},{"n":55,"t":"O halde sabret! Çünkü Allah`ın vaadi mutlaka gerçekleşecektir. Günahının bağışlanmasını iste. Akşam-sabah Rabbini övgü ile an!."},{"n":56,"t":"Kendilerine gelmiş herhangi bir delil olmadan Allah`ın âyetleri konusunda mücadele edenlerin gönüllerinde, asla ulaşamayacakları büyüklenme arzusundan başka bir şey yoktur. Artık sen, Allah`a sığın! Şüphesiz O, her şeyi işitir; görür."},{"n":57,"t":"Andolsun ki gökleri ve yeri yaratmak, insanları yaratmaktan daha büyük bir iştir. Fakat insanların çoğu bunu bilmezler."},{"n":58,"t":"Görmeyen ile gören, inanıp iyi iş yapan ile kötülük yapan bir olmaz. Ne kadar az düşünüyorsunuz!"},{"n":59,"t":"Şüphesiz kıyamet günü gelecektir, bunda hiç şüphe yoktur. Fakat insanların çoğu buna inanmazlar."},{"n":60,"t":"Rabbiniz, “Bana dua ediniz, duanıza cevap vereyim. Bana kulluk etmeyi gururlarına yediremeyenler, alçalmış olarak cehenneme gireceklerdir” buyurmuştur."},{"n":61,"t":"Dinlenesiniz diye geceyi, görmeniz için de gündüzü yaratan Allah`tır. Şüphesiz ki Allah, insanlara karşı lütufkârdır. Fakat insanların çoğu şükretmezler."},{"n":62,"t":"İşte, sizin Rabbiniz olan Allah budur. O, her şeyin yaratıcısıdır. O`ndan başka tanrı yoktur. Nasıl döndürülüyorsunuz!"},{"n":63,"t":"Allah`ın âyetlerini inkâr edenler de işte böyle döndürülürler."},{"n":64,"t":"Yeri sizin için yerleşim alanı, göğü de kubbe yapan, size şekil verip şeklinizi güzel yapan ve sizi temiz besinlerle rızıklandıran, Allah`tır. İşte, Rabbiniz olan Allah budur. Âlemlerin Rabbi olan Allah, ne yücedir!"},{"n":65,"t":"O, diridir. O`ndan başka tanrı yoktur. O halde dinde ihlaslı kişiler olarak O`na kulluk ediniz. Her türlü övgü, âlemlerin Rabbi Allah`a aittir."},{"n":66,"t":"“Rabbimden bana açık deliller geldi. Sizin Allah`tan başka taptıklarınıza kulluk etmem bana kesinlikle yasaklandı. Ben, âlemlerin Rabbine teslim olmakla emrolundum.”"},{"n":67,"t":"Sizi topraktan, sonra meniden, sonra alakadan/yapışkan-döllenmiş yumurtadan yaratan O`dur. Sonra dünyaya sizi bir bebek olarak çıkarıyor. Sonra ergenlik çağına eresiniz, sonra da hayatınızı sürdürüp yaşlanasınız diye sizi yaşatıyor. İçinizden bir kısmı daha önce vefat ettiriliyor. Bütün bunlar, belirlenen bir süreye ulaşmanız ve aklınızı kullanasınız diyedir."},{"n":68,"t":"Yaşatan ve öldüren O`dur. Bir işin olmasını istediği zaman, ona sadece, “ol” der ve o hemen oluşmaya başlar."},{"n":69,"t":"Allah`ın âyetleri hakkında tartışanların nasıl saptırıldıklarını görmez misin?"},{"n":70,"t":"Onlar bu kitabı ve peygamberlerimize gönderdiklerimizi yalanlayanlardır. İleride anlayacaklardır."},{"n":"71-72","t":"Boyunlarında halkalar ve zincirlerle, kaynar suyun içine sürükleneceklerdir; sonra da ateşte yakılacaklardır."},{"n":73,"t":"“Ortak koştuklarınız nerede?”"},{"n":74,"t":"“Allah`tan başka taptıklarınız nerede?” Onlar da, “Bizden uzaklaştılar, zaten biz önceleri hiçbir şeye tapmıyorduk” diyecekler. İşte Allah, kâfirleri böyle şaşırtır."},{"n":75,"t":"Bu durum, sizin yeryüzünde haksız yere şımarıp taşkınlık yapmanızdan dolayıdır."},{"n":76,"t":"“Süreli olarak kalacağınız cehennemin kapılarından girin! Büyüklenenlerin konaklama yeri ne kötüdür!”"},{"n":77,"t":"Sıkıntılara karşı sabırlı ol; çünkü Allah`ın vaadi mutlaka gerçekleşecektir. Şu kâfirlere hazırladığımız cezayı sana ister gösterelim, ister seni ondan önce öldürelim, onlar bize döndürüleceklerdir."},{"n":78,"t":"Andolsun, senden önce birçok peygamber gönderdik; sana onların kimini anlattık, kimini anlatmadık; hiçbir peygamber, Allah`ın izni olmadan bir âyet getiremez. Allah`ın buyruğu gelince iş gerçekten biter. İşte o zaman, boşa uğraşanlar zarar ederler."},{"n":79,"t":"Allah kimine binesiniz, kimini yiyesiniz diye sizin için hayvanları yaratandır."},{"n":80,"t":"Onlarda sizin için daha nice faydalar vardır ve gönüllerinizde duyduğunuz önemli ihtiyaçlarınıza onlarla ulaşırsınız. Onların ve gemilerin üstünde taşınırsınız."},{"n":81,"t":"Allah size âyetlerini gösteriyor. Şimdi Allah`ın âyetlerinden hangisini inkâr edersiniz?"},{"n":82,"t":"Yeryüzünde dolaşıp, kendilerinden öncekilerin sonlarının nasıl olduğuna bir bakmazlar mı? Onlar gerek güç, gerekse yeryüzünde bıraktıkları eserler bakımından bunlardan daha kuvvetli idiler. Buna rağmen, kazanmış oldukları kendilerinden hiçbir şeyi savamamıştı."},{"n":83,"t":"Peygamberleri onlara apaçık deliller getirdiklerinde, kendi bildikleri ile şımarmışlar ve alay ettikleri azap kendilerini çepeçevre kuşatmıştı."},{"n":84,"t":"Azabımızı gördüklerinde, “Tek olan Allah`a inandık. Ortak koştuklarımızı inkâr ettik” demişlerdi."},{"n":85,"t":"Ancak, azabımızı görünce, inanmalarının kendilerine hiçbir faydası olmamıştı. İşte, öteden beri Allah`ın kullarına uyguladığı yasası budur. O durumda inkâr edenler kaybedeceklerdir."}],[{"n":1,"t":"Hâ, mîm."},{"n":2,"t":"Bu kitap, rahmet ve merhametin kaynağı olan Allah`ın katından indirilmiştir."},{"n":3,"t":"Bilen bir toplum için âyetleri açıklanmış, Arapça okunan bir kitaptır."},{"n":4,"t":"Müjdeleyici ve uyarıcı olarak gönderilmiştir. Buna rağmen onların çoğu yüz çevirip dinlemezler."},{"n":5,"t":"Onlar, “Bizi çağırdığın şeye karşılık kalplerimiz perdelenmiştir. Kulaklarımızda bir ağırlık ve bizimle senin aranda da bir perde vardır. Sen istediğini yap, biz de istediğimizi yapacağız” dediler."},{"n":6,"t":"“Ben ancak sizin gibi bir insanım. Tanrınızın tek bir tanrı olduğu bana vahyediliyor. Artık O`na yöneliniz. O`ndan af dileyiniz. Ortak koşanların vay haline!”"},{"n":7,"t":"Onlar zekâtı vermezler ve âhireti de inkâr ederler."},{"n":8,"t":"Şüphesiz iman edip yararlı iş yapanlar için tükenmeyen bir ödül vardır."},{"n":9,"t":"“Siz, yerküreyi iki evrede yaratmış olan Allah`ı gerçekten inkâr mı ediyorsunuz? O`na ortaklar mı koşuyorsunuz? O, âlemlerin Rabbidir.”"},{"n":10,"t":"“Yeryüzünde sabit dağlar yerleştirdi. Orada bereketler yarattı ve orada dört evrede isteyenler/ihtiyaç sahibi olanlar için fark gözetmeden gıdalar takdir etti.”"},{"n":11,"t":"“Sonra duman halinde olan göğe yöneldi, göğe ve yerküreye, “İsteyerek veya istemeyerek, geliniz!” dedi. İkisi de, “İsteyerek geldik” dediler."},{"n":12,"t":"Böylece onları, iki evrede yedi gök olarak yarattı ve her göğe görevini vahyetti/öğretti. Biz, yakın/dünya göğünü kandillerle/ışık saçan cisimlerle donattık, bozulmaktan da koruduk. İşte bu, gücü sonsuz ve her şeyi bilen Allah`ın takdiridir."},{"n":13,"t":"“Ben, ‘Âd ve Semûd toplumlarını helâk eden yıldırıma benzer bir yıldırımla sizi uyarıyorum.”"},{"n":14,"t":"O vakit onlara, önlerinden ve arkalarından peygamberler gelmiş, “Allah`tan başkasına kulluk etmeyiniz” demişlerdi. Onlar da, “Eğer Rabbimiz dileseydi bize melekler gönderirdi. Biz, sizinle gönderilenleri inkâr ediyoruz” demişlerdi."},{"n":15,"t":"Âd kavmi, yeryüzünde haksız yere büyüklük tasladılar ve “Bizden daha kuvvetli kim vardır?” dediler. Kendilerini yaratan Allah`ın onlardan daha kuvvetli olduğunu görmediler mi? Onlar âyetlerimizi inkâr ediyorlardı."},{"n":16,"t":"Bundan dolayı biz de, onlara dünya hayatında rezillik azabını tattırmak için o uğursuz günlerde, üzerlerine dondurucu bir rüzgâr gönderdik. Âhiret azabı ise daha çok perişan edicidir. Onlara hiç yardım da edilmeyecektir."},{"n":17,"t":"Semûd kavmine gelince, onlara yol gösterdik, fakat onlar körlüğü, doğru yolu bulmaya tercih ettiler. Böylece yaptıkları yüzünden alçaltıcı azap yıldırımı onları yakaladı."},{"n":18,"t":"İnananları ve Allah`tan sakınanları kurtardık."},{"n":19,"t":"Allah`ın düşmanları, ateşe sürülmek üzere toplandıkları gün, hepsi bir araya getirilirler."},{"n":20,"t":"Oraya geldiklerinde kulakları, gözleri ve derileri, yaptıkları amellere karşı onların aleyhine şahitlik ederler."},{"n":21,"t":"Onlar derilerine, “Niçin aleyhimize tanıklık ediyorsunuz?” diyecekler. Derileri de, “Her şeyi konuşturan Allah bizi de konuşturdu. Sizi ilk defa yaratan O`dur ve yalnız O`na döndürüleceksiniz” diyecekler."},{"n":22,"t":"Siz ne kulaklarınızın, ne gözlerinizin, ne de derilerinizin aleyhinize şahitlik etmesinden sakınıyordunuz. Yaptıklarınızdan çoğunu Allah`ın bilemeyeceğini sanıyordunuz."},{"n":23,"t":"İşte sizi, Rabbiniz hakkındaki bu yanlış düşünceniz helâk etti de, bugün artık kaybedenlerden oldunuz."},{"n":24,"t":"Eğer dayanabilirlerse yerleri ateştir. Eğer Allah`ı hoşnut etmek isterlerse, memnun edilecek değillerdir."},{"n":25,"t":"Onlara birtakım arkadaşlar hazırlarız da onlar, bunların yaptıkları ve yapacakları bütün işleri kendilerine güzel gösterirler. Kendilerinden önce gelip geçmiş olan cinler ve insanlar için uygulanan ceza, onlara da gerekli olmuştur. Şüphesiz bunlar tamamen kaybeden bir topluluktur."},{"n":26,"t":"İnkâr edenler, “Bu Kur`ân`ı dinlemeyiniz. Okunurken gürültü çıkarınız ki duyulmasını engelleyesiniz” dediler."},{"n":27,"t":"O inkâr edenlere şiddetli bir azap tattıracağız ve onları, yaptıklarının en kötüsüyle cezalandıracağız."},{"n":28,"t":"İşte, Allah düşmanlarının cezası budur. Âyetlerimizi inkâr etmiş olmalarının cezası olarak, onlar süreli olarak ateşte kalacaklardır."},{"n":29,"t":"İnkâr edenler, “Ey Rabbimiz! Cinlerden ve insanlardan bizi saptıranları bize göster. Onları ayaklarımızın altına alalım da en aşağılıklardan olsunlar” diyecekler."},{"n":30,"t":"“Korkmayınız ve üzülmeyiniz, size vaad olunan cennetle sevininiz!”"},{"n":"31-32","t":"“Biz, dünya hayatında da, âhirette de sizin dostlarınızız. Çok bağışlayan ve çok merhametli Allah`ın bir ikramı olarak, orada sizin canınızın çektiği ve istediğiniz her şey vardır.”"},{"n":33,"t":"Allah`a çağıran, yararlı iş yapan ve “Ben, kesinlikle Müslümanlardanım” diyenden daha güzel sözlü kim vardır?"},{"n":34,"t":"İyilikle kötülük bir olmaz. Sen, en iyi olanla karşılık ver! Bir de bakarsın ki seninle arasında düşmanlık bulunan kişi sanki candan bir dostmuş gibi olur."},{"n":35,"t":"Buna ancak sabredenler kavuşturulur; buna ancak büyük nasibi olan kimse kavuşturulur."},{"n":36,"t":"Şeytan senin içine bir vesvese düşürürse hemen Allah`a sığın! Çünkü O, her şeyi duyandır; bilendir."},{"n":37,"t":"Gece, gündüz, güneş ve ay, Allah`ın âyetlerindendir. Güneşe ve aya secde etmeyiniz. Eğer yalnız O`na kulluk edecekseniz onları da yaratan Allah`a secde ediniz."},{"n":38,"t":"Eğer büyüklenirlerse, bil ki Rabbinin katında olanlar hiç bıkmadan gece gündüz O`nu noksan sıfatlardan uzak tutmaktadırlar."},{"n":39,"t":"Kupkuru gördüğün toprağa yağmur yağdırdığımızda titreşip kabarması Allah`ın âyetlerindendir. Yere can veren, kesinlikle ölüleri de diriltecektir. Şüphesiz O`nun her şeye gücü yeter."},{"n":40,"t":"Âyetlerimizin anlamını saptıranlar, kendilerini bizden gizleyemezler. Kıyamet gününde ateşe atılacak olan mı daha iyidir; yoksa güven içinde gelecek olan mı? Dilediğinizi yapınız. Şüphesiz ki Allah, yaptığınız her şeyi görmektedir."},{"n":41,"t":"Kendilerine geldiğinde Kur`ân`ı inkâr edenler de saklanamazlar. Çünkü o Kur`ân eşsiz bir kitaptır."},{"n":42,"t":"Ona ne önünden, ne ardından batıl yaklaşamaz. O, bütün kainatın övdüğü bir hikmet sahibi tarafından peyderpey indirilmiştir."},{"n":43,"t":"Sana söylenenler, senden önceki peygamberlere söylenenlerden başkası değildir. Şüphesiz senin Rabbin, hem affedicidir; hem de acı bir azap sahibidir."},{"n":44,"t":"“O, inananlar için bir yol gösterici ve gönüllerine şifadır. Kâfirlerin kulaklarında ağırlık vardır ve Kur`ân onlara kapalıdır; sanki onlara uzak bir yerden sesleniliyor.”"},{"n":45,"t":"Andolsun biz Mûsâ`ya kitabı verdik, onda da ayrılığa düşüldü. Eğer Rabbinden, önceden verilmiş bir söz olmasaydı, aralarında hüküm verilecekti. Onlar Kur`ân hakkında derin bir şüphe içindedirler."},{"n":46,"t":"Kim iyi bir iş yaparsa kendi yararına, kim de kötülük yaparsa kendi zararınadır. Rabbin, kullarına hiçbir haksızlık yapmaz."},{"n":47,"t":"Kıyametin bilgisi, yalnızca Allah`a aittir. Allah`ın bilgisi olmadan ne bir meyve kabuğu çıkar, ne de bir dişi, gebe kalıp doğurur. O gün Allah müşriklere, “Nerede ortaklarım?” diye seslenecek. Onlar da, “Bizden bir tanık olmadığını sana arzederiz” derler."},{"n":48,"t":"Daha önce taptıkları tanrılar uzaklaşıp kaybolacaktır. Sığınacak hiçbir yerleri olmadığını anlayacaklardır."},{"n":49,"t":"İnsan, iyiliği istemekten usanmaz. Fakat ona bir kötülük dokunursa, bir de bakarsın ümitsizliğe düşer."},{"n":50,"t":"Başına gelen sıkıntıdan sonra, katımızdan ona bir rahmet tattırdığımızda, “Bu benim hakkımdır. Ben kıyametin kopacağını sanmıyorum. Rabbime döndürülmüş olsam bile elbette O`nun katında benim için daha güzel şeyler vardır” der. Biz, böylesi inkârcılara kesinlikle yaptıklarını bildireceğiz. Onlara ağır bir azap tattıracağız."},{"n":51,"t":"İnsana bir nimet verdiğimizde nankörlük edip yüz çevirir; fakat ona bir kötülük dokununca da yalvarıp durur."},{"n":52,"t":"“İnkâr ettiğiniz Kur`ân, gerçekten Allah`tan ise, halinizin ne olacağını hiç düşündünüz mü? Doğrudan ayrılıp uzaklaşandan daha sapık kim olabilir?”"},{"n":53,"t":"Onlara dış âlemdeki ve kendi içlerindeki âyetlerimizi/doğa kanunlarını göstereceğiz. Böylece Kur`ân`ın gerçek/hak olduğunu anlayacaklardır. “Rabbinin her şeye tanık olması onlara yetmiyor mu?”"},{"n":54,"t":"Dikkat ediniz, onlar Rabblerine kavuşacakları konusunda şüphe içerisindedirler. İyi biliniz ki, Allah, her şeyi çepeçevre kuşatmıştır."}],[{"n":"1-2","t":"Hâ, mîm. ‘Ayn, sîn, kâf."},{"n":3,"t":"Kudret ve hikmet sahibi olan Allah, sana ve senden öncekilere şöyle vahyediyor:"},{"n":4,"t":"“Göklerde ve yerde olan her şey O`nundur. O, yücedir; uludur.”"},{"n":5,"t":"O`nun ululuğu karşısında gökler neredeyse çatlayacaktır. Melekler, Rabblerini övgü ile tesbih ederler ve yeryüzünde bulunanlar için af dilerler. Çünkü Allah çok bağışlayandır; çok merhamet edendir."},{"n":6,"t":"Allah`tan başka dost edinenleri Allah daima gözetlemektedir. Sen onlara vekil değilsin."},{"n":7,"t":"İşte böylece şehirlerin anası Mekke ve çevresindekileri uyarman ve gerçekleşmesinde şüphe bulunmayan toplanma günü hakkında korkutman için sana Arapça bir Kur`ân indirdik. O gün insanların bir kısmı cennette, bir kısmı da alevli ateşte olacaktır."},{"n":8,"t":"Eğer Allah dileseydi, onları bir tek inanç etrafında toplardı. Fakat O, dileyenleri rahmetinin içine alır. Zâlimler için hiçbir koruyucu ve yardımcı yoktur."},{"n":9,"t":"Yoksa O`ndan başka dostlar mı edindiler? Oysa gerçek dost Allah`tır. O, ölüleri diriltir. O`nun her şeye gücü yeter."},{"n":10,"t":"Ayrılığa düştüğünüz herhangi bir konuda hüküm vermek Allah`a aittir. İşte bu Allah, benim Rabbimdir. O`na dayandım ve O`na yöneldim."},{"n":11,"t":"O, göklerin ve yerin yoktan yaratıcısıdır. Size kendi türünüzden eşler, hayvanlara da kendi türlerinden eşler yaratmıştır. Bu suretle çoğalmanızı sağlamıştır. O`nun benzeri hiçbir varlık yoktur. O her şeyi işitendir; her şeyi görendir."},{"n":12,"t":"Göklerin ve yerin anahtarları/yönetim sistemi O`nundur. Dilediğine rızkı bol verir, dilediğine de kısar. O her şeyi bilendir."},{"n":13,"t":"Allah Nûh`a, sana, İbrâhim`e, Mûsâ`ya ve İsâ`ya, “Dine dosdoğru uyunuz, dinde ayrılığa düşmeyiniz” diye vasiyet ettiğimiz dini size yasallaştırdı. Senin kendilerini çağırdığın bu esas, müşriklere ağır geldi. Allah dileyenleri kendine seçer, kendisine yönelenleri de doğru yola iletir."},{"n":14,"t":"Kendilerine ilim geldikten sonra ihtilafa düşmeleri, sırf aralarındaki kıskançlıktan dolayıdır. Eğer Rabbin tarafından belirli bir süreye kadar önceden verilmiş bir söz olmasaydı, kesinlikle aralarında hüküm verilecekti. Onlardan sonra kendilerine kitap verilenler de kesinlikle o din hakkında aşırı şüphe içerisindedirler."},{"n":15,"t":"“Allah`ın indirdiği kitaba inandım. Aranızda adeletli davranmakla emrolundum. Allah bizim de sizin de Rabbinizdir. Bizim yaptıklarımız bize, sizin yaptıklarınız da sizedir. Aramızda tartışmaya gerek yoktur. Allah hepimizi bir araya getirecektir. Dönüş yalnız O`nadır.”"},{"n":16,"t":"Allah`ın çağrısını kabul ettikten sonra hâlâ Allah hakkında tartışanlara gelince, onların delilleri ve itirazları Rabbleri katında geçersizdir. Allah`ın gazabı onların üzerine çökecektir ve onlar için şiddetli bir azap vardır."},{"n":17,"t":"Gerçeği taşıyan kitabı ve adalet ölçüsünü hak olarak indiren Allah`tır. Ne biliyorsun, belki de kıyamet saati yakındır!"},{"n":18,"t":"Kıyamete inanmayanlar, onun acele gelmesini istiyorlar. İnananlar ise onun gelmesinden korkarlar ve onun gerçek olduğunu bilirler. İyi biliniz ki, kıyamet hakkında şüpheye düşenler, büyük bir yanılgı içindedirler."},{"n":19,"t":"Allah, kullarına çok lütufkârdır, dilediğini rızıklandırır. O, güçlüdür; her şeyin üstesinden gelir."},{"n":20,"t":"Kim âhiret sevabını isterse, onun sevabını arttırırız. Kim de dünya nimetini isterse, ona da onu veririz. Artık onun âhiret sevabından hiçbir payı olmaz."},{"n":21,"t":"Yoksa onların, Allah`ın izin vermediği bir dini kendilerine yasallaştıran ortakları mı var? Eğer erteleme sözü olmasaydı, derhal aralarında hüküm verilirdi. Şüphesiz, zâlimlere can yakıcı bir azap vardır."},{"n":22,"t":"Yaptıkları şeyler başlarına gelirken, zâlimlerin korkudan titrediklerini göreceksin. İman edip iyi işler yapanlar da, cennet bahçelerinde olacaklardır. Rabblerinin yanında onlara diledikleri her şey vardır. İşte, büyük lütuf budur."},{"n":23,"t":"“Ben, buna karşılık sizden bir karşılık istemiyorum; ancak, Allah`a yaklaştıran sevgiyi istiyorum.” Kim bir iyilik yaparsa onun iyiliğini arttırırız. Şüphesiz Allah affedendir; iyiliğe karşılık verendir."},{"n":24,"t":"Yoksa onlar, senin için, “Allah`a karşı yalan uydurdu” mu diyorlar? Allah dilerse senin kalbini de mühürler. Allah bâtılı silip süpürür ve hakkı sözleriyle ortaya koyar. Şüphesiz Allah sinelerde olanları bilendir."},{"n":25,"t":"Allah, kullarının tövbesini kabul eden, kötülüklerini affeden ve ne yaptığınızı bilendir."},{"n":26,"t":"İnanıp iyi amel yapanların duasını kabul eder ve onlara kendi lütfundan fazlasıyla verir. Kâfirler için şiddetli bir azap vardır."},{"n":27,"t":"Allah, kullarına rızkı bol bol verseydi, yeryüzünde azarlardı. Fakat Allah rızkı dilediği ölçüde indirir. Allah, kullarını çok iyi bilir ve görür."},{"n":28,"t":"İnsanlar ümitsizliğe düştükten sonra yağmuru yağdıran ve rahmetini yayan O`dur. Kullarının işlerini düzenleyen ve övgüye lâyık olan da O`dur."},{"n":29,"t":"Gökleri ve yeri yaratıp oralarda canlıları yayması O`nun varlığının delillerindendir. Dilediği zaman onları toplamaya da gücü yeter."},{"n":30,"t":"Başınıza gelecek her felaket, kendi yapıp ettiklerinizin bir ürünüdür. Bununla beraber Allah pek çoğunu bağışlıyor."},{"n":31,"t":"Siz O`nu yeryüzünde âciz bırakamazsınız. Allah`tan başka bir dostunuz ve yardımcınız da yoktur."},{"n":32,"t":"Denizde dağlar gibi akıp giden gemiler de O`nun varlığının delillerindendir."},{"n":33,"t":"Dilerse rüzgârı durdurur; o zaman denizin üstünde hareketsiz kalıverirler. Bunda, şüphesiz çok çok sabreden, gönülden şükreden herkes için mesajlar vardır."},{"n":34,"t":"Yahut yaptıkları yüzünden onları helâk eder, birçoğunu da bağışlar."},{"n":35,"t":"Böylece âyetlerimiz üzerinde tartışanlar, kendilerine kaçacak bir yer olmadığını bilsinler."},{"n":36,"t":"Size verilen her şey, geçici dünya malıdır. Allah katında bulunanlar ise daha iyi ve daha kalıcıdır. Bu ödül, iman eden ve Rabblerine dayanıp güvenenler içindir."},{"n":37,"t":"Onlar, büyük günahlardan ve hayâsızlıktan kaçınırlar; kızdıklarında da hataları bağışlarlar."},{"n":38,"t":"Onlar, Rabblerinin çağrısına uyarlar ve namazı dosdoğru kılarlar. İşlerini birbirlerine danışarak yaparlar ve kendilerine verdiğimiz rızıklardan hayırda harcarlar."},{"n":39,"t":"Kendilerine bir haksızlık yapıldığında yardımlaşarak üstesinden gelirler."},{"n":40,"t":"Bir kötülüğün cezası, ona denk bir cezadır. Kim affeder ve barışı sağlarsa, onun ödülü Allah`a aittir. Doğrusu Allah zâlimleri sevmez."},{"n":41,"t":"Kim zulme uğradıktan sonra hakkını alırsa artık onların aleyhlerine bir yol yoktur."},{"n":42,"t":"Ancak, insanlara zulmedenlere ve yeryüzünde haksız yere taşkınlık edenlere ceza vardır. İşte, acıklı azap bunlaradır."},{"n":43,"t":"Kim sabreder ve affederse, şüphesiz bu hareketi, yapılmaya değer işlerdendir."},{"n":44,"t":"İşte, Allah kimi saptırırsa, artık onun hiçbir koruyucusu yoktur. Azabı gördüklerinde zâlimlerin, “Geri dönüşün hiçbir yolu yok mu?” dediklerini görürsün."},{"n":45,"t":"“İşte asıl ziyana uğrayanlar, kıyamet günü kendilerini ve ailelerini ziyana sokanlar bunlardır.” Biliniz ki, zâlimler kesinlikle süreli bir azap içerisindedirler!"},{"n":46,"t":"Onların Allah`tan başka kendilerine yardım edecek hiçbir dostları olmayacaktır. Allah kimi saptırırsa, artık onun kurtuluşa çıkan bir yolu yoktur."},{"n":47,"t":"Allah`tan geri çevrilmesi imkansız bir gün gelmezden önce, Rabbinize uyunuz! Çünkü o gün, hiçbiriniz sığınacak yer bulamazsınız, itiraz da edemezsiniz."},{"n":48,"t":"Eğer yüz çevirirlerse, bilesin ki biz seni onların üzerine bekçi göndermedik. Sana düşen sadece tebliğ etmektir. Biz insana katımızdan bir rahmet tattırdığımız zaman ona sevinir; ama elleriyle yaptıkları yüzünden başlarına bir kötülük gelirse, işte o zaman insan pek nankördür."},{"n":49,"t":"Göklerin ve yerin mülkü Allah`ındır. Dilediğini yaratır, dilediğine kız çocukları, dilediğine de erkek çocukları bahşeder."},{"n":50,"t":"Yahut, çocukları hem erkek hem de kız olmak üzere karışık verir. Dilediğini de kısır yapar. O, her şeyi bilendir; her şeye gücü yetendir."},{"n":51,"t":"Allah, bir insanla ancak ilham yoluyla, yahut perde arkasından konuşur, yahut izniyle dilediğini vahyedecek bir elçi/Cebrail gönderir. Allah yücedir; hikmet sahibidir."},{"n":52,"t":"İşte sana da böyle, emrimizden bir ruh/can vahyettik. Sen kitap nedir, iman nedir bilmezdin. Fakat biz Kur`ân`ı, kullarımızdan dilediğimizi doğru yola ilettiğimiz bir nur yaptık. Şüphesiz sen doğru yola götürüyorsun."},{"n":53,"t":"Göklerde ve yerde bulunan her şeyin sahibi Allah`ın yoluna. İyi bil ki bütün işler, sonunda Allah`a varır."}],[{"n":1,"t":"Hâ, mîm."},{"n":2,"t":"Apaçık kitaba andolsun."},{"n":3,"t":"Biz, anlayasınız diye onu Arapça bir Kur`ân yaptık."},{"n":4,"t":"O, katımızda bulunan bütün vahiylerin kaynağından çıkmıştır. O, gerçekten yücedir; hikmet doludur."},{"n":5,"t":"Siz haddi aşan kimseler oldunuz diye, sizi Kur`ân ile uyarmaktan vaz mı geçelim?"},{"n":6,"t":"Daha önceki milletlere nice peygamberler göndermiştik."},{"n":7,"t":"Onlar, kendilerine gelen her peygamberi mutlaka alaya alırlardı."},{"n":8,"t":"Biz, bunlardan daha kuvvetli olanları da helâk ettik. Nitekim öncekilerde örneği geçmiştir."},{"n":9,"t":"Onlara, “Gökleri ve yeri kim yarattı?” diye soracak olursan; “Kesinlikle onları her şeye gücü yeten ve her şeyi bilen Allah yarattı” diye cevap vereceklerdir."},{"n":10,"t":"Allah, yeri size beşik yapmış ve doğru gidesiniz diye yeryüzünde size yollar yaratmıştır."},{"n":11,"t":"Gökten gerekli ölçüde tekrar tekrar suyu indiren Allah`tır. Biz o su ile ölü topraklara hayat veririz. İşte siz de böyle çıkarılacaksınız."},{"n":12,"t":"Bütün çiftleri O yaratmıştır; gemileri ve hayvanları binmeniz için hizmetinize vermiştir."},{"n":13,"t":"Onların sırtına kurulasınız ve üzerlerine yerleştiğinizde, Rabbinizin nimetini hatırlayarak şöyle diyesiniz diye, “Bunları bizim emrimize veren Allah, her türlü eksiklikten uzaktır. Aksi takdirde biz bunları emrimizin altına alamazdık.”"},{"n":14,"t":"“Şüphesiz biz Rabbimize döneceğiz.”"},{"n":15,"t":"Ama onlar, kullarından bir kısmını, O`nun bir parçası saydılar. Gerçekten insan apaçık bir nankördür."},{"n":16,"t":"Yoksa Allah, yarattıklarından kızları kendisine aldı da oğulları size mi ayırdı?"},{"n":17,"t":"Oysa, Rahmân`a yakıştırdıkları kızların müjdesi onlardan birine verilince, yüzü simsiyah kesilip içini üzüntü kaplar."},{"n":18,"t":"“Süs içinde büyüyen ve savaşmasını bilmeyen mi!” der."},{"n":19,"t":"Onlar, Rahmân`ın kulları olan meleklerin dişiler olduklarını kabul ettiler. Meleklerin yaratılışına tanık mı oldular? Onların bu tanıklıkları yazılacak ve bundan sorulacaklardır."},{"n":20,"t":"“Eğer Rahmân dileseydi putlara tapmazdık” dediler. Bu bilgisizce bir sözdür. Onlar sadece yalan söylemektedirler."},{"n":21,"t":"Yoksa onlara, Kur`ân`dan önce bir kitap verdik de onlar ona mı dayanıyorlar?"},{"n":22,"t":"Hayır! Sadece, biz babalarımızı bir din üzerinde bulduk; biz de onların izinden gidiyoruz, derler."},{"n":23,"t":"Senden önce, peygamber gönderdiğimiz bütün beldelerin şımarıkları da aynı şekilde, “Şüphesiz biz babalarımızı bir yol üzerinde bulduk, biz de onların izlerini takip ediyoruz” demişlerdi."},{"n":24,"t":"Peygamberler, “Size, babalarınızı üzerinde bulduğunuz yoldan daha doğrusunu getirmiş olsak da mı?” diye sormuştu. Onlar da, “Şüphesiz biz, seninle gönderileni kesinlikle inkâr ediyoruz” diye cevap vermişlerdi."},{"n":25,"t":"Biz de bundan dolayı onları cezalandırmıştık. Yalancıların sonlarının nasıl olduğuna bir bak!"},{"n":26,"t":"“Ben sizin taptıklarınızdan uzağım. Ben yalnız beni yokken yaratana ibadet ederim. Çünkü O, bana doğru yolu gösterecektir.”"},{"n":27,"t":"“Ben sizin taptıklarınızdan uzağım. Ben yalnız beni yokken yaratana ibadet ederim. Çünkü O, bana doğru yolu gösterecektir.”"},{"n":28,"t":"Onun bu sözünü, ardından geleceklere sürekli kalacak bir ilke olarak bıraktık ki, insanlar Rabblerine dönsünler."},{"n":29,"t":"Doğrusu ben, bunları ve babalarını, bu gerçek ve onu açıklayan bir peygamber gelene kadar geçindirdim."},{"n":30,"t":"Bu gerçek kendilerine geldiğinde, “Bu bir büyüdür. Biz onu reddediyoruz” dediler."},{"n":31,"t":"“Bu Kur`ân, iki şehirden bir büyük adama indirilmeliydi!”"},{"n":32,"t":"Rabbinin rahmetini onlar mı taksim ediyorlar? Biz onların dünya hayatındaki geçimliklerini taksim ettik ve bir kısmının diğerlerine iş gördürebilmesi için, bir kısmını bir kısmından derecelerle üstün kıldık. Rabbinin rahmeti onların biriktirdiklerinden daha iyidir."},{"n":33,"t":"İnsanlar bir tek ümmet haline gelmeyecek olsalardı, Rahmân`ı inkâr edenlerin evlerinin tavanlarını ve merdivenlerini gümüşten yapardık."},{"n":"34-35","t":"Evlerini gümüşten kapılar ve yaslanacakları koltuklarla donatıp süslerdik. Bütün bunlar sadece geçici dünya malıdır. Âhiret ise Rabbin katında muttakiler/ Allah`a saygı duyanlar içindir."},{"n":36,"t":"Kim Rahmân`ın zikrinden/öğüdünden yüz çevirirse, ona bir şeytan salarız; o, onun yoldaşı olur."},{"n":37,"t":"Şüphesiz bu şeytanlar onları doğru yoldan alıkoyarlar. Ama onlar hâlâ kendilerinin doğru yolda olduklarını sanırlar."},{"n":38,"t":"“Keşke benimle senin aranda iki doğu/dünya kadar uzaklık olsaydı. Sen ne kötü bir arkadaşmışsın!”"},{"n":39,"t":"Kendilerine, “Bugün pişmanlığınızın size hiçbir faydası olmayacaktır. Çünkü siz zulmettiniz. Siz azapta da ortaksınız” denilir."},{"n":40,"t":"Manen sağır olanlara sen mi işittireceksin; yahut manevi körleri ve apaçık sapıklıkta olanları doğru yola sen mi ileteceksin?"},{"n":41,"t":"Biz seni onlardan alıp götürsek de yine onlardan intikam alırız."},{"n":42,"t":"Yahut onlara vaad ettiğimiz azabı sana gösteririz. Çünkü bizim onlara gücümüz yeter."},{"n":43,"t":"Sen, sana vahyedilene sımsıkı sarıl! Şüphesiz sen dosdoğru yoldasın."},{"n":44,"t":"Doğrusu Kur`ân, sana ve kavmine bir şereftir. İleride ondan sorumlu tutulacaksınız."},{"n":45,"t":"“Rahmân`dan başka tanrılara tapılmasını emretmiş miyiz?”"},{"n":46,"t":"Andolsun biz, Mûsâ`yı mucizelerimizle Firavun`a ve onun ileri gelen adamlarına göndermiştik de Mûsâ, “Ben âlemlerin Rabbi`nin peygamberiyim” demişti."},{"n":47,"t":"Onlara mucizelerimizi getirince mucizelere gülüvermişlerdi."},{"n":48,"t":"Onlara gösterdiğimiz her mucize diğerinden daha büyüktü. Dönsünler diye onları azaba uğrattık."},{"n":49,"t":"“Ey sihirbaz! Seninle yaptığı sözleşmenin hatırına bizim için Rabbine dua et; çünkü biz artık doğru yola gireceğiz.”"},{"n":50,"t":"Fakat biz onları azaptan kurtarır kurtarmaz, bir de bakarsın ki sözlerinden dönüvermişler."},{"n":51,"t":"“Ey kavmim! Mısır mülkü ve altımdan akıp giden şu ırmaklar benim değil mi? Hâlâ görmüyor musunuz?”"},{"n":52,"t":"“Yoksa ben, kendisi zayıf ve neredeyse söz anlatamayacak durumda bulunan şu adamdan daha üstün değil miyim?”"},{"n":53,"t":"“Ona altın bilezikler verilmeli veya yanında yardımcı melekler gelmeli değil miydi?”"},{"n":54,"t":"Firavun kavmini aldattı; onlar da kendisine boyun eğdiler. Onlar yoldan çıkmış bir kavim idiler."},{"n":55,"t":"Böylece bizi öfkelendirince, onlardan intikam aldık, hepsini suda boğduk."},{"n":56,"t":"Onları geçmişten bir hâtıra ve sonrakiler için bir ders örneği kıldık."},{"n":"57-58","t":"Meryem`in oğlu örnek gösterilince, senin toplumun hemen yaygarayı basarlar ve “Bizim tanrılarımız mı daha iyidir, yoksa o mu?” derler. Tartışmak için bu örneği verirler. Doğrusu onlar çok kavgacı bir toplumdur."},{"n":59,"t":"İsâ, kendisine nimet verdiğimiz ve kendisini İsrâiloğulları`na örnek kıldığımız bir kuldan başka bir şey değildir."},{"n":60,"t":"Eğer dileseydik, sizin yerinizde yeryüzünde melekler yaratırdık."},{"n":61,"t":"Şüphesiz Kur`ân, kıyametin kopacağını bildirir. Kıyamet hakkında hiç şüphe duymayınız. Bana tâbi olunuz. Dosdoğru yol budur."},{"n":62,"t":"Şeytan, sizi alıkoymasın. Şüphesiz o, sizin apaçık düşmanınızdır."},{"n":63,"t":"“Ben size bu hikmeti getirdim ve ayrılığa düştüğünüz şeylerden bir kısmını size açıklamak için geldim. Öyleyse Allah`a saygı duyunuz ve bana itaat ediniz.”"},{"n":64,"t":"“Şüphesiz Allah, benim ve sizin yegane Rabbinizdir. Yalnız O`na kulluk ediniz; doğru yol budur.”"},{"n":65,"t":"Bunun ardından gruplar, yine ayrılığa düştüler. Azabı acıklı günden dolayı vay o zâlimlerin hallerine!"},{"n":66,"t":"Onlar, farkında olmadan kıyamet saatinin kendilerine ansızın gelmesinden başka bir şey beklemiyorlar."},{"n":67,"t":"O gün, Allah`ın emirlerine karşı gelmekten sakınanların dışında, bütün dostlar birbirlerine düşman olacaklardır."},{"n":68,"t":"“Ey kullarım! Bugün size korku yoktur ve siz üzülmeyeceksiniz de.”"},{"n":69,"t":"“Bunlar, âyetlerimize inanan ve Müslüman olan kullarımdır.”"},{"n":70,"t":"“Siz ve eşleriniz, büyük mutluluk içinde cennete giriniz.”"},{"n":71,"t":"Onlara altın tepsiler ve kadehler dolaştırılır. Orada canlarının istediği, gözlerinin hoşlandığı her şey vardır. Siz orada süreli olarak kalacaksınız."},{"n":72,"t":"Sizi yaptıklarınıza karşılık mirasçı kıldığımız cennet, işte budur."},{"n":73,"t":"Orada, yiyeceğiniz çok meyveler vardır."},{"n":74,"t":"Şüphesiz suçlular, cehennem azabında süreli olarak kalacaklardır."},{"n":75,"t":"Azapları hafiflemeyecek ve orada ümitsizlik içinde kalacaklardır."},{"n":76,"t":"Biz onlara zulmetmedik; onlar kendilerine zulmetmişlerdir."},{"n":77,"t":"“Ey Mâlik! Rabbin bizi öldürsün.” Bekçi de, “Siz burada süreli olarak kalacaksınız” diyecektir."},{"n":78,"t":"Andolsun ki biz size hakkı getirdik. Fakat çoğunuz haktan hoşlanmıyordunuz."},{"n":79,"t":"Yoksa müşrikler inkâra karar mı verdiler? Şüphesiz biz de onları cezalandırmaya karar verdik."},{"n":80,"t":"Yoksa onlar, bizim onların sırlarını ve gizli gizli konuşmalarını işitmediğimizi mi sanıyorlar? Doğrusu, yanlarındaki meleklerimiz yaptıklarını yazmaktadırlar."},{"n":81,"t":"“Eğer Rahmân`ın bir çocuğu olsaydı, kulluk edenlerin ilki ben olurdum.”"},{"n":82,"t":"Göklerin ve yerin Rabbi, egemenlik tahtının sahibi olan Allah, onların bu tür nitelendirmelerinden uzaktır."},{"n":83,"t":"Uyarıldıkları güne kavuşuncaya kadar bırak onları; eğlenceye dalsınlar, oynasınlar!"},{"n":84,"t":"Gökte de Tanrı O`dur, yerde de Tanrı O`dur. O`nun her işinde hikmet vardır; her şeyi bilir."},{"n":85,"t":"Göklerin, yerin ve ikisi arasındakilerin mülkiyeti kendisine ait olan Allah en yücedir! Kıyametin bilgisi de O`nun katındadır. Sizler yalnız O`na döndürüleceksiniz."},{"n":86,"t":"Allah`tan başka yalvardıklarının, şefaat etmeye güçleri yoktur. Ancak bilerek gerçeğe tanıklık edenler hariç."},{"n":87,"t":"Onlara kendilerini kimin yarattığını sorsan, kesinlikle “Allah” diyeceklerdir. Buna rağmen nasıl da döndürülüyorlar!"},{"n":88,"t":"Peygamber`in, “Ey Rabbim! Bunlar inanmayan bir toplumdur” sözüne Allah şöyle karşılık verir:"},{"n":89,"t":"“Onlara karşı dikkatli ol ve “selam” size de! İleride gerçeği anlayacaklardır.”"}],[{"n":1,"t":"Hâ, mîm."},{"n":2,"t":"Açıklayıcı kitaba yemin olsun."},{"n":3,"t":"Biz onu, mübarek bir gecede indirmeye başladık. Şüphesiz biz, uyarıcıyız."},{"n":"4-5","t":"O gecede katımızdan verdiğimiz bir emirle bütün hikmetli işler belirlenir. Şüphesiz biz peygamberler göndeririz."},{"n":6,"t":"Peygamber göndermemiz, Rabbinden olan bir rahmet gereğidir. Şüphesiz Allah her şeyi işitendir; her şeyi bilendir."},{"n":7,"t":"Eğer kesin olarak inanıyorsanız, göklerin, yerin ve ikisi arasında bulunanların Rabbidir."},{"n":8,"t":"O`ndan başka tanrı yoktur. O yaşatır ve öldürür. Sizin de, önceki atalarınızın da Rabbidir."},{"n":9,"t":"Doğrusu onlar şüphe içerisinde oynamaktadırlar."},{"n":"10-11","t":"Artık sen, göğün, insanları bürüyecek apaçık bir duman çıkaracağı günü bekle! Bu, elem verici bir azaptır."},{"n":12,"t":"İnsanlar, “Ey Rabbimiz! Bizden bu azabı kaldır. Doğrusu biz artık inanıyoruz” derler."},{"n":13,"t":"Bu öğüt, kıyamet anında onlara ne fayda sağlar ki? Çünkü daha önce hakikati ortaya apaçık olarak koyan bir peygamber gelmişti."},{"n":14,"t":"Sonra ondan yüz çevirdiler ve “Bu, öğretilmiş bir delidir!” dediler."},{"n":15,"t":"Biz azabı biraz kaldırırsak, siz yine eski halinize dönersiniz."},{"n":16,"t":"Fakat biz büyük bir şiddetle vurup yakaladığımız gün, elbette kendilerinden intikam alacağız."},{"n":17,"t":"“Ey Allah`ın kulları! Çağrıma uyarak bana karşı görevinizi yerine getiriniz. Çünkü ben size gönderilmiş güvenilir bir peygamberim.”"},{"n":18,"t":"“Ey Allah`ın kulları! Çağrıma uyarak bana karşı görevinizi yerine getiriniz. Çünkü ben size gönderilmiş güvenilir bir peygamberim.”"},{"n":19,"t":"“Allah`a karşı baş kaldırmayınız. Çünkü ben size apaçık bir mucize getirdim.”"},{"n":20,"t":"“Ben, beni taşlamanızdan dolayı benim ve sizin Rabbiniz olan Allah`a sığındım.”"},{"n":21,"t":"“Eğer bana inanmıyorsanız, hiç olmazsa yanımdan uzaklaşınız.”"},{"n":22,"t":"Bunun üzerine Mûsâ, bunların suç işleyen bir toplum olduğunu Rabbine arzetti."},{"n":23,"t":"Allah, “O halde kullarımı geceleyin yola çıkar. Çünkü takip edileceksiniz” dedi."},{"n":24,"t":"“Denizi sükûnetle geç/terk et; çünkü onlar boğulacak bir ordudur.”"},{"n":"25-27","t":"Onlar arkalarında ne bahçeler, pınarlar, ekinler, güzel konaklar, zevk ve safasını sürdükleri nice nimetler bırakmışlardı."},{"n":28,"t":"Böylece biz de bıraktıklarına başka bir toplumu mirasçı kıldık."},{"n":29,"t":"Gök ve yer onların ardından ağlamadı; onlara mühlet de verilmedi."},{"n":"30-31","t":"Andolsun biz, İsrâiloğulları`nı o alçaltıcı azaptan, yani Firavun`dan kurtardık. Çünkü o, aşırı gidenlerden bir zorba idi."},{"n":32,"t":"Andolsun, biz bilerek İsrâiloğulları`nı çağların insanlarına tercih ettik."},{"n":33,"t":"Onlara, her birinde açıkça bir sınav olan âyetler verdik."},{"n":34,"t":"“Ölüm, sadece bizim bir kere ölmemizdir. Biz tekrar diriltilmeyeceğiz. Eğer doğru söylüyorsanız haydi, babalarımızı diriltip getiriniz.”"},{"n":35,"t":"“Ölüm, sadece bizim bir kere ölmemizdir. Biz tekrar diriltilmeyeceğiz. Eğer doğru söylüyorsanız haydi, babalarımızı diriltip getiriniz.”"},{"n":36,"t":"“Ölüm, sadece bizim bir kere ölmemizdir. Biz tekrar diriltilmeyeceğiz. Eğer doğru söylüyorsanız haydi, babalarımızı diriltip getiriniz.”"},{"n":37,"t":"“Bunlar mı daha üstündür yoksa Tübba‘ kavmi ve onlardan öncekiler mi?” Hepsini helâk ettik. Çünkü onlar suçlu toplumlardı."},{"n":38,"t":"Biz gökleri, yeri ve ikisinin arasında bulunanları, oyun ve eğlence olsun diye yaratmadık."},{"n":39,"t":"Biz onları, gerçek bir amaç için yarattık. Fakat insanların çoğu bunu bilmezler."},{"n":40,"t":"Haklıyı haksızdan ayırma günü, onların hepsinin toplanma günüdür."},{"n":41,"t":"O gün, hiçbir dostun dostuna bir faydası olmayacak ve yardım da görmeyeceklerdir."},{"n":42,"t":"Allah`ın acıdıkları hariç, çünkü O`nun her şeye gücü yeter; çok merhametlidir."},{"n":"43-44","t":"Şüphesiz zakkum ağacı, günahkârların yiyeceğidir."},{"n":"45-46","t":"Erimiş maden gibi, karınlarda kaynar, sıcak suyun kaynaması gibi."},{"n":47,"t":"“Bu suçluyu yakalayın ve onu cehennemin ortasına atın.”"},{"n":48,"t":"“Sonra başından aşağı kaynar su azabından dökün.”"},{"n":49,"t":"“Tat bakalım, hani sen şerefli ve güçlü idin!”"},{"n":50,"t":"İşte şüphe ettiğiniz azap budur."},{"n":51,"t":"Allah`ın emirlerine karşı gelmekten sakınanlar ise güvenli bir yerdedirler."},{"n":52,"t":"Bahçelerde ve pınarların başlarında."},{"n":53,"t":"İnce ve kalın ipekten elbiseler giyerek karşılıklı otururlar."},{"n":54,"t":"Aynı şekilde onlara çok güzel eşler veririz."},{"n":55,"t":"Orada güven içinde her türlü meyveden isterler."},{"n":56,"t":"Orada, ilk ölümün dışında, başka bir ölüm tatmazlar. Allah onları cehennem azabından korumuştur."},{"n":57,"t":"Rabbinden bir lütuf olarak işte, asıl büyük başarı budur."},{"n":58,"t":"Böylece biz Kur`ân`ı senin kendi dilinde kolay anlaşılır kıldık ki, düşünüp öğüt alsınlar."},{"n":59,"t":"Öyleyse bekle, çünkü onlar da bekliyorlar."}],[{"n":1,"t":"Hâ, mîm."},{"n":2,"t":"Kitap, üstün ve hikmet sahibi Allah tarafından indirilmiştir."},{"n":3,"t":"Şüphesiz, göklerde ve yerde, inananlar için deliller vardır."},{"n":4,"t":"Sizin yaratılışınızda ve yeryüzüne yaydığı canlıların yaratılışında, kesin olarak inananlar için dersler vardır."},{"n":5,"t":"Gece ve gündüzün değişmesinde, Allah`ın gökten indirmiş olduğu rızıkta ve onunla ölümünden sonra yeri diriltmesinde, rüzgârları değişik yönlerden estirmesinde, aklını kullanan toplum için dersler vardır."},{"n":6,"t":"İşte bunlar, Allah`ın âyetleridir. Bunları sana gerçek olarak okuyoruz. Allah`tan ve O`nun âyetlerinden sonra hangi söze inanacaklar?"},{"n":7,"t":"Bütün yalancı ve günahkârların vay haline!"},{"n":8,"t":"Onlar, kendilerine okunan Allah`ın âyetlerini dinler, sonra sanki hiç duymamış gibi, gururlanarak, inanmamakta ısrar ederler. Böylelerini acıklı bir azapla müjdele!"},{"n":9,"t":"Âyetlerimizden bir şeyler öğrendiklerinde, onu alaya alırlar. Onlar için alçaltıcı bir azap vardır."},{"n":10,"t":"Önlerinde cehennem vardır. Kazandıkları malları, Allah`tan başka edindikleri dostları, kendilerine hiçbir fayda sağlamayacaktır. Onlar için büyük bir azap vardır."},{"n":11,"t":"Bu Kur`ân, yol gösteren bir rehberdir. Rabblerinin âyetlerini inkâr edenler için çok çetin bir azap vardır."},{"n":12,"t":"Denizi sizin hizmetinize sunan Allah`tır. Ta ki gemiler, O`nun buyruğu ile denizde akıp gitsin de siz bu sayede O`nun lütfundan payınızı arayasınız ve şükredesiniz."},{"n":13,"t":"Göklerde ve yerde bulunan şeyleri, kendisinden bir lütuf olarak size boyun eğdirdi. Şüphesiz bunda, düşünen bir toplum için dersler vardır."},{"n":14,"t":"Allah`ın ceza günlerini beklemeyenlere aldırmasınlar; çünkü Allah, her bir topluluğa yaptıklarının karşılığını verecektir."},{"n":15,"t":"Kim iyi bir amel yaparsa yararı kendisinedir. Kim de kötü bir amel yaparsa zararı kendisinedir. Sonunda Rabbinize döndürüleceksiniz."},{"n":16,"t":"Andolsun biz, İsrâiloğulları`na kitap, hükümranlık ve peygamberlik verdik, onları güzel rızıklarla besledik ve onları âlemlere üstün kıldık."},{"n":17,"t":"Onlara din işinde açık kanıtlar verdik. Onlar kendilerine bilgi geldikten sonra sadece aralarındaki kıskançlık yüzünden ayrılığa düştüler. Şüphesiz Rabbin, kıyamet günü, ayrılığa düştükleri şeylerde onlar arasında hüküm verecektir."},{"n":18,"t":"Sonra sana da emrimizden bir yasa belirledik; artık ona uy, bilmeyenlerin arzularına uyma!"},{"n":19,"t":"Çünkü onlar, Allah`tan gelecek olan hiçbir şeyi savamazlar. Şüphesiz, zâlimler birbirlerinin dostlarıdır. Allah da takvâ sahiplerinin dostudur."},{"n":20,"t":"Bu Kur`ân, insanlar için basiret/aydınlık nurları; kesin olarak inanan bir toplum için hidayet ve rahmettir."},{"n":21,"t":"Kötülük işleyenler kendilerini, hayatlarında ve ölümlerinde, inanıp yararlı iş yapanlarla bir tutacağımızı mı sandılar? Ne kötü hüküm veriyorlar!"},{"n":22,"t":"Allah, gökleri ve yeri bir amaç uğruna yarattı ki, her can, kendi kazandığının karşılığını görsün. Onlar asla haksızlığa uğratılmazlar."},{"n":23,"t":"Arzusunu tanrısı edineni; Allah`ın bir bilgiye dayanarak saptırdığı, kulaklarını ve kalbini mühürlediği ve gözlerinin üzerine bir perde çektiği insanı, hiç düşündün mü? Şimdi onu Allah`tan başka kim doğru yola iletebilir? O halde, hiç düşünüp ders almaz mısınız?"},{"n":24,"t":"Onlar, “Bizim dünya hayatımızdan başka bir hayat yoktur. Dünyaya geldiğimiz gibi ölürüz. Bizi ancak zaman yok eder” derler. Fakat onların bu konuda hiçbir bilgileri yoktur. Sadece öyle zannediyorlar."},{"n":25,"t":"Âyetlerimiz kendilerine açık açık okunduğu zaman, onların, “Eğer doğru söylüyorsanız, babalarımızı geri getiriniz” demekten başka delilleri yoktur."},{"n":26,"t":"“Sizi Allah diriltir, sonra öldürür, sonra sizi şüphe olmayan kıyamet gününde toplayacaktır. Fakat insanların çoğu bunu bilmezler.”"},{"n":27,"t":"Göklerin ve yerin egemenliği yalnız Allah`a aittir. Kıyamet kopacağı gün, işte o gün, yanlış yola sapanlar kaybedeceklerdir."},{"n":28,"t":"“Bugün yaptıklarınızın karşılığını göreceksiniz.”"},{"n":29,"t":"İşte, kitabımız size gerçeği söylüyor. Şüphesiz biz sizin yaptıklarınızı yazdırmıştık."},{"n":30,"t":"İnanıp yararlı işler yapanlara gelince; Rabbleri onları rahmetinin içine alacaktır. İşte apaçık kurtuluş budur."},{"n":31,"t":"“Âyetlerim size okunmuyor muydu? Neden büyüklenip, suçlu bir toplum oldunuz?”"},{"n":32,"t":"“Kıyametin ne olduğunu bilmiyoruz. Sadece öyle bir şey sanıyoruz, ama biz onun gerçekleşeceğine de inanmıyoruz.”"},{"n":33,"t":"Yaptıklarının kötülükleri onlara gözükecek ve alaya aldıkları gerçek kendilerini çepeçevre kuşatacaktır."},{"n":34,"t":"“Siz, bugüne kavuşacağınızı unuttuğunuz gibi, biz de sizi unuttuk. Sizin yeriniz cehennemdir. Sizin için hiçbir yardımcı da yoktur.”"},{"n":35,"t":"“Bunun sebebi, sizin, Allah`ın âyetlerini alaya almanız ve dünya hayatının sizi aldatmasıdır.” Artık o gün, ne ateşten çıkarılacaklar, ne de Allah`ı hoşnut etmeleri istenecektir."},{"n":36,"t":"Bütün övgüler, göklerin Rabbi, yerin Rabbi, bütün insanların Rabbi olan Allah`a aittir."},{"n":37,"t":"Göklerde ve yerde bütün ululuk O`nundur. Yalnız O, kudretlidir; hikmet sahibidir."}],[{"n":1,"t":"Hâ, mîm."},{"n":2,"t":"Kitap, üstün ve hikmet sahibi Allah tarafından indirilmiştir."},{"n":3,"t":"Biz, gökleri, yeri ve arasındakileri bir amaç için ve belli bir süreye göre yarattık. İnkâr edenler ise, uyarıldıkları şeyden yüz çevirmektedirler."},{"n":4,"t":"“Allah`tan başka taptıklarınızın durumuna baktınız mı? Yeryüzünde neyi yarattıklarını ya da göklerde bir ortağını bana gösteriniz? Eğer doğru söylüyorsanız, bana bu Kur`ân`dan önce bir kitap ya da bir bilgi kalıntısı getiriniz!”"},{"n":5,"t":"Allah`ı bırakıp da, kıyamete kadar kendilerine cevap veremeyecek ve kendi çağırılarından habersiz olan tanrılara yalvaranlardan daha sapık kim vardır?"},{"n":6,"t":"Kaldı ki, insanlar toplandığı gün onlar bunlara düşman olacak ve kulluk ettiklerini de inkâr edeceklerdir."},{"n":7,"t":"Âyetlerimiz onlara apaçık okunduğunda, hakikat kendilerine geldiğinde onu inkâr edenler, “Bu, apaçık bir büyüdür” dediler."},{"n":8,"t":"“Eğer ben onu uydurmuşsam, Allah tarafından bana gelecek şeyi savmaya gücünüz yetmez. Allah, sizin Kur`ân hakkında yaptığınız taşkınlıkları çok daha iyi bilir. Benimle sizin aranızda şahit olarak O yeter. O, affedicidir; merhamet sahibidir.”"},{"n":9,"t":"“Ben peygamberler arasında türedi biri değilim. Bana ve size ne yapılacağını da bilmem. Ben sadece bana vahyedilene uyuyorum ve ben apaçık bir uyarıcıyım.”"},{"n":10,"t":"“Hiç düşündünüz mü? Eğer Kur`ân, Allah katından olduğu halde siz onu tanımamışsanız, İsrâiloğuları`ndan bir tanık da bunun benzerini görüp inanmış iken siz inanmaya tenezzül etmemişseniz, durumunuz nice olur? Allah, zâlim toplumu doğru yola iletmez.”"},{"n":11,"t":"“Eğer Muhammed`in getirdiği iyi olsaydı, biz onlardan önce inanırdık.” Bununla amaçlarına ulaşamayınca da, “Bu, eski bir uydurmadır” dediler."},{"n":12,"t":"Kur`ân`dan önce Mûsâ`nın kitabı, rehber ve rahmet olarak vardı. Bu da onu doğrulayıcı bir kitaptır. Zulmedenleri uyarmak ve iyi iş yapanları da müjdelemek için Arapça olarak indirilmiştir."},{"n":13,"t":"“Şüphesiz Rabbimiz Allah`tır” deyip sonra dosdoğru hareket edenlere korku yoktur ve onlar üzülmeyeceklerdir."},{"n":14,"t":"İşte onlar cennetliklerdir; yaptıklarının karşılığı olarak cennette süreli kalacaklardır."},{"n":15,"t":"“Ey Rabbim! Bana ve anne babama verdiğin nimete şükretmemi ve hoşnut olacağın iyi ameller yapmamı bana nasip et! Benim soyumdan iyi insanlar yetiştir. Ben sana yöneldim ve ben sana teslim olanlardanım.”"},{"n":16,"t":"İşte onlar öyle kişilerdir ki, yaptıklarının en iyisini onlardan kabul ederiz ve onların kötülüklerini bağışlarız; onlar cennet halkı arasındadırlar. Bu, kendilerine verilen doğru sözün gerçekleşmesidir."},{"n":17,"t":"Diğer bir kimse de anne babasına, “Öf be! Bana kabirden çıkartılıp diriltileceğimizi mi söylüyorsunuz? Oysa benden önce nice nesiller de gelip geçti” der. Anne babası da Allah`tan yardım dileyerek, “Sana yazıklar olsun, Allah`ın vaadine inan, çünkü Allah`ın vaadi gerçektir” dediler. O da, “Bunlar eskilerin masallarından başka bir şey değildir” diye cevap vermişti."},{"n":18,"t":"İşte onlar, kendilerinden önce cinlerden ve insanlardan gelip geçmiş topluluklar içinde, haklarında azabın gerçekleştiği kimselerdir. Gerçekten onlar ziyana uğrayanlardır."},{"n":19,"t":"Herkesin yaptıklarına göre dereceleri vardır. Allah onlara, yaptıklarının karşılığını verir, asla kendilerine haksızlık yapılmaz."},{"n":20,"t":"“Dün hayatınızdaki bütün güzelliklerinizi boşa harcayıp safasını sürdünüz. Bugün ise yeryüzünde haksız yere büyüklük taslamanızdan ve yoldan çıkmanızdan dolayı alçaltıcı bir azap göreceksiniz.”"},{"n":21,"t":"‘Âd`ın kardeşi olan Hûd`u hatırla! Zira o, kendinden önce ve sonra uyarıcıların da gelip geçtiği Ahkâf bölgesindeki kavmine, “Allah`tan başkasına kulluk etmeyiniz, ben sizin büyük bir günün azabına uğramanızdan korkuyorum” demişti."},{"n":22,"t":"Onlar, “Sen bizi tanrılarımızdan vazgeçirmeye mi geldin? Eğer doğru söylüyorsan haydi, uyardığın azabı getir!” dediler."},{"n":23,"t":"“Bilgi, ancak Allah katındadır. Ben size, bana gönderilen şeyi duyuruyorum. Fakat sizin cahil bir kavim olduğunuzu görüyorum.”"},{"n":24,"t":"Nihayet onu, vadilerine doğru yayılan bir bulut şeklinde görünce, “Bu bize yağmur yağdıracak yaygın bir buluttur” dediler. “Hayır! O, sizin acele gelmesini istediğiniz şeydir. İçinde acı azap bulunan bir rüzgârdır.”"},{"n":25,"t":"“O rüzgâr, Rabbinin emri ile her şeyi yerle bir eder” der demez, evlerinin kalıntılarından başka bir şey görünmez oldu. İşte biz, suç işleyen toplumu böyle cezalandırırız."},{"n":26,"t":"Andolsun ki, onlara, size vermediğimiz imkanları sağlamıştık. Kendilerine kulaklar, gözler ve kalpler vermiştik. Fakat kulakları, gözleri ve kalpleri kendilerine bir fayda sağlamadı. Zira bile bile Allah`ın âyetlerini inkâr ediyorlardı. Alay edip durdukları şey kendilerini kuşatıverdi."},{"n":27,"t":"Andolsun ki biz, sizin çevrenizde bulunan nice ülkeleri de yok ettik. Belki doğru yola dönerler diye, âyetleri tekrar tekrar açıkladık."},{"n":28,"t":"Allah`tan başka kendilerine yakınlık sağlamak için tanrı edindikleri şeyler, kendilerine yardım etselerdi ya! Ama öyle olmadı, onları bırakıp gittiler. Bu onların yalanı ve uydurup durdukları şeydir."},{"n":29,"t":"Hani, cinlerden Kur`ân`ı dinlemek isteyen bir grubu sana yöneltmiştik. Onlar Kur`ân`ı dinlemeye geldiklerinde, “Susup dinleyin!” dediler. Kur`ân`ın okunması tamamlanınca, uyarıcılar olarak kavimlerine döndüler."},{"n":30,"t":"“Ey kavmimiz! Şüphesiz biz Mûsâ`dan sonra indirilen ve kendilerinden öncekileri doğrulayan bir kitap dinledik. O, hakikate ve doğru yola götürmektedir.”"},{"n":31,"t":"“Ey kavmimiz! Allah`ın çağrısına uyunuz ve O`na iman ediniz. O, günahlarınızı affedecek ve âhirette acıklı azaptan koruyacaktır.”"},{"n":32,"t":"Kim Allah`ın çağrısına uymazsa, bilsin ki yeryüzünde Allah`a karşı koyamaz, onun O`ndan başka dostları da olmaz. Böyleleri apaçık bir sapıklık içindedirler."},{"n":33,"t":"Gökleri, yeri yaratan ve onları yaratmaktan yorulmayan Allah`ın, ölüleri diriltmeye de gücünün yeteceğini düşünmezler mi? Evet, Allah`ın her şeye gücü yeter."},{"n":34,"t":"Kâfirler ateşle yüz yüze getirildikleri gün, kendilerine, “Bu gerçek değil miymiş?” denilecek. Onlar, “Evet, Rabbimize andolsun doğruymuş” diyecekler. Allah, “Öyleyse, inkâr etmenizden dolayı tadın bu azabı” diyecektir."},{"n":35,"t":"Artık güç ve kuvvet sahibi peygamberlerin sabrettiği gibi sen de sabret! Onlara azabın çabuk gelmesini isteme. Onlar uyarıldıkları azabı gördükleri zaman, sanki günün bir saati kadar beklemiş gibi olacaklardır. Bu bir tebliğdir. Yoldan çıkan topluluklardan başkası helâk olmayacaktır."}],[{"n":1,"t":"Allah, inkâr edenlerin ve Allah yolundan alıkoyanların amellerini boşa çıkarmıştır."},{"n":2,"t":"İman edip iyi amel işleyenlerin ve Rabbleri tarafından hak olarak Muhammed`e indirilene inananların günahlarını Allah örtmüş ve hallerini düzeltmiştir."},{"n":3,"t":"Bunun sebebi, inkâr edenlerin bâtıla uymaları; inananların da Rabblerinden gelen hakka uymuş olmalarıdır. İşte Allah, insanlara kendileriyle ilgili durumları böyle örnek vermektedir."},{"n":4,"t":"İnkâr edenlerle savaşta karşılaştığınızda, hemen boyunlarını vurunuz. Onları yendiğinizde de sıkıca bağlayınız. Savaş sona erdiğinde ya bir lütuf olarak karşılıksız ya da fidye alarak salıveriniz. Allah dileseydi onlara galip gelirdi. Fakat kiminizi kiminizle denemek için böyle yaptı. Allah yolunda öldürülenlerin yaptıkları hiçbir ameli Allah asla boşa çıkarmayacaktır."},{"n":5,"t":"Allah onları hidayete iletecek ve durumlarını düzeltecek."},{"n":6,"t":"Onları, kendilerine tanıttığı cennete koyacaktır."},{"n":7,"t":"Ey iman edenler! Eğer siz Allah`a yardım ederseniz, O da size yardım eder, ayaklarınızı sabit tutar/kaydırmaz."},{"n":8,"t":"İnkâr edenlere gelince, onların sonu felakettir. Allah onların amellerini boşa çıkarmıştır."},{"n":9,"t":"Bunun sebebi, Allah`ın indirdiğini beğenmemeleridir. Allah da onların amellerini boşa çıkarmıştır."},{"n":10,"t":"Yeryüzünde dolaşıp, kendilerinden öncekilerin sonlarının nasıl olduğuna bakmazlar mı? Allah onları yerle bir etmiştir. Kâfirlere de onların benzerlerini yapacaktır."},{"n":11,"t":"Çünkü Allah, inananların yardımcısıdır. Kâfirlerin ise dostları yoktur."},{"n":12,"t":"Şüphesiz Allah, inanıp iyi amel işleyenleri, içinden ırmakların aktığı cennetlere koyacaktır. İnkâr edenler ise, dünya nimetlerinden yararlanıp hayvanlar gibi yiyip içecekler. Sonunda varacakları yer ateş olacaktır."},{"n":13,"t":"Seni yurdundan eden şehrin halkından daha güçlü, kuvvetli, nice şehirlerin halklarını yok ettik. Onlara yardım eden de olmadı."},{"n":14,"t":"Rabbinin katından bir delil üzere olanla, kötü işi kendisine güzel gösterilen bir midir? Bunlar kendi arzularına uymaktadırlar."},{"n":15,"t":"Orada bozulmayan sudan ırmaklar, tadı değişmeyen sütten ırmaklar, içenlere lezzet veren şerbetten ırmaklar ve süzme baldan ırmaklar vardır. Onlara orada her çeşit meyvelerden de vardır. Rableri tarafından bağışlanacaklardır. Bu durumda olanlar, süreli olarak ateşte kalıp, bağırsaklarını parça parça edecek kaynar su içirilenlerle bir midir?"},{"n":16,"t":"`O, demin ne anlattı?` diye sorarlar. İşte onlar, Allah’ın kalplerini, kafalarını anlayışsız hale getirdiği kimselerdir. Onlar sadece, şahsî arzu ve ihtiraslarına uyarlar."},{"n":17,"t":"Doğru yola yönelenlerin Allah doğruluklarını arttırır ve sakınmalarını sağlar."},{"n":18,"t":"Onlar kıyamet saatinin kendilerine ansızın gelmesinden başka bir şey beklemiyorlar. Şüphesiz onun geleceği şimdiden haber verilmiştir. Kıyamet koptuğunda, geçmiş günahlarını hatırlamalarının onlara ne faydası olacaktır?"},{"n":19,"t":"Allah`tan başka tanrı olmadığını bil; hem kendi günahın, hem de inanan erkek ve kadınların günahları için af dile! Allah dönüp dolaşacağınız yeri bilir."},{"n":20,"t":"İnananlar, “Keşke savaşa izin veren bir sûre indirilmiş olsaydı!” derler. Ama hükmü açık bir sûre indirilip de onda savaştan söz edilince, kalplerinde hastalık olanların, ölüm baygınlığı geçiren kimsenin bakışı gibi sana baktıklarını görürsün. Onlara yakışan da budur!"},{"n":21,"t":"Onların görevi, itaat etmek ve güzel söz söylemektir. Savaşa karar verildiğinde, Allah`a verdikleri sözde dursalardı kendileri için daha iyi olurdu."},{"n":22,"t":"“Durumunuz bu iken, ey münafıklar, iktidarı ele geçirirseniz yeryüzünde bozgunculuk çıkarmanız ve akrabalık bağlarını koparmanız sizden beklenmez mi?”"},{"n":23,"t":"İşte, Allah böylelerine lanet edip kulaklarını sağır ve gözlerini kör etmiştir."},{"n":24,"t":"Bunlar, Kur`ân`ı düşünmüyorlar mı? Yoksa kalpleri kilitli midir?"},{"n":25,"t":"Kendilerine doğru yol apaçık belli olduktan sonra eski hallerine dönenleri, şeytan sürüklemiş ve kendilerine ümit vermiştir."},{"n":26,"t":"Bunun sebebi, onların Allah`ın indirdiğinden hoşlanmayanlara, “Bazı hususlarda size itaat edeceğiz” demeleridir. Oysa Allah, onların gizlediklerini biliyor."},{"n":27,"t":"Ya melekler onların yüzlerine ve sırtlarına vurarak canlarını alırken durumları nasıl olacak?"},{"n":28,"t":"Onlar, Allah`ı kızdıran şeylerin ardından gittiler ve O`nun razı olduğu şeylerden hoşlanmadılar. Böylece Allah da onların yaptıklarını boşa çıkardı."},{"n":29,"t":"Yoksa o kalplerinde hastalık olanlar, Allah kendilerinin şiddetli kinlerini hiçbir zaman ortaya çıkarmayacak mı sandılar?"},{"n":30,"t":"Biz dileseydik, onları sana gösterirdik de sen onları yüzlerinden tanırdın. Andolsun ki, sen onları konuşma üsluplarından tanırsın. Allah işlediklerinizi bilir."},{"n":31,"t":"Andolsun ki, içinizden cihad edenleri ve sabredenleri bilmek için sizi imtihan edeceğiz; sözlerinizin doğruluğunu da test edeceğiz."},{"n":32,"t":"İnkâr edenler, Allah`ın yolundan alıkoyanlar ve kendilerine doğru yol belli olduktan sonra Peygambere karşı gelenler, Allah`a asla zarar veremezler. Allah onların yaptıklarını boşa çıkaracaktır."},{"n":33,"t":"Ey iman edenler! Allah`a itaat ediniz, peygambere itaat ediniz, işlerinizi boşa çıkarmayınız!"},{"n":34,"t":"İnkâr edip Allah yolundan alıkoyanları ve sonra da kâfir olarak ölenleri Allah asla bağışlamaz."},{"n":35,"t":"Üstün durumdayken gevşeyip barışa çağırmayınız. Allah sizinle beraberdir. O, amellerinizi asla heder etmeyecektir."},{"n":36,"t":"Gerçekten dünya hayatı ancak bir oyun ve eğlencedir. Eğer iman eder ve sakınırsanız Allah size mükâfatınızı verir. Sizden mallarınızı tamamen sarfetmenizi istemez."},{"n":37,"t":"Eğer mallarınızın tamamını isteseydi ve sizi zorlasaydı, cimrilik ederdiniz. Bu da sizin kinlerinizi ortaya çıkarırdı."},{"n":38,"t":"İşte, sizler Allah yolunda infak etmeye çağrılıyorsunuz. İçinizden kiminiz cimrilik ediyor. Ama kim cimrilik ederse, ancak kendisine cimrilik ediyor. Allah zengindir, siz ise fakirsiniz. Eğer O`ndan yüz çevirirseniz, yerinize sizden başka bir toplum getirir, artık onlar sizin gibi olmazlar."}],[{"n":1,"t":"Biz sana apaçık zaferin kapılarını açtık."},{"n":2,"t":"Böylece Allah, senin geçmiş ve gelecek bütün hatalarını bağışlayacak, bütün nimetlerini sana verecek ve seni dosdoğru bir yola sevk edecektir."},{"n":3,"t":"Allah sana, şanlı bir zaferle yardımda bulunacaktır."},{"n":4,"t":"İmanlarını kat kat arttırmaları için inananların kalplerine huzur ve güven veren O`dur. Göklerin ve yerin orduları Allah`ındır. Allah her şeyi bilir; her işinde hikmet vardır."},{"n":5,"t":"Bu, inanmış erkekleri ve inanmış kadınları, içinde süreli olarak kalacakları, içinde ırmaklar akan cennetlere sokması ve onların kötülüklerini gizlemesi içindir. İşte bu, Allah katında çok büyük bir kurtuluştur."},{"n":6,"t":"Yine bu, Allah hakkında yanlış düşünceler besleyen münafık erkek ve münafık kadınları, müşrik erkek ve müşrik kadınları cezalandırması içindir. Müslümanlar için bekledikleri kötülük çemberi, başlarına gelsin! Allah onlara gazap etmiş, lanetlemiş ve cehennemi kendilerine hazırlamıştır. Orası ne kötü bir yerdir!"},{"n":7,"t":"Göklerin ve yerin orduları Allah`ındır. Allah, kudret ve hikmet sahibidir."},{"n":8,"t":"Biz seni şâhit, müjdeleyici ve uyarıcı olarak gönderdik."},{"n":9,"t":"Allah`a ve peygamberine inanasınız, O`nu destekleyesiniz, O`na saygı gösteresiniz ve sabah akşam O`nu tesbih edesiniz/anasınız/namaz kılasınız diye."},{"n":10,"t":"Sana bağlılıklarını bildirenler aslında Allah`a bağlılıklarını bildirmektedirler. Allah`ın kudreti, onların kudretleri üzerindedir. O halde, kim ahdini bozarsa kendi aleyhine bozmuş olur. Kim de Allah`a verdiği sözü yerine getirirse, Allah ona büyük bir ödül verecektir."},{"n":11,"t":"“Allah size bir zarar vermeyi dilerse, yahut bir fayda murat ederse, onun sizin için dilediğine kim engel olabilir? Doğrusu şu ki, Allah sizin yaptıklarınızdan haberdardır.”"},{"n":12,"t":"“Doğrusu siz, Peygamberin ve inananların, ailelerine bir daha asla dönmeyeceklerini sanmıştınız. Bu durum gönüllerinize hoş gösterildi, kötü duygulara kapıldınız. Siz, helâki hak etmiş bir toplum oldunuz.”"},{"n":13,"t":"Kim Allah`a ve Peygamberine inanmazsa bilsin ki biz, inkâr edenler için alevli bir ateş hazırladık."},{"n":14,"t":"Göklerin ve yerin mülkiyeti Allah`a aittir. O, dilediğini affeder, dilediğini cezalandırır. Allah affedicidir; merhamet sahibidir."},{"n":15,"t":"“Siz asla bizimle beraber gelmeyeceksiniz. Allah sizin için önceden böyle buyurdu.” Onlar, “Hayır, siz bizi kıskanıyorsunuz” diyecekler. Aslında onlar, kafaları pek az çalışan kimselerdir."},{"n":16,"t":"“Yakında çok güçlü bir topluma karşı savaşmaya çağırılacaksınız. Ya onlarla savaşacaksınız ya da onlar teslim olacaklar. Eğer emre itaat ederseniz, Allah size güzel bir ödül verir. Ama önceden döndüğünüz gibi yine dönecek olursanız, sizi acıklı bir azaba uğratır.”"},{"n":17,"t":"Gözleri görmeyene, sakat olana veya hasta olana, savaşa katılmamakta bir vebal yoktur. Kim Allah`a ve Peygambere itaat ederse, Allah onu içinden ırmaklar akan cennetlere koyacaktır. Kim de yüz çevirirse, onu da acıklı bir ceza ile cezalandıracaktır."},{"n":18,"t":"O ağacın altında sana bağlılıklarını bildiren müminlerden Allah razı olmuştur. Çünkü onların kalplerinden geçeni biliyordu; böylece Allah onlara bir iç huzuru verdi. Yakında onları bir fetihle ödüllendirecektir."},{"n":19,"t":"Elde edecekleri birçok ganimetle de ödüllendirecektir. Allah üstündür; hikmet sahibidir."},{"n":20,"t":"Allah size, elde edeceğiniz birçok ganimet vaad etmiştir. Bir kısmını sizin için çabuklaştırmıştır. İnsanların ellerini de üzerinizden çekmiştir. Bu, müminlere bir işaret olsun ve sizi doğru yola iletsin diyedir."},{"n":21,"t":"Henüz elde edemediğiniz başka ganimetler de vardır ki, onlar Allah`ın bilgi ve kudreti dahilindedir. Allah`ın gücü her şeye yeter."},{"n":22,"t":"Eğer kâfirler sizinle savaşsalardı, arkalarına dönüp kaçarlardı. Sonra bir dost ve yardımcı da bulamazlardı."},{"n":23,"t":"Allah`ın öteden beri süre gelen yasası budur. Allah`ın yasasında asla bir değişiklik bulamazsın."},{"n":24,"t":"Sizi onlara muzaffer kıldıktan sonra Mekke vadisinde onların ellerini sizin üzerinizden, sizin ellerinizi de onlardan çeken O`dur. Allah yapmış olduğunuz her şeyi görmektedir."},{"n":25,"t":"İnkâr edenler, sizi Mescid-i Harâm`dan alıkoyanlar, kurbanların yerlerine ulaşmasına engel olanlardır. Eğer Mekke`de bulunan inanmış erkekler ve kadınlardan tanımadıklarınızı öldürüp bu yüzden bilmeden günaha girmeniz söz konusu olmasaydı, Allah savaşı önlemeyecekti. Dilediklerine rahmet etmek için Allah böyle yapmıştır. Eğer inananlarla kâfirler iç içe olmasalardı, inkâr edenleri acıklı bir azap ile cezalandırırdık."},{"n":26,"t":"O zaman inkâr edenler, kalplerine taassubu, Câhiliye taassubunu yerleştirmişlerdi. Allah da, Peygamberine ve müminlere huzuru ve güvenini indirmişti; onlara takvâ sözünü aşılamıştı. Zaten onlar buna lâyık kimselerdi. Allah her şeyi bilendir."},{"n":27,"t":"Andolsun ki Allah, Peygamberine rüyayı doğru çıkardı. Allah dilerse, Mescid-i Harâm`a güven içerisinde, başlarınızı tıraş ederek ve saçlarınızı kısaltmış olarak korkusuzca gireceksiniz. Allah sizin bilmediğinizi bilir. Bu rüyadan sonra size yakın bir fetih nasip edecektir."},{"n":28,"t":"Bütün dinlerden üstün kılmak üzere, Peygamberini hidayet ve hak din ile gönderen O`dur. Şâhit olarak Allah yeter."},{"n":29,"t":"Filizini yarıp çıkarmış, gittikçe onu kuvvetlendirerek kalınlaşmış, gövdesi üzerinde dimdik duran bir ekine benzerler. Bu ekincilerin hoşuna gider. Allah bunlarla, kâfirleri öfkelendirecektir. Allah, inanıp yararlı işler yapanlara af ve büyük bir ödül vaad etmiştir."}],[{"n":1,"t":"Ey iman edenler! Allah`ın ve Peygamberinin önüne geçmeyiniz. Allah`a saygı duyunuz. Şüphesiz ki Allah, işitendir; bilendir."},{"n":2,"t":"Ey inananlar! Seslerinizi, Peygamberin sesinden daha fazla yükseltmeyiniz. Birbirinize bağırdığınız gibi, Peygambere yüksek sesle bağırmayınız. Yoksa siz farkına varmadan amelleriniz boşa gidiverir."},{"n":3,"t":"Allah, Peygamber`in yanında seslerini kısanların kalplerini takvâ ile imtihan etmiştir. Onlar için af ve büyük bir ödül vardır."},{"n":4,"t":"Sana odaların arkasından bağıranların çoğu, aklı ermez kimselerdir."},{"n":5,"t":"Eğer onlar, sen yanlarına çıkıncaya kadar sabretselerdi kendileri için daha iyi olurdu. Allah çok affedicidir; çok merhamet sahibidir."},{"n":6,"t":"Ey inananlar! Eğer bir fâsık/yalan haber taşıyan size bir haber getirirse, onun doğruluğunu araştırınız. Yoksa bilmeden bir topluluğa kötülük edersiniz de, sonra yaptıklarınıza pişman olursunuz."},{"n":7,"t":"Biliniz ki, aranızda Allah`ın peygamberi vardır. Şâyet o, birçok işte size uysaydı, sıkıntıya düşerdiniz. Fakat Allah, size imanı sevdirdi ve onu gönüllerinize çekici kıldı. Küfrü, fıskı ve isyanı da size çirkin gösterdi. İşte, doğru yolda olanlar bunlardır."},{"n":8,"t":"Allah, bunu katından bir lütuf ve nimet olarak yapmıştır. Allah her şeyi bilir ve her işinde hikmet vardır."},{"n":9,"t":"Müminlerden iki grup birbiriyle savaşırlarsa, aralarını düzeltiniz. Şâyet biri ötekine saldırırsa, Allah`ın emrine dönünceye kadar, saldıran tarafla savaşınız. Eğer dönerlerse, artık aralarını adaletle düzeltiniz ve adaletli davranınız. Şüphesiz Allah, âdil davrananları sever."},{"n":10,"t":"Müminler ancak kardeştirler. Öyleyse kardeşlerinizin arasını düzeltiniz ve Allah`a saygı duyunuz ki merhamet olunasınız."},{"n":11,"t":"Ey iman edenler! Hiçbir topluluk başka bir toplulukla alay etmesin. Olur ki alay edilenler, onlardan daha iyi olabilirler. Kadınlar da başka kadınlarla alay etmesinler. Alay edilen kadınlar, kendilerinden daha iyi olabilirler. Birbirinizi ayıplamayınız. Birbirinize kötü lakaplar takmayınız. İmandan sonra, fâsık diye anılmak ne kötüdür! Kim tövbe etmezse işte onlar zâlimlerdir."},{"n":12,"t":"Ey iman edenler! Zandan çok sakınınız. Çünkü zannın bir kısmı günahtır. Birbirinizin ayıplarını araştırmayınız. Birbirinizin arkasından gıybet etmeyiniz. Sizden biri, ölü kardeşinin etini yemekten hoşlanır mı? İşte bakın, bundan tiksindiniz. Allah`a saygı duyunuz. Şüphesiz Allah tövbeleri kabul edendir; merhamet sahibidir."},{"n":13,"t":"Ey insanlar! Doğrusu biz sizi bir erkek ve bir kadından yarattık ve birbirinizi tanıyıp kaynaşasınız diye sizi milletlere ve kabilelere ayırdık. Şüphesiz Allah katında en üstün olanınız, Allah`a en çok saygı duyanınızdır. Allah her şeyi bilendir; her şeyden haberdar olandır."},{"n":14,"t":"“Siz iman etmediniz, ama ‘boyun eğdik` deyiniz. Henüz iman kalplerinize girmedi. Eğer Allah`a ve Peygamberine itaat ederseniz, Allah işlerinizden hiçbir şeyi eksiltmez.” Çünkü Allah, affedicidir; merhamet sahibidir."},{"n":15,"t":"Gerçek müminler, Allah`a ve Peygamberine inanan, sonra şüphe etmeyen ve Allah yolunda mallarıyla, canlarıyla cihad edenlerdir. İşte sözünde duranlar onlardır."},{"n":16,"t":"“Dininizi Allah`a mı öğretiyorsunuz? Allah, göklerde ve yerde ne varsa hepsini bilir. Allah her şeyi bilmektedir.”"},{"n":17,"t":"“Müslüman olmanızı benim başıma kakmayınız. Tersine, eğer gerçekten inanmışsanız, sizi imana ilettiği için Allah, başınıza kaksa yeridir.”"},{"n":18,"t":"Şüphesiz Allah, göklerin ve yerin gaybını bilir. Allah yaptıklarınızı görendir."}],[{"n":1,"t":"Kâf. Şerefli Kur`ân`a andolsun."},{"n":2,"t":"“Bu şaşılacak bir şeydir.”"},{"n":3,"t":"“Biz, ölüp toprak olduktan sonra mı dirileceğiz? Bu, akla uzak bir dönüştür.”"},{"n":4,"t":"Şüphesiz biz, toprağın onlardan neyi eksilttiğini biliriz. Katımızda her şeyi saklayan bir kitap vardır."},{"n":5,"t":"Doğrusu onlar, hak kendilerine gelince onu yalanladılar. Şimdi onlar şaşırmış bir haldedirler."},{"n":6,"t":"Üstlerindeki göğü nasıl bina ettiğimize, onu nasıl süslediğimize ve onda hiçbir çatlağın olmadığına bakmazlar mı?"},{"n":7,"t":"Yine, yeryüzünü nasıl döşediğimize, oraya sabit dağlar yerleştirdiğimize ve orada her çeşit bitkileri bitirdiğimize bakmazlar mı?"},{"n":8,"t":"Bunları, yönelen her kul için bir aydınlatma ve öğüt yaptık."},{"n":9,"t":"Gökten bereketli bir su indirip, onunla bahçeler ve biçilecek ekinler bitirdik."},{"n":"10-11","t":"Yarattıklarımıza rızık olarak salkımları birbirine geçmiş yüksek hurma ağaçlarını da onlar için yarattık. O su ile ölü toprağa can verdik. Kabirden çıkış da işte böyledir."},{"n":"12-14","t":"Onlardan önce Nûh kavmi, Ress halkı ve Semûd da yalanlamıştı. ‘Âd ve Firavun ile Lût`un kardeşleri de yalanladılar. Eyke halkı ve Tübba‘ kavmi de. Hepsi peygamberleri yalanladılar da, onları uyardığım şey başlarına geldi."},{"n":15,"t":"İlk yaratmada âcizlik mi gösterdik? Hayır; onlar, yeni bir yaratma hususunda şüphe içindedirler."},{"n":16,"t":"Andolsun insanı biz yarattık. Nefsinin ona neler fısıldadığını biliriz. Biz ona şah damarından daha yakınız."},{"n":17,"t":"İki melek onun sağında ve solunda oturarak yaptıklarını yazmaktadır."},{"n":18,"t":"İnsan hiçbir söz söylemez ki, yanında gözetleyen, yazmaya hazır bir melek bulunmasın."},{"n":19,"t":"Ölüm sarhoşluğu gerçekten gelecek, “İşte ey insan! Bu, senin öteden beri kaçtığın şeydir” denecek."},{"n":20,"t":"Sûr`a üfürülür, işte bu, geleceği vaad edilen gündür."},{"n":21,"t":"Herkes, yanında bir götüren ve tanıkla gelecek."},{"n":22,"t":"“Andolsun, sen bunu görmezden gelmiştin. Derhal senin perdeni kaldıracağız. Bugün senin gözün çok keskindir” denecektir."},{"n":23,"t":"“İşte yanımdaki hazır.” Siz iki melek! “Tüm nankörleri, inatçıları cehenneme atın! Her türlü hayra bütün gücüyle engel olanı, saldırgan şüphecileri de atın. Allah ile beraber başka tanrı kabul edenleri, haydi, böylelerini şiddetli azaba atın.”"},{"n":24,"t":"“İşte yanımdaki hazır.” Siz iki melek! “Tüm nankörleri, inatçıları cehenneme atın! Her türlü hayra bütün gücüyle engel olanı, saldırgan şüphecileri de atın. Allah ile beraber başka tanrı kabul edenleri, haydi, böylelerini şiddetli azaba atın.”"},{"n":25,"t":"“İşte yanımdaki hazır.” Siz iki melek! “Tüm nankörleri, inatçıları cehenneme atın! Her türlü hayra bütün gücüyle engel olanı, saldırgan şüphecileri de atın. Allah ile beraber başka tanrı kabul edenleri, haydi, böylelerini şiddetli azaba atın.”"},{"n":26,"t":"“İşte yanımdaki hazır.” Siz iki melek! “Tüm nankörleri, inatçıları cehenneme atın! Her türlü hayra bütün gücüyle engel olanı, saldırgan şüphecileri de atın. Allah ile beraber başka tanrı kabul edenleri, haydi, böylelerini şiddetli azaba atın.”"},{"n":27,"t":"“Rabbimiz, onu ben azdırmadım. Onun kendisi, dönüşü olmayan bir sapıklık içindeydi.”"},{"n":"28-29","t":"Allah, “Huzurumda tartışmayın. Ben önceden sizi uyarmıştım. Katımda söz değiştirilmez. Ben kullarıma asla haksızlık etmem” diyecek."},{"n":30,"t":"O gün, cehenneme “Doldun mu?” deriz. O da, “Daha var mı?” der."},{"n":31,"t":"Cennet de, takvâ sahiplerine uzak olmayarak iyice yaklaştırılacaktır."},{"n":32,"t":"Size, hatasından dönen ve verdiği sözü tutan herkese, vaad edilen budur."},{"n":33,"t":"Görmediği halde Rahmân`a saygı duyan ve yönelmiş bir kalple gelen herkese mahsustur."},{"n":34,"t":"Oraya esenlikle giriniz. İşte bu, süreli yaşamın başladığı gündür."},{"n":35,"t":"Diledikleri her şey orada vardır. Katımızda dahası da vardır."},{"n":36,"t":"Biz onlardan önce, kendilerinden daha güçlü olan, diyar diyar dolaşan nice nesilleri helâk ettik. Kurtuluş var mı?"},{"n":37,"t":"Şüphesiz ki bunda, aklı olan veya hazır bulunup kulak veren kimseler için bir öğüt vardır."},{"n":38,"t":"Biz gökleri, yeri ve ikisi arasında bulunanları altı günde/evrede/dönemde yarattık, bize hiçbir yorgunluk dokunmadı."},{"n":39,"t":"Onların dediklerine sabret! Güneşin doğumundan önce ve batışından önce Rabbini hamd ile teşbih et/namaz kıl!"},{"n":40,"t":"Gecenin bir kısmında ve secdelerin ardından da O`nu an!"},{"n":41,"t":"Seslenenin yakın bir yerden sesleneceği güne kulak ver!"},{"n":42,"t":"O gün insanlar bu sesi gerçekten işiteceklerdir. İşte bu, çıkış günüdür."},{"n":43,"t":"Şüphesiz biz diriltir ve öldürürüz. Dönüş ancak bizedir."},{"n":44,"t":"O gün yer, onlardan dolayı yarılır da onlar hızla oradan çıkarlar. İşte bu, bize kolay gelen bir toplanmadır."},{"n":45,"t":"O halde onların ne dediklerini en iyi biz biliriz. Sen onların üzerinde bir zorba değilsin. Sen, benim tehdidimden korkanlara Kur`ân ile öğüt ver!"}],[{"n":"1-6","t":"Esip savuran rüzgârlara, yağmur yüklü bulutlara, kolayca akanlara, iş bölümü yapanlara yemin olsun ki, size vaad edilen kesinlikle gerçekleşecektir; ceza da kesinlikle olacaktır."},{"n":7,"t":"Yörüngelere sahip olan göğe yemin olsun ki,"},{"n":8,"t":"Şüphesiz siz çelişkili sözler söylüyorsunuz."},{"n":9,"t":"O sözden dolayı imandan döndürülebilen, döndürülüyor."},{"n":10,"t":"Kahrolsun o koyu yalancılar!"},{"n":11,"t":"Onlar cehalet bataklığında ne yaptıklarından habersizdirler."},{"n":12,"t":"“Ceza günü ne zaman?” diye sorarlar."},{"n":13,"t":"O gün onlar ateşe sokulacaklardır."},{"n":14,"t":"“Azabınızı tadın! Acele gelmesini beklediğiniz şey budur” denir."},{"n":15,"t":"Allah’ın emirlerine karşı gelmekten sakınanlar, cennetlerde ve pınar başlarında bulunacaklar."},{"n":16,"t":"Rablerinin kendilerine verdiğini alarak. Şüphesiz onlar, bundan önce (dünyada) iyilik eden kimseler idiler."},{"n":17,"t":"Onlar, geceleri pek az uyurlardı."},{"n":18,"t":"Seher vakitlerinde de Allah`tan af dilerlerdi."},{"n":19,"t":"Mallarında muhtaç ve yoksullar için bir hak vardı."},{"n":20,"t":"Kesin olarak inananlar için, yeryüzünde âyetler vardır."},{"n":21,"t":"Kendi iç âleminizde de âyetler vardır. Gözlem yapmıyor musunuz?"},{"n":22,"t":"Gökte de rızkınız ve size vaad edilen şeyler vardır."},{"n":23,"t":"Göğün ve yerin Rabbine yemin olsun ki, bu Kur`ân, sizin konuşmanız gibi kesin ve gerçektir."},{"n":24,"t":"İbrâhim`in saygın konuklarının haberi sana geldi mi?"},{"n":25,"t":"Onlar, İbrâhim`in yanına girip selâm vermişlerdi. İbrâhim de selâmı almış, içinden “Bunlar yabancılar” demişti."},{"n":26,"t":"Hemen hanımının yanına giderek, semiz bir dana kebabını getirmişti."},{"n":27,"t":"Onların önüne koyup, “Yemez misiniz?” dedi."},{"n":28,"t":"Hallerinden dolayı içinden bir korku duydu. “Korkma!” dediler ve ona bilgin bir çocuk müjdesi verdiler."},{"n":29,"t":"O esnada, hanımı çığlık atarak, yüzüne vurarak geldi ve “Kısır bir kocakarıdan mı?” dedi."},{"n":30,"t":"`Rabbin böyle buyurdu. Şüphesiz O, hikmet sahibidir, bilendir` dediler."},{"n":31,"t":"İbrâhim, “Ey elçiler! Sizin göreviniz nedir?” dedi."},{"n":32,"t":"“Biz, suçlu bir topluma gönderildik.”"},{"n":33,"t":"“Üzerlerine taşlanmış çamur yağdırmak için.”"},{"n":34,"t":"“Rabbinin katından aşırı gidenler için belirlenmiş taşlardan.”"},{"n":35,"t":"Bunun üzerine orada bulunan müminleri çıkardık."},{"n":36,"t":"Fakat orada bir aile dışında Müslüman bulamadık."},{"n":37,"t":"Acı azabdan korkanlar için orada bir ibret bıraktık."},{"n":38,"t":"Mûsâ`nın başından geçen olaylarda da dersler vardır. Onu apaçık bir delil ile Firavun`a gönderdik."},{"n":39,"t":"Firavun ve yandaşları yüz çevirdi. Firavun, “Bu, bir büyücüdür veya delidir” dedi."},{"n":40,"t":"Sonunda onu ve askerlerini denize attık. O, kendini kınayıp duruyordu."},{"n":41,"t":"‘Âd kavminde de dersler vardır. Onlara kasıp kavuran rüzgârı göndermiştik."},{"n":42,"t":"Üzerinden geçtiği şeyi canlı bırakmıyor, onu kül edip savuruyordu."},{"n":43,"t":"Semûd olgusunda da dersler vardır. Çünkü onlara, “Belli süreye kadar nimetlerden faydalanınız” denilmişti."},{"n":44,"t":"Buna rağmen Rablerinin emirlerine karşı geldiler de bakıp dururlarken onları yıldırım çarptı."},{"n":45,"t":"Ayağa kalkacak güçleri kalmamış, yardım edenleri de olmamıştı."},{"n":46,"t":"Bunlardan önce de, Nûh toplumunu helâk etmiştik. Çünkü onlar yoldan çıkmış bir toplum idiler."},{"n":47,"t":"Göğü kendi kudretimizle biz bina ettik ve biz elbette genişleticiyiz."},{"n":48,"t":"Yeri de döşedik. Ne güzel döşeyiciyiz!"},{"n":49,"t":"Düşünüp öğüt alasınız diye, her şeyi çift yarattık."},{"n":50,"t":"Artık hepiniz Allah`a koşunuz. Şüphesiz ben, sizin için O`nun tarafından gönderilmiş apaçık bir uyarıcıyım."},{"n":51,"t":"Allah ile birlikte başka bir tanrı edinmeyiniz. Şüphesiz ben, sizin için O`nun tarafından gönderilmiş apaçık bir uyarıcıyım."},{"n":52,"t":"Aynen bunların yaptığı gibi, onlardan öncekilere de bir peygamber geldiğinde ona “büyücü” ya da “deli” demişlerdi."},{"n":53,"t":"Onlar bunu nesilden nesile vasiyet mi etmişlerdi? Doğrusu onlar, haddi aşan bir toplumdur."},{"n":54,"t":"Artık onlardan yüz çevir! Bundan sonra sen hiç kınanmazsın."},{"n":55,"t":"Öğüt ver, çünkü öğüt müminlere fayda verir."},{"n":56,"t":"Ben cinleri ve insanları, ancak bana kulluk etsinler diye yarattım."},{"n":57,"t":"Ben onlardan rızık istemiyorum. Beni doyurmalarını da istemiyorum."},{"n":58,"t":"Şüpesiz rızık veren, güç ve kuvvet sahibi olan ancak Allah`tır."},{"n":59,"t":"Bu haksızlığı yapanların, benzerleri gibi elbette azaptan payları vardır. Artık onun acele gelmesini istemesinler."},{"n":60,"t":"Uyarıldıkları günden dolayı vay hallerine o inkârcıların!"}],[{"n":"1-6","t":"Tûr`a, açılmış ince deride yazılı kitaba, imar edilmiş o eve; yükseltilmiş şu tavana, kabaran denize yemin olsun ki…"},{"n":7,"t":"Rabbinin azabı kesinlikle gerçekleşecektir."},{"n":8,"t":"Ona hiçbir engel yoktur."},{"n":9,"t":"O gün, gök şiddetle sallanır."},{"n":10,"t":"Dağlar yerlerinden kopup gider."},{"n":11,"t":"Yalanlayanların vay haline o gün!"},{"n":12,"t":"Onlar bâtıla dalıp eğlenirler."},{"n":"13-14","t":"O gün cehennem ateşine zorla itilirler. Kendilerine, “İşte yalanladığınız ateş budur” denir."},{"n":15,"t":"“Bu bir büyü müdür, yoksa siz mi görmüyorsunuz?”"},{"n":16,"t":"Oraya girin, artık ona dayanmanız da dayanmamanız da sizin için farketmez. Siz sadece yaptığınızın karşılığını görmektesiniz."},{"n":"17-18","t":"Kendilerini Allah`ın emirlerine karşı gelmekten koruyanlar, Rablerinin kendilerine verdiklerinden yararlanarak cennetler ve nimetler içinde olacaklardır. Rableri onları cehennem azabından koruyacaktır."},{"n":19,"t":"“Dizili koltuklara yaslanarak, yaptıklarınızın karşılığı olarak afiyetle yiyiniz, içiniz!” Onlara çok güzel eşler de veririz."},{"n":20,"t":"“Dizili koltuklara yaslanarak, yaptıklarınızın karşılığı olarak afiyetle yiyiniz, içiniz!” Onlara çok güzel eşler de veririz."},{"n":21,"t":"İnananlar ve soyları da imanlı olarak kendilerine uyanları, soyları ile buluştururuz. Onların yaptıklarından hiçbir şeyi eksiltmeyiz. Herkes kazandığına karşılık rehindir."},{"n":22,"t":"Onlara, hoşlarına giden meyvelerden ve etten de veririz."},{"n":23,"t":"Orada karşılıklı kadeh tokuştururlar; ama burada kötü söz de yoktur, günah işleme de."},{"n":24,"t":"Sedefteki inci gibi olan hizmetçileri, etraflarında dolaşırlar."},{"n":25,"t":"Birbirlerine yönelip soru sorarlar."},{"n":26,"t":"“Şüphesiz biz bundan önce ailemizin içerisinde korkardık.”"},{"n":27,"t":"“Allah bize lütfetti ve bizi iliklere işleyen azaptan korudu.”"},{"n":28,"t":"“Gerçekten biz bundan önce O`na yalvarıyorduk. Çünkü asıl iyilik sahibi ve merhamet eden O`dur.”"},{"n":29,"t":"Sen öğüt ver! Rabbinin nimeti sayesinde sen ne kâhinsin ne de bir deli."},{"n":30,"t":"Yoksa onlar, “O, başına bir felaketin gelmesini beklediğimiz bir şair midir?” diyorlar."},{"n":31,"t":"“Bekleyiniz, ben de sizinle beraber bekleyenlerdenim.”"},{"n":32,"t":"Onlara akılları mı bunu emrediyor? Yoksa onlar azgınlar topluluğu mudurlar?"},{"n":33,"t":"Yoksa, “onu kendisi uydurdu” mu diyorlar? Hayır! Onlar inanmıyorlar."},{"n":34,"t":"Eğer doğru iseler onun benzeri bir söz getirsinler."},{"n":35,"t":"Acaba onlar herhangi bir yaratıcı olmadan mı yaratıldılar? Yoksa kendileri mi yaratıcıdırlar?"},{"n":36,"t":"Yoksa, gökleri ve yeri onlar mı yarattılar? Hayır! Onlar kesinlikle inanmıyorlar."},{"n":37,"t":"Yoksa, Rabbinin hazineleri onların yanında mı? Yoksa, her şeye hâkim olan kendileri midir?"},{"n":38,"t":"Yoksa, üzerine çıkıp vahiy dinledikleri bir merdivenleri mi var? Öyleyse onları dinleyenler açık bir mucize getirsin."},{"n":39,"t":"Yoksa kızlar O`nun da oğlanlar sizin mi?"},{"n":40,"t":"Yoksa, sen onlardan bir karşılık mı istiyorsun da onlar bu isteğin altından kalkamıyorlar?"},{"n":41,"t":"Yoksa, gayb onların yanındadır da onlar mı yazıyorlar?"},{"n":42,"t":"Yahut, bir tuzak mı kurmak istiyorlar? Asıl tuzağa düşecek olanlar, inkâr edenlerdir."},{"n":43,"t":"Yoksa, onların Allah`tan başka bir tanrıları mı vardır? Hâşâ! Allah onların ortak koştuklarından uzaktır."},{"n":44,"t":"Gökten düşen bir kütle görseler, “Üst üste yığılmış bulutlardır” derler."},{"n":45,"t":"Artık, çarpılacakları günlerine kavuşuncaya kadar onları kendi hallerine bırak!"},{"n":46,"t":"O gün, tuzakları kendilerine hiçbir fayda vermez ve yardım da görmezler."},{"n":47,"t":"Şüphesiz, zulmedenler için bundan başka bir azap da vardır. Fakat onların çoğu bilmezler."},{"n":48,"t":"Rabbinin hükmüne sabret! Bil ki sen, bizim gözlerimizin önündesin. Kalktığında Rabbini hamd ile tesbih et."},{"n":49,"t":"Gecenin bir kısmında ve yıldızların batışından sonra O`nu tesbih et."}],[{"n":"1-4","t":"Battığı zaman yıldıza andolsun ki, arkadaşınız Muhammed sapmadı, azmadı. O, arzusuna göre de konuşmuyor. Bildirdikleri, kendisine vahyolunan bir vahiyden ibarettir."},{"n":"5-10","t":"Ona, bunu çok güçlü akıl sahibi olan Cebrail öğretmiştir. Doğrulup dikildi. O, en yüksek ufuktaydı. Sonra iyice yaklaştı ve sarktı. İki yayın arası kadar, hatta daha da yakın. Böylece kuluna vahyedeceğini vahyetti."},{"n":"11-18","t":"Kalp gördüğünü yalanlamadı. O`nun gördükleri hakkında onunla tartışıyor musunuz? Andolsun ki Cebrail`i bir başka inişte de görmüştü. Son sınır ağacı, sidretü`l-müntehâ yanında. O ağacın yanında Me`vâ cenneti vardır. Sidre`yi neler kaplamıştı neler! Ne gözü kaydı ne de belirlenen sınırı aştı. Andolsun ki Rabbinin en büyük âyetlerinden bir kısmını gördü."},{"n":19,"t":"Gördünüz mü o Lât ve ‘Uzzâ`yı?"},{"n":20,"t":"Üçüncüleri olan ötekini, Menât`ı."},{"n":"21-22","t":"Demek ki erkek size, dişi Allah`a, öyle mi? O zaman bu, insafsızca bir taksim!"},{"n":"23-24","t":"Bunlar sizin babalarınızın verdiği isimlerden başka bir şey değildir. Allah bu konuda bir delil indirmemiştir. Onlar sadece zanna ve nefislerinin arzularına uymaktadırlar. Halbuki, onlara Rablerinden doğru yolu gösteren bir rehber gelmiştir. Yoksa insan, her aklına eseni yapamaz."},{"n":25,"t":"Ahiret de, bu dünya da yalnız Allah`ındır."},{"n":26,"t":"Göklerde nice melek var ki, Allah, kendilerine izin vermedikçe Allah`ın isteği ve rızası dışında kimseye şefaat edemezler."},{"n":27,"t":"Ahiret hayatına inanmayanlar, meleklere kız adı veriyorlar."},{"n":28,"t":"Halbuki onların bu hususta hiç bilgileri yoktur. Sadece zanna uyuyorlar. Zan ise asla gerçeği ifade etmez."},{"n":29,"t":"Kitabımızdan yüz çevirenlerden ve dünya hayatından başka bir şey istemeyen kimselerden yüz çevir!"},{"n":30,"t":"Onların ilimde aldıkları mesafe bu kadardır. Şüphesiz Rabbin yoldan çıkanı da doğru yola geleni de hakkıyla bilmektedir."},{"n":31,"t":"Göklerde ve yerde olanlar Allah`ındır. Sonunda, işlerini kötü yapanları cezalandıracak ve iyi yapanları da daha güzeli ile ödüllendirecektir."},{"n":32,"t":"Onlar, basit hatalar hariç büyük günahlardan ve yüz kızartıcı davranışlardan kaçınanlardır. Şüphesiz Rabbinin bağışlaması geniştir. O sizi topraktan var ederken de, annelerinizin rahminde saklı bulunduğunuzda da, sizinle ilgili her bilgiye sahiptir. Öyleyse kendinizi temize çıkarmayınız. O, Allah`a saygı duyanı en iyi bilendir."},{"n":33,"t":"Gördün mü yüz çevireni?"},{"n":34,"t":"Az verip sonra vermemekte direneni?"},{"n":35,"t":"Gaybın bilgisi o adamın yanında da, o görüyor mu?"},{"n":36,"t":"Yoksa ona Mûsâ`nın sayfalarındaki şu bilgiler haber verilmedi mi?"},{"n":37,"t":"Sözünü tam olarak yerine getiren İbrâhim`in sayfalarındaki şu bilgiler de mi?"},{"n":38,"t":"“Gerçekten hiçbir günahkar, başkasının günah yükünü yüklenemez.”"},{"n":39,"t":"Bilsin ki, insan için kendi çalışmasından başka bir şey yoktur."},{"n":40,"t":"Çalışması da ileride görülecektir."},{"n":41,"t":"Sonra ona karşılığı tastamam ödenecektir."},{"n":42,"t":"Şüphesiz sonunda varış sadece Rabbine olacaktır."},{"n":43,"t":"Güldürecek ve ağlatacak olan da O`dur."},{"n":44,"t":"Öldürecek ve diriltecek olan da O`dur."},{"n":"45-46","t":"Atıldığı zaman döl suyundan çifti, yani erkeği ve dişiyi yaratan da O`dur."},{"n":47,"t":"Öldükten sonra tekrar diriltme de O`na aittir."},{"n":48,"t":"Zengin eden de yoksul kılan da O`dur."},{"n":49,"t":"Şı‘râ yıldızının Rabbi de O`dur."},{"n":50,"t":"Şüphesiz ‘Âd kavmini O helâk etti."},{"n":51,"t":"Semûd`u da O helâk etti ve geriye hiçbir şey bırakmadı."},{"n":52,"t":"Onlardan önce, Nûh toplumunu da helâk etmiştir. Onların hepsi çok zâlim ve çok azgın kimselerdi."},{"n":53,"t":"Alt-üst olan şehirleri de O böyle yaptı."},{"n":54,"t":"Onları neler kapladı neler!"},{"n":55,"t":"Artık, Rabbinin hangi nimetinden şüphe ediyorsun?"},{"n":56,"t":"Bu peygamber de eski uyarıcılar gibi bir uyarıcıdır."},{"n":"57-58","t":"Kıyamet yaklaştı. Allah`tan başka, onun vaktini ortaya çıkaracak yoktur."},{"n":59,"t":"Şimdi bu kitaba mı hayret ediyorsunuz?"},{"n":60,"t":"Gülüyorsunuz da ağlamıyorsunuz."},{"n":61,"t":"Gaflet içinde oyalanıp duruyorsunuz."},{"n":62,"t":"Haydi! Allah`a secde edip O`na kulluk ediniz!"}],[{"n":"1-2","t":"Kıyamet yaklaşıp ay yarılsa, onlar da bu oluşumu gözleriyle görseler, “Bu devamlı yapılan bir büyüdür” diyerek yüz çevirirler."},{"n":3,"t":"Onlar yalanladılar ve kendi arzularına uydular. Oysa her işin varacağı bir yeri vardır."},{"n":4,"t":"Şüphesiz onlara, geçmiş toplumların haberlerinden, kendilerini caydıracak kadar bilgi gelmiştir."},{"n":5,"t":"Bunlar son derece hikmetli haberlerdir, ama uyarılar işe yaramıyor."},{"n":6,"t":"Öyleyse onlardan yüz çevir. Çağrıcının hoşlanılmayan bir şeye çağıracağı günü bekle!"},{"n":7,"t":"Gözleri korkudan perişan bir vaziyette, etrafa saçılmış çekirgeler gibi bulundukları yerden çıkarlar."},{"n":8,"t":"O davetçiye koşarlar. İnkârcılar, “Bu, çok zor bir gün” derler."},{"n":9,"t":"Onlardan önce Nûh`un toplumu da yalanladı, hem de kulumuzun yalancı olduğuna ısrar ederek. “O, delirdi” dediler ve davetten vazgeçmeye zorlandı."},{"n":10,"t":"Bunun üzerine Rabbine, “Ben yenik düştüm, bana yardım et!” diyerek yalvardı."},{"n":11,"t":"Biz de gök kapılarını, devamlı yağan bir yağmurla açtık."},{"n":12,"t":"Yerden kaynaklar fışkırttık. Her iki su, karar verilmiş bir işin gerçekleşmesi için birleşmişti."},{"n":13,"t":"Nûh`u da, tahtadan yapılmış, çivilerle çakılmış gemiye bindirdik."},{"n":14,"t":"İnkâr edilmiş Nûh`a bir ödül olmak üzere, gemi gözlerimizin önünde akıp gidiyordu."},{"n":15,"t":"Andolsun ki, gemiyi bir ibret olarak bıraktık, ibret alan yok mudur?"},{"n":16,"t":"Benim azabım ve uyarılarım nasılmış?"},{"n":17,"t":"Andolsun ki Kur`ân`ı, düşünenler için kolaylaştırdık. Düşünen var mı?"},{"n":18,"t":"‘Âd toplumu da yalanlamıştı. Benim cezalandırmam ve uyarmam nasıl oldu?"},{"n":19,"t":"Biz onların üzerine, uğursuzluğu devamlı bir günde, dondurucu bir rüzgâr gönderdik."},{"n":20,"t":"O rüzgâr, insanları, sanki köklerinden koparılmış, hurma kütükleri gibi yere seriyordu."},{"n":21,"t":"Nasılmış benim azabım ve uyarılarım?"},{"n":22,"t":"Andolsun ki Kur`ân`ı, düşünenler için kolaylaştırdık. Düşünen var mı?"},{"n":23,"t":"Semûd kavmi de uyarıcıları yalanladı."},{"n":24,"t":"“Aramızdan bir beşere mi uyacağız? O takdirde biz apaçık bir sapıklık ve çılgınlık etmiş oluruz” dediler."},{"n":25,"t":"“Vahiy, aramızda ona mı verildi? Hayır, o yalancı ve şımarığın biridir” dediler."},{"n":26,"t":"Yarın onlar, yalancı ve şımarığın kim olduğunu bileceklerdir."},{"n":27,"t":"Gerçekten, onları denemek için dişi deveyi gönderen biziz. Sen onları gözetle ve sabret!"},{"n":28,"t":"Onlara, suyun aralarında paylaştırdığını haber ver! Her biri, kendi içme sırasında gelsin."},{"n":29,"t":"Arkadaşlarını çağırdılar, o da kılıcını kaptı ve deveyi kesti."},{"n":30,"t":"Nasılmış benim azabım ve uyarılarım?"},{"n":31,"t":"Biz onların üzerine korkunç bir ses gönderdik. Hemen hayvan ağılına konan kuru ot gibi oluverdiler."},{"n":32,"t":"Andolsun ki Kur`ân`ı, düşünenler için kolaylaştırdık. Düşünen var mı?"},{"n":33,"t":"Lût`un toplumu da uyarıcıları yalanladı."},{"n":"34-35","t":"Lût ailesi hariç, biz de onların üzerine taş yağdırdık. Katımızdan bir nimet olarak, Lût ailesini seher vakti kurtardık. Şükredenleri işte böyle ödüllendiririz."},{"n":36,"t":"Andolsun ki, Lût, onları bu yakalayışımıza karşı uyardı. Onlar bu uyarıları şüphe ile karşıladılar."},{"n":37,"t":"Andolsun ki, onlar Lût`tan misafirlerini kendilerine teslim etmesini istediler. Bunun üzerine biz de onların gözlerini kör ettik. “Cezamı ve uyarımı tadın!” dedik."},{"n":38,"t":"Andolsun ki, bir sabah kendilerine, yakalarını bir daha bırakmayacak olan bir azap gelip çattı."},{"n":39,"t":"İşte, azabımı ve uyarımı tadın!"},{"n":40,"t":"Andolsun ki Kur`ân`ı, düşünenler için kolaylaştırdık. Düşünen var mı?"},{"n":41,"t":"Firavun ailesine de uyarıcılar gelmişti."},{"n":42,"t":"Bütün mucizelerimizi yalanladılar. Bunun üzerine biz de, her şeye gücü yeten ve her şeyin üstesinden gelene yaraşır bir biçimde yakaladık."},{"n":43,"t":"Sizin kâfirleriniz onlardan daha mı iyidir? Yoksa sizin için, eski kitaplarda azaptan kurtuluş belgesi mi var?"},{"n":44,"t":"Yoksa onlar, “Biz üstün olan bir toplumuz” mu diyorlar?"},{"n":45,"t":"Yakında o topluluk mağlup olacak ve sırtlarını dönüp kaçacaklardır."},{"n":46,"t":"Doğrusu kıyamet saati onların azap vaktidir. O saat daha dehşetli ve daha acıdır."},{"n":47,"t":"Şüphesiz suçlular bir sapıklık ve çılgınlık içerisindedirler."},{"n":48,"t":"“Cehennemin dokunuşunu tadın!” denir."},{"n":49,"t":"Şüphesiz biz, her şeyi bir ölçüye göre yarattık."},{"n":50,"t":"Bizim buyruğumuz, göz açıp kapama gibi anlık bir iştir."},{"n":51,"t":"Andolsun ki, sizin benzerlerinizi hep helâk ettik. Düşünüp öğüt alan var mı?"},{"n":52,"t":"Yaptıkları her şey kitaplarda mevcuttur."},{"n":53,"t":"Küçük büyük her şey, satır satır yazılmıştır."},{"n":54,"t":"Takvâ sahipleri cennetlerde ve ırmakların kenarlarındadır."},{"n":55,"t":"Güçlü ve Yüce Allah`ın huzurunda, hak meclisindedirler/doğruluk makamındadırlar."}],[{"n":"1-4","t":"Rahmân, Kur`ân`ı öğretti. İnsanı yarattı, ona kendini ifade etmeyi öğretti."},{"n":5,"t":"Güneş ve ay bir hesapla hareket etmektedir."},{"n":6,"t":"Yıldızlar ve ağaçlar secde ederler."},{"n":7,"t":"Göğü yükseltti ve teraziyi/ölçüyü koydu."},{"n":8,"t":"Sakın terazide haksızlık etmeyiniz/ölçüyü bozmayınız!"},{"n":9,"t":"Ölçüyü adaletle tutunuz ve eksik tartmayınız!"},{"n":10,"t":"Yeri de canlılar için hazırlamıştır."},{"n":11,"t":"Orada meyveler ve salkımlı hurma ağaçları vardır."},{"n":12,"t":"Yapraklı taneler ve hoş kokulu bitkiler vardır."},{"n":13,"t":"Şimdi, Rabbinizin yaratılış gücünü nasıl göremezsiniz?"},{"n":14,"t":"Allah, insanı, çömlek gibi pişmiş çamurdan yarattı."},{"n":15,"t":"Cinleri de yalın ateşten yarattı."},{"n":16,"t":"Şimdi, Rabbinizin yaratışını nasıl yalanlayabilirsiniz?"},{"n":17,"t":"O, iki doğunun ve iki batının sahibidir."},{"n":18,"t":"Öyleyse Rabbinizin mevsimlerini nasıl inkâr edersiniz?"},{"n":19,"t":"İki denizi birbirine kavuşmak üzere salıvermiştir."},{"n":20,"t":"Aralarında bir engel vardır, birbirine geçip kavuşmazlar."},{"n":21,"t":"Şimdi, Rabbinizin ilginç tezahürlerini nasıl inkâr edersiniz?"},{"n":22,"t":"İkisinden de inci ve mercan çıkar."},{"n":23,"t":"Şimdi, Rabbinizin süslerinden hangisini inkâr edersiniz?"},{"n":24,"t":"Denizden yüce dağlar gibi yükselen gemiler de O`nundur."},{"n":25,"t":"Şimdi, Rabbinizin suyun akıtma gücünü nasıl inkâr edersiniz?"},{"n":"26-28","t":"Kâinatta bulunan her canlı fânidir. Ancak yüce olan ve ikram sahibi Rabbinizin zatı kalacaktır. Şimdi Rabbinizin hayat kanununu nasıl inkâr edersiniz?"},{"n":29,"t":"Göklerde ve yerde bulunan herkes O`ndan ister. O, her an yaratma halindedir."},{"n":30,"t":"Şimdi, Rabbinizin ilgisini nasıl inkâr edersiniz?"},{"n":"31-32","t":"Ey cinler ve insanlar! Yakında sizin hesabınızı görmek için vakit ayıracağız. Şimdi, Rabbinizin sorgulamasını nasıl yalanlıyorsunuz?"},{"n":"33-34","t":"Ey cin ve insan toplulukları! Göklerin ve yerin etrafından kaçma imkanınız varsa kaçınız. Ama büyük bir güce sahip olmadan kaçamazsınız. Şimdi, Rabbinizin her yerde var olduğunu nasıl inkâr edebilirsiniz?"},{"n":"35-36","t":"İkinizin de üzerine ateşten bir dev ve erimiş bakır/duman göndeririz de, başarılı olamazsınız. Şimdi, Rabbinizin gücünü nasıl inkâr edebilirsiniz?"},{"n":37,"t":"Gök parça parça yarıldığı ve yanık yağ gibi kızıllaştığı zaman."},{"n":38,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":"39-40","t":"İşte o gün, insana da cinne de günahı sorulmaz. Şimdi, Rabbinizin ahiretteki sorgulamasını nasıl inkâr edebilirsiniz?"},{"n":"41-42","t":"Suçlular simalarından tanınır. Perçemlerinden ve ayaklarından yakalanırlar. Şimdi, Rabbinizin adaletini nasıl inkâr edebilirsiniz?"},{"n":"43-45","t":"Onlara, “İşte suçluların yalanladıkları cehennem budur” denir. Onlar, cehennemle kaynar su arasında dolaşıp dururlar. Şimdi, Rabbinizin cezasını nasıl inkâr edebilirsiniz?"},{"n":"46-47","t":"Rabbinin huzurunda durmaktan korkanlar için iki cennet vardır. Şimdi, Rabbinizin ödülünü nasıl inkâr edebilirsiniz?"},{"n":"48-49","t":"Fidanlarla dolu iki cennet. Şimdi, Rabbinizin ahiret nimetlerinden hangisini inkâr edebilirsiniz?"},{"n":"50-51","t":"Onlarda akan iki pınar vardır. Şimdi, Rabbinizin ahiret nimetlerinden hangisini inkâr edebilirsiniz?"},{"n":"52-53","t":"İkisinde de her türlü meyveden iki çeşit vardır. Şimdi, Rabbinizin ahiret nimetlerinden hangisini inkâr edebilirsiniz?"},{"n":"54-55","t":"Hepsi de örtüleri atlastan minderlere yaslanırlar. İki cennetin de meyvesinin devşirilmesi yakındır. Şimdi, Rabbinizin ahiret nimetlerinden hangisini inkâr edebilirsiniz?"},{"n":"56-59","t":"Orada, gözlerini eşlerinden ayırmayan, kendilerinden önce ne insan ne de cin dokunmuş eşler olacaktır. Şimdi, Rabbinizin cennet güzelliklerini nasıl inkâr edebilirsiniz? Onlar sanki yakut ve mercan gibidirler. Şimdi, Rabbinizin cennet güzelliklerini nasıl inkâr edebilirsiniz?"},{"n":"60-61","t":"İyiliğin karşılığı ancak iyiliktir. Şimdi, Rabbinizin adaletini nasıl inkâr edebilirsiniz?"},{"n":"62-63","t":"Bu iki cennetten başka iki cennet daha vardır. Şimdi, Rabbinizin cömertliğini nasıl inkâr edebilirsiniz?"},{"n":"64-67","t":"Onlar koyu yeşil iki cennettir. Şimdi, Rabbinizin ahiret nimetlerinden hangisini inkâr edebilirsiniz? İkisinde de durmadan fışkıran iki kaynak vardır. Şimdi, Rabbinizin ahiret nimetlerinden hangisini inkâr edebilirsiniz?"},{"n":"68-78","t":"İkisinde de her türlü meyveler, hurmalar ve nar vardır. Şimdi, Rabbinizin ahiret nimetlerinden hangisini inkâr edebilirsiniz? İçlerinde huyu ve yüzü güzel hanımlar vardır. Şimdi, Rabbinizin güzelliklerini nasıl inkâr edebilirsiniz? Otağları içinde sahiplerine tahsis edilmiş huriler vardır. Şimdi, Rabbinizin ahiret nimetlerinden hangisini inkâr edebilirsiniz? Bunlara onlardan önce ne bir insan ne bir cin dokunmuştur. Şimdi, Rabbinizin vefasını nasıl inkâr edebilirsiniz? Yeşil yastıklara ve rengarenk halılara yaslanarak sohbet ederler. Rabbinizden daha ne istiyorsunuz? İhtişam sahibi ve cömert olan Rabbinin adı ne yücedir!"}],[{"n":1,"t":"Kıyamet koptuğu zaman."},{"n":2,"t":"Onun kopacağını hiç kimse yalanlayamayacaktır."},{"n":3,"t":"O, kimini alçaltacak, kimini de yükseltecektir."},{"n":"4-7","t":"Yer şiddetle sarsıldığında, dağlar paramparça olup, etrafa saçılan toz haline geldiğinde ve sizler de üç sınıfa ayrıldığınızda."},{"n":8,"t":"Sağ taraftaki mutlu kişiler, ne iyi olacak onların durumları!"},{"n":9,"t":"Sol taraftaki mutsuz kişiler, ne kötü olacak onların halleri!"},{"n":"10-11","t":"Hayır/iyilik işlerinde yarışanlar önde olacaklardır. İşte onlar Allah`a yakın olanlardır."},{"n":12,"t":"Nimet cennetlerindedirler."},{"n":"13-14","t":"Onların çoğu öncekilerden, azı da sonrakilerdendir."},{"n":"15-16","t":"Mücevherlerle işlenmiş divanlar üzerinde karşılıklı olarak yaslanırlar."},{"n":"17-19","t":"Hizmetçileri kadehler, ibrikler ve kaynaktan doldurulmuş bardaklar ile etraflarında devamlı dolaşırlar. Ondan başları ağrımaz ve sarhoş da olmazlar."},{"n":"20-21","t":"Tercih ettikleri meyveler ile, canlarının çektiği kuş etleri ile nimetlendirilirler,"},{"n":"22-24","t":"Yaptıklarına karşılık olarak orada sedefteki inciler gibi güzel gözlü eşler de vardır."},{"n":"25-26","t":"Karşılıklı selâmlaşmadan başka, orada boş ve günah söz duymazlar."},{"n":27,"t":"Sağdakiler; nedir sağdakilerin görecekleri karşılık?"},{"n":"28-33","t":"Dikensiz meyve ağaçları; salkımları sarkmış muz ağaçları, yayılmış gölgelerde, çağlayarak akan sularda, koparılmamış ve yasak edilmemiş birçok meyve ile nimetlendirilirler."},{"n":34,"t":"Yüksek, yumuşak döşeklerdedirler."},{"n":"35-40","t":"Sağdakiler için biz, kadınları yeniden biçimlendiririz. Onları genç kızlar haline getiririz. Eşleri tarafından sevilen yaşıt genç kızlar. Bütün bunlar amel defteri sağından verilenler içindir. Onların birçoğu öncekilerden, birçoğu da sonrakilerdendir."},{"n":41,"t":"Soldakiler; ne yazık o soldakilere!"},{"n":"42-46","t":"İçlerine işleyen bir ateş ve kaynar su içinde serin ve hoş olmayan kapkara dumandan bir gölge altındadırlar. Çünkü onlar bundan önce, varlık içinde sefahete dalmışlardı. Büyük günahı işlemekte ısrar edip dururlardı."},{"n":47,"t":"“Şüphesiz öncekiler de, sonrakiler de, belli bir günün randevusunda bir araya getirileceklerdir.”"},{"n":48,"t":"“Şüphesiz öncekiler de, sonrakiler de, belli bir günün randevusunda bir araya getirileceklerdir.”"},{"n":49,"t":"“Şüphesiz öncekiler de, sonrakiler de, belli bir günün randevusunda bir araya getirileceklerdir.”"},{"n":50,"t":"“Şüphesiz öncekiler de, sonrakiler de, belli bir günün randevusunda bir araya getirileceklerdir.”"},{"n":51,"t":"Sonra, siz ey yalancı sapıklar!"},{"n":"52-53","t":"Kesinlikle zakkum ağacından yiyeceksiniz. Onunla karınlarınızı dolduracaksınız."},{"n":"54-56","t":"Onun üzerine kaynar sudan içeceksiniz. Onu susuz develerin içişi gibi içeceksiniz. İşte, yargı günü onların ziyafeti böyle olacaktır."},{"n":57,"t":"Sizi biz yarattık. Tasdik etmeniz gerekmez mi?"},{"n":"58-59","t":"Düşündünüz mü akıttığınız menileri? Onu siz mi yaratıyorsunuz, yoksa biz mi yaratıyoruz?"},{"n":"60-62","t":"Aranızda ölümü takdir eden biziz. Biz, sizin yerinize benzerlerinizi getirmek ve sizi bilmediğiniz bir alemde tekrar var etmek konusunda önüne geçilebileceklerden değiliz. Andolsun, ilk yaratılışı bildiniz; düşünüp bundan ders almanız gerekmez mi?"},{"n":"63-67","t":"Düşündünüz mü ektiklerinizi? Siz mi onları ekin haline getiriyorsunuz yoksa biz mi? Dileseydik, onu kuru bir çöp yapardık da şaşar kalırdınız. “Doğrusu borç altına girdik, daha doğrusu biz yoksul kaldık” derdiniz."},{"n":"68-70","t":"İçtiğiniz suyu hiç düşündünüz mü? Siz mi onu buluttan indiriyorsunuz yoksa biz mi? Dileseydik onu acı yapardık. Hiç şükretmez misiniz?"},{"n":"71-74","t":"Hiç düşündünüz mü yaktığınız ateşi? Onun ağacını siz mi var ettiniz yoksa biz mi? Biz onu bir ders ve çölden gelip geçenlerin istifadesi için yarattık. Öyleyse Yüce Rabbinin adını övgüyle an!"},{"n":"75-76","t":"Hayır! Yıldızların yerlerine yemin ederim ki, bilirseniz, gerçekten bu büyük bir yemindir."},{"n":"77-78","t":"Şüphesiz bu, değerli bir Kur`ân`dır, korunmuş bir kitaptadır."},{"n":"79-80","t":"Onunla ancak temiz olanlar iletişim kurabilir. Âlemlerin Rabbi tarafından indirilmiştir."},{"n":"81-82","t":"Şimdi siz, böyle bir söze mi leke süreceksiniz? Hakikati yalanlamayı günlük gıdanız olarak mı görüyorsunuz?"},{"n":"83-85","t":"Hele can boğaza dayandığı zaman. Siz o zaman, bakıp duracaksınız. O anda biz, ona sizden daha yakınız, ama göremezsiniz."},{"n":"86-87","t":"Şâyet siz yaptıklarınızın karşılığını görmeyecekseniz, eğer doğru iseniz o çıkmakta olan canı geri çevirsenize."},{"n":"88-89","t":"Eğer ölmek üzere olan kişi, Allah`a yakın olanlardansa, ona rahatlık, güzel kokular ve nimet cenneti vardır."},{"n":"90-91","t":"Eğer sağdakilerdense, kendisine, “Sağdakilerden sana selâm vardır” denilir."},{"n":"92-94","t":"Eğer o kişi, yalanlayan sapıklardansa, o da kaynar su ile ağırlanır ve onun için cehenneme yaslanış vardır."},{"n":"95-96","t":"Şüphesiz bu anlatılanlar kesin gerçeklerdir. Artık Yüce Rabbinin adını övgüyle an!"}],[{"n":1,"t":"Göklerde ve yerde bulunan her şey Allah`ı tesbih etmektedir. O, güçlüdür; hikmet sahibidir.[ 608]"},{"n":2,"t":"Göklerin ve yerin mülkiyeti O`nundur. O, yaşatır ve öldürür. O, her şeye gücü yetendir."},{"n":3,"t":"O, ilktir, sondur, açık olandır, gizli olandır. O, her şeyi bilendir."},{"n":4,"t":"Gökleri ve yeri altı evrede yaratan, sonra bütün bunları hâkimiyeti altına alan O`dur. Toprağa gireni de, topraktan çıkanı da, gökten ineni de, göğe yükseleni de O bilir. Nerede olursanız olunuz O, sizinle beraberdir. Allah yaptığınız her şeyi görmektedir."},{"n":5,"t":"Göklerin ve yerin mülkiyeti yalnız O`nundur. Bütün işler O`na döner."},{"n":6,"t":"Geceyi gündüze, gündüzü de geceye katar. O, sinelerdekini çok iyi bilir."},{"n":7,"t":"Allah`a ve Peygamberine inanınız; sizi üzerlerine yetkili kıldığı mallardan hayra harcayınız. Sizden, inanıp da hayırda harcama yapanlar için büyük bir ödül vardır."},{"n":8,"t":"Size ne oluyor ki Allah`a inanmıyorsunuz? Oysa Peygamber sizi Rabbinize inanmaya çağırıyor. Allah da önceden sizden söz almıştı. İnanacaksanız şimdi inanınız!"},{"n":9,"t":"Sizi karanlıklardan aydınlığa çıkarmak için kuluna apaçık âyetler indiren O`dur. Şüphesiz Allah, size son derece şefkatlidir; merhametlidir."},{"n":10,"t":"Size ne oluyor ki Allah yolunda infak etmiyorsunuz? Oysa göklerde ve yerde bulunan her şey yalnız Allah`a kalacaktır. Sizden o büyük fetihten önce infak edip savaşanlar ile, savaştan sonra infak edip savaşanlar eşit değillerdir. Onların derecesi sonradan infak edip savaşanlardan daha yüksektir. Allah hepsine de güzel şeyleri vaad etmiştir. Allah yaptıklarınızdan haberdardır."},{"n":11,"t":"Kim Allah`a güzel bir borç verirse, Allah onun verdiğini kat kat arttırır ve onun için değerli bir ödül de vardır."},{"n":12,"t":"O gün, mümin erkeklerle mümin kadınları, amellerinin nurları önlerinden ve sağlarından aydınlatıp giderken görürsün. Kendilerine, “Bugün müjdeniz, içinden ırmaklar akan ve süreli kalacağınız cennetlerdir” denilir. İşte büyük kurtuluş budur."},{"n":13,"t":"“Arkanıza dönün de, nur arayın” denilir ve böylece aralarına, kapısı bulunan bir sûr çekilir ki, onun içinde rahmet vardır, dış yüzünde de azap."},{"n":14,"t":"“Evet, ama siz kendi başınızı belâya soktunuz, gözlediniz, şüpheye düştünüz ve kuruntular sizi aldattı. Şeytan, Allah ile sizi aldattı. Nihayet Allah`ın emri geldi çattı.”"},{"n":15,"t":"Bugün artık ne sizden ne de inkâr edenlerden bedel kabul edilir. Varacağınız yer ateştir. Size yaraşan odur. Ne kötü bir dönüş yeridir!"},{"n":16,"t":"Müminlerin Allah`ı anmaları ve O`ndan gelen bu gerçeğe karşı kalplerinin yumuşama zamanı gelmedi mi? İnananlar, kendilerinden önce kitap verilenler gibi olmasınlar. Çünkü onların üzerinden uzun zaman geçip kalpleri katılaşmıştı. Onların çoğu yoldan çıkmışlardır."},{"n":17,"t":"Biliniz ki Allah, kuruduktan sonra toprağa can verir. Şüphesiz, aklınızı kullanasınız diye âyetleri size açık açık anlattık."},{"n":18,"t":"Şüphesiz sadaka veren erkeklerin ve kadınların, Allah`a güzelce ödünç verenlerin, karşılığı kat kat ödenir ve onlara değerli bir ödül de vardır."},{"n":19,"t":"Allah`a ve Peygamberlerine inananlar var ya, özü sözü doğru kişiler onlardır. Rableri katında tanık olanlar onlardır. Onların ödülleri ve nurları vardır. İnkâr edip âyetlerimizi yalanlayanlara gelince, onlar cehennem yârânı olacaklardır."},{"n":20,"t":"Biliniz ki dünya hayatı gerçekte oyun, eğlence, süs, aranızda soy sopla övünme, mal ve çocukların çokluğu ile böbürlenmeden ibarettir. Onun durumu, bitirdiği bitkilerin çiftçileri hayran bıraktığı bir yağmur gibidir. Ardından o bitkiler kurur, sen onları sapsarı olmuş görürsün. Sonra bunlar çerçöpe dönüşürler. Âhirette şiddetli bir azap ile, Allah`ın bağışlaması ve rızası vardır. Dünya hayatı geçici ve yanıltıcı bir şeyden başkası değildir."},{"n":21,"t":"O halde Rabbinizin affı ve cenneti için yarışınız! Allah`a ve peygamberlerine inananlar için hazırlanan bu cennetin eni, gök ve yer genişliğindedir. Bu, Allah`ın hak edene vereceği bir lütuftur. Çünkü Allah büyük lütuf sahibidir."},{"n":22,"t":"Gerek dışınızda, gerek içinizde olup biten musibetler daha biz yaratmadan önce bir kitaba kaydedilir. Bu, Allah`a göre çok basit bir işlemdir."},{"n":23,"t":"Elinizden çıkanlara üzülmeyesiniz ve elinize geçenlere de şımarmayasınız diye bu böyle yapılmıştır. Çünkü Allah, kendini beğenip böbürlenenleri sevmez."},{"n":24,"t":"Onlar cimrilik edip insanlara da cimriliği emrederler. Kim yüz çevirirse bilsin ki, yegâne ihtiyacı olmayan ve övgüye lâyık olan, Allah`tır."},{"n":25,"t":"Andolsun biz peygamberlerimizi açık seçik delillerle gönderdik. İnsanlar adaleti ayakta tutsunlar diye beraberlerinde kitabı ve ölçüyü indirdik. Biz demiri de indirdik. Onda büyük bir kuvvet ve insanlar için faydalar vardır. Bu, Allah`a ve peygamberlerine görmeden yardım edenleri belirlemesi içindir. Şüphesiz Allah güçlüdür; üstündür."},{"n":26,"t":"Andolsun ki biz, Nûh ve İbrâhim`i de gönderdik. Onların soylarına peygamberlik ve kitap verdik. Onların soylarından doğru yolu izleyenler oldu, içlerinden birçoğu da yoldan çıkmışlardır."},{"n":27,"t":"Sonra onların ardından da peygamberlerimizi gönderdik. Meryem oğlu İsa`yı da onların ardından gönderdik ve ona İncil`i verdik. Ona uyanların kalplerine şefkat ve merhamet duyguları koyduk. Ruhbanlığı ise kendileri uydurdular. Biz onu kendilerine yazmadık. Ancak onlar Allah`ın rızasını kazanmak arzusu ile bunu yaptılar; ama buna gereği gibi de uymadılar. Onlardan da inananlara ödüllerini verdik. Onların çoğu yoldan çıkmışlardır."},{"n":28,"t":"Ey kitap ehli inanırları, Allah`a saygı duyunuz; O`nun Peygamberine inanınız ki size rahmetinden iki pay versin, sizin için ışığında yürüyeceğiniz bir nur yaratsın ve sizi affetsin. Allah affedicidir; merhamet sahibidir."},{"n":29,"t":"Kitap ehli, Allah`ın, mesajını kime vereceği üzerinde hiçbir yetkilerinin olmadığını bilmelidirler. Allah, kendi yetkisinde olan peygamberlik görevini dilediğine verir. Allah sonsuz lütuf sahibidir."}],[{"n":1,"t":"Allah, kocası hakkında seninle tartışan ve Allah`a şikâyette bulunan kadının sözünü işitti. Allah, ikinizin konuşmasını işitmektedir. Çünkü Allah her şeyi işitendir; her şeyi görendir."},{"n":2,"t":"Sizden zıhar yapanlar/hanımlarını annelerine benzetenler bilmelidirler ki, o hanımlar onların anaları değillerdir. Onların anaları, ancak kendilerini doğuran kadınlardır. Onlar çirkin ve yalan bir söz söylüyorlar. Bununla beraber Allah affedicidir; bağışlayıcıdır."},{"n":3,"t":"Hanımlarından zıhar ile ayrılmak isteyip sonra söylediklerinden dönenlerin hanımlarıyla cinsel ilişkide bulunmadan önce bir köleyi özgürlüğüne kavuşturmaları gerekir. Size öğütlenen budur. Allah, yaptıklarınızdan haberdardır."},{"n":4,"t":"Köle azad etmeye imkân bulamayan kişi, hanımıyla cinsel ilişkide bulunmadan önce kesintisiz iki ay oruç tutsun. Buna da gücü yetmezse, altmış fakiri doyursun. Bu hafifletme, Allah`a ve Peygamber`ine inanmanızdan dolayıdır. Bunlar Allah`ın hükümleridir. Kâfirler için acı bir azap vardır."},{"n":5,"t":"Âyetleri apaçık indirmemize rağmen Allah`a ve Peygamber`ine karşı çıkanlar, kendilerinden öncekilerin aşağılandıkları gibi aşağılanacaklardır. Sözlerimizi inkâr edenler için alçaltıcı bir azap vardır."},{"n":6,"t":"Allah, onların hepsini dirilttiği gün, kendilerine yaptıklarını haber verecektir. Onlar unutsa da, Allah onları sayıp dökecektir. Allah her şeye şahittir."},{"n":7,"t":"Göklerde ve yerde olan biten her şeyi Allah`ın bildiğinden haberin yok mu? Üç kişinin gizli konuştuğu yerde dördüncüsü mutlaka O`dur. Beş kişinin gizli konuştuğu yerde altıncısı mutlaka O`dur. Bunlardan az veya çok olsunlar ve nerede bulunursa bulunsunlar, mutlaka Allah onlarla beraberdir. Sonra, kıyamet günü onlara yaptıklarını haber verecektir. Doğrusu Allah her şeyi bilendir."},{"n":8,"t":"Gizli konuşmaktan yasaklandıktan sonra o yasaklananı yapmaya kalkışarak günah, düşmanlık ve Peygambere karşı gelmek hususunda gizlice toplananları görmedin mi? Onlar sana geldikleri zaman, seni Allah`ın selâmlamadığı bir şekilde selâmlıyorlar. İçlerinden de, “Söylediklerimiz yüzünden Allah`ın bizi cezalandırması gerekmez miydi?” diyorlar. Cehennem onlara yeter. Oraya gireceklerdir. Orası ne kötü varış yeridir!"},{"n":9,"t":"Ey iman edenler! Gizlice toplanıp konuşursanız; günah, düşmanlık ve Peygambere karşı gelme hususunda toplanmayınız. Ancak iyilik ve takvâ konusunda toplanıp konuşunuz. Huzurunda toplanacağınız Allah`a saygı duyunuz."},{"n":10,"t":"İnananları üzmek için gizli toplantılar yapmak, şeytandandır. Halbuki, Allah`ın izni olmadan şeytan onlara hiçbir zarar veremez. İnananlar yalnız Allah`a güvensinler."},{"n":11,"t":"Ey inananlar! Size, “Meclislerde yer açın!” dendiği zaman yer açın ki Allah da size genişlik versin. Size, “kalkın” dendiği zaman da kalkın ki Allah sizden inananları ve kendilerine bilgi verilenleri derecelerle yükseltsin. Allah, yaptığınız her şeyden haberdardır."},{"n":12,"t":"Ey iman edenler! Peygamberle özel olarak konuşmak istediğinizde, özel konuşmanızdan önce sadaka veriniz. Bu, sizin için daha iyidir ve daha temizdir. Eğer verecek sadaka bulamazsanız, biliniz ki Allah affedicidir; merhamet sahibidir."},{"n":13,"t":"Özel konuşmanızdan önce sadakaları vermekten çekindiniz mi? Çünkü sadaka vermeyi yerine getirmediniz; Allah da sizi affetti. Artık namazı kılınız, zekâtı veriniz, Allah`a ve Peygamberine itaat ediniz. Allah, yaptıklarınızdan haberdardır."},{"n":14,"t":"Allah`ın öfke duyduğu bir toplumu dost edinenleri görmez misin? Onlar ne sizdendir ne de onlardandır. Bile bile yalan yere yemin ederler."},{"n":15,"t":"Allah onlar için çok ağır ceza hazırladı. Çünkü yaptıkları çok kötü bir şeydi."},{"n":16,"t":"Yeminlerini kendilerine kalkan edinip, Allah yolundan alıkoyuyorlar. Artık onlar için alçaltıcı bir azap vardır."},{"n":17,"t":"Ne malları ne de çocukları Allah`a karşı bir yarar sağlar. Onlar cehennemliklerdir, orada süreli kalacaklardır."},{"n":18,"t":"O gün Allah onların hepsini yeniden diriltecek, onlar da dünyada size yemin ettikleri gibi, O`na da yemin edeceklerdir. Kendilerinin bir şey üzerinde olduklarını sanırlar. İyi biliniz ki, onlar gerçekten yalancıdırlar."},{"n":19,"t":"Şeytan onları etkisi altına aldı da kendilerine Allah`ı anmayı unutturdu. İşte onlar şeytanın yandaşlarıdır. İyi biliniz ki, şeytanın yandaşları hep kayıptadırlar."},{"n":20,"t":"Allah`a ve Peygamberine karşı gelenler sürüm sürüm sürüneceklerdir."},{"n":21,"t":"Allah, “Kesinlikle ben ve peygamberim galip geleceğiz” diye yazmıştır. Çünkü Allah güçlüdür; her şeyin üstesinden gelir."},{"n":22,"t":"Allah`a ve âhiret gününe inanan bir toplumun, onlar kendilerinin babaları veya oğulları veya kardeşleri ya da akrabaları olsa da, Allah`a ve Peygamberine karşı gelenlere sevgi beslediklerini göremezsin. İşte onlar, kalplerine imanı yazdığı, katından bir ruh ile desteklediği kimselerdir. Onları içinden ırmaklar akan cennetlere koyacak, orada süreli olarak kalacaklardır. Allah onlardan razı olmuş, onlar da Allah`tan memnun olmuşlardır. İşte onlar Allah`ın tarafında olanlardır. İyi biliniz ki, Allah`ın tarafında olanlar kurtuluşa erenlerdir."}],[{"n":1,"t":"Göklerde ve yerde olanların hepsi Allah`ı anmaktadır. O, mülkünde galiptir; hikmet sahibidir."},{"n":2,"t":"Kitap ehlinden inkâr edenleri, ilk sürgünde yurtlarından çıkaran O`dur. Siz onların çıkacaklarını sanmamıştınız. Onlar da kalelerinin, kendilerini Allah`tan koruyacağını sanmışlardı. Ama Allah, onlara beklemedikleri yerden geliverdi. Allah, yüreklerine korku saldı. Evlerini hem kendi elleriyle, hem de müminlerin elleriyle harap ediyorlardı. Ey ileriyi görenler, bu olayı değerlendiriniz."},{"n":3,"t":"Eğer Allah onlara sürgünü yazmamış olsaydı, elbette onları dünyada başka şekilde cezalandıracaktı. Âhirette de onlar için cehennem azabı vardır."},{"n":4,"t":"Bu, onların Allah`a ve Peygamberine karşı gelmelerinden dolayıdır. Kim Allah`a karşı gelirse, bilsin ki, Allah`ın cezalandırması çetindir."},{"n":5,"t":"Herhangi bir hurma ağacını kesmeniz, yahut onu kökleri üzerinde bırakmanız hep Allah`ın izniyle ve yoldan çıkanları rüsvâ etmek için olmuştur."},{"n":6,"t":"Allah`ın onların mallarından Peygamberine verdiği ganimetlere gelince; siz bu malları elde etmek için ne at koşturdunuz, ne de deve. Fakat Allah peygamberlerini dilediği kimselere galip kılar. Allah`ın gücü her şeye yeter."},{"n":7,"t":"Allah`ın fethedilen ülkeler halkından peygamberine verdiği ganimetler, Allah, Peygamber, yakınları, yetimler, yoksullar ve yolda kalmışlar içindir. Bu taksim, malların içinizden yalnız zenginler arasında dolaşan bir devlet olmaması içindir. Peygamber size ne verdiyse onu alınız, size ne yasakladıysa ondan da sakınınız. Allah`a saygılı olunuz, çünkü Allah`ın azabı çetindir."},{"n":8,"t":"Allah`ın lütfunu ve rızasını kazanma arzusundan, Allah`a ve Peygamberine yardım ettiklerinden dolayı, yurtlarından çıkarılan ve mallarından mahrum edilen fakir muhâcirlere de verilir. İşte onlar özü-sözü doğru kimselerdir."},{"n":9,"t":"Daha önce Medine`yi yurt edinmiş ve gönüllerine imanı yerleştirmiş olan kimseler, kendilerine hicret edenleri severler ve onlara verilenlerden dolayı içlerinde bir rahatsızlık hissetmezler. Kendileri ihtiyaç içinde olsalar bile muhâcirleri kendilerine tercih ederler. Kim nefsinin kıskançlığından korunursa, işte onlar kurtuluşa erenlerdir."},{"n":10,"t":"“Ey Rabbimiz! Bizi ve bizden önce inanan kardeşlerimizi bağışla. Kalplerimizde, inananlara karşı hiçbir kin bırakma! Ey Rabbimiz! Şüphesiz sen çok şefkatlisin; çok merhametlisin."},{"n":11,"t":"Münafıkların, kitap ehlinden inkâr eden kardeşlerine, “Eğer siz yurdunuzdan çıkarılırsanız, kesinlikle biz de sizinle birlikte çıkacağız. Sizin aleyhinizde kimseye asla uymayacağız. Eğer sizinle savaşırlarsa kesinlikle size yardım edeceğiz” dediklerinden haberin yok mu? Allah onların göz göre göre yalan söylediklerine tanıklık ediyor."},{"n":12,"t":"Kitap ehlinin kâfirleri yurtlarından çıkarılsalar, münafıklar onlarla beraber çıkmazlar. Eğer onlarla savaşırlarsa onlara yardım etmezler. Onlara yardım etmeye çalışsalar bile arkalarını dönüp kaçarlar. Sonra yardım da görmezler."},{"n":13,"t":"Kesinlikle, siz onların kalplerine Allah`tan daha çok korku salmaktasınız. Bunun sebebi, onların, anlamayan bir toplum olmalarıdır."},{"n":14,"t":"Onlar sizinle topluca savaşamazlar. Ancak surla çevrilmiş kalelerde veya surların arkasından savaşırlar. Kendi aralarındaki düşmanlıkları şiddetlidir. Sen onları birlik sanırsın, oysa kalpleri darmadağınıktır. Bunun sebebi onların akıllarını kullanmayan bir toplum olmalarıdır."},{"n":15,"t":"Onların durumu, kendilerinden az önce geçmiş ve yaptıklarının cezasını tatmış olanlara benzemektedir. Onlara acıklı bir azap vardır."},{"n":16,"t":"Münafıklar şeytan gibidirler. Çünkü şeytan insana, “İnkâr et” der. İnsan inkâr edince de, “Ben senden uzağım; çünkü ben, âlemlerin Rabbi olan Allah`tan korkarım” der."},{"n":17,"t":"Böylece her ikisinin de âkıbeti, süreli olarak kalacakları ateş olur. İşte bu, zâlimlerin cezasıdır."},{"n":18,"t":"Ey iman edenler! Allah`tan sakının ve herkes yarına ne hazırladığına baksın. Allah`tan sakının! Çünkü Allah yaptıklarınızdan haberdardır."},{"n":19,"t":"Allah`ı unutan ve bu yüzden Allah`ın da onlara kendilerini unutturduğu kimseler gibi olmayınız! Onlar yoldan çıkanlardır."},{"n":20,"t":"Ateşe mahkûm olanlar ile cenneti hak edenler eşit olamazlar. Cenneti hak edenler kurtuluşa erenlerdir."},{"n":21,"t":"Bu Kur`ân`ı bir dağa indirmiş olsaydık, Allah korkusundan onu baş eğmiş, çatlamış, yarılmış görürdün. Bu misalleri, düşünmeleri için insanlara anlatıyoruz."},{"n":22,"t":"O Allah, kendisinden başka tanrı olmayandır. Görülen ve görülmeyen her şeyi bilir. O, rahmetin ve merhametin kaynağıdır."},{"n":23,"t":"O Allah, kendisinden başka tanrı olmayandır. O, mülkün sahibi ve hâkimidir. Kutsal kurtuluşun tek kaynağıdır. Güven verendir, iman bağışlayandır. Görüp gözetendir. Güçlüdür, istediğini zorla yaptırandır. Büyüklükte eşi olmayandır. Allah, onların eş koştuklarından uzaktır."},{"n":24,"t":"O Allah, yaratan, yoktan var eden ve yarattıklarına şekil verendir. En güzel isimler O`nundur. Göklerde ve yerde her şey O`nu övgüyle anar. O`nun her şeye gücü yeter; hikmet sahibidir."}],[{"n":1,"t":"Ey inananlar! Benim de düşmanım, sizin de düşmanınız olan kimseleri dost edinmeyiniz. Onlar, size gelen gerçeği inkâr ettikleri, Rabbiniz Allah`a inandığınızdan dolayı Peygamberi ve sizi yurdunuzdan çıkardıkları halde, siz onlara sevgi iletiyorsunuz. Benim yolumda savaşmak ve benim rızamı kazanmak için yurdunuzdan çıktığınız halde, içinizde onlara sevgi gizliyorsunuz. Oysa ben sizin gizlediğiniz ve açığa vurduğunuz her şeyi bilirim. Sizden kim bunu yaparsa doğru yoldan sapmış olur."},{"n":2,"t":"Onlar sizi ele geçirseler, size düşman olurlar; size ellerini, dillerini kötülükle uzatırlar ve inkâr etmenizi isterler."},{"n":3,"t":"Kıyamet günü, akrabanız ve çocuklarınız size fayda vermez. Allah aranızı ayırır. Allah, yaptıklarınızı görmektedir."},{"n":4,"t":"“Biz, sizden ve Allah`tan başka taptıklarınızdan uzak kimseleriz. Sizi kabul etmiyoruz. Siz tek Allah`a inanıncaya kadar, aramızda asla ortadan kalkmayacak düşmanlık ve kin baş göstermiştir.” Ancak İbrâhim`in babasına, “Senin için bağışlanma dileyeceğim. Allah`a karşı senin için hiçbir şey yapamam” demesi istisnadır. Onlar, “Ey Rabbimiz! Sana güvendik, yalnız sana yöneldik ve sonunda dönüş sanadır” diyerek dua etmişlerdi."},{"n":5,"t":"“Ey Rabbimiz! Bizi, inkâr edenlerin oyuncağı durumuna getirme, bizi bağışla! Şüphesiz senin gücün her şeye yeter; her işinde hikmet vardır.”"},{"n":6,"t":"Andolsun ki sizin için, Allah`ı ve âhiret gününü umanlar için onlarda kesinlikle güzel bir örnek vardır. O halde kim örnek almaktan yüz çevirecek olursa, bilsin ki Allah`ın hiçbir şeye ihtiyacı yoktur; bütün övgüler O`nadır."},{"n":7,"t":"Allah`ın, sizin ile, inkâr edenlerden düşman olduklarınız arasında bir sevgi oluşturması ihtimal dahilindedir. Allah`ın buna gücü yeter. Allah affedendir; merhamet sahibidir."},{"n":8,"t":"Allah, sizinle din konusunda savaşmayan ve sizi yurtlarınızdan çıkarmayanlara iyilik yapmanızı ve adaletli davranmanızı yasaklamaz. Çünkü Allah, âdil olanları sever."},{"n":9,"t":"Allah sadece, sizinle din konusunda savaşanları, sizi yurdunuzdan çıkaranları ve sizin çıkarılmanıza yardımcı olanları dost edinmenizi yasaklar. Kim onları dost edinirse, işte onlar zâlimlerin ta kendileridir."},{"n":10,"t":"Ey iman edenler! Mümin kadınlar hicret ederek size geldiklerinde onları imtihan ediniz. Allah onların imanlarını daha iyi bilir. Eğer siz de onların inanmış kadınlar olduklarının farkına varırsanız, onları kâfirlere geri göndermeyiniz. Bunlar kâfirlere helâl değildir. Kâfirler de bu hanımlara helâl değildir. Hicret eden kadınlara, kâfir kocalarının sarfettiklerini geri veriniz. Mehirlerini kendilerine verdiğiniz takdirde onlarla evlenmenizde bir günah yoktur. Kâfir kadınları nikâhınızda tutmayınız ve sarfettiğinizi isteyiniz; onlar da sarfettiklerini istesinler. Allah`ın hükmü budur. O, aranızda hükmeder. Allah bilendir; hikmet sahibidir."},{"n":11,"t":"Eğer birinizin eşi inkârcılara kaçar, ardından onlarla savaşıp ganimet elde ederseniz, eşleri kaçanlara, harcadıkları kadar veriniz. İnanmış olduğunuz Allah`ın emirlerine karşı gelmekten sakınınız."},{"n":12,"t":"Ey Peygamber! İnanmış kadınlar, sana gelip, Allah`a hiçbir şeyi ortak koşmayacaklarına, hırsızlık yapmayacaklarına, zina etmeyeceklerine, çocuklarını öldürmeyeceklerine, kimseye asla iftira etmeyeceklerine ve iyi olan hiçbir işte sana karşı gelmeyeceklerine dair biat etmek istediklerinde, onların biatını kabul et. Onlar için Allah`tan af dile. Şüphesiz Allah affedicidir; merhamet sahibidir."},{"n":13,"t":"Ey iman edenler! Allah`ın gazap ettiği bir toplumu dost edinmeyiniz! Zira onlar, kâfirler kabirlerindekilerden ümit kestikleri gibi, âhiretten ümit kesmişlerdir."}],[{"n":1,"t":"Göklerde ve yerde bulunanların tümü Allah`ı tesbih etmektedir/anmaktadır. O güçlüdür; hikmet sahibidir."},{"n":"2-3","t":"Ey iman edenler! Yapmayacağınız şeyleri niçin söylüyorsunuz? Yapmayacağınız şeyleri söylemeniz, Allah katında büyük bir nefretle karşılanır."},{"n":4,"t":"Allah, kendi yolunda, malzemesi birbirine kaynamış binalar gibi saf bağlayarak savaşanları sever.”"},{"n":5,"t":"“Ey kavmim! Niçin beni üzüyorsunuz? Oysa, siz benim Allah`ın size gönderdiği peygamber olduğumu biliyorsunuz.” Onlar yoldan sapınca, Allah da kalplerini saptırmıştı. Allah günaha gömülüp giden bir toplumu doğru yola iletmez."},{"n":6,"t":"Meryem oğlu İsâ da, “Ey İsrâiloğulları! Ben, Allah`ın size gönderilmiş peygamberiyim. Benden önce gelen Tevrat`ı doğrulayıcı ve benden sonra gelecek Ahmed adında bir peygamberi müjdeleyici olarak gönderildim.” Fakat İsa`nın müjdelediği peygamber onlara apaçık kanıtlar getirince, “Bu, apaçık bir büyüdür” dediler."},{"n":7,"t":"İslâm`a çağrıldığı halde Allah hakkında asılsız şeyler uydurandan daha zâlim kimdir? Allah, zâlimler topluluğunu doğru yola iletmez."},{"n":8,"t":"Ağızlarıyla Allah`ın nurunu söndürmek istiyorlar; oysa kâfirler hoşlanmasa da Allah nurunu tamamlayacaktır."},{"n":9,"t":"Müşrikler istemeseler de, dinini bütün dinlere üstün kılmak için Peygamberini hidayet ve hak din ile gönderen Allah`tır."},{"n":10,"t":"Ey iman edenler! Sizi acıklı bir azaptan kurtaracak bir ticareti size göstereyim mi?"},{"n":11,"t":"Allah`a ve Peygamberine inanır, Allah yolunda malınız ve canınızla cihad ederseniz, bu sizin iyiliğinizedir; keşke bilseydiniz!"},{"n":12,"t":"Eğer böyle yaparsanız, Allah sizin günahlarınızı affeder, sizi içinden ırmaklar akan cennetlere, Adn cennetlerindeki güzel meskenlere koyar. İşte, en büyük kurtuluş budur."},{"n":13,"t":"Hoşlanacağınız diğer bir şey de Allah`ın yardımı ve yakın bir fetihdir. İnananları müjdele!"},{"n":14,"t":"“Allah yolunda benim yardımcılarım kimlerdir?” Havâriler, “Allah`ın yardımcıları biziz” demişlerdi. Böylece, İsrâiloğulları`ndan bir grup inanmış, bir grup da inkâr etmişti. Biz, inananları düşmanlarına karşı destekledik de onlar galip geldiler."}],[{"n":1,"t":"Göklerde ve yerde olanların hepsi, mülkün sahibi, kutsal kurtuluşun tek kaynağı, kudret ve hikmet sahibi Allah`ı tesbih ediyor/anıyor."},{"n":2,"t":"Ümmîlere/cahillere, kendilerine Allah`ın âyetlerini okuyan, onları arındıran, onlara kitabı ve hikmeti öğreten içlerinden bir peygamberi gönderen O`dur. Onlar, bundan önce apaçık bir sapıklık içindeydiler."},{"n":3,"t":"Peygamberi, müminlerden henüz kendilerine ulaşmamış bulunan diğer insanlara da göndermiştir. O`nun her şeye gücü yeter; her işinde hikmet vardır."},{"n":4,"t":"Peygamberlik yetkisi, Allah`ın lütfudur. Onu kullarından dilediğine verir. Allah büyük lütuf sahibidir."},{"n":5,"t":"Tevrat`ı bilip sonra onun öğretilerine uymayanlar, sırtında kitaplar taşıyan eşek gibidir. Allah`ın âyetlerini yalanlayan toplumun durumu ne kötüdür! Allah böyle zâlim toplumu doğru yola iletmez."},{"n":6,"t":"“Ey Yahudiler! Bütün insanlar değil de, yalnız kendinizin Allah`ın dostları olduğunuzu iddia ediyorsanız, bunda da samimi iseniz, haydi ölümü temenni ediniz.”"},{"n":7,"t":"Onlar yaptıkları yüzünden asla ölümü temenni edemeyecekler. Allah o zâlimleri çok iyi bilmektedir."},{"n":8,"t":"“Kendisinden kaçtığınız ölüm kesinlikle size ulaşacaktır. Sonra, görülmeyen ve görülen her şeyi bilen Allah`a döndürüleceksiniz de O size neler yaptığınızı bildirecektir.”"},{"n":9,"t":"Ey iman edenler! Cuma günü namaza çağırıldığı zaman, hemen Allah`ı anmaya koşunuz ve alış-verişi bırakınız. Eğer bilseniz bu sizin için çok hayırlıdır."},{"n":10,"t":"Namaz bitince artık yeryüzüne dağılınız ve Allah`ın lütfundan aramaya devam ediniz. Allah`ı çokça anınız ki kurtuluşa eresiniz."},{"n":11,"t":"“Allah`ın yanında bulunan, eğlenceden ve ticaretten daha hayırlıdır. Allah rızık verenlerin en üstünüdür.”"}],[{"n":1,"t":"Münafıklar sana geldiklerinde, “Senin kesinlikle Allah`ın peygamberi olduğuna tanıklık ederiz” derler. Allah, senin, O`nun peygamberi olduğunu biliyor ve Allah münafıkların yalancı olduğuna tanıklık ediyor."},{"n":2,"t":"Yeminlerini kalkan yapıp Allah`ın yoluna engel olurlar. Onların yaptıkları ne kötüdür!"},{"n":3,"t":"“İnanırlar, sonra inkâr ederler; bu yüzden kalplerinin üzeri mühürlenir, artık onlar anlamazlar.”"},{"n":4,"t":"Onları gördüğünde, bedenleri hoşuna gider. Konuşsalar sözlerini dinlersin. Onlar sanki elbise giydirilmiş kütükler gibidir. Her sesi kendi aleyhlerine sayarlar. Onlar gerçek düşmanlardır. Onlardan sakının; Allah, onları kahretsin, nasıl da haktan döndürülüyorlar!"},{"n":5,"t":"Onlara, “Geliniz, Allah`ın Peygamberi sizin affınızı dilesin” dendiğinde, sinirlenerek başlarını salladıklarını, yüz çevirip kibirlendiklerini görürsün."},{"n":6,"t":"Onlar için af dilesen de dilemesen de birdir. Çünkü Allah, onları kesinlikle bağışlamayacaktır. Şüphesiz Allah, böylesi yoldan çıkmış toplumu doğruya iletmez."},{"n":7,"t":"Onlar, “Allah`ın peygamberinin yanında bulunanlara yardım etmeyiniz ki etrafından dağılıp gitsinler” diyenlerdir. Göklerin ve yerin bütün hazineleri yalnız Allah`ındır. Fakat münafıklar bu gerçeği anlamazlar."},{"n":8,"t":"Onlar, “Andolsun, eğer Medine`ye dönersek, üstün olan, zayıf olanı oradan mutlaka çıkaracaktır” diyorlardı. Halbuki, asıl üstünlük ancak Allah, Peygamber`i ve müminlerindir. Fakat münafıklar bunu bilmezler."},{"n":9,"t":"Ey iman edenler! Mallarınız ve çocuklarınız sizi Allah`ı anmaktan alıkoymasın. Kimler bunu yaparsa işte onlar ziyana uğrayanlardır."},{"n":10,"t":"Herhangi birinize ölüm gelip de, “Rabbim! Beni yakın bir süreye kadar geciktirsen de sadaka verip iyilerden olsam!” demesinden önce, size verdiğimiz rızıktan infak edin!"},{"n":11,"t":"Allah, eceli geldiğinde hiç kimseyi ertelemez. Allah, yaptıklarınızdan haberdardır."}],[{"n":1,"t":"Göklerde ve yerde olan her şey Allah`ı tesbih eder/anar, kâinatın yönetimi O`na aittir. Bütün övgüler O`na mahsustur. O`nun gücü her şeye yeter."},{"n":2,"t":"Sizi yaratan O`dur. Buna rağmen bazınız inkâr ediyor, bazınız da iman ediyor. Allah yaptıklarınızı görmektedir."},{"n":3,"t":"O, gökleri ve yeri bir amaç için yaratmıştır. Sizi şekillendirdi ve şekillerinizi de güzel yaptı. Dönüş ancak O`nadır."},{"n":4,"t":"Göklerde ve yerde olanları bilir. Gizlediklerinizi ve açığa vurduklarınızı da bilir. Allah, sinelerde olanı bilendir."},{"n":5,"t":"Daha önce inkâr edenlerin haberi size ulaşmadı mı? İşte onlar dünyada yaptıklarının cezasını tattılar. Onlar için elem verici bir azap da vardır."},{"n":6,"t":"Onlara peygamberleri apaçık deliller getirmişlerdi, fakat onlar, “Bir beşer mi bizi doğru yola götürecekmiş?” dediler, inkâr ettiler ve yüz çevirdiler. Allah da hiçbir şeye muhtaç olmadığını gösterdi. Allah zengindir; övgüye lâyıktır."},{"n":7,"t":"“Hayır! Rabbime yemin olsun ki, öldükten sonra, diriltileceksiniz. Sonra yaptıklarınız size haber verilecektir. Bu, Allah`a göre kolaydır.”"},{"n":8,"t":"Onun için, Allah`a, Peygamberine ve indirdiğimiz o nura inanınız! Allah yaptıklarınızdan haberdardır."},{"n":9,"t":"Sizi bir araya toplayacağı günü düşününüz. İşte o gün, kayıp ve kazanç günüdür. Kim Allah`a inanır ve iyi ameller işlerse, Allah onun kötülüklerini örter. Onu, içinde ırmaklar akan, süreli olarak kalacağı cennetlere koyar. İşte büyük kurtuluş budur."},{"n":10,"t":"İnkâr edip, âyetlerimizi yalanlayanlara gelince; onlar cehennemliklerdir. Süreli orada kalacaklardır. Orası ne kötü bir sondur!"},{"n":11,"t":"Allah`ın izni olmadıkça hiçbir musibet isabet etmez. Kim Allah`a iman ederse, Allah onun kalbini doğruya götürür. Allah her şeyi bilendir."},{"n":12,"t":"Allah`a itaat ediniz, Peygambere de itaat ediniz. Yüz çevirirseniz biliniz ki Peygambermize düşen, apaçık bir duyurmadır."},{"n":13,"t":"Allah, kendisinden başka tanrı olmayandır. İnananlar yalnız Allah`a güvenip dayansınlar."},{"n":14,"t":"Ey iman edenler! Eşlerinizden ve çocuklarınızdan size düşman olanlar da vardır. Onlara karşı dikkatli olunuz! Eğer affeder, tedbirinizi alır ve bağışlarsanız, biliniz ki Allah da çok bağışlayıcıdır; çok merhametlidir."},{"n":15,"t":"Mallarınız ve çocuklarınız sadece bir imtihandır. Asıl büyük ödül Allah katındadır."},{"n":16,"t":"O halde gücünüz yettiğince Allah`a saygı duyunuz; dinleyiniz ve itaat ediniz. Kendi iyiliğiniz için infak ediniz. Nefsinin aşırı cimriliğinden korunanlar, işte onlar, kurtuluşa erenlerdir."},{"n":17,"t":"Eğer Allah`a güzel bir ödünç verirseniz, O bunu fazlasıyla size geri ödeyecek ve günahlarınızı affedecektir. Çünkü Allah, iyiliklerin karşılığını verir; çok yumuşak davranır/cezada acele etmez."},{"n":18,"t":"Görünmeyen ve görünen her şeyi bilir. O`nun gücü her şeye yeter ve her işinde hikmet vardır."}],[{"n":1,"t":"Ey Peygamber! Hanımlarınızı boşayacağınız zaman iddetlerini gözeterek boşayınız ve bekleme sürelerini iyice hesap ediniz. Rabbiniz Allah`a saygı duyunuz. Apaçık bir hayâsızlık yapmış olmadıkça onları evlerinden çıkarmayınız. Kendileri de çıkmasınlar. Bunlar Allah`ın koyduğu sınırlardır. Kim Allah`ın koyduğu sınırları aşarsa, aslında kendisine yazık etmiş olur. Bilemezsin ki, belki Allah bundan sonra yeni bir durum ortaya çıkarıverir."},{"n":2,"t":"Sürelerinin sonuna ulaştıklarında onları ya uygun biçimde tutunuz yahut onlardan uygun biçimde ayrılınız. İçinizden âdil iki kişiyi şahit tutunuz ve şahitliği Allah adına özenle yerine getiriniz. İşte, Allah`a ve âhiret gününe inananlara öğütlenen budur. Kim Allah`a saygı duyarsa, O, kendisine bir çıkış yolu yaratır."},{"n":3,"t":"Allah, onu hiç beklemediği yerden rızıklandırır. Kim Allah`a dayanıp güvenirse, O, kendine yeter. Şüphesiz Allah, dilediği şeyi sonuca ulaştırır. Allah her şey için bir ölçü belirlemiştir."},{"n":4,"t":"Kadınlarınızdan âdetten kesilmiş olanlar ile âdet görmeyenler hakkında tereddüt ederseniz onların bekleme süresi üç aydır. Hamile olanların bekleme süreleri ise doğum yapmalarıyla sona erer. Kim Allah`a saygı duyarsa Allah ona işinde bir kolaylık verir."},{"n":5,"t":"İşte bu, Allah`ın size indirdiği buyruğudur. Evet, kim Allah`a saygı duyarsa Allah onun kötülüklerini örter ve ödülünü büyütür."},{"n":6,"t":"O kadınları imkanınıza göre kendi oturduğunuz yerde oturtunuz ve onları baskı altına almak için kendilerine zarar vermeye kalkışmayınız. Eğer hamile iseler, doğum yapıncaya kadar nafakalarını karşılayınız. Sizin hesabınıza çocuğunuzu emzirirlerse onlara karşılığını ödeyiniz ve aranızda güzelce konuşup anlaşınız. Anlaşmakta zorlanırsanız bu durumda çocuğu, o erkeğin hesabına başka bir kadın emzirecektir."},{"n":7,"t":"Varlıklı olan, sahip olduğu imkanlara göre harcasın; rızkı daralmış bulunan da Allah`ın kendisine verdiği kadarından harcasın. Allah kimseyi kendi verdiğinden fazlasıyla yükümlü tutmaz. Allah, bir güçlüğün ardından bir kolaylık sağlayacaktır."},{"n":8,"t":"Nice ülkeler vardır ki, Rablerinin buyruklarına ve peygamberine küstahça karşı çıkmışlardır. Bunun üzerine biz hepsini çetin bir hesaba çektik ve görülmemiş bir cezaya çarptırdık."},{"n":9,"t":"Böylece yaptıklarının cezasını çekmişler ve sonuçları hüsran olmuştur."},{"n":10,"t":"Allah onlar için şiddetli bir azap hazırlamıştır. Ey inanan akıl sahipleri! Allah`a saygı duyunuz. Allah, sizin için kesinlikle bir öğüt indirmiştir."},{"n":11,"t":"İman edip iyi amel işleyenleri karanlıklardan aydınlığa çıkarmak için, size Allah`ın apaçık âyetlerini okuyan bir peygamber gönderdi. Kim Allah`a inanır, iyi amel yaparsa, Allah onu, içinden ırmaklar akan, içinde süreli kalacakları cennetlere sokar. Allah ona gerçekten güzel rızık verecektir."},{"n":12,"t":"Allah, yedi kat göğü ve onların benzerini de yerkürede yaratandır. Düzen bunların arasında cereyan eder. Allah`ın her şeye gücünün yettiğini ve bilgisinin her şeyi kuşattığını bilmeniz için bunlar yeterlidir."}],[{"n":1,"t":"“Ey Peygamber! Niçin Allah`ın sana helâl kıldığı şeyi, eşlerinin hatırı için haram kılıyorsun? Allah affedendir; merhamet sahibidir.”"},{"n":2,"t":"Allah, yeminlerinizi nasıl bozabileceğinizi size açıklamıştır. Allah sizin mevlânızdır. O her şeyi bilendir; hikmet sahibidir."},{"n":3,"t":"Bir gün Peygamber, eşlerinden birine bir sır vermişti. Ama sırdaşı hanım, bunu kumasına anlatınca Allah, Peygamberini durumdan haberdar etmişti. Peygamber de ayrıntıya girmeden, durumu sırdaşı hanımına bildirmişti. Peygamber durumu bu şekilde anlatınca, sırdaşı, “Bunu sana kim söyledi?” diye sormuş, Peygamber de, “Her şeyi bilen, her şeyden haberdar olan Allah” demişti."},{"n":4,"t":"“Ey hanımlar! İkiniz de Allah`a tövbe etmelisiniz. Çünkü kalbinizi bozdunuz. Eğer Peygambere karşı iş birliği yaparsanız, Allah onun koruyucusudur. Cibrîl, duyarlı müminler ve melekler, ona sahip çıkacaktır.”"},{"n":5,"t":"“Peygamber sizi boşayacak olursa, belki de, Rabbi ona sizden daha hayırlı, kendisini Allah`a teslim eden, inanan, gönülden itaat eden, tövbe eden, ibadet eden, oruç tutan, dul ve bakire eşler verir.”"},{"n":6,"t":"“Ey iman edenler! Kendinizi ve ailenizi, yakıtı insanlar ve taşlar olan ateşten koruyunuz! O ateşin başında, acımasız/sert, güçlü, Allah`ın kendilerine emrettiğine karşı gelmeyen, emrolunduklarını yerine getiren melekler vardır.”"},{"n":7,"t":"“Ey inkâr edenler! Bugün özür dilemeyiniz. Size ancak yaptıklarınızın karşılığı verilecektir.”"},{"n":8,"t":"“Ey iman edenler! Gönülden gelen bir tövbe ile Allah`a yöneliniz. Belki Rabbiniz kötülüklerinizi örter. Peygamberi ve onunla beraber iman edenleri utandırmayacağı günde Allah sizi, içinden ırmaklar akan cennetlere koyar. Onların önlerinden ve sağlarından nurları aydınlatıp gider de, ‘Ey Rabbimiz! Nurumuzu bizim için tamamla, bizi affet, çünkü senin her şeye gücün yeter` derler.”"},{"n":9,"t":"“Ey Peygamber! Kâfirlere ve münafıklara karşı cihad et ve onlara sert davran! Onların varacakları yer cehennemdir. Orası varılacak ne kötü bir yerdir!”"},{"n":10,"t":"Allah, kâfirlere, Nûh`un eşi ile Lût`un eşini örnek olarak vermektedir. Bu iki kadın, kullarımızdan iki iyi kişinin nikâhında iken onlara hainlik ettiler. Kocaları, Allah`tan gelen hiçbir şeyi onlardan savamadı. Onlara, “Haydi, ateşe girenlerle beraber siz de girin!” denilecek."},{"n":11,"t":"“Ey Rabbim! Bana katında cennette bir ev yap; beni Firavun`dan ve onun kötü işinden koru; beni zâlimler topluluğundan kurtar!”"},{"n":12,"t":"İffetini korumuş olan, İmran kızı Meryem`i de Allah örnek verdi. “Biz ona ruhumuzdan üfledik.” Rabbinin sözlerini ve kitaplarını tasdik etti. O gönülden itaat edenlerdendi."}],[{"n":1,"t":"Hükümranlığın sahibi olan Allah, yüceler yücesidir ve O`nun gücü her şeye yeter."},{"n":2,"t":"Hanginizin daha güzel/iyi amel yapacağınızı denemek için yoklukla varlığı yaratan, O`dur. O mutlak galiptir; affedicidir."},{"n":3,"t":"Yedi kat göğü birbiri üzerine tabaka tabaka yaratan da O`dur. Rahmân`ın yaratmasında bir uyumsuzluk göremezsin. Gözünü çevir de bak, bir bozukluk görüyor musun?"},{"n":4,"t":"Sonra tekrar tekrar yine bak; sonunda göz, aradığı bozukluğu bulamayıp güçsüz ve bitkin bir halde sana geri dönecektir."},{"n":5,"t":"Andolsun ki, biz en yakın göğü kandillerle süsledik. Onları şeytanlara atılan taşlar yaptık ve onlara alevli ateş azabını hazırladık."},{"n":6,"t":"Rablerini inkâr edenler için cehennem azabı vardır. Orası ne kötü bir varış yeridir!"},{"n":7,"t":"Onlar cehenneme atıldıklarında, onun kaynarken çıkardığı sesi duyacaklar."},{"n":8,"t":"Neredeyse öfkeden çatlayacak! Her ne zaman oraya bir grup atılsa, onun bekçileri onlara, “Size uyarıcı bir peygamber gelmemiş miydi?” diye soracaklar."},{"n":9,"t":"“Evet, doğrusu bize uyarıcı bir peygamber gelmişti; fakat biz onu yalanlamış ve ‘Allah`ın bir şey gönderdiği yok; siz olsa olsa, bir sapıklık içindesiniz!` demiştik.”"},{"n":10,"t":"“Eğer söz dinleseydik, yahut aklımızı kullansaydık, şu çılgın ateş halkı arasında bulunmazdık” diyecekler."},{"n":11,"t":"Böylece günahlarını itiraf ederler. Artık o alevli cehennemin mahkûmları rahmetten mahrumdurlar."},{"n":12,"t":"Fakat, daha görmeden Rablerine saygı duyanlara gelince; onlar için gerçekten hem bağışlanma hem de büyük ödül vardır."},{"n":13,"t":"Sözünüzü ister gizleyiniz, ister açığa vurunuz; biliniz ki Allah sinelerdekini bilmektedir."},{"n":14,"t":"Hiç, yaratan bilmez mi? O, en ince işleri bilmektedir ve her şeyden haberdardır."},{"n":15,"t":"Allah, yeryüzünü yaşanmaya elverişli bir yer yapmıştır. Öyleyse onun her tarafını dolaşıp Allah`ın verdiği rızıktan yiyiniz. Dönüşünüzün O`na olacağını unutmayınız."},{"n":16,"t":"Göktekinin sizi yerin dibine geçirmesinden emin mi oldunuz? O zaman yer şiddetle sarsılır."},{"n":17,"t":"Yoksa, göktekinin başınıza taş yağdırmasından emin mi oldunuz? İşte bu uyarılarımın ne olduğunu yakında anlayacaksınız."},{"n":18,"t":"Onlardan öncekiler de yalanlamışlardı. Bak ki, benim cezalandırmam nasıl olmuştur?"},{"n":19,"t":"Üstlerinde kanatlarını açıp kapayarak uçan kuşları görmezler mi? Onları havada, Rahmân olan Allah`tan başkası tutmuyor. Şüphesiz O, her şeyi görmektedir."},{"n":20,"t":"Rahmân`a karşı size yardım edebilecek askerleriniz kimlerdir? Kâfirler ancak derin bir yanılgı içindedirler."},{"n":21,"t":"Allah size verdiği rızkı keserse, rızık verecek kim vardır? Hayır! Onlar azgınlık ve nefrette inatla direnmektedirler."},{"n":22,"t":"Yüzüstü kapanarak sürünen mi daha doğru gidebilir, yoksa dosdoğru yolda düzgün bir şekilde yürüyen mi?"},{"n":23,"t":"“Sizi yaratan, size işitme duyusu, gözler ve kalpler veren Allah`tır. Ne az şükrediyorsunuz!”"},{"n":24,"t":"“Sizi yeryüzünde çoğaltıp yayan O`dur, ancak O`nun huzuruna gelip toplanacaksınız.”"},{"n":25,"t":"“Eğer doğru söylüyorsanız, bu tehdit ne zaman gerçekleşecek?” diyorlar."},{"n":26,"t":"“O bilgi yalnızca Allah`a mahsustur. Ben ise sadece apaçık bir uyarıcıyım.”"},{"n":27,"t":"Onu yakından gördüklerinde, inkâr edenlerin suratları asılır ve kendilerine, “İşte durmadan istediğiniz azap budur!” denilir."},{"n":28,"t":"“Hiç düşündünüz mü; Allah, beni ve benimle beraber olanları helâk ederse ya da bize merhamet ederse, inkâr edenleri acıklı bir azaptan kim kurtarabilir?”"},{"n":29,"t":"“Bizim Rabbimiz Rahmân`dır. O`na inandık ve yalnız O`na güvendik. Yakında, kimin apaçık bir sapıklık içinde olduğunu bileceksiniz.”"},{"n":30,"t":"“Suyunuz çekilirse, söyleyin bakalım! Size kim bir akarsu getirebilir?”"}],[{"n":1,"t":"Nûn. Kalem ve yazdıklarına yemin olsun ki,"},{"n":2,"t":"Rabbinin nimeti sayesinde sen bir deli değilsin."},{"n":3,"t":"Şüphesiz, senin için kesintisiz bir ödül vardır."},{"n":4,"t":"Sen kesinlikle evrensel bir ahlâk üzeresin."},{"n":"5-6","t":"Hanginizde delilik olduğunu yakında sen de göreceksin, onlar da görecekler."},{"n":7,"t":"Şüphesiz senin Rabbin, yolundan çıkanı daha iyi bilir. Doğru yolda olanı da en iyi O bilir."},{"n":"8-9","t":"Yalanlayanlara uyma! Çünkü onlar isterler ki, sen yağcılık yapasın, onlar da sana yağcılık yapsınlar."},{"n":10,"t":"Yemin edip duran alçağa uyma!"},{"n":11,"t":"Devamlı kusur arayan, laf götürüp getirenlere boyun eğme."},{"n":12,"t":"İyiliğe mani olana, saldırgana, günahkâra da uyma!"},{"n":13,"t":"Kaba ve haşin, bütün bunların ötesinde soysuza da uyma!"},{"n":"14-15","t":"Mal ve çocuklarına güvenip, kendisine okunan âyetlerimize yönelik olarak, “Öncekilerin masalıdır” diyene de uyma!"},{"n":16,"t":"Yakında onun burnunu damgalayacağız."},{"n":17,"t":"Biz, bahçe sahiplerini sınadığımız gibi onları da sınıyoruz. Hani bir vakit onlar, sabahleyin kesinlikle meyvelerini toplayacaklarına yemin etmişlerdi."},{"n":18,"t":"“İnşallah” dememişlerdi."},{"n":19,"t":"Onlar uykudayken Rabbinin katından bir felâket, bostanlarını sardı."},{"n":20,"t":"Bostanları yanıp simsiyah oldu."},{"n":21,"t":"“Eğer ürünlerinizi devşirecekseniz erkenden bostanlarınıza gidiniz!”"},{"n":22,"t":"“Eğer ürünlerinizi devşirecekseniz erkenden bostanlarınıza gidiniz!”"},{"n":23,"t":"“Bugün tarlada, yanınıza hiçbir yoksulun girmesine müsaade etmeyiniz!”"},{"n":24,"t":"“Bugün tarlada, yanınıza hiçbir yoksulun girmesine müsaade etmeyiniz!”"},{"n":"25-28","t":"Amaçlarına ulaşacaklarından emin olarak erkenden gittiler. Harap olmuş bostanı gördüklerinde kimileri, “Biz yanlış yere geldik” dediler. Kimileri de, “Hayır, biz mahvolmuşuz” dediler. İçlerinden en feraset sahibi, “Ben size, niçin Allah`ı anmıyorsunuz, dememiş miydim?” dedi!”"},{"n":29,"t":"“Yazıklar olsun bize, biz azgın kimseleriz. Belki Rabbimiz bize bundan daha iyisini verir. Biz de ümitle O`na yöneleceğiz.”"},{"n":30,"t":"“Yazıklar olsun bize, biz azgın kimseleriz. Belki Rabbimiz bize bundan daha iyisini verir. Biz de ümitle O`na yöneleceğiz.”"},{"n":31,"t":"“Yazıklar olsun bize, biz azgın kimseleriz. Belki Rabbimiz bize bundan daha iyisini verir. Biz de ümitle O`na yöneleceğiz.”"},{"n":32,"t":"“Yazıklar olsun bize, biz azgın kimseleriz. Belki Rabbimiz bize bundan daha iyisini verir. Biz de ümitle O`na yöneleceğiz.”"},{"n":33,"t":"İşte bazı insanları bu dünyada denemek için gönderdiğimiz azap böyledir ama öteki dünyada günahkarların uğrayacağı azap daha da şiddetli olacak, keşke bunu bilselerdi."},{"n":34,"t":"Allah’a sığınıp, emirlerine yapışarak, günahlardan arınıp, azaptan korunanlar, kulluk ve sorumluluk şuuruyla, haklarına ve özgürlüklerine sahip çıkarak şahsiyetli davranan, dinî ve sosyal görevlerinin bilincinde olan mü’minler için, Rablerinin katında nimetlerle dolu Cennetler vardır."},{"n":35,"t":"Öyle ya, Allah`a teslim olanlarla suçluları bir tutar mıyız hiç?"},{"n":36,"t":"Size ne oluyor? Ne biçim hüküm veriyorsunuz?"},{"n":"37-38","t":"Yoksa size ait bir kitap var da, beğendiğiniz her şeyin sizin için olacağını onda mı okuyorsunuz?"},{"n":39,"t":"Yoksa, “Ne hükmederseniz mutlaka sizindir” diye, sizin lehinize olarak tarafımızdan verilmiş, kıyamet gününe kadar geçerli, kesin sözler mi var?"},{"n":40,"t":"Bu iddiayı onların hangisi savunacak?"},{"n":41,"t":"Yoksa, onların ortakları mı var? Sözlerinde doğru iseler, hadi getirsinler ortaklarını!"},{"n":42,"t":"O gün işler zorlaşır ve secdeye davet edilirler; fakat güç yetiremezler."},{"n":43,"t":"Gözleri horluktan aşağı düşmüş bir halde, kendilerini zillet bürür. Halbuki onlar, sapasağlam iken de secdeye davet ediliyorlardı."},{"n":44,"t":"Sen, bu Kur`ân`ı yalan sayanı bana bırak! Biz onları, bilmedikleri bir yönden yavaş yavaş azaba yaklaştırıyoruz."},{"n":45,"t":"Onlara biraz süre tanıyorum. Doğrusu benim planım çok sağlamdır."},{"n":46,"t":"Yoksa, sanki sen onlardan bir ücret istiyorsun da, bu yüzden onlar ağır bir borç altında mı kalıyorlar?"},{"n":47,"t":"Yoksa, gayb bilgileri var da bu bilgileri kendileri mi yazıyorlar?"},{"n":48,"t":"Artık, Rabbinin hüküm vermesi için sabret! Balığın dostu/Yûnus gibi olma! O vakit, üzgün olarak Rabbine yalvarmıştı."},{"n":49,"t":"Rabbi katından ona bir rahmet ulaşmasaydı, kınanmış bir halde o açık araziye atılacaktı."},{"n":50,"t":"Rabbi onu seçip, iyi kullarından kıldı."},{"n":51,"t":"İnkâr edenler Kur`ân`ı duyduklarında, neredeyse seni gözleriyle devireceklerdi. “Bu tam anlamıyla delidir” diyorlardı."},{"n":52,"t":"Oysaki Kur`ân, insanlar için bir öğütten başka bir şey değildir."}],[{"n":1,"t":"Gerçekleşen,"},{"n":2,"t":"Nedir o gerçekleşen?"},{"n":3,"t":"Gerçekleşenin ne olduğunu sen nereden bileceksin."},{"n":4,"t":"Semûd ve ‘Âd kavimleri kıyameti yalanladı."},{"n":5,"t":"Semûd kavmi korkunç bir sarsıntı ile yok edilmişti."},{"n":"6-8","t":"‘Âd toplumuna gelince, onlar soğuk ve şiddetli bir rüzgârla yok edildiler. Allah o rüzgârı yedi gece, sekiz gündüz, aralıksız olarak başlarına sardı. Böylece o halkın, içi boş hurma kütükleri gibi yere serildiklerini görürsün. Onlardan geriye kalan hiçbir kimseyi görüyor musun?"},{"n":9,"t":"Firavun, ondan öncekiler ve alt üst olmuş şehirler de hep o günahı işlediler."},{"n":10,"t":"Rablerinin peygamberine karşı geldiler. O da onları pek şiddetli bir şekilde yakalayıverdi."},{"n":11,"t":"Şüphesiz, su bastığı zaman sizi gemide biz taşıdık."},{"n":12,"t":"Onu sizin için öğüt yapalım ve belleyici kulaklar onu bellesin diye."},{"n":13,"t":"Sûra bir üfleyişle üflendiğinde;"},{"n":14,"t":"Yer ve dağlar yükletilip birbirine bir çarpışla parça parça edildiğinde;"},{"n":15,"t":"İşte o gün olması gereken olacaktır."},{"n":16,"t":"Gök yarılmıştır. O gün o, lime lime sarkmıştır."},{"n":17,"t":"Bütün melekler göğün etrafında olacaklar ve onların üzerinde o gün sekiz melek, Rabbinin egemenlik tahtını taşıyacaklar."},{"n":18,"t":"O gün huzura arz olunursunuz. Size ait hiçbir şey gizli kalmayacak,"},{"n":"19-20","t":"Kitabı sağ tarafından verilenler, “Alın kitabımı okuyun, doğrusu ben hesabımla karşılaşacağımı zaten biliyordum” diyecek."},{"n":21,"t":"“Geçmiş günlerde yaptıklarınızdan dolayı afiyetle yiyiniz, içiniz!”"},{"n":22,"t":"“Geçmiş günlerde yaptıklarınızdan dolayı afiyetle yiyiniz, içiniz!”"},{"n":23,"t":"“Geçmiş günlerde yaptıklarınızdan dolayı afiyetle yiyiniz, içiniz!”"},{"n":24,"t":"“Geçmiş günlerde yaptıklarınızdan dolayı afiyetle yiyiniz, içiniz!”"},{"n":25,"t":"“Keşke kitabım bana verilmeseydi, hesabımın ne olduğunu bilmeseydim, keşke ölüm her şeyi bitirmiş olsaydı; malım bana hiçbir fayda vermedi, bütün gücüm yok oldu.”"},{"n":26,"t":"“Keşke kitabım bana verilmeseydi, hesabımın ne olduğunu bilmeseydim, keşke ölüm her şeyi bitirmiş olsaydı; malım bana hiçbir fayda vermedi, bütün gücüm yok oldu.”"},{"n":27,"t":"`Keşke, ölümle her iş bitmiş olsaydı.`"},{"n":28,"t":"“Keşke kitabım bana verilmeseydi, hesabımın ne olduğunu bilmeseydim, keşke ölüm her şeyi bitirmiş olsaydı; malım bana hiçbir fayda vermedi, bütün gücüm yok oldu.”"},{"n":29,"t":"“Keşke kitabım bana verilmeseydi, hesabımın ne olduğunu bilmeseydim, keşke ölüm her şeyi bitirmiş olsaydı; malım bana hiçbir fayda vermedi, bütün gücüm yok oldu.”"},{"n":30,"t":"“Onu yakalayıp bağlayınız.”"},{"n":31,"t":"ve sonra cehenneme atın."},{"n":32,"t":"“Sonra da onu, yetmiş arşın uzunluğunda bir zincire bağlayınız.”"},{"n":"33-34","t":"“Çünkü o, Yüce Allah`a iman etmezdi, yoksulu doyurmaya teşvik etmezdi.”"},{"n":35,"t":"Bu sebeple bugün burada onun candan bir dostu yoktur."},{"n":"36-37","t":"Ancak günahkârların yediği kanlı irinden başka yiyeceği de yoktur.”"},{"n":"38-39","t":"Görebildikleriniz ve göremedikleriniz üzerine andolsun."},{"n":40,"t":"Şüphesiz Kur`ân, çok şerefli bir elçinin sözüdür."},{"n":"41-42","t":"O, bir şair sözü değildir. Ne de az inanıyorsunuz! Bir kâhin sözü de değildir. Ne de az düşünüyorsunuz!"},{"n":43,"t":"Kur`ân, âlemlerin Rabbi tarafından indirilmiştir."},{"n":"44-47","t":"Eğer Peygamber bize atfen bazı sözler uydurmaya kalkışsaydı, elbette onu bundan dolayı kıskıvrak yakalardık; sonra da onun şah damarını keser atardık. Hiçbiriniz buna engel de olamazdınız."},{"n":"48-49","t":"Şüphesiz Kur`ân, takvâ sahipleri için bir öğüttür. İçinizde onu yalanlayanların olduğunu elbette biliyoruz."},{"n":50,"t":"Elbette Kur`ân, kâfirler için bir iç yarasıdır."},{"n":51,"t":"Kur`ân, gerçekten kesin bilginin ta kendisidir."},{"n":52,"t":"O halde, Yüce Rabbinin ismi ile tesbih et."}],[{"n":"1-3","t":"Birisi, yükselme derecelerinin sahibi olan Allah`tan kâfirlere gelecek olan ve hiç kimsenin savaşamayacağı azabı sordu."},{"n":4,"t":"Melekler ve Rûh ona miktarı elli bin yıl olan bir günde yükselip çıkarlar."},{"n":5,"t":"Şimdi sen güzelce sabret!"},{"n":"6-7","t":"Kâfirler o azabı uzak görüyorlar; biz ise onu yakın görmekteyiz."},{"n":8,"t":"O gün gök, erimiş maden gibi olur."},{"n":9,"t":"Dağlar, atılmış renkli yün gibi olur."},{"n":10,"t":"Dost dostun halini soramaz."},{"n":"11-14","t":"Onlar birbirlerine gösterilecekler. Günahkâr, o günün azabından kurtulmak için çocuklarını fidye vermeyi temenni edecek. Eşini ve kardeşini, mensubu olduğu aşiretini, yeryüzündeki herkesi verip sonunda kendini kurtarmak ister."},{"n":15,"t":"Hayır, hayır; o cehennem, alevli bir ateştir."},{"n":"16-18","t":"Kızaran derileri soyar; sırtını döneni, yüz çevireni ve biriktirip depo edeni çağırır."},{"n":"19-21","t":"İnsanoğlu gerçekten cimri yaratılmıştır. Kendisine fenalık dokunduğunda sızlanır, feryat eder. Kendisine imkân dokunduğunda pinti kesilir."},{"n":22,"t":"Namaz kılanlar, -ki onlar namazlarında devamlıdırlar-."},{"n":23,"t":"Namaz kılanlar, -ki onlar namazlarında devamlıdırlar-."},{"n":"24-25","t":"Mallarında dilenciye ve yoksula ait belli bir hak vardır."},{"n":"26-28","t":"Ceza gününü tasdik ederler. Rablerinin azabından korkarlar; çünkü Rablerinin azabına karşı emin olunmaz."},{"n":"29-31","t":"İffetlerini korurlar. Ancak, eşlerine ya da ellerinin altında bulunanlara karşı onlar kınanmazlar. Ama kim bundan ötesini ararsa, onlar sınırı aşanlardır."},{"n":32,"t":"Emanetlerini ve sözlerini yerine getirirler."},{"n":33,"t":"Şahitliklerini dosdoğru yaparlar."},{"n":34,"t":"Namazlarını titizlikle kılarlar."},{"n":35,"t":"Bunlar, cennetlerde ikram görürler."},{"n":"36-37","t":"O kâfirlere ne oluyor ki, grup grup sağından ve solundan sana doğru koşuyorlar!"},{"n":"38-39","t":"Onlardan her biri nimet cennetine girmeyi mi umuyor? Hayır, öyle değil; biz onları bildikleri şeyden yarattık."},{"n":"40-41","t":"Doğuların ve batıların Rabbine yemin ederim ki, elbette onların yerine daha iyilerini getirmeye bizim gücümüz yeter ve kimse bizim önümüze geçemez."},{"n":42,"t":"Sen onları bırak, uyarıldıkları günlerine kavuşuncaya kadar dalsınlar, oynayadursunlar."},{"n":"43-44","t":"O gün, gözleri önlerine eğik, kendilerini zillet kaplamış bir durumda, sanki bir hedefe doğru koşuyorlarmış gibi kabirlerinden hızla çıkarlar. İşte uyarıldıkları gün bu gündür."}],[{"n":1,"t":"Şüphesiz biz Nûh`u, kendilerine acıklı bir azap gelmeden önce toplumunu uyarması için toplumuna peygamber olarak gönderdik."},{"n":2,"t":"“Ey kavmim! Ben size gönderilen apaçık bir uyarıcıyım. Allah`a kulluk ediniz. Onun emirlerine karşı gelmekten sakınınız ve bana itaat ediniz ki, Allah günahlarınızı affetsin ve size belli bir zamana kadar süre tanısın. Şüphesiz, Allah`ın belirlediği süre dolunca ertelenmez. Keşke bunu bilseydiniz!”"},{"n":3,"t":"“Ey kavmim! Ben size gönderilen apaçık bir uyarıcıyım. Allah`a kulluk ediniz. Onun emirlerine karşı gelmekten sakınınız ve bana itaat ediniz ki, Allah günahlarınızı affetsin ve size belli bir zamana kadar süre tanısın. Şüphesiz, Allah`ın belirlediği süre dolunca ertelenmez. Keşke bunu bilseydiniz!”"},{"n":4,"t":"“Ey kavmim! Ben size gönderilen apaçık bir uyarıcıyım. Allah`a kulluk ediniz. Onun emirlerine karşı gelmekten sakınınız ve bana itaat ediniz ki, Allah günahlarınızı affetsin ve size belli bir zamana kadar süre tanısın. Şüphesiz, Allah`ın belirlediği süre dolunca ertelenmez. Keşke bunu bilseydiniz!”"},{"n":5,"t":"“Ey Rabbim! Doğrusu ben kavmimi gece gündüz tevhid inancına davet ettim. Fakat benim davetim, ancak kaçmalarını arttırdı. Her ne zaman onları senin bağışlamana çağırdıysam, parmaklarını kulaklarına tıkadılar, elbiselerini başlarına çektiler, direndiler ve büyüklendikçe büyüklendiler. Sonra ben onları açıkça çağırdım. Sonra onlara davetimi hem açık ilân ettim, hem de gizlice. Özel olarak kendileriyle konuştum.”"},{"n":6,"t":"“Ey Rabbim! Doğrusu ben kavmimi gece gündüz tevhid inancına davet ettim. Fakat benim davetim, ancak kaçmalarını arttırdı. Her ne zaman onları senin bağışlamana çağırdıysam, parmaklarını kulaklarına tıkadılar, elbiselerini başlarına çektiler, direndiler ve büyüklendikçe büyüklendiler. Sonra ben onları açıkça çağırdım. Sonra onlara davetimi hem açık ilân ettim, hem de gizlice. Özel olarak kendileriyle konuştum.”"},{"n":7,"t":"“Ey Rabbim! Doğrusu ben kavmimi gece gündüz tevhid inancına davet ettim. Fakat benim davetim, ancak kaçmalarını arttırdı. Her ne zaman onları senin bağışlamana çağırdıysam, parmaklarını kulaklarına tıkadılar, elbiselerini başlarına çektiler, direndiler ve büyüklendikçe büyüklendiler. Sonra ben onları açıkça çağırdım. Sonra onlara davetimi hem açık ilân ettim, hem de gizlice. Özel olarak kendileriyle konuştum.”"},{"n":8,"t":"“Ey Rabbim! Doğrusu ben kavmimi gece gündüz tevhid inancına davet ettim. Fakat benim davetim, ancak kaçmalarını arttırdı. Her ne zaman onları senin bağışlamana çağırdıysam, parmaklarını kulaklarına tıkadılar, elbiselerini başlarına çektiler, direndiler ve büyüklendikçe büyüklendiler. Sonra ben onları açıkça çağırdım. Sonra onlara davetimi hem açık ilân ettim, hem de gizlice. Özel olarak kendileriyle konuştum.”"},{"n":9,"t":"“Ey Rabbim! Doğrusu ben kavmimi gece gündüz tevhid inancına davet ettim. Fakat benim davetim, ancak kaçmalarını arttırdı. Her ne zaman onları senin bağışlamana çağırdıysam, parmaklarını kulaklarına tıkadılar, elbiselerini başlarına çektiler, direndiler ve büyüklendikçe büyüklendiler. Sonra ben onları açıkça çağırdım. Sonra onlara davetimi hem açık ilân ettim, hem de gizlice. Özel olarak kendileriyle konuştum.”"},{"n":10,"t":"“Rabbinizden af dileyiniz. Çünkü O, çok bağışlayıcıdır.”"},{"n":"11-12","t":"“Size gökten bol bol yağmur yağdırsın. Sizi, mal ve çocuklarla desteklesin; size bahçeler lütfetsin ve nehirler akıtsın.”"},{"n":"13-14","t":"“Size ne oluyor ki, Allah`a gereken saygıyı göstermiyorsunuz? Halbuki O, sizi halden hale geçirerek yarattı.”"},{"n":"15-16","t":"“Allah`ın yedi göğü birbiri ile nasıl uyumlu yarattığını görmüyor musunuz? Ayı, bunlar içinde bir nur yaptı ve güneşi bir kandil haline getirdi.”"},{"n":"17-18","t":"“Allah sizi bir bitki olarak yerden bitirdi. Sonra sizi oraya gönderecek ve yine oradan çıkaracaktır.”"},{"n":"19-20","t":"“Allah, orada geniş yollar edinip dolaşabilesiniz diye, yeryüzünü sizin için bir sergi yapmıştır.”"},{"n":21,"t":"“Ey Rabbim! Bunlar bana karşı geldiler. Malı ve çocukları kendi zararını arttırmaktan başka işe yarayamayan kişiye uydular ve büyük tuzaklar kurdular.”"},{"n":22,"t":"“Ey Rabbim! Bunlar bana karşı geldiler. Malı ve çocukları kendi zararını arttırmaktan başka işe yarayamayan kişiye uydular ve büyük tuzaklar kurdular.”"},{"n":23,"t":"“Sakın ilâhlarınızı bırakmayınız, hele Vedd`den; Süva‘`dan, Ye‘ûs`tan, Ye‘ûk`tan ve Nesr`den asla vazgeçmeyiniz.”"},{"n":24,"t":"“Bunlar birçoklarını saptırdılar. Sen de bu zâlimlerin sadece şaşkınlıklarını arttır!”"},{"n":25,"t":"Onlar hataları yüzünden boğuldular. Ardından ateşe atılacaklar. Allah`a karşı kendilerine yardım edecek kimseler bulamayacaklar."},{"n":"26-27","t":"“Ey Rabbim! Kâfirlerden yeryüzünde dolaşan hiçbirini bırakma! Çünkü onları bırakırsan, kullarını saptırırlar. Yalnızca ahlaksızlığa ve inkâra yol verirler.”"},{"n":28,"t":"`Rabbim, beni, anamı, babamı, iman etmiş olarak evime, gemime girenleri, mü’min erkekleri ve mü’min kadınları koruma kalkanına al, bağışla. İnkâr ile isyan ile, baskı, zulüm ve işkence ile temel hak ve hürriyetleri kısıtlayan, suikastler tertipleyen, Allah yolunu ve Allah yolundaki faaliyetleri engelleyen zâlimlerin, müşriklerin de yalnızca helâklerini artır!`"}],[{"n":1,"t":"“Biz, doğru yola ileten eşsiz bir Kur`ân dinledik. Bu yüzden ona inandık. Artık Rabbimize hiçbir şeyi ortak koşmayacağız.”"},{"n":2,"t":"“Biz, doğru yola ileten eşsiz bir Kur`ân dinledik. Bu yüzden ona inandık. Artık Rabbimize hiçbir şeyi ortak koşmayacağız.”"},{"n":3,"t":"“Gerçek şu ki, Rabbimizin şanı çok yücedir. Ne bir eş, ne de bir çocuk edinmiştir.”"},{"n":4,"t":"“Bizim aşağılıklarımız, Allah hakkında yakışıksız şeyler söylemektedirler.”"},{"n":5,"t":"“Biz, insanları ve cinleri Allah hakkında asla yalan söylemezler sanmıştık.”"},{"n":6,"t":"İnsanlardan bazıları, bazı cinlere sığınırlardı. Bu, cinlerin sadece azgınlıklarını arttırıyordu."},{"n":7,"t":"Cinler sizin sandığınız gibi Allah`ın hiçbir kimseyi peygamber olarak göndermeyeceğini sanıyorlardı."},{"n":8,"t":"“Doğrusu biz cinler, göğü yokladık, fakat onu sert bekçilerle, alev hüzmeleri ile doldurulmuş bulduk.”"},{"n":9,"t":"“Halbuki biz, göğü dinleyebileceğimiz yerlerde oturuyorduk. Fakat şimdi, kim dinlemek isterse, kendisini gözetleyen bir alev hüzmesi buluyor.”"},{"n":10,"t":"“Yeryüzündekilere kötülük mü yapılmak istendiğini, yoksa Rablerinin onlara bir iyilik mi yapmak istediğini biz bilemeyiz.”"},{"n":11,"t":"“Bizden iyiler de vardır, iyi olmayanlar da. Biz çeşitli gruplara ayrıldık.”"},{"n":12,"t":"“Biz, yeryüzünde Allah`ı asla âciz bırakamayacağımızı ve kaçarak da O`ndan kurtulamayacağımızı kesin olarak anladık.”"},{"n":13,"t":"“Biz o Kur`ân`ı dinleyince ona inandık. Kim Rabbine inanırsa, artık ne bir ödül eksikliğine uğratılmasından ne de haksızlık edilmesinden korkar.”"},{"n":14,"t":"“Bizden Allah`a teslim olanlar da var, hak yoldan sapanlar da var. Müslüman olanlar doğruyu araştıranlardır.”"},{"n":15,"t":"“Hak yoldan sapanlara gelince, onlar cehenneme odun olacaklardır.”"},{"n":"16-17","t":"“Eğer doğru yolda yürüselerdi, onları onun içinde imtihan edelim diye bol su ile suvarırdık. Kim Rabbinin öğüdünden yüz çevirirse, Rabbi onu gittikçe yükselen bir azaba sokar.”"},{"n":18,"t":"Şüphesiz, mescitler yalnız Allah`ındır. Allah ile beraber hiçbir kimseye yalvarmayınız!"},{"n":19,"t":"Allah`ın kulu, Allah`a dua etmek üzere kalktığında, müşrikler/kâfirler neredeyse üzerine çullanacaklardı."},{"n":20,"t":"“Ben yalnız Rabbime ibadet ediyorum ve O`na kimseyi ortak koşmuyorum.”"},{"n":21,"t":"“Ben size ne bir zarar verebilirim, ne de doğruya ulaştırabilirim.”"},{"n":22,"t":"“Beni Allah`tan kimse kurtaramaz ve ben O`ndan başka bir sığınak da bulamam.”"},{"n":23,"t":"“Benim elimden gelen sadece Allah`ın mesajını ulaştırmak ve emirlerini bildirmektir. Kim Allah`a ve Peygamberine karşı gelirse, bilsin ki ona içinde süreli kalacağı cehennem ateşi vardır.”"},{"n":24,"t":"Sonunda uyarıldıkları azabı gördüklerinde, kimin yardımcıları daha zayıf ve taraftarlarının daha az olduğunu bileceklerdir.”"},{"n":25,"t":"“Uyarıldığınız azap yakın mıdır, yoksa Rabbim onun için uzun bir süre mi belirlemiştir, bilmiyorum.”"},{"n":26,"t":"Allah bütün gaybı bilir. Sırlarını kimseye açıklamaz."},{"n":"27-28","t":"Ancak hoşnut olduğu peygamber hariçtir. Çünkü O, peygamberinin önünden ve ardından gözetleyiciler gönderir ki Rablerinin emirlerini tebliğ ettiklerini bilsin. Allah onları çepeçevre kuşatmıştır ve her şeyi bir bir saymıştır."}],[{"n":1,"t":"Ey vahye bürünen!"},{"n":"2-8","t":"Birazı hariç, geceleyin kalk! Tam gece yarısı, biraz erken, biraz geç kalk ve Kur`ân`ı ağır ağır oku! Sana sorumluluğu ağır bir söz vahyedeceğiz. Çünkü gecenin değerlendirilmesi daha oturaklıdır ve söz daha etkilidir. Gündüzleri senin için uzun bir meşguliyet olacaktır. Rabbinin adını an, bütün benliğinle kendini O`na ver!"},{"n":9,"t":"O, doğunun da batının da Rabbi`dir. O`ndan başka ilâh yoktur. Öyle ise yalnız O`nun himayesine sığınınız."},{"n":10,"t":"Onların dediklerine/diyeceklerine sabret ve onlardan güzelce ayrıl!"},{"n":11,"t":"Nimet içinde yüzen o yalancıları/kâfirleri bana bırak ve onlara biraz mühlet ver!"},{"n":"12-14","t":"Şüphesiz, yerin ve dağların şiddetle sarsılacağı, dağların saçılmış kum yığını haline geleceği gün, katımızda prangalar ve cehennem vardır. Boğazı tıkayan yiyecek ve acıklı azap vardır."},{"n":15,"t":"Firavun`a bir peygamber gönderdiğimiz gibi size de, size şahitlik edecek bir peygamber gönderdik."},{"n":16,"t":"Firavun o peygambere karşı gelmişti de, biz onu feci bir şekilde yakalamıştık."},{"n":17,"t":"Eğer inkâr ederseniz, çocukları ihtiyarlatan bir günden nasıl korunursunuz?"},{"n":18,"t":"O gün, gök parça parça olur ve O`nun vaadi gerçekleşmiş olur."},{"n":19,"t":"Şüphesiz bu bir öğüttür. Dileyen Rabbine giden bir yol tutar."},{"n":20,"t":"Hiç şüphen olmasın, Rabbin senin durumunu biliyor. Gecenin üçte ikisinden daha azını, yarısını, üçte birini ayakta geçiriyorsun. Seninle beraber olanlardan bir grup da öyle yapıyor. Allah, gece ve gündüz olanları ölçüp biçiyor. Sizin onu sayamayacağınızı bildiği için, sizin tövbenizi kabul etti. Artık Kur`ân`dan kolayınıza geleni okuyunuz. Sizden hastalar olacağını bildi. Bir kısmınızın Allah`ın lütfundan bir şeyler aramak için gurbete çıkacağını, diğer bir kısmının da Allah yolunda savaşacaklarını bildi. O halde Kur`ân`dan kolay geleni okuyunuz. Namazı kılınız. Zekâtı veriniz. Güzel bir ödünçle Allah`a ödünç veriniz. Kendiniz için önden gönderdiğiniz iyiliğin, Allah katında hayrını daha çok, ödülünü daha büyük olarak bulacaksınız. Allah`tan af dileyin. Şüphesiz Allah çok affedendir; çok merhamet sahibidir."}],[{"n":1,"t":"Ey örtüye bürünerek saklanan Muhammed!"},{"n":2,"t":"Kalk ve uyar!"},{"n":3,"t":"Sadece Rabbini yücelt!"},{"n":4,"t":"Öz benliğini temiz tut!"},{"n":5,"t":"Bütün pisliklerden kaçın!"},{"n":6,"t":"Yaptığını çok göstererek başa kakma!"},{"n":7,"t":"Yalnız Rabbinin emirlerini yerine getirerek, rızasını kazanmak için sabrederek mücadeleye devam et."},{"n":"8-10","t":"Sûr`a üfürüldüğünde, işte o gün, çok çetin, çok zorlu bir gündür. Kâfirler için kolay değildir."},{"n":"11-14","t":"Tek olarak yarattığım, kendisine geniş servet ve gözü önünde duran oğullar verdiğim, kendisi için nimetleri serdikçe serdiğim o kişiyi bana bırak!"},{"n":15,"t":"Bütün bunlardan sonra, kendisine verdiklerimi daha da arttırmamı istiyor."},{"n":16,"t":"Hayır, iş sanıldığı gibi değil. O, bizim âyetlerimize karşı bir inatçı kesildi."},{"n":17,"t":"Ben onu dik bir yokuşa süreceğim."},{"n":"18-20","t":"Zira o, düşündü ve ölçtü biçti. Geberesice, nasıl ölçtü biçti! Lanet olası nasıl ölçtü biçti!"},{"n":21,"t":"“Bu, sadece öncekilerden nakledilen bir büyüdür. Bu yalnızca bir insan sözüdür.”"},{"n":22,"t":"“Bu, sadece öncekilerden nakledilen bir büyüdür. Bu yalnızca bir insan sözüdür.”"},{"n":23,"t":"“Bu, sadece öncekilerden nakledilen bir büyüdür. Bu yalnızca bir insan sözüdür.”"},{"n":24,"t":"“Bu, sadece öncekilerden nakledilen bir büyüdür. Bu yalnızca bir insan sözüdür.”"},{"n":25,"t":"“Bu, sadece öncekilerden nakledilen bir büyüdür. Bu yalnızca bir insan sözüdür.”"},{"n":"26-30","t":"İşte ben onu Sekar`a sokacağım. Sekar`ın ne olduğunu nereden bileceksin? Bırakmayan ve terk etmeyen bir ateştir. İnsanın derisini kavurur; orada on dokuz bekçi vardır."},{"n":31,"t":"Biz cehennemin bekçilerini sırf melekler kıldık. Sayılarını da, inkâr edenlere bir imtihan yaptık ki, kendilerine kitap verilenler Kur`ân vahyinin doğruluğundan emin olsunlar; inananların imanı artsın; kitap verilenler ve inananlar şüphe etmesinler; kalplerinde inanç sorunu olanlar ve inkâr edenler de, “Allah bu örnekle ne demek istedi?” desinler. Allah dileyeni böyle saptırır, dileyeni de doğru yola ulaştırır. Rabbinin ordularını kendisinden başka kimse bilemez. Bunlar insana sadece bir öğüttür."},{"n":"32-34","t":"Hayır! Öyle değil, aya, uzaklaştığında geceye ve ağardığında sabaha andolsun."},{"n":35,"t":"Şüphesiz o Sekar, büyük felâketlerden biridir."},{"n":36,"t":"İnsanlık için bir uyarıcıdır."},{"n":37,"t":"Sizden, ilerlemek ya da geri kalmak isteyenler için."},{"n":38,"t":"Herkes, kazandığına karşılık bir rehindir."},{"n":"39-42","t":"Ancak sağdakiler hariçtir. Onlar cennetlerde olacak ve suçlulara soracaklardır. “Sizi Sekar`a sürükleyen nedir?”"},{"n":43,"t":"“İnanıp kulluk edenlerden değildik. Yoksulları doyurmuyorduk. Bâtıla dalanlarla birlikte dalardık. Ceza gününü yalanlardık. Sonunda ölüm bize geldi çattı.”"},{"n":44,"t":"“İnanıp kulluk edenlerden değildik. Yoksulları doyurmuyorduk. Bâtıla dalanlarla birlikte dalardık. Ceza gününü yalanlardık. Sonunda ölüm bize geldi çattı.”"},{"n":45,"t":"“İnanıp kulluk edenlerden değildik. Yoksulları doyurmuyorduk. Bâtıla dalanlarla birlikte dalardık. Ceza gününü yalanlardık. Sonunda ölüm bize geldi çattı.”"},{"n":46,"t":"“İnanıp kulluk edenlerden değildik. Yoksulları doyurmuyorduk. Bâtıla dalanlarla birlikte dalardık. Ceza gününü yalanlardık. Sonunda ölüm bize geldi çattı.”"},{"n":47,"t":"“İnanıp kulluk edenlerden değildik. Yoksulları doyurmuyorduk. Bâtıla dalanlarla birlikte dalardık. Ceza gününü yalanlardık. Sonunda ölüm bize geldi çattı.”"},{"n":48,"t":"Artık onlara, şefaatçilerin şefaati fayda vermez."},{"n":"49-52","t":"Öyleyken, onlara ne oluyor ki âdeta arslandan ürküp kaçan yaban eşekleri gibi, öğütten yüz çeviriyorlar? Daha doğrusu onların her biri, kendisine açılmış sahifeler verilmesini istiyor."},{"n":53,"t":"Hayır! Aslında onlar âhiretten korkmuyorlar."},{"n":"54-55","t":"Asla! Doğrusu Kur`ân bir hatırlatmadır. Dileyen ondan öğüt alır."},{"n":56,"t":"Böylece zaten onlar Allah`ın dilediğini ancak öğüt almış olurlar. Çünkü saygı duyulması gereken O`dur. Bağışlayacak olan da O`dur."}],[{"n":1,"t":"Hayır! Kıyamet gününe yemin ederim."},{"n":2,"t":"Hayır! Sürekli olarak kendini kınayan nefse yemin ederim."},{"n":3,"t":"İnsan bizim, onun kemiklerini bir araya getiremeyeceğimizi mi sanıyor?"},{"n":4,"t":"Evet, bizim onun parmak uçlarına varıncaya kadar bir araya getirmeye gücümüz yeter."},{"n":5,"t":"“Kıyamet günü ne zamanmış?” diye sorar."},{"n":6,"t":"“Kıyamet günü ne zamanmış?” diye sorar."},{"n":"7-9","t":"İşte, göz kamaştığı, ay tutulduğu, güneşle ay bir araya geldiği zaman!"},{"n":"10-12","t":"O gün insan, “Kaçacak yer neresidir?” diyecektir. Hayır hayır! Kaçıp sığınacak yer yoktur! O gün varıp durulacak yer, sadece Rabbinin huzurudur."},{"n":13,"t":"O gün, insana, yaptıkları da yapmadıkları da haber verilir."},{"n":14,"t":"Doğrusu insan, kendi öz benliğinin gözlemcisidir."},{"n":15,"t":"Her türlü özrünü sayıp dökse de."},{"n":16,"t":"Vahyi ezberlemek için dilini acele kıpırdatma!"},{"n":17,"t":"Şüphesiz onu kalbinde toplamak ve sana okutturmak yalnızca bize aittir."},{"n":18,"t":"Biz onu okuttuğumuz zaman, onun okunuşunu takip et!"},{"n":19,"t":"Sonra onu açıklamak da yalnız bize düşer."},{"n":"20-21","t":"Hayır! Öyle değil, doğrusu sizler bu dünyayı seviyorsunuz ve âhireti bırakıyorsunuz."},{"n":"22-25","t":"Yüzler vardır o gün, parıltılı, Rabbinden beklenti içindedir ve yüzler vardır o gün, asıktır. Bel kemiklerini kıran bir felâkete uğrayacağını anlar."},{"n":"26-30","t":"Hayır! Can köprücük kemiğine dayandığında, “Kim tedavi edecektir?” dendiğinde, onun kesin ayrılış olduğunu anladığında, bacaklar birbirine dolaştığında, o gün sevk yeri yalnızca Rabbinin huzurudur."},{"n":"31-35","t":"Ne doğruladı, ne de kulluk görevini yerine getirdi. Fakat yalanladı ve yüz çevirdi. Sonra da çalım sata sata yürüyerek ailesine gitmişti. Sana yazıklar olsun, yazıklar! Tekrar tekrar sana yazıklar olsun, yazıklar!"},{"n":36,"t":"İnsanoğlu kendisinin başı boş bırakılacağını mı sanıyor?"},{"n":"37-40","t":"O, akıtılan bir meni damlası değil miydi? Sonra döllenmiş hücre. Bu safhada Allah onu yaratıp ona şekil vermişti. Ondan iki cinsi, erkeği ve dişiyi var etmişti. Bunları yapan Allah`ın, ölüleri diriltmeye gücü yetmez mi?"}],[{"n":1,"t":"İnsanın üzerinden, henüz kendisinin anılan bir şey olmadığı uzun bir süre geçmedi mi?"},{"n":2,"t":"Doğrusu biz, insanı imtihan etmek için, döllenmiş yumurtadan yarattık ve onu işiten ve gören bir varlık yaptık."},{"n":3,"t":"Şüphesiz biz ona doğru yolu gösterdik. İster inanır, ister inkâr eder."},{"n":4,"t":"Biz kafirler için zincirler, kelepçeler ve çılgın alevli cehennem hazırladık."},{"n":5,"t":"İyiler de, karışımı kâfur/hoş koku olan bir kadehten içerler."},{"n":6,"t":"Bu Allah`ın iyi kullarının istedikleri yere akmasını sağlayarak içebilecekleri bir pınardır."},{"n":"7-10","t":"Adaklarını yerine getirirler ve kötülüğü yaygın olan bir günden korkarlar. Sevdikleri gıdalardan yoksula, yetime ve esire yedirirler. “Biz, size sırf Allah rızası için yediriyoruz; sizden ne bir karşılık, ne de teşekkür bekliyoruz. Çünkü biz suratsız, çok katı bir günün azabından ötürü Rabbimizden korkarız” derler."},{"n":11,"t":"Bundan dolayı Allah, onları o günün kötülüklerinden koruyacaktır ve onları güler yüze ve mutluluğa kavuşturacaktır."},{"n":12,"t":"Sabretmelerinden dolayı onları cennet ve ipek giysilerle ödüllendirecektir."},{"n":13,"t":"Orada koltuklara yaslanacaklar ve ne sıcak ne de soğuk göreceklerdir."},{"n":14,"t":"Cennetin gölgeleri üstlerine yaklaşmış, meyveleri de aşağı eğdirildikçe eğdirilmiştir."},{"n":"15-16","t":"Çevrelerinde gümüşten kaplar ve kristal kaseler dolaştırılacaktır. Sanki gümüşten yapılmış kristaller. Onları kendi arzularına göre belirleyeceklerdir."},{"n":17,"t":"Onlara orada, karışımı zencefil olan kadehten içirilir."},{"n":18,"t":"Orada, selsebil adı verilen bir pınardan içirilirler."},{"n":19,"t":"Çevrelerinde sürekli hizmetçiler dolaşacaktır. Onları gördüğünde, saçılmış inciler sanırsın."},{"n":20,"t":"Nereye baksan bir nimet ve büyük bir saltanat görürsün."},{"n":21,"t":"Onların üzerlerinde ince yeşil ve kalın ipekten elbiseler olacaktır. Gümüş bilezikler takınacaklardır. Rableri onlara tertemiz bir içecek içirecektir."},{"n":22,"t":"Şüphesiz bu, sizin ödülünüzdür, çalışmalarınızın karşılığı verilmiştir."},{"n":23,"t":"Kur`ân`ı sana biz indirdik."},{"n":24,"t":"Artık Rabbinin hükmüne sabret; onlardan hiçbir günahkâra, hiçbir nanköre boyun eğme!"},{"n":25,"t":"Sabah akşam Rabbinin ismini an!"},{"n":26,"t":"Gecenin bir kısmında O`na secde et, gecenin uzun bir bölümünde de O`nu tesbih et!"},{"n":27,"t":"Şüphesiz şu insanlar dünyayı severler, ağır bir günü kulak ardı ederler."},{"n":28,"t":"Onları biz yarattık, onların yaratılışını sapasağlam yaptık. Dilediğimizde yerlerine benzerlerini getiririz."},{"n":"29-31","t":"Şüphesiz ki bu bir öğüttür. Artık, dileyen Rabbine bir yol tutar. Zaten siz ancak Rabbinizin dilediğini dilersiniz. Şüphesiz Allah her şeyi bilendir; hikmet sahibidir. Allah, dileyeni rahmetine dahil eder. Zâlimlere gelince, onlar için elem verici bir azap hazırlamıştır."}],[{"n":"1-7","t":"Birbiri ardınca gönderilenlere, görevlerine koştukça koşanlara, iyiden iyiye yayanlara, hak ile bâtılı ayırdıkça ayıranlara, öğüt bırakanlara, özür veya uyarıda bulunanlara yemin olsun ki, size verilen söz mutlaka gerçekleşecektir."},{"n":"8-15","t":"Yıldızlar silindiği zaman, gök yarıldığı zaman, dağlar ufalanıp savrulduğu zaman, peygamberlere vakit bildirildiği zaman; ertelendikleri gün için; yani hüküm günü için, -ki hüküm gününün ne olduğunu sen nereden bileceksin?- Yalanlayanların vay haline o gün!"},{"n":"16-17","t":"Biz, öncekileri helâk etmedik mi? Sonra da, peşlerinden gelenleri onların ardına takacağız."},{"n":18,"t":"İşte biz, suçlulara böyle yaparız."},{"n":19,"t":"O gün, geçmişten ders almayan yalancıların vay haline!"},{"n":20,"t":"Sizi değersiz bir sudan yaratmadık mı?"},{"n":"21-22","t":"Sonra belli bir süreye kadar onu sağlam bir yere yerleştirmedik mi?"},{"n":23,"t":"Buna gücümüz yeter. Güç yetiren ne güzeldir!"},{"n":24,"t":"O gün, yaratanını inkâr edenlerin vay haline!"},{"n":"25-26","t":"Biz yeryüzünü dirilerle ölülere toplanma yeri yapmadık mı?"},{"n":27,"t":"Oraya sabit ve yüksek dağlar yerleştirmedik mi? Size tatlı sular içirmedik mi?"},{"n":28,"t":"O gün, Allah`ın nimetlerini yalanlayanların vay haline!"},{"n":"29-33","t":"Yalan sayageldiğiniz şeye doğru gidiniz! Üç boyutlu azaba, ne gölgelendiren ne de alevden koruyan bir gölgeye gidiniz. O saray gibi kocaman bir kıvılcım saçar. Her bir kıvılcım sanki birer sarı devedir."},{"n":34,"t":"O gün, Allah`ın uyarısını yalanlayanların vay haline!"},{"n":35,"t":"Bu, konuşamayacakları gündür."},{"n":36,"t":"Özür dilemelerine izin verilmeyecektir."},{"n":37,"t":"O gün, âhireti yalanlayanların vay haline!"},{"n":38,"t":"Bu, sizleri ve öncekileri topladığımız hüküm günüdür."},{"n":39,"t":"Eğer bir tuzağınız varsa, bana kurunuz."},{"n":40,"t":"O gün, hüküm gününü yalanlayanların vay haline!"},{"n":"41-42","t":"Şüphesiz o gün, takvâ sahipleri, gölgelerde ve pınar başlarında, canlarının çektiğinden çeşit çeşit meyveler arasında olacaklardır."},{"n":"43-44","t":"Kendilerine, “Yaptıklarınızın karşılığı olarak şimdi âfiyetle yiyiniz, içiniz” denilecektir. İşte biz, güzel amel yapanları böyle ödüllendiririz."},{"n":45,"t":"O gün, âhiretteki ödülü yalanlayanların vay haline!"},{"n":"46-47","t":"Yiyiniz, azıcık sefa sürünüz; siz suçlusunuz. O gün, kıyametin kopacağını yalanlayanların vay haline!"},{"n":"48-49","t":"Kendilerine “Allah`ın huzurunda eğiliniz” dendiğinde, eğilmezler. O gün, Allah`a ibadeti yalanlayanların vay haline!"},{"n":50,"t":"Onlar, bundan başka hangi söze inanacaklar?"}],[{"n":1,"t":"Birbirlerine neyi soruyorlar?"},{"n":"2-3","t":"Üzerinde anlaşmazlığa düştükleri büyük haberi mi?"},{"n":"4-5","t":"Hayır! İleride anlayacaklardır. Yine hayır! İleride anlayacaklardır."},{"n":"6-7","t":"Biz, yeryüzünü bir döşek, dağları da birer kazık yapmadık mı?"},{"n":8,"t":"Sizi çifter çifter yaratmadık mı?"},{"n":9,"t":"Uykunuzu dinlenme vasıtası yapmadık mı?"},{"n":10,"t":"Geceyi örtü gibi yapmadık mı?"},{"n":11,"t":"Gündüzünüzü, geçiminizi sağlama vakti yapmadık mı?"},{"n":12,"t":"Üzerinize sağlam yedi göğü yaratmadık mı?"},{"n":13,"t":"Güneşi ışık ve enerji kaynağı olarak yaratmadık mı?"},{"n":"14-16","t":"Yağmurla taneleri ve bitkileri bitirmek ve sık ağaçlı bahçeler oluşturmak için, yoğunlaşmış bulutlardan bolca yağan yağmur yağdırmadık mı?"},{"n":17,"t":"Şüphesiz, hüküm gününün vakti belirlenmiştir."},{"n":18,"t":"Sûr`a üfürüldüğü gün hepiniz bölük bölük gelirsiniz."},{"n":19,"t":"Gökyüzü açılır ve orada pek çok kapılar oluşur."},{"n":20,"t":"Dağlar yürütülür, serap haline gelir."},{"n":"21-22","t":"Azgınların barınağı olacak Cehennem, pusuda beklemektedir."},{"n":23,"t":"Azgınlar, çağlar boyu orada kalırlar."},{"n":"24-28","t":"Yaptıklarına uygun bir karşılık olarak orada ne bir serinlik, ne de bir soğuk içecek bulacaklar. Ancak kaynar su ve irin içecekler. Çünkü onlar, hesap gününü hiç beklemiyorlardı. Âyetlerimizi şiddetle yalanlamışlardı."},{"n":29,"t":"Oysa biz, her şeyi en ince detayına kadar kaydetmişizdir."},{"n":30,"t":"Onlara, “Azabı tadınız. Size azabımızı arttırmaktan başka bir şey yapmayacağız” denir."},{"n":"31-34","t":"Allah`a saygı duyanlar için umdukları yer, muhteşem bahçeler ve bağlar, müthiş uyumlu harika eşler ve dolup taşan kadehler vardır."},{"n":"35-36","t":"Orada, ne boş söz ne de yalan duyacaklar. Bütün bunlar, Rabbinin katından hesaplarının karşılığı verilenlerdir."},{"n":37,"t":"O, göklerin, yerin ve ikisi arasında bulunanların Rabbi`dir. O, rahmetin kaynağıdır. O gün insanlar, O`na karşı konuşmaya yetkili değillerdir."},{"n":38,"t":"Rûh ve melekler saf saf olup durduğu gün, Rahmân`ın izin verdiklerinden başkası konuşamaz, konuşan da doğruyu söyler."},{"n":39,"t":"İşte o, kesin olarak gelecek olan gündür. O halde dileyen, Rabbine varan bir yol tutsun."},{"n":40,"t":"Biz, yakın bir azap ile sizi uyardık. O gün kişi önceden yaptıklarına bakacak ve kâfir, “Keşke toprak olsaydım!” diyecektir."}],[{"n":"1-5","t":"Andolsun doğup batan yıldızlara, yörüngelerinden çıkmadan hareket edenlere, uzayda sakin sakin yüzenlere, hayırda yarışanlara, işini mükemmel yapanlara."},{"n":"6-7","t":"O gün, deprem sarsar, onu ikinci bir sarsıntı izler."},{"n":"8-9","t":"Bazı yürekler o gün çarpar; gözleri korkudan aşağı kayar."},{"n":10,"t":"“Biz eski halimize mi döndürüleceğiz? Çürümüş kemikler haline geldikten sonra mı? Öyleyse bu hüsran dolu bir dönüştür.”"},{"n":11,"t":"“Biz eski halimize mi döndürüleceğiz? Çürümüş kemikler haline geldikten sonra mı? Öyleyse bu hüsran dolu bir dönüştür.”"},{"n":12,"t":"“Biz eski halimize mi döndürüleceğiz? Çürümüş kemikler haline geldikten sonra mı? Öyleyse bu hüsran dolu bir dönüştür.”"},{"n":"13-14","t":"Bu dönüş sadece bir seslenmeye bakar. Birden bire kendilerini mahşerde buluverirler."},{"n":15,"t":"Mûsâ`nın haberi sana geldi mi?"},{"n":16,"t":"“Arınmak istemez misin? Sana, Rabbine giden yolu göstereceğim, böylece saygı duyarsın.”"},{"n":17,"t":"“Arınmak istemez misin? Sana, Rabbine giden yolu göstereceğim, böylece saygı duyarsın.”"},{"n":18,"t":"“Arınmak istemez misin? Sana, Rabbine giden yolu göstereceğim, böylece saygı duyarsın.”"},{"n":19,"t":"“Arınmak istemez misin? Sana, Rabbine giden yolu göstereceğim, böylece saygı duyarsın.”"},{"n":20,"t":"Ona büyük mucizeyi gösterdi."},{"n":21,"t":"O ise hemen yalanladı ve isyan etti."},{"n":22,"t":"Sonra yüz çevirip mücadele etmeye çalıştı."},{"n":23,"t":"“Ben sizin en yüce rabbinizim!”"},{"n":24,"t":"“Ben sizin en yüce rabbinizim!”"},{"n":25,"t":"Böylece Allah, onu âhiret ve dünya azabıyla cezalandırdı."},{"n":26,"t":"Şüphesiz bunda, Allah`a saygı duyanlara bir ders vardır."},{"n":"27-29","t":"Sizi yaratmak mı daha güç, yoksa gökyüzünü yaratmak mı, ki onu Allah bina etti, onu yükseltip düzene koydu. Gecesini karanlık yapmış, gündüzünü aydınlatmıştır."},{"n":"30-33","t":"Ardından yerküreyi döşedi. Sizin ve hayvanlarınızın geçimi için yerden suyunu ve bitkilerini çıkardı. Dağları yerleştirdi."},{"n":"34-35","t":"O en büyük felâket geldiğinde, o gün insan, neyin uğruna çalıştığını hatırlayacaktır."},{"n":36,"t":"Cehennem, her görenin göreceği şekilde ortaya çıkarılacaktır."},{"n":"37-39","t":"İşte, azıp dünya hayatını tercih edenin varacağı yer şüphesiz cehennemdir."},{"n":"40-41","t":"Ama, kim Rabbinin makamından korkup da, kendini kötülüklerden alıkoymuşsa, varacağı yer şüphesiz cennettir."},{"n":"42-46","t":"Sana, kıyametin ne zaman gelip çatacağını soruyorlar. Sen onun hakkında ne söyleyebilirsin ki? Onun bilgisi sadece Rabbine aittir. Sen, sadece kıyametten korkanı uyaransın. Kıyameti gördükleri gün, dünyada ancak bir akşam, yahut bir kuşluk vakti kadar kalmış gibi olurlar."}],[{"n":"1-10","t":"Kendisine âmâ geldi diye yüzünü ekşitti ve döndü. Sen nereden bileceksin, belki o arınacaktı? Yahut, öğüt dinleyecek de öğüt kendisine yarayacaktı. Kendisini yeterli görüp tenezzül etmeyene gelince; sen ona yöneliyorsun. Onun arınmamasından sen sorumlu değilsin. Fakat koşarak sana gelen, saygı duyarak gelmişken, sen onunla ilgilenmiyorsun."},{"n":"11-12","t":"Hayır! Yaptığın doğru değil, âyetlerimiz bir öğüttür, dileyen ondan öğüt alır."},{"n":"13-16","t":"Kur`ân, kutsal sayfalardır. Yüksek tutulan tertemiz sayfalarda, yazıcıların yani değerli, iyi yazıcıların ellerinde."},{"n":17,"t":"Kahrolası insan! O ne nankördür!"},{"n":"18-19","t":"Allah onu nereden yaratmış? Onu meniden yaratıp ona biçim vermiştir."},{"n":20,"t":"Sonra, tutacağı yolu kolaylaştırmıştır."},{"n":"21-22","t":"Sonra onu öldürür, kabre koydurur. Sonra dilediği zaman onu tekrar diriltecektir."},{"n":23,"t":"Hayır! İnsan, Allah`ın emirlerini yerine getirmedi."},{"n":24,"t":"İnsan, yediğine bir baksın!"},{"n":"25-32","t":"Doğrusu, suyu bol bol indirmekteyiz. Sonra toprağı göz göz yardık, oradan ekinler, üzüm bağları, sebzeler, zeytin ve hurma ağaçları, iri ve sık ağaçlı bahçeler, meyveler ve çayırlar bitirdik. Bütün bunlar, sizi ve hayvanlarınızı yararlandırmak içindir."},{"n":33,"t":"Kulakları sağır eden o ses geldiğinde,"},{"n":"34-36","t":"O gün, kişi kardeşinden, annesinden, babasından, eşinden ve çocuklarından kaçar."},{"n":37,"t":"O gün, herkesin kendine yetip artacak bir derdi vardır."},{"n":"38-39","t":"O gün birtakım yüzler parlak, güleç ve sevinçlidir."},{"n":"40-42","t":"Yine o gün, birtakım yüzleri de keder bürümüş, hüzünden kapkara kesilmiştir. İşte bunlar kâfirlerdir, haktan sapanlardır."}],[{"n":1,"t":"Güneş katlanıp karanlığa gömüldüğünde,"},{"n":2,"t":"Yıldızlar dökülüp ışıklarını yitirdiğinde,"},{"n":3,"t":"Dağlar yürütülüp kaybolduğunda,"},{"n":4,"t":"Değerli mallar terkedildiğinde,"},{"n":5,"t":"Yabani hayvanlar bir araya toplandığında,"},{"n":6,"t":"Denizler kaynayıp kabardığında,"},{"n":7,"t":"Canlar bedenlerle birleştirildiğinde,"},{"n":"8-9","t":"Diri diri toprağa gömülen kıza, hangi günah sebebiyle öldürüldüğü sorulduğunda,"},{"n":10,"t":"Amel defterleri açıldığında,"},{"n":11,"t":"Gökyüzü sıyrıldığında,"},{"n":12,"t":"Cehennem tutuşturulduğunda,"},{"n":13,"t":"Cennet yaklaştırıldığında,"},{"n":14,"t":"Her can, kendine ne hazırladığını bilecektir."},{"n":"15-16","t":"Kara deliklere, ak deliklere yemin olsun,"},{"n":"17-18","t":"Çöken geceye, söken şafaklara yemin olsun ki,"},{"n":"19-20","t":"Kur`ân kesinlikle değerli bir elçinin/Cebrail`in peygambere ilettiği sözdür. Arşın sahibinin katında güçlü ve değerli elçinin/Cebrail`in -ki o yüksek makam sahibidir-."},{"n":21,"t":"İtaatli ve de güvenilir elçidir."},{"n":"22-24","t":"Sizin arkadaşınız Muhammed, kesinlikle deli değildir. O, meleği apaçık ufukta görmüştü. O, gaypten gelen bilgileri sizden esirgeyemez."},{"n":25,"t":"Bu Kur`ân, kovulmuş şeytanın sözü değildir."},{"n":26,"t":"O halde nereye gidiyorsunuz?"},{"n":"27-28","t":"Bu Kur`ân, sizden doğru yola gitmek isteyenleriniz için, bütün insanlara bir öğütten ibarettir."},{"n":29,"t":"Siz zaten ancak, âlemlerin Rabbi olan Allah`ın dilediğini dilersiniz."}],[{"n":1,"t":"Gök, çatlayıp yarıldığı zaman,"},{"n":2,"t":"Yıldızlar dökülüp saçıldığında,"},{"n":3,"t":"Denizler fışkırtıldığında,"},{"n":4,"t":"Kabirlerin içi dışına getirildiğinde,"},{"n":5,"t":"Herkes, neyi önünden gönderdiğini ve neyi geri bıraktığını bilecektir."},{"n":6,"t":"Ey insan! Lütfu bol Rabbinden seni uzaklaştıran nedir?"},{"n":7,"t":"O ki seni yarattı, seni düzgün ve dengeli kıldı, sana ölçülü bir biçim verdi."},{"n":8,"t":"Seni dilediği herhangi bir biçimde / surette oluşturdu."},{"n":9,"t":"Öyle değil, doğrusu sizler yargı gününü yalanlıyorsunuz."},{"n":"10-12","t":"Oysa sizin üzerinizde gözcüler vardır. Değerli yazıcılar. Onlar sizin ne yaptığınızı bilirler."},{"n":13,"t":"Şüphesiz iyiler nimetler içinde olacaklardır."},{"n":14,"t":"Kötüler de cehennemde olacaklardır."},{"n":"15-16","t":"Yargı günü oraya girecekler ve süreli orada kalacaklardır."},{"n":"17-19","t":"Yargı gününün ne olduğunu sen ne bileceksin? Evet, yargı gününün ne olduğunu sen ne bileceksin? Hiçbir insanın başkasına herhangi bir fayda vermeye gücünün yetmeyeceği bir gündür. O gün, emir yalnızca Allah`ındır."}],[{"n":1,"t":"Eksik ölçüp tartanların vay haline!"},{"n":"2-3","t":"Onlar, insanlardan bir şey aldıkları zaman tam ölçüp tartarlar. Kendileri bir şey sattıkları zaman onlara eksik ölçüp tartarlar."},{"n":"4-6","t":"Onlar, âlemlerin Rabbinin huzurunda duracaklarları büyük gün için tekrar dirileceklerine inanmıyorlar mı?"},{"n":"7-9","t":"Hayır! Şüphesiz, yoldan çıkanların defterleri kesinlikle Siccîn`dedir. “Siccîn`in ne olduğunu sen nerden bileceksin?” O, kodlanmış bir kitaptır."},{"n":"10-12","t":"Yalanlayanların vay haline o gün! Onlar yargı gününü yalanlıyorlar. Oysa o günü, aşırı gidenler ve günahkârlardan başkası yalanlamaz."},{"n":13,"t":"Onlara âyetlerimiz okunduğunda, “Öncekilerin masallarıdır” derler."},{"n":14,"t":"Hayır! Doğrusu, işledikleri günahlar, kalplerinin üzerinde pas tutmuştur."},{"n":15,"t":"Hayır! Doğrusu, o gün Rablerinden perdelenmiş olacaklardır."},{"n":"16-17","t":"Sonra onlar cehenneme gireceklerdir. Sonra kendilerine, “İşte yalanladığınız budur” denilecektir."},{"n":"18-21","t":"Hayır! İyilerin defteri ‘Illiyyîn`dedir. “‘Illiyyîn`in ne olduğunu sen nerden bileceksin?” O da kodlanmış bir kitaptır. Allah`a yakın kılınmış melekler ona tanıklık edeceklerdir."},{"n":"22-23","t":"Şüphesiz, iyiler nimet cennetinde olacaklardır. Koltuklar üzerinde seyredeceklerdir."},{"n":24,"t":"Onların yüzlerinde nimetin mutluluğunu hissedersin."},{"n":"25-26","t":"Onlar, bitiminde misk kokusu olan, mühürlenmiş saf bir içecekten içerler. Yarışanlar, bunun için yarışsınlar."},{"n":27,"t":"Ona karıştırılan şey de Tesnîm'dendir;"},{"n":28,"t":"Bir pınardır ki ondan, (Allah'a) yakın olanlar içerler."},{"n":29,"t":"Suçlular, dünyada inananlara gülerlerdi."},{"n":30,"t":"Yanlarından geçtiklerinde kaş-göz işaretleriyle onlarla alay ederlerdi."},{"n":31,"t":"Ailelerinin yanlarına döndüklerinde, inananlarla alay ettiklerinden dolayı sevinç içinde dönerlerdi."},{"n":32,"t":"Müminleri gördüklerinde, “Şüphesiz bunlar sapıtmışlardır” derlerdi."},{"n":33,"t":"Oysa kendileri, müminleri denetleyici olarak gönderilmediler."},{"n":"34-35","t":"O gün de, inananlar inkâr edenlere gülecekler. Koltuklarına kurulup seyredecekler."},{"n":36,"t":"“İnkâr edenler yaptıklarının karşılığını aldılar mı?” diyecekler."}],[{"n":"1-2","t":"Gökyüzü parçalara ayrıldığında, tabiatı gereği Rabbine kulak verdiğinde,"},{"n":"3-5","t":"Yeryüzü dümdüz hale getirildiğinde, içindeki her şeyi dışarı atarak tamamen boşaldığında ve tabiatı gereği Rabbine kulak verdiğinde,"},{"n":6,"t":"“Ey insan! Şüphesiz sen Rabbine varan yolda çabalayıp durmaktasın. Sonunda O`na kavuşacaksın.”"},{"n":"7-9","t":"Kimin kitabı sağından verilirse, kolay bir hesaba çekilecek ve sevinçle ailesine dönecektir."},{"n":"10-12","t":"Kimin de kitabı arka tarafından verilirse, derhal yok olmayı isteyecek ve alevli ateşe girecektir."},{"n":13,"t":"Zira o, ailesi içinde şımarmıştı."},{"n":"14-15","t":"Çünkü o, hiçbir zaman Rabbine dönmeyeceğini sandı. Oysa gerçekten Rabbi onu görüyordu."},{"n":16,"t":"Andolsun akşam karanlığına ve topladığı şeylere,"},{"n":17,"t":"Dolunay hâlini aldığı zaman aya,"},{"n":18,"t":"Ki siz, halden hâle (tabakadan tabakaya, evreden evreye) geçeceksiniz."},{"n":19,"t":"Öyleyse onlara ne oluyor ki inanmıyorlar?"},{"n":"20-21","t":"Böyleyken, onlar acaba niçin iman etmezler? Kendilerine Kur`ân okununca secde de etmezler?"},{"n":22,"t":"Aksine, inkâr edenler yalanlıyorlar."},{"n":23,"t":"Halbuki Allah, onların gizlediği şeyleri çok iyi bilir."},{"n":24,"t":"Onlara acıklı azabı müjdele!"},{"n":25,"t":"İman edip iyi amel işleyenler müstesnadır. Onlar için arkası kesilmeyen bir ödül vardır."}],[{"n":"1-3","t":"Burçlar sahibi göğe; vaad edilen o güne; tanık olan ve tanık olunana yemin olsun ki,"},{"n":"4-5","t":"Kahrolsun! Ateşi olan o çukuru kazanlar."},{"n":"6-7","t":"Onlar da o ateş çukurunun etrafında oturmuş, müminlere yapmakta oldukları işkenceyi seyrediyorlardı."},{"n":"8-9","t":"Müminlerden, sadece, göklerin ve yerin mülkü/iktidarı kendisine ait olan, ‘sonsuz kudret sahibi ve övgüye layık olan Allah`a iman ettiklerinden dolayı intikam aldılar/alıyorlar. Oysaki Allah her şeyi görür."},{"n":10,"t":"Şüphesiz, inanan erkekler ile inanan kadınlara işkence edenlere ve sonra tövbe etmeyenlere, cehennem azabı ve orada yanma cezası vardır."},{"n":11,"t":"İman edip iyi amel yapanlara ise, içinden ırmaklar akan cennetler vardır. İşte, büyük kurtuluş budur."},{"n":"12-16","t":"Şüphesiz, Rabbinin yakalaması son derece çetindir. İnsanı yoktan yaratan ve sonra yeniden diriltecek O`dur. O, çok bağışlayandır; çok sevendir. Şanlı kudret tahtının sahibidir. Dilediği şeyleri mutlak yapandır."},{"n":"17-18","t":"Orduların, Firavun ve Semûd`un uğradıkları helâkın haberi sana geldi mi?"},{"n":19,"t":"Doğrusu, inkârcılar hakikati yalanlayıp durmaktalar."},{"n":20,"t":"Allah onları arkalarından kuşatmıştır."},{"n":"21-22","t":"Hakikatte o, korunmuş levhada/Levh-ı Mahfûz`da bulunan şerefli Kur`ân`dır."}],[{"n":"1-4","t":"Göğe ve Târık`a yemin olsun. Târık`ın ne olduğunu sen nereden bileceksin? Parlayan yıldızdır. Hiçbir kimse yoktur ki başında bir denetleyici bulunmasın."},{"n":5,"t":"İnsan nereden yaratıldığına bir baksın."},{"n":6,"t":"Atılan bir sudan yaratılmıştır."},{"n":7,"t":"O su, erkeğin belinden, kadının leğen kemiğinden çıkmaktadır."},{"n":8,"t":"Şüphesiz Allah`ın, insanı öldükten sonra diriltmeye de gücü yeter."},{"n":"9-10","t":"Bütün sırların ortaya serileceği o gün, insanın ne bir gücü, ne de bir yardımcısı olacaktır."},{"n":"11-17","t":"Andolsun o dönüşlü göğe, o yarılıp çatlayan yeryüzüne. Şüphesiz Kur`ân, hak ile bâtılı ayıran bir sözdür. O asla bir şaka değildir. Kafirler hep hile/tuzak kuruyorlar. Ben de hilelerine karşılık veririm. Onun için sen kâfirlere mühlet ver, onlara az bir zaman tanı!"}],[{"n":1,"t":"Rabbinin o yüce ismini tesbih et."},{"n":"2-5","t":"Yaratıp düzene koyanın, her şeyi ölçüyle yapıp doğasına göre görevini belirleyenin, yeşil otu çıkarıp sonra da onu kapkara bir sel artığına çevirenin ismini tesbih et."},{"n":"6-7","t":"Bundan böyle seni okutacağız; artık Allah`ın dilediği hariç, sen hiç unutmayacaksın. Şüphesiz Allah açığı ve gizleneni bilir."},{"n":"8-9","t":"Başarıya giden yolu sana kolaylaştıracağız. O halde öğüt ver, çünkü öğüdün mutlaka faydası olacaktır."},{"n":10,"t":"Allah`a saygılı olan, öğüt alır."},{"n":"11-13","t":"En şakî olan da ondan kaçınır. O da en büyük ateşe girer. Sonra orada ne ölür, ne de yaşar."},{"n":"14-15","t":"Temizlenenler, Rabbinin adını anıp O`na dua edenler, kesinlikle kurtuluşa erecektir."},{"n":"16-17","t":"Aksine siz dünya hayatını tercih ediyorsunuz. Oysa âhiret hayatı daha üstün ve daha kalıcıdır."},{"n":"18-19","t":"Şüphesiz bunlar, önceki sayfalarda, İbrâhim`in ve Mûsâ`nın sayfalarında da vardı."}],[{"n":1,"t":"O her şeyi kuşatacak olan kıyametin haberi sana geldi mi?"},{"n":"2-7","t":"O gün birtakım yüzler öne eğilecek; çok çabalayıp yorgun düşecek; kızgın ateşe girecek; son derece sıcak bir kaynaktan içirilecek. Onlar için kuru dikenden başka yemek yoktur; o ise, ne besler, ne de açlığı giderir."},{"n":"8-11","t":"O gün birtakım yüzler de şen olacaklar; çalıştığından dolayı yüksek bir cennette hoşnuttur; orada boş söz işitmeyecekler."},{"n":"12-16","t":"Orada akan pınarlar olacak; orada yüksek divanlar; konulmuş kadehler, dizilmiş koltuklar, yastıklar; serilmiş halılar olacak."},{"n":"17-20","t":"Develerin nasıl yaratıldığına, göğün nasıl yükseltildiğine, dağların nasıl dikildiğine, yerin nasıl yayıldığına bakmazlar mı?"},{"n":21,"t":"Öğüt ver, çünkü sen ancak öğüt verensin."},{"n":22,"t":"Onların üzerinde zorlayıcı değilsin."},{"n":23,"t":"Ancak, kim yüz çevirir ve inkâr ederse."},{"n":24,"t":"Allah ona en büyük azabı eder."},{"n":25,"t":"Dönüşleri yalnızca bizedir."},{"n":26,"t":"Sonra onların hesabını görmek bize düşer."}],[{"n":"1-4","t":"Şafak vaktine, on geceye, her şeyin çiftine ve tekine, geçip giden geceye yemin olsun ki,"},{"n":5,"t":"Bunda, akıl sahibi için hakikatin sağlam bir kanıtı yok mudur?"},{"n":6,"t":"Görmedin mi Rabbin nasıl yaptı ‘Âd kavmine,"},{"n":"7-8","t":"Ülkeler arasında eşi yaratılmamış sütunlu İrem`e?"},{"n":9,"t":"Ve vadide kayaları oymuş olan Semud (halkın)a?"},{"n":10,"t":"Saltanat sahibi Firavun`a."},{"n":"11-14","t":"O ülkelerde haddi aşanları, oralarda bozgunculuğu arttıranları nasıl yok ettiğini bilmez misin? Rabbin onların üzerine azap kırbacını indirmiştir. Rabbin kesinlikle gözetmektedir."},{"n":15,"t":"İnsana gelince, Rabbi kendisini imtihan edip ikramda bulunduğunda ve bol nimet verdiğinde, “Rabbim bana cömert davrandı” der."},{"n":16,"t":"Fakat imtihan edip rızkını daralttığında ise, “Rabbim beni önemsemedi” der."},{"n":"17-20","t":"Hayır! Doğrusu siz yetime ikram etmiyorsunuz; yoksulu doyurmaya teşvik etmiyorsunuz; haram helâl demeden mirası yiyorsunuz; malı aşırı derecede seviyorsunuz."},{"n":"21-22","t":"Hayır! Yeryüzü ardı ardına sarsılıp paramparça olduğunda, Rabbinin emri gelip melekler saf saf dizildiğinde,"},{"n":23,"t":"İşte o gün cehennem getirilir. O gün insan her şeyi hatırlayacak, ama bu hatırlamanın ona ne faydası olacak?"},{"n":24,"t":"“Âh, keşke bu hayatım için önceden bir şeyler yapsaydım!” der."},{"n":"25-26","t":"O gün Allah`ın günahkârlara vereceği azabı, hiç kimse veremez ve hiç kimse O`nun gibi bağ vuramaz."},{"n":27,"t":"Ey doyuma ulaşmış nefis!"},{"n":28,"t":"Hem hoşnut edici, hem de hoşnut edilmiş olarak Rabbine dön!"},{"n":"29-30","t":"Kullarımın arasına ve cennetime gir!"}],[{"n":"1-3","t":"Senin yaşamakta olduğun bu beldeye; doğurana ve doğana yemin olsun ki,"},{"n":4,"t":"Biz, insanı zorluklar içinde yarattık."},{"n":5,"t":"İnsan, hiç kimsenin kendisine güç yetiremeyeceğini mi sanıyor?"},{"n":"6-7","t":"“Pek çok mal harcadım” der, kimse onu görmedi mi sanıyor?"},{"n":"8-10","t":"Biz ona iki göz, bir dil ve iki dudak vermedik mi? Ona hak ve bâtıl şeklinde iki yolu göstermedik mi?"},{"n":"11-16","t":"Fakat insan, sarp yokuşu aşamadı. O sarp yokuşun ne olduğunu sen nereden bileceksin? Köle âzat etmektir veya açlık gününde yakını olan bir yetimi, yahut toprakta sürünen bir yoksulu doyurmaktır."},{"n":"17-18","t":"Sonra iman edenlerden, birbirine sabrı ve merhameti tavsiye edenlerden olmaktır. İşte bunlar sağdakilerdir."},{"n":"19-20","t":"Âyetlerimizi inkâr edenler ise, işte onlar soldakilerdir. Cezaları, kapıları üzerine sımsıkı kapatılmış bir ateştir."}],[{"n":"1-8","t":"Güneşe ve onun aydınlık veren parlaklığına; onu izlediğinde aya; güneşi açığa çıkardığında gündüze; güneşi örttüğünde geceye; göğe ve onu bina edene; yere ve onu döşeyene; nefse ve onu şekillendirene; nefse, kötülüğe ve korunmaya açık özelliklerini verene yemin olsun ki,"},{"n":"9-10","t":"Nefsini arındıran, kurtuluşa ermiştir. Nefsini karanlığa gömen ise kayıptadır."},{"n":11,"t":"Semûd toplumu, azgınlığı nedeniyle yalanladı."},{"n":"12-13","t":"En azgınları ileri atıldığında, Allah`ın peygamberi onlara, “Allah`ın devesini bırakınız, onun su içmesine engel olmaktan sakınınız” demişti."},{"n":14,"t":"Buna rağmen peygamberi yalanladılar ve deveyi kestiler. Rableri, günahlarından dolayı ülkelerini harap edip yerle bir etti."},{"n":15,"t":"Çünkü onların hiçbiri, başlarına gelecek şeyin korkusunu taşımıyordu."}],[{"n":"1-3","t":"Örttüğü zaman geceye, göründüğü zaman gündüze, erkeği ve dişiyi yaratana yemin olsun ki,"},{"n":4,"t":"Doğrusu sizin çalışmalarınız çeşitlidir."},{"n":"5-7","t":"Ancak verenin, saygı duyanın ve en güzeli tasdik edenin işlerini kolaylaştırırız."},{"n":"8-11","t":"Ama cimrilik edip kendini ihtiyaçsız, yeterli gören ve güzeli yalanlayana da, zorluklara uğramasını kolaylaştırırız. Cehenneme yuvarlandığı zaman malı ona hiçbir yarar sağlamaz."},{"n":12,"t":"Doğru yolu göstermek bize aittir."},{"n":13,"t":"Şüphesiz, âhiret de dünya da bizimdir."},{"n":14,"t":"Alev alev yanan bir ateşle sizi uyarıyorum."},{"n":"15-16","t":"O ateşe, yalanlayıp yüz çeviren bedbahtan başkası girmez."},{"n":"17-18","t":"Arınmak uğruna malını hayra harcayan takvâ sahipleri, o ateşten uzak tutulacaktır."},{"n":"19-20","t":"Yüce Rabbinin rızasını elde etmekten başka, hiç kimseden beklediği herhangi bir karşılık da yoktur."},{"n":21,"t":"O kesinlikle ileride memnun olacaktır."}],[{"n":"1-2","t":"Kuşluk vaktine ve sakinleşen geceye yemin olsun ki,"},{"n":3,"t":"Rabbin seni terketmedi ve sana darılmadı."},{"n":4,"t":"Gerçekten işin sonu senin için başından daha iyi olacaktır."},{"n":5,"t":"Gelecekte Rabbin sana verecek ve sen hoşnut olacaksın."},{"n":6,"t":"O, seni yetim bulup barındırmadı mı?"},{"n":7,"t":"Senin, peygamberlikten, Kur’ândan, şeriattan habersiz başına buyruk bir kavim içinde tek başına olduğunu, hidayeti arzuladığını görüp seni hidayete erdirmedi mi, insanlığa rehber yapmadı mı, insanları sana yönlendirmedi mi?"},{"n":8,"t":"Seni fakir bulup, zengin etmedi mi?"},{"n":9,"t":"Öyleyse sakın yetimi ezme!"},{"n":10,"t":"Dilenciyi de azarlama!"},{"n":11,"t":"Rabbinin nimetini an!"}],[{"n":"1-3","t":"Biz senin için göğsünü açmadık mı? Senin sırtını çatırdatan yükünü atmadık mı?"},{"n":4,"t":"Senin şanını yükseltmedik mi?"},{"n":"5-6","t":"Elbette, zorlukla beraber bir kolaylık vardır. Evet, zorluğun yanında bir kolaylık vardır."},{"n":7,"t":"Boş kaldığında hemen başka işe koyul!"},{"n":8,"t":"Yalnızca Rabbine yönel!"}],[{"n":1,"t":"İncir ve zeytine yemin olsun,"},{"n":2,"t":"Sîna dağına yemin olsun,"},{"n":3,"t":"Bu güvenli beldeye yemin olsun ki,"},{"n":"4-5","t":"Andolsun, insanı en güzel biçimde yaratırız. Sonra onu aşağıların aşağısına indiririz."},{"n":6,"t":"İman edip iyi amel yapanlar hariç. Onlar için kesintisiz bir ödül vardır."},{"n":7,"t":"O halde sana ceza ve mükâfatı yalanlatan nedir?"},{"n":8,"t":"Allah, hâkimlerin hâkimi değil mi?"}],[{"n":1,"t":"Yaratan Rabbinin adı ile oku!"},{"n":2,"t":"O, insanı bir yapışkan döllenmiş yumurta hücresinden yarattı."},{"n":3,"t":"Oku; çünkü Rabbin sonsuz kerem sahibidir."},{"n":4,"t":"O, insana kalemi kullanmayı öğretendir."},{"n":5,"t":"İnsana bilmediğini öğretti."},{"n":6,"t":"Gerçek şu ki, insan azar."},{"n":7,"t":"Çünkü kendini yeterli görür."},{"n":8,"t":"Şüphesiz dönüş Rabbinedir."},{"n":"9-10","t":"Allah`a yönelen bir kulu engelleyeni gördün mü?"},{"n":"11-12","t":"Ne dersin, o kul doğru yolda ise ve sakınmayı emrediyorsa!"},{"n":13,"t":"Ne dersin, engelleyen kişi yalanlıyor ve doğru yoldan yüz çeviriyorsa!"},{"n":14,"t":"O bilmez mi ki, Allah her şeyi görüyor?"},{"n":"15-18","t":"Hayır hayır! Eğer bu yaptığından vazgeçmezse, derhal onu o yalancı, günahkâr alnından yakalarız. O, hemen gidip meclisini çağırsın. Biz de zebanileri çağıracağız."},{"n":19,"t":"Hayır hayır! Ona uyma! Allah`a secde et ve yaklaş!"}],[{"n":1,"t":"Biz Kur`ân`ı Kadir gecesinde indirdik."},{"n":2,"t":"Kadir gecesinin ne olduğunu sen nereden bileceksin?"},{"n":3,"t":"Kadir gecesi bin aydan daha değerlidir."},{"n":4,"t":"Melekler ve Rûh/Cebrail, o gece Rablerinin izniyle her türlü iş için iner dururlar."},{"n":5,"t":"O gece, tan yerinin ağarmasına kadar bir selâmdır, yani esenliktir."}],[{"n":1,"t":"Kitap ehlinden ve müşriklerden inkâr edenler, kendilerine apaçık delil gelinceye kadar tutumlarından vaz geçecek değillerdi."},{"n":2,"t":"O apaçık delil, Allah katından gönderilmiş, tertemiz sayfaları okuyan bir peygamberdir."},{"n":3,"t":"O sayfalarda doğru hükümler vardır."},{"n":4,"t":"Kitap verilmiş olanlar, ancak kendilerine o açık kanıt geldikten sonra ayrılığa düştüler."},{"n":5,"t":"Oysa kendilerine, dini yalnız Allah`a halis kılıp O`nu birleyerek Allah`a kulluk etmeleri, namazı kılmaları, zekâtı vermeleri emredilmişti. İşte doğru din budur."},{"n":6,"t":"Kitap ehlinden ve müşriklerden olan kafirler, süreli olarak cehennem ateşinde olacaklardır. Onlar, halkın en kötüleridir."},{"n":7,"t":"İnanıp iyi amel yapanlar da halkın en iyileridir."},{"n":8,"t":"Onların, Rableri katında ödülü, içinden ırmaklar akan, içinde süreli kalacakları Adn cennetleridir. Allah onlardan razı olmuş, onlar da O`ndan memnun olmuşlardır. Bu, Rabbine saygı gösterene aittir."}],[{"n":"1-3","t":"Yerküre o korkunç sarsıntı ile sarsıldığı; yer, ağırlıklarını çıkardığı ve insan, “Ona ne oluyor?” dediği zaman!"},{"n":4,"t":"İşte o gün, yer, haberlerini söyler."},{"n":5,"t":"Çünkü Rabbin ona vahyetmiştir."},{"n":6,"t":"O gün insanlar gruplar halinde çıkarlar ki yaptıkları işler kendilerine gösterilsin."},{"n":7,"t":"Artık kim zerre ağırlığınca hayır yapmışsa onu görür."},{"n":8,"t":"Kim de zerre ağırlığınca kötü amel yapmışsa onu görür."}],[{"n":1,"t":"Öfkesinden dolayı soluk soluğa kalan düşmanlara,"},{"n":2,"t":"İçindeki kin ateşini etrafındakilere püskürenlere,"},{"n":3,"t":"Kin ve öfkeleriyle sabahlayanlara yazıklar olsun!"},{"n":4,"t":"Onlar tozu dumana katıp bozgunculuk yaparlar,"},{"n":5,"t":"Toplumu derinden yaralarlar."},{"n":6,"t":"İnsan, Rabbine karşı çok nankördür."},{"n":7,"t":"Kendisi de buna şahittir."},{"n":8,"t":"Onun mala karşı tutku derecesinde sevgisi vardır."},{"n":9,"t":"Bilmez mi kabirlerde olanlar yeniden diriltilip dışarı atıldığı zaman!"},{"n":10,"t":"Sinelerde olanlar ortaya konduğu zaman."},{"n":11,"t":"Şüphesiz, Rableri o gün onların yaptıklarından haberdardır."}],[{"n":1,"t":"Kapı çalan!"},{"n":2,"t":"Nedir o kapı çalan?"},{"n":3,"t":"O kapı çalanın ne olduğunu bilir misin?"},{"n":4,"t":"O gün insanlar, saçılmış kelebekler gibi olurlar."},{"n":5,"t":"Dağlar atılmış yün gibi olurlar."},{"n":"6-7","t":"Tartıları ağır gelenler, mutlu bir yaşam içerisinde olacaklardır."},{"n":"8-9","t":"Fakat tartıları hafif gelenler ise, onların da yeri Hâviye`dir."},{"n":10,"t":"Hâviye`nin ne olduğunu sen ne bilirsin?"},{"n":11,"t":"O, son derece kızgın bir ateştir."}],[{"n":"1-2","t":"Ta ki ölüp kabre gelinceye kadar, çoklukla övünmek sizi oyaladı."},{"n":"3-4","t":"Hayır! Yakında bileceksiniz! Yine hayır! Yakında bileceksiniz.!"},{"n":5,"t":"Hayır! Gerçeği kesin bilgi ile bilseydiniz."},{"n":"6-7","t":"“Elbette cehennemi önceden görecektiniz. Evet onu çıplak gözle göreceksiniz.”"},{"n":8,"t":"“Nihayet o gün nimetlerden elbette hesaba çekileceksiniz.”"}],[{"n":1,"t":"Zamana yemin olsun ki,"},{"n":2,"t":"Elbette insan ziyandadır."},{"n":3,"t":"Ancak, inanıp iyi işler yapanlar, hakkı birbirine tavsiye edenler ve sabrı birbirine tavsiye edenler ziyanda değillerdir."}],[{"n":"1-3","t":"Diliyle çekiştirip insanların onuru ile oynayan, kaş-göz hareketleriyle onlarla alay eden insanın vay haline! Mal yığıp onu tekrar tekrar sayar ve malının kendini ebedî yaşatacağını sanır."},{"n":"4-9","t":"Hayır! Andolsun ki o, Hutame`ye atılacaktır. Hutame`nin ne olduğunu bilir misin? Allah`ın, tutuşturulmuş, kalplerin cıdarına işleyen ateşidir. Onlar, bu ateşin içinde uzatılmış sütunlara bağlanmış haldeyken o ateş, üzerlerine kapatılmıştır."}],[{"n":1,"t":"Rabbinin, fil ordusuna neler yaptığını görmez misin?"},{"n":2,"t":"Onların kötü planlarını boşa çıkarmadı mı?"},{"n":3,"t":"Üzerlerine sürü sürü kuşlar gönderdi."},{"n":4,"t":"O kuşlar, onlara kurumuş çamurdan taşlar atıyordu."},{"n":5,"t":"Sonunda onları, kurtçuk tarafından yenilmiş ekin yaprağı gibi yaptı."}],[{"n":1,"t":"Kureyş`i alıştırdığı için."},{"n":2,"t":"Onları kış ve yaz yolculuklarına alıştırdığı için."},{"n":3,"t":"Bu evin Rabbine kulluk etsinler."},{"n":4,"t":"O ki onları yedirip açlıktan kurtardı ve onları korkudan güvene kavuşturdu."}],[{"n":1,"t":"Dini yalanlayanı gördün mü?"},{"n":2,"t":"İşte o, yetimi itip kakar."},{"n":3,"t":"Yoksulu doyurmaya teşvik etmez."},{"n":"4-5","t":"Namazlarından gaflette olarak namaz kılanların vay haline!"},{"n":6,"t":"Onlar gösteriş yapanlardır."},{"n":7,"t":"Hayra da mâni olurlar."}],[{"n":1,"t":"Biz sana çok hayır/Kevser`i verdik."},{"n":2,"t":"Öyleyse Rabbin için namaz kıl ve kurban kes!"},{"n":3,"t":"Asıl “nesli kesik” olan, sana buğzedendir."}],[{"n":"1-5","t":"Ey kâfirler! Sizin taptıklarınıza ben tapmam. Siz de benim taptığıma tapıcılar değilsiniz. Ben asla sizin taptıklarınıza tapacak değilim. Siz de benim taptığıma tapacak değilsiniz."},{"n":6,"t":"Sizin dininiz size, benim dinim banadır."}],[{"n":1,"t":"Allah`ın yardımı ve zaferi geldiğinde."},{"n":2,"t":"İnsanların dalga dalga Allah`ın dinine girdiklerini gördüğün zaman."},{"n":3,"t":"Rabbini överek O`nu tesbih et ve O`ndan af dile! Çünkü O, tövbeleri çok kabul edendir."}],[{"n":1,"t":"Ebû Leheb`in sosyal gücü de kahrolsun, kendisi de kahrolsun!"},{"n":2,"t":"Malı ve kazandıkları ona fayda vermedi."},{"n":"3-5","t":"O, alevli ateşe girecektir. Boynunda hurma lifinden bir iple odun taşıyıcısı olarak karısı da."}],[{"n":"1-2","t":"Allah tektir. Varlığını sürdürmek için hiçbir şeye muhtaç değildir, herkes O`na muhtaçtır."},{"n":"3-4","t":"O, doğurmamış ve doğurulmamıştır. Hiçbir şey O`na denk değildir."}],[{"n":1,"t":"Ben, ağaran sabahın Rabbine sığınırım."},{"n":"2-5","t":"Yarattığı her şeyin şerrinden, kapladığında karanlığın şerrinden, düğümlere üfürenlerin şerrinden, haset edenin haset ettiği zamanki şerrinden."}],[{"n":"1-3","t":"Ben insanların Rabbine sığınırım. İnsanların yöneticisine. İnsanların ilâhına."},{"n":"4-6","t":"“İnsanlara kötü şeyler fısıldayan o sinsi vesvesecinin şerrinden ki o, insanların sinesine vesvese düşürür. Cinlerden ve insanlardan oluşur.”"}]];
